"""Root-owned text evidence assembly; no JVM/test/analyzer launch."""
from pathlib import Path
from collections import Counter
import hashlib
import json

BASE = Path(__file__).resolve().parent
REPO = Path('/drive-testcomp/opentaint-go-rules/opentaint-w3')
REPORT = REPO / 'docs/reports/bidirectional-star-initial-nested-calls-20261107.md'
OUT = REPO / 'docs/reports/data/bidirectional-star-initial-nested-calls-20261107.json'

def sha(b): return hashlib.sha256(b).hexdigest()
def read(rel): return json.loads((BASE / rel).read_text())
def relative(path, parent):
    try: return str(path.relative_to(parent))
    except ValueError: return None

def fingerprint(path):
    p=Path(path)
    if p.is_file():
        b=p.read_bytes();return dict(kind='FILE',path=str(p.resolve()),bytes=len(b),sha256=sha(b))
    if p.is_dir():
        files=sorted(x for x in p.rglob('*') if x.is_file());h=hashlib.sha256()
        for x in files: h.update((str(x.relative_to(p))+'\0'+sha(x.read_bytes())+'\n').encode())
        return dict(kind='DIRECTORY',path=str(p.resolve()),files=len(files),sha256=h.hexdigest())
    return dict(kind='MISSING',path=str(p.resolve()))

variants={}
rows={}
runtime_checks=0
for v in ['current','all-may']:
    prefix=f'output/{v}'
    evidence=read(f'{prefix}/root-evidence.json')
    assert evidence['frozenInputsUnchanged'] is True
    suite=evidence['suite']
    assert suite['tests']==4 and suite['skipped']==0
    assert suite['failed']==(0 if v=='current' else 3)
    assert len(evidence['actualCaseResults'])==4
    cases={r['case']:r for r in evidence['actualCaseResults']}
    assert set(cases)=={'direct','wrapG1','wrapG2','wrapFG'}
    for name,r in cases.items():
        assert r['status']=='COMPLETE' and r['reason']=='NO_DEMAND_EDGE'
        assert r['latestReachedRun']==r['terminalRun']==3
        assert r['processedTraceComplete'] is True
        assert r['normalReports']==(1 if v=='current' or name=='direct' else 0)
    for fp in read(f'{prefix}/runtime-freeze.json')['classpath']+read(f'{prefix}/runtime-freeze.json')['nativeSourceTrees']:
        assert fingerprint(fp['path'])==fp,fp['path'];runtime_checks+=1
    rows[v]=[json.loads(line) for line in (BASE/f'{prefix}/processed.jsonl').read_text().splitlines()]
    assert len(rows[v])==evidence['processedEvents']==sum(x['processedRows'] for x in cases.values())
    variants[v]=dict(suite=suite,cases=cases,actualRootTaskExit=0 if v=='current' else 1)

same_run1={}
for name in variants['current']['cases']:
    def normalized(v):
        values=[]
        for r in rows[v]:
            if r['case']!=name or r['run']!=1:continue
            r=dict(r);r.pop('variant');values.append(json.dumps(r,sort_keys=True))
        return Counter(values)
    same_run1[name]=normalized('current')==normalized('all-may')
    assert same_run1[name]

pins=read('source-pins.json');paths=set()
for pin in pins['files']:
    p=Path(pin['path']);assert sha(p.read_bytes())==pin['sha256'],str(p);paths.add(p)
concrete={}
for v in ['current','all-may']:
    prefix=f'concrete/output/{v}'
    ev=read(f'{prefix}/root-evidence.json')
    assert ev['frozenInputsUnchanged'] is True
    assert ev['suite']['tests']==2 and ev['suite']['skipped']==0
    assert ev['suite']['failed']==(0 if v=='current' else 1)
    cases={x['case']:x for x in ev['actualCaseResults']}
    assert set(cases)=={'direct','wrapped'}
    for name,r in cases.items():
        assert r['status']=='COMPLETE' and r['reason']=='NO_DEMAND_EDGE'
        assert r['latestReachedRun']==r['terminalRun']==3 and r['processedTraceComplete'] is True
        assert r['normalReports']==(1 if v=='current' or name=='direct' else 0)
    for fp in read(f'{prefix}/runtime-freeze.json')['classpath']+read(f'{prefix}/runtime-freeze.json')['nativeSourceTrees']:
        assert fingerprint(fp['path'])==fp,fp['path'];runtime_checks+=1
    concrete[v]=dict(suite=ev['suite'],cases=cases,actualRootTaskExit=0 if v=='current' else 1)
cpins=read('concrete/source-pins.json')
for pin in cpins['files']:
    p=Path(pin['path']);assert sha(p.read_bytes())==pin['sha256'],str(p);paths.add(p)
review=dict(state='PASS_NEGATIVE_COVERAGE_EXPERIMENT',owner='root',
            productionSourceChanged=False,sourcePinChecks=len(pins['files'])+len(cpins['files']),runtimeChecks=runtime_checks,
            suiteResults=variants,run1ProcessEventMultisetsEqual=same_run1,
            concreteSuiteResults=concrete,
            observation='Complete dequeued process-event traces, before handling each instruction; not storage dumps',
            derivedNotCaptured=['callee-bound ret STAR/NORMAL','paired Dc/Dp after run-1 handoff','raw rejecting C2 callback'],
            noGlobalSafetyClaim=True,noProjectCauseClaim=True,rootJobsTerminal=True)
(BASE/'root-comparison.json').write_text(json.dumps(review,indent=2)+'\n')
for p in BASE.rglob('*'):
    if not p.is_file():continue
    rel=p.relative_to(BASE)
    if any(x in {'compiled','registry','binary-results','html','resources','__pycache__'} for x in rel.parts):continue
    if p.suffix in {'.md','.json','.jsonl','.kt','.lean','.py','.gradle','.log','.xml','.txt','.diff'}:paths.add(p)
artifacts={}
for p in sorted(paths):
    b=p.read_bytes();r=relative(p,BASE);s=relative(p,REPO)
    key='nested/'+r if r is not None else 'repo-source/'+s if s is not None else 'pinned-source/'+str(p).lstrip('/')
    assert key not in artifacts
    artifacts[key]=dict(path=str(p),bytes=len(b),sha256=sha(b),text=b.decode('utf-8'))
payload=dict(schema='star-initial-nested-call-negative-evidence-v1',date='2026-11-07',
             runtimeSourceCommit='7069fe2d73a32443d98163fc67970a3114983712',sourceHeadAtCapture='0a2846c44',
             report=dict(path=str(REPORT.relative_to(REPO)),sha256=sha(REPORT.read_bytes())),
             rootComparison=review,artifactCount=len(artifacts),artifacts=artifacts)
OUT.write_text(json.dumps(payload,ensure_ascii=False,indent=2)+'\n')
result=json.loads(OUT.read_text())
for a in result['artifacts'].values():
    b=a['text'].encode();assert len(b)==a['bytes'] and sha(b)==a['sha256']
assert result['report']['sha256']==sha(REPORT.read_bytes())
print(json.dumps(dict(state='PASS',artifacts=len(artifacts),bytes=OUT.stat().st_size,
                      sha256=sha(OUT.read_bytes()),runtimeChecks=runtime_checks)))

