// PREPARATION ONLY. Root executes one frozen native suite at a time.
def prep = new File('/drive-testcomp/opentaint-go-rules/canonical-relations-directional-inside-20261105/analysis-tools/star-initial-nested-call-audit-20261107/concrete')
def nativeProject = new File('/drive-testcomp/opentaint-go-rules/opentaint-w3/core/opentaint-dataflow-core/opentaint-dataflow')
def sha = { File f -> java.security.MessageDigest.getInstance('SHA-256').digest(f.bytes).encodeHex().toString() }
def parse = { File f -> new groovy.json.JsonSlurper().parse(f) }
def parseText = { String value -> new groovy.json.JsonSlurper().parseText(value) }
def writeJson = { File f, value -> f.parentFile.mkdirs(); f.text = groovy.json.JsonOutput.prettyPrint(groovy.json.JsonOutput.toJson(value)) + '\n' }
def fingerprint = { File f ->
    if (!f.exists()) return [kind:'MISSING', path:f.canonicalPath]
    if (f.isFile()) return [kind:'FILE', path:f.canonicalPath, bytes:f.length(), sha256:sha(f)]
    def children = []
    f.eachFileRecurse(groovy.io.FileType.FILES) { children.add(it) }
    children.sort { a,b -> f.toPath().relativize(a.toPath()).toString() <=> f.toPath().relativize(b.toPath()).toString() }
    def digest = java.security.MessageDigest.getInstance('SHA-256')
    children.each { child -> digest.update((f.toPath().relativize(child.toPath()).toString() + '\u0000' + sha(child) + '\n').getBytes('UTF-8')) }
    [kind:'DIRECTORY', path:f.canonicalPath, files:children.size(), sha256:digest.digest().encodeHex().toString()]
}
def verify = { p ->
    if (p.findProperty('concreteStarRootConfirmed') != 'true')
        throw new GradleException('Root must review local proof/candidates and confirm prior jobs terminal')
    def pins = parse(new File(prep,'source-pins.json'))
    pins.files.each { pin -> if (sha(new File(pin.path)) != pin.sha256) throw new GradleException('Pinned source changed: ' + pin.path) }
    def proof = parse(new File(pins.localProofReceipt.path))
    if (proof.state != 'PASS_LOCAL_INVESTIGATION_ONLY_POLICY_UNSELECTED' || proof.theorems != 26)
        throw new GradleException('Checked conditional nested-admission model is required; this is no global policy proof')
    pins.candidateCopies.each { item ->
        if (sha(new File(item.copy)) != sha(new File(item.original))) throw new GradleException('Candidate copy changed')
    }
}
def inspectOverlay = { File classes, boolean candidate ->
    def allowed = ['org/opentaint/dataflow/bidi/ConcreteStarInitialCandidateTest']
    if (candidate) allowed += 'org/opentaint/dataflow/bidi/ap/RestrictedInitialPolicy'
    def inventory = []
    classes.eachFileRecurse(groovy.io.FileType.FILES) { f ->
        def path = classes.toPath().relativize(f.toPath()).toString().replace(File.separatorChar,'/' as char)
        if (!(path.startsWith('META-INF/') && path.endsWith('.kotlin_module')) &&
            !allowed.any { path == it + '.class' || path.startsWith(it + '$') && path.endsWith('.class') })
            throw new GradleException('Unapproved class or resource: ' + path)
        inventory += [relativePath:path, bytes:f.length(), sha256:sha(f)]
    }
    if (!inventory.any { it.relativePath == allowed[0] + '.class' }) throw new GradleException('Test class missing')
    if (candidate && !inventory.any { it.relativePath == allowed[1] + '.class' }) throw new GradleException('Policy missing')
    inventory.sort { it.relativePath }
}
allprojects { p ->
    if (p.projectDir.canonicalFile == nativeProject.canonicalFile) p.afterEvaluate {
        if (p.gradle.startParameter.taskNames.any { it.toLowerCase().contains('concretestar') }) verify(p)
        [['current','ConcreteStarCurrent'],['all-may','ConcreteStarAll']].each { selected ->
            def variant = selected[0]
            def suffix = selected[1]
            def sourceName = suffix.substring(0,1).toLowerCase() + suffix.substring(1)
            def ss = p.sourceSets.create(sourceName)
            ss.java.setSrcDirs([]); ss.resources.setSrcDirs([])
            p.kotlin.sourceSets.getByName(sourceName).kotlin.setSrcDirs([new File(prep,'common'),new File(prep,'variants/' + variant)])
            ss.compileClasspath = p.sourceSets.main.output + p.sourceSets.test.output + p.configurations.testCompileClasspath
            def output = new File(prep,'output/' + variant)
            def classes = new File(output,'compiled')
            ss.output.classesDirs.setFrom(classes)
            ss.output.resourcesDir = new File(output,'resources')
            def compile = p.tasks.named('compile' + suffix + 'Kotlin') {
                dependsOn p.tasks.named('testClasses')
                destinationDirectory.set(classes)
                incremental = false
                compilerOptions.jvmTarget.set(p.tasks.named('compileKotlin').get().compilerOptions.jvmTarget)
                compilerOptions.freeCompilerArgs.add('-Xfriend-paths=' + [
                    p.layout.buildDirectory.dir('classes/kotlin/main').get().asFile,
                    p.layout.buildDirectory.dir('classes/kotlin/test').get().asFile
                ].collect { it.absolutePath }.join(','))
                doFirst { verify(p) }
            }
            def runtime = p.files(classes) + p.sourceSets.test.runtimeClasspath
            def trees = { ['src/main','src/test'].collect { fingerprint(new File(p.projectDir,it)) } }
            def freeze = new File(output,'runtime-freeze.json')
            p.tasks.register('freeze' + suffix + 'Runtime') {
                dependsOn compile
                dependsOn runtime.buildDependencies
                doLast {
                    verify(p)
                    if (freeze.exists()) throw new GradleException('Frozen runtime exists; do not overwrite')
                    def cp = runtime.files.collect { it.canonicalFile }
                    if (cp.drop(1).any { it.canonicalPath.contains('/canonical-relations-directional-inside-20261105/') })
                        throw new GradleException('Foreign external overlay/provider')
                    writeJson(freeze,[owner:'root',state:'READY_FROZEN_CONCRETE_DIAGNOSTIC',variant:variant,
                        sourcePinsSha256:sha(new File(prep,'source-pins.json')),classpath:cp.collect { fingerprint(it) },
                        nativeSourceTrees:trees(),overlayClasses:inspectOverlay(classes,variant != 'current')])
                    println('CONCRETE_STAR_FROZEN variant=' + variant)
                }
            }
            def stream = new File(output,'test-output.log')
            def suite = new File(output,'suite-result.json')
            def lock = new Object()
            def run = p.tasks.register('test' + suffix,org.gradle.api.tasks.testing.Test) {
                dependsOn compile
                testClassesDirs = p.files(classes)
                classpath = runtime
                useJUnitPlatform()
                filter { includeTestsMatching 'org.opentaint.dataflow.bidi.ConcreteStarInitialCandidateTest' }
                maxParallelForks = 1; maxHeapSize = '1g'; jvmArgs '-XX:ActiveProcessorCount=1'
                timeout.set(java.time.Duration.ofSeconds(60))
                systemProperty 'concrete.star.variant',variant
                systemProperty 'concrete.star.external',classes.absolutePath
                systemProperty 'concrete.star.main',p.layout.buildDirectory.dir('classes/kotlin/main').get().asFile.absolutePath
                systemProperty 'concrete.star.test',p.layout.buildDirectory.dir('classes/kotlin/test').get().asFile.absolutePath
                reports.junitXml.required.set(true)
                reports.junitXml.outputPerTestCase = true
                reports.junitXml.outputLocation.set(new File(output,'xml'))
                reports.html.outputLocation.set(new File(output,'html'))
                binaryResultsDirectory.set(new File(output,'binary-results'))
                outputs.upToDateWhen { false }
                testLogging { events 'passed','failed','skipped'; showStandardStreams = true }
                doFirst {
                    verify(p)
                    if (!freeze.isFile()) throw new GradleException('Separate freeze required')
                    def frozen = parse(freeze)
                    if (frozen.owner != 'root' || frozen.state != 'READY_FROZEN_CONCRETE_DIAGNOSTIC' ||
                        frozen.sourcePinsSha256 != sha(new File(prep,'source-pins.json')) || frozen.variant != variant ||
                        frozen.classpath != runtime.files.collect { fingerprint(it.canonicalFile) } ||
                        frozen.nativeSourceTrees != trees() || frozen.overlayClasses != inspectOverlay(classes,variant != 'current'))
                        throw new GradleException('Frozen runtime/source bytes changed')
                    def started = new File(output,'root-execution-started.json')
                    if (!started.createNewFile()) throw new GradleException('One-shot suite already started; preserve evidence')
                    writeJson(started,[owner:'root',state:'STARTED',variant:variant,runtimeFreezeSha256:sha(freeze)])
                    stream.text = ''
                }
                onOutput { descriptor,event -> synchronized(lock) { stream.append(event.message,'UTF-8') } }
                afterSuite { descriptor,result -> if (descriptor.parent == null) writeJson(suite,
                    [tests:result.testCount,successful:result.successfulTestCount,failed:result.failedTestCount,
                     skipped:result.skippedTestCount,resultType:result.resultType.toString()]) }
            }
            def record = p.tasks.register('record' + suffix + 'Evidence') {
                mustRunAfter run
                doLast {
                    verify(p)
                    if (!suite.isFile()) { println('CONCRETE_STAR_INCOMPLETE variant=' + variant); return }
                    def result = parse(suite)
                    def rows = []; def processed = []
                    stream.eachLine('UTF-8') { line ->
                        if (line.startsWith('CONCRETE_STAR_RESULT ')) rows += parseText(line.substring('CONCRETE_STAR_RESULT '.length()))
                        if (line.startsWith('CONCRETE_STAR_PROCESSED ')) processed += line.substring('CONCRETE_STAR_PROCESSED '.length())
                    }
                    def frozen = parse(freeze)
                    def unchanged = frozen.classpath == runtime.files.collect { fingerprint(it.canonicalFile) } &&
                        frozen.nativeSourceTrees == trees() && frozen.overlayClasses == inspectOverlay(classes,variant != 'current')
                    new File(output,'processed.jsonl').text = processed.join('\n') + (processed.isEmpty() ? '' : '\n')
                    writeJson(new File(output,'root-evidence.json'),[owner:'root',variant:variant,
                        state:unchanged && result.tests == 2 && result.failed == 0 && result.skipped == 0 && rows.size() == 2
                            ? 'TWO_CONCRETE_CASES_PASS_DIAGNOSTIC' : 'FAILED_OR_INCOMPLETE_REVIEW_REQUIRED',
                        suite:result,actualCaseResults:rows,processedEvents:processed.size(),frozenInputsUnchanged:unchanged,
                        policySelected:false,fullAnalyzerSafetyProved:false,
                        artifacts:[stream,suite,new File(output,'processed.jsonl')].collect { fingerprint(it) }])
                }
            }
            run.configure { finalizedBy record }
        }
    }
}

