// PREPARATION ONLY. Root executes one frozen native suite at a time.
def prep = new File('/drive-testcomp/opentaint-go-rules/canonical-relations-directional-inside-20261105/analysis-tools/star-initial-nested-call-audit-20261107')
def nativeProject = new File('/drive-testcomp/opentaint-go-rules/opentaint-w3/core/opentaint-dataflow-core/opentaint-dataflow')
def sha = { File f -> java.security.MessageDigest.getInstance('SHA-256').digest(f.bytes).encodeHex().toString() }
def parse = { File f -> new groovy.json.JsonSlurper().parse(f) }
def parseText = { String value -> new groovy.json.JsonSlurper().parseText(value) }
def writeJson = { File f, value -> f.parentFile.mkdirs(); f.text = groovy.json.JsonOutput.prettyPrint(groovy.json.JsonOutput.toJson(value)) + '\n' }
def fingerprint = { File f ->
    if (!f.exists()) return [kind:'MISSING', path:f.canonicalPath]
    if (f.isFile()) return [kind:'FILE', path:f.canonicalPath, bytes:f.length(), sha256:sha(f)]
    def children = []
    f.eachFileRecurse(groovy.io.FileType.FILES) { children.add(it) }
    children.sort { a,b -> f.toPath().relativize(a.toPath()).toString() <=> f.toPath().relativize(b.toPath()).toString() }
    def digest = java.security.MessageDigest.getInstance('SHA-256')
    children.each { child -> digest.update((f.toPath().relativize(child.toPath()).toString() + '\u0000' + sha(child) + '\n').getBytes('UTF-8')) }
    [kind:'DIRECTORY', path:f.canonicalPath, files:children.size(), sha256:digest.digest().encodeHex().toString()]
}
def verify = { p ->
    if (p.findProperty('nestedStarRootConfirmed') != 'true')
        throw new GradleException('Root must review local proof/candidates and confirm prior jobs terminal')
    def pins = parse(new File(prep,'source-pins.json'))
    pins.files.each { pin -> if (sha(new File(pin.path)) != pin.sha256) throw new GradleException('Pinned source changed: ' + pin.path) }
    def proof = parse(new File(pins.localProofReceipt.path))
    if (proof.state != 'PASS_LOCAL_INVESTIGATION_ONLY_POLICY_UNSELECTED' || proof.theorems != 26)
        throw new GradleException('Checked conditional nested-admission model is required; this is no global policy proof')
    pins.candidateCopies.each { item ->
        if (sha(new File(item.copy)) != sha(new File(item.original))) throw new GradleException('Candidate copy changed')
    }
}
def inspectOverlay = { File classes, boolean candidate ->
    def allowed = ['org/opentaint/dataflow/bidi/NestedStarInitialCandidateTest']
    if (candidate) allowed += 'org/opentaint/dataflow/bidi/ap/RestrictedInitialPolicy'
    def inventory = []
    classes.eachFileRecurse(groovy.io.FileType.FILES) { f ->
        def path = classes.toPath().relativize(f.toPath()).toString().replace(File.separatorChar,'/' as char)
        if (!(path.startsWith('META-INF/') && path.endsWith('.kotlin_module')) &&
            !allowed.any { path == it + '.class' || path.startsWith(it + '$') && path.endsWith('.class') })
            throw new GradleException('Unapproved class or resource: ' + path)
        inventory += [relativePath:path, bytes:f.length(), sha256:sha(f)]
    }
    if (!inventory.any { it.relativePath == allowed[0] + '.class' }) throw new GradleException('Test class missing')
    if (candidate && !inventory.any { it.relativePath == allowed[1] + '.class' }) throw new GradleException('Policy missing')
    inventory.sort { it.relativePath }
}
allprojects { p ->
