                        sourcePinsSha256:sha(new File(prep,'source-pins.json')),classpath:cp.collect { fingerprint(it) },
                        nativeSourceTrees:trees(),overlayClasses:inspectOverlay(classes,variant != 'current')])
                    println('NESTED_STAR_FROZEN variant=' + variant)
                }
            }
            def stream = new File(output,'test-output.log')
            def suite = new File(output,'suite-result.json')
            def lock = new Object()
            def run = p.tasks.register('test' + suffix,org.gradle.api.tasks.testing.Test) {
                dependsOn compile
                testClassesDirs = p.files(classes)
                classpath = runtime
                useJUnitPlatform()
                filter { includeTestsMatching 'org.opentaint.dataflow.bidi.NestedStarInitialCandidateTest' }
                maxParallelForks = 1; maxHeapSize = '1g'; jvmArgs '-XX:ActiveProcessorCount=1'
                timeout.set(java.time.Duration.ofSeconds(100))
                systemProperty 'nested.star.variant',variant
                systemProperty 'nested.star.external',classes.absolutePath
                systemProperty 'nested.star.main',p.layout.buildDirectory.dir('classes/kotlin/main').get().asFile.absolutePath
                systemProperty 'nested.star.test',p.layout.buildDirectory.dir('classes/kotlin/test').get().asFile.absolutePath
                reports.junitXml.required.set(true)
                reports.junitXml.outputPerTestCase = true
                reports.junitXml.outputLocation.set(new File(output,'xml'))
                reports.html.outputLocation.set(new File(output,'html'))
                binaryResultsDirectory.set(new File(output,'binary-results'))
                outputs.upToDateWhen { false }
                testLogging { events 'passed','failed','skipped'; showStandardStreams = true }
                doFirst {
                    verify(p)
                    if (!freeze.isFile()) throw new GradleException('Separate freeze required')
                    def frozen = parse(freeze)
                    if (frozen.owner != 'root' || frozen.state != 'READY_FROZEN_UNSELECTED_NESTED_DIAGNOSTIC' ||
                        frozen.sourcePinsSha256 != sha(new File(prep,'source-pins.json')) || frozen.variant != variant ||
                        frozen.classpath != runtime.files.collect { fingerprint(it.canonicalFile) } ||
                        frozen.nativeSourceTrees != trees() || frozen.overlayClasses != inspectOverlay(classes,variant != 'current'))
