            }
            def record = p.tasks.register('record' + suffix + 'Evidence') {
                mustRunAfter run
                doLast {
                    verify(p)
                    if (!suite.isFile()) { println('NESTED_STAR_INCOMPLETE variant=' + variant); return }
                    def result = parse(suite)
                    def rows = []; def processed = []
                    stream.eachLine('UTF-8') { line ->
                        if (line.startsWith('NESTED_STAR_RESULT ')) rows += parseText(line.substring('NESTED_STAR_RESULT '.length()))
                        if (line.startsWith('NESTED_STAR_PROCESSED ')) processed += line.substring('NESTED_STAR_PROCESSED '.length())
                    }
