import org.opentaint.dataflow.ap.ifds.access.util.AccessorInterner.Companion.setAccessorKind
import java.util.concurrent.ConcurrentHashMap

/** Publish each value before its ID. Reads need one volatile array read and no retry loop. */
class AccessorTable {
    internal class Storage<T : Any> {
        private val ids = ConcurrentHashMap<T, Int>()
        @Volatile private var values: Array<Any?> = arrayOfNulls(64)
        private var size = 0

        fun index(value: T): Int = ids[value] ?: synchronized(this) {
            ids[value] ?: run {
                val index = size++
                val array = if (index < values.size) values else values.copyOf(Math.multiplyExact(2, values.size))
                array[index] = value
                values = array
                ids[value] = index
                index
            }
        }

        @Suppress("UNCHECKED_CAST")
        fun value(index: Int): T = checkNotNull(values.getOrNull(index)) { "Unknown value ID: $index" } as T
    }

    private val fields = Storage<Accessor>()
    private val statics = Storage<Accessor>()

    fun index(accessor: Accessor): AccessorIdx = when (accessor) {
        is FieldAccessor -> setAccessorKind(fields.index(accessor), FIELD_KIND, BASIC_KIND_BITS)
        is ClassStaticAccessor -> setAccessorKind(statics.index(accessor), STATIC_KIND, BASIC_KIND_BITS)
        ElementAccessor -> ELEMENT_ACCESSOR_IDX
        else -> error("W5: $accessor is not a path accessor")
    }

    fun accessor(index: AccessorIdx): Accessor = when {
        index.isFieldAccessor() -> fields.value(index.getAccessorIdx(BASIC_KIND_BITS))
        index.isStaticAccessor() -> statics.value(index.getAccessorIdx(BASIC_KIND_BITS))
        index == ELEMENT_ACCESSOR_IDX -> ElementAccessor
        else -> error("W5: $index is not a path accessor")
    }
}

fun AccessorIdx.isCounted(): Boolean = isFieldAccessor() || this == ELEMENT_ACCESSOR_IDX
fun AccessorIdx.isClass(): Boolean = isStaticAccessor()
internal fun AccessorIdx.isPathAccessor(): Boolean = this >= 0 && (isCounted() || isClass())

package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.AccessPathBase

/** An entry command. Layer is not part of the interned premise identity. */
data class AdmittedInitial(val initial: InitialAp, val layer: Layer)

/** Query-local output; inspecting coverage does not intern hypothetical initials. */
data class InitialEmission(val pattern: Pattern, val layer: Layer)

private fun intrinsicInitialLayer(tail: Tail, mark: MarkSlot, zero: Boolean): Layer = when {
    zero -> Layer.NORMAL
    tail == Tail.ANY -> Layer.DEMAND
    tail == Tail.STAR && mark is MarkSlot.Concrete -> Layer.DEMAND
    else -> Layer.NORMAL
}

fun intrinsicInitialLayer(initial: InitialAp): Layer =
    intrinsicInitialLayer(initial.tail, initial.mark, initial.isZero)

fun intrinsicInitialLayer(pattern: Pattern): Layer =
    intrinsicInitialLayer(pattern.fact.tail, pattern.fact.mark, pattern.fact.base == AccessPathBase.Zero)

/** Concrete data inherits its actual support. FLOW and ZERO keep their old entry policy. */
fun admissionLayer(emitted: Pattern, actual: Pattern, supplied: Layer): Layer {
    val intrinsic = intrinsicInitialLayer(emitted)
    if (emitted.fact.base == AccessPathBase.Zero || emitted.fact.mark is MarkSlot.Star) return intrinsic
    val loss = emitted.fact.tail == Tail.EXACT && actual.fact.tail == Tail.ANY
    return intrinsic or (supplied == Layer.DEMAND || loss)
}

/** Canonicalize before seen-bit admission, including intrinsic STAR and run-1 policies. */
fun canonicalAdmission(initial: InitialAp, supplied: Layer, mode: ApMode? = null): AdmittedInitial {
    val ordinary = intrinsicInitialLayer(initial) or (supplied == Layer.DEMAND)
    val run1Demand = mode?.run1 == true && (initial.base == STATIC ||
        !initial.isZero && initial.mark is MarkSlot.Concrete && mode.markMode == MarkMode.GROUP)
    return AdmittedInitial(initial, ordinary or run1Demand)
}

fun existingZeroAdmission(initial: InitialAp): AdmittedInitial {
    require(initial.isZero) { "ZERO admission requires the existing canonical ZERO key" }
    return AdmittedInitial(initial, Layer.NORMAL)
}

package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.ap.ifds.access.util.AccessorIdx
import org.opentaint.dataflow.util.Cancellation
import org.opentaint.dataflow.util.RefManager
import org.opentaint.dataflow.util.SoftReferenceManager
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicInteger

/** Shared canonical keys. Each store will own its trie-node cache. */
class ApManager(val cancellation: Cancellation, refManager: RefManager = RefManager(), val marks: MarkTable) {
    val softRefs: SoftReferenceManager = refManager.softRefManager("bidi")
    val accessors = AccessorTable()
    val flowAlg: FlowAlgebra get() = FlowAlgebra
    val taintAlg = TaintAlgebra(this)

    private val markSets = ConcurrentHashMap<MarkSet, MarkSet>()
    private val markExclusions = ConcurrentHashMap<MarkExclusions, MarkExclusions>()
    private val exclusions = ConcurrentHashMap<ExclusionSet, ExclusionSet>()
    private val paths = ConcurrentHashMap<PathKey, PathNode>()
    private val initials = ConcurrentHashMap<InitialKey, InitialAp>()
    private val premiseSets = ConcurrentHashMap<List<InitialAp>, PremiseSet>()
    private val nextId = AtomicInteger()

    /** The suffix is canonical in this manager. Its identity avoids structural-hash clusters. */
    private class PathKey(val accessor: AccessorIdx, val next: PathNode?) {
        private val hash = accessor * 31 + System.identityHashCode(next)
        override fun hashCode(): Int = hash
        override fun equals(other: Any?): Boolean = other is PathKey && accessor == other.accessor && next === other.next
    }

    private data class InitialKey(
        val base: AccessPathBase,
        val path: PathNode?,
        val tail: Tail,
        val exclusion: ExclusionSet,
        val mark: MarkSlot,
    )

    fun intern(set: MarkSet): MarkSet = if (set.isEmpty) MarkSet.EMPTY else markSets.putIfAbsent(set, set) ?: set
    fun intern(mx: MarkExclusions): MarkExclusions {
        val owned = mx.withCatalog(marks)
        return if (owned.isEmpty) MarkExclusions.EMPTY else markExclusions.putIfAbsent(owned, owned) ?: owned
    }
    fun intern(exclusion: ExclusionSet): ExclusionSet =
        if (exclusion == ExclusionSet.Empty) exclusion else exclusions.putIfAbsent(exclusion, exclusion) ?: exclusion
    fun markSetOf(mark: TaintMark): MarkSet = intern(MarkSet(intArrayOf(mark.id)))
    fun runtimeMarks(set: MarkSet, mode: ApMode): MarkSet {
        if (mode.markMode == MarkMode.FULL) return set
        var mapped: IntArray? = null
        for (i in set.data.indices) {
            val old = set.data[i]
            val id = marks.runtimeAtom(TaintMark(old), mode.markMode).id
            if (mapped == null && id != old) mapped = set.data.copyOf()
            mapped?.let { it[i] = id }
        }
        // Public input sets need not yet belong to this manager's interner.
        return intern(mapped?.let(::MarkSet) ?: set)
    }

    private fun projectedLeaf(old: TaintLeaves, mode: ApMode): TaintLeaves {
        val exact = runtimeMarks(old.exact, mode)
        val any = runtimeMarks(old.any, mode)
        // Equal mark IDs do not establish ownership of the leaf payload.
        return if (exact === old.exact && any === old.any) taintAlg.intern(old) else taintLeaves(exact, any)
    }

    fun runtimeFact(f: Facts, mode: ApMode): Facts = if (mode.markMode == MarkMode.FULL) f else when (f) {
        is Reach -> f
        is FlowTree -> {
            val layer = if (mode.markMode == MarkMode.GROUP && f.base == STATIC) Layer.DEMAND else f.layer
            val mx = intern(f.markExclusion.projected(marks, mode.markMode))
            val exclusion = if (f.tail == Tail.ANY) ExclusionSet.Empty else intern(f.exclusion)
            if (layer == f.layer && mx === f.markExclusion && exclusion === f.exclusion) f
            else flowTree(f.base, layer, exclusion, mx, f.root, f.tail)
        }
        is TaintTree -> {
            val root = checkNotNull(taintAlg.mapCanonicalLeaves(f.root, cancellation) { projectedLeaf(it, mode) })
            val protected = f.nonSubsumable?.let { mask ->
                taintAlg.mapCanonicalLeaves(mask, cancellation) { projectedLeaf(it, mode) }
            }
            val layer = if (mode.markMode == MarkMode.GROUP) Layer.DEMAND else f.layer
            val tail = if (root.hasAny) f.anyTail else Tail.ANY_TAINT
            val exclusion = if (tail == Tail.ANY || !root.hasAny) ExclusionSet.Empty else intern(f.exclusion)
            if (root === f.root && protected === f.nonSubsumable && layer == f.layer && tail == f.anyTail && exclusion === f.exclusion) f
            else taintTree(f.base, layer, root, exclusion, tail, protected)
        }
    }

    fun path(accessor: AccessorIdx, next: PathNode?): PathNode {
        check(next == null || next.manager === this) { "A path suffix must use this AP manager" }
        return paths.computeIfAbsent(PathKey(accessor, next)) { PathNode(it.accessor, it.next, this) }
    }

    fun path(path: List<AccessorIdx>): PathNode? {
        var node: PathNode? = null
        for (index in path.indices.reversed()) {
            if (index and 255 == 0) cancellation.checkpoint()
            node = path(path[index], node)
        }
        return node
    }

    fun path(path: IntArray): PathNode? {
        var node: PathNode? = null
        for (index in path.indices.reversed()) {
            if (index and 255 == 0) cancellation.checkpoint()
            node = path(path[index], node)
        }
        return node
    }

    fun initial(base: AccessPathBase, path: PathNode?, tail: Tail, exclusion: ExclusionSet, mark: MarkSlot): InitialAp {
        check(base !is AccessPathBase.CleanerTemporary) { "A field-action temporary cannot be a premise" }
        check(path == null || path.manager === this) { "An initial path must use this AP manager" }
        return initials.computeIfAbsent(InitialKey(base, path, tail, intern(exclusion), mark)) { key ->
            InitialAp(key.base, key.path, key.tail, key.exclusion, key.mark, nextId.getAndIncrement(), this)
        }
    }

    fun initial(pattern: Pattern): InitialAp {
        check(pattern.fact.base !is AccessPathBase.CleanerTemporary) { "A field-action temporary cannot be a premise" }
        return initial(pattern.fact.base, path(pattern.fact.path), pattern.fact.tail, pattern.exclusion, pattern.fact.mark)
    }

    fun premiseOf(members: Collection<InitialAp>): PremiseKey {
        check(members.isNotEmpty()) { "A premise set must be nonempty" }
        check(members.all { it.manager === this }) { "All premises must use this AP manager" }
        val sorted = members.filter { !it.isZero }.distinct().sortedBy { it.id }
        return when (sorted.size) {
            0 -> zero
            1 -> sorted[0]
            else -> premiseSets.computeIfAbsent(sorted) { PremiseSet(it.toTypedArray()) }
        }
    }

    fun union(a: PremiseKey, b: PremiseKey): PremiseKey {
        a.forEachMember { check(it.manager === this) { "All premises must use this AP manager" } }
        b.forEachMember { check(it.manager === this) { "All premises must use this AP manager" } }
        return if (a === b) a else premiseOf(a.members + b.members)
    }

    val zero: InitialAp = initial(AccessPathBase.Zero, null, Tail.EXACT, ExclusionSet.Empty, MarkSlot.Concrete(TaintMark.ZERO))

    fun flowTree(base: AccessPathBase, layer: Layer, exclusion: ExclusionSet, mx: MarkExclusions, root: FlowNode,
                 tail: Tail = if (layer == Layer.NORMAL) Tail.STAR else Tail.ANY): FlowTree =
        FlowTree(base, layer, if (tail == Tail.ANY) ExclusionSet.Empty else intern(exclusion), intern(mx), root, tail)

    fun flowTree(base: AccessPathBase, layer: Layer, exclusion: ExclusionSet, mx: MarkSet, root: FlowNode,
                 tail: Tail = if (layer == Layer.NORMAL) Tail.STAR else Tail.ANY): FlowTree =
        flowTree(base, layer, exclusion, MarkExclusions.fromMarks(mx, marks), root, tail)

    fun taintTree(base: AccessPathBase, layer: Layer, root: TaintNode, exclusion: ExclusionSet = ExclusionSet.Empty,
                  anyTail: Tail = if (layer == Layer.NORMAL) Tail.ANY_TAINT else Tail.ANY,
                  nonSubsumable: TaintNode? = null): TaintTree =
        TaintTree(base, layer, root, if (anyTail == Tail.ANY || !root.hasAny) ExclusionSet.Empty else intern(exclusion),
            if (root.hasAny) anyTail else Tail.ANY_TAINT, nonSubsumable?.let { intersectTaintMask(it, root, cancellation) })

    fun taintLeaves(exact: MarkSet, any: MarkSet): TaintLeaves = taintAlg.leaves(exact, any)
    fun newInterners(): StoreInterners = StoreInterners(softRefs, cancellation)

    /** Build one normalized typed leaf, including exact and uniform FLOW query shapes. */
    fun factsOf(f: PathFact, exclusion: ExclusionSet, layer: Layer): Facts {
        if (f.base == AccessPathBase.Zero) {
            check(f.path.isEmpty() && f.tail == Tail.EXACT && exclusion == ExclusionSet.Empty &&
                f.mark == MarkSlot.Concrete(TaintMark.ZERO)) { "The zero base has only the canonical zero fact" }
            return Reach.of(layer)
        }
        val c = normalize(f, exclusion, layer == Layer.DEMAND)
        val resultLayer = if (c.demand) Layer.DEMAND else Layer.NORMAL
        val resultPath = path(c.fact.path)
        return when (val mark = c.fact.mark) {
            is MarkSlot.Star -> {
                flowTree(f.base, resultLayer, c.exclusion, mark.excluded,
                    FlowAlgebra.prepend(this, resultPath, FlowAlgebra.LEAF_NODE), c.fact.tail)
            }
            is MarkSlot.Concrete -> {
                val payload = if (c.fact.tail == Tail.EXACT) taintLeaves(markSetOf(mark.mark), MarkSet.EMPTY)
                    else taintLeaves(MarkSet.EMPTY, markSetOf(mark.mark))
                taintTree(f.base, resultLayer, taintAlg.prepend(this, resultPath, taintAlg.leafNode(payload)), c.exclusion,
                    if (c.fact.tail == Tail.EXACT) Tail.ANY_TAINT else c.fact.tail)
            }
        }
    }

}

package org.opentaint.dataflow.bidi.ap


/** Shared facade. All walk state is local to the call. */
class ApOps(val manager: ApManager) {
    fun run1Cover(f: Facts, emit: (Facts) -> Unit) = run1CoverFacts(manager, f, emit)

    /** Scalar callers must not silently demote exact members of a mixed group. */
    fun run1Cover(f: Facts): Facts {
        var only: Facts? = null
        run1Cover(f) { value -> check(only == null) { "Mixed E-bearing facts require the callback cover" }; only = value }
        return checkNotNull(only)
    }
    fun applyEdge(c: Facts, premise: PremiseKey, e: PathEdge, statementEdge: Boolean,
                  mode: ApMode, out: ApOut, may: Boolean = false,
                  unchangedStaticInitial: InitialAp? = null, ruleAssignment: Boolean = false) {
        check(unchangedStaticInitial == null ||
            (unchangedStaticInitial === premise && unchangedStaticInitial.manager === manager)) {
            "The ordinary static gate needs this edge's original initial"
        }
        val ce = compiled(e)
        val from = (e.from.mark as? MarkSlot.Concrete)?.mark?.let { manager.marks.runtimeAtom(it, mode.markMode) }
        val assigned = (e.to.mark as? MarkSlot.Concrete)?.mark?.let { manager.marks.runtimeAtom(it, mode.markMode) }
        val protect = ruleAssignment && from != null && assigned != null &&
            (from == assigned || premise.members.any {
                (it.mark as? MarkSlot.Concrete)?.mark?.let { atom -> manager.marks.runtimeAtom(atom, mode.markMode) } == assigned && from != assigned
            })
        val sink = if (!protect) out else object : ApOut {
            override fun result(f: Facts) = out.result(manager.selectedProtection(f, manager.markSetOf(assigned!!)))
            override fun markRequest(mark: TaintMark) = out.markRequest(mark)
        }
        applyCompiledEdge(c, ce, may, staticIdentityDepth(c, premise, ce, statementEdge, mode), mode, sink,
            unchangedStaticInitial)
    }

    internal fun compiled(e: PathEdge): CompiledEdge {
        val old = e.compiled
        if (old != null && (old.toPath == null || old.toPath.manager === manager)) return old
        return manager.compile(e).also { e.compiled = it }
    }

    internal fun applyCompiledEdge(c: Facts, ce: CompiledEdge, edgeDemand: Boolean,
                                   staticAt: Int, mode: ApMode, out: ApOut,
                                   unchangedStaticInitial: InitialAp? = null) {
        manager.transportProtection(c, out) { part, sink ->
            applyCompiledEdgeRaw(part, ce, edgeDemand, staticAt, mode, sink, unchangedStaticInitial)
        }
    }

    private fun applyCompiledEdgeRaw(c: Facts, ce: CompiledEdge, edgeDemand: Boolean,
                                    staticAt: Int, mode: ApMode, out: ApOut,
                                    unchangedStaticInitial: InitialAp?) {
        manager.cancellation.checkpoint()
        if (c.base != ce.fromBase) return
        val sink = out.run1Policy(manager, mode)
        val app = EdgeApplication(manager, ce, edgeDemand, mode, sink, unchangedStaticInitial)
        when (c) {
            is Reach -> app.reach(c)
            is FlowTree -> app.flow(c, staticAt)
            is TaintTree -> app.taint(c)
        }
        app.results.flush(sink)
    }

    fun satisfying(a: Facts, j: InitialAp, mode: ApMode, record: Boolean = false): Facts? =
        satisfying(a, j.toPattern(), mode, record)

    fun satisfying(a: Facts, j: Pattern, mode: ApMode, record: Boolean = false): Facts? =
        satisfyingPart(manager, a, j, mode, record)?.let { retainProtection(a, it, manager.cancellation) }

    /** Summary role changes only strict-ancestor STAR selection. Operation predicates stay native. */
    fun matchSummary(a: Facts, j: InitialAp, mode: ApMode, nativeRecordRead: Boolean,
                     role: SummaryMatchRole): Facts? = matchSummary(a, j.toPattern(), mode, nativeRecordRead, role)

    fun matchSummary(a: Facts, j: Pattern, mode: ApMode, nativeRecordRead: Boolean,
                     role: SummaryMatchRole): Facts? =
        satisfyingPart(manager, a, j, mode, nativeRecordRead,
            allowStrictAncestorStar = role == SummaryMatchRole.OPPOSITE_RECORD)
            ?.let { retainProtection(a, it, manager.cancellation) }

    fun applySummary(a: Facts, j: InitialAp, g: Facts, mode: ApMode, out: ApOut,
                     original: PremiseKey? = null) {
        val masks = (g as? TaintTree)?.protectedPart()?.let { protected ->
            ProtectionOutputs(manager).also { applySummaryPart(this, a.withoutProtection(), j, protected, mode, it) }
        }
        val incoming = (j.mark as? MarkSlot.Concrete)?.mark?.let { manager.marks.runtimeAtom(it, mode.markMode) }
        var restored = MarkSet.EMPTY
        if (original != null && incoming != null) {
            for (i in original.members) {
                val origin = (i.mark as? MarkSlot.Concrete)?.mark?.let { manager.marks.runtimeAtom(it, mode.markMode) } ?: continue
                if (origin != incoming) restored += origin
            }
        }
        val restoredMarks = manager.intern(restored)
        val sink = if (masks == null && restoredMarks.isEmpty) out else object : ApOut {
            override fun result(f: Facts) {
                val flagged = masks?.attach(f) ?: f
                out.result(if (restoredMarks.isEmpty) flagged else manager.selectedProtection(flagged, restoredMarks))
            }
            override fun markRequest(mark: TaintMark) = out.markRequest(mark)
        }
        applySummaryPart(this, a, j, g, mode, sink)
    }

    fun applyRecordLeaf(a: Facts, view: RecordLeafView, nonSubsumable: Boolean,
                        mode: ApMode, out: ApOut, original: PremiseKey? = null) {
        val trigger = (view.premise.fact.mark as? MarkSlot.Concrete)?.mark
            ?.let { manager.marks.runtimeAtom(it, mode.markMode) }
        var restored = MarkSet.EMPTY
        if (original != null && trigger != null) for (i in original.members) {
            val origin = (i.mark as? MarkSlot.Concrete)?.mark
                ?.let { manager.marks.runtimeAtom(it, mode.markMode) } ?: continue
            if (origin != trigger) restored += origin
        }
        val sink = if (restored.isEmpty) out else object : ApOut {
            override fun result(f: Facts) = out.result(manager.selectedProtection(f, restored))
            override fun markRequest(mark: TaintMark) = out.markRequest(mark)
        }
        applyRecordLeafPart(this, a, view, nonSubsumable, mode, sink)
    }

    fun applyCombination(parts: List<Pair<Facts, InitialAp>>, g: TaintTree, mode: ApMode, out: ApOut) =
        applyCombinationPart(manager, parts, g, mode, out.run1Policy(manager, mode))

    /** Used only after E6's full matching and TAINT guards. Caller layers remain in the resume context. */
    internal fun applyMatchedCombination(linkLayers: List<Layer>, g: TaintTree, out: ApOut) =
        applyMatchedCombinationPart(manager, linkLayers, g, out)

    fun without(c: Facts, part: Facts): Facts? = withoutPart(manager, c, part)
    fun reverse(e: PathEdge): PathEdge? = revEdge(e)
    fun leaves(f: Facts): Sequence<Pattern> = leafViews(manager, f)
    fun leavesNear(f: Facts, p: IntArray): Sequence<Pattern> = nearLeafViews(manager, f, p)

    fun clean(c: Facts, premise: PremiseKey, cl: Cleaner, mode: ApMode, out: ApOut) {
        val protect = c.base == cl.base
        val sink = if (!protect) out else object : ApOut {
            override fun result(f: Facts) = out.result(manager.selectedProtection(f, cl.mark?.let { manager.markSetOf(manager.marks.runtimeAtom(it, mode.markMode)) }))
            override fun markRequest(mark: TaintMark) = out.markRequest(mark)
        }
        manager.transportProtection(c, sink) { part, target ->
            cleanFacts(manager, part, premise, cl, mode, target.run1Policy(manager, mode))
        }
    }

    /** Selected FULL mask; null Cleaner.mark retains its all-mark meaning on the scalar API. */
    fun cleanSelectedFullMask(c: Facts, premise: PremiseKey, geometry: Cleaner, selected: MarkSet,
                              mode: ApMode, request: (MarkSet) -> Unit, out: ApOut) {
        check(geometry.mark != null) { "A FULL cleanup block must have selected-mark geometry" }
        val sink = if (c.base != geometry.base) out else object : ApOut {
            override fun result(f: Facts) = out.result(manager.selectedProtection(f, selected))
            override fun markRequest(mark: TaintMark) = out.markRequest(mark)
        }
        val protected = (c as? TaintTree)?.protectedPart()
        val masks = protected?.let { part -> ProtectionOutputs(manager).also {
            cleanSelectedFullMask(manager, part, geometry, selected, mode, {}, it.run1Policy(manager, mode))
        } }
        val target = if (masks == null) sink else object : ApOut {
            override fun result(f: Facts) = sink.result(masks.attach(f))
            override fun markRequest(mark: TaintMark) = sink.markRequest(mark)
        }
        cleanSelectedFullMask(manager, c, geometry, selected, mode, request, target.run1Policy(manager, mode))
    }

    fun filter(c: Facts, f: TypeFilter): Facts? = filterFacts(manager, c, f)?.let { retainProtection(c, it, manager.cancellation) }
    fun limit(c: Facts, fieldLimit: Int, out: ApOut) = manager.transportProtection(c, out) { part, sink ->
        limitFacts(manager, part, fieldLimit, sink)
    }
    /** Pass the original initial only when the run-1 static catalog covers this check. */
    fun checkMark(c: Facts, p: Pattern, mode: ApMode,
                  unchangedStaticInitial: InitialAp? = null): MarkCheck =
        when (val result = markCheckFacts(manager, c, p, mode, unchangedStaticInitial)) {
            is MarkCheck.Holds -> MarkCheck.Holds(retainProtection(c, result.facts, manager.cancellation))
            else -> result
        }
    fun withoutMarks(c: Facts, marks: MarkSet): Facts? = withoutMarksPart(manager, c, marks)

    fun targetTree(target: PathFact, layer: Layer, mode: ApMode? = null): Facts {
        check(target.mark is MarkSlot.Concrete && target.tail != Tail.STAR) { "W7: a target must be concrete and exact or any" }
        val value = manager.factsOf(target, ExclusionSet.Empty, layer)
        return if (mode == null) value else manager.runtimeFact(value, mode)
    }

    fun zero(layer: Layer): Reach = Reach.of(layer)
    fun startFact(i: InitialAp): Facts = initialFacts(manager, i)
    fun startFact(i: InitialAp, mode: ApMode): Facts = manager.runtimeFact(initialFacts(manager, i), mode)
    fun runtimeFact(f: Facts, mode: ApMode): Facts = manager.runtimeFact(f, mode)
    fun policy(added: Facts): InitialAp = policyInitial(manager, added)
    fun emit(d: DemandPattern, added: Facts, policy: RestrictedInitialPolicy = RestrictedInitialPolicy(direction = Direction.FORWARD, catalog = manager.marks)): List<InitialAp> = emitInitials(this, d, added, policy)
    fun restrictReference(j: InitialAp, g: Facts, d: DemandPattern): List<Conclusion> = restrictRaw(this, j, g, d)
    fun restrict(j: InitialAp, g: Facts, d: DemandPattern, policy: RestrictedInitialPolicy = RestrictedInitialPolicy(direction = Direction.FORWARD, catalog = manager.marks)): List<Facts> = restrictFacts(this, j, g, d, policy)
    fun demandPart(premise: PremiseKey, g: Facts, direction: Direction): Facts? =
        selectDemand(manager, premise, g, direction)
}

private fun staticIdentityDepth(c: Facts, premise: PremiseKey, ce: CompiledEdge,
                                statementEdge: Boolean, mode: ApMode): Int {
    if (c !is FlowTree || c.layer != Layer.NORMAL || !mode.run1 || !statementEdge) return -1
    if (c.base != STATIC || ce.fromBase != STATIC) return -1
    val i = premise as? InitialAp ?: return -1
    if (i.base != STATIC || i.tail != Tail.STAR || i.mark != MarkSlot.STAR) return -1
    val q = i.pathData
    if (!(q.isEmpty() || (q.size == 1 && q[0].isClass()))) return -1
    if (ce.fromPathData.size <= q.size || !ce.fromPathData.startsWith(q)) return -1
    return q.size
}

package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.AccessPathBase

/** Results of one operation. Mark requests refer to the input edge's premise. */
interface ApOut {
    fun result(f: Facts)
    fun markRequest(mark: TaintMark)
}

internal fun ApOut.run1Policy(m: ApManager, mode: ApMode): ApOut = if (!mode.run1) this else object : ApOut {
    override fun result(f: Facts) = run1CoverFacts(m, m.runtimeFact(f, mode)) { this@run1Policy.result(it) }
    override fun markRequest(mark: TaintMark) = this@run1Policy.markRequest(m.marks.runtimeAtom(mark, mode.markMode))
}

/** One result per kind and canonical key, without store subsumption. */
internal class Results(private val m: ApManager, private val base: AccessPathBase) {
    private val reach = BooleanArray(2)
    private data class FlowKey(val layer: Layer, val exclusion: ExclusionSet, val mx: MarkExclusions, val tail: Tail)
    private data class TaintKey(val layer: Layer, val exclusion: ExclusionSet, val anyTail: Tail)
    private val flow = LinkedHashMap<FlowKey, FlowNode>(2)
    private val taint = LinkedHashMap<TaintKey, TaintNode>(2)

    fun reach(layer: Layer) { reach[layer.ordinal] = true }

    fun flow(layer: Layer, exclusion: ExclusionSet, mx: MarkExclusions, node: FlowNode,
             tail: Tail = if (layer == Layer.NORMAL) Tail.STAR else Tail.ANY) {
        if (node.isEmpty) return
        val key = FlowKey(layer, if (tail == Tail.ANY) ExclusionSet.Empty else m.intern(exclusion), m.intern(mx), tail)
        flow[key] = flow[key]?.let { FlowAlgebra.mergeAdd(it, node, m.cancellation) } ?: node
    }

    fun flow(layer: Layer, exclusion: ExclusionSet, mx: MarkSet, node: FlowNode,
             tail: Tail = if (layer == Layer.NORMAL) Tail.STAR else Tail.ANY) =
        flow(layer, exclusion, MarkExclusions.fromMarks(mx, m.marks), node, tail)

    fun taint(layer: Layer, node: TaintNode, exclusion: ExclusionSet = ExclusionSet.Empty,
              anyTail: Tail = if (layer == Layer.NORMAL) Tail.ANY_TAINT else Tail.ANY) {
        if (node.isEmpty) return
        val key = TaintKey(layer, if (anyTail == Tail.ANY || !node.hasAny) ExclusionSet.Empty else m.intern(exclusion),
            if (node.hasAny) anyTail else Tail.ANY_TAINT)
        taint[key] = taint[key]?.let { m.taintAlg.mergeAdd(it, node, m.cancellation) } ?: node
    }

    fun flush(out: ApOut) {
        for (layer in Layer.entries) if (reach[layer.ordinal]) {
            m.cancellation.checkpoint()
            out.result(Reach.of(layer))
        }
        for ((key, root) in flow) {
            m.cancellation.checkpoint()
            out.result(m.flowTree(base, key.layer, key.exclusion, key.mx, root, key.tail))
        }
        for ((key, root) in taint) {
            m.cancellation.checkpoint()
            out.result(m.taintTree(base, key.layer, root, key.exclusion, key.anyTail))
        }
        reach.fill(false)
        flow.clear()
        taint.clear()
    }
}

/** Keep every result and request in callback order. */
class CollectingOut : ApOut {
    val results = ArrayList<Facts>()
    val markRequests = ArrayList<TaintMark>()
    override fun result(f: Facts) { results += f }
    override fun markRequest(mark: TaintMark) { markRequests += mark }
}

package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.util.Cancellation
import java.util.ArrayDeque

/** A leaf on the cleaner spine is above or at its position. */
internal fun cleanPosAt(cl: Cleaner, tail: Tail, d: Int, admitsRest: Boolean): Pos =
    if (d < cl.pathArray.size) when (tail) {
        Tail.EXACT -> Pos.DISJOINT
        Tail.STAR, Tail.ANY, Tail.ANY_TAINT -> if (admitsRest) Pos.PART else Pos.DISJOINT
    } else when (tail) {
        Tail.EXACT -> if (cl.reach == CleanReach.BELOW) Pos.DISJOINT else Pos.INSIDE
        else -> if (cl.reach == CleanReach.AT_AND_BELOW) Pos.INSIDE else Pos.PART
    }

private class CleanFrame<P : TrieLeaf>(val node: TrieNode<P>, val kept: P, val accessor: Int)

/** Keep the original positional callback interface. */
internal fun <P : TrieLeaf> LeafAlgebra<P>.cleanSpine(
    n: TrieNode<P>, p: IntArray, reach: CleanReach, d: Int,
    atNode: (Int, P) -> P, inside: (TrieNode<P>) -> TrieNode<P>?,
): TrieNode<P>? = cleanSpine(n, p, reach, d, null, atNode, inside)

/** Visit and rebuild one spine. Only children below its end go through inside. */
internal fun <P : TrieLeaf> LeafAlgebra<P>.cleanSpine(
    n: TrieNode<P>, p: IntArray, reach: CleanReach, d: Int, cancellation: Cancellation?,
    atNode: (Int, P) -> P, inside: (TrieNode<P>) -> TrieNode<P>?,
): TrieNode<P>? {
    val parents = ArrayDeque<CleanFrame<P>>()
    var current = n
    var depth = d
    var result: TrieNode<P>?
    while (true) {
        cancellation?.checkpoint()
        val kept = atNode(depth, current.leaf)
        if (depth >= p.size) {
            result = if (reach == CleanReach.EXACT) withLeaf(current, kept) else {
                val kids = retainChildren(current, cancellation) { true }
                withLeaf(kids?.let(inside), kept)
            }
            break
        }
        val accessor = p[depth]
        val child = current.child(accessor)
        if (child == null) {
            result = replaceChild(current, kept, accessor, null)
            break
        }
        parents.addLast(CleanFrame(current, kept, accessor))
        current = child
        depth++
    }
    while (!parents.isEmpty()) {
        cancellation?.checkpoint()
        val parent = parents.removeLast()
        result = replaceChild(parent.node, parent.kept, parent.accessor, result)
    }
    cancellation?.checkpoint()
    return result
}

/** Requests are attached to the incoming premise by the caller's output. */
@Suppress("UNUSED_PARAMETER")
internal fun cleanFacts(m: ApManager, c: Facts, premise: PremiseKey, cl: Cleaner, mode: ApMode, out: ApOut) {
    m.cancellation.checkpoint()
    if (c.base != cl.base) { out.result(c); return }
    when (c) {
        is Reach -> out.result(c)
        is FlowTree -> FlowClean(m, c, cl, mode, out).run()
        is TaintTree -> TaintClean(m, c, cl, mode, out).run()
    }
}

/** Exact FULL-mask form of the selected nonstatic kernel. Geometry stays in the existing spatial walker. */
internal fun cleanSelectedFullMask(m: ApManager, c: Facts, cl: Cleaner, selected: MarkSet,
                                   mode: ApMode, request: (MarkSet) -> Unit, out: ApOut) {
    require(mode.run1 && mode.direction == Direction.FORWARD && mode.markMode == MarkMode.FULL)
    require(cl.base != STATIC && cl.base != org.opentaint.dataflow.ap.ifds.AccessPathBase.Zero)
    m.cancellation.checkpoint()
    if (c.base != cl.base) { out.result(c); return }
    when (c) {
        is Reach -> out.result(c)
        is FlowTree -> {
            // Selected nonstatic FLOW cleaning intentionally has no spatial test.
            val mx = m.intern(c.markExclusion + selected)
            request(selected) // incoming mx does not remove requested memberships
            out.result(m.flowTree(c.base, c.layer, c.exclusion, mx, c.root, c.tail))
        }
        is TaintTree -> TaintClean(m, c, cl, mode, out, selected).run()
    }
}

/** The selected-mark branch changes the header and shares every path. */
private class FlowClean(private val m: ApManager, private val c: FlowTree, private val cl: Cleaner,
                        private val mode: ApMode, private val out: ApOut) {
    private val results = Results(m, c.base)

    fun run() {
        val selected = cl.mark?.let { m.marks.runtimeAtom(it, mode.markMode) }
        if (selected != null) {
            if (mode.run1 && c.base == STATIC) { selectedStatic(selected); return }
            results.flow(c.layer, c.exclusion, m.intern(c.markExclusion + selected), c.root, c.tail)
            if (mode.run1) out.markRequest(selected)
            results.flush(out)
            return
        }
        FlowAlgebra.cleanSpine(c.root, cl.pathArray, cl.reach, 0, m.cancellation,
            { depth, leaf ->
                if (leaf.isEmpty) leaf else {
                    val pattern = PathFact(c.base, cl.pathArray.copyOf(depth).asList(), c.tail,
                        MarkSlot.Star(c.markExclusion))
                    for (kept in wholeFlowClean(cl, Conclusion(pattern, c.exclusion, c.layer == Layer.DEMAND))) {
                        val node = FlowAlgebra.prepend(m, m.path(kept.fact.path), FlowAlgebra.LEAF_NODE)
                        results.flow(if (kept.demand) Layer.DEMAND else Layer.NORMAL, kept.exclusion,
                            c.markExclusion, node, kept.fact.tail)
                    }
                    FlowLeaf.NONE
                }
            }, { null })?.let { results.flow(c.layer, c.exclusion, c.markExclusion, it, c.tail) }
        results.flush(out.run1Policy(m, mode))
    }

    /** A disjoint static field is not a mark-interest producer. Split selected
     * leaves before changing mx so an unrelated sibling keeps its own header. */
    private fun selectedStatic(selected: TaintMark) {
        val mx = m.intern(c.markExclusion + selected)
        var matched = false
        fun add(node: FlowNode) {
            matched = true
            results.flow(c.layer, c.exclusion, mx, node, c.tail)
        }
        val kept = FlowAlgebra.cleanSpine(c.root, cl.pathArray, cl.reach, 0, m.cancellation,
            { depth, leaf ->
                if (leaf.isEmpty || cleanPosAt(cl, c.tail, depth,
                        depth < cl.pathArray.size && c.exclusion.admits(cl.pathArray[depth])) == Pos.DISJOINT) leaf
                else {
                    add(FlowAlgebra.prepend(m, m.path(cl.pathArray.copyOf(depth)), FlowAlgebra.LEAF_NODE))
                    FlowLeaf.NONE
                }
            },
            { children ->
                add(FlowAlgebra.prepend(m, cl.path, children))
                null
            })
        kept?.let { results.flow(c.layer, c.exclusion, c.markExclusion, it, c.tail) }
        if (matched) out.markRequest(selected)
        results.flush(out)
    }


}

/** Concrete and all-mark cleaners retain the spatial and partial-cleaning rows. */
private class TaintClean(private val m: ApManager, private val c: TaintTree, private val cl: Cleaner,
                         private val mode: ApMode, private val out: ApOut, private val selected: MarkSet? = null) {
    private val results = Results(m, c.base)
    private val anyTail = c.anyTail

    private fun gone(marks: MarkSet): MarkSet = when {
        selected != null -> marks intersect selected
        cl.mark == null || marks.isEmpty -> marks
        mode.markMode == MarkMode.GROUP -> MarkSet.EMPTY // selected full mark cannot kill wildcard group
        else -> marks.intersect(m.markSetOf(cl.mark))
    }

    fun run() {
        m.taintAlg.cleanSpine(c.root, cl.pathArray, cl.reach, 0, m.cancellation, ::row) { kids ->
            m.taintAlg.mapLeaves(kids, m.cancellation) {
                m.taintLeaves(it.exact - gone(it.exact), it.any - gone(it.any))
            }
        }?.let { results.taint(c.layer, it, c.exclusion, c.anyTail) }
        results.flush(out)
    }

    private fun row(d: Int, leaf: TaintLeaves): TaintLeaves =
        m.taintLeaves(cut(d, Tail.EXACT, leaf.exact), cut(d, anyTail, leaf.any))

    private fun cut(d: Int, tail: Tail, marks: MarkSet): MarkSet {
        val removed = gone(marks)
        if (removed.isEmpty) return marks
        val path = cl.pathArray
        when (cleanPosAt(cl, tail, d, d >= path.size || c.exclusion.admits(path[d]))) {
            Pos.DISJOINT -> return marks
            Pos.INSIDE -> Unit
            Pos.PART -> {
                val at = m.path(path.copyOf(d))
                when {
                    tail == Tail.ANY_TAINT && d == path.size - 1 && cl.reach != CleanReach.EXACT -> {
                        if (mode.run1) put(Layer.DEMAND, at, Tail.ANY_TAINT, removed)
                        else put(c.layer, at, Tail.ANY_TAINT, removed, c.exclusion.union(ExclusionSet.of(path[d])))
                        if (cl.reach == CleanReach.BELOW) put(c.layer, cl.path, Tail.EXACT, removed)
                    }
                    (tail.isAny || tail == Tail.STAR) && cl.reach == CleanReach.BELOW && d == path.size ->
                        put(c.layer, at, Tail.EXACT, removed)
                    else -> put(Layer.DEMAND, at, tail, removed, c.exclusion)
                }
            }
        }
        return marks - removed
    }

    private fun put(layer: Layer, at: PathNode?, tail: Tail, marks: MarkSet,
                    exclusion: ExclusionSet = ExclusionSet.Empty) {
        val leaf = if (tail == Tail.EXACT) m.taintLeaves(marks, MarkSet.EMPTY) else m.taintLeaves(MarkSet.EMPTY, marks)
        val root = m.taintAlg.prepend(m, at, m.taintAlg.leafNode(leaf))
        results.taint(layer, root, exclusion, if (tail == Tail.EXACT) Tail.ANY_TAINT else tail)
    }
}

package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.AccessPathBase

sealed interface Facts {
    val base: AccessPathBase
    val layer: Layer
}

class Reach private constructor(override val layer: Layer) : Facts {
    override val base: AccessPathBase get() = AccessPathBase.Zero
    companion object {
        @JvmField val NORMAL = Reach(Layer.NORMAL)
        @JvmField val DEMAND = Reach(Layer.DEMAND)
        fun of(layer: Layer): Reach = if (layer == Layer.NORMAL) NORMAL else DEMAND
    }
}

class FlowTree internal constructor(
    override val base: AccessPathBase,
    override val layer: Layer,
    val exclusion: ExclusionSet,
    val markExclusion: MarkExclusions,
    val root: FlowNode,
    val tail: Tail = if (layer == Layer.NORMAL) Tail.STAR else Tail.ANY,
) : Facts {
    internal constructor(base: AccessPathBase, layer: Layer, exclusion: ExclusionSet, mx: MarkSet,
                         root: FlowNode, tail: Tail = if (layer == Layer.NORMAL) Tail.STAR else Tail.ANY) :
        this(base, layer, exclusion, MarkExclusions.fromMarks(mx), root, tail)
    init {
        check(base != AccessPathBase.Zero) { "Only REACH represents zero" }
        check(!root.isEmpty) { "A conclusion tree must be nonempty" }
        check(tail != Tail.ANY || layer == Layer.DEMAND) { "An ANY FLOW leaf is DEMAND" }
        check(tail != Tail.ANY || exclusion == ExclusionSet.Empty) { "An ANY leaf has Empty E" }
    }
    internal fun withRoot(root: FlowNode) = FlowTree(base, layer, exclusion, markExclusion, root, tail)
    override fun equals(other: Any?): Boolean = this === other || (other is FlowTree && layer == other.layer &&
        base == other.base && tail == other.tail && exclusion == other.exclusion && markExclusion == other.markExclusion && root == other.root)
    override fun hashCode(): Int = ((root.hashCode() * 31 + base.hashCode()) * 31 + exclusion.hashCode()) * 31 +
        markExclusion.hashCode() + layer.ordinal + tail.ordinal * 17
}

/** The any-leaf geometry is independent of the edge layer. */
class TaintTree internal constructor(
    override val base: AccessPathBase,
    override val layer: Layer,
    val root: TaintNode,
    val exclusion: ExclusionSet = ExclusionSet.Empty,
    val anyTail: Tail = if (layer == Layer.NORMAL) Tail.ANY_TAINT else Tail.ANY,
    val nonSubsumable: TaintNode? = null,
) : Facts {
    init {
        check(base != AccessPathBase.Zero) { "Only REACH represents zero" }
        check(!root.isEmpty) { "A conclusion tree must be nonempty" }
        check(anyTail == Tail.STAR || anyTail == Tail.ANY || anyTail == Tail.ANY_TAINT)
        check(exclusion == ExclusionSet.Empty || (anyTail != Tail.ANY && root.hasAny)) {
            "Only STAR and must leaves have an exclusion"
        }
    }
    internal fun withRoot(root: TaintNode) = TaintTree(base, layer, root, if (root.hasAny) exclusion else ExclusionSet.Empty,
        if (root.hasAny) anyTail else Tail.ANY_TAINT, nonSubsumable?.let { intersectTaintMask(it, root) })
    override fun equals(other: Any?): Boolean = this === other || (other is TaintTree && layer == other.layer &&
        base == other.base && anyTail == other.anyTail && exclusion == other.exclusion && root == other.root)
    override fun hashCode(): Int = ((root.hashCode() * 31 + base.hashCode()) * 31 + exclusion.hashCode()) * 2 + layer.ordinal + anyTail.ordinal * 17
}

enum class FactsKind { REACH, FLOW, TAINT }
data class GroupKey(
    val kind: FactsKind,
    val layer: Layer,
    val base: AccessPathBase,
    val exclusion: ExclusionSet = ExclusionSet.Empty,
    val markExclusion: MarkExclusions = MarkExclusions.EMPTY,
    val tail: Tail = when (kind) {
        FactsKind.REACH -> Tail.EXACT
        FactsKind.FLOW -> if (layer == Layer.NORMAL) Tail.STAR else Tail.ANY
        FactsKind.TAINT -> if (layer == Layer.NORMAL) Tail.ANY_TAINT else Tail.ANY
    },
) {
    constructor(kind: FactsKind, layer: Layer, base: AccessPathBase, exclusion: ExclusionSet,
                markExclusion: MarkSet, tail: Tail = when (kind) {
                    FactsKind.REACH -> Tail.EXACT
                    FactsKind.FLOW -> if (layer == Layer.NORMAL) Tail.STAR else Tail.ANY
                    FactsKind.TAINT -> if (layer == Layer.NORMAL) Tail.ANY_TAINT else Tail.ANY
                }) : this(kind, layer, base, exclusion, MarkExclusions.fromMarks(markExclusion), tail)
}

val Facts.groupKey: GroupKey get() = when (this) {
    is Reach -> GroupKey(FactsKind.REACH, layer, base)
    is FlowTree -> GroupKey(FactsKind.FLOW, layer, base, exclusion, markExclusion, tail)
    is TaintTree -> GroupKey(FactsKind.TAINT, layer, base, exclusion, tail = anyTail)
}

/** Layer changes never change known geometry or either exclusion annotation. */
fun Facts.withLayer(layer: Layer): Facts = if (this.layer == layer) this else when (this) {
    is Reach -> Reach.of(layer)
    is FlowTree -> FlowTree(base, layer, exclusion, markExclusion, root, tail)
    is TaintTree -> TaintTree(base, layer, root, exclusion, anyTail, nonSubsumable)
}

/** Exact TAINT leaves do not carry E and must not inherit a sibling's loss. */
internal fun run1CoverFacts(m: ApManager, f: Facts, emit: (Facts) -> Unit) {
    m.cancellation.checkpoint()
    when (f) {
        is Reach -> emit(f)
        is FlowTree -> emit(if (f.exclusion == ExclusionSet.Empty) f
            else FlowTree(f.base, Layer.DEMAND, ExclusionSet.Empty, f.markExclusion, f.root, f.tail))
        is TaintTree -> if (f.exclusion == ExclusionSet.Empty) emit(f) else {
            m.taintAlg.mapLeaves(f.root, m.cancellation) { m.taintLeaves(it.exact, MarkSet.EMPTY) }
                ?.let { emit(m.taintTree(f.base, f.layer, it, nonSubsumable = f.nonSubsumable?.let { mask -> intersectTaintMask(mask, it) })) }
            m.taintAlg.mapLeaves(f.root, m.cancellation) { m.taintLeaves(MarkSet.EMPTY, it.any) }
                ?.let { emit(m.taintTree(f.base, Layer.DEMAND, it, anyTail = f.anyTail,
                    nonSubsumable = f.nonSubsumable?.let { mask -> intersectTaintMask(mask, it) })) }
        }
    }
}

package org.opentaint.dataflow.bidi.ap


/** The caller enforces the run's must-premise mode before starting an initial. */
internal fun initialFacts(m: ApManager, i: InitialAp): Facts {
    m.cancellation.checkpoint()
    if (i.isZero) return Reach.NORMAL
    return when (val mark = i.mark) {
        is MarkSlot.Star -> {
            val layer = when (i.tail) {
                Tail.STAR -> Layer.NORMAL
                Tail.ANY -> Layer.DEMAND
                Tail.EXACT, Tail.ANY_TAINT -> Layer.NORMAL
            }
            m.flowTree(i.base, layer, i.exclusion, MarkSet.EMPTY,
                FlowAlgebra.prepend(m, i.path, FlowAlgebra.LEAF_NODE), i.tail)
        }
        is MarkSlot.Concrete -> {
            val marks = m.markSetOf(mark.mark)
            val exact = i.tail == Tail.EXACT
            val leaf = if (exact) m.taintLeaves(marks, MarkSet.EMPTY) else m.taintLeaves(MarkSet.EMPTY, marks)
            val layer = if (exact || i.tail == Tail.ANY_TAINT) Layer.NORMAL else Layer.DEMAND
            m.taintTree(i.base, layer, m.taintAlg.prepend(m, i.path, m.taintAlg.leafNode(leaf)),
                if (i.tail == Tail.STAR || i.tail == Tail.ANY_TAINT) i.exclusion else ExclusionSet.Empty,
                anyTail = if (exact) Tail.ANY_TAINT else i.tail)
        }
    }
}

internal fun policyInitial(m: ApManager, added: Facts): InitialAp {
    m.cancellation.checkpoint()
    return if (added is Reach) m.zero
        else m.initial(added.base, null, Tail.STAR, ExclusionSet.Empty, MarkSlot.STAR)
}

/** An abstract entry shares one FLOW initial across matching concrete marks and exit patterns. */
internal fun emitInitials(ops: ApOps, d: DemandPattern, added: Facts,
                          policy: RestrictedInitialPolicy = RestrictedInitialPolicy(direction = Direction.FORWARD, catalog = ops.manager.marks)): List<InitialAp> {
    val m = ops.manager
    m.cancellation.checkpoint()
    check(d.entry.fact.tail != Tail.ANY_TAINT) { "W8 (d): a demand entry cannot have a must tail" }
    val result = LinkedHashSet<InitialAp>()
    for (packet in m.canonicalPackets(added)) for (a in ops.leaves(packet)) {
        m.cancellation.checkpoint()
        val j = policy.emit(d.entry, a) ?: continue
        result += m.initial(j)
    }
    return result.toList()
}

/** Preserve the reference result, including shapes outside typed Facts. */
internal fun restrictRaw(ops: ApOps, j: InitialAp, g: Facts, d: DemandPattern,
                         policy: RestrictedInitialPolicy = RestrictedInitialPolicy(direction = Direction.FORWARD, catalog = ops.manager.marks)): List<Conclusion> {
    val m = ops.manager
    m.cancellation.checkpoint()
    val initial = j.toPattern()
    val result = LinkedHashSet<Conclusion>()
    for (a in ops.leaves(g)) {
        m.cancellation.checkpoint()
        restrict(initial, Conclusion(a.fact, a.exclusion, g.layer == Layer.DEMAND), d, m.marks, policy)?.let { result += it }
    }
    return result.toList()
}

/** Restrict protected memberships with the same geometry as the ordinary result. */
internal fun restrictFacts(ops: ApOps, j: InitialAp, g: Facts, d: DemandPattern,
                           policy: RestrictedInitialPolicy = RestrictedInitialPolicy(direction = Direction.FORWARD, catalog = ops.manager.marks)): List<Facts> {
    val out = CollectingOut()
    ops.manager.transportProtection(g, out) { part, sink ->
        for (value in restrictPlainFacts(ops, j, part, d, policy)) sink.result(value)
    }
    return out.results
}

/** An accepted existing entry predicate, bound to immutable native patterns.
 * No hypothetical initial is interned and no caller may construct a ticket. */
internal class EntryRestrictionTicket private constructor(
    val initial: Pattern,
    val pair: DemandPattern,
    private val ops: ApOps,
) {
    fun acceptedOutput(): AcceptedEntryOutput? = AcceptedEntryOutput.from(this)

    fun restrict(raw: Facts): List<Facts> {
        val out = CollectingOut()
        ops.manager.transportProtection(raw, out) { part, sink ->
            val selected = LinkedHashSet<Conclusion>()
            for (leaf in ops.leaves(part)) {
                ops.manager.cancellation.checkpoint()
                restrictConclusionOnly(Conclusion(leaf.fact, leaf.exclusion, part.layer == Layer.DEMAND),
                    pair.exit, ops.manager.marks)?.let(selected::add)
            }
            for (value in packRestrictedSelections(ops, selected)) sink.result(value)
        }
        return out.results
    }

    companion object {
        fun prepare(ops: ApOps, initial: Pattern, pair: DemandPattern,
                    policy: RestrictedInitialPolicy): EntryRestrictionTicket? {
            ops.manager.cancellation.checkpoint()
            return if (policy.canStoreInitial(pair.entry, initial)) EntryRestrictionTicket(initial, pair, ops) else null
        }
    }
}

/** Only a successful native entry check can produce this DATA output capability. */
internal class AcceptedEntryOutput private constructor(
    val initial: Pattern, val pair: DemandPattern, val fullExit: Pattern,
) {
    companion object {
        fun from(ticket: EntryRestrictionTicket): AcceptedEntryOutput? =
            ticket.pair.exit?.let { AcceptedEntryOutput(ticket.initial, ticket.pair, it) }
    }
}

/** Exact-key packing preserves every reference leaf and its raw layer. */
private fun restrictPlainFacts(ops: ApOps, j: InitialAp, g: Facts, d: DemandPattern,
                           policy: RestrictedInitialPolicy = RestrictedInitialPolicy(direction = Direction.FORWARD, catalog = ops.manager.marks)): List<Facts> {
    return packRestrictedSelections(ops, restrictRaw(ops, j, g, d, policy))
}

internal fun packRestrictedSelections(ops: ApOps, selected: Iterable<Conclusion>): List<Facts> {
    val m = ops.manager
    val values = LinkedHashMap<GroupKey, Facts>()
    for (value in selected) {
        val c = normalizeFlowSummaryConclusion(value)
        m.cancellation.checkpoint()
        val f = m.factsOf(c.fact, c.exclusion, if (c.demand) Layer.DEMAND else Layer.NORMAL)
        val old = values[f.groupKey]
        values[f.groupKey] = if (old == null) f else m.mergeAddDelta(old, f).first
    }
    return values.values.toList()
}

/** The existing handoff truth table, applied to final admitted headers. */
internal fun selectedForHandoff(premise: PremiseKey, layer: Layer, direction: Direction): Boolean {
    if (layer == Layer.DEMAND) return true
    val single = premise as? InitialAp ?: return true
    return direction == Direction.BACKWARD && single.isZero
}

internal fun selectDemand(m: ApManager, premise: PremiseKey, g: Facts, direction: Direction): Facts? {
    m.cancellation.checkpoint()
    return g.takeIf { selectedForHandoff(premise, it.layer, direction) }
}

package org.opentaint.dataflow.bidi.ap

/** Query-local selections. Each stream keeps its own native exclusion/tail header. */
internal class ProgramBucket {
    val protectedSelections = LinkedHashSet<Conclusion>()
    val ordinarySelections = LinkedHashSet<Conclusion>()
}

/** Optional diagnostics; no stream or AP value is retained by a counter. */
internal interface DemandScalarWork {
    fun stream() = Unit
    fun scalar() = Unit
    fun candidate() = Unit
    fun selectedReference(size: Int) = Unit
    fun overflow() = Unit
    fun pack() = Unit
}

/** The same protected-first traversal as transportProtection, with independent headers. */
internal fun forEachDemandScalar(ops: ApOps, raw: Facts, work: DemandScalarWork?,
                                visit: (protected: Boolean, scalar: Conclusion) -> Boolean) {
    fun stream(value: Facts, protected: Boolean): Boolean {
        work?.stream()
        for (leaf in ops.leaves(value)) {
            ops.manager.cancellation.checkpoint()
            work?.scalar()
            if (!visit(protected, Conclusion(leaf.fact, leaf.exclusion, value.layer == Layer.DEMAND))) return false
        }
        return true
    }
    (raw as? TaintTree)?.protectedPart()?.let { if (!stream(it, true)) return }
    stream(raw, false)
}

/** Preserve native whole-program packing, protected masks and first header order. */
internal fun packProgramStreams(ops: ApOps, bucket: ProgramBucket, work: DemandScalarWork? = null): List<Facts> {
    val masks = if (bucket.protectedSelections.isEmpty()) null else ProtectionOutputs(ops.manager).also { masks ->
        work?.pack()
        for (value in packRestrictedSelections(ops, bucket.protectedSelections)) masks.result(value)
    }
    work?.pack()
    val ordinary = packRestrictedSelections(ops, bucket.ordinarySelections)
    return if (masks == null) ordinary else ordinary.map(masks::attach)
}

package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.AccessPathBase

/** An exact diagonal packet with a typed STAR or ANY conclusion.
 * Marks stay correlated with their own concrete initial; this is not a FLOW
 * premise with a TaintTree. One immutable geometry serves the exact mark mask.
 * Protection applies uniformly to this packet; partial flags use separate
 * packets or the existing scalar fallback. */
data class DiagonalDelta(
    val initialShape: InitialAp,
    val base: AccessPathBase,
    val layer: Layer,
    val geometry: FlowNode,
    val marks: MarkSet,
    val protected: Boolean,
    val tail: Tail = Tail.ANY,
    val exclusion: ExclusionSet = ExclusionSet.Empty,
) {
    init {
        require(initialShape.isFlow && (initialShape.tail == Tail.STAR || initialShape.tail == Tail.ANY)) { "A diagonal packet needs an admitted FLOW initial shape" }
        require(base != AccessPathBase.Zero && base !is AccessPathBase.CleanerTemporary) {
            "A diagonal packet has an ordinary nonzero conclusion base"
        }
        require(!geometry.isEmpty && !marks.isEmpty) { "A diagonal packet needs geometry and mark memberships" }
        require((tail == Tail.STAR || tail == Tail.ANY) && (tail == Tail.STAR || exclusion == ExclusionSet.Empty))
        marks.forEach { mark ->
            initialShape.manager.cancellation.checkpoint()
            require(mark != TaintMark.ZERO) {
                "A diagonal packet contains nonzero runtime atoms"
            }
        }
    }
}

package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.ap.ifds.access.util.AccessorIdx

internal fun ApManager.compile(e: PathEdge): CompiledEdge = CompiledEdge(
    e.from.base, e.from.path.toIntArray(), e.from.tail, e.from.mark,
    e.to.base, path(e.to.path), e.to.tail, e.to.mark,
    intern(e.exclusion), intern(e.fromExclusion), intern(e.toExclusion))

/** Immutable edge form. The from-path array belongs to this value. */
internal class CompiledEdge(
    val fromBase: AccessPathBase, fromPath: IntArray, val fromTail: Tail, val fromMark: MarkSlot,
    val toBase: AccessPathBase, val toPath: PathNode?, val toTail: Tail, val toMark: MarkSlot,
    val exclusion: ExclusionSet,
    val fromExclusion: ExclusionSet = ExclusionSet.Empty,
    val toExclusion: ExclusionSet = ExclusionSet.Empty,
) {
    internal val fromPathData = fromPath.copyOf()
    val fromPath: IntArray get() = fromPathData.copyOf()

    init {
        check(fromMark !is MarkSlot.Star || fromMark.excluded.isEmpty) { "S7: a premise cannot exclude marks" }
        check(toMark !is MarkSlot.Concrete || fromMark is MarkSlot.Concrete) { "S7: a concrete target needs a concrete premise" }
        check(fromTail != Tail.EXACT || toTail != Tail.STAR || fromMark is MarkSlot.Star) {
            "A concrete exact premise cannot have a STAR target"
        }
        check(toTail != Tail.ANY_TAINT || toMark is MarkSlot.Concrete || fromMark is MarkSlot.Star) {
            "An abstract must target needs a FLOW relation"
        }
        check(fromTail == Tail.STAR || toTail == Tail.STAR || exclusion == ExclusionSet.Empty) { "W1: only STAR sides have shared E" }
        check(fromTail == Tail.ANY_TAINT || fromExclusion == ExclusionSet.Empty) { "A2: only a must premise has own E" }
        check(toTail == Tail.ANY_TAINT || toExclusion == ExclusionSet.Empty) { "A2: only a must target has own E" }
    }
}

/** The tree form of concat. Field cuts belong to the caller. */
internal class EdgeApplication(private val m: ApManager, private val ce: CompiledEdge,
                               private val edgeDemand: Boolean, private val mode: ApMode,
                               private val out: ApOut, private val unchangedStaticInitial: InitialAp? = null) {
    val results = Results(m, ce.toBase)
    private val gate = MarkGate(m, ce.fromMark, ce.toMark, mode)
    private val admitsRest = { a: AccessorIdx ->
        val premiseAdmits = when (ce.fromTail) {
            Tail.EXACT -> false
            Tail.ANY_TAINT -> ce.fromExclusion.admits(a)
            else -> ce.exclusion.admits(a)
        }
        premiseAdmits && (ce.toTail != Tail.STAR || ce.exclusion.admits(a))
    }
    private val aboveTail = if (ce.toTail == Tail.EXACT) Tail.EXACT else Tail.ANY
    private val mustAboveTail = when (ce.toTail) {
        Tail.EXACT -> Tail.EXACT
        Tail.ANY -> Tail.ANY
        Tail.STAR, Tail.ANY_TAINT -> Tail.ANY_TAINT
    }
    private val aboveExclusion = if (ce.toTail == Tail.ANY_TAINT) ce.toExclusion else ce.exclusion
    private var requested = false

    fun reach(c: Reach) {
        check(ce.fromPathData.isEmpty() && !ce.fromTail.isAny)
        gate.taintMarks(m.markSetOf(TaintMark.ZERO))?.let { put(c.layer or edgeDemand, ce.toTail, it, ce.toExclusion) }
    }

    fun flow(c: FlowTree, staticAt: Int) {
        // F78: exclusion creation also creates interest on the original abstract
        // slot. Do this before the positional/mark tests and before any output.
        // The engine's collector applies the normal-origin and static-root guards.
        if (mode.run1) (ce.toMark as? MarkSlot.Star)?.excluded?.data?.forEach { id ->
            m.cancellation.checkpoint()
            out.markRequest(m.marks.runtimeAtom(TaintMark(id), mode.markMode))
            if ((ce.fromMark as? MarkSlot.Concrete)?.mark?.id == id) requested = true
        }
        val mx = gate.flowMarks(c.markExclusion)
        val exact = c.tail == Tail.EXACT
        val must = c.tail == Tail.ANY_TAINT
        val normal = c.tail != Tail.ANY
        val writeKeep = ce.fromBase == ce.toBase && ce.fromTail == Tail.STAR &&
            ce.toTail == Tail.STAR && ce.fromPathData.contentEquals(ce.toPath?.toIntArray() ?: EMPTY_PATH) &&
            ce.exclusion != ExclusionSet.Empty
        val layer = c.layer or edgeDemand
        val unchanged = if (mode.run1 && mode.markMode == MarkMode.FULL) unchangedStaticFlowPath(c, unchangedStaticInitial) else null
        val u = c.root.walk(ce.fromPathData) { d, n ->
            m.cancellation.checkpoint()
            if (n.leaf.isEmpty || (normal && !c.exclusion.admits(ce.fromPathData[d]))) return@walk
            if (normal && d == staticAt) {
                // Prescan catalog emission replaces the old position request. This parent gives no fact.
            } else if (!exact || writeKeep) flowHit(mx, c, { !sameFlowLeaf(m, unchanged, ce.fromPathData, d) }) {
                if (must) {
                    val tail = if (layer == Layer.DEMAND) Tail.ANY else mustAboveTail
                    results.flow(if (tail == Tail.ANY) Layer.DEMAND else layer,
                        if (tail == Tail.ANY || tail == Tail.EXACT) ExclusionSet.Empty else aboveExclusion, it, flagAtTarget(), tail)
                } else results.flow(Layer.DEMAND, ExclusionSet.Empty, it, flagAtTarget())
            }
        } ?: return
        val kids = FlowAlgebra.retainChildren(u, m.cancellation, admitsRest)
        when (ce.toTail) {
            Tail.STAR -> {
                if (kids != null) flowHit(mx, c, { changedFlowSubtree(m, kids, ce.fromPathData, unchanged) }) {
                    if (layer == Layer.DEMAND && (exact || must))
                        results.flow(Layer.DEMAND, ExclusionSet.Empty, it, FlowAlgebra.prepend(m, ce.toPath, kids), Tail.ANY)
                    else results.flow(layer, c.exclusion, it, FlowAlgebra.prepend(m, ce.toPath, kids), c.tail)
                }
                if (!u.leaf.isEmpty) flowHit(mx, c, {
                    !sameFlowLeaf(m, unchanged, ce.fromPathData, ce.fromPathData.size)
                }) {
                    if (mode.run1 && ce.exclusion != ExclusionSet.Empty && c.tail != Tail.ANY)
                        results.flow(Layer.DEMAND, ExclusionSet.Empty, it, flagAtTarget(), c.tail)
                    else if (layer == Layer.DEMAND && (exact || must))
                        results.flow(Layer.DEMAND, ExclusionSet.Empty, it, flagAtTarget(), Tail.ANY)
                    else results.flow(layer, c.exclusion.union(ce.exclusion), it, flagAtTarget(), c.tail)
                }
            }
            else -> if (kids != null || !u.leaf.isEmpty) flowHit(mx, c, {
                (!u.leaf.isEmpty && !sameFlowLeaf(m, unchanged, ce.fromPathData, ce.fromPathData.size)) ||
                    (kids != null && changedFlowSubtree(m, kids, ce.fromPathData, unchanged))
            }) {
                val tail = if (layer == Layer.DEMAND && ce.toTail != Tail.ANY) Tail.ANY else ce.toTail
                val exclusion = when (tail) {
                    Tail.ANY_TAINT -> ce.toExclusion
                    Tail.EXACT -> ExclusionSet.Empty
                    else -> ExclusionSet.Empty
                }
                results.flow(if (tail == Tail.ANY) Layer.DEMAND else layer, exclusion, it, flagAtTarget(), tail)
            }
        }
    }

    private inline fun flowHit(mx: MarkExclusions?, c: FlowTree, changed: () -> Boolean, add: (MarkExclusions) -> Unit) {
        if (mx != null) { add(mx); return }
        val mark = gate.flowRequest(c.markExclusion) ?: return
        if (mode.run1 && !requested && changed()) { out.markRequest(mark); requested = true }
    }

    fun taint(c: TaintTree) {
        val layer = c.layer or edgeDemand
        val must = c.anyTail == Tail.ANY_TAINT
        val e = c.exclusion
        val u = c.root.walk(ce.fromPathData) { d, n ->
            m.cancellation.checkpoint()
            if (!e.admits(ce.fromPathData[d])) return@walk
            gate.taintMarks(n.leaf.any)?.let {
                if (must) put(layer, mustAboveTail, it, aboveExclusion)
                else put(Layer.DEMAND, aboveTail, it)
            }
        } ?: return
        when (ce.toTail) {
            Tail.STAR -> {
                m.taintAlg.retainChildren(u, m.cancellation, admitsRest)?.let { kids ->
                    gateTree(kids)?.let { results.taint(layer, m.taintAlg.prepend(m, ce.toPath, it), e, c.anyTail) }
                }
                gate.taintMarks(u.leaf.exact)?.let { put(layer, Tail.EXACT, it) }
                gate.taintMarks(u.leaf.any)?.let {
                    when (c.anyTail) {
                        Tail.STAR, Tail.ANY_TAINT -> put(layer, c.anyTail, it, e.union(ce.exclusion))
                        Tail.ANY -> put(Layer.DEMAND, Tail.ANY, it)
                        else -> error("Nonexact TAINT header")
                    }
                }
            }
            else -> {
                val all = m.taintAlg.foldLeaves(u, m.cancellation, admitsRest)
                gate.taintMarks(all.exact + all.any)?.let { put(layer, ce.toTail, it, ce.toExclusion) }
            }
        }
    }

    private fun put(layer: Layer, tail: Tail, marks: MarkSet, exclusion: ExclusionSet = ExclusionSet.Empty) {
        val resultLayer = if (tail == Tail.ANY) Layer.DEMAND else layer
        if (ce.toBase == AccessPathBase.Zero) { results.reach(resultLayer); return }
        val leaf = when (tail) {
            Tail.EXACT -> m.taintLeaves(marks, MarkSet.EMPTY)
            Tail.STAR, Tail.ANY, Tail.ANY_TAINT -> m.taintLeaves(MarkSet.EMPTY, marks)
        }
        val hasExclusion = tail == Tail.STAR || tail == Tail.ANY_TAINT
        val cover = mode.run1 && hasExclusion && exclusion != ExclusionSet.Empty
        results.taint(if (cover) Layer.DEMAND else resultLayer,
            m.taintAlg.prepend(m, ce.toPath, m.taintAlg.leafNode(leaf)),
            if (cover || !hasExclusion) ExclusionSet.Empty else exclusion,
            if (tail == Tail.EXACT) Tail.ANY_TAINT else tail)
    }

    private fun gateTree(n: TaintNode): TaintNode? =
        if (ce.fromMark == MarkSlot.STAR && ce.toMark == MarkSlot.STAR) n
        else m.taintAlg.mapLeaves(n, m.cancellation) { p ->
            m.taintLeaves(gate.taintMarks(p.exact) ?: MarkSet.EMPTY, gate.taintMarks(p.any) ?: MarkSet.EMPTY)
        }

    private fun flagAtTarget(): FlowNode = FlowAlgebra.prepend(m, ce.toPath, FlowAlgebra.LEAF_NODE)
}

package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.access.util.AccessorIdx

enum class Direction { FORWARD, BACKWARD }
enum class Layer { NORMAL, DEMAND }
enum class Tail { STAR, ANY, ANY_TAINT, EXACT }

val Tail.isAny: Boolean get() = this == Tail.ANY || this == Tail.ANY_TAINT
infix fun Layer.or(demand: Boolean): Layer = if (demand) Layer.DEMAND else this

/** Run 1 is forward. Every run has a positive field limit. */
class ApMode(val run1: Boolean, val direction: Direction, val fieldLimit: Int,
             val markMode: MarkMode = MarkMode.FULL) {
    val restricted: Boolean get() = !run1

    init {
        require(fieldLimit >= 1) { "The field limit must be positive" }
        require(!run1 || direction == Direction.FORWARD) { "Run 1 must be forward" }
    }
}

@JvmInline
value class TaintMark(val id: Int) {
    companion object { val ZERO = TaintMark(0) }
}

/** A canonical immutable set. Public arrays are snapshots of the owned content. */
class MarkSet(ids: IntArray) {
    internal val data: IntArray = ids.sortedDistinct()
    val ids: IntArray get() = data.copyOf()
    private val hash = data.contentHashCode()
    val isEmpty: Boolean get() = data.isEmpty()
    val size: Int get() = data.size

    operator fun contains(mark: TaintMark): Boolean = data.binarySearch(mark.id) >= 0
    fun isSubsetOf(other: MarkSet): Boolean = this === other || sortedSubset(data, other.data)
    operator fun plus(other: MarkSet): MarkSet =
        if (other.isSubsetOf(this)) this else MarkSet(sortedUnion(data, other.data))
    operator fun plus(mark: TaintMark): MarkSet =
        if (mark in this) this else MarkSet(sortedUnion(data, intArrayOf(mark.id)))
    operator fun minus(other: MarkSet): MarkSet =
        MarkSet(data.filter { other.data.binarySearch(it) < 0 }.toIntArray())
    infix fun intersect(other: MarkSet): MarkSet =
        MarkSet(data.filter { other.data.binarySearch(it) >= 0 }.toIntArray())
    fun forEach(visit: (TaintMark) -> Unit) { data.forEach { visit(TaintMark(it)) } }

    override fun equals(other: Any?): Boolean = this === other ||
        (other is MarkSet && hash == other.hash && data.contentEquals(other.data))
    override fun hashCode(): Int = hash
    override fun toString(): String = data.joinToString(prefix = "{", postfix = "}")

    companion object {
        val EMPTY = MarkSet(IntArray(0))
        fun of(mark: TaintMark): MarkSet = MarkSet(intArrayOf(mark.id))
    }
}

sealed interface MarkSlot {
    data class Star(val excluded: MarkExclusions) : MarkSlot {
        constructor(excluded: MarkSet) : this(MarkExclusions.fromMarks(excluded))
    }
    data class Concrete(val mark: TaintMark) : MarkSlot
    companion object { val STAR = Star(MarkSet.EMPTY) }
}

/** Only the first accessor of a nonempty continuation is tested against E. */
sealed interface ExclusionSet {
    fun admits(first: AccessorIdx): Boolean
    fun admits(rest: List<AccessorIdx>): Boolean = rest.isEmpty() || admits(rest[0])
    fun union(other: ExclusionSet): ExclusionSet
    fun intersect(other: ExclusionSet): ExclusionSet
    fun isSubsetOf(other: ExclusionSet): Boolean

    data object Empty : ExclusionSet {
        override fun admits(first: AccessorIdx): Boolean = true
        override fun union(other: ExclusionSet): ExclusionSet = other
        override fun intersect(other: ExclusionSet): ExclusionSet = this
        override fun isSubsetOf(other: ExclusionSet): Boolean = true
    }

    class Concrete internal constructor(ids: IntArray) : ExclusionSet {
        internal val data: IntArray = ids.sortedDistinct()
        val ids: IntArray get() = data.copyOf()
        private val hash = data.contentHashCode()

        init { check(data.isNotEmpty()) { "A concrete exclusion must be nonempty" } }

        override fun admits(first: AccessorIdx): Boolean = data.binarySearch(first) < 0
        override fun union(other: ExclusionSet): ExclusionSet =
            if (other is Concrete) of(sortedUnion(data, other.data)) else this
        override fun intersect(other: ExclusionSet): ExclusionSet =
            if (other is Concrete) of(data.filter { other.data.binarySearch(it) >= 0 }.toIntArray()) else Empty
        override fun isSubsetOf(other: ExclusionSet): Boolean =
            other is Concrete && sortedSubset(data, other.data)
        override fun equals(other: Any?): Boolean = this === other ||
            (other is Concrete && hash == other.hash && data.contentEquals(other.data))
        override fun hashCode(): Int = hash
        override fun toString(): String = data.joinToString(prefix = "{", postfix = "}")
    }

    companion object {
        fun of(ids: IntArray): ExclusionSet = if (ids.isEmpty()) Empty else Concrete(ids)
        fun of(accessor: AccessorIdx): ExclusionSet = Concrete(intArrayOf(accessor))
    }
}

val EMPTY_PATH: IntArray = IntArray(0)

internal fun IntArray.sortedDistinct(): IntArray {
    if (isEmpty()) return IntArray(0)
    val result = sortedArray()
    var size = 1
    for (index in 1 until result.size) {
        if (result[index] != result[size - 1]) result[size++] = result[index]
    }
    return if (size == result.size) result else result.copyOf(size)
}

internal fun sortedUnion(a: IntArray, b: IntArray): IntArray {
    val result = IntArray(Math.addExact(a.size, b.size))
    var ai = 0
    var bi = 0
    var size = 0
    while (ai < a.size || bi < b.size) {
        val value = when {
            bi == b.size || (ai < a.size && a[ai] < b[bi]) -> a[ai++]
            ai == a.size || b[bi] < a[ai] -> b[bi++]
            else -> a[ai++].also { bi++ }
        }
        result[size++] = value
    }
    return result.copyOf(size)
}

internal fun sortedSubset(a: IntArray, b: IntArray): Boolean {
    var ai = 0
    var bi = 0
    while (ai < a.size && bi < b.size) {
        when {
            a[ai] == b[bi] -> { ai++; bi++ }
            a[ai] > b[bi] -> bi++
            else -> return false
        }
    }
    return ai == a.size
}

fun IntArray.startsWith(prefix: IntArray): Boolean =
    size >= prefix.size && prefix.indices.all { this[it] == prefix[it] }

package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.FactTypeChecker
import org.opentaint.dataflow.ap.ifds.access.util.AccessorInterner.Companion.ELEMENT_ACCESSOR_IDX
import java.util.ArrayDeque

/** A path filter runs before the concrete mark policy; the input annotations belong to the whole tails. */
internal fun filterFacts(m: ApManager, c: Facts, f: TypeFilter): Facts? {
    m.cancellation.checkpoint()
    return when (c) {
        is Reach -> c
        is FlowTree -> FlowAlgebra.filterPath(m, c.root, f.may)
            ?.let { if (it === c.root) c else c.withRoot(it) }
        is TaintTree -> {
            var result = m.taintAlg.filterPath(m, c.root, f.may)
            val policy = f.markPolicy
            if (result != null && policy != null) result = markPolicyOnElements(m, result, policy)
            result?.let { if (it === c.root) c else m.taintTree(c.base, c.layer, it, c.exclusion, c.anyTail) }
        }
    }
}

private class FilterState<P : TrieLeaf>(val node: TrieNode<P>, val filter: FactTypeChecker.FactApFilter) {
    private val hash = System.identityHashCode(node) * 31 + System.identityHashCode(filter)
    override fun hashCode(): Int = hash
    override fun equals(other: Any?): Boolean = other is FilterState<*> &&
        node === other.node && filter === other.filter
}

private class FilterFrame<P : TrieLeaf>(val state: FilterState<P>) {
    var next = 0
    var waiting: FilterState<P>? = null
    var changed = false
    val accessors = ArrayList<Int>()
    val children = ArrayList<TrieNode<P>>()

    fun add(index: Int, child: TrieNode<P>?) {
        val node = state.node
        if (child !== node.childData!![index]) changed = true
        if (child != null) {
            accessors += node.accessorData!![index]
            children += child
        }
    }
}

/** Evaluate each edge once per node/filter identity pair, caching removed subtrees as null. */
internal fun <P : TrieLeaf> LeafAlgebra<P>.filterPath(
    m: ApManager, n: TrieNode<P>, may: FactTypeChecker.FactApFilter,
): TrieNode<P>? {
    m.cancellation.checkpoint()
    val initial = FilterState(n, may)
    val memo = HashMap<FilterState<P>, TrieNode<P>?>()
    val pending = ArrayDeque<FilterFrame<P>>()
    pending.addLast(FilterFrame(initial))
    while (pending.isNotEmpty()) {
        m.cancellation.checkpoint()
        val frame = pending.peekLast()
        val waiting = frame.waiting
        if (waiting != null) {
            check(memo.containsKey(waiting))
            frame.add(frame.next - 1, memo[waiting])
            frame.waiting = null
            continue
        }
        val current = frame.state.node
        val accessors = current.accessorData
        if (accessors != null && frame.next < accessors.size) {
            val index = frame.next++
            val child = current.childData!![index]
            val result = frame.state.filter.check(m.accessors.accessor(accessors[index]))
            m.cancellation.checkpoint()
            when (result) {
                FactTypeChecker.FilterResult.Accept -> frame.add(index, child)
                FactTypeChecker.FilterResult.Reject -> frame.add(index, null)
                is FactTypeChecker.FilterResult.FilterNext -> {
                    val state = FilterState(child, result.filter)
                    if (memo.containsKey(state)) frame.add(index, memo[state])
                    else {
                        frame.waiting = state
                        pending.addLast(FilterFrame(state))
                    }
                }
            }
            continue
        }
        memo[frame.state] = if (!frame.changed) current.takeIf { !it.isEmpty }
            else node(current.leaf, frame.accessors.toIntArray(), frame.children.toTypedArray()).takeIf { !it.isEmpty }
        pending.removeLast()
    }
    return memo[initial]
}

private class PolicyFrame(val node: TaintNode, val kept: TaintLeaves)

/** Only the root and its uninterrupted element chain have their payload marks filtered. */
private fun markPolicyOnElements(m: ApManager, n: TaintNode, policy: MarkPolicy): TaintNode? {
    val spine = ArrayList<PolicyFrame>()
    var current = n
    var level = 0
    while (true) {
        m.cancellation.checkpoint()
        val kept = m.taintLeaves(keepPolicyMarks(m, current.leaf.exact, policy, level),
            keepPolicyMarks(m, current.leaf.any, policy, level))
        spine += PolicyFrame(current, kept)
        val child = current.child(ELEMENT_ACCESSOR_IDX) ?: break
        current = child
        level = Math.addExact(level, 1)
    }
    var below: TaintNode? = null
    for (index in spine.indices.reversed()) {
        m.cancellation.checkpoint()
        val frame = spine[index]
        val oldChild = frame.node.child(ELEMENT_ACCESSOR_IDX)
        below = when {
            frame.kept === frame.node.leaf && below === oldChild -> frame.node
            oldChild == null -> m.taintAlg.withLeaf(frame.node, frame.kept)
            else -> m.taintAlg.replaceChild(frame.node, frame.kept, ELEMENT_ACCESSOR_IDX, below)
        }
    }
    return below
}

private fun keepPolicyMarks(m: ApManager, marks: MarkSet, policy: MarkPolicy, level: Int): MarkSet {
    if (marks.isEmpty) return marks
    val kept = ArrayList<Int>()
    for (id in marks.data) {
        m.cancellation.checkpoint()
        val atom = TaintMark(id)
        val keep = policy.keeps(atom, level)
        m.cancellation.checkpoint()
        if (keep) kept += id
    }
    return if (kept.size == marks.data.size) marks else m.intern(MarkSet(kept.toIntArray()))
}

package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import java.util.ArrayDeque

/** The owner fixes method, run, view and summary endpoint. Preserve all
 * admitted counterpart geometry; no runtime atom or iteration gate applies. */
fun flowInitialForCoverage(m: ApManager, premise: PremiseKey): InitialAp? {
    m.cancellation.checkpoint()
    val initial = premise as? InitialAp ?: return null
    val mark = initial.mark as? MarkSlot.Concrete ?: return null
    if (initial.manager !== m || initial.isZero || mark.mark == TaintMark.ZERO || (initial.tail != Tail.STAR && initial.tail != Tail.ANY)) return null
    return m.initial(initial.base, initial.path, initial.tail, initial.exclusion, MarkSlot.STAR)
}

private fun eligibleAnyHeader(flow: FlowTree, base: AccessPathBase, mark: TaintMark, layer: Layer): Boolean =
    flow.base == base && flow.tail == Tail.ANY && mark !in flow.markExclusion &&
        (flow.layer == Layer.NORMAL || layer == Layer.DEMAND)

/** Look only along the one TAINT path. A branch without a FLOW leaf is not
 * an output. All header gates apply to the same selected FLOW output. */
fun flowCoversAny(m: ApManager, flow: FlowTree, base: AccessPathBase, path: IntArray,
                  mark: TaintMark, layer: Layer): Boolean {
    m.cancellation.checkpoint()
    if (!eligibleAnyHeader(flow, base, mark, layer)) return false
    var node = flow.root
    if (!node.leaf.isEmpty) return true
    for (accessor in path) {
        m.cancellation.checkpoint()
        node = node.child(accessor) ?: return false
        if (!node.leaf.isEmpty) return true
    }
    return false
}

/** Remove plain diagonal memberships under one complete FLOW candidate.
 * STAR uses equal output paths and suffix-exclusion inclusion; ANY uses
 * prefixes. EXACT/must, cross-atom and protected memberships remain. */
fun removeFlowCovered(m: ApManager, initial: PremiseKey, facts: TaintTree,
                      flow: Iterable<FlowTree>, protection: TaintNode? = null): TaintTree? {
    m.cancellation.checkpoint()
    if ((facts.anyTail != Tail.STAR && facts.anyTail != Tail.ANY) || flowInitialForCoverage(m, initial) == null) return facts
    val mark = ((initial as InitialAp).mark as MarkSlot.Concrete).mark
    var root: TaintNode = facts.root
    for (candidate in flow) {
        m.cancellation.checkpoint()
        if (candidate.base != facts.base || candidate.tail != facts.anyTail || mark in candidate.markExclusion ||
            (candidate.layer != Layer.NORMAL && facts.layer != Layer.DEMAND) ||
            (facts.anyTail == Tail.STAR && !candidate.exclusion.isSubsetOf(facts.exclusion))) continue
        root = if (facts.anyTail == Tail.STAR)
            removeCoveredStar(m, root, candidate.root, protection, mark) ?: return null
        else removeCoveredDiagonal(m, root, candidate.root, protection, mark) ?: return null
    }
    return if (root === facts.root) facts else facts.withRoot(root)
}

/** Compatibility entry for callers which explicitly inspect the ANY cell. */
fun removeFlowCoveredAny(m: ApManager, initial: PremiseKey, facts: TaintTree,
                         flow: Iterable<FlowTree>, protection: TaintNode? = null): TaintTree? =
    if (facts.anyTail == Tail.ANY) removeFlowCovered(m, initial, facts, flow, protection) else facts

private class StarCoverKey(val taint: TaintNode, val flow: FlowNode?, val protected: TaintNode?) {
    override fun hashCode(): Int = (System.identityHashCode(taint) * 31 + System.identityHashCode(flow)) * 31 +
        System.identityHashCode(protected)
    override fun equals(other: Any?): Boolean = other is StarCoverKey && taint === other.taint &&
        flow === other.flow && protected === other.protected
}
private class StarCoverFrame(val key: StarCoverKey, var expanded: Boolean = false)

/** Equal-node walk: an annotated proper prefix cannot cover a shared suffix. */
private fun removeCoveredStar(m: ApManager, root: TaintNode, flow: FlowNode,
                              protection: TaintNode?, mark: TaintMark): TaintNode? {
    val memo = HashMap<StarCoverKey, TaintNode?>()
    val stack = ArrayDeque<StarCoverFrame>()
    val initial = StarCoverKey(root, flow, protection)
    val one = m.markSetOf(mark)
    stack.addLast(StarCoverFrame(initial))
    while (stack.isNotEmpty()) {
        m.cancellation.checkpoint()
        val frame = stack.peekLast()
        val key = frame.key
        if (memo.containsKey(key)) { stack.removeLast(); continue }
        if (key.flow == null) { memo[key] = key.taint; stack.removeLast(); continue }
        fun childKey(accessor: Int, child: TaintNode) =
            StarCoverKey(child, key.flow.child(accessor), key.protected?.child(accessor))
        if (!frame.expanded) {
            frame.expanded = true
            key.taint.accessorData?.forEachIndexed { i, accessor ->
                val child = childKey(accessor, key.taint.childData!![i])
                if (!memo.containsKey(child)) stack.addLast(StarCoverFrame(child))
            }
            continue
        }
        val leaf = key.taint.leaf
        val remove = key.flow.leaf == FlowLeaf.LEAF && key.protected?.leaf?.any?.contains(mark) != true
        val remaining = if (remove) m.taintLeaves(leaf.exact, leaf.any - one) else leaf
        memo[key] = m.taintAlg.mapChildren(key.taint, remaining, m.cancellation) { accessor, child ->
            memo.getValue(childKey(accessor, child))
        }
        stack.removeLast()
    }
    return memo.getValue(initial)
}

/** References are deliberate: structural trie hashing here would traverse
 * shared geometry while building the traversal memo. */
private class AnyCoverKey(val taint: TaintNode, val flow: FlowNode?, val protected: TaintNode?,
                          val coveredAbove: Boolean, val protectedAbove: Boolean) {
    override fun hashCode(): Int = (((System.identityHashCode(taint) * 31 + System.identityHashCode(flow)) * 31 +
        System.identityHashCode(protected)) * 31 + coveredAbove.hashCode()) * 31 + protectedAbove.hashCode()
    override fun equals(other: Any?): Boolean = other is AnyCoverKey && taint === other.taint &&
        flow === other.flow && protected === other.protected && coveredAbove == other.coveredAbove &&
        protectedAbove == other.protectedAbove
}

private class AnyCoverFrame(val key: AnyCoverKey, var expanded: Boolean = false)

private fun removeCoveredDiagonal(m: ApManager, root: TaintNode, flow: FlowNode,
                                   protection: TaintNode?, mark: TaintMark): TaintNode? {
    val alg = m.taintAlg
    val memo = HashMap<AnyCoverKey, TaintNode?>()
    val stack = ArrayDeque<AnyCoverFrame>()
    val initial = AnyCoverKey(root, flow, protection, coveredAbove = false, protectedAbove = false)
    val one = m.markSetOf(mark)
    stack.addLast(AnyCoverFrame(initial))
    while (stack.isNotEmpty()) {
        m.cancellation.checkpoint()
        val frame = stack.peekLast()
        val key = frame.key
        if (memo.containsKey(key)) {
            stack.removeLast()
            continue
        }
        if ((!key.coveredAbove && key.flow == null) || mark !in alg.foldAll(key.taint, m.cancellation).any) {
            memo[key] = key.taint
            stack.removeLast()
            continue
        }
        val coveredHere = key.coveredAbove || key.flow?.leaf == FlowLeaf.LEAF
        val protectedHere = key.protectedAbove || key.protected?.leaf?.any?.contains(mark) == true
        fun childKey(accessor: Int, child: TaintNode) = AnyCoverKey(child,
            if (coveredHere) null else key.flow?.child(accessor), key.protected?.child(accessor),
            coveredHere, protectedHere)
        if (!frame.expanded) {
            frame.expanded = true
            key.taint.accessorData?.forEachIndexed { i, accessor ->
                m.cancellation.checkpoint()
                val child = childKey(accessor, key.taint.childData!![i])
                if (!memo.containsKey(child)) stack.addLast(AnyCoverFrame(child))
            }
            continue
        }
        // An ANY membership contains descendant EXACT protection too. Keep
        // that wider marked member rather than lose the protected subregion.
        val protectedBelow = key.protected?.let { alg.foldAll(it, m.cancellation) }
            ?.let { mark in it.exact || mark in it.any } == true
        val leaf = key.taint.leaf
        val offered = if (coveredHere && !protectedHere && !protectedBelow && mark in leaf.any)
            m.taintLeaves(leaf.exact, leaf.any - one) else leaf
        memo[key] = alg.mapChildren(key.taint, offered, m.cancellation) { accessor, child ->
            memo.getValue(childKey(accessor, child))
        }
        stack.removeLast()
    }
    return memo.getValue(initial)
}

package org.opentaint.dataflow.bidi.ap

import java.util.ArrayDeque
import org.opentaint.dataflow.util.Cancellation

/** Exact output coordinates. An annotation is never part of ordinary Facts identity. */
fun TaintTree.withProtection(mask: TaintNode?, cancellation: Cancellation? = null): TaintTree {
    val kept = mask?.let { intersectTaintMask(it, root, cancellation) }
    if (kept === nonSubsumable) return this
    return TaintTree(base, layer, root, exclusion, anyTail, kept)
}

fun TaintTree.withoutProtection(): TaintTree =
    if (nonSubsumable == null) this else TaintTree(base, layer, root, exclusion, anyTail)

/** A plain value lets a pure AP operation transport the annotation without new observations. */
fun TaintTree.protectedPart(): TaintTree? = nonSubsumable?.let {
    TaintTree(base, layer, it, if (it.hasAny) exclusion else ExclusionSet.Empty,
        if (it.hasAny) anyTail else Tail.ANY_TAINT)
}

fun Facts.withoutProtection(): Facts = if (this is TaintTree) withoutProtection() else this

private class MaskFrame(val pair: NodePair<TaintLeaves>, var expanded: Boolean = false)

/** Restrict metadata to the exact surviving positions and marks. This walk is stack safe. */
internal fun intersectTaintMask(mask: TaintNode, kept: TaintNode, cancellation: Cancellation? = null): TaintNode? {
    if (mask === kept) return mask
    val memo = HashMap<NodePair<TaintLeaves>, TaintNode?>()
    val initial = NodePair(mask, kept)
    val stack = ArrayDeque<MaskFrame>()
    stack.addLast(MaskFrame(initial))
    while (stack.isNotEmpty()) {
        cancellation?.checkpoint()
        val frame = stack.peekLast()
        val pair = frame.pair
        if (memo.containsKey(pair)) { stack.removeLast(); continue }
        if (pair.a === pair.b) { memo[pair] = pair.a; stack.removeLast(); continue }
        if (!frame.expanded) {
            frame.expanded = true
            pair.a.accessorData?.forEachIndexed { i, accessor ->
                cancellation?.checkpoint()
                pair.b.child(accessor)?.let { child ->
                    val key = NodePair(pair.a.childData!![i], child)
                    if (!memo.containsKey(key)) stack.addLast(MaskFrame(key))
                }
            }
            continue
        }
        val exact = pair.a.leaf.exact intersect pair.b.leaf.exact
        val any = pair.a.leaf.any intersect pair.b.leaf.any
        val leaf = if (exact.isEmpty && any.isEmpty) TaintLeaves.EMPTY else TaintLeaves(exact, any)
        val accessors = ArrayList<Int>()
        val children = ArrayList<TaintNode>()
        pair.a.accessorData?.forEachIndexed { i, accessor ->
            cancellation?.checkpoint()
            pair.b.child(accessor)?.let { child ->
                memo[NodePair(pair.a.childData!![i], child)]?.let {
                    accessors += accessor; children += it
                }
            }
        }
        memo[pair] = if (leaf.isEmpty && children.isEmpty()) null
            else if (leaf == pair.a.leaf && children.size == (pair.a.childData?.size ?: 0) &&
                children.indices.all { children[it] === pair.a.childData!![it] }) pair.a
            else TrieNode(leaf, accessors.toIntArray(), children.toTypedArray(), false)
        stack.removeLast()
    }
    return memo[initial]
}

/** Merge annotation outputs by the same complete typed header as ordinary results. */
internal class ProtectionOutputs(private val m: ApManager) : ApOut {
    // An exact-only projection has canonical Empty E/ANY_TAINT even when its
    // ordinary sibling has ANY leaves. Exact annotations are header independent.
    private val exact = HashMap<Pair<org.opentaint.dataflow.ap.ifds.AccessPathBase, Layer>, TaintNode>()
    private val any = HashMap<GroupKey, TaintNode>()
    override fun markRequest(mark: TaintMark) = Unit
    private fun <K> add(store: MutableMap<K, TaintNode>, key: K, root: TaintNode?) {
        if (root == null) return
        store[key] = store[key]?.let { m.taintAlg.mergeAdd(it, root, m.cancellation) } ?: root
    }
    override fun result(f: Facts) {
        if (f !is TaintTree) return
        val ex = if (!f.root.hasAny) f.root else m.taintAlg.mapLeaves(f.root, m.cancellation) {
            m.taintLeaves(it.exact, MarkSet.EMPTY)
        }
        add(exact, f.base to f.layer, ex)
        if (f.root.hasAny) add(any, f.groupKey, m.taintAlg.mapLeaves(f.root, m.cancellation) {
            m.taintLeaves(MarkSet.EMPTY, it.any)
        })
    }
    fun attach(f: Facts): Facts {
        if (f !is TaintTree) return f
        var root = f.nonSubsumable
        for (offered in listOfNotNull(exact[f.base to f.layer], any[f.groupKey])) {
            root = root?.let { m.taintAlg.mergeAdd(it, offered, m.cancellation) } ?: offered
        }
        return if (root == null) f else f.withProtection(root, m.cancellation)
    }
}

internal fun ApManager.transportProtection(c: Facts, out: ApOut, operation: (Facts, ApOut) -> Unit) {
    val protected = (c as? TaintTree)?.protectedPart()
    if (protected == null) { operation(c, out); return }
    val masks = ProtectionOutputs(this)
    operation(protected, masks)
    operation(c, object : ApOut {
        override fun result(f: Facts) = out.result(masks.attach(f))
        override fun markRequest(mark: TaintMark) = out.markRequest(mark)
    })
}

internal fun ApManager.selectedProtection(f: Facts, selected: MarkSet?): Facts {
    if (f !is TaintTree) return f
    val selectedRoot = if (selected == null) f.root else taintAlg.mapLeaves(f.root, cancellation) {
        taintLeaves(it.exact intersect selected, it.any intersect selected)
    } ?: return f
    val root = f.nonSubsumable?.let { taintAlg.mergeAdd(it, selectedRoot, cancellation) } ?: selectedRoot
    return f.withProtection(root, cancellation)
}

/** Selection/filter operations keep coordinates and only remove memberships. */
internal fun retainProtection(input: Facts, result: Facts, cancellation: Cancellation? = null): Facts =
    if (input !is TaintTree || result !is TaintTree || input.nonSubsumable == null) result
    else result.withProtection(input.nonSubsumable, cancellation)

package org.opentaint.dataflow.bidi.ap

/** A complete summary pair has one canonical storage key. Point keys stay unchanged. */
data class FlowSummaryForm(val premise: PremiseKey, val facts: Facts)

fun normalizeFlowSummary(manager: ApManager, premise: PremiseKey, facts: Facts): FlowSummaryForm {
    if (!premise.isFlow || facts !is FlowTree) return FlowSummaryForm(premise, facts)
    val initial = premise as InitialAp
    val key = if (initial.tail == Tail.EXACT)
        manager.initial(initial.base, initial.path, Tail.STAR, initial.exclusion, initial.mark)
    else initial
    val result = if (facts.tail == Tail.EXACT)
        manager.flowTree(facts.base, facts.layer, facts.exclusion, facts.markExclusion, facts.root, Tail.STAR)
    else facts
    return FlowSummaryForm(key, result)
}

fun normalizeFlowSummaryConclusion(c: Conclusion): Conclusion =
    if (c.fact.mark is MarkSlot.Star && c.fact.tail == Tail.EXACT)
        c.copy(fact = c.fact.copy(tail = Tail.STAR)) else c

fun assertCanonicalFlowSummary(premise: PremiseKey, facts: Facts) {
    if (!premise.isFlow || facts !is FlowTree) return
    check((premise as InitialAp).tail != Tail.EXACT && facts.tail != Tail.EXACT) {
        "Normalize the complete FLOW pair before summary storage"
    }
}

/** Guidance comparisons use the same pair form as summaries. Raw writer keys stay raw. */
fun normalizeFlowSummaryPatterns(from: Pattern, to: Pattern): Pair<Pattern, Pattern> {
    if (from.fact.mark !is MarkSlot.Star || to.fact.mark !is MarkSlot.Star) return from to to
    fun normal(p: Pattern) = if (p.fact.tail == Tail.EXACT) p.copy(fact = p.fact.copy(tail = Tail.STAR)) else p
    return normal(from) to normal(to)
}

package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.util.Cancellation
import org.opentaint.dataflow.util.SoftReferenceManager

/** FLOW values for one base, separated by layer and both exclusions. One store writer owns this group. */
class FlowGroup(private val m: ApManager, private val interner: TrieInterner<FlowLeaf>) {
    private val trees = arrayOf(ArrayList<FlowTree>(1), ArrayList<FlowTree>(1))

    fun all(): Sequence<FlowTree> = trees[0].asSequence() + trees[1].asSequence()

    /** T4: return the new part, or the merged value when T2 changes an annotation. */
    fun add(t: FlowTree): FlowTree? = addAll(t).also {
        check(it.size <= 1) { "Canonical admission has multiple headers; use addAll" }
    }.singleOrNull()

    fun addAll(t: FlowTree): List<FlowTree> {
        m.cancellation.checkpoint()
        val before = trees[t.layer.ordinal]
        if (t.tail != Tail.ANY && t.tail != Tail.ANY_TAINT)
            return addInto(t,before)?.let(::listOf) ?: emptyList()
        if (before.isEmpty()) {
            val canonical = m.canonicalFlowPacket(t)
            val root = interner.internIfRequired(canonical.root)
            val stored = if (root === canonical.root) canonical else canonical.withRoot(root)
            trees[t.layer.ordinal] = arrayListOf(stored)
            return listOf(stored)
        }
        val staged = ArrayList(before)
        if (addInto(t, staged) == null) return emptyList()
        val after = m.canonicalFlowState(staged)
        val changes = ArrayList<FlowTree>()
        for (value in after) {
            val fresh = subtractSubsumed(value,before) ?: continue
            changes += fresh
        }
        m.cancellation.checkpoint()
        trees[t.layer.ordinal] = ArrayList(after.map { it.withRoot(interner.internIfRequired(it.root)) })
        return changes
    }

    private fun addInto(t: FlowTree, list: ArrayList<FlowTree>): FlowTree? {
        var pending = t
        while (true) {
            m.cancellation.checkpoint()
            val i = list.indexOfFirst {
                m.cancellation.checkpoint()
                it.tail == pending.tail && it.exclusion == pending.exclusion && it.markExclusion == pending.markExclusion
            }
            if (i >= 0) {
                val rest = subtractSubsumed(pending, list) ?: return null
                val (merged, delta) = FlowAlgebra.mergeAddDelta(list[i].root, rest.root, m.cancellation)
                if (delta == null) return null
                list[i] = list[i].withRoot(interner.internIfRequired(merged))
                return m.flowTree(pending.base, pending.layer, pending.exclusion, pending.markExclusion, delta, pending.tail)
            }

            val k = list.indexOfFirst {
                m.cancellation.checkpoint()
                it.tail == pending.tail && it.root == pending.root &&
                    (it.markExclusion == pending.markExclusion || it.exclusion == pending.exclusion)
            }
            if (k >= 0) {
                val stored = list[k]
                val merged = m.flowTree(pending.base, pending.layer,
                    stored.exclusion.intersect(pending.exclusion),
                    stored.markExclusion.intersect(pending.markExclusion), stored.root, pending.tail)
                if (merged.exclusion == stored.exclusion && merged.markExclusion == stored.markExclusion) return null
                list.removeAt(k)
                pending = merged
                continue
            }

            val fresh = subtractSubsumed(pending, list) ?: return null
            list += fresh.withRoot(interner.internIfRequired(fresh.root))
            return fresh
        }
    }

    private fun subtractSubsumed(t: FlowTree, others: List<FlowTree>): FlowTree? {
        var root = t.root
        for (stored in others) {
            m.cancellation.checkpoint()
            val marks = stored.markExclusion.isSubsetOf(t.markExclusion)
            val atOk = marks && when (stored.tail) {
                Tail.ANY -> true
                Tail.STAR -> t.tail == Tail.STAR && stored.exclusion.isSubsetOf(t.exclusion)
                Tail.EXACT -> t.tail == Tail.EXACT && stored.exclusion.isSubsetOf(t.exclusion)
                Tail.ANY_TAINT -> t.tail == Tail.ANY_TAINT && stored.exclusion.isSubsetOf(t.exclusion)
            }
            val belowOk = !t.keepsDemandPositions() && marks && (stored.tail == Tail.ANY ||
                stored.tail == Tail.ANY_TAINT && t.tail == Tail.ANY_TAINT)
            root = FlowAlgebra.subtract(root, stored.root, FlowLeaf.NONE,
                at = { if (atOk) it else FlowLeaf.NONE },
                below = { if (belowOk) it else FlowLeaf.NONE },
                admits = stored.exclusion::admits,
                cancellation = m.cancellation) ?: return null
        }
        return if (root === t.root) t else t.withRoot(root)
    }
}

/** Construct a store result after its mask is proved to be included in root.
 * This is coordinate inclusion, not AP prefix coverage. General factories still trim. */
private fun admittedTree(
    m: ApManager, header: TaintTree, root: TaintNode, includedMask: TaintNode?,
    exclusion: ExclusionSet = header.exclusion,
): TaintTree = TaintTree(
    header.base, header.layer, root,
    if (!root.hasAny || header.anyTail == Tail.ANY) ExclusionSet.Empty else m.intern(exclusion),
    if (root.hasAny) header.anyTail else Tail.ANY_TAINT,
    includedMask,
)

/** TAINT values for one base. STAR and must spans keep distinct suffix semantics. */
class TaintGroup(private val m: ApManager, private val interner: TrieInterner<TaintLeaves>) {
    private val trees = arrayOf(ArrayList<TaintTree>(1), ArrayList<TaintTree>(1))

    fun all(): Sequence<TaintTree> = trees[0].asSequence() + trees[1].asSequence()

    /** Restore one complete current typed header for a temporary admission
     * adapter. Do not re-admit the snapshot: that would compact old STAR rows
     * merely because a later ANY row is already present. No history is kept. */
    internal fun restoreCurrent(t: TaintTree) {
        m.cancellation.checkpoint()
        val list = trees[t.layer.ordinal]
        check(list.none { it.anyTail == t.anyTail && it.exclusion == t.exclusion })
        list += t
    }

    fun add(t: TaintTree): TaintTree? = addAll(t).also {
        check(it.size <= 1) { "Canonical admission has multiple headers; use addAll" }
    }.singleOrNull()

    fun addAll(t: TaintTree): List<TaintTree> {
        m.cancellation.checkpoint()
        val before = trees[t.layer.ordinal]
        if (t.nonSubsumable != null || before.any { it.nonSubsumable != null })
            return addWithProtection(t, before)
        return addDataAll(t, before)
    }

    /** Preserve the existing incremental DATA order, including STAR/T4. */
    private fun addWithProtection(t: TaintTree, before: ArrayList<TaintTree>): List<TaintTree> {
        if (subtractSubsumed(t, before) == null) return emptyList()
        val temporary = TaintGroup(m, interner)
        before.forEach { temporary.restoreCurrent(it.withoutProtection()) }
        val dataChanges = temporary.addAll(t.withoutProtection())
        val after = m.embedRawProtection(temporary.all().toList(), before + t)
        val changes = LinkedHashMap<GroupKey, TaintTree>()
        fun add(value: TaintTree) {
            val old = changes[value.groupKey]
            changes[value.groupKey] = if (old == null) value else admittedTree(m, old,
                m.taintAlg.mergeAdd(old.root, value.root, m.cancellation),
                mergeProtection(old.nonSubsumable, value.nonSubsumable))
        }
        // Keep legacy whole-content T4 deltas, including their exact siblings.
        for (delta in dataChanges) for (current in retainCurrentFacts(m, delta, after))
            add(m.withCurrentProtection(current as TaintTree, after))
        for (value in after) {
            var fresh = value.nonSubsumable?.let { subtract(it, value, before, protectedOnly = true) } ?: continue
            fresh = subtract(fresh, value, changes.values.toList(), protectedOnly = true) ?: continue
            add(admittedTree(m, value, fresh, fresh))
        }
        m.cancellation.checkpoint()
        trees[t.layer.ordinal] = ArrayList(after.map {
            admittedTree(m, it, interner.internIfRequired(it.root), it.nonSubsumable)
        })
        return changes.values.toList()
    }

    private fun addDataAll(t: TaintTree, before: ArrayList<TaintTree>): List<TaintTree> {
        if (!t.root.hasAny || t.anyTail != Tail.ANY && t.anyTail != Tail.ANY_TAINT)
            return addInto(t,before)?.let(::listOf) ?: emptyList()
        if (before.isEmpty()) {
            val canonical = m.canonicalTaintPacket(t)
            val root = interner.internIfRequired(canonical.root)
            val stored = if (root === canonical.root) canonical
                else admittedTree(m,canonical,root,canonical.nonSubsumable)
            trees[t.layer.ordinal] = arrayListOf(stored)
            return listOf(stored)
        }
        // Ordinary and protected E provenance must remain separate until the
        // two streams are normalized. The old equal-root admission intersects
        // E before unioning masks and would broaden one-sided protection.
        if (subtractSubsumed(t,before) == null) return emptyList()
        val after = m.canonicalTaintState(before + t)
        val changes = ArrayList<TaintTree>()
        for (value in after) {
            val fresh = subtractSubsumed(value,before) ?: continue
            // Preserve T4's whole mixed-content delta only for an actual
            // equal-content E weakening; unrelated old exact siblings are not fresh.
            val wholeEJoin = before.any { old -> old.root.hasAny && old.root == t.root &&
                old.anyTail == t.anyTail && old.exclusion != t.exclusion &&
                value.anyTail == t.anyTail && value.root == t.root &&
                value.exclusion == old.exclusion.intersect(t.exclusion) && value.exclusion != old.exclusion }
            changes += if (wholeEJoin) value else fresh
        }
        m.cancellation.checkpoint()
        trees[t.layer.ordinal] = ArrayList(after.map {
            admittedTree(m,it,interner.internIfRequired(it.root),it.nonSubsumable)
        })
        return changes
    }

    private fun addInto(t: TaintTree, list: ArrayList<TaintTree>): TaintTree? {
        val alg = m.taintAlg
        var pending = t
        while (true) {
            m.cancellation.checkpoint()
            val sameKey = list.indexOfFirst {
                m.cancellation.checkpoint()
                it.anyTail == pending.anyTail && it.exclusion == pending.exclusion
            }
            if (sameKey < 0) {
                val k = list.indexOfFirst {
                    m.cancellation.checkpoint()
                    it.anyTail == pending.anyTail && it.root == pending.root
                }
                if (k >= 0) {
                    val stored = list[k]
                    val exclusion = stored.exclusion.intersect(pending.exclusion)
                    // Equal ordinary content can still carry a new protected membership.
                    if (exclusion == stored.exclusion) {
                        val rest = subtractSubsumed(pending, list) ?: return null
                        val protection = mergeProtection(stored.nonSubsumable, rest.nonSubsumable)
                        val root = alg.mergeAdd(stored.root, rest.root, m.cancellation)
                        list[k] = admittedTree(m, stored, interner.internIfRequired(root), protection)
                        return rest
                    }
                    list.removeAt(k)
                    pending = admittedTree(m, pending, stored.root,
                        mergeProtection(stored.nonSubsumable, pending.nonSubsumable), exclusion)
                    continue
                }
            }

            val rest = subtractSubsumed(pending, list) ?: return null
            // Subtraction can remove the last must leaf. Its canonical key is then Empty E.
            val i = list.indexOfFirst {
                m.cancellation.checkpoint()
                it.anyTail == rest.anyTail && it.exclusion == rest.exclusion
            }
            if (i < 0) {
                list += admittedTree(m, rest, interner.internIfRequired(rest.root), rest.nonSubsumable)
                return rest
            }
            val stored = list[i]
            val (merged, delta) = alg.mergeAddDelta(stored.root, rest.root, m.cancellation)
            val protection = mergeProtection(stored.nonSubsumable, rest.nonSubsumable)
            val deltaRoot = mergeProtection(delta, rest.nonSubsumable) ?: return null
            list[i] = admittedTree(m, stored, interner.internIfRequired(merged), protection)
            return admittedTree(m, rest, deltaRoot, rest.nonSubsumable)
        }
    }

    private fun subtractSubsumed(t: TaintTree, others: List<TaintTree>): TaintTree? {
        val ordinary = subtract(t.root, t, others, protectedOnly = false)
        // Ordinary ANY coverage cannot consume a fresh protected EXACT dependency.
        val protection = t.nonSubsumable?.let { subtract(it, t, others, protectedOnly = true) }
        val root = mergeProtection(ordinary, protection) ?: return null
        if (root === t.root && protection === t.nonSubsumable) return t
        return admittedTree(m, t, root, protection)
    }

    private fun mergeProtection(a: TaintNode?, b: TaintNode?): TaintNode? = when {
        a == null -> b
        b == null -> a
        else -> m.taintAlg.mergeAdd(a, b, m.cancellation)
    }

    private fun subtract(root: TaintNode, t: TaintTree, others: List<TaintTree>,
                         protectedOnly: Boolean): TaintNode? {
        val alg = m.taintAlg
        var remaining = root
        for (stored in others) {
            m.cancellation.checkpoint()
            val storedRoot = if (protectedOnly) stored.nonSubsumable ?: continue else stored.root
            if (protectedOnly) {
                val sameHeader = stored.anyTail == t.anyTail && stored.exclusion == t.exclusion
                remaining = alg.subtract(remaining, storedRoot, TaintLeaves.EMPTY,
                    at = { alg.leaves(it.exact, if (sameHeader) it.any else MarkSet.EMPTY) },
                    below = { TaintLeaves.EMPTY }, cancellation = m.cancellation) ?: return null
                continue
            }
            val storedMay = stored.anyTail == Tail.ANY
            val storedStar = stored.anyTail == Tail.STAR
            val coversAny = storedMay || stored.anyTail == t.anyTail
            val anyAt = coversAny && (storedMay || stored.exclusion.isSubsetOf(t.exclusion))
            remaining = alg.subtract(remaining, storedRoot, TaintLeaves.EMPTY,
                at = { alg.leaves(if (storedMay) it.exact + it.any else it.exact,
                    if (anyAt) it.any else MarkSet.EMPTY) },
                below = { alg.leaves(if (storedMay) it.any else MarkSet.EMPTY,
                    if (coversAny && !storedStar && !t.keepsDemandPositions()) it.any else MarkSet.EMPTY) },
                admits = stored.exclusion::admits,
                cancellation = m.cancellation) ?: return null
        }
        return remaining
    }
}

/** All conclusion bases and kinds for one premise key. REACH has one bit per layer. */
class ConclusionGroup(private val m: ApManager, private val interners: StoreInterners) {
    private val reach = BooleanArray(2)
    private val flow = HashMap<AccessPathBase, FlowGroup>(2)
    private val taint = HashMap<AccessPathBase, TaintGroup>(2)

    fun add(f: Facts): Facts? = addAll(f).also {
        check(it.size <= 1) { "Canonical admission has multiple headers; use addAll" }
    }.singleOrNull()

    fun addAll(f: Facts): List<Facts> {
        m.cancellation.checkpoint()
        return when (f) {
            is Reach -> if (reach[f.layer.ordinal]) emptyList() else listOf(f.also { reach[f.layer.ordinal] = true })
            is FlowTree -> flow.getOrPut(f.base) { FlowGroup(m, interners.flow) }.addAll(f)
            is TaintTree -> taint.getOrPut(f.base) { TaintGroup(m, interners.taint) }.addAll(f)
        }
    }

    fun retainCurrent(offered: Facts): List<Facts> = retainCurrentFacts(m,offered,all().asIterable())

    fun all(): Sequence<Facts> = Layer.entries.asSequence().filter { reach[it.ordinal] }.map(Reach::of) +
        flow.values.asSequence().flatMap { it.all() } + taint.values.asSequence().flatMap { it.all() }
}

/** Soft trie caches for one store, with a separate table for each leaf kind. */
class StoreInterners(refs: SoftReferenceManager, private val cancellation: Cancellation) {
    val flow = TrieInterner<FlowLeaf>(refs, cancellation)
    val taint = TrieInterner<TaintLeaves>(refs, cancellation)

    fun internIfRequired(f: Facts): Facts {
        cancellation.checkpoint()
        return when (f) {
            is Reach -> f
            is FlowTree -> flow.internIfRequired(f.root).let { if (it === f.root) f else f.withRoot(it) }
            is TaintTree -> taint.internIfRequired(f.root).let { if (it === f.root) f else f.withRoot(it) }
        }
    }
}

package org.opentaint.dataflow.bidi.ap

internal fun leafViews(m: ApManager, f: Facts): Sequence<Pattern> {
    m.cancellation.checkpoint()
    return when (f) {
        is Reach -> sequenceOf(m.zero.toPattern())
        is FlowTree -> buildList {
            FlowAlgebra.forEachLeaf(f.root, EMPTY_PATH, m.cancellation) { path, _ -> add(flowPattern(f, path)) }
        }.asSequence()
        is TaintTree -> buildList {
            m.taintAlg.forEachLeaf(f.root, EMPTY_PATH, m.cancellation) { path, leaf -> taintPatterns(f, path, leaf) { add(it) } }
        }.asSequence()
    }.map { pattern ->
        m.cancellation.checkpoint()
        pattern
    }
}

/** Walk to p once. Only an admitted non-exact leaf can overlap from above p. */
internal fun nearLeafViews(m: ApManager, f: Facts, p: IntArray): Sequence<Pattern> {
    m.cancellation.checkpoint()
    return when (f) {
        is Reach -> if (p.isEmpty()) leafViews(m, f) else emptySequence()
        is FlowTree -> buildList {
            val u = f.root.walk(p) { d, n ->
                m.cancellation.checkpoint()
                if (f.tail != Tail.EXACT && !n.leaf.isEmpty && f.exclusion.admits(p[d])) add(flowPattern(f, p.copyOf(d)))
            }
            u?.let { FlowAlgebra.forEachLeaf(it, p, m.cancellation) { path, _ -> add(flowPattern(f, path)) } }
        }.asSequence()
        is TaintTree -> buildList {
            val u = f.root.walk(p) { d, n ->
                m.cancellation.checkpoint()
                if (!n.leaf.any.isEmpty && f.exclusion.admits(p[d]))
                    taintPatterns(f, p.copyOf(d), m.taintLeaves(MarkSet.EMPTY, n.leaf.any)) { add(it) }
            }
            u?.let { m.taintAlg.forEachLeaf(it, p, m.cancellation) { path, leaf -> taintPatterns(f, path, leaf) { add(it) } } }
        }.asSequence()
    }.map { pattern ->
        m.cancellation.checkpoint()
        pattern
    }
}

private fun flowPattern(f: FlowTree, path: IntArray): Pattern = Pattern(
    PathFact(f.base, path.asList(), f.tail, MarkSlot.Star(f.markExclusion)),
    f.exclusion)

private inline fun taintPatterns(f: TaintTree, path: IntArray, leaf: TaintLeaves, add: (Pattern) -> Unit) {
    val anyTail = f.anyTail
    for (id in leaf.exact.data) add(Pattern(PathFact(f.base, path.asList(), Tail.EXACT, MarkSlot.Concrete(TaintMark(id))), ExclusionSet.Empty))
    for (id in leaf.any.data) add(Pattern(PathFact(f.base, path.asList(), anyTail, MarkSlot.Concrete(TaintMark(id))), f.exclusion))
}

package org.opentaint.dataflow.bidi.ap

import java.util.ArrayDeque
import java.util.IdentityHashMap

/** Cut before the next counted accessor after the positive public budget is exhausted. */
internal fun limitFacts(m: ApManager, c: Facts, fieldLimit: Int, out: ApOut) {
    require(fieldLimit >= 1) { "The field limit must be positive" }
    m.cancellation.checkpoint()
    when (c) {
        is Reach -> out.result(c)
        is FlowTree -> limitTrie(m, FlowAlgebra, c.root, fieldLimit,
            { out.result(if (it === c.root) c else c.withRoot(it)) },
            { out.result(m.flowTree(c.base, Layer.DEMAND, ExclusionSet.Empty, c.markExclusion, it)) })
        is TaintTree -> limitTrie(m, m.taintAlg, c.root, fieldLimit,
            { out.result(if (it === c.root) c else c.withRoot(it)) },
            { out.result(m.taintTree(c.base, Layer.DEMAND, it)) })
    }
}

private inline fun <P : TrieLeaf> limitTrie(
    m: ApManager, alg: LeafAlgebra<P>, root: TrieNode<P>, budget: Int,
    kept: (TrieNode<P>) -> Unit, cut: (TrieNode<P>) -> Unit,
) {
    if (root.boundedDepth <= budget) { kept(root); return }
    val (within, overflow) = FieldLimitCut(alg, m).keep(root, budget)
    m.cancellation.checkpoint()
    within?.let(kept)
    overflow?.let(cut)
}

/** A subtree can occur at different counted depths, so sharing is memoized by node identity and remaining budget. */
internal class FieldLimitCut<P : TrieLeaf>(private val alg: LeafAlgebra<P>, private val m: ApManager) {
    private val memo = HashMap<Int, IdentityHashMap<TrieNode<P>, Pair<TrieNode<P>?, TrieNode<P>?>>>()

    private class Frame<P : TrieLeaf>(val node: TrieNode<P>, val budget: Int, empty: P) {
        var next = 0
        var cutHere = empty
        val keptAccessors = ArrayList<Int>()
        val keptChildren = ArrayList<TrieNode<P>>()
        val cutAccessors = ArrayList<Int>()
        val cutChildren = ArrayList<TrieNode<P>>()
    }

    /** Both results are rooted at n. Zero is a valid internal remaining budget; class edges do not consume it. */
    fun keep(n: TrieNode<P>, budget: Int): Pair<TrieNode<P>?, TrieNode<P>?> {
        require(budget >= 0) { "The remaining field budget must be nonnegative" }
        m.cancellation.checkpoint()
        if (n.boundedDepth <= budget) return n to null
        memo[budget]?.get(n)?.let { return it }
        val stack = ArrayDeque<Frame<P>>()
        stack.addLast(Frame(n, budget, alg.empty))
        while (stack.isNotEmpty()) {
            m.cancellation.checkpoint()
            val frame = stack.peekLast()
            val accessors = frame.node.accessorData
            if (accessors != null && frame.next < accessors.size) {
                val accessor = accessors[frame.next]
                val child = frame.node.childData!![frame.next]
                val counted = accessor.isCounted()
                if (counted && frame.budget == 0) {
                    frame.cutHere = alg.union(frame.cutHere, alg.asAny(alg.foldAll(child, m.cancellation)))
                    frame.next++
                    continue
                }
                val childBudget = frame.budget - if (counted) 1 else 0
                val result = if (child.boundedDepth <= childBudget) child to null else memo[childBudget]?.get(child)
                if (result == null) {
                    stack.addLast(Frame(child, childBudget, alg.empty))
                    continue
                }
                result.first?.let {
                    frame.keptAccessors.add(accessor)
                    frame.keptChildren.add(it)
                }
                result.second?.let {
                    frame.cutAccessors.add(accessor)
                    frame.cutChildren.add(it)
                }
                frame.next++
                continue
            }
            val kept = alg.node(frame.node.leaf, frame.keptAccessors.toIntArray(), frame.keptChildren.toTypedArray())
                .takeIf { !it.isEmpty }
            val cut = alg.node(frame.cutHere, frame.cutAccessors.toIntArray(), frame.cutChildren.toTypedArray())
                .takeIf { !it.isEmpty }
            memo.getOrPut(frame.budget) { IdentityHashMap() }[frame.node] = kept to cut
            stack.removeLast()
        }
        return memo.getValue(budget).getValue(n)
    }
}

package org.opentaint.dataflow.bidi.ap

internal const val NOT_IDENTITY = -1
internal const val PLAIN_IDENTITY = 0
internal const val PROTECTED_IDENTITY = 1

/** Recognize the whole canonical image, including typed headers and protection.
 * This is literal equality at one coordinate, not semantic prefix coverage. */
internal fun ApManager.identityKind(initial: InitialAp, f: Facts): Int {
    cancellation.checkpoint()
    if (initial.isZero || f.base != initial.base || !sameCanonicalInitialImage(initial, f)) return NOT_IDENTITY
    if (f !is TaintTree || f.nonSubsumable == null) return PLAIN_IDENTITY
    return if (sameSingleCoordinate(initial, f.nonSubsumable)) PROTECTED_IDENTITY else NOT_IDENTITY
}

/** Do not allocate path snapshots, patterns or leaf lists on admission. */
private fun <P : TrieLeaf> ApManager.singleLeafAt(root: TrieNode<P>, path: IntArray): P? {
    var node = root
    for (accessor in path) {
        cancellation.checkpoint()
        if (!node.leaf.isEmpty) return null
        val edges = node.accessorData ?: return null
        if (edges.size != 1 || edges[0] != accessor) return null
        node = node.childData!![0]
    }
    if (node.accessorData != null || node.leaf.isEmpty) return null
    return node.leaf
}

private fun ApManager.sameSingleCoordinate(i: InitialAp, root: TaintNode): Boolean {
    val mark = (i.mark as? MarkSlot.Concrete)?.mark ?: return false
    val leaf = singleLeafAt(root, i.pathData) ?: return false
    return if (i.tail == Tail.EXACT)
        leaf.any.isEmpty && leaf.exact.size == 1 && mark in leaf.exact
    else leaf.exact.isEmpty && leaf.any.size == 1 && mark in leaf.any
}

private fun sameCanonicalHeader(i: InitialAp, f: Facts): Boolean = when (i.mark) {
    is MarkSlot.Star -> f is FlowTree && f.tail == i.tail && f.exclusion == i.exclusion && f.markExclusion.isEmpty
    is MarkSlot.Concrete -> f is TaintTree &&
        f.anyTail == (if (i.tail == Tail.EXACT) Tail.ANY_TAINT else i.tail) &&
        f.exclusion == (if (i.tail == Tail.EXACT || i.tail == Tail.ANY) ExclusionSet.Empty else i.exclusion)
}

private fun ApManager.sameCanonicalInitialImage(i: InitialAp, f: Facts): Boolean {
    if (!sameCanonicalHeader(i, f)) return false
    return when (f) {
        is FlowTree -> singleLeafAt(f.root, i.pathData) == FlowLeaf.LEAF
        is TaintTree -> sameSingleCoordinate(i, f.root)
        is Reach -> false
    }
}

/** Diagnostic classification is called only for an enabled first full admission. */
internal fun literalImageFallbackReason(initial: InitialAp?, f: Facts): String = when {
    initial == null -> "unsupported-premise"
    f.base != initial.base -> "different-base"
    !sameCanonicalHeader(initial, f) -> "different-typed-header"
    else -> "nonliteral-tree-or-mask"
}

/** Restore a stored image without applying normalization or a new abstraction. */
internal fun initialImage(m: ApManager, i: InitialAp, layer: Layer, isProtected: Boolean): Facts {
    m.cancellation.checkpoint()
    check(!i.isZero)
    return when (val slot = i.mark) {
        is MarkSlot.Star -> {
            check(!isProtected)
            val root = FlowAlgebra.prepend(m, i.path, FlowAlgebra.LEAF_NODE)
            m.flowTree(i.base, layer, i.exclusion, MarkExclusions.EMPTY, root, i.tail)
        }
        is MarkSlot.Concrete -> {
            val marks = m.markSetOf(slot.mark)
            val leaf = if (i.tail == Tail.EXACT) m.taintLeaves(marks, MarkSet.EMPTY)
                else m.taintLeaves(MarkSet.EMPTY, marks)
            val root = m.taintAlg.prepend(m, i.path, m.taintAlg.leafNode(leaf))
            m.taintTree(i.base, layer, root, i.exclusion,
                if (i.tail == Tail.EXACT) Tail.ANY_TAINT else i.tail,
                nonSubsumable = if (isProtected) root else null)
        }
    }
}

package org.opentaint.dataflow.bidi.ap

sealed interface MarkCheck {
    data object None : MarkCheck
    class Request(val mark: TaintMark) : MarkCheck
    class Holds(val facts: Facts) : MarkCheck
}

/** A literal selects full input leaves. A concrete accepted input keeps its layer. */
internal fun markCheckFacts(m: ApManager, c: Facts, p: Pattern, mode: ApMode,
                            unchangedStaticInitial: InitialAp? = null): MarkCheck {
    m.cancellation.checkpoint()
    check(unchangedStaticInitial == null || unchangedStaticInitial.manager === m) {
        "The ordinary static gate must use this AP manager"
    }
    val t = m.marks.runtimeAtom((p.fact.mark as MarkSlot.Concrete).mark, mode.markMode)
    if (c.base != p.fact.base) return MarkCheck.None
    val gate = MarkGate(m, p.fact.mark, p.fact.mark, mode)
    return when (c) {
        is Reach -> if (t == TaintMark.ZERO) MarkCheck.Holds(c) else MarkCheck.None
        is FlowTree -> {
            val unchanged = if (mode.run1 && mode.markMode == MarkMode.FULL) unchangedStaticFlowPath(c, unchangedStaticInitial) else null
            if (!flowRequests(m, c, p, unchanged)) return MarkCheck.None
            val request = gate.flowRequest(c.markExclusion) ?: return MarkCheck.None
            if (mode.run1) MarkCheck.Request(request) else MarkCheck.None
        }
        is TaintTree -> {
            val hit = taintOverlap(m, c.root, p, c.exclusion) ?: return MarkCheck.None
            val withT = m.taintAlg.mapLeaves(hit, m.cancellation) { leaf ->
                m.taintLeaves(gate.taintMarks(leaf.exact) ?: MarkSet.EMPTY,
                    gate.taintMarks(leaf.any) ?: MarkSet.EMPTY)
            } ?: return MarkCheck.None
            MarkCheck.Holds(m.taintTree(c.base, if (mode.markMode == MarkMode.GROUP) Layer.DEMAND else c.layer, withT, c.exclusion, c.anyTail))
        }
    }
}

/** Null preserves scalar behavior. A supplied initial certifies installed catalog coverage. */
internal fun unchangedStaticFlowPath(c: FlowTree, initial: InitialAp?): IntArray? {
    if (initial == null || initial.base != STATIC || c.base != STATIC || initial.tail != Tail.STAR ||
        initial.mark != MarkSlot.STAR || c.tail != Tail.STAR || c.exclusion != initial.exclusion ||
        !c.markExclusion.isEmpty) return null
    return initial.pathData
}

/** The path arrays are borrowed; this check creates no Pattern, Facts or AP node. */
internal fun sameFlowLeaf(m: ApManager, initial: IntArray?, prefix: IntArray, length: Int): Boolean {
    if (initial == null || initial.size != length) return false
    for (index in 0 until length) {
        if (index and 255 == 0) m.cancellation.checkpoint()
        if (initial[index] != prefix[index]) return false
    }
    return true
}

/** Is there a flag other than the started initial in this eligible subtree?
 *  Nonempty sibling branches prove a changed flag without enumerating the subtree. */
internal fun changedFlowSubtree(m: ApManager, root: FlowNode, prefix: IntArray,
                                initial: IntArray?): Boolean {
    if (root.isEmpty) return false
    if (initial == null || initial.size < prefix.size) return true
    for (index in prefix.indices) {
        if (index and 255 == 0) m.cancellation.checkpoint()
        if (initial[index] != prefix[index]) return true
    }
    var node = root
    for (index in prefix.size until initial.size) {
        m.cancellation.checkpoint()
        if (!node.leaf.isEmpty) return true
        val accessors = node.accessorData ?: return false
        if (accessors.size != 1 || accessors[0] != initial[index]) return true
        node = node.childData!![0]
    }
    return node.accessorData != null
}

private fun flowRequests(m: ApManager, c: FlowTree, p: Pattern, unchanged: IntArray?): Boolean {
    val path = p.fact.path.toIntArray()
    var hit = false
    val u = c.root.walk(path) { d, n ->
        m.cancellation.checkpoint()
        if (!n.leaf.isEmpty && c.exclusion.admits(path[d]) &&
            !sameFlowLeaf(m, unchanged, path, d)) hit = true
    }
    if (hit || u == null) return hit
    return if (p.fact.tail.isAny) changedFlowSubtree(m, u, path, unchanged)
        else !u.leaf.isEmpty && !sameFlowLeaf(m, unchanged, path, path.size)
}

private fun taintOverlap(m: ApManager, c: TaintNode, p: Pattern, e: ExclusionSet): TaintNode? {
    val path = p.fact.path.toIntArray()
    val spine = ArrayList<TaintLeaves>()
    val u = c.walk(path) { d, n ->
        m.cancellation.checkpoint()
        spine += if (e.admits(path[d])) m.taintLeaves(MarkSet.EMPTY, n.leaf.any) else TaintLeaves.EMPTY
    }
    val tip = u?.let { if (p.fact.tail.isAny) it else m.taintAlg.leafNode(it.leaf) }
    return m.taintAlg.chain(m, path, spine, tip)
}

internal fun withoutMarksPart(m: ApManager, c: Facts, marks: MarkSet): Facts? {
    m.cancellation.checkpoint()
    if (marks.isEmpty || c !is TaintTree) return c
    return m.taintAlg.mapLeaves(c.root, m.cancellation) {
        m.taintLeaves(it.exact - marks, it.any - marks)
    }?.let { if (it === c.root) c else c.withRoot(it) }
}

package org.opentaint.dataflow.bidi.ap

private enum class FullAtoms { UNKNOWN, ABSENT, PRESENT }

/** FLOW restrictions denote either an entire owner group or an exact full
 * mark. The atom IDs are private representation, never raw set semantics. */
class MarkExclusions private constructor(
    private val atoms: MarkSet,
    private val catalog: MarkTable?,
    private val fullAtoms: FullAtoms,
) {
    val isEmpty: Boolean get() = atoms.isEmpty
    val ids: IntArray get() = atoms.ids
    internal val data: IntArray get() = atoms.data
    fun withCatalog(table: MarkTable): MarkExclusions {
        require(catalog == null || catalog === table) { "Mixed mark catalogs in FLOW exclusions" }
        if (catalog === table) return this
        return normalized(atoms, table)
    }
    operator fun contains(mark: TaintMark): Boolean = excludes(mark, catalog)
    private fun excludes(mark: TaintMark, table: MarkTable?): Boolean {
        if (mark in atoms) return true
        if (mark == TaintMark.ZERO || table == null || table.isGroup(mark)) return false
        return atoms.data.any { id ->
            val atom = TaintMark(id)
            table.isGroup(atom) && table.groupOf(atom) == table.groupOf(mark)
        }
    }
    operator fun plus(mark: TaintMark): MarkExclusions {
        val combined = atoms + mark
        if (combined === atoms) return this
        return normalized(combined, catalog)
    }
    operator fun plus(other: MarkExclusions): MarkExclusions = union(other)
    operator fun plus(other: MarkSet): MarkExclusions = union(fromMarks(other))
    fun union(other: MarkExclusions): MarkExclusions {
        val table = tableWith(other)
        val combined = atoms + other.atoms
        if (combined === atoms && catalog === table) return this
        return normalized(combined, table)
    }
    fun intersect(other: MarkExclusions): MarkExclusions {
        val table = tableWith(other)
        val left = atoms.data.filter { other.excludes(TaintMark(it), table) }
        val right = other.atoms.data.filter { excludes(TaintMark(it), table) }
        return normalized(MarkSet((left + right).toIntArray()), table)
    }
    fun isSubsetOf(other: MarkExclusions): Boolean {
        val table = tableWith(other)
        return atoms.data.all { id ->
            val atom = TaintMark(id)
            // A finite list of full members does not cover a group, even if
            // it happens to contain the current catalog's complete population.
            if (table?.isGroup(atom) == true) atom in other.atoms else other.excludes(atom, table)
        }
    }
    fun filterMarks(marks: MarkSet): MarkSet = MarkSet(marks.data.filter { TaintMark(it) !in this }.toIntArray())
    fun projected(table: MarkTable, mode: MarkMode): MarkExclusions {
        if (mode == MarkMode.FULL) return withCatalog(table)
        if (isEmpty) return EMPTY
        if (catalog === table && fullAtoms == FullAtoms.ABSENT) return this
        return normalized(MarkSet(atoms.data.map { table.runtimeAtom(TaintMark(it), mode).id }.toIntArray()), table)
    }
    fun forEach(visit: (TaintMark) -> Unit) = atoms.data.forEach { visit(TaintMark(it)) }
    private fun tableWith(other: MarkExclusions): MarkTable? {
        require(catalog == null || other.catalog == null || catalog === other.catalog) { "Mixed mark catalogs" }
        return catalog ?: other.catalog
    }
    override fun equals(other: Any?): Boolean = other is MarkExclusions && atoms == other.atoms
    override fun hashCode(): Int = atoms.hashCode()
    override fun toString(): String = atoms.toString()
    companion object {
        val EMPTY = MarkExclusions(MarkSet.EMPTY, null, FullAtoms.ABSENT)
        fun fromMarks(marks: MarkSet, catalog: MarkTable? = null): MarkExclusions = normalized(marks, catalog)
        fun of(catalog: MarkTable, atom: TaintMark): MarkExclusions = fromMarks(MarkSet(intArrayOf(atom.id)), catalog)
        fun of(catalog: MarkTable, atoms: Iterable<TaintMark>): MarkExclusions =
            normalized(MarkSet(atoms.map { it.id }.toIntArray()), catalog)
        private fun normalized(atoms: MarkSet, catalog: MarkTable?): MarkExclusions {
            if (atoms.isEmpty) return EMPTY
            if (catalog == null) return MarkExclusions(atoms, null, FullAtoms.UNKNOWN)
            var groups: MutableSet<GroupId>? = null
            var fullAtoms = FullAtoms.ABSENT
            for (id in atoms.data) when (val key = catalog.key(TaintMark(id))) {
                MarkAtomKey.ControlZero -> Unit
                is MarkAtomKey.Group -> {
                    val present = groups ?: HashSet<GroupId>().also { groups = it }
                    present.add(key.id)
                }
                is MarkAtomKey.Full -> fullAtoms = FullAtoms.PRESENT
            }
            val presentGroups = groups ?: return MarkExclusions(atoms, catalog, fullAtoms)
            // Metadata describes retained atoms, not the input before GROUP shadowing.
            var retainedFull = FullAtoms.ABSENT
            val kept = atoms.data.filter { id ->
                when (val key = catalog.key(TaintMark(id))) {
                    MarkAtomKey.ControlZero, is MarkAtomKey.Group -> true
                    is MarkAtomKey.Full -> (key.mark.group !in presentGroups).also {
                        if (it) retainedFull = FullAtoms.PRESENT
                    }
                }
            }
            return MarkExclusions(MarkSet(kept.toIntArray()), catalog, retainedFull)
        }
    }
}

operator fun MarkSet.minus(excluded: MarkExclusions): MarkSet = excluded.filterMarks(this)

package org.opentaint.dataflow.bidi.ap

/** Cached primitive forms remain full. Only the execution view projects them. */
internal class MarkGate(private val m: ApManager, from: MarkSlot, to: MarkSlot,
                        private val mode: ApMode = ApMode(false, Direction.FORWARD, 1)) {
    val premise: MarkSlot = when (from) {
        is MarkSlot.Star -> from
        is MarkSlot.Concrete -> MarkSlot.Concrete(if (m.marks.isGroup(from.mark)) from.mark
            else m.marks.runtimeAtom(from.mark, mode.markMode))
    }
    val target: MarkSlot = when (to) {
        is MarkSlot.Star -> MarkSlot.Star(to.excluded.projected(m.marks, mode.markMode))
        is MarkSlot.Concrete -> MarkSlot.Concrete(m.marks.runtimeAtom(to.mark, mode.markMode))
    }
    init {
        check(premise !is MarkSlot.Star || premise.excluded.isEmpty) { "S7: a premise cannot exclude marks" }
        check(premise is MarkSlot.Concrete || target is MarkSlot.Star) { "S7: a selected target needs a selected premise" }
    }
    fun flowMarks(x: MarkExclusions): MarkExclusions? =
        if (premise is MarkSlot.Concrete) null else m.intern(x + (target as MarkSlot.Star).excluded)
    fun flowMarks(x: MarkSet): MarkExclusions? = flowMarks(MarkExclusions.fromMarks(x, m.marks))
    fun flowRequest(x: MarkSet): TaintMark? = flowRequest(MarkExclusions.fromMarks(x, m.marks))
    fun flowRequest(x: MarkExclusions): TaintMark? = (premise as? MarkSlot.Concrete)?.mark?.takeIf {
        mode.markMode == MarkMode.GROUP || it !in x
    }
    fun taintMarks(ms: MarkSet): MarkSet? {
        if (ms.isEmpty) return null
        val input = if (mode.markMode == MarkMode.GROUP) m.runtimeMarks(ms, mode) else ms
        val passed = when (premise) {
            is MarkSlot.Concrete -> m.intern(MarkSet(input.data.filter {
                m.marks.coversAtom(premise.mark, TaintMark(it))
            }.toIntArray())).takeIf { !it.isEmpty } ?: return null
            is MarkSlot.Star -> input
        }
        val result = when (target) {
            is MarkSlot.Concrete -> m.markSetOf(target.mark)
            is MarkSlot.Star -> m.intern(passed - target.excluded)
        }
        return result.takeIf { !it.isEmpty }
    }
}

package org.opentaint.dataflow.bidi.ap

/** Constructor provenance is transient and does not change stored AP or Record equality. */
enum class NativeReadKind { GENERIC, FLOW_MUST, CONCRETE_MUST }

data class NativeReadKey(val view: RecordLeafView, val mustOverlap: Boolean)

class NativeReverseRead internal constructor(
    val view: RecordLeafView,
    val kind: NativeReadKind,
    val sourceDirection: Direction,
    val sourcePremise: Pattern,
    val sourceConclusion: Conclusion,
) {
    val mayUseMustOverlap: Boolean = kind != NativeReadKind.GENERIC &&
        sourceConclusion.fact.tail == Tail.ANY_TAINT

    fun semanticKey(): NativeReadKey = NativeReadKey(view, mayUseMustOverlap)
}

/** Legacy matching first, then the newly selected same-path STAR overlap contribution.
 * Each packet retains its own header; the projection never changes the standing input. */
internal fun matchOppositeRecordPackets(ops: ApOps, actual: Facts, read: NativeReverseRead,
                                        mode: ApMode): List<Facts> {
    require(read.sourceDirection != mode.direction) { "A native inverse is read in the opposite direction" }
    val ap = ops.manager
    val result = ArrayList<Facts>(2)
    for (packet in ap.canonicalPackets(actual)) {
        ap.cancellation.checkpoint()
        ops.matchSummary(packet, read.view.premise, mode, nativeRecordRead = true,
            role = SummaryMatchRole.OPPOSITE_RECORD)?.let(result::add)
        if (!read.mayUseMustOverlap || read.view.premise.fact.tail != Tail.STAR) continue
        val query = read.view.premise
        if (packet.base != query.fact.base) continue
        val exclusion = when (packet) {
            is FlowTree -> packet.exclusion.takeIf { packet.tail == Tail.STAR }
            is TaintTree -> packet.exclusion.takeIf { packet.anyTail == Tail.STAR }
            is Reach -> null
        } ?: continue
        if (exclusion.isSubsetOf(query.exclusion) || query.exclusion.isSubsetOf(exclusion)) continue
        val path = query.fact.path.toIntArray()
        val projectedE = ap.intern(exclusion.union(query.exclusion))
        val projected = when (packet) {
            is FlowTree -> {
                val at = packet.root.walk(path) { _, _ -> ap.cancellation.checkpoint() }
                if (at == null || at.leaf.isEmpty) null else ap.flowTree(packet.base, packet.layer,
                    projectedE, packet.markExclusion,
                    FlowAlgebra.prepend(ap, ap.path(query.fact.path), FlowAlgebra.LEAF_NODE), Tail.STAR)
            }
            is TaintTree -> {
                val at = packet.root.walk(path) { _, _ -> ap.cancellation.checkpoint() }
                val marks = at?.leaf?.any
                if (marks == null || marks.isEmpty) null else retainProtection(packet,
                    ap.taintTree(packet.base, packet.layer,
                        ap.taintAlg.prepend(ap, ap.path(query.fact.path),
                            ap.taintAlg.leafNode(ap.taintLeaves(MarkSet.EMPTY, marks))), projectedE, Tail.STAR),
                    ap.cancellation)
            }
            is Reach -> null
        } ?: continue
        ops.matchSummary(projected, query, mode, nativeRecordRead = true,
            role = SummaryMatchRole.OPPOSITE_RECORD)?.let(result::add)
    }
    return result
}

package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.access.util.AccessorIdx

/** An immutable path cell. The manager interns the suffix before the parent. */
class PathNode internal constructor(
    @JvmField val accessor: AccessorIdx,
    @JvmField val next: PathNode?,
    internal val manager: ApManager,
) {
    init { check(accessor.isPathAccessor()) { "W5: $accessor is not a path accessor" } }

    @JvmField val size: Int = Math.addExact(1, next?.size ?: 0)
    @JvmField val counted: Int = Math.addExact(if (accessor.isCounted()) 1 else 0, next?.counted ?: 0)
    private val hash: Int = accessor + 17 * (next?.hashCode() ?: 0)

    override fun equals(other: Any?): Boolean = this === other ||
        (other is PathNode && accessor == other.accessor && next === other.next)
    override fun hashCode(): Int = hash

    fun toIntArray(): IntArray {
        val result = IntArray(size)
        var node: PathNode? = this
        var index = 0
        while (node != null) {
            result[index++] = node.accessor
            node = node.next
        }
        return result
    }

    fun toList(): List<AccessorIdx> = toIntArray().asList()
}

package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.access.util.AccessorIdx

/** Visit each proper prefix before looking up its next child. */
inline fun <N : Any> walkPath(
    root: N,
    path: IntArray,
    child: (N, AccessorIdx) -> N?,
    onPrefix: (Int, N) -> Unit = { _, _ -> },
): N? {
    var node = root
    for (depth in path.indices) {
        onPrefix(depth, node)
        node = child(node, path[depth]) ?: return null
    }
    return node
}

inline fun <P : TrieLeaf> TrieNode<P>.walk(
    path: IntArray,
    onPrefix: (Int, TrieNode<P>) -> Unit = { _, _ -> },
): TrieNode<P>? = walkPath(this, path, { node, accessor -> node.child(accessor) }, onPrefix)

package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.ap.ifds.MethodEntryPoint

typealias MethodKey = MethodEntryPoint

sealed interface PremiseKey {
    val size: Int
    fun member(k: Int): InitialAp
    val isZero: Boolean
    val nonZeroCount: Int
}

val PremiseKey.members: List<InitialAp> get() = List(size, ::member)
inline fun PremiseKey.forEachMember(body: (InitialAp) -> Unit) {
    for (index in 0 until size) body(member(index))
}
val PremiseKey.isFlow: Boolean get() = this is InitialAp && mark is MarkSlot.Star

/** Equality is identity after interning. Mode-specific must checks belong to the run. */
class InitialAp internal constructor(
    val base: AccessPathBase,
    val path: PathNode?,
    val tail: Tail,
    val exclusion: ExclusionSet,
    val mark: MarkSlot,
    @JvmField val id: Int,
    @JvmField internal val manager: ApManager,
) : PremiseKey {
    init {
        check(base !is AccessPathBase.CleanerTemporary) { "A field-action temporary cannot be a premise" }
        check(mark !is MarkSlot.Star || mark.excluded.isEmpty) { "A premise cannot exclude marks" }
        check(tail == Tail.STAR || tail == Tail.ANY_TAINT || exclusion == ExclusionSet.Empty) {
            "Only a STAR or must premise can exclude fields"
        }
        check(base != AccessPathBase.Zero || (path == null && tail == Tail.EXACT &&
            exclusion == ExclusionSet.Empty && mark == MarkSlot.Concrete(TaintMark.ZERO))) {
            "The zero base has only the canonical zero fact"
        }
    }

    internal val pathData: IntArray = path?.toIntArray() ?: EMPTY_PATH
    val pathArray: IntArray get() = pathData.copyOf()
    override val size: Int get() = 1
    override fun member(k: Int): InitialAp = also { check(k == 0) }
    override val isZero: Boolean get() = base == AccessPathBase.Zero
    override val nonZeroCount: Int get() = if (isZero) 0 else 1
    fun toPattern(): Pattern = Pattern(PathFact(base, pathArray.asList(), tail, mark), exclusion)
}

class PremiseSet internal constructor(members: Array<InitialAp>) : PremiseKey {
    private val data = members.copyOf()
    val members: Array<InitialAp> get() = data.copyOf()

    init {
        check(data.size >= 2)
        check(data.none { it.isZero }) { "A multiple-member premise cannot include zero" }
        check(data.all { it.mark is MarkSlot.Concrete }) { "Every multiple-member premise must be concrete" }
        check((1 until data.size).all { data[it - 1].id < data[it].id }) {
            "Premise members must be sorted and unique"
        }
    }

    override val size: Int get() = data.size
    override fun member(k: Int): InitialAp = data[k]
    override val isZero: Boolean get() = false
    override val nonZeroCount: Int get() = data.size
}

package org.opentaint.dataflow.bidi.ap


/** Combine original inputs only after the existing complete condition has been admitted. */
fun interface PremiseCombination {
    fun combine(inputs: Iterable<PremiseKey>): PremiseKey
}

/** Later runs keep the complete canonical conjunction. The shared AP manager has no run mode. */
class ExactPremises(private val manager: ApManager) : PremiseCombination {
    override fun combine(inputs: Iterable<PremiseKey>): PremiseKey {
        var result: PremiseKey = manager.zero
        var present = false
        for (input in inputs) {
            manager.cancellation.checkpoint()
            result = manager.union(result, input)
            present = true
        }
        check(present) { "A complete condition needs at least one input" }
        return result
    }
}

package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.ap.ifds.Accessor
import org.opentaint.dataflow.ap.ifds.FactTypeChecker

enum class CleanReach { EXACT, BELOW, AT_AND_BELOW }

/** A cleaner targets one program value, optionally for one mark. */
class Cleaner(val base: AccessPathBase, val path: PathNode?, val reach: CleanReach, val mark: TaintMark?) {
    init {
        check(base != AccessPathBase.Zero) { "S11: a cleaner cannot target zero" }
        require(mark != null || reach == CleanReach.AT_AND_BELOW) { "RemoveAll requires the whole position" }
    }
    @JvmField internal val pathArray: IntArray = path?.toIntArray() ?: EMPTY_PATH
}

/** The mark policy of interpreter.md §5.1 (`markPolicyKeeps`): it reads a concrete mark on the value of the base itself
 *  (`elements = 0`) or on the value at `[e]^k` below the base (`elements = k`: the k-th element type), as today. It is NOT
 *  a may-predicate: it reads the mark, not the path, and it can drop a real flow (outside ap.md S5; gap G6). Part II
 *  builds it from the static type t: `MarkPolicy { mark, k -> the type at level k is not primitive or boxed, or
 *  isPrimitiveTracking(mark) }`; null if no level of t is primitive or boxed. */
fun interface MarkPolicy { fun keeps(mark: TaintMark, elements: Int): Boolean }

/** ap.md §4.8: the primitive `filter(b, may)`; `may` is prefix-closed (S5). The base is the key of
 *  StatementSummary.typeFilters (and resultFilters, Part II §23.2). Part II builds `may` with JIRFactTypeChecker (REUSE of
 *  its FactApFilter). `markPolicy` is the policy of the same static type and of its element types, or null (DD9). */
class TypeFilter(val may: FactTypeChecker.FactApFilter, val markPolicy: MarkPolicy? = null) {
    /** interpreter.md §5.1: two filters on one base are a conjunction. */
    fun and(o: TypeFilter): TypeFilter = TypeFilter(AndFilter(may, o.may), when {
        markPolicy == null -> o.markPolicy
        o.markPolicy == null -> markPolicy
        else -> MarkPolicy { t, k -> markPolicy.keeps(t, k) && o.markPolicy.keeps(t, k) }
    })

    private class AndFilter(val a: FactTypeChecker.FactApFilter, val b: FactTypeChecker.FactApFilter) : FactTypeChecker.FactApFilter {
        override fun check(accessor: Accessor): FactTypeChecker.FilterResult {
            val x = a.check(accessor)
            val y = b.check(accessor)
            return when {
                x === FactTypeChecker.FilterResult.Reject || y === FactTypeChecker.FilterResult.Reject -> FactTypeChecker.FilterResult.Reject
                x === FactTypeChecker.FilterResult.Accept -> y                                   // Accept and r: r
                y === FactTypeChecker.FilterResult.Accept -> x
                else -> FactTypeChecker.FilterResult.FilterNext(                               // both FilterNext: the conjunction below
                    AndFilter((x as FactTypeChecker.FilterResult.FilterNext).filter, (y as FactTypeChecker.FilterResult.FilterNext).filter))
            }
        }
    }
}


class ConjunctiveEdge(val literals: List<Pattern>, val target: PathFact) {
    init {
        check(literals.size >= 2)
        check(literals.all { it.fact.mark is MarkSlot.Concrete && (it.fact.tail == Tail.EXACT || it.fact.tail == Tail.ANY) })
        check(target.mark is MarkSlot.Concrete && (target.tail == Tail.EXACT || target.tail == Tail.ANY_TAINT))   // W7, I14
        check(target.base != AccessPathBase.Zero)                       // so targetTree(target, layer) is a TaintTree
    }
}

package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.ap.ifds.access.util.AccessorIdx

/** Scalar reference geometry for ordinary and FLOW query tails. */
data class PathFact(val base: AccessPathBase, val path: List<AccessorIdx>, val tail: Tail, val mark: MarkSlot)
data class Pattern(val fact: PathFact, val exclusion: ExclusionSet)

data class Conclusion(val fact: PathFact, val exclusion: ExclusionSet, val demand: Boolean) {
    init {
        check(fact.tail != Tail.ANY || demand) { "W6: a may conclusion must be DEMAND" }
        check(exclusion == ExclusionSet.Empty || fact.tail == Tail.STAR || fact.tail == Tail.ANY_TAINT ||
            (fact.tail == Tail.EXACT && fact.mark is MarkSlot.Star)) {
            "Only a STAR or must conclusion can exclude fields"
        }
    }
}


fun <T> List<T>.startsWith(p: List<T>): Boolean = size >= p.size && subList(0, p.size) == p

val STATIC: AccessPathBase = AccessPathBase.ClassStatic



data class DemandPattern(val entry: Pattern, val exit: Pattern?)

fun tailAdmits(tail: Tail, exclusion: ExclusionSet, r: List<AccessorIdx>): Boolean = when (tail) {
    Tail.STAR, Tail.ANY_TAINT -> exclusion.admits(r)   // r = [] or the first accessor of r is not excluded
    Tail.ANY -> true
    Tail.EXACT -> r.isEmpty()
}
fun Pattern.tailAdmits(r: List<AccessorIdx>) = tailAdmits(fact.tail, exclusion, r)

fun markSub(i: MarkSlot, c: MarkSlot, catalog: MarkTable? = null): Boolean = when (i) {
    is MarkSlot.Star -> when (c) {
        is MarkSlot.Star -> i.excluded.isSubsetOf(c.excluded)   // *∖X ⊇ *∖Y if and only if X ⊆ Y; * ⊇ every abstract mark
        is MarkSlot.Concrete -> c.mark !in i.excluded
    }
    is MarkSlot.Concrete -> c is MarkSlot.Concrete && (catalog?.coversAtom(i.mark, c.mark) ?: (c.mark == i.mark))
}

private fun tailSub(i: Pattern, c: Pattern): Boolean = when (i.fact.tail) {
    Tail.ANY -> true
    Tail.EXACT -> c.fact.tail == Tail.EXACT
    Tail.STAR, Tail.ANY_TAINT -> when (c.fact.tail) {       // the exclusion of i must exclude only what c excludes
        Tail.EXACT -> true
        Tail.ANY -> i.exclusion == ExclusionSet.Empty
        Tail.STAR, Tail.ANY_TAINT -> i.exclusion.isSubsetOf(c.exclusion)
    }
}

fun covers(i: Pattern, c: Pattern, catalog: MarkTable? = null): Boolean {
    if (i.fact.base != c.fact.base || !markSub(i.fact.mark, c.fact.mark, catalog)) return false
    val p = i.fact.path
    val q = c.fact.path
    if (!q.startsWith(p)) return false
    return if (q.size == p.size) tailSub(i, c) else i.tailAdmits(q.drop(p.size))
}

fun overlap(a: Pattern, b: Pattern): Boolean {
    if (a.fact.base != b.fact.base) return false
    val p = a.fact.path
    val q = b.fact.path
    return when {
        q.startsWith(p) -> a.tailAdmits(q.drop(p.size))
        p.startsWith(q) -> b.tailAdmits(p.drop(q.size))
        else -> false
    }
}

fun applicable(j: Pattern, a: Pattern, catalog: MarkTable? = null): Boolean =
    covers(j, a, catalog) && (!j.fact.tail.isAny || a.fact.tail.isAny)

fun inside(j: Pattern, a: Pattern, catalog: MarkTable? = null): Boolean =
    covers(a.copy(fact = a.fact.copy(mark = MarkSlot.Star(MarkSet.EMPTY))), j, catalog) && markSub(j.fact.mark, a.fact.mark, catalog)

/** Transient native-record read. Never emitted, started, interned as an InitialAp, or persisted. */
data class RecordLeafView(val premise: Pattern, val result: Conclusion)

fun summaryEdge(j: Pattern, g: Conclusion): PathEdge {
    val jOwn = j.fact.tail == Tail.ANY_TAINT
    val gOwn = g.fact.tail == Tail.ANY_TAINT
    return PathEdge(j.fact, g.fact,
        (if (jOwn) ExclusionSet.Empty else j.exclusion).union(if (gOwn) ExclusionSet.Empty else g.exclusion),
        fromExclusion = if (jOwn) j.exclusion else ExclusionSet.Empty,
        toExclusion = if (gOwn) g.exclusion else ExclusionSet.Empty)
}

/** Concrete native must views retain their existing policy. New FLOW must views always return an ANY demand. */
private fun mustRecordReadView(p: Pattern, g: Conclusion): NativeReverseRead? {
    if (!g.demand && p.fact.mark is MarkSlot.Star && g.fact.mark is MarkSlot.Star &&
        ((p.fact.tail == Tail.ANY_TAINT && g.fact.tail in setOf(Tail.STAR, Tail.ANY_TAINT)) ||
            (p.fact.tail == Tail.STAR && g.fact.tail == Tail.ANY_TAINT))) {
        return NativeReverseRead(RecordLeafView(Pattern(g.fact.copy(tail = Tail.STAR, mark = p.fact.mark), g.exclusion),
            Conclusion(p.fact.copy(tail = Tail.ANY, mark = g.fact.mark), ExclusionSet.Empty, demand = true)),
            NativeReadKind.FLOW_MUST, Direction.FORWARD, p, g)
    }
    val concrete = p.fact.mark is MarkSlot.Concrete && g.fact.mark is MarkSlot.Concrete
    val accepted = !g.demand && concrete && when (p.fact.tail) {
        Tail.EXACT -> p.exclusion == ExclusionSet.Empty && g.fact.tail == Tail.ANY_TAINT
        Tail.ANY_TAINT -> g.fact.tail == Tail.ANY_TAINT ||
            (g.fact.tail == Tail.EXACT && g.exclusion == ExclusionSet.Empty)
        else -> false
    }
    if (!accepted) return null
    val readPremise = if (g.fact.tail == Tail.ANY_TAINT)
        Pattern(g.fact.copy(tail = Tail.STAR), g.exclusion)          // retain the old conclusion E and concrete mark
    else Pattern(g.fact, ExclusionSet.Empty)                        // exact conclusion stays exact
    val demand = p.fact.tail == Tail.ANY_TAINT
    val resultFact = if (demand) p.fact.copy(tail = Tail.ANY) else p.fact
    return NativeReverseRead(RecordLeafView(readPremise, Conclusion(resultFact, ExclusionSet.Empty, demand)),
        NativeReadKind.CONCRETE_MUST, Direction.FORWARD, p, g)   // forget old must-input E
}

/** Raw normal singleton record only. CurrentSimplifications.MustViews.readView_factored_equiv checks the accepted
 *  must constructor. Retain generic micro-edge revEdge and its fallback guards for every other native shape. */
fun reverseNativeRecordLeaf(direction: Direction, p: Pattern, g: Conclusion): NativeReverseRead? {
    if (g.demand) return null
    if (p.exclusion != ExclusionSet.Empty && p.fact.tail != Tail.STAR && p.fact.tail != Tail.ANY_TAINT) return null
    if (direction == Direction.BACKWARD && (p.fact.tail == Tail.ANY_TAINT || g.fact.tail == Tail.ANY_TAINT)) return null
    if (direction == Direction.FORWARD) mustRecordReadView(p, g)?.let { return it }
    if (p.fact.tail == Tail.ANY_TAINT) return null                   // no unsupported native must-input fallback
    if (p.fact.tail == Tail.STAR && p.fact.mark is MarkSlot.Concrete) return null   // invalid native normal shape
    val rev = revEdge(summaryEdge(p, g)) ?: return null
    return NativeReverseRead(RecordLeafView(Pattern(rev.from, ExclusionSet.Empty),
        Conclusion(rev.to, rev.exclusion, demand = rev.to.tail == Tail.ANY)), NativeReadKind.GENERIC, direction, p, g)
}

/** Geometry-only native reference API. Production matching also retains constructor provenance. */
fun reverseRecordLeaf(direction: Direction, p: Pattern, g: Conclusion): RecordLeafView? =
    reverseNativeRecordLeaf(direction, p, g)?.view

/** Identity classification without starting a transient premise. Concrete STAR readers are effects. */
fun recordLeafIdentity(v: RecordLeafView): Boolean = !v.result.demand && v.premise.fact.base != AccessPathBase.Zero &&
    (v.premise.fact.tail == Tail.EXACT || (v.premise.fact.tail == Tail.STAR && v.premise.fact.mark is MarkSlot.Star)) &&
    v.result.fact == v.premise.fact && v.result.exclusion == v.premise.exclusion


fun meet(a: Pattern, d: Pattern): Pair<Tail, ExclusionSet> {
    return when {
        a.fact.tail == Tail.ANY_TAINT && d.fact.tail == Tail.STAR ->
            Tail.ANY_TAINT to a.exclusion.union(d.exclusion)
        a.fact.tail.isAny && d.fact.tail.isAny -> a.fact.tail to a.exclusion
        a.fact.tail.isAny -> d.fact.tail to d.exclusion
        d.fact.tail.isAny -> a.fact.tail to a.exclusion
        a.fact.tail == Tail.EXACT || d.fact.tail == Tail.EXACT -> Tail.EXACT to ExclusionSet.Empty
        else -> Tail.STAR to a.exclusion.union(d.exclusion)
    }
}

/** Demand-only widening. Actual facts, native records and concrete demand retain field E. */
fun normalizeDemandFieldExclusion(pattern: Pattern): Pattern =
    if (pattern.fact.mark is MarkSlot.Star && pattern.fact.tail == Tail.STAR &&
        pattern.exclusion != ExclusionSet.Empty) pattern.copy(exclusion = ExclusionSet.Empty)
    else pattern

/** Scalar table view, including forward uniform templates. The engine passes its run policy explicitly. */
fun emit(d: Pattern, a: Pattern, catalog: MarkTable? = null): Pattern? =
    RestrictedInitialPolicy(direction = Direction.FORWARD, catalog = catalog).emit(d, a)

fun flowForm(d: Pattern): Pattern {
    val star = MarkSlot.Star(MarkSet.EMPTY)
    return if (d.fact.tail == Tail.ANY) Pattern(d.fact.copy(tail = Tail.STAR, mark = star), ExclusionSet.Empty)
    else Pattern(d.fact.copy(mark = star), d.exclusion)                // `STAR/E` keeps E
}

fun commonPart(d: Pattern, a: Pattern, catalog: MarkTable? = null): Pattern? {
    if (d.fact.base != a.fact.base) return null
    // a T demand needs the mark T: an abstract `a` gives nothing ("the added fact can't satisfy the demand", F72);
    // `*` admits every mark (Lean: markMatchB; with no `*∖X` pattern it is markSub)
    if (!markSub(d.fact.mark, a.fact.mark, catalog)) return null
    val p = d.fact.path
    val q = a.fact.path
    return when {
        q.size > p.size && q.startsWith(p) ->                                   // below: the fact itself
            if (d.tailAdmits(q.drop(p.size))) a else null
        q == p -> {                                                              // at: the meet of the tails
            val (tail, excl) = meet(a, d)
            Pattern(a.fact.copy(tail = tail), excl)
        }
        p.startsWith(q) ->                                    // above: the demand chain, the meet of the tails
            if (a.tailAdmits(p.drop(q.size))) {
                // E excludes first accessors at q. After the admitted descent to p it has no effect there.
                // Keep the demand's own E at p, including the MUST/STAR and correlated STAR cells.
                val (tail, excl) = meet(a.copy(exclusion = ExclusionSet.Empty), d)
                Pattern(d.fact.copy(tail = tail, mark = a.fact.mark), excl)
            } else null
        else -> null
    }
}

fun satisfies(j: Pattern, a: Pattern, restricted: Boolean): Boolean {
    if (j.fact.tail == Tail.ANY_TAINT && j.fact.mark is MarkSlot.Star)
        return a.fact.tail == Tail.ANY_TAINT && markSub(j.fact.mark, a.fact.mark) &&
            covers(a.copy(fact = a.fact.copy(mark = MarkSlot.STAR)), j.copy(fact = j.fact.copy(mark = MarkSlot.STAR)))
    return if (!restricted) applicable(j, a) || inside(j, a)
    else if (j.fact.tail == Tail.STAR && j.exclusion == ExclusionSet.Empty && j.fact.mark == MarkSlot.STAR)
        overlap(j, a)
    else inside(j, a) || ((j.fact.mark == MarkSlot.STAR || j.fact.tail == Tail.STAR) && applicable(j, a))
}

fun recordDemand(j: Pattern, a: Pattern, resultDemand: Boolean): Boolean =
    resultDemand || (j.fact.tail == Tail.ANY_TAINT && !inside(j, a))
fun insideLoc(j: Pattern, d: Pattern): Boolean {
    val star = MarkSlot.Star(MarkSet.EMPTY)
    return covers(d.copy(fact = d.fact.copy(mark = star)), j.copy(fact = j.fact.copy(mark = star)))
}

fun insideDemand(j: Pattern, d: Pattern, catalog: MarkTable? = null): Boolean {
    val entry = normalizeDemandFieldExclusion(d)
    return insideLoc(j, entry) && markSub(entry.fact.mark, j.fact.mark, catalog)
}

fun marksMeet(dp: MarkSlot, c: MarkSlot, catalog: MarkTable? = null): Boolean = when {
    dp is MarkSlot.Concrete && c is MarkSlot.Concrete -> (catalog?.let { it.coversAtom(dp.mark, c.mark) || it.coversAtom(c.mark, dp.mark) } ?: (dp.mark == c.mark))
    dp is MarkSlot.Concrete -> dp.mark !in (c as MarkSlot.Star).excluded      // an abstract conclusion stays as it is
    c is MarkSlot.Concrete -> c.mark !in (dp as MarkSlot.Star).excluded
    else -> true
}

fun meetConclusion(sc: Conclusion, dp: Pattern): Conclusion = when {
    !sc.fact.tail.isAny -> sc                                     // `$`; `*` stays whole (a FLOW conclusion, F72)
    dp.fact.tail == Tail.EXACT -> sc.copy(fact = sc.fact.copy(tail = Tail.EXACT),
        exclusion = if (sc.fact.mark is MarkSlot.Star && sc.fact.tail == Tail.ANY_TAINT) sc.exclusion else ExclusionSet.Empty)
    sc.fact.tail == Tail.ANY_TAINT && dp.fact.tail == Tail.STAR -> sc.copy(exclusion = sc.exclusion.union(dp.exclusion))
    else -> sc                                                    // `[any] ∩ STAR/E2` (the exception), `∩ [any]`
}

fun restrict(sp: Pattern, sc: Conclusion, d: DemandPattern, catalog: MarkTable? = null,
             policy: RestrictedInitialPolicy = RestrictedInitialPolicy(direction = Direction.FORWARD, catalog = catalog)): Conclusion? {
    if (!policy.canStoreInitial(d.entry, sp)) return null
    return restrictConclusionOnly(sc, d.exit, catalog)
}

fun restrictConclusionOnly(sc: Conclusion, exit: Pattern?, catalog: MarkTable? = null): Conclusion? {
    val dp = normalizeDemandFieldExclusion(exit ?: return null)
    if (!marksMeet(dp.fact.mark, sc.fact.mark, catalog)) return null  // the mark of the conclusion meets the mark of D-p
    if (sc.fact.base != dp.fact.base) return null
    val p = dp.fact.path
    val q = sc.fact.path
    return when {
        q == p -> meetConclusion(sc, dp)                                         // at D-p: the meet
        q.startsWith(p) -> if (dp.tailAdmits(q.drop(p.size))) sc else null     // below D-p: keeps E
        p.startsWith(q) -> when (sc.fact.tail) {                                // above D-p
            Tail.ANY, Tail.ANY_TAINT ->
                if (!sc.exclusion.admits(p.drop(q.size))) null                   // E of `[any-taint]/E` (W8)
                else if (dp.fact.tail == Tail.EXACT)                             // the chain of D-p, the layer stays
                    sc.copy(fact = sc.fact.copy(path = p, tail = Tail.EXACT), exclusion = ExclusionSet.Empty)
                else sc.copy(fact = sc.fact.copy(path = p),
                    exclusion = if (sc.fact.tail == Tail.ANY_TAINT && dp.fact.tail == Tail.STAR) dp.exclusion
                                else ExclusionSet.Empty)                         // [any-taint]/E2 under STAR/E2 (W8)
            Tail.STAR -> if (sc.exclusion.admits(p.drop(q.size))) sc else null   // a FLOW conclusion (F72)
            else -> null                                                         // `$`: no common location
        }
        else -> null
    }
}

data class PathEdge(val from: PathFact, val to: PathFact, val exclusion: ExclusionSet,
                    val fromExclusion: ExclusionSet = ExclusionSet.Empty,     // Ej of a must-premise (a summary, a record)
                    val toExclusion: ExclusionSet = ExclusionSet.Empty) {     // Et of an `[any-taint]/Et` summary conclusion
    @Volatile internal var compiled: CompiledEdge? = null
}

private fun PathEdge.premiseAdmits(r: List<AccessorIdx>): Boolean = when (from.tail) {
    Tail.EXACT -> r.isEmpty()
    Tail.ANY_TAINT -> fromExclusion.admits(r)   // a must-premise: Ej
    else -> exclusion.admits(r)        // `*`: E; `[any]`: E is Empty unless the target is `*` (row 1)
}

private class Shape(val path: List<AccessorIdx>, val tail: Tail, val exclusion: ExclusionSet, val demand: Boolean)

private fun below(c: Conclusion, edge: PathEdge, r: List<AccessorIdx>): Shape? {
    if (!edge.premiseAdmits(r)) return null
    val to = edge.to
    if (to.tail == Tail.STAR && r.isNotEmpty() && !edge.exclusion.admits(r)) return null
    return when (to.tail) {
        Tail.STAR -> when {
            r.isNotEmpty() -> Shape(to.path + r, c.fact.tail, c.exclusion, demand = false)   // keeps Ec (W8)
            c.fact.tail == Tail.EXACT -> Shape(to.path, Tail.EXACT,
                if (c.fact.mark is MarkSlot.Star) c.exclusion.union(edge.exclusion) else ExclusionSet.Empty, false)
            c.fact.tail == Tail.ANY -> Shape(to.path, Tail.ANY, ExclusionSet.Empty, demand = true)   // W6
            else -> Shape(to.path, c.fact.tail, c.exclusion.union(edge.exclusion), false)  // `STAR/Ec`, or the exclusion
        }                                                                                 // edge on `[any-taint]/Ec` (W8)
        Tail.ANY -> Shape(to.path, Tail.ANY, ExclusionSet.Empty, demand = true)               // W6: a may
        Tail.ANY_TAINT, Tail.EXACT -> Shape(to.path, to.tail,                                  // a must, or `$`
            if (to.tail == Tail.ANY_TAINT) edge.toExclusion else ExclusionSet.Empty,           // Et (W8)
            demand = false)        // W2 and the concrete premise gate reject STAR input; geometry still precedes that gate
    }
}

private fun PathEdge.isExcludedIdentityKeep(): Boolean =
    from.base == to.base && from.path == to.path && from.tail == Tail.STAR &&
        to.tail == Tail.STAR && exclusion != ExclusionSet.Empty

private fun above(c: Conclusion, edge: PathEdge, r: List<AccessorIdx>): Shape? {
    val admitted = when (c.fact.tail) {
        Tail.STAR, Tail.ANY_TAINT -> c.exclusion.admits(r); Tail.ANY -> true; Tail.EXACT -> false
    }
    if (!admitted) {
        // An excluded identity keep is the existing field-write effect, not a read.
        if (c.fact.tail == Tail.EXACT && c.fact.mark is MarkSlot.Star && edge.isExcludedIdentityKeep() && c.exclusion.admits(r))
            return Shape(edge.to.path, Tail.ANY, ExclusionSet.Empty, demand = true)
        return null
    }
    val to = edge.to
    if (c.fact.tail != Tail.ANY_TAINT) {           // a `*` fact loses its correlation; an `[any]` fact is demand (W6)
        val tail = if (to.tail == Tail.EXACT) Tail.EXACT else Tail.ANY
        return Shape(to.path, tail, ExclusionSet.Empty, demand = true)
    }
    return when (to.tail) {                        // every admitted location of c carries its mark: nothing is lost
        Tail.EXACT -> Shape(to.path, Tail.EXACT,
            if (c.fact.mark is MarkSlot.Star && r.isEmpty()) c.exclusion else ExclusionSet.Empty, demand = false)
        Tail.ANY_TAINT -> Shape(to.path, Tail.ANY_TAINT, edge.toExclusion, demand = false)    // Et
        Tail.ANY -> Shape(to.path, Tail.ANY, ExclusionSet.Empty, demand = true)               // W6: a may
        Tail.STAR -> Shape(to.path, Tail.ANY_TAINT, edge.exclusion, demand = false)          // the edge exclusion (W8)
    }
}

sealed interface EdgeOutcome {
    data object None : EdgeOutcome
    data class Fact(val conclusion: Conclusion) : EdgeOutcome
    data class Request(val mark: TaintMark) : EdgeOutcome                  // run 1 only (§4.5)
    data class PositionRequest(val path: List<AccessorIdx>) : EdgeOutcome     // run 1 only (§4.10 item 1)
}

fun rootOrClass(q: List<AccessorIdx>): Boolean = q.isEmpty() || (q.size == 1 && q[0].isClass())

fun concat(c: Conclusion, edge: PathEdge, edgeDemand: Boolean = false,
           staticIdentity: Boolean = false, restricted: Boolean = false, run1: Boolean = false): EdgeOutcome {
    val from = edge.from
    check(from.mark !is MarkSlot.Star || from.mark.excluded.isEmpty)          // S7
    check(edge.to.mark !is MarkSlot.Concrete || from.mark is MarkSlot.Concrete)          // S7
    check(from.tail != Tail.EXACT || edge.to.tail != Tail.STAR || from.mark is MarkSlot.Star)
    check(edge.to.tail != Tail.ANY_TAINT || edge.to.mark is MarkSlot.Concrete || from.mark is MarkSlot.Star)
    if (c.fact.base != from.base) return EdgeOutcome.None
    val p = from.path
    val q = c.fact.path
    val isAbove = p.size > q.size && p.startsWith(q)
    val shape = when {
        q.startsWith(p) -> below(c, edge, q.drop(p.size))
        isAbove -> above(c, edge, p.drop(q.size))
        else -> null
    } ?: return EdgeOutcome.None
    if (staticIdentity && from.base == STATIC && isAbove && rootOrClass(q)) {   // the static exception (§4.10)
        check(!restricted)
        return EdgeOutcome.PositionRequest(p.take(2))                          // cut to the static field or class
    }
    val premiseMark = from.mark
    if (premiseMark is MarkSlot.Concrete) {                                   // step 4: the mark gate
        when (val cm = c.fact.mark) {
            is MarkSlot.Concrete -> if (cm.mark != premiseMark.mark) return EdgeOutcome.None
            is MarkSlot.Star -> {
                if (premiseMark.mark in cm.excluded) return EdgeOutcome.None
                if (restricted) return EdgeOutcome.None                       // F72: no request after run 1 (§4.5)
                return EdgeOutcome.Request(premiseMark.mark)
            }
        }
    }
    val mark = compose(edge.to.mark, c.fact.mark) ?: return EdgeOutcome.None  // step 5
    val cover = run1 && shape.exclusion != ExclusionSet.Empty
    return EdgeOutcome.Fact(normalize(PathFact(edge.to.base, shape.path, shape.tail, mark),
        if (cover) ExclusionSet.Empty else shape.exclusion, c.demand || edgeDemand || shape.demand || cover))
}

fun compose(to: MarkSlot, c: MarkSlot): MarkSlot? = when (to) {
    is MarkSlot.Concrete -> to
    is MarkSlot.Star -> when (c) {
        is MarkSlot.Star -> MarkSlot.Star(to.excluded + c.excluded)
        is MarkSlot.Concrete -> if (c.mark in to.excluded) null else c
    }
}

fun normalize(f: PathFact, exclusion: ExclusionSet, demand: Boolean): Conclusion = when {
    demand && f.mark is MarkSlot.Star && (f.tail == Tail.EXACT || f.tail == Tail.ANY_TAINT) ->
        Conclusion(f.copy(tail = Tail.ANY), ExclusionSet.Empty, demand = true)
    f.tail == Tail.ANY -> Conclusion(f, ExclusionSet.Empty, demand = true)                                  // W6
    f.tail == Tail.ANY_TAINT -> {
        Conclusion(f, exclusion, demand)
    }
    else -> Conclusion(f, if (f.tail == Tail.EXACT && f.mark is MarkSlot.Concrete) ExclusionSet.Empty else exclusion, demand)
}

/** ap.md §6.5 (Lean startFact; a must-premise: AnyTaint.startT, with the exclusion AnyTaintEx.startX). No direction
 *  parameter: a must-premise occurs only in a forward restricted run (A1), and no other row reads the run. */
fun startFact(i: Pattern): Conclusion = when (i.fact.tail) {
    Tail.STAR -> Conclusion(i.fact, i.exclusion, demand = i.fact.mark is MarkSlot.Concrete)
    Tail.ANY -> Conclusion(i.fact, ExclusionSet.Empty, demand = true)
    Tail.ANY_TAINT -> Conclusion(i.fact, i.exclusion, demand = false)                // a must-premise: itself, normal
    Tail.EXACT -> Conclusion(i.fact, ExclusionSet.Empty, demand = false)
}

/** ap.md §4.4 (Lean cutPath, limitF; with the exclusion AnyTaintEx.limitFX). An `[any-taint]/E` fact over the limit
 *  becomes `[any]` in the demand layer and loses E (W8, A2). */
fun limit(c: Conclusion, fieldLimit: Int): Conclusion {
    require(fieldLimit >= 1) { "The field limit must be positive" }
    var n = 0
    for ((k, a) in c.fact.path.withIndex())
        if (a.isCounted() && ++n > fieldLimit)
            return Conclusion(c.fact.copy(path = c.fact.path.take(k), tail = Tail.ANY), ExclusionSet.Empty, demand = true)
    return c
}

enum class Pos { INSIDE, DISJOINT, PART }

/** ap.md §4.7 (Lean cleanPos; with the exclusion AnyTaintEx.cleanPosX: a cleaner strictly below an `[any-taint]/E` fact
 *  through an accessor in E is `disjoint`). The tree form is cleanPosAt (Part I §5.6). */
fun cleanPos(cl: Cleaner, c: PathFact, exclusion: ExclusionSet): Pos {
    if (c.base != cl.base) return Pos.DISJOINT
    val p = cl.path?.toList().orEmpty()
    val q = c.path
    return when {
        q.size > p.size && q.startsWith(p) -> if (cl.reach == CleanReach.EXACT) Pos.DISJOINT else Pos.INSIDE
        q == p -> when {
            cl.reach == CleanReach.AT_AND_BELOW -> Pos.INSIDE
            c.tail == Tail.EXACT -> if (cl.reach == CleanReach.EXACT) Pos.INSIDE else Pos.DISJOINT
            else -> Pos.PART
        }
        p.startsWith(q) -> when (c.tail) {
            Tail.EXACT -> Pos.DISJOINT
            Tail.STAR, Tail.ANY, Tail.ANY_TAINT ->                                  // `[any]`: the Empty exclusion admits
                if (exclusion.admits(p.drop(q.size))) Pos.PART else Pos.DISJOINT
        }
        else -> Pos.DISJOINT
    }
}

class CleanOut(val facts: List<Conclusion>, val request: TaintMark?)

/** ap.md §4.7, F75 selected-mark split (BaseCleaner.cleanRes); concrete/all-marks rows keep concPart. */
fun cleanRes(cl: Cleaner, c: Conclusion, run1: Boolean = false): CleanOut {
    val raw = if (run1 && c.fact.base == STATIC && cl.base == STATIC &&
        c.fact.mark is MarkSlot.Star && cl.mark != null && cleanPos(cl, c.fact, c.exclusion) == Pos.DISJOINT)
        CleanOut(listOf(c), null) else cleanResRaw(cl, c)
    return if (!run1) raw else CleanOut(raw.facts.map { value ->
        if (value.exclusion == ExclusionSet.Empty) value
        else value.copy(exclusion = ExclusionSet.Empty, demand = true)
    }, raw.request)
}

private fun cleanResRaw(cl: Cleaner, c: Conclusion): CleanOut {
    if (c.fact.base != cl.base) return CleanOut(listOf(c), null)
    val abstractMark = c.fact.mark as? MarkSlot.Star
    val selected = cl.mark
    if (abstractMark != null && selected != null)
        return CleanOut(listOf(c.copy(fact = c.fact.copy(mark = MarkSlot.Star(abstractMark.excluded + selected)))), selected)
        // The caller records this request only in run 1. Do not test the path or T ∈ X first.
    if (abstractMark != null && selected == null) {
        return CleanOut(wholeFlowClean(cl, c), null)
    }
    val pos = cleanPos(cl, c.fact, c.exclusion)
    if (pos == Pos.DISJOINT) return CleanOut(listOf(c), null)
    return when (val mk = c.fact.mark) {
        is MarkSlot.Concrete ->
            if (cl.mark != null && cl.mark != mk.mark) CleanOut(listOf(c), null)                  // T' not cleaned
            else if (pos == Pos.INSIDE) CleanOut(emptyList(), null)
            else CleanOut(concPart(cl, c), null)                                                  // one or two facts (A2)
        is MarkSlot.Star -> {
            check(cl.mark == null)                                               // selected mark handled before cleanPos
            CleanOut(if (pos == Pos.INSIDE) emptyList() else listOf(normalize(c.fact, c.exclusion, demand = true)), null)
        }
    }
}

/** Whole-position FLOW kill. Retain one uncertain inner residual, which covers deeper ones. */
internal fun wholeFlowClean(cl: Cleaner, c: Conclusion): List<Conclusion> {
    val path = cl.path?.toList().orEmpty()
    val q = c.fact.path
    if (q.startsWith(path)) return emptyList()
    if (!path.startsWith(q) || !c.exclusion.admits(path.drop(q.size))) return listOf(c)
    if (c.fact.tail == Tail.ANY) return listOf(c)
    val result = ArrayList<Conclusion>()
    result += c.copy(exclusion = c.exclusion.union(ExclusionSet.of(path[q.size])))
    if (q.size + 1 < path.size) {
        if (c.fact.tail == Tail.ANY_TAINT) {
            for (depth in q.size + 1 until path.size)
                result += c.copy(fact = c.fact.copy(path = path.take(depth)), exclusion = ExclusionSet.of(path[depth]))
        } else result += c.copy(fact = c.fact.copy(path = path.take(q.size + 1), tail = Tail.ANY),
            exclusion = ExclusionSet.Empty, demand = true)
    }
    return result
}

/** ap.md §4.7 (Lean concPart; with the exclusion AnyTaintEx.partX): a normal `[any-taint]/E` fact at x.p and a cleaner ONE
 *  accessor below it, at x.p.f: `atAndBelow` gives the fact with `E ∪ {f}`, `below` gives it and `(x, p.f, $, T)`, in
 *  the layer of c (A2). An any-tail fact at x.p under a `below` cleaner AT x.p keeps `(x, p, $, T)` in its layer. Any
 *  other `part` result (the `exact` cleaner one accessor below too) goes to the demand layer: an `[any-taint]` fact as
 *  `[any]`, with no exclusion (W8). */
fun concPart(cl: Cleaner, c: Conclusion): List<Conclusion> {
    val p = cl.path?.toList().orEmpty()
    val q = c.fact.path
    if (c.fact.tail == Tail.ANY_TAINT && p.size == q.size + 1 && p.startsWith(q) && cl.reach != CleanReach.EXACT) {
        val kept = c.copy(exclusion = c.exclusion.union(ExclusionSet.of(p.last())))          // `[any-taint]/(E ∪ {f})`
        return if (cl.reach == CleanReach.AT_AND_BELOW) listOf(kept)
               else listOf(kept, c.copy(fact = c.fact.copy(path = p, tail = Tail.EXACT), exclusion = ExclusionSet.Empty))   // + x.p.f.$
    }
    return listOf(
        if ((c.fact.tail.isAny || c.fact.tail == Tail.STAR) && cl.reach == CleanReach.BELOW && q == p)
            c.copy(fact = c.fact.copy(tail = Tail.EXACT), exclusion = ExclusionSet.Empty)   // in the layer of c
        else c.copy(demand = true))
}

sealed interface CheckResult { data object None : CheckResult; data object Holds : CheckResult; data class Request(val mark: TaintMark) : CheckResult }

/** ap.md §4.9 and §4.6 (Lean `check`, `ND.DN.conj`; renamed: `check` is the Kotlin assert): the check of one mark literal `s`
 *  on one fact. The tree form is ApOps.checkMark (Part I §5.8). The §11.2 difference: the effective-mark case is asserted away. */
fun markCheck(i: Pattern, f: Conclusion, s: Pattern, restricted: Boolean = false): CheckResult {
    val t = (s.fact.mark as MarkSlot.Concrete).mark
    if (!overlap(Pattern(f.fact, f.exclusion), s)) return CheckResult.None
    return when (val mk = f.fact.mark) {
        is MarkSlot.Concrete -> if (mk.mark == t) CheckResult.Holds else CheckResult.None
        is MarkSlot.Star -> if (restricted || t in mk.excluded) CheckResult.None
                            else { check(i.fact.mark is MarkSlot.Star); CheckResult.Request(t) }
    }
}

/** ap.md §4.6 (Lean ND.conjLayer; with the `[any-taint]` rule AnyTaintND.conjLayerT): the layer of one input of a literal
 *  that holds on it. Demand if the input is in the demand layer, or if the literal does not cover it and it is not
 *  `[any-taint]` (a normal `[any-taint]` input that overlaps its literal and passes its mark gate keeps the result
 *  normal: every location of it carries the mark, AnyTaintND.lit_loc). The overlap of `markCheck` reads the exclusion of
 *  an `[any-taint]/E` input (A2), so an input in the excluded part never reaches here.
 *  For the legal matched TAINT literal shapes, CurrentProposal.LiteralLayer proves this equals f.demand. */
fun conjDemand(f: Conclusion, lit: Pattern): Boolean =
    f.demand || (!covers(lit, Pattern(f.fact, f.exclusion)) && f.fact.tail != Tail.ANY_TAINT)

/** ap.md §4.5 chain answer (Lean answerInit) and §4.10 item 4 (Lean Statics.SCtx.ansInit). Precondition: a overlaps i, a.mark = t.
 *  Run 1 has no must-premise (W8 (c)): an `[any-taint]/E` `a` gives the static mark answer with the tail `[any]` and no
 *  exclusion (a larger premise, demand: sound). */
fun answer(i: Pattern, a: Pattern, t: TaintMark): Pattern = when {
    i.fact.base == STATIC && a.fact.path.startsWith(i.fact.path) ->          // a at or below a static premise: a itself
        if (a.fact.tail == Tail.ANY_TAINT) Pattern(a.fact.copy(mark = MarkSlot.Concrete(t), tail = Tail.ANY), ExclusionSet.Empty)   // `[any]`: no E
        else Pattern(a.fact.copy(mark = MarkSlot.Concrete(t)), a.exclusion)
    a.fact.tail == Tail.EXACT && a.fact.path == i.fact.path ->
        Pattern(PathFact(i.fact.base, i.fact.path, Tail.EXACT, MarkSlot.Concrete(t)), ExclusionSet.Empty)
    else -> Pattern(i.fact.copy(mark = MarkSlot.Concrete(t)), i.exclusion)   // the request chain and kind, mark t
}

/** ap.md §6.2 (Lean policy1). */
fun policy(a: Pattern): Pattern =
    if (a.fact.base == AccessPathBase.Zero) a
    else Pattern(PathFact(a.fact.base, emptyList(), Tail.STAR, MarkSlot.STAR), ExclusionSet.Empty)

/** Generic micro-edge reversal (Lean revEdge, revKinds, MarkRev), unchanged by record read views.
 *  It rejects a must premise and a must conclusion with nonempty exclusion; reverseRecordLeaf handles the supported
 *  native forward must shapes separately (§7.8). A forward must micro target still reverses to ordinary ANY.
 *  MicroEdge.may reads the forward target for pass-rule demand handling. */
fun revEdge(e: PathEdge): PathEdge? {
    if (e.from.tail == Tail.ANY_TAINT) return null                          // generic reversal only
    if (e.to.tail == Tail.ANY_TAINT && (e.toExclusion != ExclusionSet.Empty || e.exclusion != ExclusionSet.Empty))
        return null                                                         // generic reversal only
    val fAbstract = e.to.mark is MarkSlot.Star
    if (!fAbstract && e.from.mark !is MarkSlot.Concrete) return null       // no_rev_of_star_conc
    val (pt, ct) = revTails(e.from.tail, e.to.tail)
    val pm = if (fAbstract) e.from.mark else e.to.mark                     // the new premise never has `*∖X`
    val cm = if (fAbstract) e.to.mark else e.from.mark
    val excl = if (pt == Tail.STAR || ct == Tail.STAR) e.exclusion else ExclusionSet.Empty   // the exclusion goes to the new conclusion (W1)
    return PathEdge(PathFact(e.to.base, e.to.path, pt, pm), PathFact(e.from.base, e.from.path, ct, cm), excl)
}

fun revTails(i: Tail, f: Tail): Pair<Tail, Tail> = when (i) {             // the table of §9.1
    Tail.STAR -> when (f) {
        Tail.STAR -> Tail.STAR to Tail.STAR; Tail.EXACT -> Tail.EXACT to Tail.ANY; Tail.ANY -> Tail.ANY to Tail.ANY
        Tail.ANY_TAINT -> error("S15: a taint edge has an EXACT or ANY premise; a `*` premise has no `[any-taint]` conclusion")
    }
    Tail.ANY -> when (f) {
        Tail.STAR -> Tail.STAR to Tail.STAR; Tail.EXACT -> Tail.EXACT to Tail.ANY; Tail.ANY -> Tail.ANY to Tail.ANY
        Tail.ANY_TAINT -> Tail.ANY to Tail.ANY                               // a conditional source with an `[any]` literal (A1)
    }
    Tail.EXACT -> when (f) {
        Tail.STAR -> Tail.EXACT to Tail.EXACT; Tail.EXACT -> Tail.EXACT to Tail.EXACT; Tail.ANY -> Tail.ANY to Tail.EXACT
        Tail.ANY_TAINT -> Tail.ANY to Tail.EXACT                              // a source result: the premise `[any]` (A1)
    }
    Tail.ANY_TAINT -> error("generic revTails has no must-premise row")   // reverseRecordLeaf handles native must views
}

/** ap.md §8.1 (Subsume.subsumesB, markSubsB): s subsumes n inside one layer. FlowGroup and TaintGroup are its tree form.
 *  An `[any]` s (demand) subsumes every fact at or below its path with its mark. An `[any-taint]/Es` s (normal)
 *  subsumes, with its mark, in its layer, ONLY `[any-taint]` facts: an `[any-taint]/En` fact at its path if `Es ⊆ En`,
 *  and one strictly below its path through an accessor that `Es` admits (A2; argued, ap.md §11.2); NEVER a `$` fact
 *  (DD16, ap-history.md F69: a later demoting cleaner row moves s to the demand layer, and the `$` fact stays normal). */
fun subsumes(s: Conclusion, n: Conclusion): Boolean {
    if (s.fact.base != n.fact.base || s.demand != n.demand || !markSubsumes(s.fact.mark, n.fact.mark)) return false
    return when (s.fact.tail) {
        Tail.ANY -> n.fact.path.startsWith(s.fact.path)
        Tail.ANY_TAINT -> n.fact.tail == Tail.ANY_TAINT && n.fact.path.startsWith(s.fact.path) &&
            if (n.fact.path.size == s.fact.path.size) s.exclusion.isSubsetOf(n.exclusion)
            else s.exclusion.admits(n.fact.path[s.fact.path.size])
        Tail.STAR -> n.fact.tail == Tail.STAR && s.fact.path == n.fact.path && s.exclusion.isSubsetOf(n.exclusion)
        Tail.EXACT -> n.fact.tail == Tail.EXACT && s.fact.path == n.fact.path
    }
}
fun markSubsumes(s: MarkSlot, n: MarkSlot): Boolean = when (s) {
    is MarkSlot.Concrete -> n == s
    is MarkSlot.Star -> n is MarkSlot.Star && s.excluded.isSubsetOf(n.excluded)
}

/** R1 publishes normal singleton summaries except backward zero summaries. */
fun r1Eligible(premise: PremiseKey, g: Conclusion, direction: Direction): Boolean =
    !g.demand && premise is InitialAp && !(direction == Direction.BACKWARD && premise.isZero)

/** F77 selects demand edges by structure, before any transient read-view conversion. */
fun demandSelected(premise: PremiseKey, g: Conclusion, direction: Direction): Boolean =
    g.demand || premise.size > 1 || (direction == Direction.BACKWARD && premise.isZero)

package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.bidi.store.CallerRef

/** Pure scalar-oracle vocabulary. Runtime events, services and AP outputs do not accept this type. */
sealed interface ReferenceRequestKind {
    data class Mark(val mark: TaintMark) : ReferenceRequestKind
    data class Position(val path: PathNode) : ReferenceRequestKind
}

/** One result of the historical scalar join, used by reference closure and protocol tests only. */
sealed interface ReferenceRequestAction {
    class Answer(val initial: InitialAp) : ReferenceRequestAction
    class Climb(val premise: InitialAp, val request: ReferenceRequestKind) : ReferenceRequestAction
    data object None : ReferenceRequestAction
}

/** The oracle caller first enforces geometric overlap. This function does not send or admit work. */
fun referenceRequestAction(m: ApManager, i: InitialAp, kind: ReferenceRequestKind,
                           a: Pattern, caller: CallerRef): ReferenceRequestAction {
    m.cancellation.checkpoint()
    check(i.tail == Tail.STAR && i.exclusion == ExclusionSet.Empty && i.mark == MarkSlot.STAR) {
        "A reference request needs a policy initial or position answer"
    }
    return when (kind) {
        is ReferenceRequestKind.Mark -> when (val mark = a.fact.mark) {
            is MarkSlot.Concrete -> if (mark.mark == kind.mark)
                ReferenceRequestAction.Answer(m.initial(answer(i.toPattern(), a, kind.mark)))
            else ReferenceRequestAction.None
            is MarkSlot.Star -> if (kind.mark in mark.excluded) ReferenceRequestAction.None
            else ReferenceRequestAction.Climb(caller.premise as InitialAp, kind)
        }
        is ReferenceRequestKind.Position -> when {
            a.fact.path.startsWith(kind.path.toList()) -> ReferenceRequestAction.Answer(
                m.initial(STATIC, kind.path, Tail.STAR, ExclusionSet.Empty, MarkSlot.STAR))
            (caller.premise as? InitialAp)?.base == STATIC ->
                ReferenceRequestAction.Climb(caller.premise as InitialAp, kind)
            else -> ReferenceRequestAction.None
        }
    }
}

package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.ap.ifds.access.util.AccessorInterner.Companion.isFieldAccessor

/** One run's pure C2 policy. Image tests inspect templates; they never intern hypothetical facts. */
class RestrictedInitialPolicy(
    val run: Int = 2,
    val fieldLimit: Int = Int.MAX_VALUE,
    val direction: Direction = if (run % 2 == 0) Direction.BACKWARD else Direction.FORWARD,
    private val catalog: MarkTable? = null,
) {
    init { require(run >= 2 && fieldLimit >= 1) }

    fun emit(demand: Pattern, actual: Pattern): Pattern? {
        if (!validDemand(demand)) return null
        val d = normalizeDemandFieldExclusion(demand)
        if (d.fact.base != actual.fact.base || !markSub(d.fact.mark, actual.fact.mark, catalog)) return null
        if (d.fact.base == AccessPathBase.Zero && !canonicalZero(actual)) return null
        if (!fitsBudget(d) || !fitsBudget(actual)) return null
        // Only a concrete MAY witness can supply a provisional exact data point.
        if (d.fact.tail == Tail.EXACT && actual.fact.tail == Tail.ANY && d.fact.mark is MarkSlot.Star) return null
        val p = d.fact.path
        val q = actual.fact.path
        val mark = boundMark(d.fact.mark, actual.fact.mark)
        fun result(path: List<Int>, tail: Tail, e: ExclusionSet = ExclusionSet.Empty): Pattern? {
            val value = Pattern(PathFact(d.fact.base, path, tail, mark), e)
            return value.takeIf(::legalInitial)
        }
        if (q == p) return when (d.fact.tail) {
            Tail.ANY -> when (actual.fact.tail) {
                Tail.STAR -> null
                Tail.EXACT -> result(p, Tail.EXACT)
                Tail.ANY -> result(p, Tail.ANY)
                Tail.ANY_TAINT -> result(p, Tail.ANY_TAINT, actual.exclusion)
            }
            Tail.STAR, Tail.EXACT -> result(p, Tail.EXACT)
            Tail.ANY_TAINT -> null // A demand entry never has a MUST tail.
        }
        if (q.startsWith(p)) {
            if (!d.tailAdmits(q.drop(p.size))) return null
            return when (d.fact.tail) {
                Tail.STAR -> if (run == 2) result(p, Tail.STAR, d.exclusion) else null
                Tail.ANY -> {
                    val end = firstFieldEnd(d.fact.base, p, q) ?: return null
                    val tail = if (mark is MarkSlot.Concrete && actual.fact.tail == Tail.EXACT && end == q.size)
                        Tail.EXACT else Tail.STAR
                    result(q.take(end), tail)
                }
                else -> null
            }
        }
        if (p.startsWith(q) && actual.tailAdmits(p.drop(q.size))) return when (d.fact.tail) {
            Tail.ANY -> when (actual.fact.tail) {
                Tail.ANY -> result(p, Tail.ANY)
                Tail.ANY_TAINT -> result(p, Tail.ANY_TAINT, d.exclusion)
                else -> null
            }
            Tail.STAR, Tail.EXACT -> result(p, Tail.EXACT)
            Tail.ANY_TAINT -> null
        }
        return null
    }

    /** Preserve concrete support without interning an AP. Actuals are legal ApOps.leaves views:
     * exact concrete leaves have Empty E even in a mixed tree; MAY headers also have Empty E. */
    fun emitAdmission(demand: Pattern, actual: Pattern, actualLayer: Layer): InitialEmission? {
        val emitted = emit(demand, actual) ?: return null
        return InitialEmission(emitted, admissionLayer(emitted, actual, actualLayer))
    }

    /** Complete structural output image, including the non-idempotent run-2 requested STAR. */
    fun canEmitInitial(demand: Pattern, initial: Pattern): Boolean {
        if (!validDemand(demand)) return false
        val d = normalizeDemandFieldExclusion(demand)
        if (!legalInitial(initial) || !fitsBudget(d) || d.fact.base != initial.fact.base ||
            !renderedMark(d.fact.mark, initial.fact.mark)) return false
        val p = d.fact.path
        val q = initial.fact.path
        if (q == p) return when (initial.fact.tail) {
            Tail.EXACT -> initial.exclusion == ExclusionSet.Empty && d.fact.tail != Tail.ANY_TAINT
            Tail.ANY -> d.fact.tail == Tail.ANY && initial.exclusion == ExclusionSet.Empty
            Tail.ANY_TAINT -> d.fact.tail == Tail.ANY
            Tail.STAR -> run == 2 && d.fact.tail == Tail.STAR && initial.exclusion == d.exclusion &&
                p.count { it.isCounted() } < fieldLimit &&
                !(initial.fact.base == STATIC && p.size == 1)
        }
        if (d.fact.tail != Tail.ANY || !q.startsWith(p) || !d.tailAdmits(q.drop(p.size))) return false
        val end = firstFieldEnd(d.fact.base, p, q) ?: return false
        return end == q.size && initial.exclusion == ExclusionSet.Empty &&
            (initial.fact.tail == Tail.STAR || initial.fact.tail == Tail.EXACT && initial.fact.mark is MarkSlot.Concrete)
    }

    /** Summary keys are normalized, but the containment test belongs to their raw preimage. */
    fun canStoreInitial(entry: Pattern, stored: Pattern): Boolean {
        if (!validDemand(entry)) return false
        fun fits(raw: Pattern): Boolean = canEmitInitial(entry, raw) && insideDemand(raw, entry, catalog)
        if (fits(stored)) return true
        return stored.fact.mark is MarkSlot.Star && stored.fact.tail == Tail.STAR &&
            stored.exclusion == ExclusionSet.Empty && fits(stored.copy(fact = stored.fact.copy(tail = Tail.EXACT)))
    }

    private fun boundMark(required: MarkSlot, actual: MarkSlot): MarkSlot =
        if (required is MarkSlot.Concrete && catalog?.isGroup(required.mark) == true &&
            actual is MarkSlot.Concrete) actual else required

    private fun renderedMark(required: MarkSlot, rendered: MarkSlot): Boolean =
        if (required is MarkSlot.Star) rendered == required
        else rendered is MarkSlot.Concrete && markSub(required, rendered, catalog)

    private fun fitsBudget(p: Pattern): Boolean = p.fact.path.count { it.isCounted() } <= fieldLimit

    private fun validDemand(p: Pattern): Boolean =
        !(p.fact.tail == Tail.EXACT && p.fact.mark is MarkSlot.Concrete && p.exclusion != ExclusionSet.Empty) &&
            (p.fact.base != AccessPathBase.Zero || canonicalZero(p))

    private fun canonicalZero(p: Pattern): Boolean = p.fact.path.isEmpty() && p.fact.tail == Tail.EXACT &&
        p.exclusion == ExclusionSet.Empty && p.fact.mark == MarkSlot.Concrete(TaintMark.ZERO)

    private fun legalInitial(p: Pattern): Boolean {
        if (!fitsBudget(p) || p.fact.tail == Tail.ANY_TAINT && direction == Direction.BACKWARD) return false
        if (p.fact.mark is MarkSlot.Concrete && catalog?.isGroup(p.fact.mark.mark) == true) return false
        if (p.fact.tail != Tail.STAR && p.fact.tail != Tail.ANY_TAINT && p.exclusion != ExclusionSet.Empty) return false
        if (p.fact.mark is MarkSlot.Star && !p.fact.mark.excluded.isEmpty) return false
        if (p.fact.base == AccessPathBase.Zero) return p.fact.path.isEmpty() && p.fact.tail == Tail.EXACT &&
            p.exclusion == ExclusionSet.Empty && p.fact.mark == MarkSlot.Concrete(TaintMark.ZERO)
        if (p.fact.base != STATIC || p.fact.mark is MarkSlot.Star) return true
        val path = p.fact.path
        return path.size == 1 && path[0].isClass() && p.fact.tail == Tail.EXACT ||
            path.size >= 2 && path[0].isClass() && path[1].isFieldAccessor()
    }

    /** A JVM static anchor is indivisible. A raw array element cannot become a class abstraction. */
    private fun firstFieldEnd(base: AccessPathBase, prefix: List<Int>, path: List<Int>): Int? {
        val index = (prefix.size until path.size).firstOrNull { path[it].isCounted() } ?: return null
        val end = index + 1
        if (base == STATIC && (end < 2 || !path[0].isClass() || !path[1].isFieldAccessor())) return null
        return end
    }
}

package org.opentaint.dataflow.bidi.ap

import java.util.Collections

/** Ownership is independent of method specialization and execution mode. */
@JvmInline value class GroupId(val value: Int)
@JvmInline value class FullMarkId(val value: Int)
sealed interface MarkGroupKey {
    data class Rule(val outerRuleId: String) : MarkGroupKey
    data class Model(val declaredId: String) : MarkGroupKey
    data object SharedModel : MarkGroupKey
}

/** Names and claims are collected before method binding. Providers export detached copies. */
data class RawMarkDeclarations(
    val names: Set<String>,
    val explicitOwners: Map<String, MarkGroupKey>,
    val primitiveByOwner: Map<MarkGroupKey, Boolean>,
) {
    companion object { val EMPTY = RawMarkDeclarations(emptySet(), emptyMap(), emptyMap()) }
}

@JvmInline value class GroupName(val encoded: String)
data class FullKey(val group: GroupName, val name: String)

/** Includes owner kind and a final mode, even when an owner ID contains delimiters. */
fun encodeGroup(owner: MarkGroupKey, primitive: Boolean): GroupName {
    val payload = when (owner) {
        is MarkGroupKey.Rule -> "R:${owner.outerRuleId}"
        is MarkGroupKey.Model -> "M:${owner.declaredId}"
        MarkGroupKey.SharedModel -> "S:"
    }
    val mode = if (primitive) "%%primitive%%" else "%%ordinary%%"
    return GroupName("@group:${payload.length}:$payload;$mode")
}

interface MarkDeclarations {
    fun fullKey(name: String): FullKey
}

/** One analysis retains only this immutable index, not the declaration builders. */
class FrozenMarkDeclarations(keys: Map<String, FullKey>) : MarkDeclarations {
    private val byName = Collections.unmodifiableMap(LinkedHashMap(keys))
    init { require(byName.all { (name, key) -> name == key.name }) { "Full-key name mismatch" } }
    override fun fullKey(name: String): FullKey =
        requireNotNull(byName[name]) { "Undeclared executable mark: $name" }
    companion object { val EMPTY = FrozenMarkDeclarations(emptyMap()) }
}
data class ExactMark(val group: GroupId, val full: FullMarkId)
sealed interface MarkAtomKey {
    data object ControlZero : MarkAtomKey
    data class Group(val id: GroupId) : MarkAtomKey
    data class Full(val mark: ExactMark) : MarkAtomKey
}
enum class MarkMode { GROUP, FULL }

/** A group ID set is never a set of opaque runtime atom IDs. */
class GroupSet(ids: IntArray) {
    private val data = ids.sortedDistinct()
    val ids: IntArray get() = data.copyOf()
    val size: Int get() = data.size
    val isEmpty: Boolean get() = data.isEmpty()
    operator fun contains(group: GroupId): Boolean = data.binarySearch(group.value) >= 0
    operator fun plus(other: GroupSet): GroupSet = GroupSet(sortedUnion(data, other.data))
    operator fun plus(group: GroupId): GroupSet = GroupSet(sortedUnion(data, intArrayOf(group.value)))
    infix fun intersect(other: GroupSet): GroupSet = GroupSet(data.filter { other.data.binarySearch(it) >= 0 }.toIntArray())
    fun forEach(visit: (GroupId) -> Unit) { data.forEach { visit(GroupId(it)) } }
    fun toList(): List<GroupId> = data.map(::GroupId)
    fun isSubsetOf(other: GroupSet): Boolean = sortedSubset(data, other.data)
    operator fun minus(other: GroupSet): GroupSet = GroupSet(data.filter { other.data.binarySearch(it) < 0 }.toIntArray())
    override fun equals(other: Any?): Boolean = other is GroupSet && data.contentEquals(other.data)
    override fun hashCode(): Int = data.contentHashCode()
    override fun toString(): String = data.contentToString()
    companion object {
        val EMPTY = GroupSet(IntArray(0))
        fun of(group: GroupId): GroupSet = GroupSet(intArrayOf(group.value))
        fun of(groups: Iterable<GroupId>): GroupSet = GroupSet(groups.map { it.value }.toIntArray())
        fun fromIds(ids: IntArray): GroupSet = GroupSet(ids)
    }
}

/** All access is under the enclosing MarkTable monitor. */
private class MarkKeyInterner<K> {
    private val byKey = HashMap<K, Int>()
    private val keys = ArrayList<K>()
    fun intern(key: K): Int = byKey.getOrPut(key) { keys.size.also { keys.add(key) } }
    fun key(id: Int): K = keys[id]
    fun existingId(key: K): Int = checkNotNull(byKey[key])
}

/** Canonical immutable keys. Ownership is complete before any handle is published. */
class MarkTable(private val declarations: MarkDeclarations) {
    private val groups = MarkKeyInterner<GroupName>()
    private val fulls = MarkKeyInterner<FullKey>()
    private val atoms = MarkKeyInterner<MarkAtomKey>().also {
        check(it.intern(MarkAtomKey.ControlZero) == TaintMark.ZERO.id)
    }

    @Synchronized fun full(name: String): TaintMark {
        val key = declarations.fullKey(name)
        val group = GroupId(groups.intern(key.group))
        val full = FullMarkId(fulls.intern(key))
        return TaintMark(atoms.intern(MarkAtomKey.Full(ExactMark(group, full))))
    }
    fun mark(name: String): TaintMark = full(name)
    @Synchronized fun group(id: GroupId): TaintMark {
        groups.key(id.value)
        return TaintMark(atoms.intern(MarkAtomKey.Group(id)))
    }
    @Synchronized fun owner(full: FullMarkId): GroupId =
        GroupId(groups.existingId(fulls.key(full.value).group))
    @Synchronized fun key(atom: TaintMark): MarkAtomKey = atoms.key(atom.id)
    @Synchronized fun name(atom: TaintMark): String = when (val key = atoms.key(atom.id)) {
        MarkAtomKey.ControlZero -> "<zero>"
        is MarkAtomKey.Full -> fulls.key(key.mark.full.value).name
        is MarkAtomKey.Group -> groups.key(key.id.value).encoded
    }
    @Synchronized fun isFull(atom: TaintMark): Boolean = atoms.key(atom.id) is MarkAtomKey.Full
    @Synchronized fun isGroup(atom: TaintMark): Boolean = atoms.key(atom.id) is MarkAtomKey.Group
    @Synchronized fun fullId(atom: TaintMark): FullMarkId? = (atoms.key(atom.id) as? MarkAtomKey.Full)?.mark?.full
    @Synchronized fun groupId(atom: TaintMark): GroupId? = (atoms.key(atom.id) as? MarkAtomKey.Group)?.id
    fun groupOf(atom: TaintMark): GroupId = when (val k = key(atom)) {
        is MarkAtomKey.Group -> k.id
        is MarkAtomKey.Full -> k.mark.group
        MarkAtomKey.ControlZero -> error("Control ZERO has no group")
    }
    fun runtimeAtom(atom: TaintMark, mode: MarkMode): TaintMark {
        if (atom == TaintMark.ZERO) return atom
        val key = key(atom)
        if (mode == MarkMode.FULL) {
            require(key !is MarkAtomKey.Group) { "An executable full fact cannot contain a group selector" }
            return atom
        }
        return when (key) {
            is MarkAtomKey.Group -> atom
            is MarkAtomKey.Full -> group(key.mark.group)
            MarkAtomKey.ControlZero -> atom
        }
    }
    fun coversAtom(guide: TaintMark, actual: TaintMark): Boolean {
        if (guide == actual) return true
        if (guide == TaintMark.ZERO || actual == TaintMark.ZERO || !isGroup(guide)) return false
        return groupOf(guide) == groupOf(actual)
    }
    fun atomsFor(groups: GroupSet): MarkSet = MarkSet(groups.ids.map { group(GroupId(it)).id }.toIntArray())
}

class RunMarkView(val mode: MarkMode, val catalog: MarkTable) {
    fun literal(atom: TaintMark): TaintMark = catalog.runtimeAtom(atom, mode)
    fun target(atom: TaintMark): TaintMark = catalog.runtimeAtom(atom, mode)
}

package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.AccessPathBase

/** Alias admission for a raw scalar callee summary, before caller binding. */
internal fun hasNoMemoryEffect(initial: PathFact, result: PathFact): Boolean {
    if (initial.base == AccessPathBase.Zero || initial.base != result.base || initial.path != result.path) return false
    return when {
        initial.mark is MarkSlot.Star && result.mark is MarkSlot.Star ->
            initial.tail == Tail.STAR && result.tail == Tail.STAR
        initial.mark is MarkSlot.Concrete && result.mark is MarkSlot.Concrete -> initial.mark == result.mark
        else -> false
    }
}

/** Split actual path/mark payloads. Tail, layer and both headers stay on each
 * scalar result. This does not compare against a started or normalized initial. */
internal fun ApManager.run1SummaryParts(initial: InitialAp, result: Facts): List<Pair<Facts, Boolean>> {
    cancellation.checkpoint()
    check(initial.manager === this) { "A summary premise must use this AP manager" }
    if (initial.isZero || initial.base != result.base) return listOf(result to false)
    return when (result) {
        is Reach -> listOf(result to false)
        is FlowTree -> {
            if (initial.mark !is MarkSlot.Star || initial.tail != Tail.STAR || result.tail != Tail.STAR)
                return listOf(result to false)
            val (selected, rest) = splitSummaryLeaf(FlowAlgebra, result.root, initial.pathData) { it }
            summaryParts(result, selected, rest, result::withRoot)
        }
        is TaintTree -> {
            val atom = (initial.mark as? MarkSlot.Concrete)?.mark ?: return listOf(result to false)
            val singleton = markSetOf(atom)
            val (selected, rest) = splitSummaryLeaf(taintAlg, result.root, initial.pathData) { leaf ->
                taintLeaves(if (atom in leaf.exact) singleton else MarkSet.EMPTY,
                    if (atom in leaf.any) singleton else MarkSet.EMPTY)
            }
            summaryParts(result, selected, rest, result::withRoot)
        }
    }
}

private fun <P : TrieLeaf> summaryParts(
    original: Facts, selected: TrieNode<P>?, rest: TrieNode<P>?, make: (TrieNode<P>) -> Facts,
): List<Pair<Facts, Boolean>> = when {
    selected == null -> listOf(original to false)
    rest == null -> listOf(original to true)
    else -> listOf(make(rest) to false, make(selected) to true)
}

/** Only the exact premise spine changes. Ancestors and descendants are separate
 * scalar paths; untouched sibling subtrees remain shared. No mark/path product. */
private fun <P : TrieLeaf> ApManager.splitSummaryLeaf(
    algebra: LeafAlgebra<P>, root: TrieNode<P>, path: IntArray, select: (P) -> P,
): Pair<TrieNode<P>?, TrieNode<P>?> {
    val spine = ArrayList<TrieNode<P>>(path.size)
    var tip = root
    for (accessor in path) {
        cancellation.checkpoint()
        spine += tip
        tip = tip.child(accessor) ?: return null to root
    }
    val selected = select(tip.leaf)
    if (selected.isEmpty) return null to root
    var rest = algebra.withLeaf(tip, algebra.minus(tip.leaf, selected))
    for (depth in path.indices.reversed()) {
        cancellation.checkpoint()
        val parent = spine[depth]
        rest = algebra.replaceChild(parent, parent.leaf, path[depth], rest)
    }
    val chosen = if (rest == null) root else algebra.prepend(this, this.path(path), algebra.leafNode(selected))
    return chosen to rest
}

package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.interp.MicroEdge

/** The executable BIDI domain excludes literal-backed data. IR effects and
 * generic AP templates still describe literals, including overwrite kills. */
object RuntimeDataDomain {
    fun base(base: AccessPathBase): Boolean = base !is AccessPathBase.Constant
    fun initial(initial: InitialAp): Boolean = base(initial.base)
    fun premise(premise: PremiseKey): Boolean {
        for (member in 0 until premise.size) if (!initial(premise.member(member))) return false
        return true
    }
    fun packet(premise: PremiseKey, facts: Facts): Boolean = premise(premise) && base(facts.base)
    fun producer(edge: PathEdge): Boolean = base(edge.from.base) && base(edge.to.base)
    fun producer(edge: MicroEdge): Boolean = producer(edge.edge) && producer(edge.forward)
}

package org.opentaint.dataflow.bidi.ap

import java.util.ArrayDeque

/** One immutable DAG node can occur below different admitted ancestors. */
private class SpatialKey<P : TrieLeaf>(val node: TrieNode<P>, val above: P) {
    private val hash = System.identityHashCode(node) * 31 + above.hashCode()
    override fun hashCode(): Int = hash
    override fun equals(other: Any?): Boolean = other is SpatialKey<*> && node === other.node && above == other.above
}
private class SpatialFrame<P : TrieLeaf>(val key: SpatialKey<P>, var expanded: Boolean = false)

/** Same-tail prefix normalization. E is read only on the first step below a
 * newly encountered span; prior inherited coverage persists across later E. */
private fun <P : TrieLeaf> LeafAlgebra<P>.canonicalSpans(
    root: TrieNode<P>, exclusion: ExclusionSet, m: ApManager,
    belowSpan: (P) -> P, samePoint: (P) -> P = { it },
): TrieNode<P> {
    val results = HashMap<SpatialKey<P>, TrieNode<P>?>()
    val start = SpatialKey(root, empty)
    val stack = ArrayDeque<SpatialFrame<P>>()
    stack.addLast(SpatialFrame(start))
    while (stack.isNotEmpty()) {
        m.cancellation.checkpoint()
        val frame = stack.peekLast()
        val key = frame.key
        if (results.containsKey(key)) { stack.removeLast(); continue }
        val next = union(key.above, belowSpan(key.node.leaf))
        if (!frame.expanded) {
            frame.expanded = true
            key.node.accessorData?.forEachIndexed { i, accessor ->
                val child = SpatialKey(key.node.childData!![i], if (exclusion.admits(accessor)) next else key.above)
                if (!results.containsKey(child)) stack.addLast(SpatialFrame(child))
            }
        } else {
            val leaf = samePoint(minus(key.node.leaf, key.above))
            results[key] = mapChildren(key.node, leaf, m.cancellation) { accessor, child ->
                results.getValue(SpatialKey(child, if (exclusion.admits(accessor)) next else key.above))
            }
            stack.removeLast()
        }
    }
    return checkNotNull(results.getValue(start)) { "A nonempty packet has a minimal retained position" }
}

/** Explicit MAY positions guide later refinement even when an ancestor covers
 * their denotation. This applies to real FLOW packets, not TAINT geometry. */
internal fun FlowTree.keepsDemandPositions(): Boolean = layer == Layer.DEMAND && tail == Tail.ANY
internal fun TaintTree.keepsDemandPositions(): Boolean = layer == Layer.DEMAND && anyTail == Tail.ANY

internal fun ApManager.canonicalFlowPacket(value: FlowTree): FlowTree =
    if (value.keepsDemandPositions()) value else canonicalFlowDataPacket(value)

/** DATA normalization is also used by packed TAINT's temporary FLOW geometry. */
internal fun ApManager.canonicalFlowDataPacket(value: FlowTree): FlowTree {
    if (value.tail != Tail.ANY && value.tail != Tail.ANY_TAINT) return value
    if (value.root.childData == null) return value
    val root = FlowAlgebra.canonicalSpans(value.root, value.exclusion, this, { it })
    return if (root === value.root) value else value.withRoot(root)
}

internal fun ApManager.canonicalTaintPacket(value: TaintTree): TaintTree {
    if (value.anyTail != Tail.ANY && value.anyTail != Tail.ANY_TAINT || !value.root.hasAny) return value
    if (value.root.childData == null && (value.anyTail != Tail.ANY || value.root.leaf.exact.isEmpty)) return value
    val may = value.anyTail == Tail.ANY
    fun below(leaf: TaintLeaves) = taintLeaves(if (may) leaf.any else MarkSet.EMPTY,
        if (value.keepsDemandPositions()) MarkSet.EMPTY else leaf.any)
    fun at(leaf: TaintLeaves) = if (may) taintLeaves(leaf.exact - leaf.any, leaf.any) else leaf
    val ordinary = taintAlg.canonicalSpans(value.root, value.exclusion, this, ::below, ::at)
    val protection = value.nonSubsumable
    // Native masks require coordinate inclusion even when plain ancestor
    // support is spatially broader than the protected dependency.
    val root = if (protection == null) ordinary else taintAlg.mergeAdd(ordinary, protection, cancellation)
    return if (root === value.root && protection === value.nonSubsumable) value
        else taintTree(value.base, value.layer, root, value.exclusion, value.anyTail, protection)
}

/** Packet-local canonical C2 input. The list contract also supports callers
 * consuming the multi-header deltas returned by canonical group admission. */
fun ApManager.canonicalPackets(value: Facts): List<Facts> = listOf(when (value) {
    is Reach -> value
    is FlowTree -> canonicalFlowPacket(value)
    is TaintTree -> canonicalTaintPacket(value)
})

/** A cohort changes no semantic key: channel is mx for FLOW and Unit for a
 * concrete mark-mask stream. E remains a separate rooted-region payload. */
internal data class SpatialRegion<P : TrieLeaf, K>(
    val tail: Tail, val exclusion: ExclusionSet, val channel: K, val root: TrieNode<P>,
)
private data class SpatialHeader<K>(val tail: Tail, val exclusion: ExclusionSet, val channel: K)

private fun <P : TrieLeaf> LeafAlgebra<P>.intersectionAt(
    a: TrieNode<P>, b: TrieNode<P>, m: ApManager,
): TrieNode<P>? {
    if (a === b) return a
    val outside = minusNode(a, b, m.cancellation) ?: return a
    return minusNode(a, outside, m.cancellation)
}

private class FillKey<P : TrieLeaf>(val parent: TrieNode<P>, val child: TrieNode<P>?) {
    private val hash = System.identityHashCode(parent) * 31 + System.identityHashCode(child)
    override fun hashCode(): Int = hash
    override fun equals(other: Any?): Boolean = other is FillKey<*> && parent === other.parent && child === other.child
}
private class FillFrame<P : TrieLeaf>(val key: FillKey<P>, var expanded: Boolean = false)

/** Partition only the leaf masks whose complete immediate child fills E.
 * The pair DAG memo avoids path enumeration, including shared subtrees. */
private fun <P : TrieLeaf> LeafAlgebra<P>.fillImmediate(
    parent: TrieNode<P>, completeChildren: TrieNode<P>, exclusion: ExclusionSet.Concrete, m: ApManager,
): Map<ExclusionSet, TrieNode<P>> {
    val results = HashMap<FillKey<P>, Map<ExclusionSet, TrieNode<P>>>()
    val start = FillKey(parent, completeChildren)
    val stack = ArrayDeque<FillFrame<P>>()
    stack.addLast(FillFrame(start))
    while (stack.isNotEmpty()) {
        m.cancellation.checkpoint()
        val frame = stack.peekLast()
        val key = frame.key
        if (results.containsKey(key)) { stack.removeLast(); continue }
        if (key.child == null) {
            results[key] = mapOf(exclusion to key.parent)
            stack.removeLast()
            continue
        }
        if (!frame.expanded) {
            frame.expanded = true
            key.parent.accessorData?.forEachIndexed { i, field ->
                val childKey = FillKey(key.parent.childData!![i], key.child.child(field))
                if (!results.containsKey(childKey)) stack.addLast(FillFrame(childKey))
            }
        } else {
            var leaves = linkedMapOf<ExclusionSet, P>()
            if (!key.parent.leaf.isEmpty) leaves[exclusion] = key.parent.leaf
            for (field in exclusion.data) {
                m.cancellation.checkpoint()
                val support = key.child.child(field)?.leaf ?: continue
                if (support.isEmpty) continue
                val split = LinkedHashMap<ExclusionSet, P>()
                for ((e, leaf) in leaves) {
                    val yes = minus(leaf, minus(leaf, support))
                    val no = minus(leaf, support)
                    if (!no.isEmpty) split[e] = split[e]?.let { union(it, no) } ?: no
                    if (!yes.isEmpty) {
                        val next = m.intern(ExclusionSet.of((e as? ExclusionSet.Concrete)?.data
                            ?.filter { it != field }?.toIntArray() ?: EMPTY_PATH))
                        split[next] = split[next]?.let { union(it, yes) } ?: yes
                    }
                }
                leaves = split
            }
            val headers = LinkedHashSet<ExclusionSet>()
            headers.addAll(leaves.keys)
            key.parent.accessorData?.forEachIndexed { i, field ->
                headers.addAll(results.getValue(FillKey(key.parent.childData!![i], key.child.child(field))).keys)
            }
            val out = LinkedHashMap<ExclusionSet, TrieNode<P>>()
            for (e in headers) {
                val fields = ArrayList<Int>()
                val children = ArrayList<TrieNode<P>>()
                var unchanged = e == exclusion
                key.parent.accessorData?.forEachIndexed { i, field ->
                    val old = key.parent.childData!![i]
                    val child = results.getValue(FillKey(old, key.child.child(field)))[e]
                    unchanged = unchanged && child === old
                    if (child != null) { fields += field; children += child }
                }
                val leaf = leaves[e] ?: empty
                val result = if (unchanged && leaf == key.parent.leaf) key.parent
                    else node(leaf, fields.toIntArray(), children.toTypedArray())
                if (!result.isEmpty) out[e] = result
            }
            results[key] = out
            stack.removeLast()
        }
    }
    return results.getValue(start)
}

private fun <P : TrieLeaf, K> LeafAlgebra<P>.coalesceRegions(
    values: List<SpatialRegion<P, K>>, m: ApManager,
): List<SpatialRegion<P, K>> {
    val roots = LinkedHashMap<SpatialHeader<K>, TrieNode<P>>()
    for (v in values) {
        m.cancellation.checkpoint()
        if (v.root.isEmpty) continue
        val key = SpatialHeader(v.tail, v.exclusion, v.channel)
        roots[key] = roots[key]?.let { mergeAdd(it, v.root, m.cancellation) } ?: v.root
    }
    return roots.map { (h, root) -> SpatialRegion(h.tail, h.exclusion, h.channel, root) }
}

/** Constructive region rules from Canonical.lean, executed over packed DAGs.
 * FLOW channels never split into positive mark sets: caller-supplied full
 * channel support is required for a cover or a complete-child fill. */
internal fun <P : TrieLeaf, K> LeafAlgebra<P>.canonicalRegions(
    input: List<SpatialRegion<P, K>>, m: ApManager,
    equalEJoin: ((K,K) -> K)? = null,
    preserveAnyHeads: Boolean = false,
    channelCovers: (K, K) -> Boolean,
): List<SpatialRegion<P, K>> {
    var current = coalesceRegions(input, m)
    while (true) {
        m.cancellation.checkpoint()
        // Equal E makes the cofinite payload union exactly representable.
        // Join only shared coordinates; unrelated geometry keeps its old mx.
        var channelJoined = false
        if (equalEJoin != null) channelJoin@ for (i in current.indices) {
            val a = current[i]
            if (a.tail != Tail.ANY && a.tail != Tail.ANY_TAINT) continue
            for (j in i + 1 until current.size) {
                val b = current[j]
                if (b.tail != a.tail || b.exclusion != a.exclusion || b.channel == a.channel) continue
                val common = intersectionAt(a.root,b.root,m) ?: continue
                val next = ArrayList<SpatialRegion<P,K>>(current.size + 1)
                for (k in current.indices) if (k != i && k != j) next += current[k]
                minusNode(a.root,common,m.cancellation)?.let { next += a.copy(root = it) }
                minusNode(b.root,common,m.cancellation)?.let { next += b.copy(root = it) }
                next += a.copy(channel = equalEJoin(a.channel,b.channel),root = common)
                current = coalesceRegions(next,m)
                channelJoined = true
                break@channelJoin
            }
        }
        if (channelJoined) continue
        // Join shared coordinates of same-channel MUST cohorts by E intersection.
        var joined = false
        join@ for (i in current.indices) {
            val a = current[i]
            if (a.tail != Tail.ANY_TAINT) continue
            for (j in i + 1 until current.size) {
                val b = current[j]
                if (b.tail != a.tail || b.channel != a.channel || b.exclusion == a.exclusion) continue
                val common = intersectionAt(a.root, b.root, m) ?: continue
                val next = ArrayList<SpatialRegion<P, K>>(current.size + 1)
                for (k in current.indices) if (k != i && k != j) next += current[k]
                minusNode(a.root, common, m.cancellation)?.let { next += a.copy(root = it) }
                minusNode(b.root, common, m.cancellation)?.let { next += b.copy(root = it) }
                next += a.copy(exclusion = m.intern(a.exclusion.intersect(b.exclusion)), root = common)
                current = coalesceRegions(next, m)
                joined = true
                break@join
            }
        }
        if (joined) continue
        // A child channel must supply ALL parent marks. Narrower FLOW children
        // remain separate; concrete masks split only their already finite bits.
        var filled = false
        fill@ for (i in current.indices) {
            val parent = current[i]
            val e = parent.exclusion as? ExclusionSet.Concrete ?: continue
            if (parent.tail != Tail.ANY_TAINT) continue
            for (j in current.indices) {
                val child = current[j]
                if (child.tail != Tail.ANY_TAINT || child.exclusion != ExclusionSet.Empty ||
                    !channelCovers(child.channel, parent.channel)) continue
                val split = fillImmediate(parent.root, child.root, e, m)
                if (split.size == 1 && split[e] === parent.root) continue
                val next = ArrayList<SpatialRegion<P, K>>(current.size + split.size)
                for (k in current.indices) if (k != i) next += current[k]
                for ((nextE, root) in split) next += parent.copy(exclusion = nextE, root = root)
                current = coalesceRegions(next, m)
                filled = true
                break@fill
            }
        }
        if (filled) continue
        // New prefix coverage applies to compatible equal tail kinds. The
        // original admission path still owns its pre-existing cross-tail law.
        val next = ArrayList<SpatialRegion<P, K>>(current.size)
        var changed = false
        for (i in current.indices) {
            val value = current[i]
            val keepHeads = preserveAnyHeads && value.tail == Tail.ANY
            var root: TrieNode<P>? = if (!keepHeads && (value.tail == Tail.ANY || value.tail == Tail.ANY_TAINT))
                canonicalSpans(value.root, value.exclusion, m, { it }) else value.root
            for (j in current.indices) {
                if (i == j || root == null) continue
                val stored = current[j]
                if (stored.tail != value.tail || !channelCovers(stored.channel, value.channel)) continue
                val sameAt = stored.tail == Tail.ANY || stored.exclusion.isSubsetOf(value.exclusion)
                val equivalent = sameAt && (stored.tail == Tail.ANY || value.exclusion.isSubsetOf(stored.exclusion)) &&
                    channelCovers(value.channel, stored.channel)
                // Equivalent cohort headers can overlap at coordinates. Keep
                // their first witness, never subtract the same point twice.
                val atAllowed = sameAt && (!equivalent || j < i)
                val belowAllowed = !keepHeads && (stored.tail == Tail.ANY || stored.tail == Tail.ANY_TAINT)
                root = subtract(root, stored.root, empty,
                    at = { if (atAllowed) it else empty },
                    below = { if (belowAllowed) it else empty },
                    admits = stored.exclusion::admits, cancellation = m.cancellation)
            }
            changed = changed || root !== value.root
            if (root != null) next += value.copy(root = root)
        }
        if (!changed) return current
        current = coalesceRegions(next, m)
    }
}

internal fun ApManager.canonicalFlowState(values: List<FlowTree>): List<FlowTree> {
    if (values.isEmpty()) return values
    val first = values[0]
    return FlowAlgebra.canonicalRegions(values.map {
        check(it.base == first.base && it.layer == first.layer)
        SpatialRegion(it.tail,it.exclusion,it.markExclusion,it.root)
    },this,equalEJoin = { a,b -> intern(a.intersect(b)) },preserveAnyHeads = first.layer == Layer.DEMAND,
        channelCovers = MarkExclusions::isSubsetOf).map { flowTree(first.base, first.layer, it.exclusion, it.channel, it.root, it.tail) }
}

private data class TaintSpatialHeader(val tail: Tail, val exclusion: ExclusionSet)
private class TaintSpatialRoots(var ordinary: TaintNode? = null, var protected: TaintNode? = null)

internal fun ApManager.canonicalTaintState(values: List<TaintTree>): List<TaintTree> {
    if (values.none { it.nonSubsumable != null }) return canonicalTaintDataState(values)
    return embedRawProtection(canonicalTaintDataState(values.map { it.withoutProtection() }), values)
}

/** The existing regional DATA step. STAR/T4 admission remains in TaintGroup. */
private fun ApManager.canonicalTaintDataState(values: List<TaintTree>): List<TaintTree> {
    if (values.isEmpty()) return values
    val first = values[0]
    fun union(a: TaintNode?, b: TaintNode?): TaintNode? = when {
        a == null -> b
        b == null -> a
        else -> taintAlg.mergeAdd(a,b,cancellation)
    }
    fun extract(root: TaintNode, any: Boolean): TaintNode? = taintAlg.mapCanonicalLeaves(root,cancellation) {
        if (any) taintLeaves(MarkSet.EMPTY,it.any) else taintLeaves(it.exact,MarkSet.EMPTY)
    }
    val ordinary = ArrayList<SpatialRegion<TaintLeaves,Unit>>()
    val protected = ArrayList<SpatialRegion<TaintLeaves,Unit>>()
    val exactHeaders = LinkedHashMap<TaintSpatialHeader,TaintSpatialRoots>()
    // Only byte-equal whole ordinary content has the old T4 mixed-header join.
    val contentE = HashMap<Pair<Tail,TaintNode>,ExclusionSet>()
    for (value in values) {
        cancellation.checkpoint()
        check(value.base == first.base && value.layer == first.layer)
        val header = TaintSpatialHeader(value.anyTail,value.exclusion)
        val exact = exactHeaders.getOrPut(header,::TaintSpatialRoots)
        exact.ordinary = union(exact.ordinary,extract(value.root,false))
        extract(value.root,true)?.let { ordinary += SpatialRegion(value.anyTail,value.exclusion,Unit,it) }
        if (value.root.hasAny) {
            val key = value.anyTail to value.root
            contentE[key] = contentE[key]?.intersect(value.exclusion) ?: value.exclusion
        }
        value.nonSubsumable?.let { flags ->
            exact.protected = union(exact.protected,extract(flags,false))
            extract(flags,true)?.let { protected += SpatialRegion(value.anyTail,value.exclusion,Unit,it) }
        }
    }
    val ordinarySpans = taintAlg.canonicalRegions(ordinary,this,
        preserveAnyHeads = first.layer == Layer.DEMAND) { _,_ -> true }
    val protectedSpans = taintAlg.canonicalRegions(protected,this) { _,_ -> true }
    fun pruneExact(root: TaintNode?, spans: List<SpatialRegion<TaintLeaves,Unit>>): TaintNode? {
        var current = root
        for (span in spans) if (span.tail == Tail.ANY && current != null) {
            current = taintAlg.subtract(current,span.root,TaintLeaves.EMPTY,
                at = { taintLeaves(it.any,MarkSet.EMPTY) }, below = { taintLeaves(it.any,MarkSet.EMPTY) },
                cancellation = cancellation)
        }
        return current
    }
    val grouped = LinkedHashMap<TaintSpatialHeader,TaintSpatialRoots>()
    for (span in ordinarySpans) {
        val roots = grouped.getOrPut(TaintSpatialHeader(span.tail,span.exclusion),::TaintSpatialRoots)
        roots.ordinary = union(roots.ordinary,span.root)
    }
    for (span in protectedSpans) {
        val roots = grouped.getOrPut(TaintSpatialHeader(span.tail,span.exclusion),::TaintSpatialRoots)
        roots.protected = union(roots.protected,span.root)
    }
    var seenExact: TaintNode? = null
    var seenProtectedExact: TaintNode? = null
    for ((oldHeader,exact) in exactHeaders) {
        var destination = oldHeader.takeIf { it in grouped }
        if (destination == null) {
            // Keep unchanged exact coordinates in their old mixed cohort where
            // possible. A real equal-content T4 join may move that cohort.
            for (value in values) if (value.anyTail == oldHeader.tail && value.exclusion == oldHeader.exclusion && value.root.hasAny) {
                val joined = TaintSpatialHeader(value.anyTail,contentE.getValue(value.anyTail to value.root))
                if (joined in grouped) { destination = joined; break }
            }
        }
        val header = destination ?: TaintSpatialHeader(Tail.ANY_TAINT,ExclusionSet.Empty)
        val ordinaryExact = pruneExact(exact.ordinary,ordinarySpans)?.let { root ->
            if (seenExact == null) root else taintAlg.minusNode(root,checkNotNull(seenExact),cancellation)
        }
        val protectedExact = pruneExact(exact.protected,protectedSpans)?.let { root ->
            if (seenProtectedExact == null) root else taintAlg.minusNode(root,checkNotNull(seenProtectedExact),cancellation)
        }
        if (ordinaryExact == null && protectedExact == null) continue
        val roots = grouped.getOrPut(header,::TaintSpatialRoots)
        roots.ordinary = union(roots.ordinary,ordinaryExact)
        roots.protected = union(roots.protected,protectedExact)
        seenExact = union(seenExact,ordinaryExact)
        seenProtectedExact = union(seenProtectedExact,protectedExact)
    }
    return grouped.mapNotNull { (header,roots) ->
        val root = union(roots.ordinary,roots.protected) ?: return@mapNotNull null
        taintTree(first.base,first.layer,root,header.exclusion,header.tail,roots.protected)
    }
}

/** Retain supplied protection by effective scalar coordinates. DATA-derived
 * E joins stay plain. EXACT ignores its wrapper; span masks retain tail/E. */
internal fun ApManager.embedRawProtection(data: List<TaintTree>, sources: List<TaintTree>): List<TaintTree> {
    if (sources.none { it.nonSubsumable != null }) return data
    val first = sources.first()
    fun union(a: TaintNode?, b: TaintNode?): TaintNode? = when {
        a == null -> b
        b == null -> a
        else -> taintAlg.mergeAdd(a, b, cancellation)
    }
    fun exact(root: TaintNode): TaintNode? = taintAlg.mapCanonicalLeaves(root, cancellation) {
        taintLeaves(it.exact, MarkSet.EMPTY)
    }
    fun minus(a: TaintNode?, b: TaintNode?): TaintNode? =
        if (a == null || b == null) a else taintAlg.minusNode(a, b, cancellation)

    var exactFlags: TaintNode? = null
    for (source in sources) {
        cancellation.checkpoint()
        check(source.base == first.base && source.layer == first.layer)
        source.nonSubsumable?.let { exactFlags = union(exactFlags, exact(it)) }
    }
    val grouped = LinkedHashMap<TaintSpatialHeader, TaintSpatialRoots>()
    fun add(header: TaintSpatialHeader, root: TaintNode, flags: TaintNode?) {
        val key = if (root.hasAny || grouped[header]?.ordinary?.hasAny == true) header
            else TaintSpatialHeader(Tail.ANY_TAINT, ExclusionSet.Empty)
        val target = grouped.getOrPut(key, ::TaintSpatialRoots)
        target.ordinary = union(target.ordinary, root)
        target.protected = union(target.protected, flags)
    }
    var placedExact: TaintNode? = null
    for (value in data) {
        cancellation.checkpoint()
        check(value.nonSubsumable == null && value.base == first.base && value.layer == first.layer)
        val matching = exactFlags?.let { intersectTaintMask(it, value.root, cancellation) }
        val repeated = if (matching == null || placedExact == null) null
            else intersectTaintMask(matching, checkNotNull(placedExact), cancellation)
        val root = minus(value.root, repeated) ?: continue
        val flags = minus(matching, placedExact)
        add(TaintSpatialHeader(value.anyTail, value.exclusion), root, flags)
        placedExact = union(placedExact, flags)
    }
    for (source in sources) {
        cancellation.checkpoint()
        val flags = source.nonSubsumable ?: continue
        val spans = taintAlg.mapCanonicalLeaves(flags, cancellation) { taintLeaves(MarkSet.EMPTY, it.any) }
        if (spans != null) add(TaintSpatialHeader(source.anyTail, source.exclusion), spans, spans)
    }
    // Restore pruned exact flags in an existing original cohort where possible.
    // This keeps whole-content T4 geometry without duplicating effective EXACT.
    for (source in sources) {
        cancellation.checkpoint()
        val header = TaintSpatialHeader(source.anyTail, source.exclusion)
        if (header !in grouped) continue
        val flags = minus(source.nonSubsumable?.let(::exact), placedExact) ?: continue
        add(header, flags, flags)
        placedExact = union(placedExact, flags)
    }
    minus(exactFlags, placedExact)?.let {
        add(TaintSpatialHeader(Tail.ANY_TAINT, ExclusionSet.Empty), it, it)
    }
    return grouped.mapNotNull { (header, roots) ->
        roots.ordinary?.let { taintTree(first.base, first.layer, it, header.exclusion, header.tail, roots.protected) }
    }
}

/** Copy only already-current flags onto a legacy DATA delta. No prefix overlap. */
internal fun ApManager.withCurrentProtection(value: TaintTree, current: List<TaintTree>): TaintTree {
    var mask: TaintNode? = null
    for (stored in current) {
        cancellation.checkpoint()
        if (stored.base != value.base || stored.layer != value.layer) continue
        val flags = stored.nonSubsumable ?: continue
        val typed = if (stored.anyTail == value.anyTail && stored.exclusion == value.exclusion) flags
            else taintAlg.mapCanonicalLeaves(flags, cancellation) { taintLeaves(it.exact, MarkSet.EMPTY) } ?: continue
        val common = intersectTaintMask(typed, value.root, cancellation) ?: continue
        mask = mask?.let { taintAlg.mergeAdd(it, common, cancellation) } ?: common
    }
    return value.withProtection(mask, cancellation)
}

/** Read current exact coordinates, not semantic ancestor coverage. A final
 * detached batch cannot retain a removed descendant through its old snapshot.
 * Exact TAINT slots ignore a wrapper's any-tail/E, as native scalar leaves do. */
fun retainCurrentFacts(m: ApManager, offered: Facts, current: Iterable<Facts>): List<Facts> {
    m.cancellation.checkpoint()
    return when (offered) {
        is Reach -> if (current.any { it is Reach && it.layer == offered.layer }) listOf(offered) else emptyList()
        is FlowTree -> {
            var root: FlowNode? = null
            for (value in current) {
                m.cancellation.checkpoint()
                if (value !is FlowTree || value.groupKey != offered.groupKey) continue
                val common = FlowAlgebra.intersectionAt(offered.root,value.root,m) ?: continue
                root = root?.let { FlowAlgebra.mergeAdd(it,common,m.cancellation) } ?: common
            }
            root?.let { listOf(offered.withRoot(it)) } ?: emptyList()
        }
        is TaintTree -> {
            var ordinary: TaintNode? = null
            var protected: TaintNode? = null
            fun selected(value: TaintTree, root: TaintNode): TaintNode? {
                val matching = value.anyTail == offered.anyTail && value.exclusion == offered.exclusion
                return if (matching) root else m.taintAlg.mapCanonicalLeaves(root,m.cancellation) {
                    m.taintLeaves(it.exact,MarkSet.EMPTY)
                }
            }
            for (value in current) {
                m.cancellation.checkpoint()
                if (value !is TaintTree || value.base != offered.base || value.layer != offered.layer) continue
                selected(value,value.root)?.let { mask ->
                    intersectTaintMask(offered.root,mask,m.cancellation)?.let { common ->
                        ordinary = ordinary?.let { m.taintAlg.mergeAdd(it,common,m.cancellation) } ?: common
                    }
                }
                if (offered.nonSubsumable != null && value.nonSubsumable != null) {
                    selected(value,value.nonSubsumable)?.let { mask ->
                        intersectTaintMask(offered.nonSubsumable,mask,m.cancellation)?.let { common ->
                            protected = protected?.let { m.taintAlg.mergeAdd(it,common,m.cancellation) } ?: common
                        }
                    }
                }
            }
            ordinary?.let { listOf(m.taintTree(offered.base,offered.layer,it,offered.exclusion,offered.anyTail,protected)) }
                ?: emptyList()
        }
    }
}

package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.AccessPathBase

/** The two annotations of a TAINT leaf and the single annotation of a FLOW flag. */
private class SummaryTails<P : TrieLeaf>(
    val exclusion: ExclusionSet,
    val anyExclusion: ExclusionSet = ExclusionSet.Empty,
    val select: (P, star: Boolean, any: Boolean, exact: Boolean) -> P,
)

private fun flowTails(a: FlowTree) = SummaryTails<FlowLeaf>(
    if (a.tail == Tail.STAR) a.exclusion else ExclusionSet.Empty,
    if (a.tail == Tail.ANY_TAINT) a.exclusion else ExclusionSet.Empty,
) { p, star, any, exact ->
    val selected = when (a.tail) {
        Tail.STAR -> star
        Tail.EXACT -> exact
        Tail.ANY, Tail.ANY_TAINT -> any
    }
    if (selected) p else FlowLeaf.NONE
}

private fun taintTails(m: ApManager, a: TaintTree) =
    if (a.anyTail == Tail.STAR) SummaryTails<TaintLeaves>(a.exclusion) { p, star, _, exact ->
        m.taintLeaves(if (exact) p.exact else MarkSet.EMPTY, if (star) p.any else MarkSet.EMPTY)
    } else SummaryTails<TaintLeaves>(ExclusionSet.Empty, a.exclusion) { p, _, any, exact ->
        m.taintLeaves(if (exact) p.exact else MarkSet.EMPTY, if (any) p.any else MarkSet.EMPTY)
    }

/** Preserve full selected leaves and their input annotations. Record demotion occurs after return actions. */
internal fun satisfyingPart(m: ApManager, a: Facts, j: Pattern, mode: ApMode, record: Boolean,
                            allowStrictAncestorStar: Boolean = true): Facts? {
    m.cancellation.checkpoint()
    if (a.base != j.fact.base) return null
    check(j.fact.tail != Tail.ANY_TAINT || (mode.restricted && mode.direction == Direction.FORWARD)) {
        "W8 (c): a must-premise is forward restricted"
    }
    val below = record || mode.run1 || (mode.restricted && (j.fact.mark is MarkSlot.Star || j.fact.tail == Tail.STAR))
    val inside = record || mode.restricted || mode.run1
    if (j.fact.tail == Tail.ANY_TAINT && j.fact.mark is MarkSlot.Star) return when (a) {
        is Reach -> null
        is FlowTree -> if (j.fact.mark !is MarkSlot.Star || a.tail != Tail.ANY_TAINT) null
            else definiteMustPart(m, a.root, FlowAlgebra, a.exclusion, j) { it }
                ?.let { m.flowTree(a.base, a.layer, a.exclusion, a.markExclusion, it, a.tail) }
        is TaintTree -> if (a.anyTail != Tail.ANY_TAINT) null
            else definiteMustPart(m, a.root, m.taintAlg, a.exclusion, j) {
                m.taintLeaves(MarkSet.EMPTY, it.any)
            }?.let { markSubPart(m, it, j, mode) }
                ?.let { m.taintTree(a.base, a.layer, it, a.exclusion, a.anyTail) }
    }
    return when (a) {
        is Reach -> a.takeIf { j.fact.base == AccessPathBase.Zero }
        is FlowTree -> if (j.fact.mark !is MarkSlot.Star) null
            else summaryPart(m, a.root, FlowAlgebra, flowTails(a), j, below, inside, allowStrictAncestorStar)
                ?.let { m.flowTree(a.base, a.layer, a.exclusion, a.markExclusion, it, a.tail) }
        is TaintTree -> summaryPart(m, a.root, m.taintAlg, taintTails(m, a), j, below, inside, allowStrictAncestorStar)
            ?.let { markSubPart(m, it, j, mode) }
            ?.let { m.taintTree(a.base, if (mode.markMode == MarkMode.GROUP) Layer.DEMAND else a.layer, it, a.exclusion, a.anyTail) }
    }
}

/** A uniform query requires an actual uniform scope that covers the entire query. */
private fun <P : TrieLeaf> definiteMustPart(
    m: ApManager, root: TrieNode<P>, alg: LeafAlgebra<P>, exclusion: ExclusionSet,
    j: Pattern, onlyMust: (P) -> P,
): TrieNode<P>? {
    val path = j.fact.path.toIntArray()
    val spine = ArrayList<P>()
    val at = root.walk(path) { depth, node ->
        m.cancellation.checkpoint()
        spine += if (exclusion.admits(path[depth])) onlyMust(node.leaf) else alg.empty
    }
    if (at != null) spine += if (exclusion.isSubsetOf(j.exclusion)) onlyMust(at.leaf) else alg.empty
    return alg.chain(m, path, spine)
}

private fun markSubPart(m: ApManager, n: TaintNode, j: Pattern, mode: ApMode): TaintNode? {
    val gate = MarkGate(m, j.fact.mark, MarkSlot.STAR, mode)
    return m.taintAlg.mapLeaves(n, m.cancellation) { p ->
        m.taintLeaves(gate.taintMarks(p.exact) ?: MarkSet.EMPTY, gate.taintMarks(p.any) ?: MarkSet.EMPTY)
    }
}

private fun <P : TrieLeaf> summaryPart(
    m: ApManager, root: TrieNode<P>, alg: LeafAlgebra<P>, t: SummaryTails<P>, j: Pattern,
    below: Boolean, inside: Boolean, allowStrictAncestorStar: Boolean,
): TrieNode<P>? {
    val b = if (below) applicablePart(m, root, alg, t, j) else null
    val i = if (inside) insidePart(m, root, alg, t, j, allowStrictAncestorStar) else null
    return if (b == null) i else if (i == null) b else alg.mergeAdd(b, i, m.cancellation)
}

private fun <P : TrieLeaf> applicablePart(
    m: ApManager, root: TrieNode<P>, alg: LeafAlgebra<P>, t: SummaryTails<P>, j: Pattern,
): TrieNode<P>? {
    val path = j.fact.path.toIntArray()
    val u = root.walk(path) { _, _ -> m.cancellation.checkpoint() } ?: return null
    m.cancellation.checkpoint()
    val ej = j.exclusion
    val anyAt = ej.isSubsetOf(t.anyExclusion)
    val at = when (j.fact.tail) {
        Tail.STAR -> t.select(u.leaf, ej.isSubsetOf(t.exclusion), anyAt, true)
        Tail.EXACT -> t.select(u.leaf, false, false, true)
        Tail.ANY_TAINT -> t.select(u.leaf, false, anyAt, false)
        Tail.ANY -> t.select(u.leaf, false, true, false)
    }
    val kids = when (j.fact.tail) {
        Tail.STAR -> alg.retainChildren(u, m.cancellation) { ej.admits(it) }
        Tail.EXACT -> null
        Tail.ANY_TAINT -> alg.retainChildren(u, m.cancellation) { ej.admits(it) }
            ?.let { k -> alg.mapLeaves(k, m.cancellation) { t.select(it, false, true, false) } }
        Tail.ANY -> alg.retainChildren(u, m.cancellation) { true }
            ?.let { k -> alg.mapLeaves(k, m.cancellation) { t.select(it, false, true, false) } }
    }
    return alg.withLeaf(kids, at)?.let { alg.prepend(m, m.path(path), it) }
}

private fun <P : TrieLeaf> insidePart(
    m: ApManager, root: TrieNode<P>, alg: LeafAlgebra<P>, t: SummaryTails<P>, j: Pattern,
    allowStrictAncestorStar: Boolean,
): TrieNode<P>? {
    val path = j.fact.path.toIntArray()
    val spine = ArrayList<P>()
    val u = root.walk(path) { d, n ->
        m.cancellation.checkpoint()
        spine += t.select(n.leaf, allowStrictAncestorStar && t.exclusion.admits(path[d]),
            t.anyExclusion.admits(path[d]), false)
    }
    m.cancellation.checkpoint()
    if (u != null) spine += t.select(u.leaf,
        when (j.fact.tail) {
            Tail.EXACT -> true
            Tail.STAR -> t.exclusion.isSubsetOf(j.exclusion)
            Tail.ANY, Tail.ANY_TAINT -> t.exclusion == ExclusionSet.Empty
        },
        j.fact.tail == Tail.EXACT || t.anyExclusion.isSubsetOf(j.exclusion),
        j.fact.tail == Tail.EXACT)
    return alg.chain(m, path, spine)
}

/** One edge for each tail/mark kind, followed by a graft into every path having that kind. */
internal fun applySummaryPart(ops: ApOps, a: Facts, j: InitialAp, g: Facts, mode: ApMode, out: ApOut) {
    val m = ops.manager
    m.cancellation.checkpoint()
    check(a !is FlowTree || g is FlowTree) { "a FLOW fact satisfies only a `*` premise, whose summaries are FLOW" }
    for (kind in leafKinds(m, g, j)) {
        m.cancellation.checkpoint()
        val one = CollectingOut()
        ops.applyCompiledEdge(a, kind.edge, g.layer == Layer.DEMAND, -1, mode, one)
        // F78: applying an excluded abstract target preserves the interest on
        // the caller's original slot before publishing its excluded result.
        for (mark in one.markRequests) {
            m.cancellation.checkpoint()
            out.markRequest(mark)
        }
        for (r in one.results) {
            m.cancellation.checkpoint()
            out.result(kind.graft(r))
        }
    }
}

/** A transient native record uses its Pattern directly, retaining its own exclusions. */
internal fun applyRecordLeafPart(ops: ApOps, a: Facts, view: RecordLeafView, nonSubsumable: Boolean,
                                 mode: ApMode, out: ApOut) {
    val m = ops.manager
    m.cancellation.checkpoint()
    val edge = ops.compiled(summaryEdge(view.premise, view.result))
    val one = CollectingOut()
    ops.applyCompiledEdge(a, edge, view.result.demand, -1, mode, one)
    for (mark in one.markRequests) {
        m.cancellation.checkpoint()
        out.markRequest(mark)
    }
    for (r in one.results) {
        m.cancellation.checkpoint()
        out.result(if (nonSubsumable) m.selectedProtection(r, null) else r)
    }
}

private class SummaryLeafKind(val edge: CompiledEdge, val graft: (Facts) -> Facts)

private fun leafKinds(m: ApManager, g: Facts, j: InitialAp): List<SummaryLeafKind> {
    val jOwn = j.tail == Tail.ANY_TAINT
    val inputShared = if (jOwn) ExclusionSet.Empty else j.exclusion
    fun edge(tail: Tail, mark: MarkSlot, exclusion: ExclusionSet, toExclusion: ExclusionSet = ExclusionSet.Empty) =
        CompiledEdge(j.base, j.pathData, j.tail, j.mark, g.base, null, tail, mark,
            m.intern(exclusion),
            m.intern(if (jOwn) j.exclusion else ExclusionSet.Empty), m.intern(toExclusion))
    return when (g) {
        is Reach -> listOf(SummaryLeafKind(edge(Tail.EXACT, MarkSlot.Concrete(TaintMark.ZERO), ExclusionSet.Empty)) { it })
        is FlowTree -> listOf(SummaryLeafKind(edge(g.tail, MarkSlot.Star(g.markExclusion),
            if (g.tail == Tail.STAR || g.tail == Tail.EXACT) inputShared.union(g.exclusion) else inputShared,
            if (g.tail == Tail.ANY_TAINT) g.exclusion else ExclusionSet.Empty)) {
            graftSummary(m, g.root, { p -> p == FlowLeaf.LEAF }, it)
        })
        is TaintTree -> {
            val all = m.taintAlg.foldAll(g.root, m.cancellation)
            val anyTail = g.anyTail
            val kinds = ArrayList<SummaryLeafKind>()
            for (id in all.exact.ids) {
                m.cancellation.checkpoint()
                val mark = TaintMark(id)
                kinds += SummaryLeafKind(edge(Tail.EXACT, MarkSlot.Concrete(mark), inputShared)) {
                    graftSummary(m, g.root, { p -> mark in p.exact }, it)
                }
            }
            for (id in all.any.ids) {
                m.cancellation.checkpoint()
                val mark = TaintMark(id)
                val shared = if (anyTail == Tail.STAR) inputShared.union(g.exclusion) else inputShared
                val own = if (anyTail == Tail.ANY_TAINT) g.exclusion else ExclusionSet.Empty
                kinds += SummaryLeafKind(edge(anyTail, MarkSlot.Concrete(mark), shared, own)) {
                    graftSummary(m, g.root, { p -> mark in p.any }, it)
                }
            }
            kinds
        }
    }
}

private fun <G : TrieLeaf> graftSummary(m: ApManager, g: TrieNode<G>, occurs: (G) -> Boolean, r: Facts): Facts =
    when (r) {
        is Reach -> r
        is FlowTree -> r.withRoot(checkNotNull(FlowAlgebra.graft(g, occurs, r.root, m.cancellation)))
        is TaintTree -> m.taintTree(r.base, r.layer,
            checkNotNull(m.taintAlg.graft(g, occurs, r.root, m.cancellation)), r.exclusion, r.anyTail,
            r.nonSubsumable?.let { m.taintAlg.graft(g, occurs, it, m.cancellation) })
    }

/** Matching is supplied by the caller. W7 makes each complete concrete member return the same target. */
internal fun applyCombinationPart(
    manager: ApManager, parts: List<Pair<Facts, InitialAp>>, g: TaintTree, mode: ApMode, out: ApOut,
) {
    manager.cancellation.checkpoint()
    check(parts.size >= 2)
    val layers = ArrayList<Layer>(parts.size)
    for ((part, _) in parts) {
        manager.cancellation.checkpoint()
        check(part is TaintTree)
        layers += part.layer
    }
    applyMatchedCombinationPart(manager, layers, g, out)
}

/** E6's full member matcher has checked TAINT inputs. Their roots do not affect this transfer. */
internal fun applyMatchedCombinationPart(
    manager: ApManager, linkLayers: List<Layer>, g: TaintTree, out: ApOut,
) {
    manager.cancellation.checkpoint()
    check(linkLayers.size >= 2)
    var layer = g.layer
    for (linkLayer in linkLayers) {
        manager.cancellation.checkpoint()
        if (linkLayer == Layer.DEMAND) layer = Layer.DEMAND
    }
    out.result(g.withLayer(layer))
}

/** Remove identical annotated leaves; preserve the other leaves without record demotion. */
internal fun withoutPart(manager: ApManager, c: Facts, part: Facts): Facts? {
    manager.cancellation.checkpoint()
    return when {
        c.base != part.base -> c
        c is TaintTree && part is TaintTree ->
            if (c.layer != part.layer || (part.root.hasAny &&
                    (part.exclusion != c.exclusion || part.anyTail != c.anyTail))) c
            else manager.taintAlg.minusNode(c.root, part.root, manager.cancellation)
                ?.let { if (it === c.root) c else c.withRoot(it) }
        c.groupKey != part.groupKey -> c
        c is Reach -> if (part is Reach && part.layer == c.layer) null else c
        c is FlowTree && part is FlowTree -> FlowAlgebra.minusNode(c.root, part.root, manager.cancellation)
            ?.let { if (it === c.root) c else c.withRoot(it) }
        else -> c
    }
}

package org.opentaint.dataflow.bidi.ap

/** The supplying relation's origin, independent of native record query semantics. */
enum class SummaryMatchRole {
    CURRENT,
    SAVED_DIRECT,
    OPPOSITE_RECORD,
}

package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.access.util.AccessorIdx
import java.util.ArrayDeque
import java.util.IdentityHashMap
import java.util.concurrent.ConcurrentHashMap

interface TrieLeaf {
    val isEmpty: Boolean
    val hasAny: Boolean
}

enum class FlowLeaf : TrieLeaf {
    NONE, LEAF;
    override val isEmpty: Boolean get() = this == NONE
    override val hasAny: Boolean get() = false
}

class TaintLeaves internal constructor(val exact: MarkSet, val any: MarkSet) : TrieLeaf {
    private val hash = exact.hashCode() * 31 + any.hashCode()
    override val isEmpty: Boolean get() = exact.isEmpty && any.isEmpty
    override val hasAny: Boolean get() = !any.isEmpty
    override fun equals(other: Any?): Boolean = this === other ||
        (other is TaintLeaves && hash == other.hash && exact == other.exact && any == other.any)
    override fun hashCode(): Int = hash
    companion object { @JvmField val EMPTY = TaintLeaves(MarkSet.EMPTY, MarkSet.EMPTY) }
}

/** Immutable sorted children. Public arrays are snapshots of the owned content. */
class TrieNode<P : TrieLeaf> internal constructor(
    @JvmField val leaf: P,
    accessors: IntArray?,
    children: Array<TrieNode<P>>?,
    @JvmField val interned: Boolean,
) {
    internal val accessorData: IntArray? = accessors?.takeIf { it.isNotEmpty() }?.copyOf()
    internal val childData: Array<TrieNode<P>>? = children?.takeIf { it.isNotEmpty() }?.copyOf()
    val accessors: IntArray? get() = accessorData?.copyOf()
    val children: Array<TrieNode<P>>? get() = childData?.copyOf()
    @JvmField val hash: Long
    @JvmField val boundedDepth: Int
    @JvmField val hasAny: Boolean
    @JvmField val size: Long
    @JvmField internal var allLeaves: P? = null

    init {
        check((accessorData == null) == (childData == null)) { "Child arrays must be aligned" }
        check(accessorData == null || accessorData.size == childData!!.size) { "Child arrays must have equal sizes" }
        var h = leaf.hashCode().toLong()
        var depth = 0
        var any = leaf.hasAny
        var count = 1L
        if (accessorData != null) for (i in accessorData.indices) {
            val accessor = accessorData[i]
            check(accessor.isPathAccessor()) { "W5: a trie edge needs a path accessor" }
            check(i == 0 || accessorData[i - 1] < accessor) { "Trie accessors must be sorted and unique" }
            val child = childData!![i]
            check(!child.isEmpty) { "A child subtree must be nonempty" }
            count = Math.addExact(count, child.size)
            h += (child.hash * 31 + accessor) shl 5
            depth = maxOf(depth, Math.addExact(child.boundedDepth, if (accessor.isCounted()) 1 else 0))
            any = any || child.hasAny
        }
        hash = h
        boundedDepth = depth
        hasAny = any
        size = count
    }

    val isEmpty: Boolean get() = leaf.isEmpty && accessorData == null
    fun child(accessor: AccessorIdx): TrieNode<P>? {
        val index = accessorData?.binarySearch(accessor) ?: return null
        return if (index < 0) null else childData!![index]
    }

    override fun hashCode(): Int = hash.toInt()

    /** Shared DAGs and deep paths compare by value without recursive calls. */
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is TrieNode<*>) return false
        val pending = ArrayDeque<Pair<TrieNode<*>, TrieNode<*>>>()
        val seen = IdentityHashMap<TrieNode<*>, IdentityHashMap<TrieNode<*>, Boolean>>()
        pending.addLast(this to other)
        while (pending.isNotEmpty()) {
            val (a, b) = pending.removeLast()
            if (a === b) continue
            if (a.hash != b.hash || a.size != b.size || a.boundedDepth != b.boundedDepth ||
                a.hasAny != b.hasAny || a.leaf != b.leaf || !a.accessorData.contentEquals(b.accessorData)) return false
            if (seen.getOrPut(a) { IdentityHashMap() }.put(b, true) != null) continue
            val x = a.childData
            val y = b.childData
            if (x == null || y == null) {
                if (x !== y) return false
                continue
            }
            if (x.size != y.size) return false
            for (i in x.indices) pending.addLast(x[i] to y[i])
        }
        return true
    }
}

typealias FlowNode = TrieNode<FlowLeaf>
typealias TaintNode = TrieNode<TaintLeaves>

abstract class LeafAlgebra<P : TrieLeaf> {
    abstract val empty: P
    abstract fun union(a: P, b: P): P
    abstract fun minus(a: P, b: P): P
    abstract fun below(p: P): P
    abstract fun asAny(p: P): P
    abstract fun intern(p: P): P
    private val leafNodes = ConcurrentHashMap<P, TrieNode<P>>()

    fun leafNode(p: P): TrieNode<P> = leafNodes.computeIfAbsent(intern(p)) { TrieNode(it, null, null, true) }

    fun node(p: P, accessors: IntArray?, children: Array<TrieNode<P>>?): TrieNode<P> {
        val a = accessors?.takeIf { it.isNotEmpty() }
        val c = children?.takeIf { it.isNotEmpty() }
        check((a == null) == (c == null)) { "Child arrays must be aligned" }
        return if (a == null) leafNode(p) else TrieNode(intern(p), a, c, false)
    }
}

object FlowAlgebra : LeafAlgebra<FlowLeaf>() {
    override val empty: FlowLeaf get() = FlowLeaf.NONE
    override fun union(a: FlowLeaf, b: FlowLeaf) = if (!a.isEmpty || !b.isEmpty) FlowLeaf.LEAF else FlowLeaf.NONE
    override fun minus(a: FlowLeaf, b: FlowLeaf) = if (!a.isEmpty && b.isEmpty) FlowLeaf.LEAF else FlowLeaf.NONE
    override fun below(p: FlowLeaf) = p
    override fun asAny(p: FlowLeaf) = p
    override fun intern(p: FlowLeaf) = p
    val LEAF_NODE: FlowNode get() = leafNode(FlowLeaf.LEAF)
}

class TaintAlgebra(private val m: ApManager) : LeafAlgebra<TaintLeaves>() {
    private val table = ConcurrentHashMap<TaintLeaves, TaintLeaves>()
    override val empty: TaintLeaves get() = TaintLeaves.EMPTY
    fun leaves(exact: MarkSet, any: MarkSet): TaintLeaves = intern(TaintLeaves(m.intern(exact), m.intern(any)))
    override fun intern(p: TaintLeaves): TaintLeaves =
        if (p.isEmpty) TaintLeaves.EMPTY else table.putIfAbsent(p, p) ?: p
    override fun union(a: TaintLeaves, b: TaintLeaves): TaintLeaves =
        if (a === b) a else leaves(a.exact + b.exact, a.any + b.any)
    override fun minus(a: TaintLeaves, b: TaintLeaves) = leaves(a.exact - b.exact, a.any - b.any)
    override fun below(p: TaintLeaves) = leaves(p.any, p.any)
    fun belowNormal(p: TaintLeaves) = leaves(MarkSet.EMPTY, p.any)
    fun belowIn(layer: Layer): (TaintLeaves) -> TaintLeaves = if (layer == Layer.NORMAL) this::belowNormal else this::below
    override fun asAny(p: TaintLeaves) = leaves(MarkSet.EMPTY, p.exact + p.any)
}

package org.opentaint.dataflow.bidi.ap

import it.unimi.dsi.fastutil.Hash
import it.unimi.dsi.fastutil.longs.Long2ObjectOpenHashMap
import it.unimi.dsi.fastutil.objects.Object2ObjectOpenCustomHashMap
import org.opentaint.dataflow.util.Cancellation
import org.opentaint.dataflow.util.SoftReferenceManager
import java.lang.ref.Reference
import java.util.ArrayDeque
import java.util.IdentityHashMap

/** One owner per store. Soft cache loss changes sharing only. */
class TrieInterner<P : TrieLeaf>(private val refs: SoftReferenceManager, private val cancellation: Cancellation) {
    private class Table<P : TrieLeaf> {
        private val buckets = Long2ObjectOpenHashMap<Object2ObjectOpenCustomHashMap<TrieNode<P>, TrieNode<P>>>()
        fun intern(node: TrieNode<P>): TrieNode<P> = buckets.computeIfAbsent(node.hash) {
            Object2ObjectOpenCustomHashMap<TrieNode<P>, TrieNode<P>>(InternStrategy)
        }.putIfAbsent(node, node) ?: node
    }

    private class Frame<P : TrieLeaf>(val node: TrieNode<P>, var next: Int = 0)
    private var cache: Reference<Table<P>>? = null
    private var operationsBeforeIntern = INTERN_RATE
    private fun table(): Table<P> = cache?.get() ?: Table<P>().also { cache = refs.createRef(it) }

    fun intern(node: TrieNode<P>): TrieNode<P> {
        if (node.interned) return node
        val table = table()
        val memo = IdentityHashMap<TrieNode<P>, TrieNode<P>>()
        val stack = ArrayDeque<Frame<P>>()
        stack.addLast(Frame(node))
        while (stack.isNotEmpty()) {
            cancellation.checkpoint()
            val frame = stack.peekLast()
            val kids = frame.node.childData
            if (kids != null && frame.next < kids.size) {
                val child = kids[frame.next++]
                if (!child.interned && !memo.containsKey(child)) stack.addLast(Frame(child))
                continue
            }
            var out = kids
            if (kids != null) for (i in kids.indices) {
                val child = memo[kids[i]] ?: kids[i]
                if (child !== kids[i]) {
                    if (out === kids) out = kids.copyOf()
                    out!![i] = child
                }
            }
            memo[frame.node] = table.intern(TrieNode(frame.node.leaf, frame.node.accessorData, out, true))
            stack.removeLast()
        }
        return checkNotNull(memo[node])
    }

    fun internIfRequired(node: TrieNode<P>): TrieNode<P> = when {
        node.size >= SIZE_TO_FORCE_INTERN -> intern(node)
        --operationsBeforeIntern > 0 || node.size < MIN_SIZE_TO_INTERN -> node
        else -> { operationsBeforeIntern = INTERN_RATE; intern(node) }
    }

    companion object {
        const val MIN_SIZE_TO_INTERN = 100L
        const val SIZE_TO_FORCE_INTERN = 100_000L
        const val INTERN_RATE = 100
    }
}

/** Child identity is sound only after bottom-up interning in this table. */
private object InternStrategy : Hash.Strategy<TrieNode<*>> {
    override fun hashCode(node: TrieNode<*>?): Int {
        if (node == null) return 0
        var hash = node.hashCode()
        node.childData?.forEach { hash = hash * 31 + System.identityHashCode(it) }
        return hash
    }

    override fun equals(a: TrieNode<*>?, b: TrieNode<*>?): Boolean {
        if (a === b) return true
        if (a == null || b == null || a.hash != b.hash || a.leaf != b.leaf ||
            !a.accessorData.contentEquals(b.accessorData)) return false
        val x = a.childData ?: return b.childData == null
        val y = b.childData ?: return false
        return x.size == y.size && x.indices.all { x[it] === y[it] }
    }
}

package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.ap.ifds.access.util.AccessorIdx
import org.opentaint.dataflow.util.Cancellation
import java.util.ArrayDeque
import java.util.IdentityHashMap

/** Pair identity is local to a traversal; node value equality remains structural. */
internal class NodePair<P : TrieLeaf>(val a: TrieNode<P>, val b: TrieNode<P>) {
    private val hash = System.identityHashCode(a) * 31 + System.identityHashCode(b)
    override fun hashCode(): Int = hash
    override fun equals(other: Any?): Boolean = other is NodePair<*> && a === other.a && b === other.b
}

private class PairFrame<P : TrieLeaf>(val pair: NodePair<P>, var expanded: Boolean = false)

private fun <P : TrieLeaf, T> mergeNodeLoop(
    a: TrieNode<P>, b: TrieNode<P>, cancellation: Cancellation?,
    same: (TrieNode<P>) -> T,
    step: (TrieNode<P>, TrieNode<P>, Map<NodePair<P>, T>) -> T,
): T {
    val results = HashMap<NodePair<P>, T>()
    val initial = NodePair(a, b)
    val stack = ArrayDeque<PairFrame<P>>()
    stack.addLast(PairFrame(initial))
    while (stack.isNotEmpty()) {
        cancellation?.checkpoint()
        val frame = stack.peekLast()
        val pair = frame.pair
        if (results.containsKey(pair)) {
            stack.removeLast()
        } else if (pair.a === pair.b) {
            results[pair] = same(pair.a)
            stack.removeLast()
        } else if (!frame.expanded) {
            frame.expanded = true
            val x = pair.a.accessorData
            val y = pair.b.accessorData
            if (x != null && y != null) {
                var i = 0
                var j = 0
                while (i < x.size && j < y.size) {
                    cancellation?.checkpoint()
                    when {
                        x[i] < y[j] -> i++
                        x[i] > y[j] -> j++
                        else -> {
                            stack.addLast(PairFrame(NodePair(pair.a.childData!![i], pair.b.childData!![j])))
                            i++
                            j++
                        }
                    }
                }
            }
        } else {
            results[pair] = step(pair.a, pair.b, results)
            stack.removeLast()
        }
    }
    return results.getValue(initial)
}

/** Return null when all children of a stay unchanged. */
private fun <P : TrieLeaf> mergeAccessors(
    a: TrieNode<P>, b: TrieNode<P>, cancellation: Cancellation?,
    onOtherNode: (AccessorIdx, TrieNode<P>) -> Unit,
    merge: (AccessorIdx, TrieNode<P>, TrieNode<P>) -> TrieNode<P>,
): Pair<IntArray, Array<TrieNode<P>>>? {
    val y = b.accessorData ?: return null
    val yc = b.childData!!
    val x = a.accessorData
    val xc = a.childData
    if (x == null) {
        for (i in y.indices) {
            cancellation?.checkpoint()
            onOtherNode(y[i], yc[i])
        }
        return y to yc
    }
    val accessors = ArrayList<Int>(x.size + y.size)
    val children = ArrayList<TrieNode<P>>(x.size + y.size)
    var i = 0
    var j = 0
    var changed = false
    while (i < x.size || j < y.size) {
        cancellation?.checkpoint()
        when {
            j == y.size || (i < x.size && x[i] < y[j]) -> {
                accessors += x[i]
                children += xc!![i++]
            }
            i == x.size || y[j] < x[i] -> {
                onOtherNode(y[j], yc[j])
                accessors += y[j]
                children += yc[j++]
                changed = true
            }
            else -> {
                val child = merge(x[i], xc!![i], yc[j])
                accessors += x[i]
                children += child
                changed = changed || child !== xc[i]
                i++
                j++
            }
        }
    }
    return if (changed) accessors.toIntArray() to children.toTypedArray() else null
}

fun <P : TrieLeaf> LeafAlgebra<P>.mergeAdd(
    a: TrieNode<P>, b: TrieNode<P>, cancellation: Cancellation? = null,
): TrieNode<P> = mergeNodeLoop(a, b, cancellation, { it }) { x, y, results ->
    val leaf = union(x.leaf, y.leaf)
    val merged = mergeAccessors(x, y, cancellation, { _, _ -> }) { _, c, d ->
        results.getValue(NodePair(c, d))
    }
    if (leaf == x.leaf && merged == null) x
    else node(leaf, merged?.first ?: x.accessorData, merged?.second ?: x.childData)
}

fun <P : TrieLeaf> LeafAlgebra<P>.mergeAddDelta(
    a: TrieNode<P>, b: TrieNode<P>, cancellation: Cancellation? = null,
): Pair<TrieNode<P>, TrieNode<P>?> =
    mergeNodeLoop<P, Pair<TrieNode<P>, TrieNode<P>?>>(a, b, cancellation, { it to null }) { x, y, results ->
        val leaf = union(x.leaf, y.leaf)
        val deltaAccessors = ArrayList<Int>()
        val deltaChildren = ArrayList<TrieNode<P>>()
        val merged = mergeAccessors(x, y, cancellation, { accessor, child ->
            deltaAccessors += accessor
            deltaChildren += child
        }) { accessor, c, d ->
            val (child, delta) = results.getValue(NodePair(c, d))
            if (delta != null) {
                deltaAccessors += accessor
                deltaChildren += delta
            }
            child
        }
        if (leaf == x.leaf && merged == null) x to null
        else {
            val delta = node(minus(y.leaf, x.leaf), deltaAccessors.toIntArray(), deltaChildren.toTypedArray())
                .takeIf { !it.isEmpty }
            node(leaf, merged?.first ?: x.accessorData, merged?.second ?: x.childData) to delta
        }
    }

internal fun ApManager.mergeAddDelta(old: Facts, new: Facts): Pair<Facts, Facts?> {
    check(old.groupKey == new.groupKey) { "T3: merge needs one group key" }
    return when (old) {
        is Reach -> old to null
        is FlowTree -> FlowAlgebra.mergeAddDelta(old.root, (new as FlowTree).root, cancellation)
            .let { (root, delta) -> old.withRoot(root) to delta?.let(old::withRoot) }
        is TaintTree -> {
            new as TaintTree
            val (root, ordinaryDelta) = taintAlg.mergeAddDelta(old.root, new.root, cancellation)
            val protected = when {
                old.nonSubsumable == null -> new.nonSubsumable
                new.nonSubsumable == null -> old.nonSubsumable
                else -> taintAlg.mergeAdd(old.nonSubsumable, new.nonSubsumable, cancellation)
            }
            val annotationDelta = new.nonSubsumable?.let { offered ->
                if (old.nonSubsumable == null) offered
                else taintAlg.minusNode(offered, old.nonSubsumable, cancellation)
            }
            val deltaRoot = when {
                ordinaryDelta == null -> annotationDelta
                annotationDelta == null -> ordinaryDelta
                else -> taintAlg.mergeAdd(ordinaryDelta, annotationDelta, cancellation)
            }
            taintTree(old.base, old.layer, root, old.exclusion, old.anyTail, protected) to
                deltaRoot?.let { taintTree(old.base, old.layer, it, old.exclusion, old.anyTail, protected) }
        }
    }
}

internal fun <P : TrieLeaf> LeafAlgebra<P>.withLeaf(n: TrieNode<P>?, leaf: P): TrieNode<P>? = when {
    n == null -> if (leaf.isEmpty) null else leafNode(leaf)
    leaf == n.leaf -> n.takeIf { !it.isEmpty }
    else -> node(leaf, n.accessorData, n.childData).takeIf { !it.isEmpty }
}

internal fun <P : TrieLeaf> LeafAlgebra<P>.mapChildren(
    n: TrieNode<P>, leaf: P, f: (AccessorIdx, TrieNode<P>) -> TrieNode<P>?,
): TrieNode<P>? = mapChildren(n, leaf, null, f)

internal fun <P : TrieLeaf> LeafAlgebra<P>.mapChildren(
    n: TrieNode<P>, leaf: P, cancellation: Cancellation?,
    f: (AccessorIdx, TrieNode<P>) -> TrieNode<P>?,
): TrieNode<P>? {
    cancellation?.checkpoint()
    val accessors = n.accessorData ?: return withLeaf(n, leaf)
    val children = n.childData!!
    val outAccessors = ArrayList<Int>(accessors.size)
    val outChildren = ArrayList<TrieNode<P>>(accessors.size)
    var changed = false
    for (i in accessors.indices) {
        cancellation?.checkpoint()
        val child = f(accessors[i], children[i])
        changed = changed || child !== children[i]
        if (child != null) {
            outAccessors += accessors[i]
            outChildren += child
        }
    }
    return if (!changed) withLeaf(n, leaf)
    else node(leaf, outAccessors.toIntArray(), outChildren.toTypedArray()).takeIf { !it.isEmpty }
}

internal fun <P : TrieLeaf> LeafAlgebra<P>.replaceChild(
    n: TrieNode<P>?, leaf: P, accessor: AccessorIdx, child: TrieNode<P>?,
): TrieNode<P>? {
    if (n?.child(accessor) === child) return withLeaf(n, leaf)
    val accessors = ArrayList<Int>()
    val children = ArrayList<TrieNode<P>>()
    var inserted = child == null
    n?.accessorData?.forEachIndexed { i, current ->
        if (!inserted && current > accessor) {
            accessors += accessor
            children += child!!
            inserted = true
        }
        if (current == accessor) {
            if (child != null) {
                accessors += current
                children += child
            }
            inserted = true
        } else {
            accessors += current
            children += n.childData!![i]
        }
    }
    if (!inserted) {
        accessors += accessor
        children += child!!
    }
    return node(leaf, accessors.toIntArray(), children.toTypedArray()).takeIf { !it.isEmpty }
}

internal fun <P : TrieLeaf> LeafAlgebra<P>.retainChildren(
    n: TrieNode<P>, pred: (AccessorIdx) -> Boolean,
): TrieNode<P>? = retainChildren(n, null, pred)

internal fun <P : TrieLeaf> LeafAlgebra<P>.retainChildren(
    n: TrieNode<P>, cancellation: Cancellation?, pred: (AccessorIdx) -> Boolean,
): TrieNode<P>? = mapChildren(n, empty, cancellation) { accessor, child -> if (pred(accessor)) child else null }

private class NodeFrame<P : TrieLeaf>(val node: TrieNode<P>, var next: Int = 0)

/** Compute each distinct input node once, children before parent. Null is a cached result too. */
private fun <P : TrieLeaf, T> walkNodes(
    root: TrieNode<P>, cancellation: Cancellation?,
    step: (TrieNode<P>, IdentityHashMap<TrieNode<P>, T>) -> T,
): T {
    val memo = IdentityHashMap<TrieNode<P>, T>()
    val stack = ArrayDeque<NodeFrame<P>>()
    stack.addLast(NodeFrame(root))
    while (stack.isNotEmpty()) {
        cancellation?.checkpoint()
        val frame = stack.peekLast()
        val children = frame.node.childData
        if (memo.containsKey(frame.node)) {
            stack.removeLast()
        } else if (children != null && frame.next < children.size) {
            val child = children[frame.next++]
            if (!memo.containsKey(child)) stack.addLast(NodeFrame(child))
        } else {
            memo[frame.node] = step(frame.node, memo)
            stack.removeLast()
        }
    }
    return memo.getValue(root)
}

fun <P : TrieLeaf> LeafAlgebra<P>.mapLeaves(
    n: TrieNode<P>, f: (P) -> P,
): TrieNode<P>? = mapLeaves(n, null, f)

fun <P : TrieLeaf> LeafAlgebra<P>.mapLeaves(
    n: TrieNode<P>, cancellation: Cancellation?, f: (P) -> P,
): TrieNode<P>? = walkNodes(n, cancellation) { current, memo ->
    mapChildren(current, intern(f(current.leaf)), cancellation) { _, child -> memo.getValue(child) }
}

/** Projection must retain the receiving algebra's leaf representative even
 * when the generic value-based withLeaf helper can reuse an equal old leaf. */
internal fun TaintAlgebra.mapCanonicalLeaves(
    n: TaintNode, cancellation: Cancellation?, f: (TaintLeaves) -> TaintLeaves,
): TaintNode? = walkNodes(n, cancellation) { current, memo ->
    val leaf = intern(f(current.leaf))
    val result = mapChildren(current, leaf, cancellation) { _, child -> memo.getValue(child) }
    if (result != null && result.leaf !== leaf) node(leaf, result.accessorData, result.childData) else result
}

/** Cached folds skip complete subtrees and do not expand shared DAGs. */
fun <P : TrieLeaf> LeafAlgebra<P>.foldAll(n: TrieNode<P>, cancellation: Cancellation? = null): P {
    val stack = ArrayDeque<NodeFrame<P>>()
    stack.addLast(NodeFrame(n))
    while (stack.isNotEmpty()) {
        cancellation?.checkpoint()
        val frame = stack.peekLast()
        if (frame.node.allLeaves != null) {
            stack.removeLast()
            continue
        }
        val children = frame.node.childData
        if (children != null && frame.next < children.size) {
            val child = children[frame.next++]
            if (child.allLeaves == null) stack.addLast(NodeFrame(child))
            continue
        }
        var leaf = frame.node.leaf
        children?.forEach {
            cancellation?.checkpoint()
            leaf = union(leaf, checkNotNull(it.allLeaves))
        }
        frame.node.allLeaves = leaf
        stack.removeLast()
    }
    return checkNotNull(n.allLeaves)
}

internal fun <P : TrieLeaf> LeafAlgebra<P>.foldLeaves(
    n: TrieNode<P>, pred: (AccessorIdx) -> Boolean,
): P = foldLeaves(n, null, pred)

internal fun <P : TrieLeaf> LeafAlgebra<P>.foldLeaves(
    n: TrieNode<P>, cancellation: Cancellation?, pred: (AccessorIdx) -> Boolean,
): P {
    cancellation?.checkpoint()
    var leaf = n.leaf
    n.accessorData?.forEachIndexed { i, accessor ->
        cancellation?.checkpoint()
        if (pred(accessor)) leaf = union(leaf, foldAll(n.childData!![i], cancellation))
    }
    return leaf
}

fun <P : TrieLeaf> LeafAlgebra<P>.prepend(m: ApManager, path: PathNode?, n: TrieNode<P>): TrieNode<P> {
    check(path == null || path.manager === m) { "A prepended path must use this AP manager" }
    m.cancellation.checkpoint()
    if (path == null || n.isEmpty) return n
    var result = n
    val accessors = path.toIntArray()
    for (i in accessors.indices.reversed()) {
        m.cancellation.checkpoint()
        result = node(empty, intArrayOf(accessors[i]), arrayOf(result))
    }
    return result
}

internal fun <P : TrieLeaf> LeafAlgebra<P>.chain(
    m: ApManager, path: IntArray, spine: List<P>, tip: TrieNode<P>? = null,
): TrieNode<P>? {
    check(spine.size.toLong() <= path.size.toLong() + 1) { "The spine exceeds its path" }
    m.cancellation.checkpoint()
    var result = tip?.takeIf { !it.isEmpty }
    if (spine.size.toLong() == path.size.toLong() + 1)
        result = withLeaf(result, union(result?.leaf ?: empty, spine[path.size]))
    for (i in path.indices.reversed()) {
        m.cancellation.checkpoint()
        result = replaceChild(null, spine.getOrNull(i) ?: empty, path[i], result)
    }
    return result
}

fun <P : TrieLeaf> LeafAlgebra<P>.minusNode(
    n: TrieNode<P>, k: TrieNode<P>, cancellation: Cancellation? = null,
): TrieNode<P>? = mergeNodeLoop(n, k, cancellation, { null as TrieNode<P>? }) { current, part, memo ->
    mapChildren(current, minus(current.leaf, part.leaf), cancellation) { accessor, child ->
        val matching = part.child(accessor)
        if (matching == null) child else memo.getValue(NodePair(child, matching))
    }
}

private class LeafFrame<P : TrieLeaf>(
    val node: TrieNode<P>, val depth: Int, var next: Int = 0, var entered: Boolean = false,
)

/** A shared subtree contributes once per path; callbacks receive owned path arrays. */
fun <P : TrieLeaf> LeafAlgebra<P>.forEachLeaf(
    n: TrieNode<P>, prefix: IntArray, f: (IntArray, P) -> Unit,
) = forEachLeaf(n, prefix, null, f)

fun <P : TrieLeaf> LeafAlgebra<P>.forEachLeaf(
    n: TrieNode<P>, prefix: IntArray, cancellation: Cancellation?, f: (IntArray, P) -> Unit,
) {
    var path = prefix.copyOf(maxOf(16, prefix.size))
    val stack = ArrayDeque<LeafFrame<P>>()
    stack.addLast(LeafFrame(n, prefix.size))
    while (stack.isNotEmpty()) {
        cancellation?.checkpoint()
        val frame = stack.peekLast()
        if (!frame.entered) {
            frame.entered = true
            if (!frame.node.leaf.isEmpty) f(path.copyOf(frame.depth), frame.node.leaf)
        }
        val accessors = frame.node.accessorData
        if (accessors == null || frame.next == accessors.size) {
            stack.removeLast()
            continue
        }
        if (frame.depth == path.size) {
            val capacity = maxOf(frame.depth.toLong() + 1, path.size.toLong() * 2)
            check(capacity <= Int.MAX_VALUE) { "A leaf path exceeds its array representation" }
            path = path.copyOf(capacity.toInt())
        }
        val i = frame.next++
        path[frame.depth] = accessors[i]
        stack.addLast(LeafFrame(frame.node.childData!![i], Math.addExact(frame.depth, 1)))
    }
}

fun <P : TrieLeaf> LeafAlgebra<P>.forEachLeafPosition(
    n: TrieNode<P>, f: (IntArray) -> Unit,
) = forEachLeafPosition(n, null, f)

fun <P : TrieLeaf> LeafAlgebra<P>.forEachLeafPosition(
    n: TrieNode<P>, cancellation: Cancellation?, f: (IntArray) -> Unit,
) = forEachLeaf(n, EMPTY_PATH, cancellation) { path, _ -> f(path) }

fun ApManager.forEachLeafPosition(f: Facts, action: (AccessPathBase, IntArray) -> Unit) {
    cancellation.checkpoint()
    when (f) {
        is Reach -> action(AccessPathBase.Zero, EMPTY_PATH)
        is FlowTree -> FlowAlgebra.forEachLeafPosition(f.root, cancellation) { action(f.base, it) }
        is TaintTree -> taintAlg.forEachLeafPosition(f.root, cancellation) { action(f.base, it) }
    }
}

fun <G : TrieLeaf, R : TrieLeaf> LeafAlgebra<R>.graft(
    g: TrieNode<G>, occurs: (G) -> Boolean, r: TrieNode<R>, cancellation: Cancellation? = null,
): TrieNode<R>? = walkNodes(g, cancellation) { current, memo ->
    val accessors = ArrayList<Int>()
    val children = ArrayList<TrieNode<R>>()
    current.accessorData?.forEachIndexed { i, accessor ->
        cancellation?.checkpoint()
        memo.getValue(current.childData!![i])?.let { child ->
            accessors += accessor
            children += child
        }
    }
    val below = node(empty, accessors.toIntArray(), children.toTypedArray()).takeIf { !it.isEmpty }
    when {
        !occurs(current.leaf) -> below
        below == null -> r.takeIf { !it.isEmpty }
        else -> mergeAdd(r, below, cancellation)
    }
}

private class SubtractKey<P : TrieLeaf>(val node: TrieNode<P>, val stored: TrieNode<P>?, val above: P) {
    private val hash = (System.identityHashCode(node) * 31 + System.identityHashCode(stored)) * 31 + above.hashCode()
    override fun hashCode(): Int = hash
    override fun equals(other: Any?): Boolean = other is SubtractKey<*> &&
        node === other.node && stored === other.stored && above == other.above
}

private class SubtractFrame<P : TrieLeaf>(val key: SubtractKey<P>, var expanded: Boolean = false)

/** Only the first step below each stored leaf reads its exclusion. Prior cover persists. */
internal fun <P : TrieLeaf> LeafAlgebra<P>.subtract(
    n: TrieNode<P>, s: TrieNode<P>?, above: P,
    at: (P) -> P, below: (P) -> P, admits: (AccessorIdx) -> Boolean = { true },
    cancellation: Cancellation? = null,
): TrieNode<P>? {
    val memo = HashMap<SubtractKey<P>, TrieNode<P>?>()
    val initial = SubtractKey(n, s, above)
    val stack = ArrayDeque<SubtractFrame<P>>()
    stack.addLast(SubtractFrame(initial))
    while (stack.isNotEmpty()) {
        cancellation?.checkpoint()
        val frame = stack.peekLast()
        val key = frame.key
        if (memo.containsKey(key)) {
            stack.removeLast()
            continue
        }
        if (key.stored == null && key.above.isEmpty) {
            memo[key] = key.node.takeIf { !it.isEmpty }
            stack.removeLast()
            continue
        }
        val next = key.stored?.let { union(key.above, below(it.leaf)) } ?: key.above
        if (!frame.expanded) {
            frame.expanded = true
            key.node.accessorData?.forEachIndexed { i, accessor ->
                cancellation?.checkpoint()
                val childKey = SubtractKey(key.node.childData!![i], key.stored?.child(accessor),
                    if (admits(accessor)) next else key.above)
                if (!memo.containsKey(childKey)) stack.addLast(SubtractFrame(childKey))
            }
        } else {
            val cover = key.stored?.let { union(key.above, at(it.leaf)) } ?: key.above
            memo[key] = mapChildren(key.node, minus(key.node.leaf, cover), cancellation) { accessor, child ->
                memo.getValue(SubtractKey(child, key.stored?.child(accessor),
                    if (admits(accessor)) next else key.above))
            }
            stack.removeLast()
        }
    }
    return memo.getValue(initial)
}

package org.opentaint.dataflow.bidi.driver

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.engine.Target
import org.opentaint.dataflow.bidi.engine.TargetSummary
import org.opentaint.dataflow.bidi.store.*
import org.opentaint.dataflow.graph.PortId

/** Only entered scopes contribute rows. A terminal uses its logical exit port.
 * Runtime routing must resolve ROOT_EXIT through the existing directed backend
 * boundary/discovery graph. It is not permission to seed all physical ports. */
data class ScopedTargetRows(
    val method: MethodKey,
    val scope: BlockScope,
    val rows: Collection<TargetSummary>,
    val exit: PortId = PortId.ROOT_EXIT,
)

/** The same AP handoff as the public method boundary, with both control ports
 * reversed. One successful normalized insertion counts as one outgoing row. */
fun projectBlockHandOff(
    ap: ApManager,
    direction: Direction,
    run1: Boolean,
    summaries: Sequence<ScopedRunSummary>,
    targets: Sequence<ScopedTargetRows>,
    demand: DemandStore.Builder,
    counts: MutableMap<MethodKey, Int>,
    onBoundary: (ScopedSummaryKey, Pattern, Pattern) -> Unit = { _, _, _ -> },
) {
    val ops = ApOps(ap)
    for ((producer, store) in summaries) {
        ap.cancellation.checkpoint()
        val next = producer.reversed()
        for ((premise, facts) in store.demandEdges(direction)) {
            ap.cancellation.checkpoint()
            if (!run1 && facts is FlowTree && facts.layer == Layer.DEMAND)
                check(facts.tail == Tail.ANY && facts.exclusion == ExclusionSet.Empty) {
                    "A restricted block FLOW demand result must be ANY with empty field exclusions"
                }
            if (direction == Direction.BACKWARD)
                check(premise is InitialAp) { "The backward run has no multi-premise summary (ap.md §9.2)" }
            for (leaf in ops.leaves(facts)) {
                ap.cancellation.checkpoint()
                val entry = guidancePattern(leaf)
                premise.forEachMember { member ->
                    ap.cancellation.checkpoint()
                    val exit = guidancePattern(member.toPattern())
                    onBoundary(producer, exit, entry)
                    if (demand.add(next.method, next.scope, next.exit, DemandPattern(entry, exit)))
                        counts.merge(next.method, 1, Int::plus)
                }
            }
        }
    }
    for (terminal in targets) {
        ap.cancellation.checkpoint()
        val next = ScopedSummaryKey(terminal.method, terminal.scope, terminal.exit).reversed()
        for (row in terminal.rows) {
            ap.cancellation.checkpoint()
            check(row.target == Target.DemandTarget) { "Only outgoing DEMAND Targets guide a later run" }
            row.premise.forEachMember { member ->
                ap.cancellation.checkpoint()
                val exit = if (member.isZero) DemandExit.Zero
                    else DemandExit.Data(guidancePattern(member.toPattern()))
                if (demand.add(next.method, next.scope, next.exit, PairedDemand(DemandEntry.Target, exit)))
                    counts.merge(next.method, 1, Int::plus)
            }
        }
    }
}

package org.opentaint.dataflow.bidi.driver

import mu.KLogging
import org.opentaint.dataflow.bidi.ap.Direction
import org.opentaint.dataflow.bidi.ap.MethodKey
import org.opentaint.dataflow.bidi.engine.RunConfig
import org.opentaint.dataflow.bidi.engine.RunMethodAnalyzer
import org.opentaint.dataflow.bidi.engine.RunResult
import org.opentaint.dataflow.bidi.engine.RunStatus
import java.util.Collections

enum class DemandCause { FIELD_LIMIT_CUT, MAY_TARGET, CLEANER_ROW, MUST_RECORD, DEMAND_INPUT }

/** A completed run's owned keys and counts. No edge or run store is retained. */
class Frontier(
    val run: Int,
    val direction: Direction,
    analysed: Set<MethodKey>,
    demandEdges: Map<MethodKey, Int>,
    val recordCrossings: Long,
    val targetDemand: Int,
    val reportedSinks: Int,
    val seeds: Int,
    zeroOnly: Set<MethodKey>,
    val zeroOnlyEdges: Long,
    demandByCause: Map<DemandCause, Long>? = null,
) {
    val analysed: Set<MethodKey> = Collections.unmodifiableSet(LinkedHashSet(analysed))
    val demandEdges: Map<MethodKey, Int> = Collections.unmodifiableMap(LinkedHashMap(demandEdges))
    val zeroOnly: Set<MethodKey> = Collections.unmodifiableSet(LinkedHashSet(zeroOnly))
    val demandByCause: Map<DemandCause, Long>? = demandByCause?.let {
        Collections.unmodifiableMap(LinkedHashMap(it))
    }
}

/** The barrier reads counters only after all method owners have joined and frozen. */
fun frontierOf(config: RunConfig, result: RunResult<RunMethodAnalyzer>, handOff: HandOff,
               reportedSinks: Int): Frontier {
    check(result.status == RunStatus.COMPLETE) { "A frontier needs a complete run" }
    val analysed = LinkedHashSet<MethodKey>()
    val zeroOnly = LinkedHashSet<MethodKey>()
    var zeroOnlyEdges = 0L
    var recordCrossings = 0L
    for (actor in result.analyzers) {
        actor.ap.cancellation.checkpoint()
        if (actor.nonZeroInitial) analysed += actor.key
        else {
            zeroOnly += actor.key
            zeroOnlyEdges += actor.edgeDeltas
        }
        recordCrossings += actor.recordCrossings
    }
    val cancellation = result.analyzers.firstOrNull()?.ap?.cancellation
    val counts = LinkedHashMap<MethodKey, Int>()
    for ((key, count) in handOff.demandEdges) {
        cancellation?.checkpoint()
        counts[key] = count
    }
    cancellation?.checkpoint()
    val forward = config.direction == Direction.FORWARD
    return Frontier(config.index, config.direction, analysed, counts, recordCrossings,
        result.analyzers.sumOf { it.outgoingTargets.size } +
            result.analyzers.asSequence().flatMap { it.blockOutgoingTargets() }.sumOf { it.rows.size },
        reportedSinks, handOff.seeds.size, zeroOnly, zeroOnlyEdges)
}

private val frontierLogger = object : KLogging() {}.logger

fun Frontier.log() {
    frontierLogger.info {
        "Run $run ($direction) frontier: analysed ${analysed.size}, demand edges ${demandEdges.values.sum()} " +
            "in ${demandEdges.size} method keys, left ${(analysed - demandEdges.keys).size}, " +
            "record crossings $recordCrossings, target demand $targetDemand, reports " +
            "$reportedSinks, seeds $seeds, zero only ${zeroOnly.size} ($zeroOnlyEdges edges)"
    }
    frontierLogger.debug { "Run $run frontier: analysed $analysed; demand edges $demandEdges" }
    demandByCause?.let { frontierLogger.info { "Run $run demand-layer results per cause: $it" } }
}

package org.opentaint.dataflow.bidi.driver

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.engine.RunConfig
import org.opentaint.dataflow.bidi.engine.RunMethodAnalyzer
import org.opentaint.dataflow.bidi.engine.RunResult
import org.opentaint.dataflow.bidi.engine.RunStatus
import org.opentaint.dataflow.bidi.engine.SharedObjects
import org.opentaint.dataflow.bidi.interp.SinkRule
import org.opentaint.dataflow.bidi.store.DemandStore
import org.opentaint.dataflow.bidi.store.FrozenStaticCompletion
import org.opentaint.dataflow.bidi.store.guidancePattern
import org.opentaint.dataflow.bidi.store.DemandEntry
import org.opentaint.dataflow.bidi.store.DemandExit
import org.opentaint.dataflow.bidi.store.PairedDemand
import org.opentaint.ir.api.common.cfg.CommonInst
import java.util.Collections
import mu.KotlinLogging
import kotlin.time.TimeSource

/** Immutable outgoing demand, seeds and accepted explicit-pattern counts.
 * [of] counts only successful normalized builder insertions. Its method-key support is
 * empty exactly when the built explicit snapshot is empty; virtual static families are separate.
 * Manually constructed test values need not have that binding.
 */
class HandOff(val demand: DemandStore, val seeds: SeedIndex, demandEdges: Map<MethodKey, Int>) {
    val demandEdges: Map<MethodKey, Int> = Collections.unmodifiableMap(LinkedHashMap(demandEdges))

    companion object {
        private val logger = KotlinLogging.logger {}
        fun of(config: RunConfig, result: RunResult<RunMethodAnalyzer>, shared: SharedObjects): HandOff {
            check(result.status == RunStatus.COMPLETE) { "A hand-off needs a complete run" }
            shared.cancellation.checkpoint()
            val counts = LinkedHashMap<MethodKey, Int>()
            val (demand, seeds) = if (config.direction == Direction.FORWARD)
                toBackward(result, shared, counts, config.run1) else toForward(result, shared, counts)
            return HandOff(demand, seeds, counts)
        }

        private inline fun forEachDemandPiece(result: RunResult<RunMethodAnalyzer>, shared: SharedObjects,
                                             direction: Direction,
                                             body: (MethodKey, PremiseKey, Pattern) -> Unit) {
            for (actor in result.analyzers) {
                shared.cancellation.checkpoint()
                for ((premise, facts) in actor.summaries.demandEdges(direction)) {
                    shared.cancellation.checkpoint()
                    if (!actor.mode.run1 && facts is FlowTree && facts.layer == Layer.DEMAND)
                        check(facts.tail == Tail.ANY && facts.exclusion == ExclusionSet.Empty) {
                            "A restricted FLOW demand result must be ANY with empty field exclusions"
                        }
                    for (leaf in shared.ops.leaves(facts)) {
                        shared.cancellation.checkpoint()
                        body(actor.key, premise, leaf)
                    }
                }
            }
        }

        private fun toBackward(result: RunResult<RunMethodAnalyzer>, shared: SharedObjects,
                               counts: MutableMap<MethodKey, Int>, run1: Boolean): Pair<DemandStore, SeedIndex> {
            val demand = DemandStore.Builder(shared.ap)
            val completionStart = TimeSource.Monotonic.markNow()
            val joinedCompletion = if (run1) result.staticCompletion else null
            val completion = if (run1 && joinedCompletion == null)
                FrozenStaticCompletion.Builder(shared.ap, shared.staticCallGraph) else null
            if (run1) demand.withSharedStaticCarry()
            if (joinedCompletion != null) {
                demand.withCompletion(joinedCompletion)
                for ((owner, view) in joinedCompletion.scopedViews())
                    demand.withCompletion(owner.method, owner.local, view)
                logger.info { "BIDI_STATIC_CLOSURE_HANDOFF run=1 source=JOINED ${joinedCompletion.statistics()}" }
            }
            // Synthetic frozen RunResults in small tests have no runner-owned
            // pre-release phase. Their fallback uses local seeds only; real
            // RunManager results supply the joined completion above.
            if (completion != null) {
                for (actor in result.analyzers) {
                    for (edge in actor.staticGuidanceSeeds.frozenRows()) {
                        shared.cancellation.checkpoint()
                        completion.addSeed(actor.key, edge)
                    }
                    for (key in actor.freezeStaticWriteCandidates().lostRows()) {
                        shared.cancellation.checkpoint()
                        completion.addSeed(actor.key, key.original.toPattern(), key.result)
                    }
                    for (terminal in actor.outgoingTargets) {
                        shared.cancellation.checkpoint()
                        check(terminal.target == org.opentaint.dataflow.bidi.engine.Target.DemandTarget)
                        val original = checkNotNull(terminal.premise as? InitialAp) { "Run-1 cannot retain an ND original" }
                        completion.addTarget(actor.key, original.toPattern())
                    }
                }
            }
            val seedCaptureTime = completionStart.elapsedNow()
            val projectionStart = TimeSource.Monotonic.markNow()
            forEachDemandPiece(result, shared, Direction.FORWARD) { method, premise, piece ->
                val entry = guidancePattern(piece)
                premise.forEachMember { member ->
                    shared.cancellation.checkpoint()
                    val from = guidancePattern(member.toPattern())
                    completion?.addBoundary(method, from, entry)
                    val pattern = DemandPattern(entry, from)
                    if (demand.add(method, pattern)) counts.merge(method, 1, Int::plus)
                }
            }
            projectTargets(result, shared, demand, counts)
            projectBlocks(result, shared, Direction.FORWARD, run1, demand, counts, completion)
            if (completion != null) {
                val projectionTime = projectionStart.elapsedNow()
                val indexStart = TimeSource.Monotonic.markNow()
                val frozen = completion.build()
                demand.withCompletion(frozen)
                for ((owner, view) in frozen.scopedViews()) demand.withCompletion(owner.method, owner.local, view)
                logger.info { "BIDI_STATIC_CLOSURE_FREEZE run=1 source=LOCAL_FROZEN_INPUT freezeTime=${completionStart.elapsedNow()} seedTime=$seedCaptureTime projectionTime=$projectionTime indexTime=${indexStart.elapsedNow()} ${frozen.statistics()}" }
            }
            val seeds = result.analyzers.flatMap { it.sinkSeeds }
            return demand.build() to SeedIndex.of(seeds)
        }

        private fun projectTargets(result: RunResult<RunMethodAnalyzer>, shared: SharedObjects,
                                   demand: DemandStore.Builder, counts: MutableMap<MethodKey, Int>) {
            for (actor in result.analyzers) for (row in actor.outgoingTargets) {
                shared.cancellation.checkpoint()
                for (member in row.premise.members) {
                    val exit = if (member.isZero) DemandExit.Zero
                        else DemandExit.Data(guidancePattern(member.toPattern()))
                    if (demand.add(actor.key, PairedDemand(DemandEntry.Target, exit)))
                        counts.merge(actor.key, 1, Int::plus)
                }
            }
        }

        private fun projectBlocks(result: RunResult<RunMethodAnalyzer>, shared: SharedObjects,
                                  direction: Direction, run1: Boolean,
                                  demand: DemandStore.Builder, counts: MutableMap<MethodKey, Int>,
                                  completion: FrozenStaticCompletion.Builder? = null) {
            projectBlockHandOff(shared.ap, direction, run1,
                result.analyzers.asSequence().flatMap { it.blockSummaries() },
                result.analyzers.asSequence().flatMap { it.blockOutgoingTargets() }, demand, counts,
                onBoundary = { key, from, to -> completion?.addScopedSeed(key, from, to) })
            if (run1 && completion != null) for (actor in result.analyzers)
                for (terminal in actor.blockOutgoingTargets()) for (row in terminal.rows) {
                    val original = checkNotNull(row.premise as? InitialAp) { "Run-1 cannot retain an ND original" }
                    completion.addScopedTarget(org.opentaint.dataflow.bidi.store.ScopedSummaryKey(
                        terminal.method, terminal.scope, terminal.exit), original.toPattern())
                }
        }

        private fun toForward(result: RunResult<RunMethodAnalyzer>, shared: SharedObjects,
                              counts: MutableMap<MethodKey, Int>): Pair<DemandStore, SeedIndex> {
            val demand = DemandStore.Builder(shared.ap)
            forEachDemandPiece(result, shared, Direction.BACKWARD) { method, premise, piece ->
                val pattern = when (premise) {
                    is InitialAp -> DemandPattern(guidancePattern(piece),
                        guidancePattern(premise.toPattern()))
                    is PremiseSet -> error("The backward run has no multi-premise summary (ap.md §9.2)")
                }
                if (demand.add(method, pattern)) counts.merge(method, 1, Int::plus)
            }
            projectTargets(result, shared, demand, counts)
            projectBlocks(result, shared, Direction.BACKWARD, false, demand, counts)
            val seeds = ArrayList<Seed>()
            for (actor in result.analyzers) {
                shared.cancellation.checkpoint()
                for ((method, statement, edge, action) in checkNotNull(actor.sourceHits).occurrences()) {
                    shared.cancellation.checkpoint()
                    seeds += Seed.Source(method, statement, edge, action)
                }
            }
            return demand.build() to SeedIndex.of(seeds)
        }
    }
}

/** Use the same predicate handle and literal seeds as the previous handoff. */
internal fun sinkSeedsFor(sink: SinkRule, method: MethodKey, at: CommonInst): List<Seed> = when {
    sink.predicate != null && !sink.unconditional ->
        listOf(Seed.PredicateSink(checkNotNull(sink.occurrenceId), method, at))
    sink.predicate != null -> emptyList()
    else -> sink.seedPatterns().map { Seed.Sink(sink.rule, method, at, it) }
}

/** GROUP evaluation must retain the original FULL seed patterns, as before.
 * Read the existing full form; do not keep a second seed or rule cache. */
internal fun fullSinkSeedsFor(shared: SharedObjects, sink: SinkRule,
                              method: MethodKey, at: CommonInst): List<Seed> {
    val seeds = LinkedHashSet<Seed>()
    withSinksAt(shared, method, at) { sinks ->
        for (full in sinks) {
            shared.cancellation.checkpoint()
            if (full.rule == sink.rule) seeds += sinkSeedsFor(full, method, at)
        }
    }
    return seeds.toList()
}

/** Existing full-form lookup used by sink handoff before terminal reporting. */
private fun withSinksAt(shared: SharedObjects, key: MethodKey, statement: CommonInst,
                       use: (List<SinkRule>) -> Unit) {
    val forms = shared.contexts.forms(key)
    val call = shared.language.getCallExpr(statement)
    if (call != null) forms.withCall(Direction.FORWARD, statement, call) { use(it.sinks) }
    else if (shared.interpreter.exitNodes(key).any {
        shared.cancellation.checkpoint(); it.node == statement
    }) forms.withExitRules(Direction.FORWARD, statement) { use(it.rules.sinks) }
}

package org.opentaint.dataflow.bidi.driver

import mu.KLogging
import org.opentaint.dataflow.bidi.ap.Direction
import org.opentaint.dataflow.bidi.ap.MethodKey
import org.opentaint.dataflow.bidi.ap.MarkMode
import org.opentaint.dataflow.bidi.ap.TaintMark
import org.opentaint.dataflow.bidi.engine.MethodCallServicesFactory
import org.opentaint.dataflow.bidi.engine.MethodLocalServicesFactory
import org.opentaint.dataflow.bidi.engine.RunConfig
import org.opentaint.dataflow.bidi.engine.RunManager
import org.opentaint.dataflow.bidi.engine.LoopPipelineTrace
import org.opentaint.dataflow.bidi.engine.RunMethodAnalyzer
import org.opentaint.dataflow.bidi.engine.RunMethodCallServices
import org.opentaint.dataflow.bidi.engine.RunMethodHandlers
import org.opentaint.dataflow.bidi.engine.RunMethodLocalServices
import org.opentaint.dataflow.bidi.engine.RunResult
import org.opentaint.dataflow.bidi.engine.RunStatus
import org.opentaint.dataflow.bidi.engine.SharedObjects
import org.opentaint.dataflow.bidi.engine.readRun1MarkMode
import org.opentaint.dataflow.bidi.store.RelationCensus
import org.opentaint.dataflow.util.Cancellation
import org.opentaint.dataflow.util.MemoryManager
import java.util.Collections
import kotlin.time.Duration
import kotlin.time.TimeSource

/** Runs fresh engines in sequence and reads their stores only after all runners join. */
class IterationDriver internal constructor(
    private val policy: IterationPolicy,
    private val shared: SharedObjects,
    private val budget: Duration,
    private val invokeRun: (RunConfig, SharedObjects, Duration) -> RunResult<RunMethodAnalyzer>,
    private val guardBarrier: (SharedObjects, () -> Next) -> Next,
) {
    constructor(policy: IterationPolicy, shared: SharedObjects, budget: Duration) :
        this(policy, shared, budget, ::runEngine, ::withBarrierGuard)

    private val run1MarkMode = readRun1MarkMode()
    private val fieldLimitSchedule = policy.fieldLimitSchedule
    private val frontierLog = ArrayList<Frontier>()
    val frontiers: List<Frontier> get() = Collections.unmodifiableList(ArrayList(frontierLog))

    fun analyze(roots: List<MethodKey>): Report {
        val start = TimeSource.Monotonic.markNow()
        val report = ReportBuilder()
        var index = 1
        fun end(status: RunStatus, reason: EndReason): Report {
            logger.info { "BIDI_ANALYSIS_END run=$index status=$status reason=$reason elapsed=${start.elapsedNow()}" }
            return report.build(AnalysisEnd(status, index,
                if (index % 2 == 1) Direction.FORWARD else Direction.BACKWARD, reason, run1MarkMode))
        }
        try {
            logger.info { "BIDI_FIELD_LIMIT_SCHEDULE schedule=$fieldLimitSchedule" }
            val firstLimit = policy.fieldLimit(1)
            require(firstLimit == 1) { "F78: selected run 1 needs field limit exactly 1" }
            var config = RunConfig(1, firstLimit, demand = null, records = shared.records.view(),
                seeds = SeedIndex.EMPTY, roots = roots, run1MarkMode = run1MarkMode,
                fieldLimitSchedule = fieldLimitSchedule)
            while (true) {
                index = config.index
                val selectedTimeout = policy.timeout(config, budget - start.elapsedNow())
                // The callback consumes this same budget and cannot extend it.
                val timeout = minOf(selectedTimeout, budget - start.elapsedNow())
                when (val next = runOnce(config, report, timeout)) {
                    is Next.Run -> config = next.config
                    is Next.End -> return end(next.status, next.reason)
                }
            }
        } catch (error: Throwable) {
            logger.error(error) { "Run $index failed; the analysis ends with the report so far" }
            return end(RunStatus.FAILED, EndReason.ABNORMAL)
        }
    }

    /** This frame releases its result before the next engine is created. */
    private fun runOnce(config: RunConfig, report: ReportBuilder, timeout: Duration): Next {
        val start = TimeSource.Monotonic.markNow()
        logger.info { "BIDI_RUN_START run=${config.index} direction=${config.direction} limit=${config.fieldLimit} timeout=$timeout markMode=${config.mode.markMode}" }
        logOptimizationStatistics(config, "START")
        val result = try {
            invokeRun(config, shared, timeout)
        } catch (error: Throwable) {
            logger.info { "BIDI_RUN_END run=${config.index} status=FAILED engineTime=${start.elapsedNow()}" }
            logOptimizationStatistics(config, "END")
            throw error
        } finally {
            // Diagnostic counters only. Engine workers have joined before this callback returns.
            LoopPipelineTrace.finishRun(config.index)
        }
        logger.info { "BIDI_JOINED_RELEASE run=${config.index} sealReleaseTime=${result.joinedSealReleaseTime} status=${result.status}" }
        val engineTime = (start.elapsedNow() - result.joinedStaticBindingTime).coerceAtLeast(Duration.ZERO)
        logger.info { "BIDI_RUN_END run=${config.index} status=${result.status} engineTime=$engineTime" }
        if (config.run1 && config.mode.markMode == MarkMode.FULL && result.status == RunStatus.COMPLETE) {
            logger.info { "BIDI_FLOW_BACKED_STATISTICS run=${config.index} neutralBatches=${result.analyzers.sumOf { it.neutralBatchApplications }} neutralMemberships=${result.analyzers.sumOf { it.neutralBatchMemberships }} bulkStorePackets=${result.analyzers.sumOf { it.neutralBulkStorePackets }} bulkStoreMemberships=${result.analyzers.sumOf { it.neutralBulkStoreMemberships }} scalarStoreFallbackMemberships=${result.analyzers.sumOf { it.neutralScalarFallbackMemberships }}" }
        }
        if (shared.n2Statistics != null && result.status == RunStatus.COMPLETE) {
            logger.info {
                "BIDI_CFG_DELIVERY_STATISTICS run=${config.index} hits=${result.analyzers.sumOf { it.cfgDeliveryHits }} " +
                    "searches=${result.analyzers.sumOf { it.cfgDeliverySearches }} " +
                    "visitedNodes=${result.analyzers.sumOf { it.cfgDeliveryVisitedNodes }} " +
                    "destinations=${result.analyzers.sumOf { it.cfgDeliveryDestinations }} " +
                    "maxWidth=${result.analyzers.maxOfOrNull { it.cfgDeliveryMaxWidth } ?: 0}"
            }
        }
        if (shared.n2Statistics != null) {
            val loopMethods = result.analyzers.mapNotNull { actor -> actor.blockDiagnostics()?.let { actor to it } }
            logger.info { "BIDI_LOOP_BLOCK_STATISTICS run=${config.index} methods=${loopMethods.size}" }
            for ((actor, summary) in loopMethods.sortedByDescending { it.first.steps }.take(24)) logger.info {
                "BIDI_LOOP_BLOCK_METHOD run=${config.index} method=${actor.key} $summary"
            }
            val measured = result.analyzers.mapNotNull { actor -> actor.bodyWorkSnapshot?.let { actor.key to it } }
            logger.info {
                "BIDI_BODY_WORK_STATISTICS run=${config.index} scope=packet-events " +
                    "snapshotActors=${measured.size} unavailableActors=${result.analyzers.size - measured.size} " +
                    "processed=${measured.sumOf { it.second.processedPackets }} " +
                    "freshPostS=${measured.sumOf { it.second.freshPackets }} " +
                    "candidateOffers=${measured.sumOf { it.second.candidatePackets }} " +
                    "methodCandidateOffers=${measured.sumOf { it.second.methodCandidatePackets }} " +
                    "blockCandidateOffers=${measured.sumOf { it.second.blockCandidatePackets }} " +
                    "cyclicProcessed=${measured.sumOf { it.second.cyclicProcessedPackets }} " +
                    "cyclicFreshPostS=${measured.sumOf { it.second.cyclicFreshPackets }} " +
                    "sampledPackets=${(0..2).map { stage -> measured.sumOf { it.second.sampledPackets[stage] } }} " +
                    "sampledMemberships=${(0..2).map { stage -> measured.sumOf { it.second.sampledMemberships[stage] } }} " +
                    "droppedSamples=${measured.sumOf { it.second.droppedSamples }}"
            }
            val hot = (measured.sortedByDescending { it.second.processedPackets }.take(12) +
                measured.sortedByDescending { it.second.candidatePackets }.take(12)).distinctBy { it.first }
            for ((method, snapshot) in hot) logger.info {
                "BIDI_BODY_WORK_METHOD run=${config.index} method=$method snapshot=$snapshot"
            }
            // Only copied IDs from bounded hot-method samples enter this read-only dictionary.
            val fieldIds = hot.asSequence().flatMap { it.second.samples.asSequence() }.flatMap { sample ->
                (sample.firstPath + sample.initials.flatMap { it.path }).asSequence()
            }.distinct().take(256).toList()
            val markIds = hot.asSequence().flatMap { it.second.samples.asSequence() }.flatMap { sample ->
                (sample.exampleMarkIds + sample.initials.mapNotNull { it.concreteMark }).asSequence()
            }.distinct().take(256).toList()
            for (id in fieldIds) logger.info {
                "BIDI_BODY_FIELD run=${config.index} id=$id accessor=${shared.ap.accessors.accessor(id)}"
            }
            for (id in markIds) logger.info {
                "BIDI_BODY_MARK run=${config.index} id=$id name=${shared.ap.marks.name(TaintMark(id))} key=${shared.ap.marks.key(TaintMark(id))}"
            }
            // These are scalar-store end-state gauges, not cumulative edge work.
            // Cancelled/live actors need a heap census; absent snapshots are not zero.
            val snapshots = result.analyzers.mapNotNull { it.scalarIdentityStatistics }
            val reasons = sortedMapOf<String, Long>()
            for (snapshot in snapshots) for ((reason, count) in snapshot.fallbackReasons)
                reasons[reason] = (reasons[reason] ?: 0L) + count
            logger.info {
                "BIDI_IDENTITY_STORAGE_STATISTICS run=${config.index} scope=frozen-scalar-stores " +
                    "snapshotActors=${snapshots.size} unavailableActors=${result.analyzers.size - snapshots.size} " +
                    "compactPoints=${snapshots.sumOf { it.compactPoints }} " +
                    "compactNormal=${snapshots.sumOf { it.compactNormal }} compactDemand=${snapshots.sumOf { it.compactDemand }} " +
                    "compactFlow=${snapshots.sumOf { it.compactFlow }} compactTaint=${snapshots.sumOf { it.compactTaint }} " +
                    "protectedNormal=${snapshots.sumOf { it.protectedNormal }} protectedDemand=${snapshots.sumOf { it.protectedDemand }} " +
                    "fullPoints=${snapshots.sumOf { it.fullPoints }} promotedPoints=${snapshots.sumOf { it.promotedPoints }} " +
                    "firstFullPoints=${snapshots.sumOf { it.firstFullPoints }} bitWords=${snapshots.sumOf { it.bitWords }} " +
                    "fullArrayCapacity=${snapshots.sumOf { it.fullArrayCapacity }} fallbackReasons=$reasons"
            }
        }
        logOptimizationStatistics(config, "END")
        config.demand?.staticCompletionStatistics()?.let {
            logger.info { "BIDI_STATIC_CLOSURE_LOOKUP run=${config.index} $it" }
        }
        config.demand?.diagnosticC5Samples()?.forEach { sample ->
            logger.info { "BIDI_C5_ROW_SAMPLE run=${config.index} $sample" }
        }
        if (result.status != RunStatus.COMPLETE) return Next.End(result.status)
        val barrierStart = TimeSource.Monotonic.markNow()
        val next = try {
            guardBarrier(shared) { barrier(config, result, report) }
        } catch (error: Cancellation.Cancelled) {
            Next.End(RunStatus.OOM)
        } finally {
            logger.info { "BIDI_BARRIER_END run=${config.index} barrierTime=${barrierStart.elapsedNow()} iterationTime=${start.elapsedNow()}" }
            if (config.run1) shared.releaseRun1CatalogCoverage()
        }
        if (shared.cancellation.isActive()) return next
        logger.error { "Run ${config.index}: the barrier memory guard fired; the analysis ends with the report so far" }
        return Next.End(RunStatus.OOM)
    }

    private fun logOptimizationStatistics(config: RunConfig, phase: String) {
        shared.abstractionStatistics?.let { statistics ->
            logger.info { "BIDI_ABSTRACTION_STATISTICS run=${config.index} direction=${config.direction} limit=${config.fieldLimit} phase=$phase totals=${statistics.snapshot()}" }
        }
        shared.n1Statistics?.let { statistics ->
            logger.info { "BIDI_N1_STATISTICS run=${config.index} direction=${config.direction} limit=${config.fieldLimit} phase=$phase totals=${statistics.snapshot()}" }
        }
        shared.n2Statistics?.let { statistics ->
            logger.info { "BIDI_N2_STATISTICS run=${config.index} direction=${config.direction} limit=${config.fieldLimit} phase=$phase totals=${statistics.snapshot()}" }
        }
        shared.requestBatchStatistics?.let { statistics ->
            logger.info { "BIDI_REQUEST_BATCH_STATISTICS run=${config.index} direction=${config.direction} limit=${config.fieldLimit} phase=$phase totals=${statistics.snapshot()}" }
        }
    }

    private fun barrier(config: RunConfig, result: RunResult<RunMethodAnalyzer>, report: ReportBuilder): Next {
        if (shared.n2Statistics != null) {
            val censusStart = TimeSource.Monotonic.markNow()
            val publicAdmitted = result.analyzers.fold(RelationCensus()) { counts, actor -> counts + actor.summaries.census() }
            val publicOutgoing = result.analyzers.fold(RelationCensus()) { counts, actor -> counts + actor.summaries.demandCensus(config.direction) }
            val blockAdmitted = result.analyzers.asSequence().flatMap { it.blockSummaries() }
                .fold(RelationCensus()) { counts, block -> counts + block.summaries.census() }
            val blockOutgoing = result.analyzers.asSequence().flatMap { it.blockSummaries() }
                .fold(RelationCensus()) { counts, block -> counts + block.summaries.demandCensus(config.direction) }
            val admitted = publicAdmitted + blockAdmitted
            val outgoing = publicOutgoing + blockOutgoing
            logger.info { "BIDI_FLOW_BACKED_CENSUS run=${config.index} admitted=$admitted outgoing=$outgoing blockAdmitted=$blockAdmitted blockOutgoing=$blockOutgoing scanTime=${censusStart.elapsedNow()}" }
        }
        val forward = config.direction == Direction.FORWARD
        val terminals = report.prepare(config, result, shared)
        shared.records.persistCompleted(config.direction, result.analyzers.asSequence().map { it.key to it.summaries },
            result.analyzers.asSequence().flatMap { it.blockSummaries() })
        val handOff = HandOff.of(config, result, shared)
        val frontier = frontierOf(config, result, handOff, terminals.entries.size)
        frontierLog += frontier
        frontier.log()
        val next = when {
            forward && handOff.demandEdges.isEmpty() -> Next.End(RunStatus.COMPLETE, EndReason.NO_DEMAND_EDGE)
            forward && !policy.continueAfter(config, result, frontiers) -> Next.End(RunStatus.COMPLETE, EndReason.POLICY)
            else -> Next.Run(nextConfig(config, handOff, terminals.normal))
        }
        logger.info { "BIDI_TARGET_STATISTICS run=${config.index} raw=${result.analyzers.sumOf { it.targets.size }} outgoing=${result.analyzers.sumOf { it.outgoingTargets.size }} reports=${terminals.entries.size} blockRaw=${result.analyzers.asSequence().flatMap { it.blockTargets() }.sumOf { it.rows.size }} blockOutgoing=${result.analyzers.asSequence().flatMap { it.blockOutgoingTargets() }.sumOf { it.rows.size }}" }
        // All fallible preparation precedes this single terminal/report commit.
        shared.cancellation.checkpoint()
        if (forward && config.mode.markMode == MarkMode.FULL) {
            shared.normalRuleContributors.publish(result.analyzers.asSequence()
                .flatMap { it.normalContributorRows() }.asIterable())
        }
        report.commit(terminals)
        return next
    }

    private fun nextConfig(config: RunConfig, handOff: HandOff, normalTargets: org.opentaint.dataflow.bidi.engine.NormalTargetView): RunConfig {
        val index = config.index + 1
        val limit = policy.fieldLimit(index)
        require(limit >= config.fieldLimit) { "ap.md W3: the field limit must not decrease" }
        return RunConfig(index, limit, handOff.demand, shared.records.view(), handOff.seeds, config.roots,
            run1MarkMode = run1MarkMode, fieldLimitSchedule = fieldLimitSchedule, normalTargets = normalTargets)
    }

    companion object : KLogging() {
        const val BARRIER_MEMORY_THRESHOLD = 0.99
    }
}

private fun runEngine(config: RunConfig, shared: SharedObjects, timeout: Duration): RunResult<RunMethodAnalyzer> =
    RunManager(config, shared, RunMethodHandlers(MethodLocalServicesFactory(::RunMethodLocalServices),
        MethodCallServicesFactory(::RunMethodCallServices))).run(timeout)

private fun withBarrierGuard(shared: SharedObjects, body: () -> Next): Next =
    MemoryManager(shared.refManager, IterationDriver.BARRIER_MEMORY_THRESHOLD) { shared.cancellation.cancel() }
        .runWithMemoryManager(body)

package org.opentaint.dataflow.bidi.driver

import org.opentaint.dataflow.bidi.engine.RunConfig
import org.opentaint.dataflow.bidi.engine.RunMethodAnalyzer
import org.opentaint.dataflow.bidi.engine.RunResult
import org.opentaint.dataflow.bidi.engine.RunStatus
import java.util.Collections
import kotlin.time.Duration

interface IterationPolicy {
    val fieldLimitSchedule: FieldLimitSchedule get() = FieldLimitSchedule.REPEAT_RUN1
    fun fieldLimit(runIndex: Int): Int

    /** Called only after a complete forward run and the two fixed stop checks. */
    fun continueAfter(run: RunConfig, result: RunResult<RunMethodAnalyzer>, frontiers: List<Frontier>): Boolean

    fun timeout(run: RunConfig, remaining: Duration): Duration = remaining
}

/** RUN_INDEX is an opt-in experiment. The normal schedule stays unchanged. */
enum class FieldLimitSchedule {
    REPEAT_RUN1, RUN_INDEX;

    fun fieldLimit(runIndex: Int): Int {
        require(runIndex >= 1) { "The run index must be positive" }
        return when (this) {
            REPEAT_RUN1 -> maxOf(1, runIndex - 1)
            RUN_INDEX -> runIndex
        }
    }
}

/** Run 1 and the first exact backward run both use field limit 1. */
object IncreasingLimits : IterationPolicy {
    override fun fieldLimit(runIndex: Int): Int = fieldLimitSchedule.fieldLimit(runIndex)

    override fun continueAfter(run: RunConfig, result: RunResult<RunMethodAnalyzer>, frontiers: List<Frontier>): Boolean = true
}

object RunIndexLimits : IterationPolicy {
    override val fieldLimitSchedule: FieldLimitSchedule = FieldLimitSchedule.RUN_INDEX
    override fun fieldLimit(runIndex: Int): Int = fieldLimitSchedule.fieldLimit(runIndex)

    override fun continueAfter(run: RunConfig, result: RunResult<RunMethodAnalyzer>, frontiers: List<Frontier>): Boolean = true
}

/** The project entry point reads the setting once when it selects the policy. */
fun configuredIncreasingLimits(
    value: String? = System.getProperty("opentaint.bidi.fieldLimitSchedule"),
): IterationPolicy = when (value) {
    null, "REPEAT_RUN1" -> IncreasingLimits
    "RUN_INDEX" -> RunIndexLimits
    else -> error("Invalid opentaint.bidi.fieldLimitSchedule=$value; use REPEAT_RUN1 or RUN_INDEX")
}

class FixedLimits(limits: List<Int>) : IterationPolicy {
    private val limits: List<Int> = Collections.unmodifiableList(ArrayList(limits))

    override fun fieldLimit(runIndex: Int): Int = limits[runIndex - 1]

    override fun continueAfter(run: RunConfig, result: RunResult<RunMethodAnalyzer>, frontiers: List<Frontier>): Boolean =
        run.index + 2 <= limits.size
}

sealed interface Next {
    class Run(val config: RunConfig) : Next
    class End(val status: RunStatus, val reason: EndReason = EndReason.ABNORMAL) : Next
}

package org.opentaint.dataflow.bidi.driver

import org.opentaint.dataflow.bidi.ap.Direction
import org.opentaint.dataflow.bidi.ap.MarkMode
import org.opentaint.dataflow.bidi.engine.*
import java.util.Collections

enum class EndReason { STOP_RULE, NO_DEMAND_EDGE, POLICY, ABNORMAL }

data class AnalysisEnd(
    val status: RunStatus, val run: Int, val direction: Direction, val reason: EndReason,
    val run1MarkMode: MarkMode = MarkMode.FULL,
)

/** Only settled configured-root ZERO terminal identities enter the report. */
class Report(entries: List<Entry>, val end: AnalysisEnd) {
    val entries: List<Entry> = Collections.unmodifiableList(ArrayList(entries))
    data class Entry(val id: ReportId, val descriptor: ReportDescriptor)
}

/** One completed driver barrier commits retained relations and root reports together. */
class ReportBuilder {
    class Snapshot internal constructor(val normal: NormalTargetView, entries: Map<ReportId, Report.Entry>) {
        internal val entries = Collections.unmodifiableMap(LinkedHashMap(entries))
    }
    private var state = Snapshot(NormalTargetView.EMPTY, emptyMap())
    val normalTargets: NormalTargetView get() = state.normal
    val reportCount: Int get() = state.entries.size

    fun prepare(config: RunConfig, result: RunResult<RunMethodAnalyzer>, shared: SharedObjects): Snapshot {
        check(result.status == RunStatus.COMPLETE)
        if (config.direction != Direction.FORWARD) return state
        val entries = LinkedHashMap(state.entries)
        for (actor in result.analyzers) {
            shared.cancellation.checkpoint()
            if (actor.key !in config.roots) continue
            for (row in actor.targets) {
                val target = row.target as? Target.NormalTarget ?: continue
                if (row.premise.isZero) entries.putIfAbsent(target.id,
                    Report.Entry(target.id, shared.reportCatalog.descriptor(target.id)))
            }
        }
        val fresh = result.analyzers.asSequence().flatMap { actor ->
            actor.targets.asSequence().mapNotNull { row ->
                (row.target as? Target.NormalTarget)?.let { OwnedNormalTarget(actor.key, row.premise, it.id) }
            }
        }
        val local = result.analyzers.asSequence().flatMap { it.blockTargets() }.flatMap { block ->
            block.rows.asSequence().mapNotNull { row ->
                (row.target as? Target.NormalTarget)?.let {
                    OwnedNormalTarget(block.method, row.premise, it.id, block.scope)
                }
            }
        }
        val normal = NormalTargetStore(shared.ap, state.normal.rows() + fresh + local)
        check(normal.zeroRows().all { it.id in entries }) {
            "Every retained ZERO terminal must reach a configured root before the barrier"
        }
        return Snapshot(normal, entries)
    }

    fun commit(prepared: Snapshot) { state = prepared }
    fun build(end: AnalysisEnd): Report = Report(state.entries.values.toList(), end)
}

package org.opentaint.dataflow.bidi.driver

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.RuntimeDataDomain
import org.opentaint.dataflow.bidi.ap.MethodKey
import org.opentaint.dataflow.bidi.ap.PathEdge
import org.opentaint.dataflow.bidi.ap.Pattern
import org.opentaint.dataflow.bidi.store.RuleId
import org.opentaint.dataflow.bidi.interp.RuleOccurrenceId
import org.opentaint.dataflow.bidi.interp.ActionId
import org.opentaint.ir.api.common.cfg.CommonInst
import java.util.Collections

/** Persistent hand-off seeds retain their context and original statement. */
sealed interface Seed {
    val method: MethodKey
    val statement: CommonInst

    /** One full-condition handle; it holds no compiled predicate or leaf inventory. */
    data class PredicateSink(
        val occurrence: RuleOccurrenceId,
        override val method: MethodKey,
        override val statement: CommonInst,
    ) : Seed

    class Sink(
        val rule: RuleId,
        override val method: MethodKey,
        override val statement: CommonInst,
        requirement: Pattern,
    ) : Seed {
        init {
            check(requirement.fact.base !is AccessPathBase.CleanerTemporary) {
                "A field-action temporary cannot enter a sink seed"
            }
        }
        val requirement: Pattern = requirement.copy(fact = requirement.fact.copy(
            path = Collections.unmodifiableList(ArrayList(requirement.fact.path))))

        override fun equals(other: Any?): Boolean = this === other ||
            (other is Sink && rule == other.rule && method == other.method && statement == other.statement &&
                requirement == other.requirement)

        override fun hashCode(): Int =
            ((rule.hashCode() * 31 + method.hashCode()) * 31 + statement.hashCode()) * 31 + requirement.hashCode()
    }

    /** The producer owns edge paths; preserve the supplied forward edge for later source selection. */
    data class Source(override val method: MethodKey, override val statement: CommonInst,
                      val edge: PathEdge, val action: ActionId? = null) : Seed {
        init {
            check(edge.from.base !is AccessPathBase.CleanerTemporary && edge.to.base !is AccessPathBase.CleanerTemporary) {
                "A field-action temporary cannot enter a source seed"
            }
        }
    }
}

/** Seed entries keep order and multiplicity; source admission compares the complete forward edge. */
class SeedIndex(byPlace: Map<Pair<MethodKey, CommonInst>, List<Seed>>) {
    private val byPlace: Map<Pair<MethodKey, CommonInst>, List<Seed>> = Collections.unmodifiableMap(
        LinkedHashMap<Pair<MethodKey, CommonInst>, List<Seed>>().apply {
            for ((place, seeds) in byPlace) {
                val admitted = seeds.filter { seed -> when (seed) {
                    is Seed.Sink -> RuntimeDataDomain.base(seed.requirement.fact.base)
                    is Seed.Source -> RuntimeDataDomain.producer(seed.edge)
                    is Seed.PredicateSink -> true
                } }
                if (admitted.isNotEmpty()) put(place, Collections.unmodifiableList(ArrayList(admitted)))
            }
        })
    private val sources: Set<Seed.Source> =
        this.byPlace.values.asSequence().flatten().filterIsInstance<Seed.Source>()
            .toSet()

    fun at(method: MethodKey, statement: CommonInst): List<Seed> = byPlace[method to statement].orEmpty()
    fun allowsSource(method: MethodKey, statement: CommonInst, forward: PathEdge, action: ActionId? = null): Boolean =
        RuntimeDataDomain.producer(forward) && Seed.Source(method, statement, forward, action) in sources
    val size: Int get() = byPlace.values.sumOf { it.size }

    fun sinkMethods(): Set<MethodKey> = byPlace.values.asSequence().flatten()
        .filter { it is Seed.Sink || it is Seed.PredicateSink }
        .mapTo(HashSet()) { it.method }

    companion object {
        val EMPTY = SeedIndex(emptyMap())
        fun of(seeds: List<Seed>): SeedIndex = SeedIndex(seeds.groupBy { it.method to it.statement })
    }
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.store.ExactDemandResults
import org.opentaint.dataflow.bidi.store.ScopeDemandView
import org.opentaint.dataflow.bidi.store.BlockScope
import org.opentaint.dataflow.graph.PortId

/** The router supplies a witness for the boundary which was actually reached. */
internal enum class BlockEntryRole { NORMAL_INTERFACE, EXCEPTIONAL_INTERFACE, MID_BLOCK }

internal data class BlockBoundaryAdmission(val initials: Set<AdmittedInitial>,
                                         val borrowedExceptionalNormalZero: Boolean)

/**
 * DATA keeps its exact physical interface. Typed ZERO control also sees the
 * normal endpoint when that endpoint was reached. The exceptional case below
 * is the selected HACK, rather than a new block seed or an alias of DATA rows.
 */
internal class BlockBoundaryDemandView(
    private val ap: ApManager,
    private val physical: ScopeDemandView,
    private val normal: ScopeDemandView,
    direction: Direction,
    role: BlockEntryRole,
    normalOutputs: Collection<PortId>,
    private val staticShortcutTarget: (PortId, PremiseKey, RestrictedInitialPolicy) -> Boolean = { _, _, _ -> false },
) : org.opentaint.dataflow.bidi.store.PreparedScopeDemandView, org.opentaint.dataflow.bidi.store.EntryPrecisionView {
    private val outputs = normalOutputs.toSet()
    private val exceptionalHack = direction == Direction.BACKWARD && role == BlockEntryRole.EXCEPTIONAL_INTERFACE
    private val backward = direction == Direction.BACKWARD
    private val borrowNormal = role == BlockEntryRole.NORMAL_INTERFACE ||
        exceptionalHack

    fun admission(actual: Facts, policy: RestrictedInitialPolicy): BlockBoundaryAdmission {
        val result = LinkedHashSet(physical.initials(actual, policy))
        // HACK: backward ZERO at the actual exceptional interface applies the
        // normal exit's control demands too. Ordinary DATA never reads them.
        var borrowed = false
        if (borrowNormal && actual is Reach) {
            val selected = normal.initials(actual, policy)
            result += selected
            borrowed = exceptionalHack && selected.any { it.initial.isZero }
        }
        return BlockBoundaryAdmission(result, borrowed)
    }

    override fun initials(actual: Facts, policy: RestrictedInitialPolicy): Set<AdmittedInitial> =
        admission(actual, policy).initials

    override fun precisionCursors(actual: Pattern, policy: RestrictedInitialPolicy): List<org.opentaint.dataflow.bidi.store.AnyDemandCursor>? =
        (physical as? org.opentaint.dataflow.bidi.store.EntryPrecisionView)?.precisionCursors(actual, policy)

    override fun prepareDataPlan(exit: PortId, templates: List<Pattern>,
                                 policy: RestrictedInitialPolicy, onEntryCheck: () -> Unit): org.opentaint.dataflow.bidi.store.PreparedLocalDataPlan? =
        (physical as? org.opentaint.dataflow.bidi.store.PreparedScopeDemandView)?.prepareDataPlan(exit, templates, policy, onEntryCheck)

    override fun intersect(exit: PortId, original: PremiseKey, raw: Facts,
                           policy: RestrictedInitialPolicy): List<Facts> {
        val result = ExactDemandResults(ap)
        physical.intersect(exit, original, raw, policy).forEach(result::add)
        if (borrowNormal && original.isZero)
            normal.intersect(exit, original, raw, policy).forEach(result::add)
        return result.all()
    }

    override fun acceptsTarget(exit: PortId, original: PremiseKey,
                               policy: RestrictedInitialPolicy): Boolean {
        // A Target is attached to the normal interface. A matching complete
        // paired row can name any genuine normal physical output of this block.
        for (output in outputs + exit) {
            ap.cancellation.checkpoint()
            if (physical.acceptsTarget(output, original, policy)) return true
            if (borrowNormal && original.isZero && normal.acceptsTarget(output, original, policy)) return true
            // The write shortcut has its own exact paired completion row.
            // It is not a DATA admission alias of the normal control view.
            if (backward && policy.run == 2 && original is InitialAp && original.base == STATIC &&
                staticShortcutTarget(output, original, policy)) return true
        }
        return false
    }
}

/** Only handoff control metadata uses the borrowed normal invocation address.
 * A synthetic discovery ingress is not a forward DATA/native output port. */
internal fun targetHandoffScope(actual: BlockScope, direction: Direction, borrowedNormalZero: Boolean,
                                row: TargetSummary): BlockScope =
    if (direction == Direction.BACKWARD && borrowedNormalZero && row.premise.isZero && row.target == Target.DemandTarget)
        actual.copy(entry = PortId.ROOT_EXIT) else actual

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.graph.BlockId
import org.opentaint.dataflow.graph.CompactGraph
import org.opentaint.dataflow.graph.DirectedMethodBlockLayout
import org.opentaint.dataflow.graph.MethodBlockLayout
import org.opentaint.dataflow.graph.MethodBlockRoute
import org.opentaint.dataflow.util.Cancellation
import java.util.BitSet
import java.util.Collections

/** A delivery frontier contains original statements or an exact block output edge. */
internal sealed interface BlockDeliveryTarget {
    data class Statement(val index: Int) : BlockDeliveryTarget
    data class Boundary(val route: MethodBlockRoute) : BlockDeliveryTarget
}

/**
 * One immutable layout, directed backend graph and lowest physical owner. Cache
 * the same neutral closure as CfgDeliveryCache, but make every outgoing block
 * edge a terminal control point. A cached search can never jump a loop gate.
 *
 * Boundary indexes below are private local cache points, never instructions or
 * LanguageManager indexes. No fact, rule, form or mutable current scope is kept.
 */
internal class BlockCfgDeliveryCache(
    private val layout: MethodBlockLayout,
    private val graph: CompactGraph,
    val block: BlockId,
    backward: Boolean,
    private val cancellation: Cancellation,
    directedView: DirectedMethodBlockLayout = layout.directed(graph, backward),
    boundaryTarget: (Int) -> Boolean = { false },
    relevant: (Int, AccessPathBase) -> Boolean,
) {
    private val points: List<BlockDeliveryTarget>
    private val boundaries: Map<Long, BlockDeliveryTarget.Boundary>
    private val cache: CfgDeliveryCache
    private val instructionCount = layout[block].instructions.size

    init {
        require(graph.size == layout.instructionCount)
        require(directedView.layout === layout && directedView.backward == backward)
        val allPoints = ArrayList<BlockDeliveryTarget>()
        for (index in layout[block].instructions) allPoints += BlockDeliveryTarget.Statement(index)
        val boundaryIndexes = HashMap<Long, Int>()
        val boundaryValues = HashMap<Long, BlockDeliveryTarget.Boundary>()
        for (from in layout[block].instructions) graph.forEachSuccessor(from) { to ->
            cancellation.checkpoint()
            val route = directedView.route(from, to)
            if (route.crossesBoundary || boundaryTarget(to)) {
                val edge = edgeKey(from, to)
                val value = BlockDeliveryTarget.Boundary(route)
                boundaryIndexes[edge] = allPoints.size
                boundaryValues[edge] = value
                allPoints += value
            }
        }
        points = Collections.unmodifiableList(allPoints)
        boundaries = Collections.unmodifiableMap(boundaryValues)
        val localGraph = CompactGraph.build(points.size) { point ->
            cancellation.checkpoint()
            BitSet(points.size).apply {
                val from = (points[point] as? BlockDeliveryTarget.Statement)?.index
                if (from != null) graph.forEachSuccessor(from) { to ->
                    val boundary = boundaryIndexes[edgeKey(from, to)]
                    if (boundary != null) set(boundary)
                    else {
                        check(layout.ownerOf(to) == block)
                        set(layout.localIndex(to))
                    }
                }
            }
        }
        cache = CfgDeliveryCache(localGraph, cancellation) { point, base ->
            when (val value = points[point]) {
                is BlockDeliveryTarget.Statement -> relevant(value.index, base)
                is BlockDeliveryTarget.Boundary -> true
            }
        }
    }

    val hits: Long get() = cache.hits
    val searches: Long get() = cache.searches
    /** Includes private boundary points; physical instruction diagnostics stay separate. */
    val visitedNodes: Long get() = cache.visitedNodes
    val destinations: Long get() = cache.destinations
    val maxWidth: Int get() = cache.maxWidth

    /** Include the given original statement when it is relevant. Empty is a cached answer. */
    fun targets(start: Int, base: AccessPathBase): List<BlockDeliveryTarget> {
        cancellation.checkpoint()
        require(layout.ownerOf(start) == block) { "Start $start is not owned by $block" }
        val local = layout.localIndex(start)
        check(local in 0 until instructionCount)
        // ZERO must execute each physical operation; it still meets explicit
        // boundary routing in after(), including self-loop feedback edges.
        if (base == AccessPathBase.Zero) return listOf(points[local])
        val indexes = cache.targets(local, base)
        if (indexes.isEmpty()) return emptyList()
        // Borrow the cached immutable index array. Do not allocate its members
        // again on a hit or store a second per-start/per-base frontier index.
        return object : AbstractList<BlockDeliveryTarget>() {
            override val size: Int get() = indexes.size
            override fun get(index: Int): BlockDeliveryTarget = points[indexes[index]]
        }
    }

    /** Called after processing and storing the result at the original statement. */
    fun after(from: Int, base: AccessPathBase): List<BlockDeliveryTarget> {
        cancellation.checkpoint()
        require(layout.ownerOf(from) == block) { "Source $from is not owned by $block" }
        val result = LinkedHashSet<BlockDeliveryTarget>()
        graph.forEachSuccessor(from) { to ->
            cancellation.checkpoint()
            val boundary = boundaries[edgeKey(from, to)]
            if (boundary != null) result += boundary else result += targets(to, base)
        }
        cancellation.checkpoint()
        return Collections.unmodifiableList(result.toList())
    }

    private fun edgeKey(from: Int, to: Int): Long =
        (from.toLong() shl 32) or (to.toLong() and 0xffffffffL)
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.interp.*
import org.opentaint.dataflow.bidi.store.*
import org.opentaint.ir.api.common.cfg.CommonInst
import java.util.Collections
import org.opentaint.dataflow.graph.PortId

/** Mutable transfer state. The original method actor owns its scheduling and lifetime. */
open class BlockRunState internal constructor(
    val key: MethodKey,
    port: RunnerPort<RunMethodAnalyzer>,
    publisher: PublicationSink,
    localFactory: MethodLocalServicesFactory,
    callFactory: MethodCallServicesFactory,
    targetPublisher: TargetPublicationSink,
    internal val binding: BlockRuntimeBinding? = null,
) : SummaryApplier {
    private var port: RunnerPort<RunMethodAnalyzer>? = port
    private var runContext: RunMethodContext? = binding?.context ?: RunMethodContext(key, port.forms, port.config, port.shared)
    val scope: BlockScope get() = binding?.scope ?: BlockScope.ROOT
    internal val isRootScope: Boolean get() = binding == null
    internal var rootRouting: MethodRootRouting? = null
    internal val runnerPort: RunnerPort<RunMethodAnalyzer> get() = checkNotNull(port) { "The method is frozen" }
    internal val context: RunMethodContext get() = checkNotNull(runContext) { "The method is frozen" }
    internal val config: RunConfig get() = context.config
    internal val forms: DirectedForms get() = context.forms
    internal val ap: ApManager = port.shared.ap
    internal val ops: ApOps = port.shared.ops
    internal val mode: ApMode = port.config.mode
    internal val forward: Boolean = port.config.direction == Direction.FORWARD
    private val limit = port.config.fieldLimit
    private var bodyWork = if (binding != null) binding.bodyWork else context.bodyWorkStatistics()
    internal val sharedBodyWork: BodyWorkStatistics? get() = bodyWork
    internal var bodyWorkSnapshot: BodyWorkSnapshot? = null; private set
    /** The run manager may call this only after all runner jobs have joined.
     * It copies numeric diagnostics; it does not export an incomplete run store. */
    internal fun stoppedBodyWorkSnapshot(): BodyWorkSnapshot? = bodyWorkSnapshot ?: bodyWork?.snapshot()
    internal val diagnosticCandidateOffers: Long get() =
        bodyWorkSnapshot?.candidatePackets ?: bodyWork?.candidatePackets ?: 0L

    private var edgeStore: ScopedEdgeStore<CommonInst>? = if (binding != null) ScopedEdgeStore(ap, binding.points, limit,
        flowBacked = mode.run1 && mode.markMode == MarkMode.FULL,
        collectStatistics = port.shared.n2Statistics != null) else MethodEdgeStore(ap, key, port.shared.language, limit,
        flowBacked = mode.run1 && mode.markMode == MarkMode.FULL,
        collectStatistics = port.shared.n2Statistics != null)
    private var initialStore: InitialFactStore? = InitialFactStore()
    val edges: ScopedEdgeStore<CommonInst> get() = checkNotNull(edgeStore) { "The method edges were released" }
    val initials: InitialFactStore get() = checkNotNull(initialStore) { "The initial facts were released" }
    val summaries = RunSummaryStore(ap, flowBacked = true)
    internal val normalRuleContributors = NormalRuleContributors(ap,
        port.shared.normalRuleContributors.snapshot(), key, scope, mode)
    internal var frozenNormalContributorRows: List<NormalRuleContributorRow> = emptyList()
        private set
    internal val portSummaries = PortSummaryStores(ap, flowBacked = true)
    private var localPublications = LinkedHashMap<PortId, MutableList<Publication>>()
    val sourceHits: SourceHitStore? = if (binding != null) binding.sourceHits else if (forward) null else SourceHitStore()
    val staticGuidanceSeeds = StaticGuidanceSeedStore(ap, ops, port.shared.staticGuidanceInterner)
    private val staticWriteCandidates = if (mode.run1)
        KilledStaticWriteStore(key, ap, ops, port.shared.staticWriteKeyInterner) else null

    /** Joined guidance completion only; raw observed rows still support ordinary call binding.
     * This also works after actor freeze for existing synthetic handoff fixtures. */
    fun freezeStaticWriteCandidates(): FrozenStaticWrites {
        check(mode.run1) { "Static-write candidate guidance exists only for run-1" }
        val admitted = if (isRootScope) summaries.all()
            else portSummaries.entries().asSequence().flatMap { it.second.all() }
        return checkNotNull(staticWriteCandidates).freeze(admitted, staticGuidanceSeeds.frozenRows())
    }
    internal fun joinedStaticSource(owner: OwnedScope): JoinedStaticSource {
        check(mode.run1)
        return JoinedStaticSource(owner, summaries.takeIf { isRootScope },
            portSummaries.takeUnless { isRootScope }, outgoingTargets, staticGuidanceSeeds,
            checkNotNull(staticWriteCandidates))
    }

    private val checkRun2StaticAnchors = config.index == 2
    private var temporary = RequestStorage()
    private var temporarySinceNanos = 0L
    private val staticSupplyProfile = if (config.run1 && config.direction == Direction.FORWARD &&
        mode.markMode == MarkMode.FULL) SupplyProfile.CANONICAL_RUN1_FULL else SupplyProfile.ORDERED_REFERENCE
    internal var staticBatch = StaticBatch(staticSupplyProfile, ap.cancellation, context.shared.n2Statistics); private set
    private var pointResumes = if (config.run1) Run1PointResume(this) else null
    private data class PointWork(val premise: PremiseKey, val facts: Facts,
                                 val site: ResumeSite, val state: CallResumeState?)
    private data class RuleItem(val premise: PremiseKey, val facts: Facts)
    private var resumeQueue = java.util.ArrayDeque<PointWork>()
    private val operationOwner = FormOwner()
    internal var abstraction: Run1Abstraction? = if (config.run1) Run1Abstraction(
        ops,
        answer = ::addInitial,
        borrowRequests = { input -> binding?.borrowRequests(input) ?: runnerPort.summaryStorage(key).borrowMatchingRequests(input) },
        collectRequests = ::collectRequests,
        statistics = context.shared.requestBatchStatistics,
        policyStatistics = context.shared.abstractionStatistics,
        owner = key,
    ) else null
        private set
    internal open fun releaseAbstraction() {
        abstraction?.release(); abstraction = null
        if (!temporary.isEmpty) {
            context.shared.abstractionStatistics?.temporaryChanged(-temporary.dynamicRows.toLong(), -temporary.dynamicMembers)
            temporary = RequestStorage()
        }
        temporarySinceNanos = 0L
    }
    internal fun unchangedStaticInitial(premise: PremiseKey): InitialAp? =
        null // The selected design has no inherited static request suppression.

    private var publicationSink: PublicationSink? = publisher
    private var local: MethodLocalServices? = localFactory.create(this)
    private var calls: MethodCallServices? = callFactory.create(this)
    internal val localServices: MethodLocalServices get() = checkNotNull(local) { "The local services were released" }
    private val callServices: MethodCallServices get() = checkNotNull(calls) { "The call services were released" }
    private var formApplier: FormApplier<PremiseKey, Facts>? = FormApplier(EngineAlgebra(this))
    internal val applier get() = checkNotNull(formApplier) { "The form applier was released" }
    private var worklist = DeltaWorklist(flowFirst = mode.run1 && mode.markMode == MarkMode.FULL,
        batchManager = ap.takeIf { mode.run1 && mode.markMode == MarkMode.FULL })
    private var pending = ArrayList<Publication>()
    private var targetPublicationSink: TargetPublicationSink? = targetPublisher
    private var pendingTargets = ArrayList<TargetSummary>()
    private val rawTargetRows = LinkedHashSet<TargetSummary>()
    val targets: Set<TargetSummary> get() = Collections.unmodifiableSet(rawTargetRows)
    private val outgoingTargetRows = LinkedHashSet<TargetSummary>()
    val outgoingTargets: Set<TargetSummary> get() = Collections.unmodifiableSet(outgoingTargetRows)
    val sinkSeeds = binding?.sinkSeeds ?: LinkedHashSet<org.opentaint.dataflow.bidi.driver.Seed>()

    internal fun emitTarget(premise: PremiseKey, target: Target) {
        if (!RuntimeDataDomain.premise(premise)) return
        if (!forward && target is Target.NormalTarget) return
        premise.forEachMember { check(!it.isFlow) { "Target needs a concrete or ZERO origin" } }
        if (target is Target.NormalTarget && (if (isRootScope) config.normalTargets.contains(key, premise, target.id)
                else config.normalTargets.contains(key, scope, premise, target.id))) return
        val row = TargetSummary(premise, target)
        if (!rawTargetRows.add(row)) return
        if (target is Target.NormalTarget || config.run1 ||
            (binding?.demand?.acceptsTarget(binding.terminalExit, premise, config.admissionPolicy)
                ?: checkNotNull(config.demand).acceptsTarget(key, premise, config.admissionPolicy))) {
            pendingTargets += row
            if (target == Target.DemandTarget) outgoingTargetRows += row
            requestWork()
        }
    }

    private var localSteps: Long = 0
    open val steps: Long get() = localSteps
    open val hasZeroWork: Boolean get() = worklist.hasZeroWork
    private var localEdgeDeltas: Long = 0
    open val edgeDeltas: Long get() = localEdgeDeltas
    private var localDemandLayerEdges: Long = 0
    open val demandLayerEdges: Long get() = localDemandLayerEdges
    var nonZeroInitial: Boolean = false; private set
    private var localRecordCrossings: Long = 0
    open val recordCrossings: Long get() = localRecordCrossings
    private var localTriggerSeeds: Long = 0
    open val triggerSeeds: Long get() = localTriggerSeeds
    private var localNeutralBatchApplications: Long = 0
    open val neutralBatchApplications: Long get() = localNeutralBatchApplications
    private var localNeutralBatchMemberships: Long = 0
    open val neutralBatchMemberships: Long get() = localNeutralBatchMemberships
    private var localNeutralBulkStorePackets: Long = 0
    open val neutralBulkStorePackets: Long get() = localNeutralBulkStorePackets
    private var localNeutralBulkStoreMemberships: Long = 0
    open val neutralBulkStoreMemberships: Long get() = localNeutralBulkStoreMemberships
    private var localNeutralScalarFallbackMemberships: Long = 0
    open val neutralScalarFallbackMemberships: Long get() = localNeutralScalarFallbackMemberships
    var cfgDeliveryHits: Long = 0; private set
    var cfgDeliverySearches: Long = 0; private set
    var cfgDeliveryVisitedNodes: Long = 0; private set
    var cfgDeliveryDestinations: Long = 0; private set
    var cfgDeliveryMaxWidth: Int = 0; private set
    /** Scalar gauges copied before release. No premise, fact or actor is retained. */
    var scalarIdentityStatistics: ScalarIdentityStatistics? = null; private set

    private var initialized = false

    /** Called only by the registered actor's owner; use the ordinary publication path. */
    private fun initialize() {
        if (initialized) return
        initialized = true
        // Static reads and effects start only at their reached operation.
    }

    fun addRootZero() {
        if (config.run1) addInitial(ap.zero)
        else for (initial in emitRestrictedInitials(config, ops, key, Reach.NORMAL)) addInitial(initial)
    }

    fun addLink(ref: CallerRef, linkLayer: Layer, added: Facts) {
        if (!RuntimeDataDomain.packet(ref.premise, added)) return
        check(config.run1) { "Raw call inputs are for run-1 only" }
        checkPremise(ref.premise)
        ap.cancellation.checkpoint()
        initialize()
        check(added.base !is AccessPathBase.CleanerTemporary) { "A field-action temporary cannot enter an added link" }
        check(linkLayer == added.layer) { "The link layer must be the added fact's layer" }
        context.shared.abstractionStatistics?.arrival()
        // Diagnostic input presence; this is not selected outgoing demand or a retained-group count.
        if (added.layer == Layer.DEMAND && !sawDemandInput) { sawDemandInput = true; localDemandLayerEdges++ }
        checkNotNull(abstraction).emit(ref, added)
    }

    private var sawDemandInput = false

    fun addMarkRequest(premise: InitialAp, mark: TaintMark) {
        check(config.run1) { "Requests exist only in run 1" }
        localServices.addMarkRequest(premise, mark)
    }

    fun addMarkRequests(premise: InitialAp, marks: RequestMarkSet) {
        check(config.run1) { "Requests exist only in run 1" }
        localServices.addMarkRequests(premise, marks)
    }

    fun addMarkRequests(rows: RequestRows) {
        check(config.run1) { "Requests exist only in run 1" }
        for ((slot, marks) in rows) { ap.cancellation.checkpoint(); collectRequests(slot, marks) }
    }

    internal fun collectRequests(slot: Run1Slot, offered: RequestMarkSelection) {
        initialize()
        check(config.run1) { "Requests exist only in run 1" }
        val statistics = context.shared.abstractionStatistics
        val counts = statistics?.let { RequestAdmissionCounts() }
        val beforeRows = temporary.dynamicRows
        val beforeMembers = temporary.dynamicMembers
        try {
            val fresh = offered.minus(binding?.borrowRequest(slot) ?: runnerPort.summaryStorage(key).borrowRequest(slot), counts, ap.cancellation::checkpoint)
            if (fresh.isEmpty) return
            val delta = temporary.addAll(slot, fresh, counts, ap.cancellation::checkpoint)
            if (!delta.isEmpty && temporarySinceNanos == 0L && context.shared.requestBatchStatistics != null)
                temporarySinceNanos = System.nanoTime()
            requestWork() // also schedules request-only actors; producers never read P
        } finally {
            if (counts != null) {
                counts.freshTemporaryMembers = temporary.dynamicMembers - beforeMembers
                statistics?.temporaryChanged((temporary.dynamicRows - beforeRows).toLong(), counts.freshTemporaryMembers)
                statistics?.requestOffer(counts)
            }
        }
    }

    internal fun addInitial(initial: InitialAp) = addInitial(AdmittedInitial(initial, Layer.NORMAL))

    internal fun addInitial(admitted: AdmittedInitial) {
        val initial = admitted.initial
        if (!RuntimeDataDomain.initial(initial)) return
        ap.cancellation.checkpoint()
        initialize()
        if (config.run1) {
            validateRun1Initial(initial, limit)
            check(initial.base != STATIC) { "Run-1 static descriptors resume at an operation, not method entry" }
        }
        check(forward || initial.tail != Tail.ANY_TAINT) { "A backward run has no must premise" }
        val intrinsic = ops.startFact(initial, mode)
        val start = forceRun1Layer(initial, intrinsic.withLayer(intrinsic.layer or (admitted.layer == Layer.DEMAND)))
        val fresh = initials.add(AdmittedInitial(initial, start.layer))
        context.shared.abstractionStatistics?.initial(fresh)
        if (!fresh) return
        if (!initial.isZero) nonZeroInitial = true
        if (binding != null) {
            binding.start(this, initial, start)
            return
        }
        for (node in forms.startNodes(key, zero = initial.isZero)) {
            ap.cancellation.checkpoint()
            rootRouting?.start(node, initial, start) ?: startAt(initial, node, start)
        }
    }

    internal fun collect(premise: PremiseKey, input: Facts, sink: ResultSink): ApOut {
        return object : ApOut {
            override fun result(f: Facts) {
                if (!RuntimeDataDomain.packet(premise, input) || !RuntimeDataDomain.packet(premise, f)) return
                val runtime = forceRun1Layer(premise, f)
                if (config.run1) ops.run1Cover(runtime) { sink(premise, it) } else sink(premise, runtime)
            }
            override fun markRequest(mark: TaintMark): Unit = raiseMark(premise, input, mark)
        }
    }

    internal fun raiseMark(premise: PremiseKey, input: Facts, mark: TaintMark) {
        if (!RuntimeDataDomain.packet(premise, input)) return
        check(config.run1) { "Requests exist only in run 1" }
        check(input is FlowTree && premise is InitialAp) { "A request needs a FLOW input premise" }
        check(premise.base != STATIC) { "A static-origin interest needs an exact operation input" }
        addMarkRequest(premise, mark)
    }

    internal fun operation(node: CommonInst, ordinal: Int = 0): OperationId =
        OperationId(FormKey(operationOwner, key.method, key, node), ordinal)

    internal fun forceRun1Layer(premise: PremiseKey, value: Facts): Facts {
        if (!config.run1) return value
        return run1Layer(premise, ops.runtimeFact(value, mode))
    }

    /** FULL uses the ordinary AP layer. GROUP projection and the independent
     * run-1 static approximation keep their DEMAND policy. */
    private fun run1Layer(premise: PremiseKey, value: Facts): Facts {
        return if ((value is TaintTree && mode.markMode == MarkMode.GROUP) || value.base == STATIC ||
            Run1StaticService.hasStaticMember(premise)) value.withLayer(Layer.DEMAND) else value
    }

    internal fun collect(at: OperationInput, sink: ResultSink): ApOut {
        return object : ApOut {
            override fun result(f: Facts) {
                if (!RuntimeDataDomain.packet(at.premise, at.facts) || !RuntimeDataDomain.packet(at.premise, f)) return
                val value = forceRun1Layer(at.premise, f)
                if (config.run1) ops.run1Cover(value) { sink(at.premise, it) } else sink(at.premise, value)
            }
            override fun markRequest(mark: TaintMark) = needGroups(at, mark)
        }
    }

    /** Only for the immediate callback from this actor's ops.applyEdge run1Policy.
     * That policy already projected and covered each result with this AP manager. */
    internal fun collectAfterRun1Policy(at: OperationInput, sink: ResultSink): ApOut {
        return object : ApOut {
            override fun result(f: Facts) {
                if (!RuntimeDataDomain.packet(at.premise, at.facts) || !RuntimeDataDomain.packet(at.premise, f)) return
                val value = if (config.run1) run1Layer(at.premise, f) else f
                if (config.run1) ops.run1Cover(value) { sink(at.premise, it) } else sink(at.premise, value)
            }
            override fun markRequest(mark: TaintMark) = needGroups(at, mark)
        }
    }

    internal fun needGroups(at: OperationInput, mark: TaintMark) {
        if (!RuntimeDataDomain.packet(at.premise, at.facts)) return
        if (!config.run1) return
        val original = at.premise as? InitialAp ?: return
        if (at.facts !is FlowTree || original.mark !is MarkSlot.Star) return
        if (dropsStaticField(original)) return
        val atom = ap.marks.runtimeAtom(mark, mode.markMode)
        if (original.base == STATIC) {
            checkNotNull(pointResumes).request(at, MarkSet.of(atom))
            binding?.staticMarkRequest(original, atom)
        } else addMarkRequest(original, atom)
    }

    /** FULL block requests share one immutable image and one raw suffix address. */
    internal fun needGroups(at: OperationInput, marks: MarkSet) {
        if (!RuntimeDataDomain.packet(at.premise, at.facts)) return
        if (!config.run1 || marks.isEmpty) return
        val original = at.premise as? InitialAp ?: return
        if (at.facts !is FlowTree || original.mark !is MarkSlot.Star || dropsStaticField(original)) return
        check(mode.markMode == MarkMode.FULL)
        if (original.base == STATIC) {
            checkNotNull(pointResumes).request(at, marks)
            for (id in marks.ids) binding?.staticMarkRequest(original, TaintMark(id))
        } else addMarkRequests(original, RequestMarkSet.fromIds(marks.ids))
    }

    internal fun reachedOperations(summary: StatementSummary, at: OperationInput) {
        if (!RuntimeDataDomain.packet(at.premise, at.facts)) return
        if (config.run1) checkNotNull(pointResumes).reached(summary, at)
    }

    internal fun emitOperationResult(at: OperationInput, operation: StaticOperation.Write?, value: Facts, sink: ResultSink) {
        if (!RuntimeDataDomain.packet(at.premise, at.facts) || !RuntimeDataDomain.packet(at.premise, value)) return
        if (dropsStaticPremise(at.premise)) return
        val admitted = withoutDisabledStaticFields(value) ?: return
        val runtime = forceRun1Layer(at.premise, admitted)
        if (config.run1 && runtime.base == STATIC) {
            val boundary = at.site as? ResumeSite.BoundaryInput
            if (operation != null) {
                boundedSummaryResult(at.premise, runtime) { premise, bounded ->
                    if (boundary != null && !boundary.atStart &&
                        context.isEnd(boundary.operation.form.statement) &&
                        !context.isExceptionalExit(boundary.operation.form.statement)) {
                        // The next exit-rule continuation can kill this executed
                        // write before the final boundary result is available.
                        checkNotNull(staticWriteCandidates).observe(premise, bounded)
                    }
                    // A real write becomes globally visible at the producer,
                    // independently of its later exit rules and summary.
                    checkNotNull(pointResumes).localWrite(premise, bounded)
                    if (boundary != null && !boundary.atStart) sink(premise, bounded)
                    else routeBoundedRun1StaticToExit(at.site.operation.form.statement, premise, bounded)
                }
            } else if (boundary != null && !boundary.atStart) {
                // This value already belongs to an exit-rule pipeline. Finish
                // its remaining rules; never schedule NormalExit again.
                sink(at.premise, runtime)
            }
            return
        }

        sink(at.premise, runtime)
    }

    open fun onStaticEffect(effect: StaticOwnerEffect) {
        check(config.run1 && effect.owner == key)
        checkNotNull(pointResumes).onEffect(effect)
    }

    internal fun staticFacts(slice: RegionGroups): Facts = checkNotNull(runnerPort.staticService).facts(slice.region, slice.groups)
    internal fun staticSlices(facts: Facts): List<RegionGroups> = checkNotNull(runnerPort.staticService).slices(facts)
    internal fun staticCallInterest(part: Subscription, result: StaticCallResult, member: Int) {
        if (!dropsStaticField(result.premise.member(member)))
            checkNotNull(pointResumes).callInterest(part, result, member)
    }
    internal fun staticCallSupply(part: Subscription, result: StaticCallResult, member: Int, supply: RegionGroups) =
        callServices.staticSupply(part, result, member, supply)

    /** These published run-1 originals have already received their canonical pool input. */
    internal fun hasKnownStaticGroupInput(premise: PremiseKey): Boolean =
        config.run1 && premise is InitialAp &&
            premise.base == STATIC && premise.mark is MarkSlot.Concrete &&
            premise.exclusion == ExclusionSet.Empty &&
            ((premise.pathData.size == 2 && premise.tail == Tail.STAR) ||
                (premise.pathData.size == 1 && premise.tail == Tail.EXACT))

    internal fun knownStaticInput(initial: InitialAp): Facts {
        check(hasKnownStaticGroupInput(initial))
        return ops.startFact(initial, mode)
    }

    private fun boundedStaticSummaryOut(premise: PremiseKey, emit: (Facts) -> Unit): ApOut = object : ApOut {
        override fun result(f: Facts) {
            if (f is TaintTree) {
                // Static effects leave the ordinary call suffix early. Apply
                // the same field limit that suffix would apply to its result.
                ops.limit(forceRun1Layer(premise, f), limit, collect(premise, f) { _, bounded -> emit(bounded) })
            }
        }
        override fun markRequest(mark: TaintMark) = Unit // summary application is not rule execution
    }

    internal fun composeStaticSummaryWithActualInput(initial: InitialAp, value: Facts, actual: Facts,
                                                    emit: (Facts) -> Unit) {
        checkPremise(initial)
        for (packet in ap.canonicalPackets(actual)) {
            val matched = ops.matchSummary(packet, initial, mode, nativeRecordRead = false,
                role = SummaryMatchRole.CURRENT) ?: continue
            ops.applySummary(matched, initial, value, mode, boundedStaticSummaryOut(initial, emit))
        }
    }

    /** Apply a complete static tuple on this owner after releasing the service lock. */
    internal fun composeStaticSummary(premise: PremiseKey, value: Facts, inputs: List<RegionGroups>, emit: (Facts) -> Unit) {
        checkPremise(premise)
        when (premise) {
            is InitialAp -> if (premise.isZero) { if (value is TaintTree) emit(value.withLayer(Layer.DEMAND)) }
                else if (inputs.size == 1) {
                    composeStaticSummaryWithActualInput(premise, value, staticFacts(inputs.single()), emit)
                }
            is PremiseSet -> if (inputs.size == premise.size && value is TaintTree) {
                val parts = inputs.mapIndexed { i, slice ->
                    ap.cancellation.checkpoint()
                    val initial = premise.member(i)
                    // Complete tuples use only each matched input's layer (W7). Canonical
                    // splits preserve that layer, so one existing match witnesses this arm.
                    val matched = ap.canonicalPackets(staticFacts(slice)).firstNotNullOfOrNull { packet ->
                        ops.matchSummary(packet, initial, mode, nativeRecordRead = false,
                            role = SummaryMatchRole.CURRENT)
                    } ?: return
                    matched to initial
                }
                ops.applyCombination(parts, value, mode, boundedStaticSummaryOut(premise, emit))
            }
        }
    }

    internal fun installPoint(premise: PremiseKey, value: Facts, site: ResumeSite, state: CallResumeState? = null) {
        if (!RuntimeDataDomain.packet(premise, value)) return
        check(config.run1)
        checkPremise(premise)
        if (dropsStaticPremise(premise)) return
        val admitted = withoutDisabledStaticFields(value) ?: return
        premise.forEachMember { validateRun1Initial(it, limit) }
        val runtime = forceRun1Layer(premise, admitted)
        checkKinds(premise, runtime)
        nonZeroInitial = nonZeroInitial || !premise.isZero
        resumeQueue.addLast(PointWork(premise, runtime, site, state))
        requestWork()
    }

    internal fun cut(point: Cut, premise: PremiseKey, facts: Facts, sink: ResultSink) {
        if (!RuntimeDataDomain.packet(premise, facts)) return
        runnerPort.onCut?.invoke(point, facts)
        val checkedSink: ResultSink = if (!checkRun2StaticAnchors) sink else { pr, bounded ->
            validateStaticFullAnchors(bounded)
            sink(pr, bounded)
        }
        val out = collect(premise, facts, checkedSink)
        if (config.run1) ops.run1Cover(facts) { ops.limit(it, limit, out) }
        else ops.limit(facts, limit, out)
    }

    /** Current result headers stay unchanged. Only query/seed admission requires
     * EXACT/ANY with empty E; other bounded field facts can retain MUST/E. */
    private fun validateStaticFullAnchors(facts: Facts) {
        if (facts !is TaintTree || facts.base != STATIC) return
        for (leaf in ops.leaves(facts)) validateRun2StaticFullAnchor(ap, leaf)
    }

    private val hasPendingAbstractionWork: Boolean get() =
        !temporary.isEmpty || !staticBatch.isEmpty || resumeQueue.isNotEmpty()

    internal val hasLocalWork: Boolean get() = !worklist.isEmpty || pending.isNotEmpty() ||
        localPublications.isNotEmpty() || pendingTargets.isNotEmpty() || hasPendingAbstractionWork
    internal val localHasZeroWork: Boolean get() = worklist.hasZeroWork
    internal val localHasFlowWork: Boolean get() = worklist.hasFlowWork

    private fun commitRequests() {
        if (!config.run1 || temporary.isEmpty) return
        if (temporarySinceNanos != 0L)
            context.shared.requestBatchStatistics?.serviceDelay(System.nanoTime() - temporarySinceNanos)
        if (binding != null) binding.commitRequests(this, temporary) else runnerPort.summaryStorage(key).commit(temporary)
        context.shared.abstractionStatistics?.temporaryChanged(-temporary.dynamicRows.toLong(), -temporary.dynamicMembers)
        temporary = RequestStorage() // replace only after synchronous commit and secured sends
        temporarySinceNanos = 0L
    }

    open fun work(quantum: Int): Boolean = workLocal(quantum)

    internal fun workLocal(quantum: Int): Boolean {
        require(quantum > 0) { "The work quantum must be positive" }
        checkNotNull(port) { "The method is frozen" }
        val zeroAtStart = worklist.hasZeroWork
        var processed = 0
        while (true) {
            ap.cancellation.checkpoint()
            while (resumeQueue.isNotEmpty()) {
                if (processed >= quantum) return false
                processed++
                val resume = resumeQueue.removeFirst()
                when (val site = resume.site) {
                    is ResumeSite.StatementInput -> runStatement(EdgeDelta(resume.premise, site.operation.form.statement, resume.facts))
                    is ResumeSite.BoundaryInput -> if (site.atStart) startAt(resume.premise, site.operation.form.statement, resume.facts)
                        else endAt(resume.premise, site.operation.form.statement, resume.facts,
                            summary = !context.isExceptionalExit(site.operation.form.statement))
                    is ResumeSite.ReadOutput -> installPoint(resume.premise, resume.facts, site.input, resume.state)
                    is ResumeSite.CallStageInput, is ResumeSite.CleanerInput -> callServices.resumePoint(resume.premise, resume.facts, site, resume.state)
                }
            }
            while (!worklist.isEmpty) {
                // Keep the zero phase separate. A quantum yield retains P without publishing it;
                // only the method fact-queue-empty boundary commits request memberships.
                if (worklist.hasZeroWork != zeroAtStart) return false
                if (processed >= quantum) {
                    return false
                }
                if (mode.run1 && mode.markMode == MarkMode.FULL)
                    processed += processPending(worklist.removeNextBatch(), quantum - processed)
                else {
                    processed++
                    process(worklist.removeNext())
                }
            }
            flushPublications()
            ap.cancellation.checkpoint()
            if (!worklist.isEmpty || pending.isNotEmpty() || localPublications.isNotEmpty() || pendingTargets.isNotEmpty()) continue
            commitRequests()
            if (config.run1 && !staticBatch.isEmpty) {
                val committed = staticBatch
                val effects = checkNotNull(runnerPort.staticService) { "Run-1 needs its static service" }.commit(committed)
                staticBatch = StaticBatch(staticSupplyProfile, ap.cancellation, context.shared.n2Statistics)
                for (effect in effects) check(runnerPort.sendStatic(effect)) { "Static effect delivery was rejected" }
            }
            ap.cancellation.checkpoint()
            // Retain the counted Work reservation through P commit/replacement and sends.
            if (worklist.isEmpty && pending.isEmpty() && localPublications.isEmpty() && pendingTargets.isEmpty() && !hasPendingAbstractionWork) return true
        }
    }

    private fun process(item: EdgeDelta) {
        if (!RuntimeDataDomain.packet(item.premise, item.facts)) return
        ap.cancellation.checkpoint()
        localSteps++
        bodyWork?.processed(context.shared.language.getInstIndex(item.node), item.premise, item.facts)
        runnerPort.onProcess?.invoke(key, item)
        if (config.run1 && item.facts.base == STATIC && context.isEnd(item.node))
            completeMethodBoundary(item.premise, item.node, item.facts, summary = true)
        else if (context.callAt(item.node) != null) callServices.process(item) else runStatement(item)
    }

    /** A batch can cross only a certified plain statement. Keep a remainder
     * counted as work before any successor, yield or request/static barrier. */
    private fun processPending(work: PendingWork, budget: Int): Int {
        if (work is PendingWork.Scalar) {
            process(work.delta)
            return 1
        }
        work as PendingWork.MarkedBatch
        val node = work.node
        var used = 0
        val plainPoint = binding == null && rootRouting == null && context.callAt(node) == null && !context.isEnd(node) &&
            !context.isExceptionalExit(node) && runnerPort.onProcess == null && runnerPort.onCut == null &&
            !dropsStaticField(work.batch.initialShape)
        if (plainPoint) forms.withStatement(key, node) { summary ->
            if (!NeutralRelationBatch.certifies(summary)) return@withStatement
            val chunk = work.batch.take(budget)
            used = chunk.size
            worklist.addBatch(node, work.batch)
            localSteps += used
            localNeutralBatchApplications++
            localNeutralBatchMemberships += used
            check(chunk.applyPacked(ops, summary, mode,
                emit = { shape, facts, marks -> emitPackedAfter(node, shape, facts, marks) },
                untouched = { shape, facts, marks ->
                    NeutralRelationBatch.decodePacked(ap, shape, facts, marks) { premise, value ->
                        emitUnchanged(EdgeDelta(premise, node, value))
                    }
                }))
        }
        if (used != 0) return used
        val (premise, facts) = work.batch.removeFirst()
        worklist.addBatch(node, work.batch)
        process(EdgeDelta(premise, node, facts))
        return 1
    }

    private fun emitPackedAfter(node: CommonInst, shape: InitialAp, facts: TaintTree, marks: MarkSet) {
        if (!RuntimeDataDomain.packet(shape, facts)) return
        val offered = NeutralRelationBatch.toDiagonal(ap, shape, facts, marks)
        if (offered == null) {
            // Classify once, then use the exact decoder for an unsupported
            // tail or partial-protection cell. No scalar tree is built first.
            localNeutralScalarFallbackMemberships += marks.size
            NeutralRelationBatch.decodePacked(ap, shape, facts, marks) { premise, value -> emitAfter(premise, node, value) }
            return
        }
        check(!context.isEnd(node) && !context.isExceptionalExit(node))
        val fresh = edges.addDiagonal(node, offered)
        if (fresh == null) {
            // Decode once at the producer, before successor fan-out.
            localNeutralScalarFallbackMemberships += marks.size
            NeutralRelationBatch.decodePacked(ap, shape, facts, marks) { premise, value ->
                completeOutput(premise, node, value)
            }
        } else for (delta in fresh) {
            ap.cancellation.checkpoint()
            localNeutralBulkStorePackets++
            localNeutralBulkStoreMemberships += delta.marks.size
            localEdgeDeltas += delta.marks.size
            if (delta.layer == Layer.DEMAND) localDemandLayerEdges += delta.marks.size
            context.forEachSuccessor(node) { successor ->
                context.forEachDeliveryTarget(successor, delta.base) { target ->
                    // Each queued destination owns its mutable remaining-mark wrapper.
                    worklist.addBatch(target, checkNotNull(NeutralRelationBatch.fromDiagonal(ap, delta)))
                    requestWork()
                }
            }
        }
    }

    private fun runStatement(item: EdgeDelta) {
        forms.withStatement(key, item.node) { summary ->
            applier.statement(summary, item.premise, item.facts,
                Place(item.node, config.run1, sources = true, site = ResumeSite.StatementInput(operation(item.node))),
                sink = { premise, result ->
                    cut(Cut.STATEMENT, premise, result) { pr, facts -> emitAfter(pr, item.node, facts) }
                }, untouched = { _, _ -> emitUnchanged(item) })
        }
    }

    internal fun emitAfter(premise: PremiseKey, node: CommonInst, value: Facts) {
        if (!RuntimeDataDomain.packet(premise, value)) return
        checkPremise(premise)
        if (config.run1 && value.base == STATIC && !context.isEnd(node)) return
        if (config.run1) ops.run1Cover(forceRun1Layer(premise, value)) { emitCovered(premise, node, it) }
        else emitCovered(premise, node, value)
    }

    private fun emitCovered(premise: PremiseKey, node: CommonInst, facts: Facts) {
        when {
            context.isEnd(node) -> completeMethodBoundary(premise, node, facts, summary = true)
            context.isExceptionalExit(node) -> completeMethodBoundary(premise, node, facts, summary = false)
            else -> completeOutput(premise, node, facts)
        }
    }

    private fun completeMethodBoundary(premise: PremiseKey, node: CommonInst, facts: Facts, summary: Boolean) {
        if (binding != null) binding.methodBoundary(this, node, premise, facts, summary)
        else endAt(premise, node, facts, summary)
    }

    internal fun emitUnchanged(item: EdgeDelta) {
        if (!RuntimeDataDomain.packet(item.premise, item.facts)) return
        checkPremise(item.premise)
        if (config.run1 && item.facts.base == STATIC && !context.isEnd(item.node)) return
        emitCovered(item.premise, item.node, item.facts)
    }

    /** One durable result row per producer. Identity output uses this gate too. */
    private fun completeOutput(premise: PremiseKey, node: CommonInst, facts: Facts) {
        for (fresh in admitOutput(node, premise, facts)) {
            // Complete fan-out while the current Work reservation is held.
            if (binding != null) binding.successors(this, node, premise, fresh)
            else if (rootRouting != null) checkNotNull(rootRouting).successors(node, premise, fresh)
            else context.forEachSuccessor(node) { deliverAt(it, premise, fresh) }
        }
    }

    private fun admitOutput(node: CommonInst, premise: PremiseKey, facts: Facts): List<Facts> {
        if (!RuntimeDataDomain.packet(premise, facts)) return emptyList()
        checkKinds(premise, facts)
        return edges.addAll(node, premise, facts).also { deltas ->
            for (fresh in deltas) {
                bodyWork?.fresh(context.shared.language.getInstIndex(node), premise, fresh)
                localEdgeDeltas++
                if (fresh.layer == Layer.DEMAND) localDemandLayerEdges++
            }
        }
    }

    private fun deliverAt(start: CommonInst, premise: PremiseKey, facts: Facts) {
        rootRouting?.let { it.enter(start, premise, facts); return }
        context.forEachDeliveryTarget(start, facts.base) { enqueueInput(it, premise, facts) }
    }

    internal fun enqueueInput(node: CommonInst, premise: PremiseKey, facts: Facts) {
        if (!RuntimeDataDomain.packet(premise, facts)) return
        checkKinds(premise, facts)
        worklist.add(EdgeDelta(premise, node, facts))
        requestWork()
    }

    internal fun checkPremise(premise: PremiseKey) {
        check(!config.run1 || premise is InitialAp) { "Run-1 executable edges have one original premise" }
    }

    internal fun checkKinds(premise: PremiseKey, facts: Facts) {
        checkPremise(premise)
        check((facts is FlowTree) == premise.isFlow) { "K6: the conclusion kind follows its premise" }
        check(premise !is PremiseSet || facts is TaintTree) { "A multi-premise edge must be TAINT" }
        if (config.run1) when (facts) {
            is FlowTree -> check(facts.exclusion == ExclusionSet.Empty) { "Run-1 FLOW has Empty field E" }
            is TaintTree -> check(facts.exclusion == ExclusionSet.Empty) { "Run-1 TAINT has Empty field E" }
            is Reach -> Unit
        }
    }

    internal open fun requestWork() {
        if (binding != null) binding.schedule() else runnerPort.enqueue(this as RunMethodAnalyzer)
    }

    internal fun nextStaticTicket(): Long = binding?.staticTicket() ?: ++lastStaticTicket
    private var lastStaticTicket = 0L

    private inner class RuleWorklist(
        private val rules: RuleStatement,
        private val node: CommonInst,
        private val point: Cut,
    ) {
        private val items = LinkedHashMap<Pair<PremiseKey, Facts>, RuleItem>()
        private val add: ResultSink = { premise, facts ->
            cut(point, premise, facts) { pr, result ->
                val key = pr to result
                val old = items[key]
                val merged = if (old == null) result else ap.mergeAddDelta(old.facts, result).first
                items[key] = RuleItem(pr, merged)
            }
        }

        fun input(premise: PremiseKey, facts: Facts) {
            applier.statement(rules.summary, premise, facts, Place(node, config.run1, sources = true,
                site = ResumeSite.BoundaryInput(operation(node), point == Cut.ENTRY_RULES)), sink = add)
        }

        fun drain(after: (PremiseKey, Facts, Triggers) -> Unit = { _, _, _ -> }) {
            for (item in items.values) {
                ap.cancellation.checkpoint()
                val premise = item.premise; val facts = item.facts
                val triggers = localServices.checkSinksAt(premise, node, facts, rules.sinks,
                    OperationInput(ResumeSite.BoundaryInput(operation(node), point == Cut.ENTRY_RULES), premise, facts))
                after(premise, facts, triggers)
            }
        }

        fun forEachResult(visit: (PremiseKey, Facts) -> Unit) {
            for (item in items.values) { visit(item.premise, item.facts) }
        }
    }

    internal fun startAt(premise: PremiseKey, node: CommonInst, start: Facts,
                         deliver: (PremiseKey, Facts) -> Unit = { pr, value ->
                             binding?.startResult(this, node, pr, value) ?: deliverAt(node, pr, value) }) {
        if (!RuntimeDataDomain.packet(premise, start)) return
        forms.withStartRules(key, node) { rules ->
            val work = RuleWorklist(rules, node,
                if (forward) Cut.ENTRY_RULES else Cut.EXIT_RULES)
            work.input(premise, start)
            if (!forward && premise.isZero) localServices.fireSinkSeeds(node) { seed -> work.input(ap.zero, seed) }
            work.drain()
            work.forEachResult { pr, facts ->
                ap.cancellation.checkpoint()
                if (config.run1 && facts.base == STATIC) return@forEachResult
                deliver(pr, facts)
            }
        }
    }

    internal fun endAt(premise: PremiseKey, node: CommonInst, facts: Facts, summary: Boolean) {
        if (!RuntimeDataDomain.packet(premise, facts)) return
        if (config.run1 && summary) checkNotNull(staticWriteCandidates).observe(premise, facts)
        forms.withEndRules(key, node) { exit ->
            val work = RuleWorklist(exit.rules, node, if (forward) Cut.EXIT_RULES else Cut.ENTRY_RULES)
            work.input(premise, facts)
            work.drain { pr, value, triggers ->
                if (!summary) {
                    // Exceptional rules and observations still run, but normal
                    // summary adjustment and killed-write guidance do not.
                    for (fresh in admitOutput(node, pr, value))
                        if (binding != null) retainBlockSummary(PortId(-4), pr, fresh)
                    return@drain
                }
                if (config.run1) checkNotNull(staticWriteCandidates).observe(pr, value)
                // Local span rows include the real boundary rules. G2 and entry-mark
                // metadata use the complete method origin after parent binding.
                val result = if (isRootScope) finishMethodData(ops, mode, pr, value, exit, triggers.parts) else value
                result?.let { completed ->
                    boundedSummaryResult(pr, completed) { boundedPremise, bounded ->
                        for (fresh in admitOutput(node, boundedPremise, bounded))
                            retainSummary(boundedPremise, fresh, binding?.terminalExit ?: PortId.ROOT_EXIT)
                    }
                }
            }
        }
    }

    /** Complete method-origin metadata only. The real boundary rules already ran in a leaf. */
    internal fun finishBoundMethodBoundary(premise: PremiseKey, node: CommonInst, value: Facts, summary: Boolean) {
        if (!summary) return
        if (config.run1) checkNotNull(staticWriteCandidates).observe(premise, value)
        forms.withEndRules(key, node) { exit ->
            adjustMethodExitMetadata(premise, value, exit)?.let { summaryDelta(premise, it) }
        }
    }

    internal fun adjustMethodExitMetadata(premise: PremiseKey, value: Facts, exit: ExitRules): Facts? =
        finishMethodData(ops, mode, premise, value, exit)

    /** Query adapter for the same ordered metadata, with no rule actions or joins. */
    internal fun adjustObservedMethodExit(premise: PremiseKey, value: Facts): Facts? {
        var result: Facts? = null
        val node = if (forward) context.normalExit else context.shared.interpreter.entryNode(key)
        forms.withEndRules(key, node) { exit -> result = adjustMethodExitMetadata(premise, value, exit) }
        return result
    }

    internal fun dropsStaticField(fact: PathFact): Boolean =
        config.disableRun1Statics && fact.base == STATIC && fact.path.size >= 2

    internal fun dropsStaticField(initial: InitialAp): Boolean =
        config.disableRun1Statics && initial.base == STATIC && initial.pathData.size >= 2

    private fun dropsStaticPremise(premise: PremiseKey): Boolean = config.disableRun1Statics &&
        (0 until premise.size).any { dropsStaticField(premise.member(it)) }

    /** The diagnostic gate runs before summary/index/publication or writer effects.
     * A packed STATIC tree can also contain exact global class markers. Keep them. */
    private fun withoutDisabledStaticFields(value: Facts): Facts? {
        if (!config.disableRun1Statics || value.base != STATIC) return value
        var kept: Facts? = null
        for (leaf in ops.leaves(value)) {
            if (leaf.fact.path.size != 1 || leaf.fact.tail != Tail.EXACT) continue
            val exact = ap.factsOf(leaf.fact, leaf.exclusion, value.layer)
            kept = kept?.let { ap.mergeAddDelta(it, exact).first } ?: exact
        }
        return kept
    }

    /** A call result supplies its computed mark, but is not a new local writer. */
    internal fun routeStaticResultToExit(node: CommonInst, premise: PremiseKey, value: Facts) {
        check(config.run1 && value.base == STATIC) { "Static exit routing needs a run-1 static result" }
        boundedSummaryResult(premise, value) { pr, bounded ->
            checkNotNull(pointResumes).computedGroups(pr, bounded)
            routeBoundedRun1StaticToExit(node, pr, bounded)
        }
    }

    private fun routeBoundedRun1StaticToExit(node: CommonInst, premise: PremiseKey, bounded: Facts) {
        check(config.run1 && bounded.base == STATIC)
        for (fresh in admitOutput(node, premise, bounded)) {
            if (binding != null) binding.routeStaticToExit(this, node, premise, fresh)
            else enqueueInput(context.normalExit, premise, fresh)
        }
    }

    internal fun summaryDelta(premise: PremiseKey, value: Facts) =
        boundedSummaryResult(premise, value, ::retainSummary)

    private fun boundedSummaryResult(premise: PremiseKey, value: Facts, sink: ResultSink) {
        checkPremise(premise)
        if (dropsStaticPremise(premise)) return
        val admitted = withoutDisabledStaticFields(value) ?: return
        val runtime = if (config.run1) forceRun1Layer(premise, admitted).let {
            // A nonstatic FLOW original does not itself force a static result
            // to DEMAND. Preserve the explicit static boundary assignment.
            if (it.base == STATIC) it.withLayer(Layer.DEMAND) else it
        } else admitted
        if (config.run1) ops.run1Cover(runtime) { covered ->
            // Static producer routing bypasses the ordinary successor cut.
            // Preserve the same bounded AP value at that boundary.
            ops.limit(covered, limit, collect(premise, covered, sink))
        }
        else {
            // Native/summary producers can reach this boundary without a new
            // successor cut. Keep the producer's existing bound and annotations.
            if (checkRun2StaticAnchors) validateStaticFullAnchors(admitted)
            sink(premise, admitted)
        }
    }

    internal fun retainBlockSummary(exit: PortId, premise: PremiseKey, facts: Facts) {
        boundedSummaryResult(premise, facts) { pr, value -> retainSummary(pr, value, exit) }
    }

    private fun retainSummary(rawPremise: PremiseKey, rawFacts: Facts, exit: PortId = PortId.ROOT_EXIT) {
        if (!RuntimeDataDomain.packet(rawPremise, rawFacts)) return
        val preparedExit = binding?.prepareExit(exit, rawFacts.base)
        if (preparedExit === PreparedExit.DeadData ||
            preparedExit == null && binding?.keepLocalConclusion(exit, rawFacts) == false) return
        val normalized = normalizeFlowSummary(ap, rawPremise, rawFacts)
        val premise = normalized.premise
        val facts = normalized.facts
        val trace = LoopPipelineTrace.enabled(config.index, key)
        if (trace) LoopPipelineTrace.record(config.index, key, "c5-normalized") {
            catalog(ap)
            text("scope", scope.toString())
            number("exit", exit.ordinal)
            this.premise("rawP", rawPremise)
            this.facts("rawF", rawFacts)
            this.premise("P", premise)
            this.facts("F", facts)
        }
        bodyWork?.candidate(premise, facts, internalBlock = !isRootScope)
        assertCanonicalFlowSummary(premise, facts)
        if (!config.run1 && facts is FlowTree && facts.layer == Layer.DEMAND)
            check(facts.tail == Tail.ANY && facts.exclusion == ExclusionSet.Empty) {
                "Restricted FLOW DEMAND must have an uncertain ANY tail"
            }
        checkKinds(premise, facts)
        if (isRootScope && !context.shared.interpreter.isSummaryBase(facts.base)) return
        // Existing computed summary supplies are independent of local write
        // effects. Pending fixed-mark joins own their scalar payload without
        // retaining a static/static method summary.
        if (config.run1 && facts.base == STATIC) checkNotNull(pointResumes).computedGroups(premise, facts)
        if (isRootScope && erasesRun1StaticSummary(premise, facts)) {
            staticGuidanceSeeds.add(premise, facts)
            return
        }
        val admitted = if (config.run1) listOf(facts) else
            binding?.intersectSummary(exit, premise, facts)
                ?: rootRouting?.intersectSummary(exit, premise, facts)
                ?: binding?.demand?.intersect(exit, premise, facts, config.admissionPolicy)
                ?: checkNotNull(config.demand).intersect(key, premise, facts, config.admissionPolicy)
        for (piece in admitted) {
            ap.cancellation.checkpoint()
            checkKinds(premise, piece)
            if (trace) LoopPipelineTrace.record(config.index, key, "c5-admitted") {
                catalog(ap)
                text("scope", scope.toString())
                number("exit", exit.ordinal)
                this.premise("P", premise)
                this.facts("F", piece)
            }
            val store = if (isRootScope) summaries else portSummaries.at(exit)
            for (delta in store.addAdmittedAll(premise, piece)) {
                localEdgeDeltas++
                if (delta.layer == Layer.DEMAND) localDemandLayerEdges++
                if (isRootScope) pending += Publication(premise, delta)
                else localPublications.getOrPut(exit, ::ArrayList).add(Publication(premise, delta))
            }
        }
        if (pending.isNotEmpty() || localPublications.isNotEmpty()) requestWork()
    }

    internal fun erasesRun1StaticSummary(premise: PremiseKey, facts: Facts): Boolean =
        config.run1 && facts.base == STATIC && !premise.isZero &&
            (0 until premise.size).all { premise.member(it).base == STATIC }

    private fun flushPublications() {
        if (pendingTargets.isNotEmpty()) {
            val detachedTargets = pendingTargets
            pendingTargets = ArrayList()
            try {
                if (binding != null) binding.publishTargets(this, Collections.unmodifiableList(detachedTargets))
                else checkNotNull(targetPublicationSink).publishTargets(key, Collections.unmodifiableList(detachedTargets))
            } catch (error: Throwable) {
                pendingTargets.addAll(0, detachedTargets)
                throw error
            }
        }
        if (localPublications.isNotEmpty()) {
            val detachedLocal = localPublications.toList()
            localPublications.clear()
            for ((exit, rows) in detachedLocal) checkNotNull(binding).publish(this, exit, Collections.unmodifiableList(rows))
        }
        if (pending.isEmpty()) return
        val detached = pending
        pending = ArrayList()
        val batch: List<Publication> = Collections.unmodifiableList(detached)
        try {
            checkNotNull(publicationSink).publish(key, batch)
        } catch (error: Throwable) {
            pending.addAll(0, detached)
            throw error
        }
    }

    override open fun applyTarget(part: Subscription, row: TargetSummary, member: Int): Unit =
        callServices.applyTarget(part, row, member)
    override open fun applyStaticTarget(part: Subscription, row: TargetSummary, member: Int): Unit =
        callServices.applyStaticTarget(part, row, member)
    override open fun applySummary(part: Subscription, pub: Publication, member: Int): Unit =
        callServices.applySummary(part, pub, member)
    override open fun applyStaticSummary(part: Subscription, pub: Publication, member: Int): Unit =
        callServices.applyStaticSummary(part, pub, member)
    override open fun requestStaticGroups(part: Subscription, marks: RequestMarkSelection) {
        check(config.run1 && part.ref.premise.isFlow && part.added is FlowTree)
        val at = OperationInput(ResumeSite.CallStageInput(operation(part.ref.call, part.ref.stageOrdinal)),
            part.ref.premise, part.added, CallResumeState(part.ref.callerLayer))
        val cursor = marks.cursor()
        while (!cursor.isComplete) {
            ap.cancellation.checkpoint()
            cursor.step(256) { needGroups(at, it) }
        }
    }
    override open fun applyRecord(part: Subscription, record: Record): Unit = callServices.applyRecord(part, record)
    override open fun applyRecordView(part: Subscription, view: RecordLeafView, nonSubsumable: Boolean): Unit =
        callServices.applyRecordView(part, view, nonSubsumable)
    internal fun countRecordCrossing() { localRecordCrossings++ }
    internal fun countTriggerSeed() { localTriggerSeeds++ }

    /** Copy closed local-store gauges only. No child state remains in the method result. */
    internal fun includeClosedBlockMeasurements(
        blocks: Collection<BlockRunState>,
        completionStatistics: Collection<ScalarIdentityStatistics> = emptyList(),
    ) {
        cfgDeliveryHits += blocks.sumOf { it.cfgDeliveryHits }
        cfgDeliverySearches += blocks.sumOf { it.cfgDeliverySearches }
        cfgDeliveryVisitedNodes += blocks.sumOf { it.cfgDeliveryVisitedNodes }
        cfgDeliveryDestinations += blocks.sumOf { it.cfgDeliveryDestinations }
        cfgDeliveryMaxWidth = maxOf(cfgDeliveryMaxWidth, blocks.maxOfOrNull { it.cfgDeliveryMaxWidth } ?: 0)
        val snapshots = listOfNotNull(scalarIdentityStatistics) + blocks.mapNotNull { it.scalarIdentityStatistics } +
            completionStatistics
        if (snapshots.isEmpty()) return
        val reasons = LinkedHashMap<String, Long>()
        for (snapshot in snapshots) for ((reason, count) in snapshot.fallbackReasons)
            reasons[reason] = (reasons[reason] ?: 0L) + count
        scalarIdentityStatistics = ScalarIdentityStatistics(
            compactPoints = snapshots.sumOf { it.compactPoints },
            compactNormal = snapshots.sumOf { it.compactNormal },
            compactDemand = snapshots.sumOf { it.compactDemand },
            compactFlow = snapshots.sumOf { it.compactFlow },
            compactTaint = snapshots.sumOf { it.compactTaint },
            protectedNormal = snapshots.sumOf { it.protectedNormal },
            protectedDemand = snapshots.sumOf { it.protectedDemand },
            fullPoints = snapshots.sumOf { it.fullPoints },
            promotedPoints = snapshots.sumOf { it.promotedPoints },
            firstFullPoints = snapshots.sumOf { it.firstFullPoints },
            bitWords = snapshots.sumOf { it.bitWords },
            fullArrayCapacity = snapshots.sumOf { it.fullArrayCapacity },
            fallbackReasons = java.util.Collections.unmodifiableMap(reasons),
        )
    }

    private var joinedCaptured = false
    internal var executionReleased = false; private set

    internal open fun captureJoinedExports() {
        check(!executionReleased) { "Method execution was released" }
        if (joinedCaptured) return
        check(worklist.isEmpty && pending.isEmpty() && localPublications.isEmpty() && pendingTargets.isEmpty() && !hasPendingAbstractionWork) {
            "A method cannot capture unfinished work"
        }
        joinedCaptured = true // A failed capture must still be releasable without a second freezeRows call.
        frozenNormalContributorRows = normalRuleContributors.freezeRows()
        if (binding == null) context.delivery.let {
            cfgDeliveryHits = it.hits; cfgDeliverySearches = it.searches
            cfgDeliveryVisitedNodes = it.visitedNodes; cfgDeliveryDestinations = it.destinations
            cfgDeliveryMaxWidth = it.maxWidth
        } else binding.deliveryStatistics()?.let {
            cfgDeliveryHits = it.hits; cfgDeliverySearches = it.searches
            cfgDeliveryVisitedNodes = it.visited; cfgDeliveryDestinations = it.destinations
            cfgDeliveryMaxWidth = it.maxWidth
        }
        scalarIdentityStatistics = edgeStore?.scalarStatisticsSnapshot()
        if (isRootScope) bodyWorkSnapshot = bodyWork?.snapshot()
    }

    open fun freeze() {
        if (executionReleased) return
        check(worklist.isEmpty && pending.isEmpty() && localPublications.isEmpty() && pendingTargets.isEmpty() && !hasPendingAbstractionWork) {
            "A method cannot freeze with unfinished work"
        }
        var failure: Throwable? = null
        try { captureJoinedExports() } catch (error: Throwable) { failure = error }
        fun release(action: () -> Unit) {
            try { action() }
            catch (error: Throwable) {
                val first = failure
                if (first == null) failure = error
                else if (error !== first) first.addSuppressed(error)
            }
        }
        try {
            release { releaseAbstraction() }
            release { localServices.freeze() }
            release { callServices.freeze() }
            release { pointResumes?.clear() }
            pointResumes = null

        } finally {
            local = null
            calls = null
            formApplier = null
            publicationSink = null
            targetPublicationSink = null
            port = null
            runContext = null
            rootRouting = null
            worklist.clear()
            worklist = DeltaWorklist(flowFirst = mode.run1 && mode.markMode == MarkMode.FULL,
                batchManager = ap.takeIf { mode.run1 && mode.markMode == MarkMode.FULL })
            pending = ArrayList()
            localPublications = LinkedHashMap()
            bodyWork = null
            edgeStore = null
            initialStore = null
            temporary = RequestStorage()
            pendingTargets = ArrayList()
            resumeQueue = java.util.ArrayDeque()
            staticBatch = StaticBatch(staticSupplyProfile, ap.cancellation)
            executionReleased = true
        }
        failure?.let { throw it }
    }
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.store.*
import org.opentaint.dataflow.graph.PortId

private typealias Input = LocalInputValue
private typealias InputKey = LocalInputKey

/** Optional numeric census shared by one method's block links. No input or result history. */
internal class LocalSummaryMatchStatistics {
    var offers = 0L; internal set
    var freshInputGroups = 0L; internal set
    var freshInputDeltas = 0L; internal set
    var publicationRows = 0L; internal set
    var targetRows = 0L; internal set
    var candidatePairs = 0L; internal set
    var publicationCandidatePairs = 0L; internal set
    var publicationLinearPairBound = 0L; internal set
    var nativeMatches = 0L; internal set
    var ndCombinations = 0L; internal set
    var dataCallbacks = 0L; internal set
    var targetCallbacks = 0L; internal set

    fun diagnosticStatistics(): String =
        "localInputOffers=$offers localFreshInputGroups=$freshInputGroups localFreshInputDeltas=$freshInputDeltas " +
        "localPublishedRows=$publicationRows localPublishedTargetRows=$targetRows " +
        "localCandidatePairs=$candidatePairs localPublicationCandidatePairs=$publicationCandidatePairs " +
        "localPublicationLinearPairs=$publicationLinearPairBound " +
        "localNativeMatches=$nativeMatches localNdCombinations=$ndCombinations " +
        "localDataCallbacks=$dataCallbacks localTargetCallbacks=$targetCallbacks"
}

/** A local boundary has no call instruction, binding stages, or iteration counter. */
internal data class LocalLink(
    val parent: BlockScope,
    val point: PortId,
    val original: PremiseKey,
    val layer: Layer,
    val child: BlockScope,
)

/** Exact live inputs and admitted current publications for one child entry.
 * Saved records are replayed separately on every complete offer before this store is used.
 * All callbacks are queued under the original method's work reservation.
 */
internal class BlockSummaryLinks(
    private val ops: ApOps,
    private val mode: ApMode,
    val scope: BlockScope,
    private val data: (LocalLink, PortId, PremiseKey, Pattern, PremiseKey, Facts) -> Unit,
    private val terminal: (LocalLink, PremiseKey, Target) -> Unit,
    private val request: (LocalLink, Facts, TaintMark) -> Unit,
    private val matchStatistics: LocalSummaryMatchStatistics? = null,
) {
    private val ap get() = ops.manager
    private val application = LocalRelationApplication(ops, mode)
    private var inputDirectory: LocalInputDirectory? = LocalInputDirectory(ops)
    private val inputs: LocalInputDirectory get() = checkNotNull(inputDirectory) { "Local links are sealed" }
    private fun checkLive() { checkNotNull(inputDirectory) { "Local links are sealed" } }
    private val publications = LinkedHashMap<PortId, PublicationIndex>()
    private var targets = PublicationIndex(ap, ops)
    private val deliveries = ArrayDeque<Delivery>()
    private sealed interface Delivery {
        data class Data(val input: Input, val exit: PortId, val row: Publication, val member: Int,
                        val matched: Facts) : Delivery
        data class Terminal(val input: Input, val row: TargetSummary, val member: Int, val saved: Boolean) : Delivery
    }
    private data class NdKey(val parent: BlockScope, val point: PortId, val exit: PortId,
                             val premise: PremiseSet, val layer: Layer)
    private data class NdInput(val link: LocalLink, val initial: InitialAp, val layer: Layer) {
        lateinit var matched: TaintTree
    }
    private val joins = HashMap<NdKey, NdSummaryJoin<NdInput>>()
    private data class TerminalKey(val parent: BlockScope, val point: PortId, val premise: PremiseSet,
                                   val target: Target, val saved: Boolean)
    private data class TerminalInput(val link: LocalLink, val layer: Layer)
    private val terminalJoins = HashMap<TerminalKey, KaryJoin<TerminalInput>>()

    val hasPending: Boolean get() = deliveries.isNotEmpty()
    val inputGroups: Int get() = inputs.size

    fun offer(link: LocalLink, actual: Facts) {
        for (packet in ap.canonicalPackets(actual)) offerCanonical(link, packet)
    }

    private fun offerCanonical(link: LocalLink, actual: Facts) {
        checkLive()
        matchStatistics?.let { it.offers++ }
        require(link.child == scope)
        ap.cancellation.checkpoint()
        if (!RuntimeDataDomain.packet(link.original, actual)) return
        require(actual.layer == link.layer)
        val key = InputKey(link, actual.groupKey)
        val old = inputs[key]
        val fresh = if (old == null) {
            matchStatistics?.let { it.freshInputGroups++ }
            inputs[key] = Input(link, actual)
            actual
        } else {
            val (merged, delta) = ap.mergeAddDelta(old.value, actual)
            if (delta == null) return
            old.value = merged
            delta
        }
        matchStatistics?.let { it.freshInputDeltas++ }
        inputs.recordDelta(key, fresh)
        // Deliver the fresh packet only. The standing row retains the current union.
        for (packet in ap.canonicalPackets(fresh)) offerFresh(Input(link, packet))
    }

    private fun offerFresh(offered: Input) {
        val link = offered.link
        val fresh = offered.value
        val matches = HashMap<InitialAp, MatchedInput?>()
        for ((exit, index) in publications) {
            for ((row, member) in index.candidates(link.original, fresh, mode))
                queueData(offered, exit, row, member, matches)
            if (isStaticControl(offered)) for ((row, member) in index.staticCandidates())
                queueData(offered, exit, row, member, matches)
        }
        for ((row, member) in targets.targetCandidates(link.original, fresh, mode))
            deliveries += Delivery.Terminal(offered, row, member, saved = false)
        if (isStaticControl(offered)) for ((row, member) in targets.staticTargetCandidates())
            deliveries += Delivery.Terminal(offered, row, member, saved = false)
    }

    fun publish(exit: PortId, rows: List<Publication>) {
        checkLive()
        val index = publications.getOrPut(exit) { PublicationIndex(ap, ops, flowBacked = true) }
        val fresh = index.addAll(rows)
        matchStatistics?.let { stats ->
            stats.publicationRows += fresh.size
            for (row in fresh) stats.publicationLinearPairBound += inputs.size.toLong() * row.premise.size
        }
        // Snapshot before delivery. A callback can offer another local input.
        val matches = HashMap<InputKey, MutableMap<InitialAp, MatchedInput?>>()
        for (row in fresh) for ((input, member) in inputs.candidates(row.premise, mode)) {
            matchStatistics?.let { it.publicationCandidatePairs++ }
            val cache = matches.getOrPut(InputKey(input.link, input.value.groupKey)) { HashMap() }
            queueData(input, exit, row, member, cache)
        }
    }

    fun publishTargets(rows: TargetBatch) {
        checkLive()
        val fresh = targets.addTargets(rows)
        matchStatistics?.let { stats ->
            stats.targetRows += fresh.size
        }
        for (row in fresh) for ((input, member) in inputs.candidates(row.premise, mode)) {
            ap.cancellation.checkpoint()
            if (isStaticControl(input) && row.premise.member(member).base == STATIC ||
                application.targetArmLayer(input.value, row.premise.member(member), row.target,
                    saved = false, offeredLayer = input.link.layer) != null)
                deliveries += Delivery.Terminal(input, row, member, saved = false)
        }
    }

    /** The certified static lane changes the selected original as well as the packet.
     * Keep the raw selected packet for ordinary request callbacks. */
    private data class MatchedInput(val input: Input, val facts: Facts)
    private fun queueData(offered: Input, exit: PortId, row: Publication, member: Int,
                          cache: MutableMap<InitialAp, MatchedInput?>) {
        matchStatistics?.let { it.candidatePairs++ }
        val initial = row.premise.member(member)
        if (!cache.containsKey(initial)) {
            val input = if (isStaticControl(offered) && initial.base == STATIC)
                suppliedStaticInput(offered, initial) else offered
            matchStatistics?.let { it.nativeMatches++ }
            cache[initial] = ops.matchSummary(input.value, initial, mode, nativeRecordRead = false,
                role = SummaryMatchRole.CURRENT)?.let { MatchedInput(input, it) }
        }
        val matched = cache[initial] ?: return
        deliveries += Delivery.Data(matched.input, exit, row, member, matched.facts)
    }

    fun replaySavedTarget(link: LocalLink, actual: Facts, row: TargetSummary, member: Int) {
        checkLive()
        if (row.premise.isZero && row.target is Target.NormalTarget) return
        deliveries += Delivery.Terminal(Input(link, actual), row, member, saved = true)
    }

    /** Bounded draining makes every local callback visible to the method idle test. */
    fun drain(quantum: Int): Int {
        checkLive()
        require(quantum > 0)
        var done = 0
        while (done < quantum && deliveries.isNotEmpty()) {
            ap.cancellation.checkpoint()
            when (val next = deliveries.removeFirst()) {
                is Delivery.Data -> deliver(next)
                is Delivery.Terminal -> deliverTarget(next)
            }
            done++
        }
        return done
    }

    private fun output(input: Input, exit: PortId, row: PremiseKey, geometry: Pattern) = object : LocalRelationOut {
        override fun data(original: PremiseKey, value: Facts) {
            matchStatistics?.let { it.dataCallbacks++ }
            data(input.link, exit, row, geometry, original, value)
        }
        override fun target(original: PremiseKey, target: Target) {
            matchStatistics?.let { it.targetCallbacks++ }
            terminal(input.link, original, target)
        }
        override fun markRequest(mark: TaintMark) = request(input.link, input.value, mark)
    }

    private fun deliver(delivery: Delivery.Data) {
        val (input, exit, row, member, matchedInput) = delivery
        // A different geometry has a different loop growth classification.
        for (scalar in annotatedLoopScalars(ops, row.conclusion)) {
            val geometry = ops.leaves(scalar).single()
            when (val premise = row.premise) {
                is InitialAp -> application.applyMatched(matchedInput, input.link.original, premise, scalar,
                    output(input, exit, premise, geometry))
                is PremiseSet -> {
                    check(!mode.run1 && mode.direction == Direction.FORWARD)
                    val matched = matchedInput as? TaintTree ?: continue
                    val key = NdKey(input.link.parent, input.link.point, exit, premise, scalar.layer)
                    val join = joins.getOrPut(key) { NdSummaryJoin(ap, premise.size) }
                    val binding = NdInput(input.link, premise.member(member), matched.layer).also { it.matched = matched }
                    fun emit(parts: List<NdInput>, value: TaintTree) {
                        matchStatistics?.let { it.ndCombinations++ }
                        var original: PremiseKey = ap.zero
                        for (part in parts) original = ap.union(original, part.link.original)
                        val complete = Input(input.link.copy(original = original), input.value)
                        for (piece in annotatedLoopScalars(ops, value))
                            application.applyCombination(parts.map { LocalRelationBinding(it.link.original, it.initial, it.matched) },
                                piece as TaintTree, output(complete, exit, premise, ops.leaves(piece).single()))
                    }
                    for ((parts, value) in join.addSubscription(member, binding) { prior, offered ->
                        val (merged, delta) = ap.mergeAddDelta(prior.matched, offered.matched)
                        prior.matched = merged as TaintTree
                        delta != null
                    }) emit(parts, value)
                    for ((parts, value) in join.addConclusion(scalar as TaintTree)) emit(parts, value)
                }
            }
        }
    }

    private fun deliverTarget(delivery: Delivery.Terminal) {
        val (offered, row, member, saved) = delivery
        val input = if (isStaticControl(offered) && row.premise.member(member).base == STATIC)
            suppliedStaticInput(offered, row.premise.member(member)) else offered
        val layer = application.targetArmLayer(input.value, row.premise.member(member), row.target,
            saved, input.link.layer) ?: return
        val binding = TerminalInput(input.link, layer)
        val combinations = when (val premise = row.premise) {
            is InitialAp -> listOf(listOf(binding))
            is PremiseSet -> terminalJoins.getOrPut(
                TerminalKey(input.link.parent, input.link.point, premise, row.target, saved)
            ) { KaryJoin(premise.size, ap.cancellation) }.add(member, binding)
        }
        for (parts in combinations) {
            var original: PremiseKey = ap.zero
            for (part in parts) original = ap.union(original, part.link.original)
            if (row.target !is Target.NormalTarget || parts.all { it.layer == Layer.NORMAL }) {
                matchStatistics?.let { it.targetCallbacks++ }
                terminal(input.link, original, row.target)
            }
        }
    }

    private fun isStaticControl(input: Input): Boolean =
        mode.run1 && input.link.original.isZero && input.value is Reach

    /**
     * Reuse the run-1 static summary lane. The physical read has already received
     * this exact/static-field input from the pool before it can publish its row.
     * Replaying that certified original through a local ZERO continuation needs
     * no new read, mark interest, writer registration or pool supply.
     */
    private fun suppliedStaticInput(input: Input, initial: InitialAp): Input {
        validateRun1Initial(initial, mode.fieldLimit)
        check(initial.base == STATIC && initial.pathData.size in 1..2)
        val actual = ops.startFact(initial, mode).withLayer(Layer.DEMAND)
        return Input(input.link.copy(original = initial, layer = Layer.DEMAND), actual)
    }

    fun forEachInput(visit: (LocalLink, Facts) -> Unit) {
        checkLive()
        val snapshot = ArrayList<Pair<LocalLink, Facts>>()
        inputs.visitCanonical { link, value -> snapshot += link to value }
        for ((link, value) in snapshot) { ap.cancellation.checkpoint(); visit(link, value) }
    }

    internal fun detachJoinedInputs(): JoinedLocalInputs {
        check(deliveries.isEmpty()) { "Local deliveries must drain before input detach" }
        val owned = checkNotNull(inputDirectory) { "Local inputs were already detached" }
        owned.releaseCandidateIndex()
        inputDirectory = null
        return JoinedLocalInputs(owned)
    }

    fun clear() {
        check(deliveries.isEmpty()) { "Local deliveries must drain before release" }
        inputDirectory?.clear()
        inputDirectory = null
        publications.clear(); joins.clear(); terminalJoins.clear()
        targets = PublicationIndex(ap, ops)
    }
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.graph.CompactGraph
import org.opentaint.dataflow.util.Cancellation
import java.util.ArrayDeque
import java.util.IdentityHashMap

/** Optional numeric observer. It retains no fact, premise, graph, or trie node.
 * Point counts are exact packet events. Membership counts are sampled packet
 * annotations, not retained-set sizes. A cyclic SCC is not a provenance trace. */
internal class BodyWorkStatistics(graph: CompactGraph, private val cancellation: Cancellation) {
    private val components = diagnosticComponents(graph)
    private val counts = LongArray(3)
    private val points = Array(3) { LongArray(graph.size) }
    private val depths = Array(3) { LongArray(17) }
    private val kinds = Array(3) { LongArray(3) }
    private val sampled = LongArray(3)
    private val memberships = LongArray(3)
    private val protected = LongArray(3)
    private val samples = ArrayDeque<BodyWorkSample>()
    private var dropped = 0L
    private var saturated = false
    private var methodCandidates = 0L
    private var blockCandidates = 0L
    val candidatePackets: Long get() = counts[2]

    fun processed(index: Int, premise: PremiseKey, facts: Facts) = observe(0, index, premise, facts)
    fun fresh(index: Int, premise: PremiseKey, facts: Facts) = observe(1, index, premise, facts)
    fun candidate(premise: PremiseKey, facts: Facts, internalBlock: Boolean = false) {
        if (internalBlock) blockCandidates++ else methodCandidates++
        observe(2, -1, premise, facts)
    }

    private fun observe(stage: Int, index: Int, premise: PremiseKey, facts: Facts) {
        val ordinal = ++counts[stage]
        if (index >= 0) points[stage][index]++
        val root = when (facts) { is Reach -> null; is FlowTree -> facts.root; is TaintTree -> facts.root }
        val depth = root?.boundedDepth ?: 0
        depths[stage][minOf(16, depth)]++
        val kind = when (facts) { is Reach -> 0; is FlowTree -> 1; is TaintTree -> 2 }
        kinds[stage][kind]++
        if (ordinal > 16 && ordinal % 1024L != 0L) return
        cancellation.checkpoint()
        val ordinary = when (facts) {
            is Reach -> 1L
            is FlowTree -> count(facts.root) { if (it.isEmpty) 0 else 1 }
            is TaintTree -> count(facts.root) { it.exact.size.toLong() + it.any.size }
        }
        val protection = if (facts is TaintTree && facts.nonSubsumable != null)
            count(facts.nonSubsumable) { it.exact.size.toLong() + it.any.size } else 0L
        if (ordinary == null || protection == null) { dropped++; return }
        sampled[stage]++
        memberships[stage] = sum(memberships[stage], ordinary)
        protected[stage] = sum(protected[stage], protection)
        val tail = when (facts) { is Reach -> "ZERO"; is FlowTree -> facts.tail.name; is TaintTree -> facts.anyTail.name }
        val base = when (facts.base) { AccessPathBase.Zero -> "ZERO"; AccessPathBase.ClassStatic -> "STATIC"; else -> facts.base.javaClass.simpleName }
        val initial = when { premise.isZero -> "ZERO"; premise is PremiseSet -> "ND"; premise.isFlow -> "FLOW"; else -> "TAINT" }
        var node = root
        val path = ArrayList<Int>()
        while (node != null && path.size < 12 && node.accessorData != null) {
            path += node.accessorData[0]
            node = node.childData!![0]
        }
        val leaf = node?.leaf
        val markIds = if (leaf is TaintLeaves)
            (leaf.exact.data.take(2) + leaf.any.data.take(2)).distinct() else emptyList()
        val origins = (0 until minOf(4, premise.size)).map { ordinal ->
            val member = premise.member(ordinal)
            BodyWorkInitial(member.base.toString().take(100), member.pathArray.take(12), member.tail,
                (member.mark as? MarkSlot.Concrete)?.mark?.id,
                (member.exclusion as? ExclusionSet.Concrete)?.ids?.take(8) ?: emptyList())
        }
        if (samples.size == 64) samples.removeFirst()
        samples.addLast(BodyWorkSample(stage, index, if (index < 0) -1 else components.first[index],
            index >= 0 && components.second[index], initial, base, kind, facts.layer, tail, depth,
            ordinary, protection, path.toList(), origins, premise.size > 4, markIds))
    }

    private class Frame<P : TrieLeaf>(val node: TrieNode<P>, var next: Int = 0)
    private fun <P : TrieLeaf> count(root: TrieNode<P>, weight: (P) -> Long): Long? {
        val memo = IdentityHashMap<TrieNode<P>, Long>()
        val stack = ArrayDeque<Frame<P>>()
        stack.addLast(Frame(root))
        while (stack.isNotEmpty()) {
            cancellation.checkpoint()
            if (memo.size + stack.size > 4096) return null
            val frame = stack.peekLast()
            val children = frame.node.childData
            if (children != null && frame.next < children.size) {
                val child = children[frame.next++]
                if (!memo.containsKey(child)) stack.addLast(Frame(child))
                continue
            }
            var result = weight(frame.node.leaf)
            children?.forEach { result = sum(result, memo.getValue(it)) }
            memo[frame.node] = result
            stack.removeLast()
        }
        return memo.getValue(root)
    }

    private fun sum(a: Long, b: Long): Long = if (Long.MAX_VALUE - a < b) {
        saturated = true; Long.MAX_VALUE
    } else a + b

    fun snapshot(): BodyWorkSnapshot = BodyWorkSnapshot(counts.toList(), depths.map { it.toList() },
        kinds.map { it.toList() }, sampled.toList(), memberships.toList(), protected.toList(), dropped,
        saturated, points[0].indices.filter { components.second[it] }.sumOf { points[0][it] },
        points[1].indices.filter { components.second[it] }.sumOf { points[1][it] },
        points[0].indices.sortedByDescending { points[0][it] + points[1][it] }.take(12).map { index ->
            BodyWorkPoint(index, components.first[index], components.second[index], points[0][index], points[1][index])
        }, samples.toList(), methodCandidates, blockCandidates)
}

internal data class BodyWorkPoint(val point: Int, val component: Int, val cyclic: Boolean,
                                  val processed: Long, val fresh: Long)
internal data class BodyWorkInitial(val base: String, val path: List<Int>, val tail: Tail,
    val concreteMark: Int?, val exclusions: List<Int>)
internal data class BodyWorkSample(val stage: Int, val point: Int, val component: Int, val cyclic: Boolean,
    val originalKind: String, val baseKind: String, val factsKind: Int, val layer: Layer, val tail: String,
    val maxDepth: Int, val memberships: Long, val protectedMemberships: Long, val firstPath: List<Int>,
    val initials: List<BodyWorkInitial>, val omittedInitials: Boolean, val exampleMarkIds: List<Int>)
internal data class BodyWorkSnapshot(val packets: List<Long>, val maximumDepthBins: List<List<Long>>,
    val kindPackets: List<List<Long>>, val sampledPackets: List<Long>, val sampledMemberships: List<Long>,
    val sampledProtected: List<Long>, val droppedSamples: Long, val saturated: Boolean,
    val cyclicProcessedPackets: Long, val cyclicFreshPackets: Long,
    val topPoints: List<BodyWorkPoint>, val samples: List<BodyWorkSample>,
    val methodCandidatePackets: Long, val blockCandidatePackets: Long) {
    val processedPackets: Long get() = packets[0]
    val freshPackets: Long get() = packets[1]
    val candidatePackets: Long get() = packets[2]
}

/** Iterative Kosaraju on the selected directed CFG. Graph state does not escape. */
internal fun diagnosticComponents(graph: CompactGraph): Pair<IntArray, BooleanArray> {
    val seen = BooleanArray(graph.size)
    val order = ArrayList<Int>(graph.size)
    val todo = ArrayDeque<Int>()
    for (start in 0 until graph.size) {
        if (seen[start]) continue
        todo.addLast(start)
        while (todo.isNotEmpty()) {
            val item = todo.removeLast()
            if (item < 0) { order += item.inv(); continue }
            if (seen[item]) continue
            seen[item] = true
            todo.addLast(item.inv())
            graph.forEachSuccessor(item) { if (!seen[it]) todo.addLast(it) }
        }
    }
    val component = IntArray(graph.size) { -1 }
    val sizes = ArrayList<Int>()
    for (start in order.asReversed()) {
        if (component[start] >= 0) continue
        val id = sizes.size
        var size = 0
        todo.addLast(start)
        component[start] = id
        while (todo.isNotEmpty()) {
            val item = todo.removeLast()
            size++
            graph.forEachPredecessor(item) { next ->
                if (component[next] < 0) { component[next] = id; todo.addLast(next) }
            }
        }
        sizes += size
    }
    val cyclic = BooleanArray(graph.size) { sizes[component[it]] > 1 }
    for (index in 0 until graph.size) graph.forEachSuccessor(index) { if (it == index) cyclic[index] = true }
    return component to cyclic
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.store.AddedFactAccumulator
import org.opentaint.dataflow.bidi.store.CallerRef
import org.opentaint.dataflow.bidi.store.PathTrie
import it.unimi.dsi.fastutil.ints.IntOpenHashSet

/** The caller runner owns exact added groups, indexed as the transpose of replay. */
class CalleeSubscriptions(private val ops: ApOps, private val statistics: N2Statistics? = null) {
    private val values = AddedFactAccumulator(ops.manager)
    private val callees = ArrayList<MethodKey>()
    private var index = PathTrie<Int>(ops.manager.cancellation)
    private val zeroParts = LinkedHashMap<CallerRef, Subscription>()
    private var postings = 0L
    private var visitingQuestion = false

    /** A queued replay keeps the established fresh delta, not an old cumulative root. */
    internal inner class Admission(val fresh: Subscription, private val handle: Int, val growth: Boolean = false) {
        val current: Subscription get() {
            if (handle < 0) return fresh
            val value = values.snapshot(handle)
            return Subscription(callees[handle], value.ref, value.group.layer, value.facts)
        }
    }

    fun add(sub: Subscription): Subscription? = admit(sub)?.fresh

    internal fun admit(sub: Subscription): Admission? {
        ops.manager.cancellation.checkpoint()
        if (!RuntimeDataDomain.packet(sub.ref.premise, sub.added)) return null
        check(!visitingQuestion) { "Question effects must be queued before changing N2 inputs" }
        if (sub.zeroOnly) {
            check(sub.ref.premise.isZero) { "A zero-only subscription needs a zero caller premise" }
            check(sub.added is Reach) { "A zero-only subscription needs REACH" }
            check(sub.linkLayer == sub.added.layer) { "The link layer must be the added fact's layer" }
            if (sub.ref in zeroParts) return null
            zeroParts[sub.ref] = sub
            statistics?.accepted(zeroOnly = true)
            return Admission(sub, -1)
        }
        val update = values.add(sub.ref, sub.linkLayer, sub.added) ?: return null
        if (update.newGroup) callees += sub.callee
        statistics?.accepted(newGroup = update.newGroup)
        ops.manager.forEachLeafPosition(update.delta) { base, path ->
            if (index.add(base, path, update.handle) && statistics != null) {
                postings++
                statistics.posted()
            }
        }
        // This immutable delta is retained only by the pending replay callback.
        return Admission(sub.copy(added = update.delta), update.handle, growth = !update.newGroup)
    }

    /** Request overlap differs from run-1 summary applicability: ancestors are candidates too.
     *  The owner must queue every effect, including local effects, until this finite visit ends. */
    internal fun visitRequestBatch(rows: List<RequestedRow>, visit: (Subscription) -> Unit) {
        ops.manager.cancellation.checkpoint()
        check(!visitingQuestion) { "A request visit cannot recursively enter the caller directory" }
        visitingQuestion = true
        try {
            // One set for the whole batch, not one set per requested slot.
            val seen = IntOpenHashSet()
            for (row in rows) {
                ops.manager.cancellation.checkpoint()
                index.visitAround(row.slot.base, row.slot.pathData) { handle ->
                    ops.manager.cancellation.checkpoint()
                    if (seen.add(handle)) {
                        val value = values.snapshot(handle)
                        for (packet in ops.manager.canonicalPackets(value.facts))
                            visit(Subscription(callees[handle], value.ref, value.group.layer, packet))
                    }
                }
            }
        } finally { visitingQuestion = false }
    }

    fun candidates(pub: Publication, member: Int, mode: ApMode): Sequence<Subscription> =
        candidates(pub.premise, member, mode)

    fun candidates(premise: PremiseKey, member: Int, mode: ApMode): Sequence<Subscription> = sequence {
        ops.manager.cancellation.checkpoint()
        val initial = premise.member(member)
        val ids = LinkedHashSet<Int>()
        if (mode.run1) {
            ids += index.lookupExtensions(initial.base, initial.pathData)
            // Candidate ancestors are checked by the same full AP predicate
            // as replay. Exact ancestors and excluded components do not match.
            ids += index.lookupPrefixes(initial.base, initial.pathData)
        }
        else {
            ids += index.lookupPrefixes(initial.base, initial.pathData)
            if (initial.mark is MarkSlot.Star || initial.tail == Tail.STAR) ids += index.lookupExtensions(initial.base, initial.pathData)
        }
        // Capture every candidate value before callbacks can grow this directory.
        val snapshot = ArrayList<Subscription>(ids.size + if (premise.isZero) zeroParts.size else 0)
        for (id in ids) {
            ops.manager.cancellation.checkpoint()
            val value = values.snapshot(id)
            for (packet in ops.manager.canonicalPackets(value.facts))
                snapshot += Subscription(callees[id], value.ref, value.group.layer, packet)
        }
        if (premise.isZero) snapshot.addAll(zeroParts.values)
        for (sub in snapshot) {
            ops.manager.cancellation.checkpoint()
            yield(sub)
        }
    }

    /** The manager calls this only after all runner jobs join, before clear().
     * No caller input can grow, so visit one current value at a time without a
     * second Facts snapshot directory. Candidate indexes are the live protocol's. */
    internal fun visitJoinedCandidates(pub: Publication, mode: ApMode, visit: (Subscription) -> Unit) {
        check(mode.run1 && pub.premise is InitialAp) { "Joined writer binding is a run-1 singleton operation" }
        check(!visitingQuestion) { "A joined borrow cannot overlap a live request visit" }
        val initial = pub.premise
        val ids = LinkedHashSet<Int>()
        ids += index.lookupExtensions(initial.base, initial.pathData)
        ids += index.lookupPrefixes(initial.base, initial.pathData)
        for (id in ids) {
            ops.manager.cancellation.checkpoint()
            val value = values.snapshot(id)
            for (packet in ops.manager.canonicalPackets(value.facts))
                visit(Subscription(callees[id], value.ref, value.group.layer, packet))
        }
        if (initial.isZero) for (part in zeroParts.values) {
            ops.manager.cancellation.checkpoint()
            visit(part)
        }
    }

    /** A genuine run-1 ZERO control port is a view of the existing caller input. */
    internal fun staticControlCandidates(): List<Subscription> {
        ops.manager.cancellation.checkpoint()
        val out = ArrayList<Subscription>()
        for (handle in index.lookupExtensions(org.opentaint.dataflow.ap.ifds.AccessPathBase.Zero, EMPTY_PATH)) {
            ops.manager.cancellation.checkpoint()
            val value = values.snapshot(handle)
            if (!value.ref.premise.isZero || value.facts !is Reach) continue
            out += Subscription(callees[handle], value.ref, value.group.layer, value.facts)
        }
        return out
    }

    /** Called only after the runner joins. */
    fun clear() {
        check(!visitingQuestion) { "A live question visit cannot release its input directory" }
        statistics?.releaseDirectory(values.size, zeroParts.size, postings)
        values.clear()
        callees.clear()
        zeroParts.clear()
        index = PathTrie(ops.manager.cancellation)
        postings = 0L
    }
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.graph.CompactGraph
import org.opentaint.dataflow.util.Cancellation
import java.util.BitSet

/** One actor, graph direction and rule view. Rows contain no facts or forms. */
internal class CfgDeliveryCache(
    private val graph: CompactGraph,
    private val cancellation: Cancellation,
    private val relevant: (Int, AccessPathBase) -> Boolean,
) {
    private val rows = arrayOfNulls<MutableMap<AccessPathBase, IntArray>>(graph.size)
    var hits = 0L; private set
    var searches = 0L; private set
    var visitedNodes = 0L; private set
    var destinations = 0L; private set
    var maxWidth = 0; private set

    /** Borrowed immutable first-relevant frontier. Empty is a completed hit. */
    fun targets(start: Int, base: AccessPathBase): IntArray {
        cancellation.checkpoint()
        rows[start]?.get(base)?.let { hits++; return it }
        val visited = BitSet(graph.size)
        val todo = IntArray(graph.size)
        var read = 0
        var write = 1
        todo[0] = start
        visited.set(start)
        val found = ArrayList<Int>()
        while (read < write) {
            cancellation.checkpoint()
            val node = todo[read++]
            if (relevant(node, base)) found += node
            else graph.forEachSuccessor(node) { next ->
                if (!visited[next]) { visited.set(next); todo[write++] = next }
            }
        }
        // A cancelled traversal never publishes a partial or empty placeholder.
        cancellation.checkpoint()
        val result = found.toIntArray()
        val row = rows[start] ?: HashMap<AccessPathBase, IntArray>().also { rows[start] = it }
        row[base] = result
        searches++
        visitedNodes += read
        destinations += result.size
        maxWidth = maxOf(maxWidth, result.size)
        return result
    }
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.ApManager
import org.opentaint.dataflow.bidi.ap.FlowTree
import org.opentaint.dataflow.bidi.ap.RuntimeDataDomain
import org.opentaint.ir.api.common.cfg.CommonInst

/** Ordinary input queues. Completed output deduplication belongs to MethodEdgeStore. */
class DeltaWorklist(private val flowFirst: Boolean = false, batchManager: ApManager? = null) {
    private val zero = ArrayList<EdgeDelta>()
    private val flow = ArrayList<EdgeDelta>()
    private val other = ArrayList<Any>() // EdgeDelta or PendingWork.MarkedBatch
    private val batches = batchManager?.let(::NeutralBatchWorklist)

    val isEmpty: Boolean get() = zero.isEmpty() && flow.isEmpty() && other.isEmpty()
    val hasZeroWork: Boolean get() = zero.isNotEmpty()
    internal val hasFlowWork: Boolean get() = flow.isNotEmpty()
    val size: Int get() = zero.size + flow.size + other.size

    fun add(delta: EdgeDelta) {
        if (!RuntimeDataDomain.packet(delta.premise, delta.facts)) return
        when {
            delta.zeroToZero -> zero += delta
            flowFirst && delta.facts is FlowTree -> flow += delta
            else -> {
                val admission = if (!hasZeroWork) batches?.offer(delta) else null
                if (admission == null) other += delta
                else if (admission.newlyQueued) other += admission.work
            }
        }
    }

    fun removeNext(): EdgeDelta = when (val work = removeItem()) {
        is EdgeDelta -> work
        is PendingWork.MarkedBatch -> {
            val (initial, facts) = work.batch.removeFirst()
            addBatch(work.node, work.batch)
            EdgeDelta(initial, work.node, facts)
        }
        else -> error("Unknown work item")
    }

    fun removeNextBatch(): PendingWork = when (val work = removeItem()) {
        is EdgeDelta -> PendingWork.Scalar(work)
        is PendingWork.MarkedBatch -> work
        else -> error("Unknown work item")
    }

    private fun removeItem(): Any {
        zero.removeLastOrNull()?.let { return it }
        flow.removeLastOrNull()?.let { return it }
        val work = other.removeLast()
        if (work is PendingWork.MarkedBatch) batches?.removed(work)
        return work
    }

    /** Retain an unfinished quantum before any work barrier or yield. */
    fun addBatch(node: CommonInst, batch: NeutralRelationBatch) {
        if (batch.isEmpty) return
        val admission = batches?.retain(node, batch)
        if (admission == null) other += PendingWork.MarkedBatch(node, batch)
        else if (admission.newlyQueued) other += admission.work
    }

    fun clear() {
        zero.clear()
        flow.clear()
        other.clear()
        batches?.clear()
    }
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.ap.ifds.AccessPathBase
