import org.opentaint.dataflow.bidi.interp.RuleKind
import org.opentaint.ir.api.common.cfg.CommonInst

/** All application modes use the same AP operations and source hooks. */
internal class EngineAlgebra(private val core: BlockRunState) : FactAlgebra<PremiseKey, Facts> {
    private fun input(at: Place, premise: PremiseKey, facts: Facts): OperationInput =
        OperationInput(at.site ?: ResumeSite.StatementInput(core.operation(at.node)), premise, facts,
            at.callerLayer?.let { CallResumeState(it, at.identityCandidate, at.pendingDemotion) })

    override fun reached(s: StatementSummary, premise: PremiseKey, c: Facts, at: Place) =
        core.reachedOperations(s, input(at, premise, c))
    override fun base(c: Facts): AccessPathBase {
        core.ap.cancellation.checkpoint()
        return c.base
    }
    override fun filter(c: Facts, filter: TypeFilter): Facts? = core.ops.filter(c, filter)
    override fun applyEdge(me: MicroEdge, c: Facts, premise: PremiseKey, statementEdge: Boolean,
                           out: ResultSink) {
        if (!RuntimeDataDomain.packet(premise, c) || !RuntimeDataDomain.producer(me) || disabledStaticEdge(me)) return
        core.ops.applyEdge(c, premise, me.edge, statementEdge, core.mode,
            core.collect(premise, c, out), may = me.may, ruleAssignment = me.isRuleAssignment)
    }

    override fun applyEdgeAt(me: MicroEdge, c: Facts, premise: PremiseKey, at: Place, out: ResultSink) {
        if (!RuntimeDataDomain.packet(premise, c) || !RuntimeDataDomain.producer(me) || disabledStaticEdge(me)) return
        core.ops.applyEdge(c, premise, me.edge, at.statementEdge, core.mode,
            core.collect(input(at, premise, c), out), may = me.may, ruleAssignment = me.isRuleAssignment)
    }

    private fun disabledStaticEdge(me: MicroEdge): Boolean = core.config.disableRun1Statics && (
        core.dropsStaticField(me.edge.from) || core.dropsStaticField(me.edge.to) ||
            // A configured source on a static read emits ZERO -> lhs directly.
            me.actionId?.occurrence?.kind == RuleKind.FIELD_SOURCE)

    override fun operationResult(me: MicroEdge?, premise: PremiseKey, input: Facts, result: Facts, at: Place, out: ResultSink) {
        if (!RuntimeDataDomain.packet(premise, input) || !RuntimeDataDomain.packet(premise, result)) return
        val operationInput = input(at, premise, input)
        val write = at.staticOperations.filterIsInstance<StaticOperation.Write>().firstOrNull {
            if (me != null) (it.transfer != null && (it.transfer == me.forward || it.transfer == me.edge)) ||
                (it.action != null && it.action == me.actionId)
            else when {
                at.completedAction != null -> it.action == at.completedAction
                at.completedConjunction != null -> it.action == null && it.transfer == null &&
                    it.target.fact == at.completedConjunction.target
                else -> false
            }
        }
        core.emitOperationResult(operationInput, write, result, out)
    }

    override fun conjunction(cj: ConjunctiveEdge, premise: PremiseKey, c: Facts, node: CommonInst,
                             out: ResultSink) {
        core.localServices.conjunction(cj, premise, c, node, out)
    }

    override fun conjunctionAt(cj: ConjunctiveEdge, premise: PremiseKey, c: Facts, at: Place, out: ResultSink) =
        core.localServices.conjunctionAt(cj, premise, c, at.node, input(at, premise, c), out)

    override fun sourcePredicate(source: SourceRuleOccurrence, premise: PremiseKey, c: Facts, node: CommonInst,
                                 statementEdge: Boolean, out: ResultSink) {
        core.localServices.sourcePredicate(source, premise, c, node, statementEdge, out)
    }

    override fun sourcePredicateAt(source: SourceRuleOccurrence, premise: PremiseKey, c: Facts, at: Place, out: ResultSink) =
        core.localServices.sourcePredicateAt(source, premise, c, at.node, at.statementEdge, input(at, premise, c), out)

    override fun sourcePredicateActionsAt(source: SourceRuleOccurrence, premise: PremiseKey, c: Facts, at: Place,
                                          out: (PremiseKey, Facts, org.opentaint.dataflow.bidi.interp.ActionId?) -> Unit) =
        core.localServices.sourcePredicateActionsAt(source, premise, c, at.node, at.statementEdge, input(at, premise, c), out)

    override fun allowsSource(node: CommonInst, me: MicroEdge): Boolean =
        !core.config.seededSources || core.config.seeds.allowsSource(core.key, node, me.forward, me.actionId)

    override fun acceptedSource(application: AcceptedSource<PremiseKey, Facts>) {
        if (!RuntimeDataDomain.packet(application.original, application.input) ||
            !RuntimeDataDomain.packet(application.resultPremise, application.rawResult) ||
            !RuntimeDataDomain.producer(application.edge)) return
        core.ap.cancellation.checkpoint()
        if (core.forward) return
        core.sourceHits?.add(core.key, application.at.node, application.edge.forward, application.edge.actionId)
        if (application.edge.isSource) core.emitTarget(application.original, Target.DemandTarget)
    }
}

package org.opentaint.dataflow.bidi.engine

import java.util.PriorityQueue

/** Runner-owned queue: actor state is read once when each immutable priority key is made. */
class EventQueue {
    private class Entry(val event: RunEvent, val rank: Int, val steps: Long, val sequence: Long)
    private val heap = PriorityQueue(compareBy<Entry>({ it.rank }, { it.steps }, { it.sequence }))
    private var sequence = 0L

    fun add(event: RunEvent) {
        val (rank, steps) = when (event) {
            is RunEvent.Work -> (if (event.analyzer.hasZeroWork) 0 else 2) to event.analyzer.steps
            else -> 1 to 0L
        }
        heap.add(Entry(event, rank, steps, sequence++))
    }

    fun poll(): RunEvent? = heap.poll()?.event
    fun isEmpty(): Boolean = heap.isEmpty()

    /** The manager calls this only after joining the owning runner. */
    fun clear() = heap.clear()
}

package org.opentaint.dataflow.bidi.engine

/** One run counts accepted events, live handlers and its start-batch reservation. */
class InFlight(private val onZero: () -> Unit) {
    private val lock = Any()
    private var count = 0L
    private var handledCount = 0L

    val pending: Long get() = synchronized(lock) { count }
    val handled: Long get() = synchronized(lock) { handledCount }

    /** Reserve before an event becomes visible in a channel or a local queue. */
    fun beforeSend() {
        synchronized(lock) { count++ }
    }

    /** A completed handler releases only after all its sends and local-work enqueues. */
    fun afterHandler() = release(countHandled = true)

    /** A failed send releases its reservation without reporting a handled event. */
    fun rejectedSend() = release(countHandled = false)

    private fun release(countHandled: Boolean) {
        val zero = synchronized(lock) {
            check(count > 0L) { "An in-flight release requires a live reservation" }
            if (countHandled) handledCount++
            count--
            count == 0L
        }
        // The manager serializes admission and terminal selection with its outer lock.
        // Keep this callback outside our bookkeeping lock to avoid lock inversion.
        if (zero) onZero()
    }
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.store.*
import org.opentaint.dataflow.graph.PortId
import java.util.IdentityHashMap

internal enum class JoinedPreparationPhase { CAPTURED, SEALED, RELEASED, BEFORE_BIND, BOUND, CLOSED }

/** Plain stopped-owner values. No actor, runtime, runner or callback is captured. */
internal class JoinedStaticSource(
    val owner: OwnedScope,
    private val root: RunSummaryStore?,
    private val ports: PortSummaryStores?,
    val outgoingDemandTargets: Set<TargetSummary>,
    val privateSeeds: StaticGuidanceSeedStore,
    private val rawWrites: KilledStaticWriteStore,
) {
    fun exitStores(): Sequence<Pair<PortId, RunSummaryStore>> =
        root?.let { sequenceOf(PortId.ROOT_EXIT to it) } ?: checkNotNull(ports).entries()
    fun freezeWrites(): FrozenStaticWrites = rawWrites.freeze(
        exitStores().flatMap { it.second.all() }, privateSeeds.frozenRows())
}

/** Joined-only directories. Every map entry keeps its original complete owner key. */
internal class JoinedBindingLease : AutoCloseable {
    private val local = LinkedHashMap<OwnedScope, JoinedLocalInputs>()
    private val callerOwners = IdentityHashMap<SubscriptionManager, JoinedCallerInputs>()
    private val callers = LinkedHashMap<MethodKey, List<JoinedCallerInputs>>()
    private var closed = false

    fun addLocal(method: MethodKey, inputs: Map<BlockScope, JoinedLocalInputs>) {
        check(!closed)
        try {
            for ((scope, reader) in inputs) {
                val owner = OwnedScope(method, scope)
                check(owner !in local) { "Joined local owner was already captured" }
                local[owner] = reader
            }
        } catch (error: Throwable) {
            // The lease retains registered owners; close every reader it failed to adopt.
            for ((scope, reader) in inputs) if (local[OwnedScope(method, scope)] !== reader) try {
                reader.close()
            } catch (closeError: Throwable) { if (closeError !== error) error.addSuppressed(closeError) }
            throw error
        }
    }
    fun addCallers(storage: SummaryStorage) {
        check(!closed)
        callers[storage.method] = storage.detachJoinedSubscribers { subscriber ->
            callerOwners[subscriber] ?: subscriber.detachJoinedInputs().also { reader ->
                try { callerOwners[subscriber] = reader } catch (error: Throwable) {
                    try { reader.close() } catch (closeError: Throwable) {
                        if (closeError !== error) error.addSuppressed(closeError)
                    }
                    throw error
                }
            }
        }
    }
    fun visitLocalInputs(owner: OwnedScope, visit: (LocalLink, Facts) -> Unit) {
        check(!closed) { "Joined binding lease is closed" }
        local[owner]?.visit(visit)
    }
    fun visitCallerInputs(method: MethodKey, writer: Publication, mode: ApMode, visit: (Subscription) -> Unit) {
        check(!closed) { "Joined binding lease is closed" }
        for (reader in callers[method].orEmpty()) reader.visit(method, writer, mode, visit)
    }
    override fun close() {
        if (closed) return
        closed = true
        var failure: Throwable? = null
        fun close(action: () -> Unit) {
            try { action() } catch (error: Throwable) {
                val first = failure
                if (first == null) failure = error else if (first !== error) first.addSuppressed(error)
            }
        }
        for (reader in local.values) close { reader.close() }
        for (reader in callerOwners.values) close { reader.close() }
        local.clear(); callers.clear(); callerOwners.clear()
        failure?.let { throw it }
    }
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.ApMode
import org.opentaint.dataflow.bidi.ap.MethodKey

/** Moved existing per-callee accumulators and indexes. No live subscription port. */
internal class JoinedCallerInputs internal constructor(
    private var directory: LinkedHashMap<MethodKey, CalleeSubscriptions>?,
) : AutoCloseable {
    fun visit(callee: MethodKey, writer: Publication, mode: ApMode, visit: (Subscription) -> Unit) {
        checkNotNull(directory) { "Joined caller inputs are closed" }[callee]?.visitJoinedCandidates(writer, mode, visit)
    }
    override fun close() {
        val owned = directory ?: return
        directory = null
        var failure: Throwable? = null
        for (inputs in owned.values) try { inputs.clear() } catch (error: Throwable) {
            if (failure == null) failure = error else if (failure !== error) failure.addSuppressed(error)
        }
        owned.clear()
        failure?.let { throw it }
    }
}

package org.opentaint.dataflow.bidi.engine

import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.CoroutineStart
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.NonCancellable
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.delay
import kotlinx.coroutines.launch
import kotlinx.coroutines.runBlocking
import kotlin.time.Duration

/** Joined AP/tree loops use the shared cancellation token. An independent
 * watchdog makes the original deadline visible inside those existing checks. */
internal fun <T> withJoinedDeadline(remaining: () -> Duration, onTimeout: () -> Unit, body: () -> T): T {
    val root = SupervisorJob()
    val watchdog = CoroutineScope(Dispatchers.Default + root).launch(start = CoroutineStart.UNDISPATCHED) {
        val left = remaining()
        if (left > Duration.ZERO) delay(left)
        onTimeout()
    }
    try { return body() }
    finally {
        root.cancel()
        runBlocking(NonCancellable) { watchdog.join() }
    }
}

