import org.opentaint.dataflow.bidi.interp.ResumeSite
import org.opentaint.dataflow.bidi.interp.ActionId
import org.opentaint.dataflow.bidi.store.CallerRef
import org.opentaint.dataflow.bidi.store.ConjunctionStore
import org.opentaint.dataflow.bidi.store.RequestMarkSet
import org.opentaint.ir.api.common.cfg.CommonInst
import java.util.Collections

internal typealias ResultSink = (PremiseKey, Facts) -> Unit

/** A run supplies its actual publication destination. A failure must propagate. */
fun interface PublicationSink {
    fun publish(method: MethodKey, batch: List<Publication>)
}

/** Evaluated literal parts remain separate even when no complete sink fired. */
class Triggers(fired: List<Pair<SinkRule, Layer>>, parts: List<Facts>) {
    val fired: List<Pair<SinkRule, Layer>> = Collections.unmodifiableList(ArrayList(fired))
    val parts: List<Facts> = Collections.unmodifiableList(ArrayList(parts))
    operator fun plus(other: Triggers): Triggers =
        Triggers((fired + other.fired).distinct(), parts + other.parts)

    companion object { val NONE = Triggers(emptyList(), emptyList()) }
}

/** Required local operations bind to the one actor's stores and run inputs. */
interface MethodLocalServices {
    val conjunctions: ConjunctionStore?
    fun addMarkRequest(premise: InitialAp, mark: TaintMark)
    fun addMarkRequests(premise: InitialAp, marks: RequestMarkSet) {
        marks.forEachMark { addMarkRequest(premise, it) }
    }
    val hasPendingRequests: Boolean get() = false
    /** A positive, bounded service opportunity; callbacks can admit another frontier. */
    fun flushRequests(quantum: Int): Boolean = true
    fun conjunction(edge: ConjunctiveEdge, premise: PremiseKey, facts: Facts, node: CommonInst,
                    sink: (PremiseKey, Facts) -> Unit)
    fun conjunctionAt(edge: ConjunctiveEdge, premise: PremiseKey, facts: Facts, node: CommonInst,
                      at: OperationInput, sink: (PremiseKey, Facts) -> Unit) = conjunction(edge, premise, facts, node, sink)
    fun sourcePredicate(source: SourceRuleOccurrence, premise: PremiseKey, facts: Facts, node: CommonInst,
                        statementEdge: Boolean, sink: (PremiseKey, Facts) -> Unit) {
        error("These local services do not implement rule predicates")
    }
    fun sourcePredicateAt(source: SourceRuleOccurrence, premise: PremiseKey, facts: Facts, node: CommonInst,
                          statementEdge: Boolean, at: OperationInput,
                          sink: (PremiseKey, Facts) -> Unit) = sourcePredicate(source, premise, facts, node, statementEdge, sink)
    fun sourcePredicateActionsAt(source: SourceRuleOccurrence, premise: PremiseKey, facts: Facts, node: CommonInst,
                                statementEdge: Boolean, at: OperationInput,
                                sink: (PremiseKey, Facts, ActionId?) -> Unit) =
        sourcePredicateAt(source, premise, facts, node, statementEdge, at) { pr, result -> sink(pr, result, null) }
    fun checkSinks(premise: PremiseKey, node: CommonInst, facts: Facts, sinks: List<SinkRule>): Triggers
    fun checkSinksAt(premise: PremiseKey, node: CommonInst, facts: Facts, sinks: List<SinkRule>, at: OperationInput): Triggers =
        checkSinks(premise, node, facts, sinks)
    fun fireSinkSeeds(node: CommonInst, emit: (Facts) -> Unit)
    fun fireTriggerSeeds(node: CommonInst, sink: SinkRule, emit: (Facts) -> Unit)
    fun freeze()
}

fun interface MethodLocalServicesFactory {
    fun create(core: BlockRunState): MethodLocalServices
}

/** Call processing and resume operations are supplied by the call engine. */
interface MethodCallServices : SummaryApplier {
    fun process(item: EdgeDelta)
    fun resumePoint(premise: PremiseKey, facts: Facts, site: ResumeSite, state: CallResumeState?) {
        error("These call services cannot resume a static point")
    }
    fun staticSupply(part: Subscription, result: StaticCallResult, member: Int, supply: RegionGroups) {
        error("These call services cannot join static supply")
    }
    fun freeze()
}

fun interface MethodCallServicesFactory {
    fun create(core: BlockRunState): MethodCallServices
}

package org.opentaint.dataflow.bidi.engine

import java.util.concurrent.atomic.AtomicLong

/** Optional aggregate census. Current counts cover subscription directories, not live graph bytes. */
class N2Statistics {
    private val acceptedDeltas = AtomicLong()
    private val cumulativeGroups = AtomicLong()
    private val zeroOnlyEntries = AtomicLong()
    private val indexPostings = AtomicLong()
    private val createdGroups = AtomicLong()
    private val createdZeroOnlyEntries = AtomicLong()
    private val createdIndexPostings = AtomicLong()
    private val queuedReplays = AtomicLong()
    private val peakQueuedReplays = AtomicLong()
    private val e6Bindings = AtomicLong()
    private val e6AvoidedBindings = AtomicLong()
    private val e6Combinations = AtomicLong()
    private val staticGroupCallOffers = AtomicLong()
    private val staticGroupDirectCalls = AtomicLong()
    private val staticGroupFallbackCallsAdmitted = AtomicLong()
    private val staticGroupScalarApplications = AtomicLong()
    private val staticGroupSuffixEntries = AtomicLong()
    private val staticGroupDirectSupplyLeaves = AtomicLong()
    private val staticGroupFallbackJoinLeaves = AtomicLong()

    private val staticSupplyOffers = AtomicLong()
    private val staticSupplyOfferedMembers = AtomicLong()
    private val staticSupplyFreshMembers = AtomicLong()
    private val staticSupplyRegionRows = AtomicLong()
    private val staticSupplyCommits = AtomicLong()

    private val selectedCallOffers = AtomicLong()
    private val persistedReplayInvocations = AtomicLong()
    private val persistedReplayCandidates = AtomicLong()
    private val persistedReplayMatches = AtomicLong()
    private val demandLookupInvocations = AtomicLong()
    private val demandLookupEmpty = AtomicLong()
    private val demandLookupEligible = AtomicLong()
    private val initialPackets = AtomicLong()
    private val offeredInitialKeys = AtomicLong()

    private val fullCleanupBlocks = AtomicLong()
    private val fullCleanupSuffixEntries = AtomicLong()
    private val fullCleanupSelectedSteps = AtomicLong()
    private val fullCleanupInputs = AtomicLong()
    private val fullCleanupSingletonFlowInputs = AtomicLong()
    private val fullCleanupSingletonFlowSteps = AtomicLong()
    private val fullCleanupFallbacks = AtomicLong()
    private val fullCleanupRequestMembers = AtomicLong()

    data class Snapshot(
        val acceptedDeltas: Long,
        val cumulativeGroups: Long,
        val zeroOnlyEntries: Long,
        val indexPostings: Long,
        val createdGroups: Long,
        val createdZeroOnlyEntries: Long,
        val createdIndexPostings: Long,
        val queuedReplays: Long,
        val peakQueuedReplays: Long,
        val e6Bindings: Long,
        val e6AvoidedBindings: Long,
        val e6Combinations: Long,
        val staticGroupCallOffers: Long = 0,
        val staticGroupDirectCalls: Long = 0,
        val staticGroupFallbackCallsAdmitted: Long = 0,
        val staticGroupScalarApplications: Long = 0,
        val staticGroupSuffixEntries: Long = 0,
        val staticGroupDirectSupplyLeaves: Long = 0,
        val staticGroupFallbackJoinLeaves: Long = 0,
        val fullCleanupBlocks: Long = 0,
        val fullCleanupSuffixEntries: Long = 0,
        val fullCleanupSelectedSteps: Long = 0,
        val fullCleanupInputs: Long = 0,
        /** Completed singleton same-base FLOW blocks have one scalar call at each raw suffix step. */
        val fullCleanupSingletonFlowInputs: Long = 0,
        val fullCleanupSingletonFlowSteps: Long = 0,
        val fullCleanupFallbacks: Long = 0,
        val fullCleanupRequestMembers: Long = 0,
        val staticSupplyOffers: Long = 0,
        val staticSupplyOfferedMembers: Long = 0,
        val staticSupplyFreshMembers: Long = 0,
        val staticSupplyRegionRows: Long = 0,
        val staticSupplyCommits: Long = 0,
        val selectedCallOffers: Long = 0,
        val persistedReplayInvocations: Long = 0,
        val persistedReplayCandidates: Long = 0,
        val persistedReplayMatches: Long = 0,
        val demandLookupInvocations: Long = 0,
        val demandLookupEmpty: Long = 0,
        val demandLookupEligible: Long = 0,
        val initialPackets: Long = 0,
        val offeredInitialKeys: Long = 0,
    )

    internal fun selectedCallOffered() { selectedCallOffers.incrementAndGet() }
    internal fun persistedReplayStarted() { persistedReplayInvocations.incrementAndGet() }
    internal fun persistedReplayCandidate() { persistedReplayCandidates.incrementAndGet() }
    internal fun persistedReplayMatched() { persistedReplayMatches.incrementAndGet() }
    internal fun demandLookupCompleted(eligible: Boolean) {
        demandLookupInvocations.incrementAndGet()
        if (eligible) demandLookupEligible.incrementAndGet() else demandLookupEmpty.incrementAndGet()
    }
    internal fun initialPacketOffered(keys: Int) {
        require(keys > 0)
        initialPackets.incrementAndGet()
        offeredInitialKeys.addAndGet(keys.toLong())
    }

    internal fun accepted(newGroup: Boolean = false, zeroOnly: Boolean = false) {
        acceptedDeltas.incrementAndGet()
        if (newGroup) {
            cumulativeGroups.incrementAndGet()
            createdGroups.incrementAndGet()
        }
        if (zeroOnly) {
            zeroOnlyEntries.incrementAndGet()
            createdZeroOnlyEntries.incrementAndGet()
        }
    }

    internal fun posted() {
        indexPostings.incrementAndGet()
        createdIndexPostings.incrementAndGet()
    }

    internal fun releaseDirectory(groups: Int, zeroEntries: Int, postings: Long) {
        cumulativeGroups.addAndGet(-groups.toLong())
        zeroOnlyEntries.addAndGet(-zeroEntries.toLong())
        indexPostings.addAndGet(-postings)
    }

    internal fun replayQueued() {
        // Pending callbacks include an executing Inline callback, not only a physical queue.
        val count = queuedReplays.incrementAndGet()
        peakQueuedReplays.accumulateAndGet(count, ::maxOf)
    }

    internal fun replayFinished() { queuedReplays.decrementAndGet() }

    /** E6 totals are cumulative insertions and avoided duplicate member bindings. */
    fun recordE6(newBindings: Int, avoidedBindings: Int, newCombinations: Int) {
        require(newBindings >= 0 && avoidedBindings >= 0 && newCombinations >= 0)
        e6Bindings.addAndGet(newBindings.toLong())
        e6AvoidedBindings.addAndGet(avoidedBindings.toLong())
        e6Combinations.addAndGet(newCombinations.toLong())
    }

    /** Scalar offers include repeats rejected by a pending fallback key. */
    internal fun staticGroupCallOffered() { staticGroupCallOffers.incrementAndGet() }
    internal fun staticGroupCallDirect() { staticGroupDirectCalls.incrementAndGet() }
    internal fun staticGroupCallFallbackAdmitted() { staticGroupFallbackCallsAdmitted.incrementAndGet() }
    /** Count matched scalar reducer entries and nonempty suffix batches separately. */
    internal fun staticGroupScalarApplied() { staticGroupScalarApplications.incrementAndGet() }
    internal fun staticGroupSuffixEntered() { staticGroupSuffixEntries.incrementAndGet() }
    internal fun staticGroupSupplyDirect() { staticGroupDirectSupplyLeaves.incrementAndGet() }
    internal fun staticGroupJoinFallback() { staticGroupFallbackJoinLeaves.incrementAndGet() }

    /** Canonical temporary FULL supplies only. Rows and fresh members are summed per batch. */
    internal fun staticSupplyOffered(members: Int, fresh: Int, newRegion: Boolean) {
        staticSupplyOffers.incrementAndGet()
        staticSupplyOfferedMembers.addAndGet(members.toLong())
        staticSupplyFreshMembers.addAndGet(fresh.toLong())
        if (newRegion) staticSupplyRegionRows.incrementAndGet()
    }
    internal fun staticSupplyCommitted() { staticSupplyCommits.incrementAndGet() }

    internal fun fullCleanupBlock(suffix: Boolean, steps: Int, inputs: Int) {
        fullCleanupBlocks.incrementAndGet()
        if (suffix) fullCleanupSuffixEntries.incrementAndGet()
        fullCleanupSelectedSteps.addAndGet(steps.toLong() * inputs)
        fullCleanupInputs.addAndGet(inputs.toLong())
    }
    /** Invoke only after the singleton FLOW bulk operation returns successfully. */
    internal fun fullCleanupSingletonFlow(steps: Int) {
        fullCleanupSingletonFlowInputs.incrementAndGet()
        fullCleanupSingletonFlowSteps.addAndGet(steps.toLong())
    }
    internal fun fullCleanupFallback() { fullCleanupFallbacks.incrementAndGet() }
    internal fun fullCleanupRequested(size: Int) { fullCleanupRequestMembers.addAndGet(size.toLong()) }

    /** Read after joining for a consistent aggregate; reads during work are a bounded live census. */
    fun snapshot(): Snapshot = Snapshot(acceptedDeltas.get(), cumulativeGroups.get(), zeroOnlyEntries.get(),
        indexPostings.get(), createdGroups.get(), createdZeroOnlyEntries.get(), createdIndexPostings.get(),
        queuedReplays.get(), peakQueuedReplays.get(), e6Bindings.get(),
        e6AvoidedBindings.get(), e6Combinations.get(), staticGroupCallOffers.get(), staticGroupDirectCalls.get(),
        staticGroupFallbackCallsAdmitted.get(), staticGroupScalarApplications.get(), staticGroupSuffixEntries.get(),
        staticGroupDirectSupplyLeaves.get(), staticGroupFallbackJoinLeaves.get(), fullCleanupBlocks.get(),
        fullCleanupSuffixEntries.get(), fullCleanupSelectedSteps.get(), fullCleanupInputs.get(),
        fullCleanupSingletonFlowInputs.get(), fullCleanupSingletonFlowSteps.get(), fullCleanupFallbacks.get(), fullCleanupRequestMembers.get(), staticSupplyOffers.get(),
        staticSupplyOfferedMembers.get(), staticSupplyFreshMembers.get(), staticSupplyRegionRows.get(),
        staticSupplyCommits.get(), selectedCallOffers.get(), persistedReplayInvocations.get(),
        persistedReplayCandidates.get(), persistedReplayMatches.get(), demandLookupInvocations.get(),
        demandLookupEmpty.get(), demandLookupEligible.get(), initialPackets.get(), offeredInitialKeys.get())
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.ApManager
import org.opentaint.ir.api.common.cfg.CommonInst

/** An actor either evaluates one original scalar item or one exact diagonal
 * mask. A fallback consumes that mask incrementally and retains the remainder. */
sealed interface PendingWork {
    class Scalar(val delta: EdgeDelta) : PendingWork
    class MarkedBatch(val node: CommonInst, val batch: NeutralRelationBatch) : PendingWork
}

/** Pending ordinary cohorts. ZERO retains its separate priority phase.
 * There is one input tree per
 * cohort and an exact mark mask, with no per-mark scalar input archive. */
internal class NeutralBatchWorklist(private val m: ApManager) {
    private data class Key(val node: CommonInst, val geometry: Any)
    data class Admission(val work: PendingWork.MarkedBatch, val newlyQueued: Boolean)
    private val pending = HashMap<Key, PendingWork.MarkedBatch>()

    fun offer(delta: EdgeDelta): Admission? {
        m.cancellation.checkpoint()
        val batch = NeutralRelationBatch.from(m, delta.premise, delta.facts) ?: return null
        return retain(delta.node, batch)
    }

    /** Retain an unfinished quantum or scalar fallback without losing marks. */
    fun retain(node: CommonInst, batch: NeutralRelationBatch): Admission {
        m.cancellation.checkpoint()
        check(!batch.isEmpty) { "An empty mask is not pending work" }
        val key = Key(node, batch.geometryKey)
        val previous = pending[key]
        if (previous != null) {
            check(previous.batch.mergeIfSameGeometry(batch)) { "A cohort key must identify one complete geometry" }
            return Admission(previous, newlyQueued = false)
        }
        val work = PendingWork.MarkedBatch(node, batch)
        pending[key] = work
        return Admission(work, newlyQueued = true)
    }

    fun removed(work: PendingWork.MarkedBatch) {
        val key = Key(work.node, work.batch.geometryKey)
        if (pending[key] === work) pending.remove(key)
    }

    fun clear() = pending.clear()
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.interp.StatementSummary
import java.util.ArrayDeque
import org.opentaint.dataflow.util.Cancellation

/** One diagonal geometry and an exact mask. No scalar per-mark input archive is kept. */
class NeutralRelationBatch private constructor(
    private val m: ApManager,
    val initialShape: InitialAp,
    val template: TaintTree,
    marks: MarkSet,
    sharedGeometryKey: Any? = null,
) {
    var marks: MarkSet = marks; private set
    val size: Int get() = marks.size
    val markCount: Int get() = size
    val geometryKey: Any = sharedGeometryKey ?: GeometryKey(initialShape, template.groupKey,
        ShapeKey(template.root, geometryHash(m, template.root), m.cancellation),
        template.nonSubsumable?.let { ShapeKey(it, geometryHash(m, it), m.cancellation) })
    val isEmpty: Boolean get() = marks.isEmpty

    fun mergeIfSameGeometry(other: NeutralRelationBatch): Boolean {
        m.cancellation.checkpoint()
        if (m !== other.m || geometryKey != other.geometryKey) return false
        marks = m.intern(marks + other.marks)
        return true
    }

    private fun initial(mark: TaintMark): InitialAp = m.initial(initialShape.base, initialShape.path,
        initialShape.tail, initialShape.exclusion, MarkSlot.Concrete(mark))

    /** Decode only at an existing scalar boundary. Marks stay correlated with their own initials. */
    private fun decode(mark: TaintMark): TaintTree {
        val one = m.markSetOf(mark)
        fun root(n: TaintNode): TaintNode = checkNotNull(m.taintAlg.mapLeaves(n, m.cancellation) {
            m.taintLeaves(if (it.exact.isEmpty) MarkSet.EMPTY else one, if (it.any.isEmpty) MarkSet.EMPTY else one)
        })
        return m.taintTree(template.base, template.layer, root(template.root), template.exclusion, template.anyTail,
            template.nonSubsumable?.let(::root))
    }

    fun decode(): Sequence<Pair<InitialAp, TaintTree>> = sequence {
        for (id in marks.ids) {
            m.cancellation.checkpoint()
            val mark = TaintMark(id)
            yield(initial(mark) to decode(mark))
        }
    }

    /** A queue can retain the remaining exact mask when it takes the scalar fallback. */
    fun removeFirst(): Pair<InitialAp, TaintTree> {
        check(!marks.isEmpty) { "An empty batch has no scalar member" }
        val mark = TaintMark(marks.ids[0])
        marks = m.intern(marks - m.markSetOf(mark))
        return initial(mark) to decode(mark)
    }

    /** Limit one actor turn without expanding its pending mark memberships. */
    fun take(max: Int): NeutralRelationBatch {
        require(max > 0) { "A batch slice needs a positive budget" }
        check(!isEmpty) { "An empty batch has no prefix" }
        val selected = m.intern(MarkSet(marks.ids.take(max).toIntArray()))
        marks = m.intern(marks - selected)
        return NeutralRelationBatch(m, initialShape, template, selected, geometryKey)
    }

    private fun packed(): TaintTree {
        val mask = marks
        fun root(n: TaintNode): TaintNode = checkNotNull(m.taintAlg.mapLeaves(n, m.cancellation) {
            m.taintLeaves(if (it.exact.isEmpty) MarkSet.EMPTY else mask, if (it.any.isEmpty) MarkSet.EMPTY else mask)
        })
        return m.taintTree(template.base, template.layer, root(template.root), template.exclusion, template.anyTail,
            template.nonSubsumable?.let(::root))
    }

    /** Calls, endpoints, observers and rule stages are certified by the caller before this boundary.
     * A false result makes no callback and leaves the batch available for the scalar path. */
    fun applyPacked(ops: ApOps, summary: StatementSummary, mode: ApMode,
                    emit: (InitialAp, TaintTree, MarkSet) -> Unit,
                    untouched: (InitialAp, TaintTree, MarkSet) -> Unit = emit): Boolean {
        if (!RuntimeDataDomain.initial(initialShape) || !RuntimeDataDomain.base(template.base)) return true
        if (ops.manager !== m || !mode.run1 || mode.markMode != MarkMode.FULL ||
            isEmpty || !certifies(summary)) return false
        if (template.base !in summary.touched) {
            untouched(initialShape, packed(), marks)
            return true
        }
        val input = summary.typeFilters[template.base]?.let { ops.filter(packed(), it) } ?: if (
            summary.typeFilters.containsKey(template.base)) null else packed()
        if (input == null) return true
        // No mark-dependent primitive is admitted. The representative initial is
        // used only for the unchanged nonstatic spatial AP contract.
        val representative = initial(TaintMark(marks.ids[0]))
        val output = object : ApOut {
            override fun markRequest(mark: TaintMark): Unit = error("A certified neutral form cannot request a mark")
            override fun result(f: Facts) {
                if (!RuntimeDataDomain.base(f.base)) return
                val filtered = summary.resultFilters[f.base]?.let { ops.filter(f, it) } ?: if (
                    summary.resultFilters.containsKey(f.base)) null else f
                if (filtered == null) return
                ops.limit(filtered, mode.fieldLimit, object : ApOut {
                    override fun markRequest(mark: TaintMark): Unit = error("Field limits cannot request a mark")
                    override fun result(bounded: Facts) {
                        if (!RuntimeDataDomain.base(bounded.base)) return
                        check(bounded is TaintTree) { "Neutral transport preserves TAINT" }
                        emit(initialShape, bounded, marks)
                    }
                })
            }
        }
        for (edge in summary.edgesOf(input.base)) {
            m.cancellation.checkpoint()
            if (!RuntimeDataDomain.producer(edge)) continue
            ops.applyEdge(input, representative, edge.edge, statementEdge = true, mode = mode, out = output, may = edge.may)
        }
        return true
    }

    /** Existing scalar boundaries decode only after the form has been classified. */
    fun apply(ops: ApOps, summary: StatementSummary, mode: ApMode,
              emit: (PremiseKey, Facts) -> Unit,
              untouched: (PremiseKey, Facts) -> Unit = emit): Boolean =
        applyPacked(ops, summary, mode,
            { _, facts, mask -> emitDecoded(facts, emit, mask) },
            { _, facts, mask -> emitDecoded(facts, untouched, mask) })

    private fun emitDecoded(packed: Facts, emit: (PremiseKey, Facts) -> Unit, selected: MarkSet = marks) {
        check(packed is TaintTree) { "A nonstatic STAR-to-STAR transfer preserves TAINT" }
        decodePacked(m, initialShape, packed, selected, emit)
    }

    private data class GeometryKey(val initial: InitialAp, val header: GroupKey,
                                   val ordinary: ShapeKey, val protection: ShapeKey?)
    private class ShapeKey(val root: TaintNode, val hash: Long, val cancellation: Cancellation) {
        override fun hashCode(): Int = (hash xor (hash ushr 32)).toInt()
        override fun equals(other: Any?): Boolean = this === other || other is ShapeKey &&
            hash == other.hash && sameGeometry(root, other.root, cancellation)
    }

    companion object {
        private class HashFrame(val node: TaintNode, var next: Int = 0)
        private fun geometryHash(m: ApManager, root: TaintNode): Long {
            val memo = java.util.IdentityHashMap<TaintNode, Long>()
            val stack = ArrayDeque<HashFrame>()
            stack.addLast(HashFrame(root))
            while (stack.isNotEmpty()) {
                m.cancellation.checkpoint()
                val frame = stack.peekLast()
                val kids = frame.node.childData
                if (kids != null && frame.next < kids.size) {
                    val child = kids[frame.next++]
                    if (!memo.containsKey(child)) stack.addLast(HashFrame(child))
                    continue
                }
                var hash = (if (frame.node.leaf.exact.isEmpty) 0L else 1L) +
                    (if (frame.node.leaf.any.isEmpty) 0L else 2L)
                frame.node.accessorData?.forEachIndexed { i, accessor ->
                    hash += (memo.getValue(kids!![i]) * 31 + accessor) shl 5
                }
                memo[frame.node] = hash
                stack.removeLast()
            }
            return memo.getValue(root)
        }

        /** Scalar fallback, invoked only after packet/form admission has been classified. */
        fun decodePacked(m: ApManager, initialShape: InitialAp, packed: TaintTree, marks: MarkSet,
                         emit: (PremiseKey, Facts) -> Unit) {
            if (!RuntimeDataDomain.initial(initialShape) || !RuntimeDataDomain.base(packed.base)) return
            check(initialShape.manager === m && initialShape.isFlow)
            for (id in marks.ids) {
                m.cancellation.checkpoint()
                val mark = TaintMark(id)
                val one = m.markSetOf(mark)
                val root = m.taintAlg.mapLeaves(packed.root, m.cancellation) {
                    m.taintLeaves(it.exact intersect one, it.any intersect one)
                } ?: continue
                val protected = packed.nonSubsumable?.let { n -> m.taintAlg.mapLeaves(n, m.cancellation) {
                    m.taintLeaves(it.exact intersect one, it.any intersect one)
                } }
                val initial = m.initial(initialShape.base, initialShape.path, initialShape.tail,
                    initialShape.exclusion, MarkSlot.Concrete(mark))
                emit(initial, m.taintTree(packed.base, packed.layer, root, packed.exclusion, packed.anyTail, protected))
            }
        }

        /** A stored mask becomes one packed work value; no per-mark scalar input is built. */
        fun fromDiagonal(m: ApManager, delta: DiagonalDelta): NeutralRelationBatch? {
            if (!RuntimeDataDomain.initial(delta.initialShape) || !RuntimeDataDomain.base(delta.base) ||
                delta.initialShape.manager !== m || delta.base == STATIC ||
                delta.base is AccessPathBase.CleanerTemporary || delta.marks.isEmpty ||
                delta.marks.ids.any { m.marks.isGroup(TaintMark(it)) || it == TaintMark.ZERO.id }) return null
            val leaf = m.taintAlg.leafNode(m.taintLeaves(MarkSet.EMPTY, delta.marks))
            val root = m.taintAlg.graft(delta.geometry, { !it.isEmpty }, leaf, m.cancellation) ?: return null
            val packed = m.taintTree(delta.base, delta.layer, root, delta.exclusion, anyTail = delta.tail,
                nonSubsumable = if (delta.protected) root else null)
            return NeutralRelationBatch(m, delta.initialShape, packed, delta.marks)
        }

        /** Certify the packet cell before any scalar result decoder is called. */
        fun toDiagonal(m: ApManager, initialShape: InitialAp, packed: TaintTree, marks: MarkSet): DiagonalDelta? {
            if (!RuntimeDataDomain.initial(initialShape) || !RuntimeDataDomain.base(packed.base) ||
                initialShape.manager !== m || initialShape.mark != MarkSlot.STAR || (initialShape.tail != Tail.STAR && initialShape.tail != Tail.ANY) || packed.base == STATIC ||
                packed.base is AccessPathBase.CleanerTemporary || (packed.anyTail != Tail.STAR && packed.anyTail != Tail.ANY) || marks.isEmpty ||
                marks.ids.any { m.marks.isGroup(TaintMark(it)) || it == TaintMark.ZERO.id }) return null
            var uniform = true
            m.taintAlg.forEachLeaf(packed.root, EMPTY_PATH, m.cancellation) { _, leaf ->
                if (!leaf.exact.isEmpty || leaf.any != marks) uniform = false
            }
            if (!uniform) return null
            val protected = packed.nonSubsumable
            if (protected != null && protected !== packed.root &&
                m.taintAlg.minusNode(packed.root, protected, m.cancellation) != null) return null
            val geometry = FlowAlgebra.graft(packed.root, { !it.any.isEmpty }, FlowAlgebra.LEAF_NODE, m.cancellation)
                ?: return null
            return DiagonalDelta(initialShape, packed.base, packed.layer, geometry, m.intern(marks), protected != null,
                packed.anyTail, packed.exclusion)
        }

        fun from(m: ApManager, premise: PremiseKey, facts: Facts): NeutralRelationBatch? {
            if (!RuntimeDataDomain.packet(premise, facts)) return null
            val initial = premise as? InitialAp ?: return null
            val mark = (initial.mark as? MarkSlot.Concrete)?.mark ?: return null
            val f = facts as? TaintTree ?: return null
            if (initial.manager !== m || mark == TaintMark.ZERO || m.marks.isGroup(mark) || initial.tail != Tail.STAR ||
                initial.exclusion != ExclusionSet.Empty || f.exclusion != ExclusionSet.Empty || f.base == STATIC ||
                f.base is AccessPathBase.CleanerTemporary) return null
            val all = m.taintAlg.foldAll(f.root, m.cancellation)
            val one = m.markSetOf(mark)
            if (!all.exact.isSubsetOf(one) || !all.any.isSubsetOf(one)) return null
            val shape = m.initial(initial.base, initial.path, initial.tail, initial.exclusion, MarkSlot.STAR)
            return NeutralRelationBatch(m, shape, f, one)
        }

        /** Only transport geometry is shared. Mark filters and every source/static hook stay scalar. */
        fun certifies(summary: StatementSummary): Boolean = summary.sources.isEmpty() &&
            summary.conjunctions.isEmpty() && summary.staticOperations.isEmpty() &&
            summary.typeFilters.values.all { it.markPolicy == null } &&
            summary.resultFilters.values.all { it.markPolicy == null } && summary.edges.all { me ->
                val e = me.edge
                !me.isSource && !me.conjunctive && me.actionId == null &&
                    e.from.base != STATIC && e.to.base != STATIC &&
                    e.from.base != AccessPathBase.Zero && e.to.base != AccessPathBase.Zero &&
                    (e.from.mark as? MarkSlot.Star)?.excluded?.isEmpty == true &&
                    (e.to.mark as? MarkSlot.Star)?.excluded?.isEmpty == true
            }

        /** Marks do not enter this comparison. The caller has already checked diagonality. */
        private fun sameGeometry(a: TaintNode?, b: TaintNode?, cancellation: Cancellation): Boolean {
            if (a === b) return true
            if (a == null || b == null) return false
            val pending = ArrayDeque<Pair<TaintNode, TaintNode>>()
            val seen = HashSet<NodePair<TaintLeaves>>()
            pending.addLast(a to b)
            while (pending.isNotEmpty()) {
                cancellation.checkpoint()
                val (x, y) = pending.removeLast()
                if (x === y) continue
                if (x.leaf.exact.isEmpty != y.leaf.exact.isEmpty || x.leaf.any.isEmpty != y.leaf.any.isEmpty ||
                    !x.accessorData.contentEquals(y.accessorData)) return false
                if (!seen.add(NodePair(x, y))) continue
                x.childData?.indices?.forEach { pending.addLast(x.childData[it] to y.childData!![it]) }
            }
            return true
        }
    }
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.interp.ResumeSite
import org.opentaint.dataflow.bidi.store.*

/** One actor-owned condition cache facade. Only an accepted current leaf may
 * activate [restoreOnce]. It never schedules facts, actions, or initials. */
class NormalRuleContributors(
    private val manager: ApManager,
    previous: NormalRuleContributorView,
    method: MethodKey,
    scope: BlockScope,
    mode: ApMode,
) {
    private val enabled = mode.direction == Direction.FORWARD && mode.markMode == MarkMode.FULL
    private val owner = NormalRuleContributorOwner(method, scope, mode.markMode, mode.direction)
    private var previous: NormalRuleContributorView? = if (enabled) previous else null
    private var restored: MutableSet<NormalRuleContributorKey>? = if (enabled) HashSet() else null
    private var temporary: NormalRuleContributorStore? = if (enabled) NormalRuleContributorStore(manager) else null
    private var frozen = false
    var capturedRows: Long = 0; private set
    var capturedUpdates: Long = 0; private set
    var restoredRows: Long = 0; private set

    /** The callback inserts old leaves into the ordinary join and collects ready
     * complete bindings. Its caller drains those bindings before the new input. */
    fun restoreOnce(rule: NormalRuleDescriptor, site: ResumeSite,
                    replay: (NormalRuleContributorRow) -> Unit): Boolean {
        check(!frozen) { "Condition contributors were frozen" }
        if (!enabled) return false
        manager.cancellation.checkpoint()
        val key = key(rule, site)
        if (!checkNotNull(restored).add(key)) return false
        for (row in checkNotNull(previous).rows(key)) {
            manager.cancellation.checkpoint()
            replay(row)
            restoredRows++
        }
        return true
    }

    fun keep(rule: NormalRuleDescriptor, site: ResumeSite, leaf: Int, input: ConjunctionStore.Input): Boolean {
        check(!frozen) { "Condition contributors were frozen" }
        if (!enabled || input.layer != Layer.NORMAL || input.facts?.layer != Layer.NORMAL) return false
        val temporary = checkNotNull(temporary)
        val count = temporary.retainedRows
        val fresh = temporary.publish(listOf(NormalRuleContributorRow(key(rule, site), leaf, input)))
        capturedRows += temporary.retainedRows - count
        if (fresh && temporary.retainedRows == count) capturedUpdates++
        return fresh
    }

    /** Snapshot cleanup has no cancellation point; a failed run exports nothing
     * at its barrier, but still releases reader and deduplication references. */
    fun freezeRows(): List<NormalRuleContributorRow> {
        check(!frozen) { "Condition contributors were already frozen" }
        return try { temporary?.snapshot()?.allRows().orEmpty() }
        finally {
            previous = null
            restored?.clear(); restored = null
            temporary = null
            frozen = true
        }
    }

    private fun key(rule: NormalRuleDescriptor, site: ResumeSite) =
        NormalRuleContributorKey(owner, rule, stableSite(rule, site))

    companion object {
        fun stableSite(rule: NormalRuleDescriptor, site: ResumeSite): NormalRuleSite = NormalRuleSite.of(rule, site)
    }
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.store.BlockScope
import org.opentaint.dataflow.bidi.store.OwnedScope
import java.util.Collections

/** A run reads a fixed view. Only a complete driver barrier builds its successor. */
interface NormalTargetView {
    fun contains(method: MethodKey, premise: PremiseKey, id: ReportId): Boolean
    fun candidates(method: MethodKey, part: Subscription, mode: ApMode): List<Pair<TargetSummary, Int>>
    fun contains(method: MethodKey, scope: BlockScope?, premise: PremiseKey, id: ReportId): Boolean =
        scope == null && contains(method, premise, id)
    fun candidates(method: MethodKey, scope: BlockScope?, original: PremiseKey, actual: Facts,
                   mode: ApMode): List<Pair<TargetSummary, Int>> = emptyList()
    /** Complete snapshot, including internal scopes for future local replay. */
    fun rows(): Sequence<OwnedNormalTarget>
    /** Only public method ZERO rows participate in root report accounting. */
    fun zeroRows(): Sequence<OwnedNormalTarget> = rows().filter { it.scope == null && it.premise.isZero }

    companion object {
        val EMPTY = object : NormalTargetView {
            override fun contains(method: MethodKey, premise: PremiseKey, id: ReportId) = false
            override fun candidates(method: MethodKey, part: Subscription, mode: ApMode) = emptyList<Pair<TargetSummary, Int>>()
            override fun rows() = emptySequence<OwnedNormalTarget>()
        }
    }
}

/** Shares the existing premise index. Target identities do not change AP equality. */
class NormalTargetStore(ap: ApManager, records: Sequence<OwnedNormalTarget>) : NormalTargetView {
    private val members: Set<OwnedNormalTarget>
    private val byMethod: Map<MethodKey, PublicationIndex>
    private val byScope: Map<OwnedScope, PublicationIndex>

    init {
        val owned = LinkedHashSet<OwnedNormalTarget>()
        val indexes = LinkedHashMap<MethodKey, PublicationIndex>()
        val scoped = LinkedHashMap<OwnedScope, PublicationIndex>()
        for (record in records) {
            ap.cancellation.checkpoint()
            if (!RuntimeDataDomain.premise(record.premise) || !owned.add(record)) continue
            val index = if (record.scope == null) indexes.getOrPut(record.method) { PublicationIndex(ap, ApOps(ap)) }
                else scoped.getOrPut(OwnedScope(record.method, record.scope)) { PublicationIndex(ap, ApOps(ap)) }
            index.addTargets(listOf(TargetSummary(record.premise, Target.NormalTarget(record.id))))
        }
        members = Collections.unmodifiableSet(owned)
        byMethod = Collections.unmodifiableMap(indexes)
        byScope = Collections.unmodifiableMap(scoped)
    }

    override fun contains(method: MethodKey, premise: PremiseKey, id: ReportId): Boolean =
        OwnedNormalTarget(method, premise, id) in members
    override fun candidates(method: MethodKey, part: Subscription, mode: ApMode): List<Pair<TargetSummary, Int>> =
        byMethod[method]?.targetCandidates(part, mode).orEmpty()
    override fun contains(method: MethodKey, scope: BlockScope?, premise: PremiseKey, id: ReportId): Boolean =
        OwnedNormalTarget(method, premise, id, scope) in members
    override fun candidates(method: MethodKey, scope: BlockScope?, original: PremiseKey, actual: Facts,
                            mode: ApMode): List<Pair<TargetSummary, Int>> =
        (if (scope == null) byMethod[method] else byScope[OwnedScope(method, scope)])
            ?.targetCandidates(original, actual, mode).orEmpty()
    override fun rows(): Sequence<OwnedNormalTarget> = members.asSequence()
}

package org.opentaint.dataflow.bidi.engine

import it.unimi.dsi.fastutil.ints.IntOpenHashSet
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.store.BlockScope
import org.opentaint.dataflow.bidi.store.CallerRef
import org.opentaint.dataflow.bidi.store.OwnedScope
import org.opentaint.dataflow.bidi.store.StaticWriteKeyInterner

/** Only an existing live input link can bind a primitive writer. */
internal sealed interface OwnedWriterInputKey {
    data class Local(val link: LocalLink) : OwnedWriterInputKey
    data class Call(val ref: CallerRef, val zeroOnly: Boolean) : OwnedWriterInputKey
}

internal class OwnedWriterInput private constructor(
    val parent: OwnedScope,
    val original: InitialAp,
    val actual: Facts,
    val key: OwnedWriterInputKey,
    val zeroOnly: Boolean,
) {
    companion object {
        fun local(method: MethodKey, link: LocalLink, actual: Facts): OwnedWriterInput =
            OwnedWriterInput(OwnedScope(method, link.parent),
                checkNotNull(link.original as? InitialAp) { "Run-1 local originals are singleton" }, actual,
                OwnedWriterInputKey.Local(link), zeroOnly = false)

        fun call(part: Subscription): OwnedWriterInput =
            OwnedWriterInput(OwnedScope(part.ref.caller, part.ref.scope),
                checkNotNull(part.ref.premise as? InitialAp) { "Run-1 caller originals are singleton" }, part.added,
                OwnedWriterInputKey.Call(part.ref, part.zeroOnly), part.zeroOnly)
    }
}

/** Joined phase A. Bind local inputs first, then real method callers at the root.
 *
 * It borrows existing current inputs after all runners join. No second standing input store,
 * synthetic method, alias application, static composition or new request authority is added.
 */
internal class OwnedJoinedStaticWriterBinding(
    private val ops: ApOps,
    private val mode: ApMode,
    private val keys: StaticWriteKeyInterner,
    private val borrow: (OwnedScope, Publication, (OwnedWriterInput) -> Unit) -> Unit,
    private val onBound: (OwnedScope, InitialAp, Pattern) -> Unit,
    private val checkpoint: () -> Unit,
) {
    private data class Writer(val owner: OwnedScope, val id: Int)
    private data class InputKey(val key: OwnedWriterInputKey, val group: GroupKey)
    private val admitted = HashMap<OwnedScope, IntOpenHashSet>()
    private val pending = ArrayDeque<Writer>()
    private var offers = 0L
    private var processed = 0L
    private var candidates = 0L
    private var matchedInputs = 0L
    private var duplicateInputs = 0L
    private var outputs = 0L

    init { check(mode.run1) }

    fun offer(owner: OwnedScope, id: Int) {
        checkpoint()
        val row = keys.row(id)
        if (!RuntimeDataDomain.initial(row.original) || !RuntimeDataDomain.base(row.result.fact.base)) return
        check(row.result.fact.base == STATIC)
        check(row.original.base != STATIC) { "Static originals enter the frozen bridge graph, never writer binding" }
        offers++
        if (admitted.getOrPut(owner, ::IntOpenHashSet).add(id)) pending += Writer(owner, id)
    }

    fun complete(): JoinedStaticWriterBinding.Statistics {
        val ap = ops.manager
        while (pending.isNotEmpty()) {
            checkpoint()
            val writer = pending.removeFirst()
            val row = keys.row(writer.id)
            val conclusion = ap.factsOf(row.result.fact, row.result.exclusion, Layer.DEMAND)
            val publication = Publication(row.original, conclusion)
            val visited = HashSet<InputKey>()
            processed++
            borrow(writer.owner, publication) { input ->
                checkpoint()
                if (!RuntimeDataDomain.packet(input.original, input.actual)) return@borrow
                check((input.actual is FlowTree) == input.original.isFlow)
                candidates++
                if (!visited.add(InputKey(input.key, input.actual.groupKey))) {
                    duplicateInputs++
                    return@borrow
                }
                // Do not turn an arbitrary reached ZERO packet into a new source authority.
                if (row.original.isZero && (!input.original.isZero || input.actual !is Reach)) return@borrow
                val packets = if (input.zeroOnly) listOfNotNull(input.actual.takeIf { row.original.isZero })
                    else ap.canonicalPackets(input.actual).mapNotNull {
                        ops.matchSummary(it, row.original, mode, nativeRecordRead = false,
                            role = SummaryMatchRole.CURRENT)
                    }
                if (packets.isEmpty()) return@borrow
                matchedInputs++
                val out = object : ApOut {
                    override fun result(f: Facts) {
                        checkpoint()
                        check(f.base == STATIC)
                        // This is the existing static-result lane. Keep raw mx until AP
                        // application ends; no configured call suffix or aliases execute.
                        ops.run1Cover(f.withLayer(Layer.DEMAND)) { covered ->
                            ops.limit(covered, mode.fieldLimit, object : ApOut {
                                override fun result(f: Facts) {
                                    ops.run1Cover(f.withLayer(Layer.DEMAND)) { bounded ->
                                        for (piece in ops.leaves(bounded)) {
                                            checkpoint()
                                            outputs++
                                            onBound(input.parent, input.original, piece)
                                            if (input.original.base != STATIC)
                                                offer(input.parent, keys.intern(input.original, piece))
                                        }
                                    }
                                }
                                override fun markRequest(mark: TaintMark) =
                                    error("A joined field cut cannot create a mark request")
                            })
                        }
                    }
                    // Live execution already owns the exclusion's request.
                    override fun markRequest(mark: TaintMark) = Unit
                }
                if (input.zeroOnly) out.result(conclusion)
                else for (actual in packets) ops.applySummary(actual, row.original, conclusion, mode, out, original = input.original)
            }
        }
        checkpoint()
        return JoinedStaticWriterBinding.Statistics(offers, admitted.values.sumOf { it.size.toLong() }, processed,
            candidates, duplicateInputs, matchedInputs, outputs)
    }
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.store.Record

/** Read the previous-run store on every original offer, without live input history. */
internal fun replayPersistedSummaries(
    config: RunConfig,
    ops: ApOps,
    part: Subscription,
    applier: SummaryApplier,
    statistics: N2Statistics? = null,
) {
    check(config.restricted && !part.zeroOnly)
    for (packet in ops.manager.canonicalPackets(part.added))
        replayCanonicalPersistedSummaries(config, ops, part.copy(added = packet), applier, statistics)
}

private fun replayCanonicalPersistedSummaries(
    config: RunConfig, ops: ApOps, part: Subscription, applier: SummaryApplier, statistics: N2Statistics?,
) {
    val records = config.records
    val direction = config.direction
    val mode = config.mode
    val cancellation = ops.manager.cancellation
    statistics?.persistedReplayStarted()
    val seen = HashSet<Record>()
    val seenViews = HashMap<NativeReadKey, Boolean>()
    for (leaf in ops.leaves(part.added)) {
        cancellation.checkpoint()
        for (record in records.byEntry(part.callee, leaf)) {
            cancellation.checkpoint()
            statistics?.persistedReplayCandidate()
            if (record.direction != direction || !seen.add(record)) continue
            val added = ops.matchSummary(part.added, record.premise, mode, nativeRecordRead = true, role = SummaryMatchRole.SAVED_DIRECT) ?: continue
            statistics?.persistedReplayMatched()
            applier.applyRecord(part.copy(added = added), record)
        }
        for (record in records.byExit(part.callee, leaf)) {
            cancellation.checkpoint()
            statistics?.persistedReplayCandidate()
            if (record.direction == direction) continue
            record.forEachNativeReversedAt(leaf) { read, nonSubsumable ->
                cancellation.checkpoint()
                val key = read.semanticKey()
                val previous = seenViews[key]
                if (previous == true || previous == false && !nonSubsumable) return@forEachNativeReversedAt
                seenViews[key] = previous == true || nonSubsumable
                val packets = matchOppositeRecordPackets(ops, part.added, read, mode)
                if (packets.isEmpty()) return@forEachNativeReversedAt
                statistics?.persistedReplayMatched()
                for (added in packets)
                    applier.applyRecordView(part.copy(added = added), read.view, nonSubsumable)
            }
        }
    }
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.store.BlockScope
import org.opentaint.dataflow.graph.*
import java.util.BitSet
import java.util.Collections

/** Routing annotation only. It never enters AP, publication, native-record or report equality. */
internal sealed interface PreparedExit {
    data object DeadData : PreparedExit
    class Routes(routes: List<MethodBlockRoute>) : PreparedExit {
        val routes: List<MethodBlockRoute> = Collections.unmodifiableList(routes.toList())
    }
    class ActualStarts internal constructor(private val allowed: BitSet?) : PreparedExit {
        fun allows(target: Int): Boolean = allowed?.get(target) ?: true
    }
    class Terminal(val exit: PortId) : PreparedExit
}

/** Immutable layout/liveness inputs only; no actor, mutable entry or callback is retained. */
internal class PreparedExitDirectory(
    private val layout: MethodBlockLayout,
    private val routes: Map<PortId, MethodBlockRoute>,
    private val backward: Boolean,
    private val live: BlockLiveLocals?,
    private val endpoints: Set<Int>,
    private val originalEntry: Int,
) {
    private data class Key(val scope: BlockScope, val exit: PortId, val base: AccessPathBase)
    private val prepared = HashMap<Key, PreparedExit>()
    private val allowedTargets = HashMap<Int, BitSet>()
    var preparations: Long = 0; private set
    var targetMaskBuilds: Long = 0; private set

    fun getOrPrepare(scope: BlockScope, exit: PortId, base: AccessPathBase): PreparedExit =
        prepared.getOrPut(Key(scope, exit, base)) {
            preparations++
            val block = layout[scope.block]
            if (block.isLeaf && !block.isLoop && block.instructions.isEmpty() && exit.ordinal < 0) {
                // Starts are mutable reachability state, not a frozen destination list.
                val local = base as? AccessPathBase.LocalVar
                PreparedExit.ActualStarts(local?.let { l -> allowedTargets.getOrPut(l.idx) {
                    targetMaskBuilds++
                    BitSet(layout.instructionCount).apply {
                        for (target in 0 until layout.instructionCount) if (keep(target, l.idx)) set(target)
                    }
                } })
            } else if (exit.ordinal < 0) PreparedExit.Terminal(exit)
            else {
                val physical = layout.normalExit(exit)?.routes?.map { id ->
                    checkNotNull(routes[id]) { "A normal interface keeps every native directed route" }
                } ?: routes[exit]?.let(::listOf)
                // Unknown/synthetic interfaces retain their native dispatch/error behavior.
                if (physical == null) PreparedExit.Terminal(exit)
                else {
                    val local = base as? AccessPathBase.LocalVar
                    val kept = if (local == null) physical else physical.filter { keep(it.to, local.idx) }
                    if (kept.isEmpty()) PreparedExit.DeadData else PreparedExit.Routes(kept)
                }
            }
        }

    private fun keep(target: Int, local: Int): Boolean = target == originalEntry || target in endpoints ||
        live?.mayEnter(backward, target, local) != false

    fun clear() { prepared.clear(); allowedTargets.clear() }
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.Facts
import org.opentaint.dataflow.bidi.ap.Layer
import org.opentaint.dataflow.bidi.ap.MethodKey
import org.opentaint.dataflow.bidi.ap.PremiseKey
import org.opentaint.dataflow.bidi.ap.Reach
import org.opentaint.dataflow.bidi.ap.RecordLeafView
import org.opentaint.dataflow.bidi.store.CallerRef
import org.opentaint.dataflow.bidi.store.Record
import org.opentaint.ir.api.common.cfg.CommonInst

/** New propagation content preserves its exact premise, position and fact group. */
data class EdgeDelta(val premise: PremiseKey, val node: CommonInst, val facts: Facts) {
    val zeroToZero: Boolean get() = premise.isZero && facts is Reach

    override fun equals(other: Any?): Boolean = this === other || other is EdgeDelta &&
        premise == other.premise && node == other.node && facts == other.facts
    override fun hashCode(): Int = (premise.hashCode() * 31 + node.hashCode()) * 31 + facts.hashCode()
}

enum class Cut { STATEMENT, CALL, ENTRY_RULES, EXIT_RULES, SEED }

/** Published summary content keeps its canonical keys and the unchanged fact object. */
data class Publication(val premise: PremiseKey, val conclusion: Facts) {
    val layer: Layer get() = conclusion.layer
}

/** The caller layer is independent of the common added-fact and link layer. */
data class Subscription(
    val callee: MethodKey,
    val ref: CallerRef,
    val linkLayer: Layer,
    val added: Facts,
    val zeroOnly: Boolean = false,
) {
    val caller: MethodKey get() = ref.caller

    /** Owner metadata does not change the semantic subscription identity. */
    override fun equals(other: Any?): Boolean = this === other || other is Subscription &&
        callee == other.callee && ref == other.ref && linkLayer == other.linkLayer &&
        added == other.added && zeroOnly == other.zeroOnly

    override fun hashCode(): Int = (((callee.hashCode() * 31 + ref.hashCode()) * 31 +
        linkLayer.hashCode()) * 31 + added.hashCode()) * 31 + zeroOnly.hashCode()
}

/** Tests can control replay and notification timing without changing protocol operations. */
interface ProtocolSteps {
    fun replay(step: () -> Unit)
    fun notify(step: () -> Unit)

    object Inline : ProtocolSteps {
        override fun replay(step: () -> Unit): Unit = step()
        override fun notify(step: () -> Unit): Unit = step()
    }
}

/** Native records and opposite-direction leaf views have separate application boundaries. */
interface SummaryApplier : TargetApplier {
    fun requestStaticGroups(part: Subscription, marks: org.opentaint.dataflow.bidi.store.RequestMarkSelection) {
        error("This summary applier does not support static point requests")
    }
    fun applySummary(part: Subscription, pub: Publication, member: Int)
    /** Run-1 control admits a conditional static relation; it does not supply its mark. */
    fun applyStaticSummary(part: Subscription, pub: Publication, member: Int) {
        error("This summary applier does not support run-1 conditional statics")
    }
    fun applyRecord(part: Subscription, record: Record)
    fun applyRecordView(part: Subscription, view: RecordLeafView, nonSubsumable: Boolean)
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.store.PathTrie
import org.opentaint.dataflow.bidi.store.FlowBackedSummaries
import org.opentaint.dataflow.bidi.store.NormalStarRelationIndex
import java.util.Collections

/** Candidate lookup preserves the full premise and the member that matched its position. */
class PublicationIndex(private val ap: ApManager, private val ops: ApOps, flowBacked: Boolean = false) {
    private data class Member(val premise: PremiseKey, val index: Int)
    private val interners = ap.newInterners()
    private val possiblyEmpty = LinkedHashSet<PremiseKey>()
    private val normalStars = NormalStarRelationIndex(ap, interners) { possiblyEmpty += it }
    private val backed = FlowBackedSummaries(ap, replaceCovered = flowBacked, interners = interners,
        normalStars = normalStars, emptied = { possiblyEmpty += it })
    private val targets = LinkedHashMap<PremiseKey, LinkedHashSet<Target>>()
    private val indexed = java.util.Collections.newSetFromMap(java.util.IdentityHashMap<PremiseKey, Boolean>())
    private val byMember = PathTrie<Member>(ap.cancellation)
    fun addAll(pubs: List<Publication>): List<Publication> {
        ap.cancellation.checkpoint()
        val out = ArrayList<Publication>()
        for (pub in pubs) {
            ap.cancellation.checkpoint()
            if (!RuntimeDataDomain.packet(pub.premise, pub.conclusion)) continue
            assertCanonicalFlowSummary(pub.premise, pub.conclusion)
            check(pub.conclusion.base !is AccessPathBase.CleanerTemporary) {
                "A field-action temporary cannot enter a publication"
            }
            check((pub.conclusion is FlowTree) == pub.premise.isFlow) {
                "K6: the conclusion kind follows its premise"
            }
            check(pub.premise !is PremiseSet || pub.conclusion is TaintTree) {
                "A multi-premise publication must be TAINT"
            }
            val fresh = backed.addAll(pub.premise, pub.conclusion)
            if (fresh.isEmpty()) continue
            indexPremise(pub.premise)
            for (piece in fresh) out += Publication(pub.premise, piece)
        }
        // FLOW can arrive after a marked delta in this same detached batch.
        // Normalize before notifying callers, as well as before later replay.
        val current = out.flatMap { pub ->
            val kept = backed.retainCurrentAll(pub.premise, pub.conclusion)
            kept.map { Publication(pub.premise, it) }
        }
        for (premise in possiblyEmpty) if (publications(premise).isEmpty() && targets[premise].isNullOrEmpty()) {
            indexed.remove(premise)
            for (index in 0 until premise.size) {
                val initial = premise.member(index)
                byMember.remove(initial.base, initial.pathData, Member(premise, index))
            }
        }
        possiblyEmpty.clear()
        return Collections.unmodifiableList(current)
    }

    private fun indexPremise(premise: PremiseKey) {
        if (!indexed.add(premise)) return
        for (member in 0 until premise.size) {
            ap.cancellation.checkpoint()
            val initial = premise.member(member)
            byMember.add(initial.base, initial.pathData, Member(premise, member))
        }
    }

    fun addTargets(rows: TargetBatch): TargetBatch {
        val fresh = ArrayList<TargetSummary>()
        for (row in rows) {
            ap.cancellation.checkpoint()
            if (!RuntimeDataDomain.premise(row.premise)) continue
            if (!targets.getOrPut(row.premise, ::LinkedHashSet).add(row.target)) continue
            indexPremise(row.premise)
            fresh += row
        }
        return Collections.unmodifiableList(fresh)
    }

    private fun candidateMembers(original: PremiseKey, actual: Facts, mode: ApMode, zeroOnly: Boolean): Set<Member> {
        ap.cancellation.checkpoint()
        if (!RuntimeDataDomain.packet(original, actual)) return emptySet()
        val members = LinkedHashSet<Member>()
        if (zeroOnly) {
            for (member in byMember.lookupExtensions(AccessPathBase.Zero, EMPTY_PATH)) {
                ap.cancellation.checkpoint()
                if (member.premise.isZero) members += member
            }
        } else {
            for (leaf in ops.leaves(actual)) {
                ap.cancellation.checkpoint()
                val path = leaf.fact.path.toIntArray()
                if (mode.run1) {
                    members += byMember.lookupPrefixes(leaf.fact.base, path)
                    if (leaf.fact.tail != Tail.EXACT) {
                        // A nonexact actual ancestor can supply a requested
                        // component. The complete AP predicate checks its E,
                        // marks and tail after this candidate lookup.
                        members += byMember.lookupExtensions(leaf.fact.base, path)
                    }
                }
                else {
                    members += byMember.lookupExtensions(leaf.fact.base, path)
                    for (member in byMember.lookupPrefixes(leaf.fact.base, path)) {
                        ap.cancellation.checkpoint()
                        if (member.premise.member(member.index).let { it.mark is MarkSlot.Star || it.tail == Tail.STAR }) members += member
                    }
                }
            }
        }
        return members
    }

    fun candidates(part: Subscription, mode: ApMode): List<Pair<Publication, Int>> =
        candidates(part.ref.premise, part.added, mode, part.zeroOnly)

    fun candidates(original: PremiseKey, actual: Facts, mode: ApMode,
                   zeroOnly: Boolean = false): List<Pair<Publication, Int>> {
        val out = ArrayList<Pair<Publication, Int>>()
        for (member in candidateMembers(original, actual, mode, zeroOnly)) {
            ap.cancellation.checkpoint()
            for (publication in publications(member.premise)) out += publication to member.index
        }
        return Collections.unmodifiableList(out)
    }

    fun targetCandidates(part: Subscription, mode: ApMode): List<Pair<TargetSummary, Int>> =
        targetCandidates(part.ref.premise, part.added, mode, part.zeroOnly)

    fun targetCandidates(original: PremiseKey, actual: Facts, mode: ApMode,
                         zeroOnly: Boolean = false): List<Pair<TargetSummary, Int>> {
        val out = ArrayList<Pair<TargetSummary, Int>>()
        for (member in candidateMembers(original, actual, mode, zeroOnly)) {
            ap.cancellation.checkpoint()
            for (target in targets[member.premise].orEmpty()) out += TargetSummary(member.premise, target) to member.index
        }
        return Collections.unmodifiableList(out)
    }

    fun staticTargetCandidates(): List<Pair<TargetSummary, Int>> {
        val out = ArrayList<Pair<TargetSummary, Int>>()
        for (member in byMember.lookupExtensions(STATIC, EMPTY_PATH)) {
            ap.cancellation.checkpoint()
            for (target in targets[member.premise].orEmpty()) out += TargetSummary(member.premise, target) to member.index
        }
        return Collections.unmodifiableList(out)
    }

    /** Borrow the existing publication rows. No duplicate static-summary store. */
    fun staticCandidates(): List<Pair<Publication, Int>> {
        ap.cancellation.checkpoint()
        val out = ArrayList<Pair<Publication, Int>>()
        for (member in byMember.lookupExtensions(STATIC, EMPTY_PATH)) {
            ap.cancellation.checkpoint()
            for (publication in publications(member.premise)) {
                ap.cancellation.checkpoint()
                out += publication to member.index
            }
        }
        return Collections.unmodifiableList(out)
    }

    private fun currentFacts(premise: PremiseKey): Sequence<Facts> = backed.borrow(premise)

    /** Settled current native relation, including packed channels; never an append history. */
    internal fun currentPublications(): List<Publication> = backed.all().map { Publication(it.first, it.second) }.toList()

    private fun publications(premise: PremiseKey): List<Publication> =
        currentFacts(premise).map { Publication(premise, it) }.toList()
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.MethodKey
import org.opentaint.dataflow.configuration.CommonTaintConfigurationSink
import org.opentaint.ir.api.common.CommonMethod
import org.opentaint.ir.api.common.cfg.CommonInst

data class SinkKey(val method: CommonMethod, val statement: CommonInst, val ruleId: String)
data class ReportDescriptor(val key: SinkKey, val rule: CommonTaintConfigurationSink,
                            val representativeMethodKey: MethodKey)

/** Stable physical sink identities. Does not retain forms or witness trees. */
class ReportCatalog {
    private val byKey = HashMap<SinkKey, ReportId>()
    private val descriptors = ArrayList<ReportDescriptor>()

    @Synchronized fun intern(key: SinkKey, rule: CommonTaintConfigurationSink, context: MethodKey): ReportId {
        check(context.method == key.method && rule.id == key.ruleId)
        return byKey.getOrPut(key) {
            ReportId(descriptors.size).also { descriptors += ReportDescriptor(key, rule, context) }
        }
    }

    @Synchronized fun descriptor(id: ReportId): ReportDescriptor = descriptors[id.value]
}

package org.opentaint.dataflow.bidi.engine

import java.util.concurrent.atomic.AtomicLong
import java.util.concurrent.atomic.AtomicLongArray
import java.util.Collections

/** Optional numeric request-join measurements. No key, fact, event or trace is retained. */
class RequestBatchStatistics {
    private val phases = AtomicLong()
    private val continuations = AtomicLong()
    private val groupGeometryTests = AtomicLong()
    private val groupGeometrySteps = AtomicLong()
    private val memberScans = AtomicLong()
    private val answers = AtomicLong()
    private val climbs = AtomicLong()
    private val outgoingBatches = AtomicLong()
    private val outgoingMembers = AtomicLong()
    private val outgoingWidthHistogram = AtomicLongArray(31)
    private val maxOutgoingWidth = AtomicLong()
    private val duplicateTargetUnions = AtomicLong()
    private val peakPendingMembers = AtomicLong()
    private val peakPendingPrimitiveCapacity = AtomicLong()
    private val peakPendingLinkGroups = AtomicLong()
    private val peakPendingDeltaRoots = AtomicLong()
    private val peakCapturedLinkRoots = AtomicLong()
    private val maxServiceDelayNanos = AtomicLong()

    /** One flush accumulates in ordinary fields, then adds to the shared numeric totals. */
    internal class Counts {
        var phases = 0L
        var continuations = 0L
        var groupGeometryTests = 0L
        var groupGeometrySteps = 0L
        var memberScans = 0L
        var answers = 0L
        var climbs = 0L
        var outgoingBatches = 0L
        var outgoingMembers = 0L
        val outgoingWidthHistogram = LongArray(31)
        var maxOutgoingWidth = 0
        var duplicateTargetUnions = 0L

        fun acceptedBatch(width: Int) {
            require(width > 0) { "An outgoing request batch must be nonempty" }
            outgoingBatches++
            outgoingMembers += width
            outgoingWidthHistogram[31 - Integer.numberOfLeadingZeros(width)]++
            if (width > maxOutgoingWidth) maxOutgoingWidth = width
        }
    }

    internal fun record(counts: Counts) {
        phases.addAndGet(counts.phases)
        continuations.addAndGet(counts.continuations)
        groupGeometryTests.addAndGet(counts.groupGeometryTests)
        groupGeometrySteps.addAndGet(counts.groupGeometrySteps)
        memberScans.addAndGet(counts.memberScans)
        answers.addAndGet(counts.answers)
        climbs.addAndGet(counts.climbs)
        outgoingBatches.addAndGet(counts.outgoingBatches)
        outgoingMembers.addAndGet(counts.outgoingMembers)
        for (bin in counts.outgoingWidthHistogram.indices) {
            val count = counts.outgoingWidthHistogram[bin]
            if (count != 0L) outgoingWidthHistogram.addAndGet(bin, count)
        }
        maxOutgoingWidth.keepMaximum(counts.maxOutgoingWidth.toLong())
        duplicateTargetUnions.addAndGet(counts.duplicateTargetUnions)
    }

    internal fun pending(members: Long, primitiveCapacity: Long, linkGroups: Long, deltaRoots: Long, capturedRoots: Long) {
        peakPendingMembers.keepMaximum(members)
        peakPendingPrimitiveCapacity.keepMaximum(primitiveCapacity)
        peakPendingLinkGroups.keepMaximum(linkGroups)
        peakPendingDeltaRoots.keepMaximum(deltaRoots)
        peakCapturedLinkRoots.keepMaximum(capturedRoots)
    }

    internal fun serviceDelay(nanos: Long) { maxServiceDelayNanos.keepMaximum(nanos.coerceAtLeast(0L)) }

    data class Snapshot(
        val phases: Long,
        val continuations: Long,
        val groupGeometryTests: Long,
        /** Geometry-node inspections inside those group/row queries. */
        val groupGeometrySteps: Long,
        /** FLOW selection cells or TAINT concrete leaf ID probes; includes empty hash cells. */
        val memberScans: Long,
        val answers: Long,
        val climbs: Long,
        val outgoingBatches: Long,
        val outgoingMembers: Long,
        /** Accepted batches: bin k contains widths 2^k through 2^(k+1)-1, for k = 0..30. */
        val outgoingWidthHistogram: List<Long>,
        val maxOutgoingWidth: Long,
        val duplicateTargetUnions: Long,
        /** Maximum observed in one actor, not a simultaneous global live total. */
        val peakPendingMembers: Long,
        /** Owned request-builder/set int cells, not JVM bytes or hash-map capacity. */
        val peakPendingPrimitiveCapacity: Long,
        val peakPendingLinkGroups: Long,
        /** Pending AP delta wrappers/roots. This does not count their shared descendants or bytes. */
        val peakPendingDeltaRoots: Long,
        /** Old immutable group roots retained by one active phase view; overlaps other AP owners. */
        val peakCapturedLinkRoots: Long,
        /** Oldest pending work's observed wait to a flush service opportunity. */
        val maxServiceDelayNanos: Long,
    )

    fun snapshot(): Snapshot = Snapshot(phases.get(), continuations.get(), groupGeometryTests.get(), groupGeometrySteps.get(),
        memberScans.get(), answers.get(), climbs.get(), outgoingBatches.get(), outgoingMembers.get(),
        Collections.unmodifiableList(List(31) { outgoingWidthHistogram.get(it) }), maxOutgoingWidth.get(),
        duplicateTargetUnions.get(), peakPendingMembers.get(), peakPendingPrimitiveCapacity.get(),
        peakPendingLinkGroups.get(), peakPendingDeltaRoots.get(), peakCapturedLinkRoots.get(), maxServiceDelayNanos.get())

    companion object {
        fun ifEnabled(): RequestBatchStatistics? =
            if (java.lang.Boolean.getBoolean("org.opentaint.bidi.optimizationStatistics")) RequestBatchStatistics() else null
    }
}

private fun AtomicLong.keepMaximum(value: Long) {
    var old = get()
    while (value > old && !compareAndSet(old, value)) old = get()
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.*

/** Complete fixed-run admission, evaluated once in the caller on the original offer. */
internal fun emitRestrictedInitials(
    config: RunConfig,
    ops: ApOps,
    callee: MethodKey,
    actual: Facts,
    statistics: N2Statistics? = null,
): List<AdmittedInitial> {
    check(config.restricted)
    val ap = ops.manager
    val result = LinkedHashSet<AdmittedInitial>()
    ops.limit(actual, config.fieldLimit, object : ApOut {
        override fun markRequest(mark: TaintMark): Nothing = error("A field cut cannot request a mark")
        override fun result(bounded: Facts) {
            for (leaf in ops.leaves(bounded)) {
                ap.cancellation.checkpoint()
                if (config.index == 2) validateRun2StaticFullInput(ap, leaf, config.fieldLimit)
            }
            result.addAll(checkNotNull(config.demand).initials(callee, bounded, config.admissionPolicy))
        }
    })
    statistics?.demandLookupCompleted(result.isNotEmpty())
    return result.toList()
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.store.*

/** Run-1 input emission borrows the authoritative request rows. It retains no
 * supplier, question mirror, deferred answer, or completed-answer history. */
internal class Run1Abstraction(
    private val ops: ApOps,
    private val answer: (AdmittedInitial) -> Unit,
    private val borrowRequests: (Facts) -> List<RequestedRow>,
    private val collectRequests: (Run1Slot, RequestMarkSelection) -> Unit,
    private val statistics: RequestBatchStatistics? = null,
    private val policyStatistics: Run1AbstractionStatistics? = null,
    private val owner: MethodKey? = null,
) {
    private var released = false

    // Pending ownership is exclusively the method actor's temporary RequestStorage.
    val hasPending: Boolean get() = false
    internal val pendingAnswerShapeCount: Long get() = 0
    internal val pendingAnswerMarkCount: Long get() = 0

    fun emit(ref: CallerRef, input: Facts) {
        emit(ref.premise, input)
    }

    /** A local link has an original premise, but no physical call instruction. */
    fun emit(original: PremiseKey, input: Facts) {
        check(!released)
        val ap = ops.manager
        ap.cancellation.checkpoint()
        if (!RuntimeDataDomain.packet(original, input)) return
        validateRun1Supplier(ap, original, input)
        validateRun1Input(ap, input)
        if (input.base == STATIC) return // static reads/refinements are operation-local, never callee entry seeds
        answer(AdmittedInitial(ops.policy(input), Layer.NORMAL))
        if (input is Reach) return
        if (input is TaintTree) {
            // Read after any synchronous abstraction starts; later P admission is
            // covered by registered caller-input replay, never by an emitter memo.
            val rows = borrowRequests(input)
            val counts = statistics?.let { RequestBatchStatistics.Counts() }
            forEachConcreteAnswer(ap, input, rows, counts) { initial ->
                if (counts != null) counts.answers++
                answer(initial)
            }
            if (counts != null) statistics?.record(counts)
        }
    }

    fun requireMark(initial: InitialAp, mark: TaintMark) = requireMarks(initial, RequestMarkSet.of(mark))

    fun requireMarks(initial: InitialAp, marks: RequestMarkSet) {
        check(!released)
        ops.manager.cancellation.checkpoint()
        val slot = normalRun1Slot(initial) ?: return // concrete/zero/special-root origins never request
        check(slot is Run1Slot.Base) { "Static interests do not enter ordinary P/R" }
        collectRequests(slot, marks)
    }

    /** Compatibility for local-service callers; only the actor can commit P. */
    fun flush(quantum: Int): Boolean { require(quantum > 0); check(!released); return true }

    fun release() { released = true }
}

package org.opentaint.dataflow.bidi.engine

import java.util.concurrent.atomic.AtomicLong

/** Numeric counters do not retain methods, initials, suppliers or profile objects. */
class Run1AbstractionStatistics {
    private val inputArrivals = AtomicLong()
    private val restrictedIntersections = AtomicLong()
    private val initialCandidates = AtomicLong()
    private val newInitials = AtomicLong()
    private val inheritedBaseRowsSkipped = AtomicLong()
    private val structuralCandidates = AtomicLong()
    private val replayVisits = AtomicLong()
    private val replayCandidates = AtomicLong()
    private val replayTests = AtomicLong()
    private val replayAnswers = AtomicLong()
    private val replayClimbs = AtomicLong()
    private val maxReplayVisitNanos = AtomicLong()
    private val maxReplayVisitCandidates = AtomicLong()
    private val requestCommits = AtomicLong()
    private val freshRequestRows = AtomicLong()
    private val freshRequestMembers = AtomicLong()
    private val createdDynamicRows = AtomicLong()
    private val requestMatcherCalls = AtomicLong()
    private val requestDirectLookups = AtomicLong()
    private val requestBroadScans = AtomicLong()
    private val requestScannedKeys = AtomicLong()
    private val requestMatchedRows = AtomicLong()
    private val requestFrozenSlotsExamined = AtomicLong()
    private val requestDynamicKeysExamined = AtomicLong()
    private val temporaryRows = AtomicLong()
    private val temporaryMembers = AtomicLong()
    private val peakTemporaryRows = AtomicLong()
    private val peakTemporaryMembers = AtomicLong()
    private val requestOfferCalls = AtomicLong()
    private val offeredRequestMembers = AtomicLong()
    private val authoritativeDuplicateRequestMembers = AtomicLong()
    private val temporaryDuplicateRequestMembers = AtomicLong()
    private val freshTemporaryRequestMembers = AtomicLong()
    private val freshFlowInputReads = AtomicLong()
    private val growthFlowInputReads = AtomicLong()

    internal fun requestOffer(counts: RequestAdmissionCounts) {
        requestOfferCalls.incrementAndGet(); offeredRequestMembers.addAndGet(counts.offeredMembers)
        authoritativeDuplicateRequestMembers.addAndGet(counts.authoritativeDuplicates)
        temporaryDuplicateRequestMembers.addAndGet(counts.temporaryDuplicates)
        freshTemporaryRequestMembers.addAndGet(counts.freshTemporaryMembers)
    }
    /** An admitted FLOW input's actual current value was read; growth is a subset of these reads. */
    internal fun freshFlowInputVisit(growth: Boolean) {
        freshFlowInputReads.incrementAndGet()
        if (growth) growthFlowInputReads.incrementAndGet()
    }

    internal fun requestCommit(rows: Int, marks: Long, createdRows: Int) {
        requestCommits.incrementAndGet(); freshRequestRows.addAndGet(rows.toLong())
        freshRequestMembers.addAndGet(marks); createdDynamicRows.addAndGet(createdRows.toLong())
    }
    internal fun requestMatch(counts: RequestMatchCounts, returnedRows: Int) {
        requestMatcherCalls.incrementAndGet(); requestDirectLookups.addAndGet(counts.directLookups)
        requestBroadScans.addAndGet(counts.broadScans); requestScannedKeys.addAndGet(counts.scannedKeys)
        requestMatchedRows.addAndGet(returnedRows.toLong())
        requestFrozenSlotsExamined.addAndGet(counts.frozenSlotsExamined)
        requestDynamicKeysExamined.addAndGet(counts.dynamicKeysExamined)
    }
    internal fun temporaryChanged(rows: Long, marks: Long) {
        peakTemporaryRows.accumulateAndGet(temporaryRows.addAndGet(rows), ::maxOf)
        peakTemporaryMembers.accumulateAndGet(temporaryMembers.addAndGet(marks), ::maxOf)
    }

    internal fun arrival() { inputArrivals.incrementAndGet() }
    internal fun intersection() { restrictedIntersections.incrementAndGet() }
    internal fun initial(fresh: Boolean) {
        initialCandidates.incrementAndGet()
        if (fresh) newInitials.incrementAndGet()
    }
    internal fun inheritedBaseRowSkipped() { inheritedBaseRowsSkipped.incrementAndGet() }
    internal fun structural() { structuralCandidates.incrementAndGet() }
    /** One finite request-batch/current-input visit, including work interrupted by cancellation. */
    internal fun replayVisit(candidates: Long, tests: Long, answers: Long, climbs: Long, nanos: Long) {
        replayVisits.incrementAndGet()
        replayCandidates.addAndGet(candidates)
        replayTests.addAndGet(tests)
        replayAnswers.addAndGet(answers)
        replayClimbs.addAndGet(climbs)
        maxReplayVisitNanos.accumulateAndGet(nanos, ::maxOf)
        maxReplayVisitCandidates.accumulateAndGet(candidates, ::maxOf)
    }
    data class Snapshot(
        val inputArrivals: Long, val restrictedIntersections: Long,
        val initialCandidates: Long, val newInitials: Long,
        /** Matched inherited B rows skipped as a whole; no mark enumeration is counted here. */
        val inheritedBaseRowsSkipped: Long, val structuralCandidates: Long,
        val replayVisits: Long, val replayCandidates: Long, val replayTests: Long,
        val replayAnswers: Long, val replayClimbs: Long,
        val maxReplayVisitNanos: Long, val maxReplayVisitCandidates: Long,
        val requestCommits: Long, val freshRequestRows: Long, val freshRequestMembers: Long,
        val createdDynamicRequestRows: Long, val requestMatcherCalls: Long, val requestDirectLookups: Long,
        val requestBroadScans: Long, val requestScannedKeys: Long, val requestMatchedRows: Long,
        val currentTemporaryRequestRows: Long, val currentTemporaryRequestMembers: Long,
        val peakTemporaryRequestRows: Long, val peakTemporaryRequestMembers: Long,
        /** Actor collectRequests calls, including offers wholly rejected by effective R. */
        val requestOfferCalls: Long,
        /** Mark IDs examined by those calls before effective R filtering. */
        val offeredRequestMembers: Long,
        val authoritativeDuplicateRequestMembers: Long, val temporaryDuplicateRequestMembers: Long,
        /** Accepted P memberships; overlaps eventual D admission counts and is not a fact count. */
        val freshTemporaryRequestMembers: Long,
        /** Actual current-value reads for newly admitted FLOW inputs, not logical facts or marks. */
        val freshFlowInputReads: Long, val growthFlowInputReads: Long,
        /** Stored frozen S slots and dynamic keys examined; sum equals requestScannedKeys. */
        val requestFrozenSlotsExamined: Long, val requestDynamicKeysExamined: Long,
    )

    fun snapshot(): Snapshot = Snapshot(inputArrivals.get(), restrictedIntersections.get(),
        initialCandidates.get(), newInitials.get(), inheritedBaseRowsSkipped.get(), structuralCandidates.get(),
        replayVisits.get(), replayCandidates.get(), replayTests.get(), replayAnswers.get(), replayClimbs.get(),
        maxReplayVisitNanos.get(), maxReplayVisitCandidates.get(), requestCommits.get(), freshRequestRows.get(),
        freshRequestMembers.get(), createdDynamicRows.get(), requestMatcherCalls.get(), requestDirectLookups.get(),
        requestBroadScans.get(), requestScannedKeys.get(), requestMatchedRows.get(), temporaryRows.get(), temporaryMembers.get(),
        peakTemporaryRows.get(), peakTemporaryMembers.get(), requestOfferCalls.get(), offeredRequestMembers.get(),
        authoritativeDuplicateRequestMembers.get(), temporaryDuplicateRequestMembers.get(), freshTemporaryRequestMembers.get(),
        freshFlowInputReads.get(), growthFlowInputReads.get(), requestFrozenSlotsExamined.get(), requestDynamicKeysExamined.get())
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.interp.*

/** Only immutable invocation state is retained, never a cached full call plan. */
data class CallResumeState(val callerLayer: Layer, val identityCandidate: Boolean? = null,
                           val pendingDemotion: Boolean = false)

data class OperationInput(val site: ResumeSite, val premise: PremiseKey, val facts: Facts,
                          val callState: CallResumeState? = null)

/** Actor-owned resume directory. Service replies name these rows; they never carry callbacks. */
internal class Run1PointResume(private val core: BlockRunState) {
    private data class PointKey(val site: ResumeSite, val initial: InitialAp, val base: AccessPathBase,
                                val tail: Tail, val fieldExclusion: ExclusionSet, val layer: Layer,
                                val state: CallResumeState?)
    private val pointKeys = HashMap<PointKey, Long>()
    private class PendingFlowImages(private var root: FlowNode) {
        fun addAll(incoming: FlowNode, ap: ApManager) {
            root = FlowAlgebra.mergeAdd(root, incoming, ap.cancellation)
        }
        fun snapshotRoot(): FlowNode = root
    }
    private class PointRow(val id: Long, val key: PointKey) {
        val pending = HashMap<TaintMark, PendingFlowImages>()
    }
    private data class DetachedAnswer(val group: TaintMark, val images: FlowNode)
    private val points = HashMap<Long, PointRow>()
    private data class ReadKey(val site: ResumeSite, val operation: StaticOperation)
    private val readKeys = HashMap<ReadKey, Long>()
    private val reads = HashMap<Long, Pair<OperationInput, StaticOperation>>()
    private data class WriterKey(val premise: PremiseKey, val output: Pattern, val layer: Layer)
    private val writerKeys = HashMap<WriterKey, Long>()
    private val writers = HashMap<Long, WriterKey>()
    private class DirectRow(val key: ReadKey, val payload: OperationInput, var waiting: MarkSet)
    private val direct = HashMap<Long, DirectRow>()
    private val directKeys = HashMap<ReadKey, Long>()
    private class WriterInput(val writer: WriterKey, var waiting: MarkSet)
    private val writerInputs = HashMap<Long, WriterInput>()
    private class ConditionalJoin(val writer: WriterKey) {
        val inputs = arrayOfNulls<RegionGroups>(writer.premise.size)
    }
    private data class JoinInput(val join: Long, val member: Int)
    private val conditionalKeys = HashMap<WriterKey, Long>()
    private val conditional = HashMap<Long, ConditionalJoin>()
    private val joinInputs = HashMap<Long, JoinInput>()
    private sealed interface CallResultKey {
        data class Ap(val output: Pattern, val layer: Layer) : CallResultKey
        data class Terminal(val target: Target) : CallResultKey
    }
    private data class CallKey(val callee: MethodKey, val ref: org.opentaint.dataflow.bidi.store.CallerRef,
                               val linkLayer: Layer, val premise: PremiseKey, val result: CallResultKey, val member: Int)
    private class CallContinuation(val key: CallKey, var part: Subscription, var result: StaticCallResult,
                                   val member: Int) { var waiting = MarkSet.EMPTY }
    private val callKeys = HashMap<CallKey, Long>()
    private val calls = HashMap<Long, CallContinuation>()

    fun callInterest(part: Subscription, result: StaticCallResult, member: Int) {
        if (!RuntimeDataDomain.packet(part.ref.premise, part.added) || !RuntimeDataDomain.premise(result.premise)) return
        val initial = result.premise.member(member)
        val atom = (initial.mark as? MarkSlot.Concrete)?.mark ?: return
        val statistics = core.context.shared.n2Statistics
        val pieces = when (result) {
            is StaticCallResult.Ap -> {
                val pub = result.publication
                if (!RuntimeDataDomain.packet(pub.premise, pub.conclusion)) return
                core.ops.leaves(pub.conclusion).map { leaf ->
                    val plain = core.ap.factsOf(leaf.fact, leaf.exclusion, pub.layer)
                    val conclusion = if (plain is TaintTree && pub.conclusion is TaintTree)
                        plain.withProtection(pub.conclusion.nonSubsumable) else plain
                    CallResultKey.Ap(leaf, pub.layer) to StaticCallResult.Ap(pub.copy(conclusion = conclusion))
                }.toList()
            }
            is StaticCallResult.Terminal -> listOf(CallResultKey.Terminal(result.summary.target) to result)
        }
        for ((resultKey, piece) in pieces) {
            statistics?.staticGroupCallOffered()
            val key = CallKey(part.callee, part.ref, part.linkLayer, result.premise, resultKey, member)
            val id = callKeys.getOrPut(key) {
                (core.nextStaticTicket()).also { calls[it] = CallContinuation(key, part, piece, member) }
            }
            val row = calls.getValue(id)
            // AP equality retains the current per-leaf key and protection refresh.
            val previous = row.result
            if (previous is StaticCallResult.Ap && piece is StaticCallResult.Ap)
                row.result = StaticCallResult.Ap(previous.publication.copy(conclusion =
                    core.ap.mergeAddDelta(previous.publication.conclusion, piece.publication.conclusion).first))
            row.part = row.part.copy(added = core.ap.mergeAddDelta(row.part.added, part.added).first)
            val fresh = MarkSet.of(core.ap.marks.runtimeAtom(atom, core.mode.markMode)) - row.waiting
            if (fresh.isEmpty) continue
            statistics?.staticGroupCallFallbackAdmitted()
            row.waiting += fresh
            core.staticBatch.interests += StaticInterest(core.key, id, initial.toPattern(), fresh)
        }
        core.requestWork()
    }

    fun reached(summary: StatementSummary, at: OperationInput) {
        if (!RuntimeDataDomain.packet(at.premise, at.facts)) return
        if (at.facts !is Reach || !at.premise.isZero) return
        for (operation in summary.staticOperations) {
            if (core.config.disableRun1Statics && when (operation) {
                    is StaticOperation.Read -> true
                    is StaticOperation.Write -> core.dropsStaticField(operation.target.fact)
                    is StaticOperation.MarkInput -> operation.position.fact.path.size != 1 ||
                        (operation.position.fact.tail != Tail.EXACT && !operation.includeBase)
                }) continue
            val key = ReadKey(at.site, operation)
            val id = readKeys.getOrPut(key) {
                (core.nextStaticTicket()).also { reads[it] = at to operation }
            }
            when (operation) {
                is StaticOperation.Read -> core.staticBatch.reads += StaticReadRegistration(core.key, id,
                    Pattern(operation.transfer.from, operation.transfer.exclusion))
                is StaticOperation.MarkInput -> {
                    val mark = (operation.position.fact.mark as? MarkSlot.Concrete)?.mark ?: continue
                    val groups = MarkSet.of(core.ap.marks.runtimeAtom(mark, core.mode.markMode))
                    if (operation.position.fact.path.size == 1) {
                        val exact = operation.position.fact.tail == Tail.EXACT
                        // A wildcard is a field-query descriptor, never a class
                        // FLOW initial. Its empty-suffix branch is an exact
                        // global marker; BELOW cleaners omit that branch.
                        if (!exact && !core.config.disableRun1Statics)
                            core.staticBatch.reads += StaticReadRegistration(core.key, id, operation.position)
                        if (exact || operation.includeBase) {
                            val directId = directKeys.getOrPut(key) {
                                (core.nextStaticTicket()).also { direct[it] = DirectRow(key, at, MarkSet.EMPTY) }
                            }
                            val row = direct.getValue(directId)
                            val fresh = groups - row.waiting
                            if (!fresh.isEmpty) {
                                row.waiting += fresh
                                val point = operation.position.copy(fact = operation.position.fact.copy(tail = Tail.EXACT),
                                    exclusion = ExclusionSet.Empty)
                                core.staticBatch.interests += StaticInterest(core.key, directId, point, fresh)
                            }
                        }
                    } else core.staticBatch.reads += StaticReadRegistration(core.key, id, operation.position)
                }
                is StaticOperation.Write -> Unit
            }
        }
        // A late call-summary suffix can reach this operation outside this
        // state's workLocal call. Its final post-S output can be a duplicate,
        // so output admission alone does not reserve work for these effects.
        if (!core.staticBatch.isEmpty) core.requestWork()
    }

    fun request(at: OperationInput, groups: MarkSet) {
        if (!RuntimeDataDomain.packet(at.premise, at.facts)) return
        val original = at.premise as? InitialAp ?: return
        val flow = at.facts as? FlowTree ?: return
        if (original.base != STATIC || original.mark !is MarkSlot.Star) return
        if (groups.isEmpty) return
        val key = PointKey(at.site, original, flow.base, flow.tail, flow.exclusion, flow.layer, at.callState)
        val id = pointKeys.getOrPut(key) {
            (core.nextStaticTicket()).also { points[it] = PointRow(it, key) }
        }
        val row = points.getValue(id)
        var subscribe = MarkSet.EMPTY
        groups.forEach { group ->
            core.ap.cancellation.checkpoint()
            val images = row.pending[group]
            if (images == null) {
                row.pending[group] = PendingFlowImages(flow.root)
                subscribe += group
            } else images.addAll(flow.root, core.ap)
        }
        if (!subscribe.isEmpty) {
            core.staticBatch.interests += StaticInterest(core.key, id, original.toPattern(), subscribe)
        }
        core.requestWork()
    }

    /** Only an executed local producer reaches this boundary. Its bounded
     * scalar relation belongs to the writer, independently of summary deltas. */
    fun localWrite(premise: PremiseKey, value: Facts) {
        if (!RuntimeDataDomain.packet(premise, value)) return
        check(value.base == STATIC)
        // A completed local write already has its permitted concrete input.
        // Supply the actual bounded output here, independently of outgoing exit
        // rules or summary publication. FLOW writers remain registered below.
        if (value is TaintTree) core.staticBatch.supplies += core.staticSlices(value)
        for (leaf in core.ops.leaves(value)) {
            if (leaf.fact.path.size < 2) continue // exact class markers have no FLOW writer
            val region = Run1StaticService.region(leaf)
            core.staticBatch.writes += region
            if (value !is FlowTree) continue
            check(premise is InitialAp && !premise.isZero && premise.mark is MarkSlot.Star)
            val key = WriterKey(premise, leaf, value.layer)
            if (key in writerKeys) continue
            val id = core.nextStaticTicket()
            writerKeys[key] = id
            writers[id] = key
            if (premise.base == STATIC)
                core.staticBatch.writers += StaticWriterRegistration(core.key, id, premise, region)
            else core.staticBatch.flowWriters += StaticFlowWriter(core.key, id, region)
        }
        core.requestWork()
    }

    /** A computed result can supply the pool before its summary is erased.
     * Promotion never admits a new write point or FLOW writer. */
    fun computedGroups(premise: PremiseKey, value: Facts) {
        if (!RuntimeDataDomain.packet(premise, value)) return
        check(value.base == STATIC)
        if (value !is TaintTree) return
        if (core.hasKnownStaticGroupInput(premise)) {
            val initial = premise as InitialAp
            val actual = core.knownStaticInput(initial)
            for (leaf in core.ops.leaves(value)) {
                core.ap.cancellation.checkpoint()
                core.context.shared.n2Statistics?.staticGroupSupplyDirect()
                val scalar = core.ap.factsOf(leaf.fact, leaf.exclusion, value.layer)
                core.composeStaticSummaryWithActualInput(initial, scalar, actual) { value ->
                    core.staticBatch.supplies += core.staticSlices(value)
                }
            }
        } else if (!premise.isZero && (0 until premise.size).all { premise.member(it).base == STATIC }) {
            for (leaf in core.ops.leaves(value)) {
                core.context.shared.n2Statistics?.staticGroupJoinFallback()
                val key = WriterKey(premise, leaf, value.layer)
                if (key in conditionalKeys) continue
                // A fixed-group conditional is a pending complete binding, not a
                // permanent summary archive or a service-side Cartesian join.
                // Its immutable scalar survives erasure of the method row.
                val joinId = core.nextStaticTicket()
                conditionalKeys[key] = joinId
                conditional[joinId] = ConditionalJoin(key)
                repeat(premise.size) { member ->
                    val initial = premise.member(member)
                    val atom = (initial.mark as MarkSlot.Concrete).mark
                    val inputId = core.nextStaticTicket()
                    joinInputs[inputId] = JoinInput(joinId, member)
                    core.staticBatch.interests += StaticInterest(core.key, inputId, initial.toPattern(),
                        MarkSet.of(core.ap.marks.runtimeAtom(atom, core.mode.markMode)))
                }
            }
        }
        if (premise.isZero)
            core.staticBatch.supplies += core.staticSlices(value)
        core.requestWork()
    }

    fun onEffect(effect: StaticOwnerEffect) {
        when (effect) {
            is StaticOwnerEffect.ReadReady -> {
                val (at, operation) = checkNotNull(reads[effect.id]) { "Unknown static read reply" }
                val position = effect.region.fact.path
                if (position.size < 2) return // class-point MarkInput uses the direct group path
                val initial = core.ap.initial(Pattern(PathFact(STATIC, position.take(2), Tail.STAR, MarkSlot.STAR), ExclusionSet.Empty))
                val input = core.ap.factsOf(effect.region.fact.copy(mark = MarkSlot.STAR,
                    tail = if (effect.region.fact.tail == Tail.EXACT || effect.region.fact.tail == Tail.ANY_TAINT) Tail.STAR else effect.region.fact.tail),
                    ExclusionSet.Empty, Layer.DEMAND)
                core.installPoint(initial, input, at.site, at.callState)
            }
            is StaticOwnerEffect.PointReady -> {
                calls[effect.id]?.let { call ->
                    call.waiting -= effect.supply.groups
                    if (call.waiting.isEmpty) { callKeys.remove(call.key); calls.remove(effect.id) }
                    core.staticCallSupply(call.part, call.result, call.member, effect.supply)
                    return
                }
                writerInputs[effect.id]?.let { input ->
                    input.waiting -= effect.supply.groups
                    if (input.waiting.isEmpty) writerInputs.remove(effect.id)
                    publishMatched(input.writer, listOf(effect.supply))
                    core.requestWork()
                    return
                }
                joinInputs.remove(effect.id)?.let { input ->
                    val join = conditional.getValue(input.join)
                    join.inputs[input.member] = effect.supply
                    if (join.inputs.all { it != null }) {
                        conditional.remove(input.join)
                        check(conditionalKeys.remove(join.writer) == input.join)
                        publishMatched(join.writer, join.inputs.map { checkNotNull(it) })
                    }
                    core.requestWork()
                    return
                }
                val directRow = direct[effect.id]
                if (directRow != null) {
                    val at = directRow.payload
                    directRow.waiting -= effect.supply.groups
                    if (directRow.waiting.isEmpty) { directKeys.remove(directRow.key); direct.remove(effect.id) }
                    val actual = core.staticFacts(effect.supply)
                    for (leaf in core.ops.leaves(actual)) {
                        val premise = concreteInitial(leaf)
                        core.installPoint(premise, core.ops.startFact(premise, core.mode), at.site, at.callState)
                    }
                    return
                }
                answerPackedPoint(effect)
            }
            is StaticOwnerEffect.WriterInterest -> {
                val writer = checkNotNull(writers[effect.id]) { "Unknown static writer interest" }
                val original = writer.premise as? InitialAp ?: return
                check(!original.isZero && original.mark is MarkSlot.Star && writer.output.fact.mark is MarkSlot.Star)
                if (original.base == STATIC) {
                    val inputId = core.nextStaticTicket()
                    writerInputs[inputId] = WriterInput(writer, effect.groups)
                    core.staticBatch.interests += StaticInterest(core.key, inputId, original.toPattern(), effect.groups)
                } else {
                    for (atom in effect.groups.ids)
                        core.addMarkRequest(original, TaintMark(atom))
                }
            }
        }
        core.requestWork()
    }

    private fun answerPackedPoint(effect: StaticOwnerEffect.PointReady) {
        val row = checkNotNull(points[effect.id]) { "Unknown static point reply" }
        effect.supply.groups.forEach { group -> check(row.pending.containsKey(group)) }
        val detached = ArrayList<DetachedAnswer>()
        effect.supply.groups.forEach { group ->
            detached += DetachedAnswer(group, checkNotNull(row.pending.remove(group)).snapshotRoot())
        }
        // Detach every supplied group before any callback. Later requests must
        // subscribe again; an immutable detached root cannot acquire new images.
        if (row.pending.isEmpty()) {
            check(pointKeys.remove(row.key) == row.id)
            check(points.remove(row.id) === row)
        }
        for (answer in detached) {
            core.ap.cancellation.checkpoint()
            materializeScalarImages(row.key, answer.images,
                RegionGroups(effect.supply.region, MarkSet.of(answer.group)))
        }
    }

    private fun materializeScalarImages(key: PointKey, images: FlowNode, supply: RegionGroups) {
        val actual = core.staticFacts(supply)
        for (leaf in core.ops.leaves(actual)) {
            core.ap.cancellation.checkpoint()
            val premise = concreteInitial(leaf)
            materializeStaticFlowImages(core.ops, core.mode, key.initial, premise, images,
                key.base, key.tail, key.fieldExclusion, key.layer) { value ->
                core.installPoint(premise, value, key.site, key.state)
            }
        }
    }

    private fun publishMatched(writer: WriterKey, inputs: List<RegionGroups>) {
        // Both FLOW writers and unanswered fixed-mark input joins own the
        // admitted bounded scalar; neither borrows an erased method summary.
        val current = core.ap.factsOf(writer.output.fact, writer.output.exclusion, writer.layer)
        core.composeStaticSummary(writer.premise, current, inputs) { value ->
            core.staticBatch.supplies += core.staticSlices(value)
        }
    }

    private fun concreteInitial(leaf: Pattern): InitialAp = concreteStaticResumeInitial(core.ap, leaf)

    fun clear() { pointKeys.clear(); points.clear(); readKeys.clear(); reads.clear(); writerKeys.clear(); writers.clear(); direct.clear(); directKeys.clear(); callKeys.clear(); calls.clear(); writerInputs.clear(); conditionalKeys.clear(); conditional.clear(); joinInputs.clear() }
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.ap.ifds.access.util.AccessorInterner.Companion.isFieldAccessor
import org.opentaint.dataflow.bidi.ap.*

/** Only the actual singleton normal abstract origin is a request slot. */
internal fun normalRun1Slot(premise: PremiseKey): Run1Slot? =
    (premise as? InitialAp)?.let { Run1Slot.fromInitial(it) }

/** Validate the actual origin before request eligibility. Layer changes do not
 * change the origin or invalidate a surviving FLOW dependency. */
internal fun validateRun1Supplier(ap: ApManager, premise: PremiseKey, input: Facts) {
    ap.cancellation.checkpoint()
    check((input is FlowTree) == premise.isFlow) { "K6: input kind follows its original premise" }
    check(premise !is PremiseSet || input is TaintTree) { "A conjunctive supplier is concrete" }
    if (input is FlowTree) {
        val original = premise as? InitialAp ?: error("A run-1 FLOW supplier needs one abstract origin")
        validateRun1Initial(original, 1)
        check(original.mark == MarkSlot.STAR) { "A FLOW supplier needs an abstract original mark" }
    }
}

/** Non-static request geometry has one empty-path base row. */
internal fun slotMatches(slot: Run1Slot, input: Facts): Boolean = input !is Reach &&
    slot.base == input.base && when (input) {
        is FlowTree -> !input.root.isEmpty
        is TaintTree -> !input.root.isEmpty
        is Reach -> false
    }

/** All concrete branches and all actual requested marks, with no supplier memo.
 * Exact and nonexact alternatives remain distinct; every nonexact answer is STAR. */
internal fun forEachConcreteAnswer(
    ap: ApManager, input: Facts, rows: List<RequestedRow>,
    statistics: RequestBatchStatistics.Counts? = null, emit: (AdmittedInitial) -> Unit,
) {
    if (input !is TaintTree || rows.isEmpty()) return
    val stack = ArrayDeque<Pair<TaintNode, IntArray>>()
    stack.addLast(input.root to EMPTY_PATH)
    while (stack.isNotEmpty()) {
        ap.cancellation.checkpoint()
        val (node, path) = stack.removeLast()
        fun branch(marks: MarkSet, exact: Boolean) {
            if (marks.isEmpty) return
            for (row in rows) {
                ap.cancellation.checkpoint()
                if (statistics != null) statistics.groupGeometrySteps++
                val slot = row.slot
                if (slot.base != input.base) continue
                val tail = if (exact && path.isEmpty()) Tail.EXACT else Tail.STAR
                var canonicalPath: PathNode? = null
                var prepared = false
                for (id in marks.data) {
                    ap.cancellation.checkpoint()
                    if (statistics != null) statistics.memberScans++
                    val mark = TaintMark(id)
                    if (mark !in row.marks) continue
                    if (!prepared) { canonicalPath = ap.path(slot.pathData); prepared = true }
                    val initial = ap.initial(slot.base, canonicalPath, tail, ExclusionSet.Empty, MarkSlot.Concrete(mark))
                    val layer = input.layer or (tail != Tail.EXACT)
                    emit(AdmittedInitial(initial, layer))
                }
            }
        }
        branch(node.leaf.exact, exact = true)
        branch(node.leaf.any, exact = false)
        val children = node.childData ?: continue
        val accessors = checkNotNull(node.accessorData)
        for (i in children.indices.reversed()) {
            ap.cancellation.checkpoint()
            stack.addLast(children[i] to (path + accessors[i]))
        }
    }
}

/** Admission checks the selected F78 initial domain, not the wider AP factory. */
internal fun validateRun1Initial(initial: InitialAp, fieldLimit: Int) {
    check(fieldLimit == 1) { "F78 run 1 requires field limit 1" }
    check(initial.exclusion == ExclusionSet.Empty) { "A run-1 initial has no field exclusion" }
    check(initial.tail == Tail.EXACT || initial.tail == Tail.STAR) { "A run-1 initial is EXACT or STAR" }
    check(initial.base !is AccessPathBase.CleanerTemporary)
    if (initial.isZero) {
        check(initial.path == null && initial.tail == Tail.EXACT && initial.mark == MarkSlot.Concrete(TaintMark.ZERO))
        return
    }
    val path = initial.pathData
    if (initial.base != STATIC) {
        check(path.isEmpty()) { "A non-static run-1 initial has an empty path" }
    } else {
        check(path.size <= 2 && (path.isEmpty() || path[0].isClass()) &&
            (path.size < 2 || path[1].isFieldAccessor())) { "Invalid run-1 static initial layout" }
    }
    when (val mark = initial.mark) {
        is MarkSlot.Star -> {
            check(mark.excluded.isEmpty && initial.tail == Tail.STAR)
            check(initial.base != STATIC || path.size == 2) { "Run 1 has only abstract static-field initials" }
        }
        is MarkSlot.Concrete -> {
            check(initial.base != STATIC || path.isNotEmpty()) {
                "Run 1 has no concrete empty static-root initial"
            }
            check(initial.base != STATIC || path.size != 1 || initial.tail == Tail.EXACT) {
                "A global class marker is exact; it has no class-wide initial"
            }
        }
    }
}

/** No emitter cut: fail if the preceding selected JVM cuts/bindings did not
 * establish their input invariant. Current facts may still have ANY/must/E/mx. */
internal fun validateRun1Input(ap: ApManager, input: Facts) {
    if (input is Reach) return
    check(input.base !is AccessPathBase.CleanerTemporary)
    val root: TrieNode<*> = when (input) {
        is FlowTree -> input.root
        is TaintTree -> input.root
        is Reach -> return
    }
    check(root.boundedDepth <= 1) { "The run-1 input was not cut before delivery" }
    if (input.base != STATIC) {
        val children = root.childData ?: return
        val accessors = checkNotNull(root.accessorData)
        for (i in children.indices) {
            ap.cancellation.checkpoint()
            check(accessors[i].isCounted() && children[i].childData == null) {
                "A non-static run-1 input has at most one ordinary accessor"
            }
        }
        return
    }
    check(input !is TaintTree || input.root.leaf.exact.isEmpty) { "Exact empty static-root taint is outside F78" }
    val classes = root.accessorData ?: return
    for (i in classes.indices) {
        ap.cancellation.checkpoint()
        check(classes[i].isClass()) { "A static input begins with its class accessor" }
        val cls = root.childData!![i]
        if (input is TaintTree) check((cls.leaf as TaintLeaves).any.isEmpty) {
            "A run-1 global class marker is exact; class-wide queries are descriptors"
        }
        val fields = cls.accessorData ?: continue
        for (j in fields.indices) {
            ap.cancellation.checkpoint()
            check(fields[j].isFieldAccessor() && cls.childData!![j].childData == null) {
                "A static class contains one static field and no deeper path"
            }
        }
    }
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.interp.ownedMap
import org.opentaint.dataflow.bidi.store.forEachMark
import org.opentaint.dataflow.bidi.store.RequestMarkCursor
import org.opentaint.dataflow.bidi.store.RequestMarkSelection
import org.opentaint.dataflow.bidi.store.RequestMarkSet
import org.opentaint.dataflow.bidi.store.RequestMarkSetBuilder

/** Only non-static abstract origins use ordinary mark requests. Statics use the direct service. */
sealed interface Run1Slot {
    val base: AccessPathBase
    val pathData: IntArray

    data class Base(override val base: AccessPathBase) : Run1Slot {
        init {
            require(base != STATIC && base != AccessPathBase.Zero && base !is AccessPathBase.CleanerTemporary)
        }
        override val pathData: IntArray get() = IntArray(0)
    }

    fun initial(ap: ApManager): InitialAp = ap.initial(base, ap.path(pathData.toList()), Tail.STAR,
        ExclusionSet.Empty, MarkSlot.STAR)

    companion object {
        fun fromInitial(initial: InitialAp): Run1Slot? {
            if (!RuntimeDataDomain.initial(initial) || initial.tail != Tail.STAR || initial.mark != MarkSlot.STAR ||
                initial.exclusion != ExclusionSet.Empty) return null
            val path = initial.pathData
            return if (initial.base != STATIC && path.isEmpty() && !initial.isZero &&
                initial.base !is AccessPathBase.CleanerTemporary) Base(initial.base) else null
        }
    }
}

typealias RequestRows = Map<Run1Slot, RequestMarkSet>

/** Borrowed merged mark set. No frozen or precomputed static segment is retained. */
data class RequestRowView(val marks: RequestMarkSet) : RequestMarkSelection {
    val isEmpty: Boolean get() = marks.isEmpty
    override fun containsId(id: Int): Boolean = marks.containsId(id)
    operator fun contains(mark: TaintMark): Boolean = mark in marks
    fun forEachMark(visit: (TaintMark) -> Unit) = marks.forEachMark(visit)
    fun countMarks(checkpoint: () -> Unit): Int { checkpoint(); return marks.size }
    override fun cursor(): RequestMarkCursor = marks.cursor()
}

data class RequestedRow(val slot: Run1Slot, val marks: RequestRowView)

fun RequestMarkSelection.minus(admitted: RequestMarkSelection, checkpoint: () -> Unit = {}): RequestMarkSet {
    return minus(admitted, null, checkpoint)
}

internal fun RequestMarkSelection.minus(admitted: RequestMarkSelection, counts: RequestAdmissionCounts?,
                                        checkpoint: () -> Unit): RequestMarkSet {
    val fresh = RequestMarkSetBuilder()
    val cursor = cursor()
    while (!cursor.isComplete) cursor.step(256) { mark ->
        checkpoint()
        if (counts != null) counts.offeredMembers++
        if (admitted.containsId(mark.id)) {
            if (counts != null) counts.authoritativeDuplicates++
        } else fresh.add(mark)
    }
    checkpoint()
    return fresh.takeSnapshot()
}

internal fun RequestMarkSelection.toRequestMarkSet(checkpoint: () -> Unit): RequestMarkSet {
    if (this is RequestMarkSet) return this
    val out = RequestMarkSetBuilder()
    val cursor = cursor()
    while (!cursor.isComplete) cursor.step(256) { checkpoint(); out.add(it) }
    checkpoint()
    return out.takeSnapshot()
}

internal fun unionRequestMarks(a: RequestMarkSet, b: RequestMarkSet, checkpoint: () -> Unit): RequestMarkSet {
    if (a.isEmpty) return b
    if (b.isEmpty || a === b) return a
    val larger = if (a.size >= b.size) a else b
    val other = if (larger === a) b else a
    var subset = true
    other.forEachMark { checkpoint(); if (it !in larger) subset = false }
    if (subset) return larger
    return RequestMarkSetBuilder().apply {
        larger.forEachMark { checkpoint(); add(it) }
        other.forEachMark { checkpoint(); add(it) }
    }.takeSnapshot()
}

/** One owner keeps merged non-static rows. Temporary and committed stores use the same type. */
class RequestStorage {
    private val additions = LinkedHashMap<Run1Slot, RequestMarkSet>()
    private var addedMembers = 0L
    val isEmpty: Boolean get() = additions.isEmpty()
    val dynamicRows: Int get() = additions.size
    val dynamicMembers: Long get() = addedMembers

    fun borrow(slot: Run1Slot): RequestRowView = RequestRowView(additions[slot] ?: RequestMarkSet.EMPTY)

    fun addAll(slot: Run1Slot, offered: RequestMarkSelection, checkpoint: () -> Unit = {}): RequestMarkSet {
        return addAll(slot, offered, null, checkpoint)
    }

    internal fun addAll(slot: Run1Slot, offered: RequestMarkSelection, counts: RequestAdmissionCounts?,
                        checkpoint: () -> Unit): RequestMarkSet {
        if (!RuntimeDataDomain.base(slot.base)) return RequestMarkSet.EMPTY
        val old = borrow(slot)
        val fresh = RequestMarkSetBuilder()
        val cursor = offered.cursor()
        while (!cursor.isComplete) cursor.step(256) { mark ->
            checkpoint()
            if (mark in old) {
                if (counts != null) counts.temporaryDuplicates++
            } else fresh.add(mark)
        }
        if (fresh.isEmpty) return RequestMarkSet.EMPTY
        checkpoint()
        val delta = fresh.takeSnapshot()
        val prior = additions[slot]
        additions[slot] = if (prior == null) delta else RequestMarkSetBuilder().apply {
            prior.forEachMark { checkpoint(); add(it) }
            delta.forEachMark { checkpoint(); add(it) }
        }.takeSnapshot()
        addedMembers = Math.addExact(addedMembers, delta.size.toLong())
        checkpoint()
        return delta
    }

    /** Only the synchronous owner flusher may iterate this borrowed map. */
    fun pendingRows(): RequestRows {
        return java.util.Collections.unmodifiableMap(additions)
    }

    /** Hold SummaryStorage's lock until the complete descriptor list is built. No actor callbacks. */
    fun borrowMatchingRows(input: Facts, checkpoint: () -> Unit): List<RequestedRow> =
        borrowMatchingRows(input, checkpoint, null)

    fun borrowMatchingRows(input: Facts, checkpoint: () -> Unit, counts: RequestMatchCounts?): List<RequestedRow> = buildList {
        checkpoint()
        if (!RuntimeDataDomain.base(input.base)) return@buildList
        val root: TrieNode<*> = when (input) {
            is Reach -> return@buildList
            is FlowTree -> input.root
            is TaintTree -> input.root
        }
        if (root.isEmpty) return@buildList
        fun addSlot(slot: Run1Slot) {
            checkpoint()
            val row = borrow(slot)
            if (!row.isEmpty) add(RequestedRow(slot, row))
        }
        if (input.base == STATIC) return@buildList
        if (counts != null) counts.directLookups++
        addSlot(Run1Slot.Base(input.base))
    }

}

/** Per-call numeric aggregation; no atomic operation for individual candidate rows. */
class RequestMatchCounts {
    var directLookups: Long = 0
    var broadScans: Long = 0
    var scannedKeys: Long = 0
    var frozenSlotsExamined: Long = 0
    var dynamicKeysExamined: Long = 0
}

/** One actor collection attempt; populated only inside its existing R/P membership passes. */
internal class RequestAdmissionCounts {
    var offeredMembers = 0L
    var authoritativeDuplicates = 0L
    var temporaryDuplicates = 0L
    var freshTemporaryMembers = 0L
}

internal fun freezeRequestRows(rows: Map<Run1Slot, RequestMarkSet>): RequestRows = ownedMap(rows)

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.ap.ifds.access.util.AccessorIdx
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.interp.*
import org.opentaint.dataflow.util.Cancellation

/** An immutable AP slice. The selector is stored separately from group membership. */
data class StaticRegion(val pattern: Pattern) {
    init { require(pattern.fact.base == STATIC) }
    constructor(fact: PathFact, exclusion: ExclusionSet = ExclusionSet.Empty) :
        this(Pattern(fact.copy(mark = MarkSlot.STAR), exclusion))
}

/** Selected executable atoms: GROUP handles in GROUP mode, FULL handles in FULL
 * mode. The legacy payload name does not imply owner-only membership. */
data class RegionGroups(val region: Pattern, val groups: MarkSet)

/** Event payloads contain values and IDs, never actor callbacks or mutable stores. */
sealed interface StaticOwnerEffect {
    val owner: MethodKey
    data class ReadReady(override val owner: MethodKey, val id: Long, val region: Pattern) : StaticOwnerEffect
    data class PointReady(override val owner: MethodKey, val id: Long, val supply: RegionGroups) : StaticOwnerEffect
    data class WriterInterest(override val owner: MethodKey, val id: Long,
                              val groups: MarkSet) : StaticOwnerEffect
}

data class StaticReadRegistration(val owner: MethodKey, val id: Long, val region: Pattern)
data class StaticInterest(val owner: MethodKey, val id: Long, val region: Pattern, val wanted: MarkSet)
data class StaticWriterRegistration(val owner: MethodKey, val id: Long, val premise: PremiseKey, val region: Pattern)
data class StaticFlowWriter(val owner: MethodKey, val id: Long, val region: Pattern)

/** Select before collecting any supplies. Raw callers preserve first-hit packet order. */
enum class SupplyProfile { CANONICAL_RUN1_FULL, ORDERED_REFERENCE }

/** One actor-owned delta. Keys own their paths; immutable masks contain complete runtime atoms. */
class StaticSupplies internal constructor(
    private val profile: SupplyProfile,
    private val cancellation: Cancellation?,
    private val statistics: N2Statistics?,
) : AbstractCollection<RegionGroups>() {
    private val ordered = if (profile == SupplyProfile.ORDERED_REFERENCE) ArrayList<RegionGroups>() else null
    private val merged = if (profile == SupplyProfile.CANONICAL_RUN1_FULL) LinkedHashMap<Pattern, MarkSet>() else null

    operator fun plusAssign(supply: RegionGroups) {
        if (!RuntimeDataDomain.base(supply.region.fact.base)) return
        if (ordered != null) {
            ordered += supply
            return
        }
        cancellation?.checkpoint()
        if (supply.groups.isEmpty) {
            statistics?.staticSupplyOffered(0, 0, false)
            return
        }
        val p = supply.region
        require(p.fact.base == STATIC && p.exclusion == ExclusionSet.Empty &&
            (p.fact.path.size == 2 && p.fact.path[0].isClass() && !p.fact.path[1].isClass() ||
                p.fact.path.size == 1 && p.fact.path[0].isClass() && p.fact.tail == Tail.EXACT)) {
            "A canonical run-1 supply must be a bounded static field or exact class marker with empty E"
        }
        val rows = checkNotNull(merged)
        val region = if (p.fact.mark == MarkSlot.STAR) p else Run1StaticService.region(p)
        val old = rows[region] ?: MarkSet.EMPTY
        if (supply.groups.isSubsetOf(old)) {
            statistics?.staticSupplyOffered(supply.groups.size, 0, false)
            return
        }
        // Snapshot only a newly retained key. Duplicate offers allocate no path copy or delta mask.
        val key = if (old.isEmpty) region.copy(fact = region.fact.copy(path = ownedList(region.fact.path))) else region
        val combined = old + supply.groups
        rows[key] = combined
        statistics?.staticSupplyOffered(supply.groups.size, combined.size - old.size, old.isEmpty)
    }

    operator fun plusAssign(supplies: Iterable<RegionGroups>) {
        for (supply in supplies) this += supply
    }

    override val size: Int get() = ordered?.size ?: checkNotNull(merged).size
    override fun iterator(): Iterator<RegionGroups> {
        ordered?.let { return it.iterator() }
        val entries = checkNotNull(merged).iterator()
        return object : Iterator<RegionGroups> {
            override fun hasNext(): Boolean {
                cancellation?.checkpoint()
                return entries.hasNext()
            }
            override fun next(): RegionGroups {
                cancellation?.checkpoint()
                val (region, groups) = entries.next()
                return RegionGroups(region, groups)
            }
        }
    }
}

/** Temporary actor-owned deltas. Commit is the only route to cumulative service membership. */
class StaticBatch(val supplyProfile: SupplyProfile = SupplyProfile.ORDERED_REFERENCE,
                  cancellation: Cancellation? = null,
                  private val statistics: N2Statistics? = null) {
    val reads = ArrayList<StaticReadRegistration>()
    val interests = ArrayList<StaticInterest>()
    val writes = ArrayList<Pattern>()
    val supplies = StaticSupplies(supplyProfile, cancellation, statistics)
    val writers = ArrayList<StaticWriterRegistration>()
    val flowWriters = ArrayList<StaticFlowWriter>()
    internal fun committed() {
        if (supplyProfile == SupplyProfile.CANONICAL_RUN1_FULL) statistics?.staticSupplyCommitted()
    }
    val isEmpty: Boolean get() = reads.isEmpty() && interests.isEmpty() && writes.isEmpty() &&
        supplies.isEmpty() && writers.isEmpty() && flowWriters.isEmpty()
}

/** Run-1 positive forward closure. Program transfer and resumption always run at the addressed owner. */
class Run1StaticService(private val ap: ApManager, private val markMode: MarkMode = MarkMode.FULL) {
    private val lock = Any()
    private val ops = ApOps(ap)
    private data class Key(val owner: MethodKey, val id: Long)

    /** Positional candidates only. Owners perform complete AP matching and transfer. */
    private inner class Regions<V : Any> {
        private var index = org.opentaint.dataflow.bidi.store.PathTrie<V>(ap.cancellation)
        fun add(p: Pattern, value: V) = index.add(p.fact.base, p.fact.path.toIntArray(), value)
        fun around(p: Pattern): List<V> = index.around(p.fact.base, p.fact.path.toIntArray()).distinct()
        fun prefixes(p: Pattern): List<V> = index.lookupPrefixes(p.fact.base, p.fact.path.toIntArray()).distinct()
        fun clear() { index = org.opentaint.dataflow.bidi.store.PathTrie(ap.cancellation) }
    }
    private class ReadRow(val registration: StaticReadRegistration) { val delivered = HashSet<Pattern>() }
    private class InterestRow(val registration: StaticInterest) { var wanted = registration.wanted }
    private class FlowWriterRow(val owner: MethodKey, val id: Long, val region: Pattern,
                                val staticOrigin: Boolean) { var admitted = MarkSet.EMPTY }
    private data class FieldKey(val klass: AccessorIdx, val field: AccessorIdx)
    private class FieldState(val region: Pattern) {
        var req = MarkSet.EMPTY
        var reach = MarkSet.EMPTY
        var processed = MarkSet.EMPTY
        val pending = LinkedHashMap<Key, InterestRow>()
    }
    private val writes = LinkedHashSet<Pattern>()
    private val writeIndex = Regions<Pattern>()
    // Only broad root/class supplies keep spatial history. A normal field has
    // one canonical membership, never a second region-valued group pool.
    private val broadGroups = LinkedHashMap<Pattern, MarkSet>()
    private val fields = LinkedHashMap<FieldKey, FieldState>()
    private val fieldIndex = Regions<FieldKey>()
    private val reads = LinkedHashMap<Key, ReadRow>()
    private val readIndex = Regions<Key>()
    private val classInterests = LinkedHashMap<Key, InterestRow>()
    private val classRequested = LinkedHashMap<Pattern, MarkSet>()
    private val flowWriters = LinkedHashMap<Key, FlowWriterRow>()
    private val flowWriterIndex = Regions<Key>()
    private var candidateVisits = 0L
    private var replies = 0L

    private fun isExactClassPoint(p: Pattern): Boolean =
        p.fact.base == STATIC && p.fact.path.size == 1 && p.fact.tail == Tail.EXACT

    private fun fieldKey(p: Pattern): FieldKey? = p.fact.path
        .takeIf { p.fact.base == STATIC && it.size >= 2 }
        ?.let { FieldKey(it[0], it[1]) }

    private fun field(p: Pattern): FieldState {
        val key = checkNotNull(fieldKey(p))
        return fields.getOrPut(key) {
            val canonical = Pattern(PathFact(STATIC, listOf(key.klass, key.field), Tail.STAR,
                MarkSlot.STAR), ExclusionSet.Empty)
            FieldState(canonical).also { state ->
                fieldIndex.add(canonical, key)
                for ((position, groups) in broadGroups) {
                    ap.cancellation.checkpoint()
                    if (!isExactClassPoint(position) && intersect(canonical, position) != null)
                        state.reach += groups
                }
            }
        }
    }

    fun commit(batch: StaticBatch): List<StaticOwnerEffect> = synchronized(lock) {
        ap.cancellation.checkpoint()
        val out = ArrayList<StaticOwnerEffect>()
        for (read in batch.reads) {
            if (!RuntimeDataDomain.base(read.region.fact.base)) continue
            val key = Key(read.owner, read.id)
            if (key in reads) continue
            val row = ReadRow(read)
            reads[key] = row
            readIndex.add(read.region, key)
            for (write in writeIndex.around(read.region)) admitRead(row, write, out)
        }
        for (interest in batch.interests) {
            if (interest.wanted.isEmpty || interest.region.fact.base != STATIC) continue
            if (fieldKey(interest.region) != null) request(field(interest.region), interest, out)
            else requestClass(interest, out)
        }
        // Every FLOW writer uses this route, including static-origin summaries.
        // Complete fixed-mark bindings are pending actor state, not writer rows.
        for (writer in batch.writers) {
            if (!RuntimeDataDomain.premise(writer.premise) || !RuntimeDataDomain.base(writer.region.fact.base)) continue
            check(writer.premise is InitialAp && writer.premise.mark is MarkSlot.Star)
            check(writer.premise.base == STATIC) { "Only all-static summaries subscribe to pool values" }
            registerWriter(FlowWriterRow(writer.owner, writer.id, writer.region, true), out)
        }
        for (writer in batch.flowWriters) {
            if (!RuntimeDataDomain.base(writer.region.fact.base)) continue
            registerWriter(FlowWriterRow(writer.owner, writer.id, writer.region, false), out)
        }
        for (write in batch.writes) if (RuntimeDataDomain.base(write.fact.base)) admitWrite(region(write), out)
        for (supply in batch.supplies) {
            if (supply.groups.isEmpty) continue
            val position = region(supply.region)
            require(position.fact.base == STATIC)
            admitWrite(position, out)
            if (fieldKey(position) != null) groupWrite(field(position), supply.groups, out)
            else {
                val old = broadGroups[position] ?: MarkSet.EMPTY
                val fresh = supply.groups - old
                if (fresh.isEmpty) continue
                broadGroups[position] = old + fresh
                if (!isExactClassPoint(position)) {
                    for (key in fieldIndex.around(position)) {
                        val state = fields.getValue(key)
                        if (intersect(state.region, position) != null) groupWrite(state, fresh, out)
                    }
                }
            }
            // Exact class points never supply fields. Keep the old broad AP
            // boundary and pending-only class continuations.
            if (fieldKey(position) == null) {
                val iterator = classInterests.iterator()
                while (iterator.hasNext()) {
                    ap.cancellation.checkpoint()
                    val row = iterator.next().value
                    answerClass(row, position, supply.groups, out)
                    if (row.wanted.isEmpty) iterator.remove()
                }
            }
        }
        replies += out.size
        batch.committed()
        out
    }

    private fun request(state: FieldState, interest: StaticInterest,
                        out: MutableList<StaticOwnerEffect>) {
        val answered = interest.wanted intersect (state.reach + state.processed)
        if (!answered.isEmpty) out += StaticOwnerEffect.PointReady(interest.owner, interest.id,
            RegionGroups(state.region, answered))
        val newlyRequested = interest.wanted - (state.req + state.processed)
        state.reach -= interest.wanted
        state.processed += answered
        val pending = interest.wanted - answered
        state.req += pending
        if (!pending.isEmpty) {
            val key = Key(interest.owner, interest.id)
            val row = state.pending[key]
            if (row == null) state.pending[key] = InterestRow(interest.copy(wanted = pending))
            else row.wanted += pending
        }
        if (!newlyRequested.isEmpty) {
            for (key in flowWriterIndex.around(state.region)) {
                val writer = flowWriters.getValue(key)
                if (requestMatches(writer.region, state.region)) askOnce(writer, newlyRequested, out)
            }
        }
    }

    private fun groupWrite(state: FieldState, groups: MarkSet,
                           out: MutableList<StaticOwnerEffect>) {
        val fresh = groups - (state.reach + state.processed)
        if (fresh.isEmpty) return
        val answered = fresh intersect state.req
        state.req -= answered
        state.processed += answered
        state.reach += fresh - answered
        if (answered.isEmpty) return // An unrequested arrival never wakes writers.
        val iterator = state.pending.iterator()
        while (iterator.hasNext()) {
            val row = iterator.next().value
            val selected = row.wanted intersect answered
            if (!selected.isEmpty) {
                row.wanted -= selected
                out += StaticOwnerEffect.PointReady(row.registration.owner, row.registration.id,
                    RegionGroups(state.region, selected))
            }
            if (row.wanted.isEmpty) iterator.remove()
        }
    }

    private fun registerWriter(row: FlowWriterRow, out: MutableList<StaticOwnerEffect>) {
        val key = Key(row.owner, row.id)
        if (flowWriters.putIfAbsent(key, row) != null) return
        flowWriterIndex.add(row.region, key)
        var wanted = MarkSet.EMPTY
        for (field in fieldIndex.around(row.region)) {
            val state = fields.getValue(field)
            if (requestMatches(row.region, state.region)) wanted += state.req + state.processed
        }
        if (fieldKey(row.region) == null) {
            for ((region, groups) in classRequested)
                if (requestMatches(row.region, region)) wanted += groups
        }
        askOnce(row, wanted, out)
    }

    private fun askOnce(row: FlowWriterRow, offered: MarkSet,
                        out: MutableList<StaticOwnerEffect>) {
        val fresh = offered - row.admitted
        if (fresh.isEmpty) return
        row.admitted += fresh
        out += StaticOwnerEffect.WriterInterest(row.owner, row.id, fresh)
    }

    private fun requestMatches(a: Pattern, b: Pattern): Boolean {
        ap.cancellation.checkpoint()
        candidateVisits++
        return intersect(a.copy(exclusion = ExclusionSet.Empty), b.copy(exclusion = ExclusionSet.Empty)) != null
    }

    private fun requestClass(interest: StaticInterest, out: MutableList<StaticOwnerEffect>) {
        check(interest.region.fact.path.size == 1 && interest.region.fact.tail == Tail.EXACT) {
            "A global marker request names an exact class point"
        }
        val key = Key(interest.owner, interest.id)
        val row = classInterests[key] ?: InterestRow(interest).also { classInterests[key] = it }
        row.wanted += interest.wanted
        val requested = region(interest.region).copy(exclusion = ExclusionSet.Empty)
        classRequested[requested] = (classRequested[requested] ?: MarkSet.EMPTY) + interest.wanted
        for ((position, supplied) in broadGroups) answerClass(row, position, supplied, out)
        if (row.wanted.isEmpty) classInterests.remove(key)
        for (writer in flowWriterIndex.prefixes(interest.region)) {
            val w = flowWriters.getValue(writer)
            if (requestMatches(w.region, interest.region)) askOnce(w, interest.wanted, out)
        }
    }

    private fun answerClass(row: InterestRow, position: Pattern, supplied: MarkSet,
                            out: MutableList<StaticOwnerEffect>) {
        val overlap = intersect(row.registration.region, position) ?: return
        val fresh = supplied intersect row.wanted
        if (fresh.isEmpty) return
        row.wanted -= fresh
        out += StaticOwnerEffect.PointReady(row.registration.owner, row.registration.id,
            RegionGroups(overlap, fresh))
    }

    private fun admitRead(row: ReadRow, write: Pattern, out: MutableList<StaticOwnerEffect>) {
        ap.cancellation.checkpoint()
        candidateVisits++
        val overlap = intersect(row.registration.region, write) ?: return
        if (row.delivered.add(overlap)) out += StaticOwnerEffect.ReadReady(row.registration.owner, row.registration.id, overlap)
    }

    private fun admitWrite(position: Pattern, out: MutableList<StaticOwnerEffect>) {
        if (!writes.add(position)) return
        writeIndex.add(position, position)
        for (key in readIndex.around(position)) admitRead(reads.getValue(key), position, out)
    }

    data class Statistics(val writeRegions: Int, val suppliedRegions: Int, val suppliedGroups: Long,
                          val readDescriptors: Int, val pointSubscriptions: Int, val writerRows: Int,
                          val flowWriterRows: Int, val candidateVisits: Long, val ownerReplies: Long,
                          val distinctRequestedAtoms: Int, val distinctSuppliedAtoms: Int,
                          val suppliedOwnerGroups: Int, val suppliedFullAtoms: Int)
    fun statistics(): Statistics = synchronized(lock) {
        val supplied = fields.values.filter { !(it.reach + it.processed).isEmpty }
        // Snapshot only: union existing membership, with no hot-path observer,
        // member enumeration, or retained cardinality index. GROUP mode cannot
        // recover the number of underlying FULL marks from these memberships.
        val requestedAtoms = HashSet<TaintMark>()
        val suppliedAtoms = HashSet<TaintMark>()
        for (state in fields.values) {
            state.req.forEach { requestedAtoms += it }
            state.processed.forEach { requestedAtoms += it; suppliedAtoms += it }
            state.reach.forEach { suppliedAtoms += it }
        }
        classRequested.values.forEach { marks -> marks.forEach { requestedAtoms += it } }
        broadGroups.values.forEach { marks -> marks.forEach { suppliedAtoms += it } }
        Statistics(writes.size, supplied.size + broadGroups.size,
            supplied.sumOf { (it.reach + it.processed).size.toLong() } + broadGroups.values.sumOf { it.size.toLong() },
            reads.size, fields.values.sumOf { it.pending.size } + classInterests.size,
            flowWriters.values.count { it.staticOrigin }, flowWriters.values.count { !it.staticOrigin },
            candidateVisits, replies, requestedAtoms.size, suppliedAtoms.size,
            suppliedAtoms.mapTo(HashSet(), ap.marks::groupOf).size,
            suppliedAtoms.count(ap.marks::isFull))
    }

    data class RequestStatistics(val requested: Long, val reached: Long, val processed: Long,
                                 val pendingMemberships: Long, val writerAdmissions: Long)
    fun requestStatistics(): RequestStatistics = synchronized(lock) {
        RequestStatistics(fields.values.sumOf { it.req.size.toLong() },
            fields.values.sumOf { it.reach.size.toLong() }, fields.values.sumOf { it.processed.size.toLong() },
            fields.values.sumOf { f -> f.pending.values.sumOf { it.wanted.size.toLong() } } +
                classInterests.values.sumOf { it.wanted.size.toLong() },
            flowWriters.values.sumOf { it.admitted.size.toLong() })
    }

    fun slices(value: Facts): List<RegionGroups> {
        if (value !is TaintTree) return emptyList()
        val out = ArrayList<RegionGroups>()
        for (leaf in ops.leaves(value)) {
            val mark = (leaf.fact.mark as? MarkSlot.Concrete)?.mark ?: continue
            val atom = ap.marks.runtimeAtom(mark, markMode)
            out += RegionGroups(region(leaf), MarkSet.of(atom))
        }
        return out
    }

    fun facts(region: Pattern, groups: MarkSet): Facts {
        require(!groups.isEmpty)
        check(region.fact.path.size != 1 || region.fact.tail == Tail.EXACT) {
            "Global marker materialization preserves the exact class point"
        }
        val atoms = groups
        var result: TaintTree? = null
        for (atom in atoms.ids) {
            val executable = ap.marks.runtimeAtom(TaintMark(atom), markMode)
            check(executable.id == atom) { "Static reply contains an atom from a different run mode" }
            val one = ap.factsOf(region.fact.copy(mark = MarkSlot.Concrete(executable),
                tail = if (region.fact.tail == Tail.EXACT) Tail.EXACT else Tail.ANY), ExclusionSet.Empty, Layer.DEMAND) as TaintTree
            result = if (result == null) one else ap.taintTree(one.base, Layer.DEMAND,
                ap.taintAlg.mergeAdd(result.root, one.root, ap.cancellation), one.exclusion, one.anyTail)
        }
        return checkNotNull(result)
    }

    fun clear() = synchronized(lock) {
        writes.clear(); writeIndex.clear(); broadGroups.clear(); fields.clear(); fieldIndex.clear()
        reads.clear(); readIndex.clear(); classInterests.clear(); classRequested.clear()
        flowWriters.clear(); flowWriterIndex.clear()
    }

    companion object {
        fun region(pattern: Pattern): Pattern = pattern.copy(fact = pattern.fact.copy(mark = MarkSlot.STAR))
        fun hasStaticMember(premise: PremiseKey): Boolean {
            var found = false
            premise.forEachMember { if (it.base == STATIC) found = true }
            return found
        }

        /** Exact ancestor points do not supply descendants. Exclusions apply before consuming a prefix. */
        fun intersect(a: Pattern, b: Pattern): Pattern? {
            if (a.fact.base != b.fact.base) return null
            val p = a.fact.path
            val q = b.fact.path
            val common = minOf(p.size, q.size)
            if ((0 until common).any { p[it] != q[it] }) return null
            if (p.size < q.size) {
                if (a.fact.tail == Tail.EXACT || !a.exclusion.admits(q[p.size])) return null
                return region(b)
            }
            if (q.size < p.size) {
                if (b.fact.tail == Tail.EXACT || !b.exclusion.admits(p[q.size])) return null
                return region(a)
            }
            val tail = when {
                a.fact.tail == Tail.EXACT || b.fact.tail == Tail.EXACT -> Tail.EXACT
                a.fact.tail == Tail.ANY || b.fact.tail == Tail.ANY -> Tail.ANY
                a.fact.tail == Tail.ANY_TAINT || b.fact.tail == Tail.ANY_TAINT -> Tail.ANY_TAINT
                else -> Tail.STAR
            }
            return Pattern(a.fact.copy(tail = tail, mark = MarkSlot.STAR), a.exclusion.union(b.exclusion))
        }
    }
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.MethodKey

/** The unit runner is the sole caller of an actor during a run. */
interface RunActor {
    val key: MethodKey
    val steps: Long
    val hasZeroWork: Boolean
    val demandLayerEdges: Long
    val recordCrossings: Long

    /** True only after fact work, publications and deferred request owners are complete. */
    fun work(quantum: Int): Boolean

    /** Called at a complete barrier, after every runner has joined. */
    fun freeze()
}

/** Later steps supply the method and summary handlers through this required factory. */
fun interface RunnerHandlerFactory<A : RunActor> {
    fun create(port: RunnerPort<A>): RunnerHandler<A>
}

interface RunnerHandler<A : RunActor> {
    fun createActor(key: MethodKey): A
    /** Work is handled by the owning runner. Other events use their protocol handler. */
    fun handle(event: RunEvent)
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.ApMode
import org.opentaint.dataflow.bidi.ap.Direction
import org.opentaint.dataflow.bidi.ap.MethodKey
import org.opentaint.dataflow.bidi.ap.MarkMode
import org.opentaint.dataflow.bidi.ap.RestrictedInitialPolicy
import org.opentaint.dataflow.bidi.driver.SeedIndex
import org.opentaint.dataflow.bidi.driver.FieldLimitSchedule
import org.opentaint.dataflow.bidi.store.DemandStore
import org.opentaint.dataflow.bidi.store.RecordStore
import java.util.Collections

/** Immutable run inputs. The driver writes the backing records only at a completed-run barrier. */
class RunConfig(
    val index: Int,
    val fieldLimit: Int,
    val demand: DemandStore?,
    records: RecordStore,
    val seeds: SeedIndex,
    roots: List<MethodKey>,
    disableRun1Statics: Boolean = java.lang.Boolean.getBoolean("opentaint.bidi.disableRun1Statics"),
    val run1MarkMode: MarkMode = readRun1MarkMode(),
    val fieldLimitSchedule: FieldLimitSchedule = FieldLimitSchedule.REPEAT_RUN1,
    val normalTargets: NormalTargetView = NormalTargetView.EMPTY,
) {
    init {
        require(index >= 1) { "The run index must be positive" }
        require(fieldLimit == fieldLimitSchedule.fieldLimit(index)) {
            "Field limit $fieldLimit does not match $fieldLimitSchedule at run-$index"
        }
        require((index == 1) == (demand == null)) { "Only run 1 has no demand snapshot" }
        demand?.validateIncoming(index)
    }

    /** DIAGNOSTIC ONLY: this unsound ablation can miss flows through static fields.
     * Exact global class markers are kept. The setting has no effect after run 1. */
    val disableRun1Statics: Boolean = index == 1 && disableRun1Statics

    val records: RecordStore = records.view()
    val roots: List<MethodKey> = Collections.unmodifiableList(ArrayList(roots))
    val direction: Direction get() = if (index % 2 == 1) Direction.FORWARD else Direction.BACKWARD
    val run1: Boolean get() = index == 1
    val restricted: Boolean get() = index > 1
    val mode: ApMode = ApMode(run1, direction, fieldLimit,
        markMode = if (run1) run1MarkMode else MarkMode.FULL)
    val admissionPolicy: RestrictedInitialPolicy = demand?.admissionPolicy(index, fieldLimit, direction) ?: RestrictedInitialPolicy()
    val seededSources: Boolean get() = restricted && direction == Direction.FORWARD
}

/** The driver captures this value once and passes it to every run configuration. */
internal fun readRun1MarkMode(value: String? = System.getProperty("opentaint.bidi.run1MarkMode")): MarkMode =
    when (value) {
        null, "FULL" -> MarkMode.FULL
        "GROUP" -> MarkMode.GROUP
        else -> error("Invalid opentaint.bidi.run1MarkMode=$value; use GROUP or FULL")
    }

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.Facts
import org.opentaint.dataflow.bidi.ap.AdmittedInitial
import org.opentaint.dataflow.bidi.ap.Layer
import org.opentaint.dataflow.bidi.ap.MethodKey
import org.opentaint.dataflow.bidi.store.CallerRef
import org.opentaint.dataflow.bidi.store.BlockScope
import java.util.Collections

sealed interface RunEvent {
    data class Start(val root: MethodKey) : RunEvent
    data class LinkIn(val callee: MethodKey, val ref: CallerRef, val linkLayer: Layer, val added: Facts) : RunEvent
    /** Restricted callers have already completed demand lookup and initial emission. */
    class InitialsIn(val callee: MethodKey, initials: Collection<AdmittedInitial>) : RunEvent {
        val initials: List<AdmittedInitial> = Collections.unmodifiableList(ArrayList(initials))
        init { require(this.initials.isNotEmpty()) }
    }
    data class StaticOwner(val effect: StaticOwnerEffect) : RunEvent

    /** A detached immutable batch addressed to the method's actual block entry. */
    data class MarkRequestsIn(val method: MethodKey, val rows: RequestRows,
                              val scope: BlockScope = BlockScope.ROOT) : RunEvent

    /** Only a subscribed caller runner handles this event; the publisher reads no caller directory. */
    data class ChangedRequests(val callee: MethodKey, val rows: RequestRows) : RunEvent

    /** Answers own only initial keys and layers, never supplier Facts or caller bindings. */
    class InitialAnswersIn(val method: MethodKey, answers: Collection<AdmittedInitial>) : RunEvent {
        val answers: List<AdmittedInitial> = Collections.unmodifiableList(ArrayList(answers))
    }

    /** The publisher can clear its pending list as soon as this event is sent. */
    class Delivery(val callee: MethodKey, publications: List<Publication>) : RunEvent {
        val publications: List<Publication> = Collections.unmodifiableList(ArrayList(publications))
    }

    class TargetDelivery(val callee: MethodKey, rows: TargetBatch) : RunEvent {
        val rows: TargetBatch = Collections.unmodifiableList(ArrayList(rows))
    }

    class Work(val analyzer: RunActor) : RunEvent
}

fun RunEvent.target(): MethodKey = when (this) {
    is RunEvent.Start -> root
    is RunEvent.LinkIn -> callee
    is RunEvent.InitialsIn -> callee
    is RunEvent.StaticOwner -> effect.owner
    is RunEvent.MarkRequestsIn -> method
    is RunEvent.InitialAnswersIn -> method
    is RunEvent.Delivery, is RunEvent.TargetDelivery, is RunEvent.ChangedRequests, is RunEvent.Work ->
        error("Delivery and Work require their owning runner")
}

