import kotlinx.coroutines.CompletableDeferred
import kotlinx.coroutines.CoroutineExceptionHandler
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.CoroutineStart
import kotlinx.coroutines.Job
import kotlinx.coroutines.NonCancellable
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.delay
import kotlinx.coroutines.isActive
import kotlinx.coroutines.joinAll
import kotlinx.coroutines.launch
import kotlinx.coroutines.runBlocking
import kotlinx.coroutines.withTimeoutOrNull
import mu.KLogging
import org.opentaint.dataflow.bidi.interp.DirectedForms
import org.opentaint.dataflow.bidi.interp.RuleView
import org.opentaint.dataflow.bidi.ap.MethodKey
import org.opentaint.dataflow.bidi.ap.MarkMode
import org.opentaint.dataflow.bidi.store.FrozenCompletion
import org.opentaint.dataflow.ifds.UnitType
import org.opentaint.dataflow.ifds.UnknownUnit
import org.opentaint.dataflow.util.MemoryManager
import java.util.concurrent.atomic.AtomicBoolean
import java.util.concurrent.atomic.AtomicReference
import java.util.concurrent.ConcurrentHashMap
import kotlin.time.Duration
import kotlin.time.Duration.Companion.seconds
import kotlin.time.TimeMark
import kotlin.time.TimeSource

/** Fresh routing, completion and coroutine ownership for exactly one run. */
class RunManager<A : RunActor>(
    val config: RunConfig,
    val shared: SharedObjects,
    private val factory: RunnerHandlerFactory<A>,
    val steps: ProtocolSteps = ProtocolSteps.Inline,
    private val quantum: Int = RUNNER_STEPS_QUANT,
) {
    init {
        require(quantum > 0) { "The runner quantum must be positive" }
        shared.cancellation.activate()
    }

    private val job = SupervisorJob()
    private val scope = CoroutineScope(shared.dispatcher + job)
    private val admission = Any()
    private val runners = LinkedHashMap<UnitType, UnitRunner<A>>()
    private val storages = ConcurrentHashMap<MethodKey, SummaryStorage>()
    private val runnerJobs = ArrayList<Job>()
    private val completion = CompletableDeferred<RunStatus>()
    private val status = AtomicReference<RunStatus?>(null)
    private val invoked = AtomicBoolean()
    /** Native lifecycle/failure control; production keeps this null. */
    internal var joinedPreparationObserver: ((JoinedPreparationPhase) -> Unit)? = null
    private class Deadline(private val start: TimeMark, private val timeout: Duration) {
        val remaining: Duration get() = timeout - start.elapsedNow()
    }
    @Volatile private var deadline: Deadline? = null
    @Volatile private var admitting = false
    val ended: Boolean get() = status.get() != null
    val terminalStatus: RunStatus? get() = status.get()
    val inFlight = InFlight {
        if (status.compareAndSet(null, RunStatus.COMPLETE)) completion.complete(RunStatus.COMPLETE)
    }
    val forms: DirectedForms = shared.contexts.directed(config.direction,
        if (config.mode.markMode == MarkMode.GROUP) RuleView.RUN1_GROUP else RuleView.FULL)
    val staticService: Run1StaticService? = if (config.run1) Run1StaticService(shared.ap, config.mode.markMode) else null
    private val memory = MemoryManager(shared.refManager, OOM_THRESHOLD) { fail(RunStatus.OOM) }

    /** All units in this run share one storage for the complete callee key. */
    fun summaryStorage(key: MethodKey): SummaryStorage = synchronized(admission) {
        check(!ended) { "The run has ended" }
        shared.cancellation.checkpoint()
        storages.computeIfAbsent(key) { SummaryStorage(it, shared.ap, shared.ops, steps,
            shared.abstractionStatistics, flowBacked = true) }
    }

    fun route(event: RunEvent): Boolean {
        if (!admitting || !withinDeadline()) return false
        val unit = shared.unitResolver.resolve(event.target().method)
        if (!withinDeadline() || unit == UnknownUnit) return false
        return synchronized(admission) {
            if (!admitting || !withinDeadline()) return@synchronized false
            val runner = runners[unit] ?: UnitRunner(unit, this, factory, quantum).also { r ->
                runners[unit] = r
                if (!withinDeadline()) return@synchronized false
                val exceptionHandler = CoroutineExceptionHandler { _, e ->
                    logger.error(e) { "Runner $unit failed in run ${config.index}" }
                    fail(RunStatus.FAILED)
                }
                val runnerJob = scope.launch(exceptionHandler, start = CoroutineStart.LAZY) { r.runLoop() }
                runnerJobs += runnerJob
                runnerJob.start()
            }
            if (!withinDeadline()) return@synchronized false
            runner.postEvent(event)
        }
    }

    /** The reservation and its visibility are one admission transition. */
    internal fun accept(send: () -> Boolean): Boolean = synchronized(admission) {
        if (!admitting || !withinDeadline()) return@synchronized false
        inFlight.beforeSend()
        val accepted = try { send() }
        catch (e: Throwable) {
            fail(RunStatus.FAILED)
            inFlight.rejectedSend()
            throw e
        }
        if (!accepted) inFlight.rejectedSend()
        accepted
    }

    internal fun afterHandler() = synchronized(admission) {
        withinDeadline()
        inFlight.afterHandler()
    }

    /** Routing and setup consume the same budget as the completion wait. */
    private fun withinDeadline(): Boolean {
        if (!ended && deadline?.remaining?.let { it <= Duration.ZERO } == true) fail(RunStatus.TIMEOUT)
        return !ended
    }

    /** Selection precedes cancellation; a later failure preserves the first terminal status. */
    fun fail(end: RunStatus) {
        require(end != RunStatus.COMPLETE) { "Only quiescence selects COMPLETE" }
        if (!status.compareAndSet(null, end)) return
        shared.cancellation.cancel()
        completion.complete(end)
    }

    fun run(timeout: Duration): RunResult<A> {
        check(invoked.compareAndSet(false, true)) { "A run manager can run only once" }
        logger.info { "BIDI_MARK_MODE run=${config.index} mode=${config.mode.markMode} configuredRun1Mode=${config.run1MarkMode}" }
        if (config.run1) logger.info {
            "Run 1: DIAGNOSTIC opentaint.bidi.disableRun1Statics=${config.disableRun1Statics}; " +
                "true disables static FIELD flows and can miss findings; exact global markers are kept"
        }
        deadline = Deadline(TimeSource.Monotonic.markNow(), timeout)
        var joinAttempted = false
        var joined = false
        fun joinRunners() {
            joinAttempted = true
            joined = try { runBlocking(NonCancellable) { stopAndJoin() } }
            catch (e: Throwable) {
                logger.error(e) { "Run ${config.index}: runner join failed" }
                false
            }
        }
        try {
            memory.runWithMemoryManager {
                try {
                    runBlocking {
                        val progress = launch {
                            var last = 0L
                            while (isActive) {
                                delay(PROGRESS_PERIOD)
                                last = logProgress(last)
                            }
                        }
                        try {
                            startRoots()
                            if (withinDeadline()) {
                                withTimeoutOrNull(checkNotNull(deadline).remaining) { completion.await() }
                                    ?: fail(RunStatus.TIMEOUT)
                            }
                        } finally { progress.cancel() }
                    }
                } catch (e: Throwable) {
                    logger.error(e) { "Run ${config.index}: caller failed" }
                    fail(RunStatus.FAILED)
                } finally { joinRunners() }
            }
        } catch (e: Throwable) {
            logger.error(e) { "Run ${config.index}: memory guard or caller failed" }
            fail(RunStatus.FAILED)
        } finally {
            if (!joinAttempted) joinRunners()
        }

        if (!joined) {
            // A failed join cannot export any runner-owned state.
            status.set(RunStatus.FAILED)
            shared.cancellation.cancel()
            completion.complete(RunStatus.FAILED)
        }
        val snapshot = synchronized(admission) { runners.values.toList() }
        val joinedActors = if (joined) snapshot.flatMap { it.analyzers() } else emptyList()
        var staticCompletion: FrozenCompletion? = null
        var joinedStaticBindingTime = Duration.ZERO
        var joinedSealReleaseTime = Duration.ZERO
        val methods = joinedActors.filterIsInstance<RunMethodAnalyzer>()
        val realMethods = methods.size == joinedActors.size
        var preparationStarted = false
        val lease = JoinedBindingLease()
        val releasedRunners = java.util.Collections.newSetFromMap(java.util.IdentityHashMap<UnitRunner<A>, Boolean>())
        var failure: Throwable? = null
        var preparationError: Throwable? = null
        fun release(action: () -> Unit) {
            try { action() } catch (error: Throwable) {
                val first = failure ?: preparationError
                if (first == null) failure = error else if (error !== first) first.addSuppressed(error)
            }
        }
        fun releaseRunner(runner: UnitRunner<A>) {
            if (releasedRunners.add(runner)) runner.release()
        }
        fun prepareJoined(checkpoint: () -> Unit): JoinedStaticGuidance? {
            var sources: List<JoinedStaticSource> = emptyList()
            var primary: Throwable? = null
            try {
                if (realMethods) {
                    preparationStarted = true
                    val sealStarted = TimeSource.Monotonic.markNow()
                    try {
                        check(inFlight.pending == 0L && !admitting) { "Joined preparation needs complete callback quiescence" }
                        for (method in methods) { checkpoint(); method.captureJoinedExports() }
                        joinedPreparationObserver?.invoke(JoinedPreparationPhase.CAPTURED)
                        if (config.run1) {
                            sources = methods.flatMap { checkpoint(); it.detachJoinedStaticSources() }
                            for (method in methods) { checkpoint(); lease.addLocal(method.key, method.detachJoinedLocalInputs()) }
                            for (storage in storages.values) { checkpoint(); lease.addCallers(storage) }
                        }
                        joinedPreparationObserver?.invoke(JoinedPreparationPhase.SEALED)
                        for (method in methods) {
                            checkpoint()
                            release { method.freeze() }
                        }
                        failure?.let { throw it }
                        for (runner in snapshot) release { releaseRunner(runner) }
                        failure?.let { throw it }
                        synchronized(admission) { runners.clear(); runnerJobs.clear(); storages.clear() }
                        joinedPreparationObserver?.invoke(JoinedPreparationPhase.RELEASED)
                    } finally { joinedSealReleaseTime += sealStarted.elapsedNow() }
                }
                if (!config.run1) return null
                checkpoint()
                joinedPreparationObserver?.invoke(JoinedPreparationPhase.BEFORE_BIND)
                val bindStarted = TimeSource.Monotonic.markNow()
                val result = try {
                    if (realMethods) completeJoinedStaticGuidance(config, shared, sources, lease, checkpoint)
                    else completeJoinedStaticGuidance(config, shared, methods, storage = { storages[it] }, checkpoint = checkpoint)
                } finally { joinedStaticBindingTime += bindStarted.elapsedNow() }
                checkpoint()
                joinedPreparationObserver?.invoke(JoinedPreparationPhase.BOUND)
                return result
            } catch (error: Throwable) {
                primary = error
                throw error
            } finally {
                val closeStarted = TimeSource.Monotonic.markNow()
                var cleanup: Throwable? = null
                fun close(action: () -> Unit) {
                    try { action() } catch (error: Throwable) {
                        val first = primary ?: cleanup
                        if (first == null) cleanup = error else if (first !== error) first.addSuppressed(error)
                    }
                }
                close { lease.close() }
                sources = emptyList() // Drop reader references, never shared native stores or keys.
                joinedSealReleaseTime += closeStarted.elapsedNow()
                if (realMethods) close { joinedPreparationObserver?.invoke(JoinedPreparationPhase.CLOSED) }
                if (primary == null) cleanup?.let { throw it }
            }
        }
        if (joined && status.get() == RunStatus.COMPLETE) {
            val resourceGate = Any()
            var resourceActive = true
            var guidance: JoinedStaticGuidance? = null
            fun rejectPreparation(reason: RunStatus) = synchronized(resourceGate) {
                check(reason != RunStatus.COMPLETE)
                if (resourceActive && status.compareAndSet(RunStatus.COMPLETE, reason)) shared.cancellation.cancel()
            }
            fun checkpoint() {
                if (checkNotNull(deadline).remaining <= Duration.ZERO) rejectPreparation(RunStatus.TIMEOUT)
                shared.cancellation.checkpoint()
            }
            try {
                if (config.run1) {
                    // Preserve the existing joined resource gate around the entire new lifetime phase.
                    withJoinedDeadline(remaining = { checkNotNull(deadline).remaining },
                        onTimeout = { rejectPreparation(RunStatus.TIMEOUT) }) {
                        MemoryManager(shared.refManager, OOM_THRESHOLD) { rejectPreparation(RunStatus.OOM) }
                            .runWithMemoryManager { checkpoint(); guidance = prepareJoined(::checkpoint); checkpoint() }
                    }
                } else {
                    // Later runs keep their old post-join guard coverage.
                    guidance = prepareJoined(shared.cancellation::checkpoint)
                }
            } catch (error: Throwable) {
                preparationError = error
                rejectPreparation(if (error is OutOfMemoryError) RunStatus.OOM else RunStatus.FAILED)
                logger.error(error) { "Run ${config.index}: joined preparation failed" }
            } finally { synchronized(resourceGate) { resourceActive = false } }
            if (status.get() == RunStatus.COMPLETE) staticCompletion = guidance?.completion
            if (config.run1) logger.info {
                "BIDI_STATIC_WRITER_BIND run=${config.index} bindingTime=$joinedStaticBindingTime status=${status.get()} " +
                    "observedCandidates=${guidance?.observedCandidates ?: 0} lostCandidates=${guidance?.lostCandidates ?: 0} " +
                    "peakCandidateMemberships=${guidance?.peakCandidates ?: 0} " +
                    "pruneTime=${guidance?.pruneTime ?: Duration.ZERO} writerTime=${guidance?.writerTime ?: Duration.ZERO} " +
                    "closureFreezeTime=${guidance?.closureFreezeTime ?: Duration.ZERO} ${guidance?.binding ?: "no-completed-binding"}"
            }
        }
        val end = checkNotNull(status.get())
        val analyzers = if (end == RunStatus.COMPLETE) joinedActors else emptyList()
        if (joined && end != RunStatus.COMPLETE && shared.n2Statistics != null) {
            // Failed runs export no actors. Read only stopped-owner diagnostics,
            // while the joined actors still exist, before releasing their runners.
            val measured = joinedActors.filterIsInstance<RunMethodAnalyzer>()
            logger.info {
                "BIDI_BODY_WORK_ABORTED run=${config.index} status=$end scope=joined-packet-events " +
                    "actors=${measured.size} steps=${measured.sumOf { it.steps }} " +
                    "candidateOffers=${measured.sumOf { it.diagnosticCandidateOffers }}"
            }
            // Copy bounded samples for the hot owners only, especially after an OOM.
            val hot = (measured.sortedByDescending { it.steps }.take(12) +
                measured.sortedByDescending { it.diagnosticCandidateOffers }.take(12)).distinctBy { it.key }
            for (actor in hot) logger.info {
                "BIDI_BODY_WORK_ABORTED_METHOD run=${config.index} status=$end method=${actor.key} snapshot=${actor.stoppedBodyWorkSnapshot()}"
            }
            for (actor in hot) actor.blockDiagnostics()?.let { summary -> logger.info {
                "BIDI_LOOP_BLOCK_ABORTED run=${config.index} status=$end method=${actor.key} $summary"
            } }
        }
        staticService?.let { logger.info { "BIDI_STATIC_STATISTICS run=${config.index} status=$end totals=${it.statistics()} requests=${it.requestStatistics()}" } }
        try {
            for (analyzer in analyzers) release { analyzer.freeze() }
            if (preparationStarted && end != RunStatus.COMPLETE)
                for (method in methods) release { method.freeze() }
        } finally {
            release { lease.close() }
            if (joined) for (runner in snapshot) release { releaseRunner(runner) }
            // A complete run's frozen state is still needed by the driver barrier.
            if (joined && config.run1 && end != RunStatus.COMPLETE) shared.releaseRun1CatalogCoverage()
            synchronized(admission) {
                runners.clear()
                runnerJobs.clear()
                if (joined) { storages.values.forEach { it.releaseStopped() }; storages.clear() }
            }
            if (joined) staticService?.clear()
        }
        failure?.let { throw it }
        return RunResult(end, analyzers, config.index, config.direction, config.mode.markMode,
            joinedStaticBindingTime, staticCompletion, joinedSealReleaseTime)
    }

    private fun startRoots() {
        val reserved = synchronized(admission) {
            if (!withinDeadline()) false
            else {
                inFlight.beforeSend()
                admitting = true
                true
            }
        }
        if (!reserved) return
        try {
            for (root in config.roots) {
                if (!withinDeadline()) break
                route(RunEvent.Start(root))
            }
        } catch (e: Throwable) {
            fail(RunStatus.FAILED)
            throw e
        } finally { afterHandler() }
    }

    private suspend fun stopAndJoin(): Boolean {
        val (snapshot, jobs) = synchronized(admission) {
            admitting = false
            runners.values.toList() to runnerJobs.toList()
        }
        snapshot.forEach { it.close() }
        job.cancel()
        return withTimeoutOrNull(shared.cancellationTimeout) { jobs.joinAll(); true } ?: false
    }

    private fun logProgress(last: Long): Long {
        val handled = inFlight.handled
        logger.info { "Run ${config.index}: $handled events (+${handled - last}), ${inFlight.pending} in flight" }
        logger.info { "Memory usage: ${MemoryManager.currentMemoryUsage()}/${Runtime.getRuntime().maxMemory()}" }
        return handled
    }

    companion object : KLogging() {
        const val RUNNER_STEPS_QUANT = 1000
        const val OOM_THRESHOLD = 0.90
        val PROGRESS_PERIOD = 10.seconds
    }
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.driver.ScopedTargetRows
import org.opentaint.dataflow.bidi.store.ScopedRunSummary
import org.opentaint.dataflow.bidi.store.OwnedScope
import org.opentaint.dataflow.bidi.store.BlockScope
import org.opentaint.dataflow.bidi.store.Record
import org.opentaint.dataflow.bidi.store.NormalRuleContributorRow

/** The only scheduled actor for an original method. Block state is owned here. */
class RunMethodAnalyzer(
    key: MethodKey,
    port: RunnerPort<RunMethodAnalyzer>,
    publisher: PublicationSink,
    localFactory: MethodLocalServicesFactory,
    callFactory: MethodCallServicesFactory,
    targetPublisher: TargetPublicationSink,
) : BlockRunState(key, port, publisher, localFactory, callFactory, targetPublisher), RunActor {
    internal var blockRuntime: MethodBlockRuntime? = null
        private set
    private val staticTicketScopes = HashMap<Long, BlockScope>()
    private var localStaticRequests = if (!config.run1) null else LocalStaticInputRequests(ops, mode, key,
        ticket = ::nextStaticTicket,
        interest = { staticBatch.interests += it; requestWork() },
        resume = { link, original, value ->
            checkNotNull(blockRuntime).offerStaticAnswer(link, original as InitialAp, value)
        })
    private var scopedSummaries: List<ScopedRunSummary> = emptyList()
    private var scopedTargets: List<ScopedTargetRows> = emptyList()
    private var scopedOutgoingTargets: List<ScopedTargetRows> = emptyList()
    private var childNormalContributorRows: List<NormalRuleContributorRow> = emptyList()
    private var frozenChildCounters = LongArray(10)
    private var capturedChildCounters = LongArray(10)
    private var joinedMethodCaptured = false
    private var frozenBlockDiagnostics: String? = null
    internal fun blockDiagnostics(): String? = blockRuntime?.diagnosticStatistics() ?: frozenBlockDiagnostics

    init {
        if (port.shared.contexts.blockLayout(key).hasLoops) {
            val runtime = MethodBlockRuntime(this, port, localFactory, callFactory)
            blockRuntime = runtime
            rootRouting = runtime
        }
    }

    private fun children(): Sequence<BlockRunState> = blockRuntime?.states()?.asSequence()
        ?.map { it.second }?.filter { it !== this } ?: emptySequence()
    private fun childCount(slot: Int, count: (BlockRunState) -> Long): Long =
        frozenChildCounters[slot] + children().sumOf(count)

    override val steps get() = super.steps + childCount(0) { it.steps }
    override val edgeDeltas get() = super.edgeDeltas + childCount(1) { it.edgeDeltas }
    override val demandLayerEdges get() = super.demandLayerEdges + childCount(2) { it.demandLayerEdges }
    override val recordCrossings get() = super.recordCrossings + childCount(3) { it.recordCrossings }
    override val triggerSeeds get() = super.triggerSeeds + childCount(4) { it.triggerSeeds }
    override val neutralBatchApplications get() = super.neutralBatchApplications + childCount(5) { it.neutralBatchApplications }
    override val neutralBatchMemberships get() = super.neutralBatchMemberships + childCount(6) { it.neutralBatchMemberships }
    override val neutralBulkStorePackets get() = super.neutralBulkStorePackets + childCount(7) { it.neutralBulkStorePackets }
    override val neutralBulkStoreMemberships get() = super.neutralBulkStoreMemberships + childCount(8) { it.neutralBulkStoreMemberships }
    override val neutralScalarFallbackMemberships get() = super.neutralScalarFallbackMemberships + childCount(9) { it.neutralScalarFallbackMemberships }
    override val hasZeroWork get() = super.hasZeroWork || children().any { it.localHasZeroWork }

    internal fun blockSummaries(): Sequence<ScopedRunSummary> = scopedSummaries.asSequence()
    internal fun blockTargets(): Sequence<ScopedTargetRows> = scopedTargets.asSequence()
    internal fun blockOutgoingTargets(): Sequence<ScopedTargetRows> = scopedOutgoingTargets.asSequence()
    internal fun normalContributorRows(): Sequence<NormalRuleContributorRow> =
        frozenNormalContributorRows.asSequence() + childNormalContributorRows.asSequence()
    internal fun joinedBlockStates(): List<Pair<BlockScope, BlockRunState>> =
        blockRuntime?.states() ?: listOf(BlockScope.ROOT to this)
    internal fun forEachJoinedLocalInput(scope: BlockScope, visit: (LocalLink, Facts) -> Unit) {
        blockRuntime?.forEachLocalInput(scope, visit)
    }

    internal fun detachJoinedLocalInputs(): Map<BlockScope, JoinedLocalInputs> =
        blockRuntime?.detachJoinedLocalInputs().orEmpty()

    internal fun detachJoinedStaticSources(): List<JoinedStaticSource> =
        joinedBlockStates().map { (scope, state) -> state.joinedStaticSource(OwnedScope(key, scope)) }

    internal fun allocateStaticTicket(scope: BlockScope): Long = nextStaticTicket().also {
        check(staticTicketScopes.put(it, scope) == null)
    }

    internal fun requestLocalStaticInput(link: LocalLink, input: Facts, mark: TaintMark) {
        checkNotNull(localStaticRequests).request(link, input as FlowTree, mark)
    }

    override fun requestWork() {
        blockRuntime?.scheduleRoot()
        super.requestWork()
    }

    override fun work(quantum: Int): Boolean = blockRuntime?.work(quantum) ?: super.work(quantum)

    override fun releaseAbstraction() {
        for (state in children()) state.releaseAbstraction()
        super.releaseAbstraction()
    }

    private fun waiting(scope: BlockScope): BlockRunState =
        if (scope == BlockScope.ROOT) this else checkNotNull(blockRuntime).state(scope)

    internal fun addScopedMarkRequests(scope: BlockScope, rows: RequestRows) {
        waiting(scope).addMarkRequests(rows)
    }

    override fun applySummary(part: Subscription, pub: Publication, member: Int) {
        if (part.ref.scope == BlockScope.ROOT) super.applySummary(part, pub, member)
        else waiting(part.ref.scope).applySummary(part, pub, member)
    }
    override fun applyStaticSummary(part: Subscription, pub: Publication, member: Int) {
        if (part.ref.scope == BlockScope.ROOT) super.applyStaticSummary(part, pub, member)
        else waiting(part.ref.scope).applyStaticSummary(part, pub, member)
    }
    override fun applyTarget(part: Subscription, row: TargetSummary, member: Int) {
        if (part.ref.scope == BlockScope.ROOT) super.applyTarget(part, row, member)
        else waiting(part.ref.scope).applyTarget(part, row, member)
    }
    override fun applyStaticTarget(part: Subscription, row: TargetSummary, member: Int) {
        if (part.ref.scope == BlockScope.ROOT) super.applyStaticTarget(part, row, member)
        else waiting(part.ref.scope).applyStaticTarget(part, row, member)
    }
    override fun requestStaticGroups(part: Subscription, marks: org.opentaint.dataflow.bidi.store.RequestMarkSelection) {
        if (part.ref.scope == BlockScope.ROOT) super.requestStaticGroups(part, marks)
        else waiting(part.ref.scope).requestStaticGroups(part, marks)
    }
    override fun applyRecord(part: Subscription, record: Record) {
        if (part.ref.scope == BlockScope.ROOT) super.applyRecord(part, record)
        else waiting(part.ref.scope).applyRecord(part, record)
    }
    override fun applyRecordView(part: Subscription, view: RecordLeafView, nonSubsumable: Boolean) {
        if (part.ref.scope == BlockScope.ROOT) super.applyRecordView(part, view, nonSubsumable)
        else waiting(part.ref.scope).applyRecordView(part, view, nonSubsumable)
    }

    override fun onStaticEffect(effect: StaticOwnerEffect) {
        if (localStaticRequests?.answer(effect) == true) return
        val ticket = when (effect) {
            is StaticOwnerEffect.ReadReady -> effect.id
            is StaticOwnerEffect.PointReady -> effect.id
            is StaticOwnerEffect.WriterInterest -> effect.id
        }
        val scope = staticTicketScopes[ticket]
        if (scope == null) super.onStaticEffect(effect)
        else checkNotNull(blockRuntime).state(scope).onStaticEffect(effect)
    }

    internal override fun captureJoinedExports() {
        if (joinedMethodCaptured) return
        check(!hasLocalWork) { "A method cannot capture unfinished root work" }
        val runtime = blockRuntime
        runtime?.requireIdle()
        joinedMethodCaptured = true // Failed capture cannot be retried during best-effort release.
        val closedChildren = children().toList()
        val completionStatistics = runtime?.completionScalarStatistics()?.toList().orEmpty()
        super.captureJoinedExports()
        for (child in closedChildren) child.captureJoinedExports()
        if (runtime != null) {
            if (context.shared.n2Statistics != null) frozenBlockDiagnostics = runtime.diagnosticStatistics()
            scopedSummaries = runtime.scopedSummaries().toList()
            scopedTargets = runtime.scopedTargets().toList()
            scopedOutgoingTargets = runtime.scopedOutgoingTargets().toList()
            capturedChildCounters = longArrayOf(closedChildren.sumOf { it.steps }, closedChildren.sumOf { it.edgeDeltas },
                closedChildren.sumOf { it.demandLayerEdges }, closedChildren.sumOf { it.recordCrossings },
                closedChildren.sumOf { it.triggerSeeds }, closedChildren.sumOf { it.neutralBatchApplications },
                closedChildren.sumOf { it.neutralBatchMemberships }, closedChildren.sumOf { it.neutralBulkStorePackets },
                closedChildren.sumOf { it.neutralBulkStoreMemberships }, closedChildren.sumOf { it.neutralScalarFallbackMemberships })
        }
        childNormalContributorRows = closedChildren.flatMap { it.frozenNormalContributorRows }
        includeClosedBlockMeasurements(closedChildren, completionStatistics)
    }

    override fun freeze() {
        if (executionReleased) return
        check(!hasLocalWork) { "A method cannot freeze with unfinished root work" }
        blockRuntime?.requireIdle()
        var failure: Throwable? = null
        try { captureJoinedExports() } catch (error: Throwable) { failure = error }
        try { blockRuntime?.freezeChildren() } catch (error: Throwable) {
            if (failure == null) failure = error else if (failure !== error) failure.addSuppressed(error)
        }
        finally {
            blockRuntime = null
            frozenChildCounters = capturedChildCounters
            localStaticRequests?.clear()
            localStaticRequests = null
            staticTicketScopes.clear()
            try { super.freeze() } catch (error: Throwable) {
                if (failure == null) failure = error else if (failure !== error) failure.addSuppressed(error)
            }
        }
        failure?.let { throw it }
    }
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.interp.*
import org.opentaint.dataflow.bidi.store.AddedFactAccumulator
import org.opentaint.dataflow.bidi.store.BlockScope
import org.opentaint.dataflow.bidi.store.CallerRef
import org.opentaint.dataflow.bidi.store.ConjunctionStore
import org.opentaint.dataflow.bidi.store.NdBinding
import org.opentaint.dataflow.bidi.store.KaryJoin
import org.opentaint.dataflow.bidi.store.Record
import org.opentaint.ir.api.common.cfg.CommonCallExpr
import org.opentaint.ir.api.common.cfg.CommonInst
import java.util.ArrayDeque

/** Call walks and suspended return batches belong to one method actor. */
class RunMethodCallServices(core: BlockRunState) : MethodCallServices {
    private var owner: BlockRunState? = core
    // Keep semantic unresolved observations once per qualified current input.
    private var observed: AddedFactAccumulator? = if (core.config.run1) AddedFactAccumulator(core.ap) else null

    private fun active(): BlockRunState = checkNotNull(owner) { "The call services were released" }.also {
        it.ap.cancellation.checkpoint()
    }

    private data class PlanFact(val premise: PremiseKey, val facts: Facts, val identityCandidate: Boolean?)
    private fun planFact(premise: PremiseKey, facts: Facts, identity: Boolean?) =
        PlanFact(premise, facts, identity)
    /** One cleaner step owns this collection. Ordinary identity stays unchanged;
     * equal results must OR their annotation before the next step sees them. */
    private class PlanFacts(private val ap: ApManager) : AbstractMutableCollection<PlanFact>() {
        private val values = LinkedHashMap<PlanFact, PlanFact>()
        override val size: Int get() = values.size
        override fun iterator(): MutableIterator<PlanFact> = values.values.iterator()
        override fun add(element: PlanFact): Boolean {
            if (!RuntimeDataDomain.packet(element.premise, element.facts)) return false
            val old = values[element]
            if (old == null) {
                values[element] = element
                return true
            }
            val (merged, delta) = ap.mergeAddDelta(old.facts, element.facts)
            if (delta == null) return false
            values[element] = element.copy(facts = merged)
            return true
        }
    }
    private class CallContext(val node: CommonInst, val call: CommonCallExpr, val plan: CallPlan, val callerLayer: Layer)
    private class Frame(val point: CallPoint, val facts: List<PlanFact>, val pendingDemotion: Boolean) {
        var entered = false
        var next = 0
        var triggers = Triggers.NONE
    }
    private val CallPlan.callees: CallStage.Callees?
        get() = stages.firstNotNullOfOrNull { it as? CallStage.Callees }

    override fun process(item: EdgeDelta) {
        val core = active()
        if (!RuntimeDataDomain.packet(item.premise, item.facts)) return
        val call = checkNotNull(core.context.callAt(item.node)) { "The delta is not at a call" }
        core.forms.withCall(core.key, item.node, call) { plan ->
            val ctx = CallContext(item.node, call, plan, item.facts.layer)
            when {
                item.facts is Reach -> zeroAtCall(item, ctx)
                item.facts.base !in ctx.plan.touched -> core.emitUnchanged(item)
                else -> flow(ctx, ctx.plan.entry, listOf(planFact(item.premise, item.facts, null)))
            }
        }
    }

    /** An explicit frame stack preserves stage order and keeps pending demotion local to this invocation. */
    private fun flow(ctx: CallContext, point: CallPoint, facts: List<PlanFact>, pendingDemotion: Boolean = false) {
        val core = active()
        check(!pendingDemotion || core.forward) { "Native must-record demotion is only forward" }
        val valid = facts.filter { RuntimeDataDomain.packet(it.premise, it.facts) }
        if (valid.isEmpty()) return
        val stack = ArrayDeque<Frame>()
        stack.addLast(Frame(point, valid, pendingDemotion))
        while (stack.isNotEmpty()) {
            core.ap.cancellation.checkpoint()
            val frame = stack.peekLast()
            if (!frame.entered) {
                frame.entered = true
                if (frame.point == ctx.plan.exit) {
                    for (fact in frame.facts) {
                        core.ap.cancellation.checkpoint()
                        val result = if (frame.pendingDemotion) toDemand(fact.facts) else fact.facts
                        core.cut(Cut.CALL, fact.premise, result) { premise, cut -> core.emitAfter(premise, ctx.node, cut) }
                    }
                    stack.removeLast()
                    continue
                }
                if (core.forward && frame.point == CallPoint.BOUND) {
                    for (fact in frame.facts) {
                        core.ap.cancellation.checkpoint()
                        val ordinal = ctx.plan.stages.indexOfFirst { it.from == frame.point }.coerceAtLeast(0)
                        frame.triggers += core.localServices.checkSinksAt(fact.premise, ctx.node, fact.facts, ctx.plan.sinks,
                            OperationInput(ResumeSite.CallStageInput(core.operation(ctx.node, ordinal)), fact.premise, fact.facts,
                                CallResumeState(ctx.callerLayer, fact.identityCandidate, frame.pendingDemotion)))
                    }
                }
                if (core.config.run1 && frame.point == CallPoint.ADDED) observeUnresolved(ctx, frame.facts)
            }
            val stages = ctx.plan.stagesAt(frame.point)
            if (frame.next >= stages.size) { stack.removeLast(); continue }
            val stage = stages[frame.next++]
            val out = applyStage(ctx, stage, frame.facts, frame.triggers, frame.pendingDemotion)
            if (out.isNotEmpty()) stack.addLast(Frame(stage.to, out, frame.pendingDemotion))
        }
    }

    private fun applyStage(ctx: CallContext, stage: CallStage, facts: List<PlanFact>, triggers: Triggers,
                           pendingDemotion: Boolean = false): List<PlanFact> {
        val core = active()
        val out = ArrayList<PlanFact>()
        val ordinal = ctx.plan.stages.indexOf(stage)
        when (stage) {
            is CallStage.Edges -> {
                if (stage.kind == StageKind.END_FACTS) return emptyList() // ignored in every run
                val guard = if (core.forward) stage.guard else null
                if (guard is Guard.SinkTriggered) {
                    for ((sink, layer) in triggers.fired) {
                        core.ap.cancellation.checkpoint()
                        if (sink.joinKey != guard.sink.joinKey) continue
                        core.applier.stage(stage.summary, core.ap.zero, Reach.of(layer),
                            Place(ctx.node, statementEdge = false, sources = false)) { premise, result, edge ->
                            core.ap.cancellation.checkpoint()
                            out += planFact(premise, result, stage.kind.identityCandidateOf(edge, null))
                        }
                    }
                } else {
                    for (fact in facts) {
                        core.ap.cancellation.checkpoint()
                        if (guard == Guard.MemoryEffect && !Guard.MemoryEffect.admits(
                                core.config.run1, fact.identityCandidate, fact.facts.layer)) continue
                        val input = fact.facts
                        val place = Place(ctx.node, core.config.run1 && stage.kind.statementEdges,
                            sources = stage.kind == StageKind.SOURCES,
                            site = ResumeSite.CallStageInput(core.operation(ctx.node, ordinal)),
                            callerLayer = ctx.callerLayer, identityCandidate = fact.identityCandidate, pendingDemotion = pendingDemotion)
                        core.applier.stage(stage.summary, fact.premise, input, place) { premise, result, edge ->
                            core.ap.cancellation.checkpoint()
                            out += planFact(premise, result, stage.kind.identityCandidateOf(edge, fact.identityCandidate))
                        }
                    }
                }
                if (stage.trigger != null && out.isNotEmpty()) {
                    core.localServices.fireTriggerSeeds(ctx.node, stage.trigger) { result ->
                        core.ap.cancellation.checkpoint()
                        out += planFact(core.ap.zero, result, null)
                    }
                }
            }
            is CallStage.Actions -> for (fact in facts) {
                core.ap.cancellation.checkpoint()
                cleanChain(stage, fact, ctx, ordinal, pendingDemotion = pendingDemotion) { out += it }
            }
            is CallStage.Callees -> for (fact in facts) {
                core.ap.cancellation.checkpoint()
                enterCallees(ctx, stage, fact)
            }
            is CallStage.Predefined -> for (fact in facts) {
                for (edge in stage.summary.edges) {
                    core.ap.cancellation.checkpoint()
                    if (!RuntimeDataDomain.packet(fact.premise, fact.facts) || !RuntimeDataDomain.producer(edge)) continue
                    core.ops.applyEdge(fact.facts, fact.premise, edge.edge, statementEdge = false,
                        mode = core.mode, out = object : ApOut {
                            override fun result(f: Facts) {
                                if (!RuntimeDataDomain.packet(fact.premise, f)) return
                                if (core.config.run1 && f.base == STATIC) core.routeStaticResultToExit(ctx.node, fact.premise, f)
                                else out += planFact(fact.premise, f, true)
                            }
                            override fun markRequest(mark: TaintMark): Nothing =
                                error("A predefined identity cannot request a mark")
                        }, ruleAssignment = false)
                }
            }
        }
        core.ap.cancellation.checkpoint()
        return out
    }

    private fun cleanChain(actions: CallStage.Actions, fact: PlanFact, ctx: CallContext, stageOrdinal: Int,
                           firstStep: Int = 0, firstPhase: CleanerPhase = CleanerPhase.INPUT,
                           pendingDemotion: Boolean = false, emit: (PlanFact) -> Unit) {
        val core = active()
        val steps = actions.steps
        val schedule = actions.returnGroupSchedule.takeIf {
            core.config.run1 && core.forward && core.mode.markMode == MarkMode.GROUP
        }
        check(schedule == null || schedule.size == steps.size)
        val fullSchedule = actions.returnFullCleanupSchedule.takeIf {
            core.config.run1 && core.forward && core.mode.markMode == MarkMode.FULL &&
                actions.from == CallPoint.RETURNED && actions.to == CallPoint.REWRITTEN
        }
        val node = ctx.node
        fun at(input: PlanFact, step: Int, phase: CleanerPhase) = OperationInput(
            ResumeSite.CleanerInput(core.operation(node, stageOrdinal), step, phase), input.premise, input.facts,
            CallResumeState(ctx.callerLayer, input.identityCandidate, pendingDemotion))
        fun statement(summary: StatementSummary, input: PlanFact, step: Int, phase: CleanerPhase): List<PlanFact> {
            val out = ArrayList<PlanFact>()
            val compiled = if (core.config.run1 && phase == CleanerPhase.READ && summary.staticOperations.isEmpty()) {
                val id = core.operation(node, stageOrdinal).copy(substep = step)
                val operations = summary.edges.filter { it.edge.from.base == STATIC && it.edge.to.base != STATIC }
                    .map { StaticOperation.Read(id, it.forward) }
                if (operations.isEmpty()) summary else summary.withStaticOperations(operations)
            } else if (core.config.run1 && phase == CleanerPhase.WRITE && summary.staticOperations.isEmpty()) {
                val id = core.operation(node, stageOrdinal).copy(substep = step)
                val operations = summary.edges.filter { it.edge.to.base == STATIC && it.edge.from.base != STATIC }
                    .map { StaticOperation.Write(id, Pattern(it.edge.to, ExclusionSet.Empty), it.forward) }
                if (operations.isEmpty()) summary else summary.withStaticOperations(operations)
            } else summary
            core.applier.statement(compiled, input.premise, input.facts,
                Place(node, core.config.run1, sources = false, site = at(input, step, phase).site,
                    callerLayer = ctx.callerLayer, identityCandidate = input.identityCandidate, pendingDemotion = pendingDemotion),
                sink = { premise, result ->
                    core.cut(Cut.STATEMENT, premise, result) { cutPremise, cut ->
                        core.ap.cancellation.checkpoint()
                        out += planFact(cutPremise, cut, input.identityCandidate)
                    }
                }, untouched = { premise, result -> out += planFact(premise, result, input.identityCandidate) })
            return out
        }
        var current = listOf(fact)
        var stepIndex = firstStep
        while (stepIndex < steps.size) {
            core.ap.cancellation.checkpoint()
            if (schedule != null && !schedule.execute(stepIndex, firstStep)) { stepIndex++; continue }
            val block = fullSchedule?.blockContaining(stepIndex)
            if (block != null) {
                val statistics = core.context.shared.n2Statistics
                if (current.all { fullCleanupCollectorFixed(it.premise, it.facts) }) {
                    val mask = block.marksFrom(stepIndex, core.ap.cancellation)
                    statistics?.fullCleanupBlock(stepIndex > block.first, block.end - stepIndex, current.size)
                    val next = PlanFacts(core.ap)
                    for (input in current) {
                        core.ap.cancellation.checkpoint()
                        val address = at(input, stepIndex, CleanerPhase.CLEAN)
                        core.ops.cleanSelectedFullMask(input.facts, input.premise, block.geometry, mask, core.mode,
                            request = { requested ->
                                statistics?.fullCleanupRequested(requested.size)
                                core.needGroups(address, requested)
                            }, out = core.collect(address) { premise, result ->
                                if (result.base == STATIC) core.routeStaticResultToExit(node, premise, result)
                                else next += planFact(premise, result, input.identityCandidate)
                            })
                        if (statistics != null && current.size == 1 && input.facts is FlowTree &&
                            input.facts.base == block.geometry.base) {
                            statistics.fullCleanupSingletonFlow(block.end - stepIndex)
                        }
                    }
                    current = next.toList()
                    stepIndex = block.end
                    continue
                }
                statistics?.fullCleanupFallback()
            }
            val step = steps[stepIndex]
            val phase = if (stepIndex == firstStep) firstPhase else CleanerPhase.INPUT
            // Finish every current-step effect before merging equal inputs to the next step.
            val next: MutableCollection<PlanFact> =
                if (core.config.run1) PlanFacts(core.ap) else ArrayList()
            for (input in current) {
                core.ap.cancellation.checkpoint()
                when (step) {
                    is CleanStep.Clean -> {
                        if (core.config.run1 && step.cleaner.base == STATIC && step.cleaner.mark != null && input.facts is Reach) {
                            val id = core.operation(node, stageOrdinal).copy(substep = stepIndex)
                            val pattern = Pattern(PathFact(STATIC, step.cleaner.pathArray.asList(),
                                if (step.cleaner.reach == CleanReach.EXACT) Tail.EXACT else Tail.ANY,
                                MarkSlot.Concrete(checkNotNull(step.cleaner.mark))), ExclusionSet.Empty)
                            core.reachedOperations(StatementSummary.EMPTY.withStaticOperations(listOf(StaticOperation.MarkInput(id, pattern, includeBase = step.cleaner.reach != CleanReach.BELOW))),
                                at(input, stepIndex, CleanerPhase.CLEAN))
                        }
                        core.ops.clean(input.facts, input.premise, step.cleaner, core.mode,
                        core.collect(at(input, stepIndex, CleanerPhase.CLEAN)) { premise, result ->
                            if (core.config.run1 && result.base == STATIC) {
                                core.routeStaticResultToExit(node, premise, result)
                            } else next += planFact(premise, result, input.identityCandidate)
                        })
                    }
                    is CleanStep.Kill -> core.applier.statement(step.keepEdges, input.premise, input.facts,
                        Place(node, core.config.run1, sources = false, site = at(input, stepIndex, CleanerPhase.INPUT).site,
                            callerLayer = ctx.callerLayer, identityCandidate = input.identityCandidate,
                            pendingDemotion = pendingDemotion),
                        sink = { premise, result -> next += planFact(premise, result, input.identityCandidate) })
                    is CleanStep.Field -> for (read in if (phase == CleanerPhase.CLEAN || phase == CleanerPhase.WRITE) listOf(input)
                            else statement(step.read, input, stepIndex, CleanerPhase.READ)) {
                        core.ap.cancellation.checkpoint()
                        val cleaned: ResultSink = { premise, result ->
                                for (written in statement(step.write, planFact(premise, result, read.identityCandidate), stepIndex, CleanerPhase.WRITE)) {
                                    core.ap.cancellation.checkpoint()
                                    if (written.facts.base != step.temporary) next += written
                                }
                            }
                        if (phase == CleanerPhase.WRITE) cleaned(read.premise, read.facts)
                        else core.ops.clean(read.facts, read.premise, step.cleaner, core.mode,
                            core.collect(at(read, stepIndex, CleanerPhase.CLEAN), cleaned))
                    }
                }
            }
            current = if (core.config.run1) next.toList() else next as ArrayList<PlanFact>
            stepIndex++
        }
        for (result in current) { core.ap.cancellation.checkpoint(); emit(result) }
    }

    private fun observeUnresolved(ctx: CallContext, facts: List<PlanFact>) {
        val core = active()
        val observer = core.context.shared.unresolvedObserver ?: return
        if (ctx.plan.stagesFrom[CallPoint.ADDED].orEmpty().none {
                it is CallStage.Edges && it.kind == StageKind.UNRESOLVED
            }) return
        val observed = checkNotNull(observed)
        for (fact in facts) {
            core.ap.cancellation.checkpoint()
            if (fact.facts !is TaintTree) continue
            val ref = CallerRef(core.key, fact.premise, ctx.callerLayer, ctx.node, scope = core.scope)
            if (observed.add(ref, fact.facts.layer, fact.facts) == null) continue
            observer.reached(ctx.call, fact.facts.base, ctx.plan)
            core.ap.cancellation.checkpoint()
        }
    }

    private fun enterCallees(ctx: CallContext, stage: CallStage.Callees, fact: PlanFact) {
        val core = active()
        val ref = CallerRef(core.key, fact.premise, ctx.callerLayer, ctx.node, ctx.plan.stages.indexOf(stage), core.scope)
        for (callee in stage.callees) {
            core.ap.cancellation.checkpoint()
            val part = Subscription(callee, ref, fact.facts.layer, fact.facts)
            if (!RuntimeDataDomain.packet(ref.premise, fact.facts)) continue
            check(part.added.base !is AccessPathBase.CleanerTemporary) {
                "A field-action temporary cannot enter an added link"
            }
            check(part.linkLayer == part.added.layer) { "The link layer must be the added fact's layer" }
            if (core.config.run1) {
                core.runnerPort.subscribe(part)
                core.ap.cancellation.checkpoint()
                core.runnerPort.link(callee, ref, part.linkLayer, part.added)
                continue
            }

            val statistics = core.context.shared.n2Statistics
            statistics?.selectedCallOffered()
            // Saved NORMAL records apply to every offer, without standing input admission.
            replayPersistedSummaries(core.config, core.ops, part, core, statistics)
            if (core.forward) for ((row, member) in core.config.normalTargets.candidates(callee, part, core.mode)) {
                core.ap.cancellation.checkpoint()
                if (!row.premise.isZero) applyTarget(part, row, member, saved = true)
            }
            // Demand admission uses the complete original offer, never a live merge delta.
            val initials = emitRestrictedInitials(core.config, core.ops, callee, part.added, statistics)
            if (initials.isEmpty()) continue

            // Register before a same-unit callee can publish. Current replay remains fresh-only.
            core.runnerPort.subscribe(part)
            core.ap.cancellation.checkpoint()
            // A duplicate live offer can still carry a complete initial packet.
            statistics?.initialPacketOffered(initials.size)
            core.runnerPort.startInitials(callee, initials)
        }
    }

    private fun zeroAtCall(item: EdgeDelta, ctx: CallContext) {
        val core = active()
        if (ctx.plan.zeroCanReturn) core.emitUnchanged(item)
        if (!item.premise.isZero) { check(!core.forward); return }
        if (core.forward) {
            flow(ctx, ctx.plan.entry, listOf(planFact(item.premise, item.facts, null)))
            return
        }
        val seeds = ArrayList<PlanFact>()
        core.localServices.fireSinkSeeds(item.node) { seeds += planFact(core.ap.zero, it, null) }
        if (seeds.isNotEmpty()) flow(ctx, CallPoint.BOUND, seeds)
        val ref = CallerRef(core.key, core.ap.zero, ctx.callerLayer, item.node,
            ctx.plan.stages.indexOfFirst { it is CallStage.Callees }.coerceAtLeast(0), core.scope)
        for (callee in ctx.plan.callees?.callees.orEmpty()) {
            core.ap.cancellation.checkpoint()
            val part = Subscription(callee, ref, item.facts.layer, item.facts, zeroOnly = true)
            val initials = emitRestrictedInitials(core.config, core.ops, callee, part.added)
            if (initials.isEmpty()) continue
            core.runnerPort.subscribe(part)
            core.ap.cancellation.checkpoint()
            core.runnerPort.startInitials(callee, initials)
        }
        for (stage in ctx.plan.stages.filterIsInstance<CallStage.Predefined>()) {
            val results = applyStage(ctx, stage, listOf(planFact(item.premise, item.facts, null)), Triggers.NONE)
            if (results.isNotEmpty()) flow(ctx, stage.to, results)
        }
    }

    override fun applySummary(part: Subscription, pub: Publication, member: Int) {
        val core = active()
        if (!RuntimeDataDomain.packet(part.ref.premise, part.added) ||
            !RuntimeDataDomain.packet(pub.premise, pub.conclusion)) return
        if (core.erasesRun1StaticSummary(pub.premise, pub.conclusion)) return
        core.checkPremise(part.ref.premise)
        core.checkPremise(pub.premise)
        when (val premise = pub.premise) {
            is PremiseSet -> ndMatch(part, pub, premise, member)
            is InitialAp -> {
                val results = ArrayList<PlanFact>()
                if (part.zeroOnly) {
                    if (core.config.run1 && pub.conclusion.base == STATIC)
                        core.routeStaticResultToExit(part.ref.call, part.ref.premise, pub.conclusion)
                    else results += planFact(part.ref.premise, pub.conclusion, false)
                }
                else applyParts(part, premise, pub.conclusion, results)
                resumeCallees(part.ref, results)
            }
        }
    }

    override fun applyStaticSummary(part: Subscription, pub: Publication, member: Int) {
        val core = active()
        if (!RuntimeDataDomain.packet(part.ref.premise, part.added) ||
            !RuntimeDataDomain.packet(pub.premise, pub.conclusion)) return
        check(core.config.run1 && part.ref.premise.isZero && part.added is Reach && !part.zeroOnly)
        core.checkPremise(pub.premise)
        if (core.erasesRun1StaticSummary(pub.premise, pub.conclusion)) return
        val initial = pub.premise.member(member)
        check(initial.base == STATIC)
        if (core.dropsStaticField(initial)) return
        if (initial.mark is MarkSlot.Star) {
            check(pub.premise is InitialAp && pub.conclusion is FlowTree)
            val value = pub.conclusion.withLayer(Layer.DEMAND)
            resumeCallees(part.ref, listOf(planFact(initial, value, false)))
        } else if (core.hasKnownStaticGroupInput(pub.premise)) {
            val actual = core.knownStaticInput(pub.premise as InitialAp)
            val statistics = core.context.shared.n2Statistics
            for (leaf in core.ops.leaves(pub.conclusion)) {
                core.ap.cancellation.checkpoint()
                statistics?.staticGroupCallOffered()
                statistics?.staticGroupCallDirect()
                val plain = core.ap.factsOf(leaf.fact, leaf.exclusion, pub.layer)
                val scalar = if (plain is TaintTree && pub.conclusion is TaintTree)
                    plain.withProtection(pub.conclusion.nonSubsumable) else plain
                applyStaticInput(part, StaticCallResult.Ap(pub.copy(conclusion = scalar)), member, actual)
            }
        } else core.staticCallInterest(part, StaticCallResult.Ap(pub), member)
    }

    override fun staticSupply(part: Subscription, result: StaticCallResult, member: Int, supply: RegionGroups) {
        val core = active()
        if (!RuntimeDataDomain.packet(part.ref.premise, part.added) || !RuntimeDataDomain.premise(result.premise)) return
        if (result is StaticCallResult.Ap && core.erasesRun1StaticSummary(result.premise, result.publication.conclusion)) return
        core.checkPremise(part.ref.premise)
        core.checkPremise(result.premise)
        applyStaticInput(part, result, member, core.staticFacts(supply))
    }

    /** Known input and late pool replies share matching and STATIC origin selection. */
    private fun applyStaticInput(part: Subscription, result: StaticCallResult, member: Int, actual: Facts) {
        val core = active()
        for (packet in core.ap.canonicalPackets(actual))
            applyCanonicalStaticInput(part, result, member, packet)
    }

    private fun applyCanonicalStaticInput(part: Subscription, result: StaticCallResult, member: Int, actual: Facts) {
        val core = active()
        val initial = result.premise.member(member)
        val matched = core.ops.matchSummary(actual, initial, core.mode, nativeRecordRead = false,
            role = SummaryMatchRole.CURRENT) ?: return
        for (leaf in core.ops.leaves(matched)) {
            check(leaf.fact.path.size != 1 || leaf.fact.tail == Tail.EXACT) {
                "A global class-marker call input must remain exact"
            }
            val path = leaf.fact.path.take(2)
            val selected = core.ap.initial(Pattern(leaf.fact.copy(path = path,
                tail = if (leaf.fact.tail == Tail.EXACT && leaf.fact.path.size <= 2) Tail.EXACT else Tail.STAR), ExclusionSet.Empty))
            val ref = part.ref.copy(premise = selected)
            val selectedInput = core.forceRun1Layer(selected, core.ops.startFact(selected, core.mode))
            val input = part.copy(ref = ref, linkLayer = selectedInput.layer, added = selectedInput)
            when (result) {
                is StaticCallResult.Terminal -> applyTarget(input, result.summary, member)
                is StaticCallResult.Ap -> {
                    val pub = result.publication
                    if (pub.premise is PremiseSet) ndMatch(input, pub, pub.premise, member)
                    else {
                        val statistics = core.context.shared.n2Statistics
                        val results = ArrayList<PlanFact>()
                        statistics?.staticGroupScalarApplied()
                        applyParts(input, initial, pub.conclusion, results)
                        if (results.isNotEmpty()) statistics?.staticGroupSuffixEntered()
                        resumeCallees(ref, results)
                    }
                }
            }
        }
    }

    private data class TargetJoinKey(val callee: MethodKey, val premise: PremiseKey, val target: Target,
                                     val call: CommonInst, val stageOrdinal: Int, val saved: Boolean, val scope: BlockScope)
    private data class TargetBinding(val ref: CallerRef, val layer: Layer)
    private val targetJoins = HashMap<TargetJoinKey, KaryJoin<TargetBinding>>()

    override fun applyTarget(part: Subscription, row: TargetSummary, member: Int) =
        applyTarget(part, row, member, saved = false)

    private fun applyTarget(part: Subscription, row: TargetSummary, member: Int, saved: Boolean) {
        val core = active()
        for (packet in core.ap.canonicalPackets(part.added))
            applyCanonicalTarget(part.copy(added = packet), row, member, saved)
    }

    private fun applyCanonicalTarget(part: Subscription, row: TargetSummary, member: Int, saved: Boolean) {
        val core = active()
        if (!core.forward && row.target is Target.NormalTarget) return
        if (!RuntimeDataDomain.packet(part.ref.premise, part.added) || !RuntimeDataDomain.premise(row.premise)) return
        val initial = row.premise.member(member)
        if (part.zeroOnly && !initial.isZero) return
        val selected = core.ops.matchSummary(part.added, initial, core.mode,
            nativeRecordRead = saved && initial.tail != Tail.ANY_TAINT,
            role = if (saved) SummaryMatchRole.SAVED_DIRECT else SummaryMatchRole.CURRENT) ?: return
        val layer = if (part.ref.callerLayer == Layer.DEMAND || selected.layer == Layer.DEMAND ||
            part.linkLayer == Layer.DEMAND) Layer.DEMAND else Layer.NORMAL
        if (row.target is Target.NormalTarget && layer != Layer.NORMAL) return
        val binding = TargetBinding(part.ref, layer)
        if (row.premise is InitialAp) emitTargetBinding(listOf(binding), row.target)
        else {
            val key = TargetJoinKey(part.callee, row.premise, row.target, part.ref.call, part.ref.stageOrdinal, saved, part.ref.scope)
            val join = targetJoins.getOrPut(key) { KaryJoin(row.premise.size, core.ap.cancellation) }
            for (bindings in join.add(member, binding)) emitTargetBinding(bindings, row.target)
        }
    }

    private fun emitTargetBinding(bindings: List<TargetBinding>, target: Target) {
        val core = active()
        if (target is Target.NormalTarget && bindings.any { it.layer != Layer.NORMAL }) return
        var premise = core.ap.zero as PremiseKey
        for (binding in bindings) {
            core.ap.cancellation.checkpoint()
            premise = core.ap.union(premise, binding.ref.premise)
        }
        core.emitTarget(premise, target)
    }

    override fun applyStaticTarget(part: Subscription, row: TargetSummary, member: Int) {
        val core = active()
        check(core.config.run1 && part.ref.premise.isZero && part.added is Reach && !part.zeroOnly)
        if (!RuntimeDataDomain.packet(part.ref.premise, part.added) || !RuntimeDataDomain.premise(row.premise)) return
        val initial = row.premise.member(member)
        check(initial.base == STATIC && initial.mark is MarkSlot.Concrete)
        if (core.dropsStaticField(initial)) return
        val result = StaticCallResult.Terminal(row)
        if (core.hasKnownStaticGroupInput(row.premise))
            applyStaticInput(part, result, member, core.knownStaticInput(row.premise as InitialAp))
        else core.staticCallInterest(part, result, member)
    }

    override fun resumePoint(premise: PremiseKey, facts: Facts, site: ResumeSite, state: CallResumeState?) {
        val core = active()
        val node = site.operation.form.statement
        val call = checkNotNull(core.context.callAt(node))
        core.forms.withCall(core.key, node, call) { plan ->
            val ctx = CallContext(node, call, plan, state?.callerLayer ?: facts.layer)
            val stage = checkNotNull(plan.stages.getOrNull(site.operation.stageOrdinal)) { "The resumed call stage changed" }
            val input = planFact(premise, facts, state?.identityCandidate)
            when (site) {
                is ResumeSite.CallStageInput -> {
                    val triggers = if (core.forward && stage.from == CallPoint.BOUND)
                        core.localServices.checkSinksAt(premise, node, facts, plan.sinks,
                            OperationInput(site, premise, facts, state)) else Triggers.NONE
                    val out = applyStage(ctx, stage, listOf(input), triggers, state?.pendingDemotion ?: false)
                    if (out.isNotEmpty()) flow(ctx, stage.to, out, state?.pendingDemotion ?: false)
                }
                is ResumeSite.CleanerInput -> {
                    val actions = checkNotNull(stage as? CallStage.Actions)
                    val out = ArrayList<PlanFact>()
                    cleanChain(actions, input, ctx, site.operation.stageOrdinal, site.step, site.phase,
                        state?.pendingDemotion ?: false) { out += it }
                    if (out.isNotEmpty()) flow(ctx, stage.to, out, state?.pendingDemotion ?: false)
                }
                else -> error("Not a call resume address")
            }
        }
    }

    override fun applyRecord(part: Subscription, record: Record) {
        val core = active()
        if (!RuntimeDataDomain.packet(part.ref.premise, part.added) ||
            !RuntimeDataDomain.packet(record.premise, record.conclusion)) return
        val premise = record.premise
        val native = ArrayList<PlanFact>()
        val pending = ArrayList<PlanFact>()
        var applied = false
        for (lane in nativeRecordLanes(core.ops, core.mode, part.added, premise)) {
            val results = if (lane.pendingDemotion) pending else native
            applied = applyParts(part.copy(added = lane.actual), premise, record.conclusion, results,
                run1Summary = false) || applied
        }
        if (applied) core.countRecordCrossing()
        resumeCallees(part.ref, native)
        val tagged = ArrayList<PlanFact>(pending.size)
        for (fact in pending) { core.ap.cancellation.checkpoint(); tagged += planFact(fact.premise, fact.facts, false) }
        resumeCallees(part.ref, tagged, pendingDemotion = true)
    }

    override fun applyRecordView(part: Subscription, view: RecordLeafView, nonSubsumable: Boolean) {
        val core = active()
        if (!RuntimeDataDomain.packet(part.ref.premise, part.added) ||
            !RuntimeDataDomain.base(view.premise.fact.base) || !RuntimeDataDomain.base(view.result.fact.base)) return
        val results = ArrayList<PlanFact>()
        var applied = false
        val identity = recordLeafIdentity(view)
        core.ops.applyRecordLeaf(part.added, view, nonSubsumable, core.mode, core.collect(part.ref.premise, part.added) { premise, result ->
            applied = true
            if (!completeBackwardSource(view.premise.fact.base == AccessPathBase.Zero, premise, result))
                results += planFact(premise, result, identity)
        }, original = part.ref.premise)
        if (applied) core.countRecordCrossing()
        resumeCallees(part.ref, results)
    }

    /** Source discharge is terminal. ZERO-to-ZERO remains ordinary control flow. */
    private fun completeBackwardSource(zeroPremise: Boolean, original: PremiseKey, result: Facts): Boolean {
        val core = active()
        if (core.forward || zeroPremise || result !is Reach) return false
        core.emitTarget(original, Target.DemandTarget)
        return true
    }

    private fun toDemand(facts: Facts): Facts {
        val core = active()
        return when (facts) {
            is TaintTree -> facts.withLayer(Layer.DEMAND)
            is Reach -> Reach.DEMAND
            is FlowTree -> error("A must record has TAINT results")
        }
    }

    private fun resumeCallees(ref: CallerRef, results: List<PlanFact>, pendingDemotion: Boolean = false) {
        val core = active()
        if (results.isEmpty()) return
        val call = checkNotNull(core.context.callAt(ref.call)) { "The caller reference is not at a call" }
        core.forms.withCall(core.key, ref.call, call) { plan ->
            val ctx = CallContext(ref.call, call, plan, ref.callerLayer)
            val stage = ctx.plan.stages.getOrNull(ref.stageOrdinal) as? CallStage.Callees
                ?: checkNotNull(ctx.plan.callees) { "A resumed result needs a callee stage" }
            flow(ctx, stage.to, results, pendingDemotion)
        }
    }

    private fun applyParts(part: Subscription, premise: InitialAp, conclusion: Facts, results: MutableList<PlanFact>,
                           run1Summary: Boolean = true): Boolean {
        val core = active()
        var applied = false
        for ((group, identity) in summaryParts(premise, conclusion, run1Summary)) {
            core.ap.cancellation.checkpoint()
            val at = OperationInput(ResumeSite.CallStageInput(core.operation(part.ref.call, part.ref.stageOrdinal)),
                part.ref.premise, part.added, CallResumeState(part.ref.callerLayer, identity))
            core.ops.applySummary(part.added, premise, group, core.mode, core.collect(at) { pr, result ->
                applied = true
                if (!completeBackwardSource(premise.isZero, pr, result)) {
                    if (core.config.run1 && result.base == STATIC) core.routeStaticResultToExit(part.ref.call, pr, result)
                    else results += planFact(pr, result, identity)
                }
            }, original = part.ref.premise)
        }
        return applied
    }

    private fun summaryParts(premise: InitialAp, conclusion: Facts, run1Summary: Boolean): List<Pair<Facts, Boolean>> {
        val core = active()
        if (core.config.run1 && run1Summary) return core.ap.run1SummaryParts(premise, conclusion)
        val start = core.ops.startFact(premise)
        if (premise.isZero || conclusion.layer != Layer.NORMAL || conclusion.groupKey != start.groupKey)
            return listOf(conclusion to false)
        val effect = core.ops.without(conclusion, start)
        val identity = if (effect == null) conclusion else core.ops.without(conclusion, effect)
        return listOfNotNull(effect?.let { it to false }, identity?.let { it to true })
    }

    private fun ndMatch(part: Subscription, pub: Publication, premise: PremiseSet, member: Int) {
        val core = active()
        check(core.forward && !core.config.run1) { "Conjunctive summaries require a later forward run" }
        check(!part.zeroOnly && part.added !is Reach && !premise.member(member).isZero)
        val conclusion = checkNotNull(pub.conclusion as? TaintTree) { "A multi-premise publication is TAINT" }
        val matched = matches(part, pub, member, core.ops, core.mode) ?: return
        check(matched is TaintTree) { "An E6 member input is TAINT" }
        check(part.linkLayer == matched.layer) { "The matched fact and link have the same layer" }
        val store = checkNotNull(core.localServices.conjunctions) { "Forward calls need their local conjunction store" }
        val join = store.ndJoin<NdBinding>(ConjunctionStore.NdKey(part.callee, premise, pub.layer, part.ref.call, part.ref.stageOrdinal, part.ref.scope))
        val binding = NdBinding(part.ref, matched.layer).also {
            it.triggering = (premise.member(member).mark as? MarkSlot.Concrete)?.mark
                ?.let { mark -> core.ap.marks.runtimeAtom(mark, core.mode.markMode) }
            it.nonSubsumable = matched.nonSubsumable != null
        }
        val fresh = join.addSubscription(member, binding) { previous, offered ->
            check(previous.triggering == offered.triggering)
            val changed = offered.nonSubsumable && !previous.nonSubsumable
            previous.nonSubsumable = previous.nonSubsumable || offered.nonSubsumable
            changed
        }
        for ((parts, result) in fresh) {
            core.ap.cancellation.checkpoint()
            applyCombination(parts, result)
        }
        for ((parts, result) in join.addConclusion(conclusion)) {
            core.ap.cancellation.checkpoint()
            applyCombination(parts, result)
        }
    }

    private fun applyCombination(parts: List<NdBinding>, conclusion: TaintTree) {
        val core = active()
        var union = parts[0].ref.premise
        val layers = ArrayList<Layer>(parts.size)
        for (index in parts.indices) {
            core.ap.cancellation.checkpoint()
            if (index != 0) union = core.ap.union(union, parts[index].ref.premise)
            layers += parts[index].linkLayer
        }
        val ref = parts.first().ref
        val results = ArrayList<PlanFact>()
        val at = OperationInput(ResumeSite.CallStageInput(core.operation(ref.call, ref.stageOrdinal)), union, conclusion,
            CallResumeState(ref.callerLayer))
        core.ops.applyMatchedCombination(layers, conclusion, core.collect(at) { pr, result ->
            val inherited = parts.any { it.nonSubsumable }
            var protected = if (inherited && result is TaintTree) result.withProtection(result.root) else result
            if (protected is TaintTree) {
                val restored = MarkSet(union.members.mapNotNull { (it.mark as? MarkSlot.Concrete)?.mark }
                    .map { core.ap.marks.runtimeAtom(it, core.mode.markMode) }
                    .filter { origin -> parts.any { it.triggering != null && it.triggering != origin } }
                    .map { it.id }.toIntArray())
                protected = core.ap.selectedProtection(protected, restored)
            }
            if (core.config.run1 && protected.base == STATIC) core.routeStaticResultToExit(ref.call, pr, protected)
            else results += planFact(pr, protected, false)
        })
        resumeCallees(ref, results)
    }

    override fun freeze() {
        targetJoins.clear()
        observed = null
        owner = null
    }
}

/** Header-only gate. NORMAL ZERO-origin exact source leaves are collector-fixed too.
 * Keep NORMAL MUST/STAR on the scalar path: repeated partial cleaning can add
 * redundant raw DEMAND exact rows, so it does not have the same raw callback image. */
internal fun fullCleanupCollectorFixed(premise: PremiseKey, facts: Facts): Boolean {
    if (facts is FlowTree && facts.exclusion != ExclusionSet.Empty) return false
    if (facts is TaintTree && (facts.exclusion != ExclusionSet.Empty ||
            facts.layer != Layer.DEMAND && (!premise.isZero || facts.root.hasAny))) return false
    if ((facts.base == STATIC || Run1StaticService.hasStaticMember(premise)) && facts.layer != Layer.DEMAND) return false
    return true
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.MethodKey

/** Actual method actors use the run's storage and its required local and call services. */
class RunMethodHandlers(
    private val localFactory: MethodLocalServicesFactory,
    private val callFactory: MethodCallServicesFactory,
) : RunnerHandlerFactory<RunMethodAnalyzer> {
    override fun create(port: RunnerPort<RunMethodAnalyzer>): RunnerHandler<RunMethodAnalyzer> =
        Handler(port, localFactory, callFactory)

    private class Handler(
        port: RunnerPort<RunMethodAnalyzer>,
        private val localFactory: MethodLocalServicesFactory,
        private val callFactory: MethodCallServicesFactory,
    ) : RunnerHandler<RunMethodAnalyzer>, SubscriptionHandler {
        private var runner: RunnerPort<RunMethodAnalyzer>? = port
        private fun active(): RunnerPort<RunMethodAnalyzer> =
            checkNotNull(runner) { "The method handler was released" }.also {
                it.shared.cancellation.checkpoint()
            }
        private var subscriptions: SubscriptionManager? = SubscriptionManager(object : SubscriptionPort {
            override val config get() = active().config
            override val ops get() = active().ops
            override val steps get() = active().steps
            override val statistics get() = active().shared.n2Statistics
            override val abstractionStatistics get() = active().shared.abstractionStatistics
            override val requestBatchStatistics get() = active().shared.requestBatchStatistics
            override val staticService get() = active().staticService
            override fun summaryStorage(key: MethodKey): SummaryStorage = active().summaryStorage(key)
            override fun applier(key: MethodKey): SummaryApplier = active().analyzer(key)
            override fun post(event: RunEvent.TargetDelivery): Boolean = active().post(event)
            override fun post(event: RunEvent.Delivery): Boolean = active().post(event)
            override fun post(event: RunEvent.ChangedRequests): Boolean = active().post(event)
            override fun send(event: RunEvent): Boolean = active().send(event)

        })

        override fun createActor(key: MethodKey): RunMethodAnalyzer {
            val port = active()
            return RunMethodAnalyzer(key, port,
                PublicationSink { method, batch -> active().summaryStorage(method).publish(batch) },
                localFactory, callFactory,
                targetPublisher = TargetPublicationSink { method, batch -> active().summaryStorage(method).publishTargets(batch) })
        }

        override fun handle(event: RunEvent) {
            val port = active()
            when (event) {
                is RunEvent.Start -> {
                    val initials = if (port.config.run1) listOf(org.opentaint.dataflow.bidi.ap.AdmittedInitial(
                        port.shared.ap.zero, org.opentaint.dataflow.bidi.ap.Layer.NORMAL))
                        else emitRestrictedInitials(port.config, port.ops, event.root,
                            org.opentaint.dataflow.bidi.ap.Reach.NORMAL)
                    if (initials.isEmpty()) return
                    val actor = port.analyzer(event.root)
                    for (initial in initials) actor.addInitial(initial)
                }
                is RunEvent.LinkIn -> if (org.opentaint.dataflow.bidi.ap.RuntimeDataDomain.packet(event.ref.premise, event.added))
                    port.analyzer(event.callee).addLink(event.ref, event.linkLayer, event.added)
                is RunEvent.InitialsIn -> {
                    check(port.config.restricted) { "Completed initial delivery is for restricted runs" }
                    val valid = event.initials.filter { org.opentaint.dataflow.bidi.ap.RuntimeDataDomain.initial(it.initial) }
                    if (valid.isEmpty()) return
                    val actor = port.analyzer(event.callee)
                    for (initial in valid) {
                        port.shared.cancellation.checkpoint()
                        actor.addInitial(initial)
                    }
                }
                is RunEvent.StaticOwner -> port.analyzer(event.effect.owner).onStaticEffect(event.effect)
                is RunEvent.MarkRequestsIn -> {
                    val valid = event.rows.filterKeys { org.opentaint.dataflow.bidi.ap.RuntimeDataDomain.base(it.base) }
                    if (valid.isNotEmpty()) port.analyzer(event.method).addScopedMarkRequests(event.scope, valid)
                }
                is RunEvent.InitialAnswersIn -> for (initial in event.answers) {
                    port.shared.cancellation.checkpoint()
                    if (org.opentaint.dataflow.bidi.ap.RuntimeDataDomain.initial(initial.initial))
                        port.analyzer(event.method).addInitial(initial)
                }
                is RunEvent.TargetDelivery -> checkNotNull(subscriptions).onTargetDelivery(event.callee, event.rows)
                is RunEvent.Delivery -> checkNotNull(subscriptions).onDelivery(event.callee, event.publications)
                is RunEvent.ChangedRequests -> checkNotNull(subscriptions).onRequests(event.callee, event.rows)
                is RunEvent.Work -> error("Work is handled by its owning unit runner")
            }
        }

        override fun subscribe(sub: Subscription) {
            active()
            checkNotNull(subscriptions).subscribe(sub)
        }

        override fun freeze() {
            subscriptions?.freeze()
            subscriptions = null
            runner = null
        }
    }
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.driver.Seed
import org.opentaint.dataflow.bidi.interp.SinkRule
import org.opentaint.dataflow.bidi.interp.ProofKey
import org.opentaint.dataflow.bidi.interp.SourceRuleOccurrence
import org.opentaint.dataflow.bidi.interp.RulePredicate
import org.opentaint.dataflow.bidi.interp.ResumeSite
import org.opentaint.dataflow.bidi.interp.ActionId
import org.opentaint.dataflow.bidi.store.*
import org.opentaint.ir.api.common.cfg.CommonInst

/** Rule joins use the method abstraction for completed mark-demand deliveries. */
class RunMethodLocalServices(core: BlockRunState) : MethodLocalServices {
    private var owner: BlockRunState? = core
    private var conjunctionStore: ConjunctionStore? = if (core.forward) ConjunctionStore(core.ap, core.context.shared.n2Statistics) else null
    private var predicateStore: RulePredicateStore? =
        if (core.forward) RulePredicateStore(core.ap, core.context.shared.formStatistics) else null
    private var originConjunctionStore: Run1OriginConjunctionStore? =
        if (core.forward && core.config.run1) Run1OriginConjunctionStore(core.ap) else null
    private var originPredicateStore: Run1OriginPredicateStore? =
        if (core.forward && core.config.run1) Run1OriginPredicateStore(core.ap, core.context.shared.formStatistics) else null
    // FULL condition evidence belongs to one semantic operation point. E6
    // call-summary joins keep the separate actor-wide conjunctionStore above.
    private val conditionConjunctions = HashMap<NormalRuleSite, ConjunctionStore>()
    private val conditionPredicates = HashMap<NormalRuleSite, RulePredicateStore>()
    private val conditionOriginConjunctions = HashMap<NormalRuleSite, Run1OriginConjunctionStore>()
    private val conditionOriginPredicates = HashMap<NormalRuleSite, Run1OriginPredicateStore>()
    override val conjunctions: ConjunctionStore? get() = conjunctionStore
    private var triggered: HashSet<Pair<CommonInst, Any>>? = HashSet()
    override val hasPendingRequests: Boolean get() = owner?.abstraction?.hasPending == true

    private fun activeCore(): BlockRunState =
        checkNotNull(owner) { "The local services were frozen" }.also { it.ap.cancellation.checkpoint() }

    private fun predicatesAt(rule: NormalRuleDescriptor, at: OperationInput): RulePredicateStore {
        val core = activeCore()
        return if (core.mode.markMode != MarkMode.FULL) checkNotNull(predicateStore)
        else conditionPredicates.getOrPut(NormalRuleContributors.stableSite(rule, at.site)) {
            RulePredicateStore(core.ap, core.context.shared.formStatistics)
        }
    }

    private fun conjunctionsAt(rule: NormalRuleDescriptor, at: OperationInput): ConjunctionStore {
        val core = activeCore()
        return if (core.mode.markMode != MarkMode.FULL) checkNotNull(conjunctionStore)
        else conditionConjunctions.getOrPut(NormalRuleContributors.stableSite(rule, at.site)) {
            ConjunctionStore(core.ap, core.context.shared.n2Statistics)
        }
    }

    private fun originPredicatesAt(rule: NormalRuleDescriptor, at: OperationInput): Run1OriginPredicateStore {
        val core = activeCore()
        return if (core.mode.markMode != MarkMode.FULL) checkNotNull(originPredicateStore)
        else conditionOriginPredicates.getOrPut(NormalRuleContributors.stableSite(rule, at.site)) {
            Run1OriginPredicateStore(core.ap, core.context.shared.formStatistics)
        }
    }

    private fun originConjunctionsAt(rule: NormalRuleDescriptor, at: OperationInput): Run1OriginConjunctionStore {
        val core = activeCore()
        return if (core.mode.markMode != MarkMode.FULL) checkNotNull(originConjunctionStore)
        else conditionOriginConjunctions.getOrPut(NormalRuleContributors.stableSite(rule, at.site)) {
            Run1OriginConjunctionStore(core.ap)
        }
    }

    /** Only a current accepted leaf activates earlier NORMAL conditional
     * evidence. Ready cached bindings use this invocation's ordinary callback. */
    private fun <B> acceptedLeaf(rule: NormalRuleDescriptor, at: OperationInput, leaf: Int,
                               input: ConjunctionStore.Input,
                               add: (Int, ConjunctionStore.Input, (B) -> Unit) -> Unit,
                               cache: Boolean = true,
                               emit: (B) -> Unit) {
        val core = activeCore()
        if (!cache) { add(leaf, input, emit); return }
        val ready = ArrayList<B>()
        if (!core.config.run1) core.normalRuleContributors.restoreOnce(rule, at.site) { saved ->
            add(saved.leaf, saved.input) { ready += it }
        }
        core.normalRuleContributors.keep(rule, at.site, leaf, input)
        for (binding in ready) emit(binding)
        add(leaf, input, emit)
    }

    override fun addMarkRequest(premise: InitialAp, mark: TaintMark) {
        val core = activeCore()
        check(core.config.run1) { "Requests exist only in run 1" }
        checkNotNull(core.abstraction).requireMark(premise, mark)
        if (hasPendingRequests) core.requestWork()
    }

    override fun addMarkRequests(premise: InitialAp, marks: RequestMarkSet) {
        val core = activeCore()
        check(core.config.run1) { "Requests exist only in run 1" }
        checkNotNull(core.abstraction).requireMarks(premise, marks)
        if (hasPendingRequests) core.requestWork()
    }

    override fun flushRequests(quantum: Int): Boolean {
        val core = activeCore()
        require(quantum > 0) { "The request-work quantum must be positive" }
        return core.abstraction?.flush(quantum) ?: true
    }

    override fun conjunction(edge: ConjunctiveEdge, premise: PremiseKey, facts: Facts, node: CommonInst,
                             sink: (PremiseKey, Facts) -> Unit) = conjunctionAt(edge, premise, facts, node,
        OperationInput(ResumeSite.StatementInput(activeCore().operation(node)), premise, facts), sink)

    override fun conjunctionAt(edge: ConjunctiveEdge, premise: PremiseKey, facts: Facts, node: CommonInst,
                               at: OperationInput, sink: (PremiseKey, Facts) -> Unit) {
        val core = activeCore()
        if (!RuntimeDataDomain.packet(premise, facts) || !RuntimeDataDomain.base(edge.target.base)) return
        check(core.forward) { "A backward form has independent conjunction branches" }
        val rule = NormalRuleDescriptor.legacyConjunction(edge)
        val store = conjunctionsAt(rule, at)
        for ((index, literal) in edge.literals.withIndex()) {
            core.ap.cancellation.checkpoint()
            if (literal.fact.base != facts.base) continue
            when (val checked = core.ops.checkMark(facts, literal, core.mode, core.unchangedStaticInitial(premise))) {
                MarkCheck.None -> Unit
                is MarkCheck.Request -> core.needGroups(at, checked.mark)
                is MarkCheck.Holds -> {
                    val input = ConjunctionStore.Input(premise, checked.facts.layer, checked.facts)
                    if (core.config.run1) {
                        core.normalRuleContributors.keep(rule, at.site, index, input)
                        val targets = HashMap<Layer, Facts>()
                        val assigned = runtimeAtom(core, (edge.target.mark as? MarkSlot.Concrete)?.mark)
                        val triggering = runtimeAtom(core, (literal.fact.mark as? MarkSlot.Concrete)?.mark)
                        originConjunctionsAt(rule, at).addProtectedOrigins(edge, node, edge.literals.size, index, input, assigned, triggering) { initial, layer, nonSubsumable ->
                            val result = targets.getOrPut(layer) { core.ops.targetTree(edge.target, layer, core.mode) }
                            sink(initial, core.forceRun1Layer(initial, protectTarget(result, nonSubsumable)))
                        }
                        continue
                    }
                    acceptedLeaf<ConjunctionStore.Combination>(rule, at, index, input,
                        add = { leaf, accepted, emit ->
                            for (combination in store.add(edge, node, edge.literals.size, leaf, accepted)) emit(combination)
                        }) { combination ->
                        core.ap.cancellation.checkpoint()
                        val result = core.ops.targetTree(edge.target, combination.layer, core.mode)
                        val protected = ruleProtection(core, combination.inputs, combination.premise,
                            runtimeAtom(core, (edge.target.mark as? MarkSlot.Concrete)?.mark))
                        sink(combination.premise, core.forceRun1Layer(combination.premise, protectTarget(result, protected)))
                        core.ap.cancellation.checkpoint()
                    }
                }
            }
        }
    }

    override fun sourcePredicate(source: SourceRuleOccurrence, premise: PremiseKey, facts: Facts, node: CommonInst,
                                 statementEdge: Boolean, sink: (PremiseKey, Facts) -> Unit) =
        sourcePredicateAt(source, premise, facts, node, statementEdge,
            OperationInput(ResumeSite.StatementInput(activeCore().operation(node)), premise, facts), sink)

    override fun sourcePredicateAt(source: SourceRuleOccurrence, premise: PremiseKey, facts: Facts, node: CommonInst,
                                   statementEdge: Boolean, at: OperationInput, sink: (PremiseKey, Facts) -> Unit) =
        sourcePredicateActionsAt(source, premise, facts, node, statementEdge, at) { pr, result, _ -> sink(pr, result) }

    override fun sourcePredicateActionsAt(source: SourceRuleOccurrence, premise: PremiseKey, facts: Facts, node: CommonInst,
                                          statementEdge: Boolean, at: OperationInput,
                                          sink: (PremiseKey, Facts, ActionId?) -> Unit) {
        val core = activeCore()
        if (!RuntimeDataDomain.packet(premise, facts)) return
        if (source.actions.isEmpty()) return
        val predicate = source.predicate
        fun transfer(pattern: Pattern, multi: Boolean) {
            for (action in source.actions) {
                core.ap.cancellation.checkpoint()
                val edge = source.transfer(pattern, action, multi)
                if (!RuntimeDataDomain.producer(edge) || edge.edge.from.base != facts.base) continue
                if (core.config.seededSources && !core.config.seeds.allowsSource(core.key, node, edge.forward, action.id)) continue
                core.ops.applyEdge(facts, premise, edge.edge, statementEdge, core.mode,
                    core.collectAfterRun1Policy(at) { _, result ->
                        core.sourceHits?.add(core.key, node, edge.forward, action.id)
                        sink(premise, result, action.id)
                    }, may = edge.may, ruleAssignment = edge.isRuleAssignment)
            }
        }
        if (source.backward) {
            check(!core.forward)
            for (leaf in predicate.leaves.indices) {
                core.ap.cancellation.checkpoint()
                if (predicate.isUnary(leaf)) transfer(predicate.leaves[leaf], multi = false)
                if (predicate.isMulti(leaf)) transfer(predicate.leaves[leaf], multi = true)
            }
            return
        }
        check(core.forward)
        val rule = NormalRuleDescriptor.predicate(source.id)
        fun multiLeaf(selected: RulePredicate, leaf: Int, pattern: Pattern, allowSingle: Boolean) {
            when (val checked = core.ops.checkMark(facts, pattern, core.mode, core.unchangedStaticInitial(premise))) {
                MarkCheck.None -> Unit
                is MarkCheck.Request -> core.needGroups(at, checked.mark)
                is MarkCheck.Holds -> if (core.config.run1) {
                    val input = ConjunctionStore.Input(premise, checked.facts.layer, checked.facts)
                    core.normalRuleContributors.keep(rule, at.site, leaf, input)
                    originPredicatesAt(rule, at).add(source.id, node, selected, leaf, input) { cube ->
                        if (allowSingle || cube.leaves.size >= 2) for (action in source.actions) {
                            core.ap.cancellation.checkpoint()
                            if (!RuntimeDataDomain.base(action.target.base)) continue
                            if (core.config.seededSources && cube.leaves.none { index ->
                                core.config.seeds.allowsSource(core.key, node,
                                    source.transfer(selected.leaves[index], action, multi = true).forward, action.id)
                            }) continue
                            val results = HashMap<Layer, Facts>()
                            val assigned = runtimeAtom(core, (action.target.mark as? MarkSlot.Concrete)?.mark)
                            cube.emitProtectedOrigins(action.id, assigned) { initial, layer, nonSubsumable ->
                                val result = results.getOrPut(layer) { core.ops.targetTree(action.target, layer, core.mode) }
                                sink(initial, core.forceRun1Layer(initial, protectTarget(result, nonSubsumable)), action.id)
                            }
                        }
                    }
                } else acceptedLeaf<RulePredicateStore.Combination>(rule, at, leaf,
                    ConjunctionStore.Input(premise, checked.facts.layer, checked.facts),
                    add = { index, input, emit -> predicatesAt(rule, at).add(source.id, node, selected, index, input, emit) }) { combination ->
                    // GROUP folding can leave one accepted leaf in an original MULTI transfer.
                    if (allowSingle || combination.leaves.size >= 2) for (action in source.actions) {
                        core.ap.cancellation.checkpoint()
                        if (!RuntimeDataDomain.base(action.target.base)) continue
                        if (core.config.seededSources && combination.leaves.none { index ->
                            core.config.seeds.allowsSource(core.key, node,
                                source.transfer(selected.leaves[index], action, multi = true).forward, action.id)
                        }) continue
                        val result = core.ops.targetTree(action.target, combination.layer, core.mode)
                        val protected = ruleProtection(core, combination.inputs, combination.premise,
                            runtimeAtom(core, (action.target.mark as? MarkSlot.Concrete)?.mark))
                        sink(combination.premise, core.forceRun1Layer(combination.premise, protectTarget(result, protected)), action.id)
                    }
                }
            }
        }
        if (core.config.run1 && source.groupTransfers) {
            for (unary in source.unaryTransfers) {
                core.ap.cancellation.checkpoint()
                matchingLeaves(core, unary.predicate, facts) { _, _ ->
                    // Use the declared anchor and original Facts, never the checked AP piece.
                    transfer(unary.anchor, multi = false)
                }
            }
            source.multiPredicate?.let { multi ->
                matchingLeaves(core, multi, facts) { leaf, pattern -> multiLeaf(multi, leaf, pattern, allowSingle = true) }
            }
            return
        }
        matchingLeaves(core, predicate, facts) { leaf, pattern ->
            core.ap.cancellation.checkpoint()
            if (predicate.isUnary(leaf)) transfer(pattern, multi = false)
            if (predicate.isMulti(leaf)) multiLeaf(predicate, leaf, pattern, allowSingle = false)
        }
    }

    private fun runtimeAtom(core: BlockRunState, atom: TaintMark?): TaintMark? =
        atom?.let { core.ap.marks.runtimeAtom(it, core.mode.markMode) }

    /** All accepted contributors remain in the exact ND premise. */
    private fun ruleProtection(core: BlockRunState, inputs: List<ConjunctionStore.Input>,
                               premise: PremiseKey, assigned: TaintMark?): Boolean {
        if (assigned == null) return false
        val triggers = ArrayList<TaintMark>()
        for (input in inputs) {
            val facts = input.facts as? TaintTree ?: continue
            if (facts.nonSubsumable != null) return true
            val leaves = core.ap.taintAlg.foldAll(facts.root, core.ap.cancellation)
            for (id in (leaves.exact + leaves.any).ids) triggers += core.ap.marks.runtimeAtom(TaintMark(id), core.mode.markMode)
        }
        if (assigned in triggers) return true
        return triggers.any { it != assigned } && premise.members.any {
            runtimeAtom(core, (it.mark as? MarkSlot.Concrete)?.mark) == assigned
        }
    }

    private fun protectTarget(result: Facts, nonSubsumable: Boolean): Facts =
        if (nonSubsumable && result is TaintTree) result.withProtection(result.root) else result

    override fun checkSinks(premise: PremiseKey, node: CommonInst, facts: Facts, sinks: List<SinkRule>): Triggers {
        return checkSinksAt(premise, node, facts, sinks,
            OperationInput(ResumeSite.StatementInput(activeCore().operation(node)), premise, facts))
    }

    override fun checkSinksAt(premise: PremiseKey, node: CommonInst, facts: Facts, sinks: List<SinkRule>, at: OperationInput): Triggers {
        val core = activeCore()
        if (!RuntimeDataDomain.packet(premise, facts)) return Triggers(emptyList(), emptyList())
        if (!core.forward || sinks.isEmpty()) return Triggers.NONE
        val fired = ArrayList<Pair<SinkRule, Layer>>()
        val parts = ArrayList<Facts>()
        for (sink in sinks) {
            core.ap.cancellation.checkpoint()
            val predicate = sink.predicate
            if (predicate != null && !predicate.isTrue) {
                val rule = NormalRuleDescriptor.predicate(checkNotNull(sink.occurrenceId))
                matchingLeaves(core, predicate, facts) { index, literal ->
                    core.ap.cancellation.checkpoint()
                    when (val checked = core.ops.checkMark(facts, literal, core.mode, core.unchangedStaticInitial(premise))) {
                        MarkCheck.None -> Unit
                        is MarkCheck.Request -> core.needGroups(at, checked.mark)
                        is MarkCheck.Holds -> {
                            parts += checked.facts
                            acceptedLeaf<RulePredicateStore.CompletePredicateBinding>(rule, at, index,
                                ConjunctionStore.Input(premise, checked.facts.layer, checked.facts),
                                add = { leaf, input, emit -> predicatesAt(rule, at).addBinding(
                                    checkNotNull(sink.occurrenceId), node, predicate, leaf, input, emit) },
                                cache = predicate.isMulti(index)) { combination ->
                                val edges = combination.inputs.map {
                                    SinkEdge(it.premise, it.layer, checkNotNull(it.facts))
                                }
                                witness(core, sink, node, edges, combination.proof)
                                fired += sink to combination.layer
                            }
                        }
                    }
                }
                continue
            }
            for ((index, literal) in sink.patterns.withIndex()) {
                core.ap.cancellation.checkpoint()
                when (val checked = core.ops.checkMark(facts, literal, core.mode, core.unchangedStaticInitial(premise))) {
                    MarkCheck.None -> Unit
                    is MarkCheck.Request -> core.needGroups(at, checked.mark)
                    is MarkCheck.Holds -> {
                        parts += checked.facts
                        if (!sink.conjunctive) {
                            witness(core, sink, node, listOf(SinkEdge(premise, checked.facts.layer, checked.facts)))
                            fired += sink to checked.facts.layer
                        } else {
                            val rule = NormalRuleDescriptor.legacySink(sink)
                            acceptedLeaf<ConjunctionStore.CompleteBinding>(rule, at, index,
                                ConjunctionStore.Input(premise, checked.facts.layer, checked.facts),
                                add = { leaf, input, emit ->
                                    for (combination in conjunctionsAt(rule, at).addBinding(sink.joinKey, node,
                                        sink.patterns.size, leaf, input)) emit(combination)
                                }) { combination ->
                                core.ap.cancellation.checkpoint()
                                val edges = combination.inputs.map { input ->
                                    core.ap.cancellation.checkpoint()
                                    SinkEdge(input.premise, input.layer, checkNotNull(input.facts))
                                }
                                witness(core, sink, node, edges)
                                fired += sink to combination.layer
                            }
                        }
                    }
                }
            }
        }
        return Triggers(fired.distinct(), parts)
    }

    private fun matchingLeaves(core: BlockRunState, predicate: RulePredicate, facts: Facts,
                               visit: (Int, Pattern) -> Unit) {
        when (facts) {
            is FlowTree -> predicate.matchingLeaves(facts.base, mark = null, visit)
            is Reach -> predicate.matchingLeaves(facts.base, TaintMark.ZERO, visit)
            is TaintTree -> {
                val leaves = core.ap.taintAlg.foldAll(facts.root, core.ap.cancellation)
                val marks = leaves.exact + leaves.any
                for (mark in marks.data) {
                    core.ap.cancellation.checkpoint()
                    predicate.matchingLeaves(facts.base, TaintMark(mark), visit)
                }
            }
        }
    }

    private fun witness(core: BlockRunState, sink: SinkRule, node: CommonInst, edges: List<SinkEdge>, proof: ProofKey? = null) {
        core.ap.cancellation.checkpoint()
        if (edges.any { !RuntimeDataDomain.packet(it.premise, it.facts) }) return
        val origins = edges.map { it.premise }.distinct()
        val cubeLayer = if (edges.any { it.layer == Layer.DEMAND }) Layer.DEMAND else Layer.NORMAL
        var demandSeedCaptured = false
        fun emitArm(premise: PremiseKey, layer: Layer) {
            val target = if (layer == Layer.NORMAL) {
                Target.NormalTarget(core.context.shared.reportCatalog.intern(
                    SinkKey(core.key.method, node, sink.rule.id), sink.rule, core.key))
            } else {
                if (!demandSeedCaptured) {
                    val projected = sink.predicate == null && sink.patterns.any {
                        (it.fact.mark as? MarkSlot.Concrete)?.mark?.let(core.ap.marks::isGroup) == true
                    }
                    core.sinkSeeds.addAll(if (projected)
                        org.opentaint.dataflow.bidi.driver.fullSinkSeedsFor(core.context.shared, sink, core.key, node)
                    else org.opentaint.dataflow.bidi.driver.sinkSeedsFor(sink, core.key, node))
                    demandSeedCaptured = true
                }
                Target.DemandTarget
            }
            core.emitTarget(premise, target)
        }
        if (core.config.run1) {
            val nonzero = origins.filterNot { it.isZero }
            for (origin in nonzero.ifEmpty { listOf(core.ap.zero) }) {
                val complete = origins.all { it.isZero || it == origin }
                emitArm(origin, if (complete) cubeLayer else Layer.DEMAND)
            }
        } else {
            var original: PremiseKey = core.ap.zero
            for (origin in origins) original = core.ap.union(original, origin)
            emitArm(original, cubeLayer)
        }
    }

    override fun fireSinkSeeds(node: CommonInst, emit: (Facts) -> Unit) {
        val core = activeCore()
        for (seed in core.config.seeds.at(core.key, node)) {
            core.ap.cancellation.checkpoint()
            if (seed is Seed.Sink) seedFact(core, seed.requirement, emit)
            if (seed is Seed.PredicateSink) {
                fun visit(sinks: List<SinkRule>) {
                    val sink = sinks.singleOrNull { it.occurrenceId == seed.occurrence }
                        ?: error("A predicate seed must resolve to its frozen rule occurrence")
                    for (requirement in sink.seedPatterns()) seedFact(core, requirement, emit)
                }
                val call = core.context.callAt(node)
                if (call != null) core.forms.withCall(core.key, node, call) { visit(it.sinks) }
                else core.forms.withStartRules(core.key, node) { visit(it.sinks) }
            }
        }
    }

    override fun fireTriggerSeeds(node: CommonInst, sink: SinkRule, emit: (Facts) -> Unit) {
        val core = activeCore()
        if (!checkNotNull(triggered).add(node to sink.joinKey)) return
        for (literal in sink.seedPatterns()) {
            core.ap.cancellation.checkpoint()
            core.countTriggerSeed()
            seedFact(core, literal, emit)
        }
    }

    private fun seedFact(core: BlockRunState, requirement: Pattern, emit: (Facts) -> Unit) {
        if (!RuntimeDataDomain.base(requirement.fact.base)) return
        core.ap.cancellation.checkpoint()
        core.cut(Cut.SEED, core.ap.zero, core.ops.targetTree(requirement.fact, Layer.NORMAL)) { _, facts ->
            if (core.config.index == 2) {
                // A seed starts at its check, before any caller-input query gate.
                // Validate the bounded value; a deeper named field is lawful before this cut.
                for (leaf in core.ops.leaves(facts)) validateRun2StaticFullInput(core.ap, leaf, core.config.fieldLimit)
            }
            emit(facts)
            core.ap.cancellation.checkpoint()
        }
    }

    override fun freeze() {
        conditionConjunctions.clear()
        conditionPredicates.clear()
        conditionOriginConjunctions.clear()
        conditionOriginPredicates.clear()
        conjunctionStore = null
        predicateStore = null
        originConjunctionStore = null
        originPredicateStore = null
        triggered = null
        owner = null
    }
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.Direction
import org.opentaint.dataflow.bidi.ap.MarkMode
import org.opentaint.dataflow.bidi.store.FrozenCompletion
import java.util.Collections
import kotlin.time.Duration

enum class RunStatus { COMPLETE, TIMEOUT, OOM, FAILED }

/** Incomplete results provide no run stores. The driver reads frozen actors at a complete barrier. */
class RunResult<A : RunActor>(
    val status: RunStatus,
    analyzers: List<A>,
    val runIndex: Int,
    val direction: Direction,
    val markMode: MarkMode? = null,
    val joinedStaticBindingTime: Duration = Duration.ZERO,
    val staticCompletion: FrozenCompletion? = null,
    val joinedSealReleaseTime: Duration = Duration.ZERO,
) {
    val analyzers: List<A> = Collections.unmodifiableList(ArrayList(analyzers))

    init {
        check(status == RunStatus.COMPLETE || this.analyzers.isEmpty())
        check(status == RunStatus.COMPLETE || staticCompletion == null) { "Incomplete guidance is not exported" }
    }

    val demandLayerEdges: Long get() = analyzers.sumOf { it.demandLayerEdges }
    val recordCrossings: Long get() = analyzers.sumOf { it.recordCrossings }
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.store.*

/** Both real replay and pure observations use the same selection reader; these are whole-reader totals. */
internal class SavedRecordSelectionStatistics {
    var queries = 0L
    var fallbackQueries = 0L
    var submittedLeaves = 0L
    var entryCandidates = 0L
    var outputPositions = 0L
    var selectedRecords = 0L
    var reversedViews = 0L
    var replayDirectMatches = 0L
    fun diagnosticStatistics(): String =
        "savedSelectionQueries=$queries savedSelectionFallbacks=$fallbackQueries savedSubmittedLeaves=$submittedLeaves " +
        "savedEntryCandidates=$entryCandidates savedOutputPositions=$outputPositions savedSelectedRecords=$selectedRecords " +
        "savedReversedViews=$reversedViews savedReplayDirectMatches=$replayDirectMatches"
}

/** Invocation-local positional capability. It does not participate in native record identity. */
internal class SavedRecordSelection(
    val record: Record,
    private val reversePositions: List<Pair<Pattern, List<RecordOutputPosition>>>? = null,
    private val statistics: SavedRecordSelectionStatistics? = null,
) {
    fun forEachNativeReversedAt(actual: Facts, ops: ApOps, emit: (NativeReverseRead, Boolean) -> Unit) {
        val seen = LinkedHashSet<Pair<NativeReadKey, Boolean>>()
        fun offer(view: NativeReverseRead, protected: Boolean) {
            if (seen.add(view.semanticKey() to protected)) {
                statistics?.let { it.reversedViews++ }
                emit(view, protected)
            }
        }
        val selected = reversePositions
        if (selected == null) {
            for (leaf in ops.leaves(actual)) record.forEachNativeReversedAt(leaf, ::offer)
        } else {
            for ((leaf, positions) in selected) for (position in positions) {
                ops.manager.cancellation.checkpoint()
                position.forEachNativeReversedAt(leaf, ::offer)
            }
        }
    }

    fun forEachReversedAt(actual: Facts, ops: ApOps, emit: (RecordLeafView, Boolean) -> Unit) =
        forEachNativeReversedAt(actual, ops) { read, protected -> emit(read.view, protected) }

}

/** Preserve record-first discovery, then submitted-leaf and native output-position order.
 * Unknown read views use the complete old reader; no partial positional result is committed. */
internal fun selectSavedRecords(records: RecordStore, method: MethodKey, scope: BlockScope,
                                actual: Facts, ops: ApOps, direction: Direction,
                                statistics: SavedRecordSelectionStatistics? = null): List<SavedRecordSelection> {
    statistics?.let { it.queries++ }
    val leaves = ops.leaves(actual).toList()
    statistics?.let { it.submittedLeaves += leaves.size }
    val positions = leaves.map { leaf -> records.byExitPositions(method, scope, leaf) }
    if (positions.any { it == null }) {
        statistics?.let { it.fallbackQueries++ }
        val seen = LinkedHashSet<Record>()
        for (leaf in leaves) {
            ops.manager.cancellation.checkpoint()
            for (record in records.byEntry(method, scope, leaf)) {
                statistics?.let { it.entryCandidates++ }
                if (record.direction == direction) seen += record
            }
            for (record in records.byExit(method, scope, leaf)) if (record.direction != direction) seen += record
        }
        statistics?.let { it.selectedRecords += seen.size }
        return seen.map { SavedRecordSelection(it, statistics = statistics) }
    }
    val ordered = LinkedHashSet<Record>()
    val reverse = LinkedHashMap<Record, MutableList<Pair<Pattern, List<RecordOutputPosition>>>>()
    for ((index, leaf) in leaves.withIndex()) {
        ops.manager.cancellation.checkpoint()
        for (record in records.byEntry(method, scope, leaf)) {
            statistics?.let { it.entryCandidates++ }
            if (record.direction == direction) ordered += record
        }
        val groups = LinkedHashMap<Record, MutableList<RecordOutputPosition>>()
        for (position in checkNotNull(positions[index])) {
            statistics?.let { it.outputPositions++ }
            val record = position.record
            if (record.direction == direction) continue
            ordered += record
            groups.getOrPut(record) { ArrayList() }.add(position)
        }
        for ((record, selected) in groups) reverse.getOrPut(record) { ArrayList() }
            .add(leaf to selected.sortedBy { it.ordinal })
    }
    statistics?.let { it.selectedRecords += ordered.size }
    return ordered.map { SavedRecordSelection(it, reverse[it], statistics) }
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.store.BlockScope
import org.opentaint.dataflow.graph.PortId
import java.util.ArrayDeque

/** Relay a real point request through the identity inputs of a static exit continuation.
 *
 * Intermediate ROOT_EXIT links pass the same canonical static input without an instruction.
 * The outer link can instead have C.f as its original and C.g as its FLOW image. Its owner
 * handles that relation through the existing local-static or ordinary mark-request path.
 * This query neither supplies a mark nor retains requests or a cross-query seen set.
 */
internal class StaticBoundaryInputRequests(
    private val ops: ApOps,
    private val mode: ApMode,
    private val borrowInputs: (BlockScope, (LocalLink, Facts) -> Unit) -> Unit,
    private val onRoot: (LocalLink, FlowTree, TaintMark) -> Unit,
) {
    private data class Query(val scope: BlockScope, val initial: InitialAp)

    fun request(scope: BlockScope, initial: InitialAp, mark: TaintMark) {
        val ap = ops.manager
        ap.cancellation.checkpoint()
        if (!mode.run1 || mode.direction != Direction.FORWARD || scope.entry != PortId.ROOT_EXIT ||
            initial.base != STATIC || initial.mark !is MarkSlot.Star) return

        val pending = ArrayDeque<Query>()
        val visited = HashSet<Query>()
        fun enqueue(query: Query) {
            if (visited.add(query)) pending.addLast(query)
        }
        enqueue(Query(scope, initial))
        while (pending.isNotEmpty()) {
            ap.cancellation.checkpoint()
            val query = pending.removeFirst()
            borrowInputs(query.scope) { link, actual ->
                ap.cancellation.checkpoint()
                check(link.child == query.scope) { "A static continuation borrows its own registered inputs" }
                if (link.point != PortId.ROOT_EXIT || actual !is FlowTree ||
                    !RuntimeDataDomain.packet(link.original, actual)) return@borrowInputs
                val parentInitial = link.original as? InitialAp ?: return@borrowInputs
                if (parentInitial.mark !is MarkSlot.Star) return@borrowInputs
                val matched = ops.satisfying(actual, query.initial, mode) as? FlowTree ?: return@borrowInputs
                if (link.parent == BlockScope.ROOT) {
                    onRoot(link, matched, mark)
                } else if (link.parent.entry == PortId.ROOT_EXIT && parentInitial == query.initial) {
                    // Only these installed, unchanged inputs are identity continuations.
                    enqueue(Query(link.parent, parentInitial))
                }
            }
        }
    }
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.store.forEachMark
import org.opentaint.dataflow.bidi.store.RequestMarkSetBuilder
import org.opentaint.dataflow.bidi.store.BlockScope
import org.opentaint.dataflow.bidi.store.OwnedScope

/** Replay and delivery use one complete AP predicate after their candidate scans. */
fun matches(sub: Subscription, pub: Publication, member: Int, ops: ApOps, mode: ApMode): Facts? {
    ops.manager.cancellation.checkpoint()
    if (!RuntimeDataDomain.packet(sub.ref.premise, sub.added) ||
        !RuntimeDataDomain.packet(pub.premise, pub.conclusion)) return null
    return if (sub.zeroOnly) sub.added.takeIf { pub.premise.isZero }
    else ops.matchSummary(sub.added, pub.premise.member(member), mode, nativeRecordRead = false,
        role = SummaryMatchRole.CURRENT)
}

/** Only notify runs on a publisher's thread; all subscription state is runner-owned. */
class SubscriptionManager(port: SubscriptionPort) {
    @Volatile private var port: SubscriptionPort? = port
    private var inputDirectory: LinkedHashMap<MethodKey, CalleeSubscriptions>? = LinkedHashMap()
    private val byCallee get() = checkNotNull(inputDirectory) { "Caller inputs were sealed" }

    private fun active(): SubscriptionPort = checkNotNull(port) { "The subscriptions were released" }.also {
        it.ops.manager.cancellation.checkpoint()
    }

    fun subscribe(sub: Subscription) {
        val port = active()
        for (packet in port.ops.manager.canonicalPackets(sub.added))
            subscribeCanonical(sub.copy(added = packet))
    }

    private fun subscribeCanonical(sub: Subscription) {
        val port = active()
        if (!RuntimeDataDomain.packet(sub.ref.premise, sub.added)) return
        check(!port.config.run1 || sub.ref.premise is InitialAp) { "Run-1 subscriptions have one original premise" }
        val storage = port.summaryStorage(sub.callee)
        val entry = byCallee.getOrPut(sub.callee) {
            CalleeSubscriptions(port.ops, port.statistics).also { storage.addSubscriber(this) }
        }
        val admitted = entry.admit(sub) ?: return
        val statistics = port.statistics
        if (statistics == null) {
            port.steps.replay { replay(storage, admitted) }
            return
        }
        statistics.replayQueued()
        var entered = false
        try {
            port.steps.replay {
                entered = true
                try { replay(storage, admitted) }
                finally { statistics.replayFinished() }
            }
        } catch (error: Throwable) {
            // Inline failures release in the callback; admission failures release here.
            if (!entered) statistics.replayFinished()
            throw error
        }
    }

    private fun replay(storage: SummaryStorage, admitted: CalleeSubscriptions.Admission) {
        val port = active()
        for (packet in port.ops.manager.canonicalPackets(admitted.fresh.added)) {
            val part = admitted.fresh.copy(added = packet)
            for ((pub, member) in storage.candidates(part, port.config.mode)) {
                port.ops.manager.cancellation.checkpoint()
                applyMatch(part, pub, member)
            }
            for ((row, member) in storage.targetCandidates(part, port.config.mode)) {
                port.ops.manager.cancellation.checkpoint()
                port.applier(part.caller).applyTarget(part, row, member)
            }
            if (isStaticControl(part)) for ((row, member) in storage.staticTargetCandidates()) {
                port.ops.manager.cancellation.checkpoint()
                port.applier(part.caller).applyStaticTarget(part, row, member)
            }
            if (isStaticControl(part)) for ((pub, member) in storage.staticCandidates()) {
                port.ops.manager.cancellation.checkpoint()
                applyStaticControl(part, pub, member)
            }
        }
        if (port.config.run1 && !admitted.fresh.zeroOnly) {
            val current = admitted.current
            checkKinds(current)
            if (current.added is FlowTree) {
                port.abstractionStatistics?.freshFlowInputVisit(admitted.growth)
                for (packet in port.ops.manager.canonicalPackets(current.added)) {
                    val part = current.copy(added = packet)
                    val rows = storage.borrowMatchingRequests(packet)
                    joinRequests(rows) { visit -> visit(part) }
                }
            }
        }
    }

    private data class ClimbTarget(val owner: OwnedScope, val slot: Run1Slot)
    private class ReplayCounts {
        var candidates = 0L
        var tests = 0L
        var answers = 0L
        var climbs = 0L
    }

    private fun checkKinds(part: Subscription) {
        check((part.added is FlowTree) == part.ref.premise.isFlow) {
            "K6: the conclusion kind follows its original premise"
        }
        check(part.ref.premise !is PremiseSet || part.added is TaintTree) {
            "A multiple-member input must be TAINT"
        }
    }

    /** Visit first, then queue every effect, including same-unit effects. */
    private fun joinRequests(rows: List<RequestedRow>, inputs: ((Subscription) -> Unit) -> Unit) {
        val port = active()
        check(port.config.run1) { "Mark requests exist only in run 1" }
        if (rows.isEmpty()) return
        val ap = port.ops.manager
        val statistics = port.abstractionStatistics
        val counts = statistics?.let { ReplayCounts() }
        val batchStatistics = port.requestBatchStatistics
        val batch = batchStatistics?.let { RequestBatchStatistics.Counts() }
        val started = if (statistics == null) 0L else System.nanoTime()
        val answers = LinkedHashMap<MethodKey, LinkedHashSet<AdmittedInitial>>()
        val climbs = LinkedHashMap<ClimbTarget, RequestMarkSetBuilder>()
        val staticPoints = LinkedHashMap<Subscription, RequestMarkSetBuilder>()
        try {
            inputs { part ->
                ap.cancellation.checkpoint()
                if (counts != null) counts.candidates++
                checkKinds(part) // K6 before eligibility guards
                if (!part.zeroOnly) when (part.added) {
                    is FlowTree -> {
                        val original = normalRun1Slot(part.ref.premise)
                        val staticOriginal = (part.ref.premise as? InitialAp)?.takeIf {
                            it.base == STATIC && it.mark is MarkSlot.Star
                        }
                        if (original != null || staticOriginal != null) {
                            if (counts != null) counts.tests++
                            if (batch != null) batch.groupGeometryTests++
                            val offered = RequestMarkSetBuilder()
                            // Compute geometry once per row, then merge the matching
                            // marks before one target-R read and one destination union.
                            for (row in rows) {
                                ap.cancellation.checkpoint()
                                if (batch != null) batch.groupGeometrySteps++
                                if (!slotMatches(row.slot, part.added)) continue
                                row.marks.forEachMark {
                                    ap.cancellation.checkpoint(); offered.add(it)
                                    if (batch != null) batch.memberScans++
                                }
                            }
                            if (!offered.isEmpty) {
                                if (staticOriginal != null) {
                                    val target = staticPoints.getOrPut(part, ::RequestMarkSetBuilder)
                                    offered.takeSnapshot().forEachMark { ap.cancellation.checkpoint(); target.add(it) }
                                    return@inputs
                                }
                                val target = ClimbTarget(OwnedScope(part.ref.caller, part.ref.scope), checkNotNull(original))
                                // Only the root snapshot is exposed here. A nonroot caller
                                // admits/deduplicates requests in its own R/P stores on delivery.
                                val admitted = if (target.owner.local == BlockScope.ROOT)
                                    port.summaryStorage(target.owner.method).borrowRequest(original) else null
                                val destination = climbs.getOrPut(target, ::RequestMarkSetBuilder)
                                offered.takeSnapshot().forEachMark { mark ->
                                    ap.cancellation.checkpoint()
                                    if (admitted?.containsId(mark.id) != true) {
                                        if (counts != null) counts.climbs++
                                        if (batch != null) batch.climbs++
                                        if (!destination.add(mark) && batch != null) batch.duplicateTargetUnions++
                                    }
                                }
                            }
                        }
                    }
                    is TaintTree -> {
                        if (counts != null) counts.tests++
                        if (batch != null) batch.groupGeometryTests++
                        forEachConcreteAnswer(ap, part.added, rows, batch) { initial ->
                            if (counts != null) counts.answers++
                            if (batch != null) batch.answers++
                            answers.getOrPut(part.callee, ::LinkedHashSet).add(initial)
                        }
                    }
                    is Reach -> Unit
                }
            }
            val requestsByOwner = LinkedHashMap<OwnedScope, MutableMap<Run1Slot, org.opentaint.dataflow.bidi.store.RequestMarkSet>>()
            for ((part, marks) in staticPoints) {
                ap.cancellation.checkpoint()
                port.applier(part.caller).requestStaticGroups(part, marks.takeSnapshot())
            }
            for ((target, marks) in climbs) {
                ap.cancellation.checkpoint()
                if (!marks.isEmpty) requestsByOwner.getOrPut(target.owner, ::LinkedHashMap)[target.slot] = marks.takeSnapshot()
            }
            for ((owner, rowsToSend) in requestsByOwner) {
                ap.cancellation.checkpoint()
                val accepted = port.send(RunEvent.MarkRequestsIn(owner.method,
                    java.util.Collections.unmodifiableMap(rowsToSend), owner.local))
                ap.cancellation.checkpoint()
                check(accepted) { "An active run rejected a request delivery" }
                if (batch != null) batch.acceptedBatch(rowsToSend.values.sumOf { it.size })
            }
            for ((method, values) in answers) {
                ap.cancellation.checkpoint()
                val accepted = port.send(RunEvent.InitialAnswersIn(method, values))
                ap.cancellation.checkpoint()
                check(accepted) { "An active run rejected a concrete answer delivery" }
            }
        } finally {
            if (counts != null) statistics?.replayVisit(counts.candidates, counts.tests, counts.answers,
                counts.climbs, System.nanoTime() - started)
            if (batch != null) batchStatistics?.record(batch)
        }
    }

    /** Publisher thread: post to the subscriber runner without reading its directory. */
    fun notifyRequests(callee: MethodKey, rows: RequestRows): Boolean {
        val port = active()
        check(port.config.run1) { "Mark requests exist only in run 1" }
        val accepted = port.post(RunEvent.ChangedRequests(callee, rows))
        port.ops.manager.cancellation.checkpoint()
        check(accepted) { "An active run rejected a request notification" }
        return accepted
    }

    fun onRequests(callee: MethodKey, rows: RequestRows) {
        val port = active()
        check(port.config.run1) { "Mark requests exist only in run 1" }
        val entry = byCallee[callee] ?: return
        val selected = rows.map { (slot, marks) ->
            RequestedRow(slot, RequestRowView(marks))
        }
        joinRequests(selected) { visit -> entry.visitRequestBatch(selected, visit) }
    }

    private fun applyMatch(part: Subscription, pub: Publication, member: Int) {
        val port = active()
        val added = matches(part, pub, member, port.ops, port.config.mode) ?: return
        port.ops.manager.cancellation.checkpoint()
        port.applier(part.caller).applySummary(part.copy(added = added), pub, member)
        port.ops.manager.cancellation.checkpoint()
    }

    private fun isStaticControl(part: Subscription): Boolean =
        active().config.run1 && !part.zeroOnly && part.ref.premise.isZero && part.added is Reach

    private fun applyStaticControl(part: Subscription, pub: Publication, member: Int) {
        val port = active()
        check(isStaticControl(part))
        check(pub.premise.member(member).base == STATIC)
        port.applier(part.caller).applyStaticSummary(part, pub, member)
    }

    /** P2's notification reads no caller-local subscriptions. */
    fun notify(callee: MethodKey, pubs: List<Publication>): Boolean {
        val port = active()
        val accepted = port.post(RunEvent.Delivery(callee, pubs))
        port.ops.manager.cancellation.checkpoint()
        return accepted
    }

    fun notifyTargets(callee: MethodKey, rows: TargetBatch): Boolean {
        val port = active()
        val accepted = port.post(RunEvent.TargetDelivery(callee, rows))
        port.ops.manager.cancellation.checkpoint()
        check(accepted) { "An active run rejected a required terminal delivery" }
        return accepted
    }

    fun onTargetDelivery(callee: MethodKey, rows: TargetBatch) {
        val port = active()
        val entry = byCallee[callee] ?: return
        for (row in rows) {
            port.ops.manager.cancellation.checkpoint()
            for (member in 0 until row.premise.size) {
                for (part in entry.candidates(row.premise, member, port.config.mode)) {
                    port.ops.manager.cancellation.checkpoint()
                    port.applier(part.caller).applyTarget(part, row, member)
                }
                if (port.config.run1 && row.premise.member(member).base == STATIC) {
                    for (part in entry.staticControlCandidates()) {
                        port.ops.manager.cancellation.checkpoint()
                        port.applier(part.caller).applyStaticTarget(part, row, member)
                    }
                }
            }
        }
    }

    /** P6 queries the subscriptions present when the destination runner handles delivery. */
    fun onDelivery(callee: MethodKey, pubs: List<Publication>) {
        val port = active()
        val entry = byCallee[callee] ?: return
        for (pub in pubs) {
            port.ops.manager.cancellation.checkpoint()
            for (member in 0 until pub.premise.size) {
                port.ops.manager.cancellation.checkpoint()
                for (part in entry.candidates(pub, member, port.config.mode)) {
                    port.ops.manager.cancellation.checkpoint()
                    applyMatch(part, pub, member)
                }
                if (port.config.run1 && pub.premise.member(member).base == STATIC) {
                    for (part in entry.staticControlCandidates()) {
                        port.ops.manager.cancellation.checkpoint()
                        applyStaticControl(part, pub, member)
                    }
                }
            }
        }
    }

    /** Joined, read-only view of the exact callee's existing current inputs.
     * This path neither asks its port for a storage nor applies a live effect. */
    internal fun visitJoinedInputs(callee: MethodKey, writer: Publication, mode: ApMode,
                                   visit: (Subscription) -> Unit) {
        checkNotNull(port) { "The caller subscriptions were already released" }
        byCallee[callee]?.visitJoinedCandidates(writer, mode, visit)
    }

    internal fun detachJoinedInputs(): JoinedCallerInputs {
        checkNotNull(port) { "Caller subscriptions were already released" }
        val owned = checkNotNull(inputDirectory) { "Caller inputs were already detached" }
        inputDirectory = null
        port = null
        return JoinedCallerInputs(owned)
    }

    /** Joining ends all notifications before the owning runner calls this method. */
    fun freeze() {
        val owned = inputDirectory
        inputDirectory = null
        port = null
        if (owned != null) JoinedCallerInputs(owned).close()
    }

}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.ApManager
import org.opentaint.dataflow.bidi.ap.ApMode
import org.opentaint.dataflow.bidi.ap.ApOps
import org.opentaint.dataflow.bidi.ap.MethodKey
import org.opentaint.dataflow.bidi.ap.Facts

/** A run owns this callee's published deltas and its subscribed caller runners. */
class SummaryStorage(
    val method: MethodKey,
    private val ap: ApManager,
    ops: ApOps,
    private val steps: ProtocolSteps,
    private val statistics: Run1AbstractionStatistics? = null,
    flowBacked: Boolean = false,
) {
    private val lock = Any()
    private var publishedIndex: PublicationIndex? = PublicationIndex(ap, ops, flowBacked)
    private val published get() = checkNotNull(publishedIndex) { "Summary storage is sealed" }
    private val subscribers = LinkedHashSet<SubscriptionManager>()
    private var requestRows: RequestStorage? = RequestStorage()
    private val requests get() = checkNotNull(requestRows) { "Summary storage is sealed" }

    fun borrowRequest(slot: Run1Slot): RequestRowView = synchronized(lock) { requests.borrow(slot) }

    fun borrowMatchingRequests(input: Facts): List<RequestedRow> = synchronized(lock) {
        val counts = statistics?.let { RequestMatchCounts() }
        requests.borrowMatchingRows(input, ap.cancellation::checkpoint, counts).also { rows ->
            if (counts != null) statistics?.requestMatch(counts, rows.size)
        }
    }

    /** Commit merged rows synchronously, then queue new marks after releasing the storage lock. */
    fun commit(temporary: RequestStorage) {
        ap.cancellation.checkpoint()
        val (fresh, recipients) = synchronized(lock) {
            val oldRows = requests.dynamicRows
            val rows = LinkedHashMap<Run1Slot, org.opentaint.dataflow.bidi.store.RequestMarkSet>()
            for ((slot, marks) in temporary.pendingRows()) {
                ap.cancellation.checkpoint()
                val delta = requests.addAll(slot, marks, ap.cancellation::checkpoint)
                if (!delta.isEmpty) rows[slot] = delta
            }
            statistics?.requestCommit(rows.size, rows.values.sumOf { it.size.toLong() }, requests.dynamicRows - oldRows)
            freezeRequestRows(rows) to if (rows.isEmpty()) emptyList() else subscribers.toList()
        }
        if (fresh.isEmpty()) return
        steps.notify {
            for (subscriber in recipients) {
                ap.cancellation.checkpoint()
                if (!subscriber.notifyRequests(method, fresh)) {
                    ap.cancellation.checkpoint()
                    error("An active run rejected a required request delivery")
                }
            }
        }
    }

    fun publish(pubs: List<Publication>) {
        ap.cancellation.checkpoint()
        val (delta, recipients) = synchronized(lock) { published.addAll(pubs) to subscribers.toList() }
        if (delta.isEmpty()) return
        steps.notify {
            for (subscriber in recipients) {
                ap.cancellation.checkpoint()
                subscriber.notify(method, delta)
            }
        }
    }

    fun publishTargets(rows: TargetBatch) {
        ap.cancellation.checkpoint()
        val (delta, recipients) = synchronized(lock) { published.addTargets(rows) to subscribers.toList() }
        if (delta.isEmpty()) return
        steps.notify {
            for (subscriber in recipients) {
                ap.cancellation.checkpoint()
                check(subscriber.notifyTargets(method, delta)) {
                    "An active run rejected a required terminal delivery"
                }
            }
        }
    }

    fun targetCandidates(part: Subscription, mode: ApMode): List<Pair<TargetSummary, Int>> =
        synchronized(lock) { published.targetCandidates(part, mode) }

    fun staticTargetCandidates(): List<Pair<TargetSummary, Int>> =
        synchronized(lock) { published.staticTargetCandidates() }

    fun addSubscriber(subscriber: SubscriptionManager) {
        ap.cancellation.checkpoint()
        synchronized(lock) { checkNotNull(publishedIndex) { "Summary storage is sealed" }; subscribers.add(subscriber) }
    }

    fun candidates(part: Subscription, mode: ApMode): List<Pair<Publication, Int>> =
        synchronized(lock) { published.candidates(part, mode) }

    fun staticCandidates(): List<Pair<Publication, Int>> = synchronized(lock) { published.staticCandidates() }

    /** Detach each shared subscriber exactly once through the enclosing lease. */
    internal fun detachJoinedSubscribers(detach: (SubscriptionManager) -> JoinedCallerInputs): List<JoinedCallerInputs> =
        synchronized(lock) {
            checkNotNull(publishedIndex) { "Summary storage was already sealed" }
            try { subscribers.map(detach) }
            finally { publishedIndex = null; requestRows = null; subscribers.clear() }
        }

    internal fun releaseStopped() = synchronized(lock) {
        publishedIndex = null
        requestRows = null
        subscribers.clear()
    }

    /** Borrow the existing subscriber index only after all runners join. The
     * storage lock is released before inspecting caller-owned immutable inputs. */
    internal fun visitJoinedInputs(writer: Publication, mode: ApMode, visit: (Subscription) -> Unit) {
        check(mode.run1 && writer.premise is org.opentaint.dataflow.bidi.ap.InitialAp)
        val recipients = synchronized(lock) { checkNotNull(publishedIndex) { "Summary storage is sealed" }; subscribers.toList() }
        for (subscriber in recipients) {
            ap.cancellation.checkpoint()
            subscriber.visitJoinedInputs(method, writer, mode, visit)
        }
    }
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.MethodKey
import org.opentaint.dataflow.bidi.ap.PremiseKey
import org.opentaint.dataflow.bidi.store.BlockScope

@JvmInline value class ReportId(val value: Int)

/** Terminal observations have no AP geometry and never become method facts. */
sealed interface Target {
    data class NormalTarget(val id: ReportId) : Target
    data object DemandTarget : Target
}

data class TargetSummary(val premise: PremiseKey, val target: Target)
data class OwnedNormalTarget(val method: MethodKey, val premise: PremiseKey, val id: ReportId,
                             val scope: BlockScope? = null)
typealias TargetBatch = List<TargetSummary>

/** The existing static continuation can carry an AP image or a terminal result. */
sealed interface StaticCallResult {
    data class Ap(val publication: Publication) : StaticCallResult
    data class Terminal(val summary: TargetSummary) : StaticCallResult
    val premise: PremiseKey get() = when (this) {
        is Ap -> publication.premise
        is Terminal -> summary.premise
    }
}

fun interface TargetPublicationSink {
    fun publishTargets(method: MethodKey, batch: TargetBatch)
}

interface TargetApplier {
    fun applyTarget(part: Subscription, row: TargetSummary, member: Int) {
        error("This summary applier does not support terminal results")
    }
    fun applyStaticTarget(part: Subscription, row: TargetSummary, member: Int) {
        error("This summary applier does not support static terminal results")
    }
}

package org.opentaint.dataflow.bidi.engine

import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.channels.Channel
import kotlinx.coroutines.coroutineScope
import kotlinx.coroutines.isActive
import kotlinx.coroutines.yield
import mu.KLogging
import org.opentaint.dataflow.bidi.ap.MethodKey
import org.opentaint.dataflow.bidi.ap.Facts
import org.opentaint.dataflow.bidi.ap.AdmittedInitial
import org.opentaint.dataflow.bidi.ap.Layer
import org.opentaint.dataflow.bidi.store.CallerRef
import org.opentaint.dataflow.ifds.UnitType
import org.opentaint.dataflow.util.Cancellation
import java.util.Collections
import java.util.IdentityHashMap
import java.util.concurrent.atomic.AtomicBoolean

/** One coroutine owns the actors, local queue and queued-work set of a unit. */
class UnitRunner<A : RunActor> internal constructor(
    val unit: UnitType,
    private val run: RunManager<A>,
    factory: RunnerHandlerFactory<A>,
    private val quantum: Int,
) : RunnerPort<A> {
    private val channel = Channel<RunEvent>(Channel.UNLIMITED)
    private val queue = EventQueue()
    private val actors = LinkedHashMap<MethodKey, A>()
    private val queued = Collections.newSetFromMap(IdentityHashMap<A, Boolean>())
    private val closed = AtomicBoolean()
    private val handler = factory.create(this)

    override val config get() = run.config
    override val shared get() = run.shared
    override val forms get() = run.forms
    override val ops get() = shared.ops
    override val steps get() = run.steps
    override val staticService get() = run.staticService

    internal fun postEvent(event: RunEvent): Boolean = run.accept {
        !closed.get() && channel.trySend(event).isSuccess
    }

    override fun post(event: RunEvent.TargetDelivery): Boolean = postEvent(event)
    override fun post(event: RunEvent.Delivery): Boolean = postEvent(event)
    override fun post(event: RunEvent.ChangedRequests): Boolean = postEvent(event)
    override fun send(event: RunEvent): Boolean = run.route(event)

    override fun summaryStorage(key: MethodKey): SummaryStorage = run.summaryStorage(key)

    override fun subscribe(sub: Subscription) {
        if (!org.opentaint.dataflow.bidi.ap.RuntimeDataDomain.packet(sub.ref.premise, sub.added)) return
        check(!run.ended && !closed.get()) { "The runner is closed" }
        check(org.opentaint.dataflow.bidi.interp.predefinedSummary(sub.callee.method) == null) {
            "A complete predefined target has no summary subscription"
        }
        shared.cancellation.checkpoint()
        val subscriptions = handler as? SubscriptionHandler
            ?: error("The runner handler does not support method subscriptions")
        subscriptions.subscribe(sub)
    }

    override fun link(callee: MethodKey, ref: CallerRef, linkLayer: Layer, added: Facts) {
        if (!org.opentaint.dataflow.bidi.ap.RuntimeDataDomain.packet(ref.premise, added)) return
        check(!run.ended && !closed.get()) { "The runner is closed" }
        shared.cancellation.checkpoint()
        val event = RunEvent.LinkIn(callee, ref, linkLayer, added)
        if (shared.unitResolver.resolve(callee.method) == unit) handler.handle(event)
        else send(event)
    }

    override fun startInitials(callee: MethodKey, initials: Collection<AdmittedInitial>) {
        check(!run.ended && !closed.get()) { "The runner is closed" }
        check(config.restricted) { "Completed initial delivery is for restricted runs" }
        shared.cancellation.checkpoint()
        val valid = initials.filter { org.opentaint.dataflow.bidi.ap.RuntimeDataDomain.initial(it.initial) }
        if (valid.isEmpty()) return
        val event = RunEvent.InitialsIn(callee, valid)
        if (shared.unitResolver.resolve(callee.method) == unit) handler.handle(event)
        else {
            val accepted = send(event)
            shared.cancellation.checkpoint()
            check(accepted) { "An active run rejected initial delivery" }
        }
    }

    override fun analyzer(key: MethodKey): A {
        check(!run.ended && !closed.get()) { "The runner is closed" }
        check(shared.unitResolver.resolve(key.method) == unit) { "$key is not in $unit" }
        check(org.opentaint.dataflow.bidi.interp.predefinedSummary(key.method) == null) {
            "A complete predefined target has no method actor: $key"
        }
        return actors.getOrPut(key) {
            handler.createActor(key).also { check(it.key == key) { "The actor has a different method key" } }
        }
    }

    override fun enqueue(analyzer: A): Boolean {
        if (run.ended || closed.get()) return false
        check(actors[analyzer.key] === analyzer) { "Work requires this runner's exact actor" }
        if (analyzer in queued) return false
        return run.accept {
            if (closed.get()) false
            else {
                check(queued.add(analyzer))
                try { queue.add(RunEvent.Work(analyzer)) }
                catch (e: Throwable) { queued.remove(analyzer); throw e }
                true
            }
        }
    }

    internal suspend fun runLoop() {
        try {
            coroutineScope {
                var events = 0
                while (isActive && !run.ended) {
                    shared.cancellation.checkpoint()
                    if (queue.isEmpty()) queue.add(channel.receive())
                    while (true) queue.add(channel.tryReceive().getOrNull() ?: break)
                    if (run.ended) break
                    val event = checkNotNull(queue.poll())
                    val complete = if (event is RunEvent.Work) {
                        check(actors[event.analyzer.key] === event.analyzer) { "Work belongs to another runner" }
                        event.analyzer.work(quantum)
                    } else {
                        handler.handle(event)
                        true
                    }
                    if (complete) {
                        if (event is RunEvent.Work) {
                            check(queued.remove(event.analyzer)) { "Work was not queued" }
                        }
                        run.afterHandler()
                    } else {
                        // The same reservation remains live; priority is sampled again.
                        queue.add(event)
                    }
                    if (event is RunEvent.Work || ++events >= quantum) {
                        events = 0
                        yield()
                    }
                }
            }
        } catch (e: Cancellation.Cancelled) {
            if (!run.ended) run.fail(RunStatus.FAILED)
        } catch (e: CancellationException) {
            if (!run.ended) run.fail(RunStatus.FAILED)
        } catch (e: Throwable) {
            logger.error(e) { "Runner $unit failed in run ${config.index}" }
            run.fail(RunStatus.FAILED)
        }
    }

    fun close() {
        closed.set(true)
        channel.cancel()
    }

    /** The manager reads and releases these collections only after a successful join. */
    internal fun analyzers(): List<A> = actors.values.toList()
    internal fun release() {
        try {
            (handler as? SubscriptionHandler)?.freeze()
        } finally {
            queue.clear()
            queued.clear()
            for (actor in actors.values) (actor as? RunMethodAnalyzer)?.releaseAbstraction()
            actors.clear()
        }
    }

    companion object : KLogging()
}

package org.opentaint.dataflow.bidi.interp

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.Cleaner
import org.opentaint.dataflow.bidi.ap.MarkSet
import org.opentaint.dataflow.bidi.ap.TaintMark
import org.opentaint.dataflow.util.Cancellation
import org.opentaint.dataflow.bidi.ap.GroupId
import org.opentaint.dataflow.bidi.ap.Layer
import org.opentaint.dataflow.bidi.ap.MarkTable
import org.opentaint.dataflow.bidi.ap.MethodKey
import org.opentaint.ir.api.common.CommonMethod
import java.util.AbstractMap.SimpleImmutableEntry

enum class CallPoint { BEFORE, BOUND, ADDED, RETURNED, REWRITTEN, AFTER }

/** Stage kind selects source places, statement edges and identity-candidate updates. */
enum class StageKind {
    BIND_IN, END_FACTS, SOURCES, UNRESOLVED, CONSTRUCTOR, BIND_BACK, ALIASES, PASS_OVER;

    val statementEdges: Boolean get() = this == SOURCES || this == UNRESOLVED
}

/** Null means no producing stage has classified this result. Other stages preserve that state. */
fun StageKind.identityCandidateOf(me: MicroEdge?, prev: Boolean?): Boolean? = when (this) {
    StageKind.SOURCES, StageKind.END_FACTS -> false
    StageKind.UNRESOLVED -> me?.isIdentity == true
    StageKind.CONSTRUCTOR -> true
    else -> prev
}

/** Forward stage selection. Reversed end facts retain the sink as a trigger, without selecting inputs. */
sealed interface Guard {
    class SinkTriggered(val sink: SinkRule) : Guard

    data object MemoryEffect : Guard {
        fun admits(identityCandidate: Boolean, layer: Layer): Boolean = layer == Layer.DEMAND || !identityCandidate

        /** Run-1 NoMemoryEffect has no DEMAND bypass. Unknown is conservative.
         * Later FULL/native calls keep their existing classifier and guard. */
        fun admits(run1: Boolean, noEffect: Boolean?, layer: Layer): Boolean =
            if (run1) noEffect != true else admits(checkNotNull(noEffect), layer)
    }
}

private data class ReturnGroupKey(val base: AccessPathBase, val group: GroupId)

private fun returnGroupKey(step: CleanStep, marks: MarkTable): ReturnGroupKey? {
    val cleaner = (step as? CleanStep.Clean)?.cleaner ?: return null
    when (cleaner.base) {
        AccessPathBase.Zero, AccessPathBase.ClassStatic -> return null
        is AccessPathBase.CleanerTemporary -> return null
        else -> Unit
    }
    val atom = cleaner.mark ?: return null
    val group = marks.groupId(atom) ?: return null
    return ReturnGroupKey(cleaner.base, group)
}

/** Raw indices stay stable; each invocation selects the first equal key in its own suffix. */
internal class ReturnGroupSchedule private constructor(private val previous: IntArray) {
    val size: Int get() = previous.size
    fun execute(step: Int, firstStep: Int): Boolean = previous[step] < firstStep
    fun storage(counts: FormStorageCounts) { counts.index(previous) }

    companion object {
        fun compile(raw: List<CleanStep>, marks: MarkTable): ReturnGroupSchedule? {
            val previous = IntArray(raw.size) { -1 }
            val last = HashMap<ReturnGroupKey, Int>()
            var hasDuplicate = false
            raw.forEachIndexed { index, step ->
                val key = returnGroupKey(step, marks)
                if (key == null) last.clear()
                else {
                    previous[index] = last.put(key, index) ?: -1
                    hasDuplicate = hasDuplicate || previous[index] >= 0
                }
            }
            return if (hasDuplicate) ReturnGroupSchedule(previous) else null
        }
    }
}

/** One immutable mask per maximal range. Raw steps are retained for invocation-local suffixes. */
internal class FullCleanupBlock(
    val first: Int,
    val end: Int,
    val geometry: Cleaner,
    val marks: MarkSet,
    private val raw: List<CleanStep>,
) {
    fun marksFrom(firstStep: Int, cancellation: Cancellation? = null): MarkSet {
        require(firstStep in first until end)
        if (firstStep == first) return marks
        val selected = IntArray(end - firstStep)
        for (index in firstStep until end) {
            cancellation?.checkpoint()
            selected[index - firstStep] = checkNotNull((raw[index] as CleanStep.Clean).cleaner.mark).id
        }
        return MarkSet(selected)
    }
}

/** Linear raw-index directory. Rebuilding a form does not change resume addresses. */
internal class ReturnFullCleanupSchedule private constructor(
    private val blocks: List<FullCleanupBlock>,
    private val byStep: IntArray,
) {
    fun blockContaining(step: Int): FullCleanupBlock? =
        byStep.getOrNull(step)?.takeIf { it >= 0 }?.let { blocks[it] }

    fun storage(counts: FormStorageCounts) {
        counts.index(byStep)
        counts.include(blocks)
        for (block in blocks) counts.index(block.marks.data)
    }

    companion object {
        fun compile(raw: List<CleanStep>, marks: MarkTable): ReturnFullCleanupSchedule? {
            fun eligible(step: CleanStep): Cleaner? {
                val cleaner = (step as? CleanStep.Clean)?.cleaner ?: return null
                if (cleaner.base == AccessPathBase.Zero || cleaner.base == AccessPathBase.ClassStatic ||
                    cleaner.base is AccessPathBase.CleanerTemporary) return null
                val mark = cleaner.mark ?: return null
                return cleaner.takeIf { marks.isFull(mark) }
            }
            fun same(a: Cleaner, b: Cleaner) = a.base == b.base && a.reach == b.reach &&
                a.pathArray.contentEquals(b.pathArray)
            val blocks = ArrayList<FullCleanupBlock>()
            val byStep = IntArray(raw.size) { -1 }
            var start = 0
            while (start < raw.size) {
                val geometry = eligible(raw[start])
                if (geometry == null) { start++; continue }
                var end = start + 1
                while (end < raw.size) {
                    val next = eligible(raw[end]) ?: break
                    if (!same(geometry, next)) break
                    end++
                }
                if (end - start >= 2) {
                    val mask = MarkSet(IntArray(end - start) { index ->
                        checkNotNull((raw[start + index] as CleanStep.Clean).cleaner.mark).id
                    })
                    for (index in start until end) byStep[index] = blocks.size
                    blocks += FullCleanupBlock(start, end, geometry, mask, raw)
                }
                start = end
            }
            return if (blocks.isEmpty()) null else ReturnFullCleanupSchedule(ownedList(blocks), byStep)
        }
    }
}

sealed interface CallStage {
    val from: CallPoint
    val to: CallPoint
    fun reversed(): CallStage

    /** A summary is applied in STAGE mode. A backward trigger fires after an end-fact edge gives a result. */
    data class Edges(
        override val from: CallPoint,
        override val to: CallPoint,
        val kind: StageKind,
        val summary: StatementSummary,
        val guard: Guard? = null,
        val trigger: SinkRule? = null,
    ) : CallStage {
        init {
            check(trigger == null || (kind == StageKind.END_FACTS && guard == null)) {
                "A backward sink trigger belongs to an unguarded END_FACTS stage"
            }
        }

        override fun reversed(): Edges = Edges(to, from, kind, summary.reversed(), guard = null,
            trigger = (guard as? Guard.SinkTriggered)?.sink)
    }

    /** Cleaners and the rewriter keep one ordered, immutable action chain. */
    class Actions private constructor(
        override val from: CallPoint,
        override val to: CallPoint,
        val steps: List<CleanStep>,
        internal val returnGroupSchedule: ReturnGroupSchedule?,
        internal val returnFullCleanupSchedule: ReturnFullCleanupSchedule?,
    ) : CallStage {
        constructor(from: CallPoint, to: CallPoint, steps: List<CleanStep>) :
            this(from, to, ownedList(steps), null, null)

        companion object {
            /** FULL forms may be shared by later runs; only the run-1 owner executes this metadata. */
            fun run1FullReturnRewriter(steps: List<CleanStep>, marks: MarkTable): Actions {
                val raw = ownedList(steps)
                return Actions(CallPoint.RETURNED, CallPoint.REWRITTEN, raw, null,
                    ReturnFullCleanupSchedule.compile(raw, marks))
            }

            /** Only forward GROUP return rewriters use this factory, after ordinary lowering. */
            fun run1GroupReturnRewriter(steps: List<CleanStep>, marks: MarkTable): Actions {
                val raw = ownedList(steps)
                return Actions(CallPoint.RETURNED, CallPoint.REWRITTEN, raw,
                    ReturnGroupSchedule.compile(raw, marks), null)
            }
        }

        override fun reversed(): Actions = Actions(to, from, steps.asReversed().map { it.reversed() })

        override fun equals(other: Any?): Boolean = this === other ||
            (other is Actions && from == other.from && to == other.to && steps == other.steps)

        override fun hashCode(): Int = (from.hashCode() * 31 + to.hashCode()) * 31 + steps.hashCode()
    }

    /** Callee keys remain the same objects when the graph reverses. */
    class Callees(override val from: CallPoint, override val to: CallPoint, callees: List<MethodKey>) : CallStage {
        val callees: List<MethodKey> = ownedList(callees)

        override fun reversed(): Callees = Callees(to, from, callees)

        override fun equals(other: Any?): Boolean = this === other ||
            (other is Callees && from == other.from && to == other.to && callees == other.callees)

        override fun hashCode(): Int = (from.hashCode() * 31 + to.hashCode()) * 31 + callees.hashCode()
    }

    /** The caller applies this complete relation without an actor or subscription. */
    data class Predefined(
        override val from: CallPoint,
        override val to: CallPoint,
        val target: CommonMethod,
        val model: CompleteMethodSummary,
        val summary: StatementSummary,
    ) : CallStage {
        override fun reversed(): Predefined = Predefined(to, from, target, model.reversed(), summary.reversed())
    }
}

/** Cached call graph. passReads is observer metadata and does not affect propagation. */
class CallPlan(
    touched: Set<AccessPathBase>,
    stages: List<CallStage>,
    sinks: List<SinkRule>,
    val entry: CallPoint,
    val exit: CallPoint,
    passReads: Set<AccessPathBase> = emptySet(),
    val zeroCanReturn: Boolean = true,
) {
    val touched: Set<AccessPathBase> = ownedSet(touched)
    val stages: List<CallStage> = ownedList(stages)
    val sinks: List<SinkRule> = ownedList(sinks)
    val passReads: Set<AccessPathBase> = ownedSet(passReads)

    /** Every stage from a point reads the same input facts. */
    val stagesFrom: Map<CallPoint, List<CallStage>> = pointDirectory(this.stages)

    fun stagesAt(point: CallPoint): List<CallStage> = stagesFrom[point].orEmpty()

    internal fun storage(counts: FormStorageCounts) {
        counts.callPlans++
        counts.include(touched)
        counts.include(stages)
        counts.include(sinks)
        counts.include(passReads)
        counts.callPointDirectoryEntries += stagesFrom.size.toLong()
        if (stagesFrom is CallPointDirectory) stagesFrom.storage(counts)
        else ownedDirectoryStorage(stagesFrom, counts)
        for (stage in stages) when (stage) {
            is CallStage.Edges -> {
                counts.include(stage.summary)
                (stage.guard as? Guard.SinkTriggered)?.let { counts.include(it.sink) }
                stage.trigger?.let(counts::include)
            }
            is CallStage.Actions -> {
                counts.include(stage.steps)
                stage.returnGroupSchedule?.storage(counts)
                stage.returnFullCleanupSchedule?.storage(counts)
                for (step in stage.steps) when (step) {
                    is CleanStep.Clean -> Unit
                    is CleanStep.Kill -> counts.include(step.keepEdges)
                    is CleanStep.Field -> { counts.include(step.read); counts.include(step.write) }
                }
            }
            is CallStage.Callees -> counts.include(stage.callees)
            is CallStage.Predefined -> {
                counts.include(stage.summary)
                counts.include(stage.model.normal)
                counts.include(stage.model.exceptional)
                counts.include(stage.model.touched)
                for (schema in stage.model.normal) if (schema is SummarySchema.PrefixFlowIdentity)
                    counts.include(schema.prefix)
            }
        }
        for (sink in sinks) counts.include(sink)
    }

    fun reversed(): CallPlan {
        check(entry == CallPoint.BEFORE && exit == CallPoint.AFTER) { "The core reverses only a forward plan" }
        val exitTargets = stages.filter { it.to == exit }.filterIsInstance<CallStage.Edges>()
            .flatMap { it.summary.targets }
        val aliasBases = passOverBases(exitTargets, touched)
        val reversed = stages.mapTo(ArrayList()) { it.reversed() }
        if (aliasBases.isNotEmpty()) {
            reversed += CallStage.Edges(CallPoint.AFTER, CallPoint.BEFORE, StageKind.PASS_OVER,
                StatementSummary.identities(aliasBases))
        }
        return CallPlan(touched + aliasBases, reversed, sinks, entry = exit, exit = entry, passReads = passReads,
            zeroCanReturn = zeroCanReturn)
    }
}

private fun pointDirectory(stages: List<CallStage>): Map<CallPoint, List<CallStage>> {
    val groups = ownedOrdinalGroups(stages) { it.from }
    return if (groups.size <= 1) groups else CallPointDirectory(groups)
}

/** Fixed six-point lookup; compatibility iteration keeps the first stage's point order. */
private class CallPointDirectory(groups: Map<CallPoint, List<CallStage>>) : AbstractMap<CallPoint, List<CallStage>>() {
    override val size: Int = groups.size
    private val pointOrder = IntArray(size)
    private val byOrdinal = arrayOfNulls<List<CallStage>>(CallPoint.entries.size)
    @Volatile private var entryView: Set<Map.Entry<CallPoint, List<CallStage>>>? = null

    init {
        var index = 0
        for ((point, stages) in groups) {
            pointOrder[index++] = point.ordinal
            byOrdinal[point.ordinal] = stages
        }
    }

    override fun get(key: CallPoint): List<CallStage>? = byOrdinal[key.ordinal]
    override fun containsKey(key: CallPoint): Boolean = byOrdinal[key.ordinal] != null

    fun storage(counts: FormStorageCounts) {
        counts.ownedContainerEntries += byOrdinal.size.toLong()
        counts.index(pointOrder)
        for (group in byOrdinal) if (group != null) counts.include(group)
    }

    override val entries: Set<Map.Entry<CallPoint, List<CallStage>>>
        get() = entryView ?: object : AbstractSet<Map.Entry<CallPoint, List<CallStage>>>() {
            override val size: Int get() = this@CallPointDirectory.size
            override fun iterator(): Iterator<Map.Entry<CallPoint, List<CallStage>>> =
                object : Iterator<Map.Entry<CallPoint, List<CallStage>>> {
                    private var next = 0
                    override fun hasNext(): Boolean = next < size
                    override fun next(): Map.Entry<CallPoint, List<CallStage>> {
                        if (!hasNext()) throw NoSuchElementException()
                        val ordinal = pointOrder[next++]
                        return SimpleImmutableEntry(CallPoint.entries[ordinal], checkNotNull(byOrdinal[ordinal]))
                    }
                }
        }.also { entryView = it }
}

package org.opentaint.dataflow.bidi.interp

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.ConjunctiveEdge
import org.opentaint.dataflow.bidi.ap.TypeFilter
import org.opentaint.dataflow.bidi.ap.Layer
import org.opentaint.ir.api.common.cfg.CommonInst

/** The place controls statement-only requests and source-seed hooks. */
data class Place(val node: CommonInst, val statementEdge: Boolean, val sources: Boolean,
                 val site: ResumeSite? = null, val staticOperations: List<StaticOperation> = emptyList(),
                 val callerLayer: Layer? = null, val identityCandidate: Boolean? = null,
                 val pendingDemotion: Boolean = false,
                 val completedAction: ActionId? = null,
                 val completedConjunction: ConjunctiveEdge? = null)

/** Accepted raw source application, before downstream result filtering. */
data class AcceptedSource<P,F>(val at: Place, val edge: MicroEdge,
                               val original: P, val input: F,
                               val resultPremise: P, val rawResult: F)

/** One implementation of form application for tree and per-path fact algebras. */
interface FactAlgebra<P, F> {
    fun base(c: F): AccessPathBase
    fun filter(c: F, filter: TypeFilter): F?
    fun filtered(premise: P, before: F, after: F) = Unit
    fun operationResult(me: MicroEdge?, premise: P, input: F, result: F, at: Place, out: (P, F) -> Unit) = out(premise, result)
    fun applyEdge(me: MicroEdge, c: F, premise: P, statementEdge: Boolean, out: (P, F) -> Unit)
    fun reached(s: StatementSummary, premise: P, c: F, at: Place) = Unit
    fun applyEdgeAt(me: MicroEdge, c: F, premise: P, at: Place, out: (P, F) -> Unit) =
        applyEdge(me, c, premise, at.statementEdge, out)
    fun conjunction(cj: ConjunctiveEdge, premise: P, c: F, node: CommonInst, out: (P, F) -> Unit)
    fun conjunctionAt(cj: ConjunctiveEdge, premise: P, c: F, at: Place, out: (P, F) -> Unit) =
        conjunction(cj, premise, c, at.node, out)
    fun sourcePredicate(source: SourceRuleOccurrence, premise: P, c: F, node: CommonInst,
                        statementEdge: Boolean, out: (P, F) -> Unit) {
        error("This fact algebra does not implement rule predicates")
    }
    fun sourcePredicateAt(source: SourceRuleOccurrence, premise: P, c: F, at: Place, out: (P, F) -> Unit) =
        sourcePredicate(source, premise, c, at.node, at.statementEdge, out)
    /** Invocation-only action identity survives the result filter. Legacy
     * algebras keep their existing source callback and operation behavior. */
    fun sourcePredicateActionsAt(source: SourceRuleOccurrence, premise: P, c: F, at: Place,
                                 out: (P, F, ActionId?) -> Unit) =
        sourcePredicateAt(source, premise, c, at) { pr, result -> out(pr, result, null) }
    fun allowsSource(node: CommonInst, me: MicroEdge): Boolean
    fun acceptedSource(application: AcceptedSource<P, F>)
}

class FormApplier<P, F>(private val alg: FactAlgebra<P, F>) {
    /** An untouched input passes unchanged; conjunction literals can still read it. */
    fun statement(s: StatementSummary, premise: P, c: F, at: Place, sink: (P, F) -> Unit,
                  untouched: (P, F) -> Unit = sink) {
        alg.reached(s, premise, c, at.copy(staticOperations = s.staticOperations))
        if (alg.base(c) !in s.touched) {
            for (cj in s.conjunctions) conjunction(s, cj, premise, c, at, sink)
            for (source in s.sources) source(s, source, premise, c, at, sink)
            untouched(premise, c)
            return
        }
        stage(s, premise, c, at) { pr, result, _ -> sink(pr, result) }
    }

    /** A stage emits generated results, with the edge that made each plain result. */
    fun stage(s: StatementSummary, premise: P, c: F, at: Place, emit: (P, F, MicroEdge?) -> Unit) {
        val place = at.copy(staticOperations = s.staticOperations)
        alg.reached(s, premise, c, place)
        val input = filterBy(s.typeFilters, premise, c) ?: return
        for (me in s.edgesOf(alg.base(input))) {
            micro(me, input, premise, place) { pr, result ->
                filterBy(s.resultFilters, pr, result)?.let { filtered ->
                    alg.operationResult(me, pr, input, filtered, place) { outputPremise, output -> emit(outputPremise, output, me) }
                }
            }
        }
        for (cj in s.conjunctions) conjunction(s, cj, premise, input, place) { pr, result -> emit(pr, result, null) }
        for (source in s.sources) source(s, source, premise, input, place) { pr, result -> emit(pr, result, null) }
    }

    /** GEN adds results. Its caller retains the input and handles end-fact triggers. */
    fun gen(edges: List<MicroEdge>, premise: P, c: F, sink: (P, F) -> Unit) {
        for (me in edges) if (me.edge.from.base == alg.base(c))
            alg.applyEdge(me, c, premise, statementEdge = false, sink)
    }

    private fun conjunction(s: StatementSummary, cj: ConjunctiveEdge, premise: P, c: F,
                            at: Place, sink: (P, F) -> Unit) {
        alg.conjunctionAt(cj, premise, c, at.copy(staticOperations = s.staticOperations)) { pr, result ->
            filterBy(s.resultFilters, pr, result)?.let { filtered ->
                alg.operationResult(null, pr, c, filtered,
                    at.copy(staticOperations = s.staticOperations, completedConjunction = cj), sink)
            }
        }
    }

    private fun source(s: StatementSummary, source: SourceRuleOccurrence, premise: P, c: F,
                       at: Place, sink: (P, F) -> Unit) {
        alg.sourcePredicateActionsAt(source, premise, c, at.copy(staticOperations = s.staticOperations)) { pr, result, action ->
            filterBy(s.resultFilters, pr, result)?.let { filtered ->
                alg.operationResult(null, pr, c, filtered,
                    at.copy(staticOperations = s.staticOperations, completedAction = action), sink)
            }
        }
    }

    private fun filterBy(filters: Map<AccessPathBase, TypeFilter>, premise: P, c: F): F? {
        val filter = filters[alg.base(c)] ?: return c
        return alg.filter(c, filter)?.also { alg.filtered(premise, c, it) }
    }

    /** A source hit precedes the first downstream callback, including result filtering. */
    private fun micro(me: MicroEdge, c: F, premise: P, at: Place, sink: (P, F) -> Unit) {
        val source = at.sources && me.isSource
        if (source && !alg.allowsSource(at.node, me)) return
        var hit = !source
        alg.applyEdgeAt(me, c, premise, at) { pr, result ->
            if (!hit) { hit = true; alg.acceptedSource(AcceptedSource(at, me, premise, c, pr, result)) }
            sink(pr, result)
        }
    }
}

package org.opentaint.dataflow.bidi.interp

import java.util.concurrent.atomic.AtomicLong

/** Optional analysis-wide aggregates. Counters never retain forms, slots or builder callbacks. */
class FormCacheStatistics {
    private val accesses = AtomicLong()
    private val hits = AtomicLong()
    private val buildAttempts = AtomicLong()
    private val buildSuccesses = AtomicLong()
    private val buildFailures = AtomicLong()
    private val reversals = AtomicLong()
    private val reversalFailures = AtomicLong()
    private val uncachedBuilds = AtomicLong()
    private val buildNanos = AtomicLong()
    private val reversalNanos = AtomicLong()
    private val activePins = AtomicLong()
    private val peakPins = AtomicLong()
    private val compiledPredicates = AtomicLong()
    private val compiledNodes = AtomicLong()
    private val compiledLeaves = AtomicLong()
    private val observedProofRecords = AtomicLong()
    private val observedSupportShapes = AtomicLong()
    private val supportGrowthUpdates = AtomicLong()
    private val newRootOutcomes = AtomicLong()
    private val rootGrowthOutcomes = AtomicLong()
    private val rootOutcomes = AtomicLong()
    private val forwardFormShapes = AtomicLong()
    private val reversedFormShapes = AtomicLong()
    private val statementSummaries = AtomicLong()
    private val callPlans = AtomicLong()
    private val ruleStatements = AtomicLong()
    private val exitRules = AtomicLong()
    private val ownedContainerEntries = AtomicLong()
    private val primitiveIndexCells = AtomicLong()
    private val summaryBaseDirectoryEntries = AtomicLong()
    private val callPointDirectoryEntries = AtomicLong()

    internal fun access() { accesses.incrementAndGet() }
    internal fun hit() { hits.incrementAndGet() }
    internal fun startBuild(): Long { buildAttempts.incrementAndGet(); return System.nanoTime() }
    internal fun finishBuild(start: Long, success: Boolean, cached: Boolean) {
        buildNanos.addAndGet((System.nanoTime() - start).coerceAtLeast(0))
        if (success) {
            buildSuccesses.incrementAndGet()
            if (!cached) uncachedBuilds.incrementAndGet()
        } else buildFailures.incrementAndGet()
    }
    internal fun startReversal(): Long { reversals.incrementAndGet(); return System.nanoTime() }
    internal fun finishReversal(start: Long, success: Boolean) {
        reversalNanos.addAndGet((System.nanoTime() - start).coerceAtLeast(0))
        if (!success) reversalFailures.incrementAndGet()
    }
    internal fun pin() {
        val current = activePins.incrementAndGet()
        peakPins.accumulateAndGet(current, ::maxOf)
    }
    internal fun unpin() { activePins.decrementAndGet() }

    /** Compilation totals include rebuilds and constants; they are not a live payload census. */
    fun compiledPredicate(nodes: Int, leaves: Int) {
        compiledPredicates.incrementAndGet()
        compiledNodes.addAndGet(nodes.toLong())
        compiledLeaves.addAndGet(leaves.toLong())
    }

    /** Runtime totals across actor stores and runs, separate from compiled potential structure.
     *  A proof record is newly interned; a support shape is first stored at a logical node.
     *  Growth updates an existing stored shape. Root counts follow canonical deduplicated outcomes.
     *  These totals do not fall when stores freeze and are not a live or peak retained-object census. */
    internal fun observedProof() { observedProofRecords.incrementAndGet() }
    internal fun observedSupport() { observedSupportShapes.incrementAndGet() }
    internal fun supportGrowth() { supportGrowthUpdates.incrementAndGet() }
    internal fun rootOutcome(growth: Boolean) {
        if (growth) rootGrowthOutcomes.incrementAndGet() else newRootOutcomes.incrementAndGet()
        rootOutcomes.incrementAndGet()
    }

    /** Cumulative samples after successful known forward/reversed form builds, including rebuilds.
     *  Shared structural containers/index arrays count once within a sample and again in later
     *  samples. These are stored reference/index cells, not new allocations, live sizes or bytes.
     *  AP/IR contents and predicate graphs are opaque; no compatibility view is initialized. */
    internal fun formBuilt(form: Any, reversed: Boolean) {
        if (form !is StatementSummary && form !is CallPlan && form !is RuleStatement && form !is ExitRules) return
        val counts = FormStorageCounts()
        counts.measure(form)
        if (reversed) reversedFormShapes.incrementAndGet() else forwardFormShapes.incrementAndGet()
        statementSummaries.addAndGet(counts.statementSummaries)
        callPlans.addAndGet(counts.callPlans)
        ruleStatements.addAndGet(counts.ruleStatements)
        exitRules.addAndGet(counts.exitRules)
        ownedContainerEntries.addAndGet(counts.ownedContainerEntries)
        primitiveIndexCells.addAndGet(counts.primitiveIndexCells)
        summaryBaseDirectoryEntries.addAndGet(counts.summaryBaseDirectoryEntries)
        callPointDirectoryEntries.addAndGet(counts.callPointDirectoryEntries)
    }

    data class Snapshot(
        val accesses: Long, val hits: Long,
        val buildAttempts: Long, val buildSuccesses: Long, val buildFailures: Long,
        val reversals: Long, val reversalFailures: Long, val uncachedBuilds: Long,
        val buildNanos: Long, val reversalNanos: Long, val activePins: Long, val peakPins: Long,
        val compiledPredicates: Long, val compiledNodes: Long, val compiledLeaves: Long,
        val observedProofRecords: Long, val observedSupportShapes: Long, val supportGrowthUpdates: Long,
        val newRootOutcomes: Long, val rootGrowthOutcomes: Long, val rootOutcomes: Long,
        val forwardFormShapes: Long, val reversedFormShapes: Long,
        val statementSummaries: Long, val callPlans: Long, val ruleStatements: Long, val exitRules: Long,
        val ownedContainerEntries: Long, val primitiveIndexCells: Long,
        val summaryBaseDirectoryEntries: Long, val callPointDirectoryEntries: Long,
    )

    fun snapshot(): Snapshot = Snapshot(accesses.get(), hits.get(), buildAttempts.get(), buildSuccesses.get(),
        buildFailures.get(), reversals.get(), reversalFailures.get(), uncachedBuilds.get(), buildNanos.get(),
        reversalNanos.get(), activePins.get(), peakPins.get(), compiledPredicates.get(), compiledNodes.get(),
        compiledLeaves.get(), observedProofRecords.get(), observedSupportShapes.get(), supportGrowthUpdates.get(),
        newRootOutcomes.get(), rootGrowthOutcomes.get(), rootOutcomes.get(),
        forwardFormShapes.get(), reversedFormShapes.get(), statementSummaries.get(), callPlans.get(),
        ruleStatements.get(), exitRules.get(), ownedContainerEntries.get(), primitiveIndexCells.get(),
        summaryBaseDirectoryEntries.get(), callPointDirectoryEntries.get())

    companion object {
        const val PROPERTY = "org.opentaint.bidi.formStatistics"
        fun ifEnabled(): FormCacheStatistics? = if (java.lang.Boolean.getBoolean(PROPERTY)) FormCacheStatistics() else null
    }
}

package org.opentaint.dataflow.bidi.interp

import java.util.IdentityHashMap

/** Scratch for one optional shape sample. Nothing in this collector survives the sample.
 *  Count owned element/key/value reference cells and retained primitive index cells, not object
 *  headers, view objects, AP/IR payloads, compiled predicate topology or heap bytes. */
internal class FormStorageCounts {
    var statementSummaries = 0L
    var callPlans = 0L
    var ruleStatements = 0L
    var exitRules = 0L
    var ownedContainerEntries = 0L
    var primitiveIndexCells = 0L
    var summaryBaseDirectoryEntries = 0L
    var callPointDirectoryEntries = 0L
    private val seen = IdentityHashMap<Any, Boolean>()
    private val work = ArrayDeque<Any>()

    fun include(value: Any) {
        if (seen.put(value, true) == null) work.addLast(value)
    }

    fun index(value: IntArray?) {
        if (value != null && seen.put(value, true) == null) primitiveIndexCells += value.size.toLong()
    }

    fun measure(form: Any) {
        include(form)
        while (work.isNotEmpty()) {
            val value = work.removeLast()
            if (ownedStorage(value, this)) continue
            when (value) {
                is StatementSummary -> value.storage(this)
                is CallPlan -> value.storage(this)
                is RuleStatement -> {
                    ruleStatements++
                    include(value.summary)
                    include(value.endFacts)
                    include(value.sinks)
                    for (sink in value.sinks) include(sink)
                }
                is ExitRules -> {
                    exitRules++
                    include(value.rules)
                    include(value.entryMarks)
                }
                is SinkRule -> {
                    include(value.patterns)
                    include(value.endFacts)
                }
            }
        }
    }
}

package org.opentaint.dataflow.bidi.interp

import org.opentaint.dataflow.bidi.ap.Direction
import org.opentaint.dataflow.bidi.ap.MethodKey
import org.opentaint.ir.api.common.cfg.CommonCallExpr
import org.opentaint.ir.api.common.cfg.CommonInst
import org.opentaint.dataflow.util.SoftReferenceManager
import java.lang.ref.Reference
import java.lang.ref.SoftReference
import java.util.concurrent.atomic.AtomicReferenceArray

/** A later forward run must not reuse the run-1 GROUP payload. */
enum class RuleView { RUN1_GROUP, FULL }

/** Lazy slots retain one reclaimable forward/reverse payload, with one build at a time per slot. */
class FormsCache<F : Any>(
    private val size: Int,
    private val refs: SoftReferenceManager? = null,
    private val statistics: FormCacheStatistics? = null,
    private val reverse: (F) -> F,
) {
    constructor(size: Int, reverse: (F) -> F) : this(size, null, null, reverse)

    init { require(size >= 0) { "A form cache size must be nonnegative" } }
    private val slots = AtomicReferenceArray<FormSlot<F>?>(size)
    private val groupSlots = AtomicReferenceArray<FormSlot<F>?>(size)

    private class FormSlot<F : Any> {
        @Volatile var payload: Reference<ForwardReversePayload<F>>? = null
        var building = false
    }

    private class ForwardReversePayload<F : Any>(val forward: F, private val statistics: FormCacheStatistics?) {
        @Volatile private var backward: F? = null
        private var reversing = false

        fun selected(direction: Direction, reverse: (F) -> F): F {
            if (direction == Direction.FORWARD) return forward
            backward?.let { return it }
            return synchronized(this) {
                backward?.let { return it }
                check(!reversing) { "Recursive reversal of a form slot" }
                reversing = true
                val start = if (statistics != null) statistics.startReversal() else 0L
                var success = false
                try {
                    reverse(forward).also {
                        backward = it
                        success = true
                        statistics?.formBuilt(it, reversed = true)
                    }
                } finally {
                    statistics?.finishReversal(start, success)
                    reversing = false
                }
            }
        }
    }

    private fun formSlot(index: Int, view: RuleView): FormSlot<F> {
        val slots = if (view == RuleView.FULL) this.slots else groupSlots
        slots.get(index)?.let { return it }
        val created = FormSlot<F>()
        return if (slots.compareAndSet(index, null, created)) created else checkNotNull(slots.get(index))
    }

    private fun payload(slot: FormSlot<F>, forward: () -> F): ForwardReversePayload<F> {
        slot.payload?.get()?.let { statistics?.hit(); return it }
        return synchronized(slot) {
            slot.payload?.get()?.let { statistics?.hit(); return it }
            check(!slot.building) { "Recursive construction of a form slot" }
            slot.building = true
            val start = if (statistics != null) statistics.startBuild() else 0L
            var success = false
            var cached = false
            try {
                ForwardReversePayload(forward(), statistics).also {
                    slot.payload = if (refs == null) SoftReference(it) else refs.createRef(it)
                    cached = slot.payload != null
                    success = true
                    statistics?.formBuilt(it.forward, reversed = false)
                }
            } finally {
                statistics?.finishBuild(start, success, cached)
                slot.building = false
            }
        }
    }

    fun <R> withForm(slot: Int, direction: Direction, forward: () -> F, use: (F) -> R): R {
        return withForm(slot, direction, RuleView.FULL, forward, use)
    }

    fun <R> withForm(slot: Int, direction: Direction, view: RuleView, forward: () -> F, use: (F) -> R): R {
        require(slot in 0 until size) { "A form slot must be within the cache" }
        statistics?.access()
        val selectedPayload = payload(formSlot(slot, view), forward)
        statistics?.pin()
        try {
            return use(selectedPayload.selected(direction, reverse))
        } finally {
            Reference.reachabilityFence(selectedPayload)
            statistics?.unpin()
        }
    }

    fun get(slot: Int, direction: Direction, forward: () -> F): F =
        withForm(slot, direction, forward) { it }

    fun get(slot: Int, direction: Direction, view: RuleView, forward: () -> F): F =
        withForm(slot, direction, view, forward) { it }
}

/** Cached language forms retain method and context ownership. */
interface MethodForms {
    /** False certifies identity transfer with no observation or registration on this base. */
    fun isBaseRelevant(direction: Direction, s: CommonInst,
                       base: org.opentaint.dataflow.ap.ifds.AccessPathBase, view: RuleView): Boolean = true
    fun statement(direction: Direction, s: CommonInst): StatementSummary
    fun call(direction: Direction, s: CommonInst, call: CommonCallExpr): CallPlan
    fun entryRules(direction: Direction): RuleStatement
    fun exitRules(direction: Direction, exit: CommonInst): ExitRules

    fun statement(direction: Direction, s: CommonInst, view: RuleView): StatementSummary = statement(direction, s)
    fun call(direction: Direction, s: CommonInst, call: CommonCallExpr, view: RuleView): CallPlan = call(direction, s, call)
    fun entryRules(direction: Direction, view: RuleView): RuleStatement = entryRules(direction)
    fun exitRules(direction: Direction, exit: CommonInst, view: RuleView): ExitRules = exitRules(direction, exit)

    fun <R> withStatement(direction: Direction, s: CommonInst, use: (StatementSummary) -> R): R =
        use(statement(direction, s))
    fun <R> withCall(direction: Direction, s: CommonInst, call: CommonCallExpr, use: (CallPlan) -> R): R =
        use(call(direction, s, call))
    fun <R> withEntryRules(direction: Direction, use: (RuleStatement) -> R): R = use(entryRules(direction))
    fun <R> withExitRules(direction: Direction, exit: CommonInst, use: (ExitRules) -> R): R =
        use(exitRules(direction, exit))

    // Providers with distinct views override these scopes as well as their getters.
    // Compatibility defaults retain existing pin/rebuild hooks for either view.
    fun <R> withStatement(direction: Direction, s: CommonInst, view: RuleView, use: (StatementSummary) -> R): R =
        withStatement(direction, s, use)
    fun <R> withCall(direction: Direction, s: CommonInst, call: CommonCallExpr, view: RuleView, use: (CallPlan) -> R): R =
        withCall(direction, s, call, use)
    fun <R> withEntryRules(direction: Direction, view: RuleView, use: (RuleStatement) -> R): R =
        withEntryRules(direction, use)
    fun <R> withExitRules(direction: Direction, exit: CommonInst, view: RuleView, use: (ExitRules) -> R): R =
        withExitRules(direction, exit, use)
}

/** The run reads forward or reversed cached forms through this direction view. */
class DirectedForms(val interp: Interpreter, val direction: Direction, private val forms: (MethodKey) -> MethodForms,
                    val ruleView: RuleView) {
    constructor(interp: Interpreter, direction: Direction, forms: (MethodKey) -> MethodForms) :
        this(interp, direction, forms, RuleView.FULL)
    private val forward get() = direction == Direction.FORWARD
    fun isBaseRelevant(m: MethodKey, s: CommonInst, base: org.opentaint.dataflow.ap.ifds.AccessPathBase): Boolean =
        forms(m).isBaseRelevant(direction, s, base, ruleView)
    fun startNodes(m: MethodKey, zero: Boolean): List<CommonInst> =
        if (forward) listOf(interp.entryNode(m)) else interp.exitNodes(m).filter { zero || !it.exceptional }.map { it.node }
    fun startRules(m: MethodKey, node: CommonInst): RuleStatement =
        if (forward) entryRules(m, Direction.FORWARD) else exitRules(m, Direction.BACKWARD, node).rules
    fun statement(m: MethodKey, s: CommonInst) = if (ruleView == RuleView.FULL)
        forms(m).statement(direction, s) else forms(m).statement(direction, s, ruleView)
    fun call(m: MethodKey, s: CommonInst, c: CommonCallExpr) = if (ruleView == RuleView.FULL)
        forms(m).call(direction, s, c) else forms(m).call(direction, s, c, ruleView)
    fun endNodes(m: MethodKey): List<CommonInst> =
        if (forward) interp.exitNodes(m).filter { !it.exceptional }.map { it.node } else listOf(interp.entryNode(m))
    fun endRules(m: MethodKey, node: CommonInst): ExitRules =
        if (forward) exitRules(m, Direction.FORWARD, node)
        else ExitRules(entryRules(m, Direction.BACKWARD), globalStateDrop = false, entryMarks = emptySet())

    private fun entryRules(m: MethodKey, d: Direction) = if (ruleView == RuleView.FULL)
        forms(m).entryRules(d) else forms(m).entryRules(d, ruleView)
    private fun exitRules(m: MethodKey, d: Direction, s: CommonInst) = if (ruleView == RuleView.FULL)
        forms(m).exitRules(d, s) else forms(m).exitRules(d, s, ruleView)
    private fun <R> withEntry(m: MethodKey, d: Direction, use: (RuleStatement) -> R): R =
        if (ruleView == RuleView.FULL) forms(m).withEntryRules(d, use) else forms(m).withEntryRules(d, ruleView, use)
    private fun <R> withExit(m: MethodKey, d: Direction, s: CommonInst, use: (ExitRules) -> R): R =
        if (ruleView == RuleView.FULL) forms(m).withExitRules(d, s, use) else forms(m).withExitRules(d, s, ruleView, use)

    fun <R> withStartRules(m: MethodKey, node: CommonInst, use: (RuleStatement) -> R): R =
        if (forward) withEntry(m, Direction.FORWARD, use)
        else withExit(m, Direction.BACKWARD, node) { use(it.rules) }
    fun <R> withStatement(m: MethodKey, s: CommonInst, use: (StatementSummary) -> R): R =
        if (ruleView == RuleView.FULL) forms(m).withStatement(direction, s, use)
        else forms(m).withStatement(direction, s, ruleView, use)
    fun <R> withCall(m: MethodKey, s: CommonInst, c: CommonCallExpr, use: (CallPlan) -> R): R =
        if (ruleView == RuleView.FULL) forms(m).withCall(direction, s, c, use)
        else forms(m).withCall(direction, s, c, ruleView, use)
    fun <R> withEndRules(m: MethodKey, node: CommonInst, use: (ExitRules) -> R): R =
        if (forward) withExit(m, Direction.FORWARD, node, use)
        else withEntry(m, Direction.BACKWARD) {
            use(ExitRules(it, globalStateDrop = false, entryMarks = emptySet()))
        }
}

package org.opentaint.dataflow.bidi.interp

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.ap.ifds.FactTypeChecker
import org.opentaint.dataflow.ap.ifds.access.util.AccessorInterner.Companion.ELEMENT_ACCESSOR_IDX
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.ir.api.common.cfg.CommonInst

/** One per-path result with its premise set. */
typealias ReferenceSink = (Set<Pattern>, Conclusion) -> Unit

/** Reference transfer, filtering and standing source support for one method and run. */
class ReferenceAlgebra(
    private val mode: ApMode,
    request: (Set<Pattern>, ReferenceRequestKind) -> Unit = { _, _ -> },
    allowsSource: (CommonInst, MicroEdge) -> Boolean = { _, _ -> true },
    sourceHit: (CommonInst, MicroEdge) -> Unit = { _, _ -> },
    private val manager: ApManager,
    conjunction: (ConjunctiveEdge, Set<Pattern>, Conclusion, CommonInst, ReferenceSink) -> Unit = { _, _, _, _, _ -> },
    private val historicalRun1: Boolean = false,
) : FactAlgebra<Set<Pattern>, Conclusion> {
    private val onRequest = request
    private val seedAllows = allowsSource
    private val onHit = sourceHit
    private val join = conjunction
    private val sourcePredicates = ReferenceSourcePredicates(manager)
    internal val run1: Boolean get() = mode.run1

    override fun base(c: Conclusion) = c.fact.base

    override fun filter(c: Conclusion, filter: TypeFilter): Conclusion? = c.takeIf { passes(filter, it) }

    override fun applyEdge(me: MicroEdge, c: Conclusion, premise: Set<Pattern>, statementEdge: Boolean, out: ReferenceSink) {
        val identity = historicalRun1 && mode.run1 && statementEdge && isStaticIdentity(premise, c)
        when (val o = concat(c, me.edge, edgeDemand = me.may, staticIdentity = identity, restricted = mode.restricted,
            run1 = mode.run1 && !historicalRun1)) {
            is EdgeOutcome.Fact -> out(premise, o.conclusion)
            is EdgeOutcome.Request -> if (mode.run1) onRequest(premise, ReferenceRequestKind.Mark(o.mark))
            is EdgeOutcome.PositionRequest -> if (mode.run1) onRequest(premise, ReferenceRequestKind.Position(manager.path(o.path)!!))
            EdgeOutcome.None -> Unit
        }
    }

    override fun conjunction(cj: ConjunctiveEdge, premise: Set<Pattern>, c: Conclusion, node: CommonInst, out: ReferenceSink) =
        join(cj, premise, c, node, out)
    override fun sourcePredicate(source: SourceRuleOccurrence, premise: Set<Pattern>, c: Conclusion, node: CommonInst,
                                 statementEdge: Boolean, out: ReferenceSink) =
        sourcePredicates.apply(source, premise, c, node, mode, statementEdge, ::applyEdge, onRequest, out)
    override fun allowsSource(node: CommonInst, me: MicroEdge) = seedAllows(node, me)
    override fun acceptedSource(application: AcceptedSource<Set<Pattern>, Conclusion>) = onHit(application.at.node, application.edge)

    fun passes(filter: TypeFilter, c: Conclusion): Boolean {
        var may: FactTypeChecker.FactApFilter = filter.may
        for (a in c.fact.path) when (val r = may.check(manager.accessors.accessor(a))) {
            FactTypeChecker.FilterResult.Accept -> break
            FactTypeChecker.FilterResult.Reject -> return false
            is FactTypeChecker.FilterResult.FilterNext -> may = r.filter
        }
        val mark = (c.fact.mark as? MarkSlot.Concrete)?.mark ?: return true
        val policy = filter.markPolicy ?: return true
        if (c.fact.path.any { it != ELEMENT_ACCESSOR_IDX }) return true
        return policy.keeps(mark, elements = c.fact.path.size)
    }

    private fun isStaticIdentity(premise: Set<Pattern>, c: Conclusion): Boolean {
        val i = premise.singleOrNull()?.fact ?: return false
        val f = c.fact
        return i.base == AccessPathBase.ClassStatic && f.base == AccessPathBase.ClassStatic &&
            i.tail == Tail.STAR && f.tail == Tail.STAR && i.mark == MarkSlot.STAR && f.mark is MarkSlot.Star &&
            f.path == i.path && !c.demand && rootOrClass(i.path)
    }
}

/** One plan item carries its premise, conclusion and nullable identity candidate. */
data class PlanItem(val premise: Set<Pattern>, val c: Conclusion, val identityCandidate: Boolean?)

/** Hooks supply guards, callees, cleaners, statement cuts and exit cuts. */
class PlanHooks(
    val guards: Boolean = false,
    val atBound: (List<PlanItem>) -> List<Pair<SinkRule, Layer>> = { emptyList() },
    val callees: (CallStage.Callees, PlanItem) -> List<PlanItem> = { _, _ -> emptyList() },
    val clean: (Cleaner, PlanItem) -> List<PlanItem> = { _, it -> listOf(it) },
    val statementCut: (PlanItem) -> PlanItem = { it },
    val exit: (PlanItem) -> PlanItem = { it },
    val trigger: (SinkRule) -> List<PlanItem> = { emptyList() },
)

/** Per-path form execution and the reference walk of a call plan. */
class FormsReference(
    private val ops: ApOps,
    // This independent reference default keeps its established GROUP algebra.
    // The production driver passes its selected run-1 mode explicitly.
    algebra: ReferenceAlgebra = ReferenceAlgebra(ApMode(run1 = true, Direction.FORWARD,
        fieldLimit = Int.MAX_VALUE, markMode = MarkMode.GROUP),
        manager = ops.manager),
    private val run1AliasAdmission: Boolean = algebra.run1,
) {
    val applier = FormApplier(algebra)
    private val zeroPremise = setOf(ZERO_PATTERN)

    fun conclusions(f: Facts): List<Conclusion> {
        val demand = f.layer == Layer.DEMAND
        return when (f) {
            is Reach -> listOf(Conclusion(ZERO_FACT, ExclusionSet.Empty, demand))
            else -> ops.leaves(f).map { Conclusion(it.fact, it.exclusion, demand) }.toList()
        }
    }

    enum class Mode { STATEMENT, STAGE, GEN }
    fun apply(mode: Mode, s: StatementSummary, premise: Set<Pattern>, c: Conclusion, at: Place): List<Conclusion> = buildList {
        when (mode) {
            Mode.STATEMENT -> applier.statement(s, premise, c, at, { _, x -> add(x) })
            Mode.STAGE -> applier.stage(s, premise, c, at) { _, x, _ -> add(x) }
            Mode.GEN -> applier.gen(s.edges, premise, c) { _, x -> add(x) }
        }
    }

    /** Compare complete leaf identities before store merging or subsumption. */
    fun agrees(mode: Mode, s: StatementSummary, at: Place, premise: Set<Pattern>, input: Facts, core: List<Facts>): Boolean {
        val ref = conclusions(input).flatMap { apply(mode, s, premise, it, at) }.toSet()
        val got = core.flatMap(::conclusions).toSet()
        return got == ref
    }

    /** Keep pending record exclusions until exit demotion, then apply the call cut. */
    fun run(plan: CallPlan, inputs: List<PlanItem>, at: Place, hooks: PlanHooks = PlanHooks(),
            from: CallPoint = plan.entry, pendingDemotion: Boolean = false): List<Pair<CallPoint, PlanItem>> {
        check(!pendingDemotion || (from == CallPoint.RETURNED && plan.exit == CallPoint.AFTER))
        fun finish(i: PlanItem): PlanItem {
            val result = if (!pendingDemotion) i else {
                check(i.c.fact.mark is MarkSlot.Concrete && i.c.fact.tail != Tail.STAR)
                i.copy(c = i.c.copy(demand = true), identityCandidate = if (run1AliasAdmission) i.identityCandidate else false)
            }
            return hooks.exit(result)
        }
        fun statement(s: StatementSummary, x: PlanItem): List<PlanItem> = buildList {
            applier.statement(s, x.premise, x.c, at.copy(statementEdge = true, sources = false),
                sink = { pr, y -> add(hooks.statementCut(PlanItem(pr, y, x.identityCandidate))) },
                untouched = { pr, y -> add(PlanItem(pr, y, x.identityCandidate)) })
        }
        fun cleanSteps(steps: List<CleanStep>, inputs: List<PlanItem>): List<PlanItem> =
            steps.fold(inputs) { fs, step -> fs.flatMap { x -> when (step) {
                is CleanStep.Clean -> hooks.clean(step.cleaner, x)
                is CleanStep.Kill -> buildList { applier.statement(step.keepEdges, x.premise, x.c,
                    at.copy(statementEdge = true, sources = false), { pr, y -> add(PlanItem(pr, y, x.identityCandidate)) }) }
                is CleanStep.Field -> statement(step.read, x).flatMap { hooks.clean(step.cleaner, it) }
                    .flatMap { statement(step.write, it) }.filter { it.c.fact.base != step.temporary }
            } } }
        val seen = LinkedHashSet<Pair<CallPoint, PlanItem>>()
        val work = ArrayDeque<Pair<CallPoint, List<PlanItem>>>()
        val start = ArrayList<PlanItem>()
        for (input in inputs) {
            val i = if (pendingDemotion && !run1AliasAdmission) input.copy(identityCandidate = false) else input
            when {
                from != plan.entry -> start += i
                i.c.fact.base == AccessPathBase.Zero -> {
                    if (plan.zeroCanReturn) seen += plan.exit to finish(i)
                    start += i
                }
                i.c.fact.base !in plan.touched -> seen += plan.exit to finish(i)
                else -> start += i
            }
        }
        if (start.isNotEmpty()) work.addLast(from to start)
        while (work.isNotEmpty()) {
            val (p, batch) = work.removeFirst()
            val items = batch.filter { seen.add(p to it) }
            if (items.isEmpty() || p == plan.exit) continue
            val fired = if (hooks.guards && p == CallPoint.BOUND) hooks.atBound(items) else emptyList()
            for (st in plan.stagesFrom[p].orEmpty()) {
                val out = ArrayList<PlanItem>()
                when (st) {
                    is CallStage.Edges -> {
                        val place = at.copy(statementEdge = st.kind.statementEdges, sources = st.kind == StageKind.SOURCES)
                        val guard = if (hooks.guards) st.guard else null
                        when {
                            guard is Guard.SinkTriggered ->
                                for ((sink, layer) in fired) if (sink.joinKey == guard.sink.joinKey) {
                                    val zero = Conclusion(ZERO_FACT, ExclusionSet.Empty, demand = layer == Layer.DEMAND)
                                    applier.stage(st.summary, zeroPremise, zero, place) { pr, x, me ->
                                        out += PlanItem(pr, x, st.kind.identityCandidateOf(me, null)) }
                                }
                            else -> {
                                for (i in items) {
                                    if (guard == Guard.MemoryEffect && !Guard.MemoryEffect.admits(run1AliasAdmission, i.identityCandidate,
                                        if (i.c.demand) Layer.DEMAND else Layer.NORMAL)) continue
                                    applier.stage(st.summary, i.premise, i.c, place) { pr, x, me ->
                                        out += PlanItem(pr, x, st.kind.identityCandidateOf(me, i.identityCandidate)) }
                                }
                                val sink = st.trigger
                                if (sink != null && out.isNotEmpty()) out += hooks.trigger(sink)
                            }
                        }
                    }
                    is CallStage.Actions -> out += cleanSteps(st.steps, items)
                    is CallStage.Callees -> for (i in items) out += hooks.callees(st, i)
                    is CallStage.Predefined -> for (i in items) {
                        applier.stage(st.summary, i.premise, i.c, at.copy(statementEdge = false, sources = false)) { pr, x, _ ->
                            out += PlanItem(pr, x, true)
                        }
                    }
                }
                val next = if (st.to == plan.exit) out.map(::finish) else out
                if (next.isNotEmpty()) work.addLast(st.to to next)
            }
        }
        return seen.toList()
    }
}

package org.opentaint.dataflow.bidi.interp

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.ap.ifds.access.util.AccessorIdx
import org.opentaint.dataflow.bidi.ap.ExclusionSet
import org.opentaint.dataflow.bidi.ap.MarkSlot
import org.opentaint.dataflow.bidi.ap.PathEdge
import org.opentaint.dataflow.bidi.ap.PathFact
import org.opentaint.dataflow.bidi.ap.Pattern
import org.opentaint.dataflow.bidi.ap.Tail
import org.opentaint.dataflow.bidi.ap.TaintMark
import java.util.Collections

/** A directed edge retains its forward object for source and may classification. */
class MicroEdge(
    val edge: PathEdge,
    val forward: PathEdge,
    val conjunctive: Boolean = false,
    val actionId: ActionId? = null,
) {
    init {
        check(forward.from.tail != Tail.ANY_TAINT) { "I14: a forward micro edge cannot have a must premise" }
        check(edge == forward || (edge.from.tail != Tail.ANY_TAINT && edge.to.tail != Tail.ANY_TAINT)) {
            "A1: a reversed micro edge cannot have a must side"
        }
    }

    val isSource: Boolean
        get() = forward.from.base == AccessPathBase.Zero && forward.to.base != AccessPathBase.Zero
    /** A pass transports input protection; its action identity is not an assignment. */
    val isRuleAssignment: Boolean
        get() {
            val id = actionId
            if (id?.role == ActionRole.PASS_THROUGH ||
                id?.occurrence?.kind == RuleKind.PASS_THROUGH) return false
            return isSource || id != null
        }
    val isIdentity: Boolean
        get() = edge.from == edge.to && edge.exclusion == ExclusionSet.Empty
    val may: Boolean get() = forward.to.tail == Tail.ANY || conjunctive

    companion object { fun of(e: PathEdge): MicroEdge = MicroEdge(e, e) }
}

val ZERO_FACT: PathFact = PathFact(AccessPathBase.Zero, emptyList(), Tail.EXACT, MarkSlot.Concrete(TaintMark.ZERO))
val ZERO_PATTERN: Pattern = Pattern(ZERO_FACT, ExclusionSet.Empty)
val ZERO_KEEP: PathEdge = PathEdge(ZERO_FACT, ZERO_FACT, ExclusionSet.Empty)

/** Helper-created facts own their paths; supplied MicroEdge objects keep their original identities. */
fun starSide(b: AccessPathBase, p: List<AccessorIdx> = emptyList()): PathFact =
    PathFact(b, Collections.unmodifiableList(ArrayList(p)), Tail.STAR, MarkSlot.STAR)

fun keepEdge(b: AccessPathBase, p: List<AccessorIdx> = emptyList(), e: ExclusionSet = ExclusionSet.Empty): PathEdge {
    val side = starSide(b, p)
    return PathEdge(side, side, e)
}

/** Each proper prefix keeps every continuation except the next step of the written path. */
fun strongKeep(b: AccessPathBase, path: List<AccessorIdx>): List<PathEdge> =
    Collections.unmodifiableList(path.indices.map { k -> keepEdge(b, path.take(k), ExclusionSet.of(path[k])) })

fun starEdge(from: AccessPathBase, fp: List<AccessorIdx>, to: AccessPathBase, tp: List<AccessorIdx>): PathEdge =
    PathEdge(starSide(from, fp), starSide(to, tp), ExclusionSet.Empty)

package org.opentaint.dataflow.bidi.interp

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.ap.ifds.access.util.AccessorIdx
import org.opentaint.dataflow.ap.ifds.access.util.AccessorInterner.Companion.isFieldAccessor
import org.opentaint.dataflow.bidi.ap.CleanReach
import org.opentaint.dataflow.bidi.ap.Cleaner
import org.opentaint.dataflow.bidi.ap.ConjunctiveEdge
import org.opentaint.dataflow.bidi.ap.PathEdge
import org.opentaint.dataflow.bidi.ap.TaintMark
import org.opentaint.dataflow.bidi.ap.TypeFilter

/** Build forward forms in insertion order. Supplied edges and conjunctions retain their identities. */
class MicroEdgeBuilder {
    private val touched = LinkedHashSet<AccessPathBase>()
    private val edges = LinkedHashSet<PathEdge>()
    private val sourceEdges = ArrayList<MicroEdge>()
    private val conjunctions = LinkedHashSet<ConjunctiveEdge>()
    private val sources = ArrayList<SourceRuleOccurrence>()
    private val staticOperations = ArrayList<StaticOperation>()
    private val operand = LinkedHashMap<AccessPathBase, TypeFilter>()
    private val result = LinkedHashMap<AccessPathBase, TypeFilter>()

    fun touch(b: AccessPathBase) { touched += b }
    fun edge(e: PathEdge) { edges += e }
    /** Source occurrences remain separate even when their transfer tuples are equal. */
    fun sourceEdge(e: PathEdge, id: ActionId) { sourceEdges += MicroEdge(e, e, actionId = id) }
    fun conjunction(c: ConjunctiveEdge) { conjunctions += c }
    fun source(source: SourceRuleOccurrence) { sources += source }
    fun staticOperation(operation: StaticOperation) { staticOperations += operation }

    fun keep(b: AccessPathBase) {
        touch(b)
        edge(keepEdge(b))
    }

    fun keepZero() {
        touch(AccessPathBase.Zero)
        edge(ZERO_KEEP)
    }

    fun operandFilter(b: AccessPathBase, f: TypeFilter?) {
        if (f != null) operand.merge(b, f) { x, y -> x.and(y) }
    }

    fun resultFilter(b: AccessPathBase, f: TypeFilter?) {
        if (f != null) result.merge(b, f) { x, y -> x.and(y) }
    }

    /** A missing source kills the target. A self move retains one identity edge. */
    fun move(to: AccessPathBase, from: AccessPathBase?, toPath: List<AccessorIdx> = emptyList()) {
        touch(to)
        if (from == null) return
        keep(from)
        if (from != to || toPath.isNotEmpty()) edge(starEdge(from, emptyList(), to, toPath))
    }

    /** A read retains its source, except when the read replaces that same base. It adds no exclusion. */
    fun read(to: AccessPathBase, base: AccessPathBase, path: List<AccessorIdx>) {
        touch(to)
        touch(base)
        if (base != to) keep(base)
        edge(starEdge(base, path, to, emptyList()))
    }

    /** Strong writes keep proper prefixes. Alias targets get value edges and remain untouched by the write. */
    fun write(
        base: AccessPathBase,
        path: List<AccessorIdx>,
        weak: Boolean,
        values: List<AccessPathBase>,
        aliasPaths: List<Pair<AccessPathBase, List<AccessorIdx>>>,
    ) {
        touch(base)
        if (weak) keep(base) else strongKeep(base, path).forEach(::edge)
        for (v in values) {
            if (v != base) keep(v) else touch(v)
            edge(starEdge(v, emptyList(), base, path))
        }
        for ((c, q) in aliasPaths) {
            if (c == base) continue
            for (v in values) edge(starEdge(v, emptyList(), c, q + path))
        }
    }

    /** Statement forms retain touched bases, conjunctions, and both filter maps. */
    fun build(): StatementSummary = StatementSummary(touched, edges.map(MicroEdge::of) + sourceEdges,
        conjunctions.toList(), operand, result, sources, staticOperations)

    /** Every plain or conjunctive endpoint belongs to the stage's touched set. */
    fun buildStage(): StatementSummary {
        edges.forEach { touch(it.from.base); touch(it.to.base) }
        sourceEdges.forEach { touch(it.edge.from.base); touch(it.edge.to.base) }
        conjunctions.forEach { c ->
            c.literals.forEach { touch(it.fact.base) }
            touch(c.target.base)
        }
        sources.forEach { source ->
            source.predicate.leaves.forEach { touch(it.fact.base) }
            source.actions.forEach { touch(it.target.base) }
        }
        return build()
    }

    /** GEN uses plain edges only; its caller retains the input. */
    fun buildGen(): StatementSummary = StatementSummary(emptySet(), edges.map(MicroEdge::of) + sourceEdges, emptyList(), emptyMap(), staticOperations = staticOperations)
}

/** A named field cleaner is an ordinary read, one temporary cleaner, and an ordinary strong write. */
fun fieldCleanStep(
    base: AccessPathBase,
    path: List<AccessorIdx>,
    reach: CleanReach,
    mark: TaintMark?,
    baseFilter: TypeFilter? = null,
    valueFilter: TypeFilter? = null,
    aliasPaths: List<Pair<AccessPathBase, List<AccessorIdx>>> = emptyList(),
    temporaryKey: TemporaryKey? = null,
): CleanStep.Field {
    check(base != AccessPathBase.ClassStatic && path.isNotEmpty() && path.last().isFieldAccessor())
    val tmp = temporaryKey?.let(AccessPathBase.CleanerTemporary::keyed) ?: AccessPathBase.CleanerTemporary()
    val read = MicroEdgeBuilder().apply {
        read(tmp, base, path)
        operandFilter(base, baseFilter)
        resultFilter(tmp, valueFilter)
    }.build()
    val write = MicroEdgeBuilder().apply {
        write(base, path, weak = false, values = listOf(tmp), aliasPaths = aliasPaths)
        operandFilter(base, baseFilter)
        operandFilter(tmp, valueFilter)
    }.build()
    return CleanStep.Field(tmp, read, Cleaner(tmp, null, reach, mark), write)
}

package org.opentaint.dataflow.bidi.interp

import java.util.AbstractMap.SimpleImmutableEntry
import java.util.RandomAccess

/** A representation threshold only: every key is retained in either representation. */
internal const val COMPACT_LINEAR_LIMIT = 8

private fun elementIndex(index: Int, size: Int) {
    if (index < 0 || index >= size) throw IndexOutOfBoundsException("index=$index, size=$size")
}

private abstract class OwnedVector<out E> : AbstractList<E>(), RandomAccess {
    open fun storage(counts: FormStorageCounts) { counts.ownedContainerEntries += size.toLong() }
}

private object EmptyVector : OwnedVector<Any?>() {
    override val size: Int get() = 0
    override fun get(index: Int): Nothing = throw IndexOutOfBoundsException("index=$index, size=0")
}

private class SingletonVector<E>(private val element: E) : OwnedVector<E>() {
    override val size: Int get() = 1
    override fun get(index: Int): E {
        elementIndex(index, 1)
        return element
    }
}

private class ArrayVector<E>(private val elements: Array<Any?>) : OwnedVector<E>() {
    override val size: Int get() = elements.size
    @Suppress("UNCHECKED_CAST")
    override fun get(index: Int): E {
        elementIndex(index, size)
        return elements[index] as E
    }
}

/** The array is newly allocated by this file and is never exposed to a mutable caller. */
@Suppress("UNCHECKED_CAST")
private fun <E> adoptVector(elements: Array<Any?>): List<E> = when (elements.size) {
    0 -> EmptyVector as List<E>
    1 -> SingletonVector(elements[0] as E)
    else -> ArrayVector(elements)
}

/** Snapshot unknown inputs; an already owned immutable vector needs no second copy. */
@Suppress("UNCHECKED_CAST")
internal fun <E> ownedList(values: Collection<E>): List<E> {
    if (values is OwnedVector<*>) return values as List<E>
    return when (values.size) {
        0 -> EmptyVector as List<E>
        1 -> SingletonVector(if (values is List<E>) values[0] else values.iterator().next())
        else -> {
            val elements = arrayOfNulls<Any?>(values.size)
            if (values is List<E> && values is RandomAccess) {
                for (index in elements.indices) elements[index] = values[index]
            } else {
                var index = 0
                for (value in values) elements[index++] = value
            }
            adoptVector(elements)
        }
    }
}

/** Evaluate each supplied element once into storage owned by the result. */
internal fun <E> ownedList(size: Int, elementAt: (Int) -> E): List<E> {
    require(size >= 0)
    return when (size) {
        0 -> ownedList(emptyList())
        1 -> SingletonVector(elementAt(0))
        else -> adoptVector(Array<Any?>(size) { elementAt(it) })
    }
}

/** Single-use internal builder. Public form builders continue to create independent snapshots. */
internal class OwnedListBuilder<E>(private val initialCapacity: Int = 0) {
    init { require(initialCapacity >= 0) }
    private var first: Any? = null
    private var elements: Array<Any?>? = null
    private var count = 0
    private var frozen = false

    fun add(value: E) {
        check(!frozen) { "An owned vector builder was already frozen" }
        if (count == 0) first = value
        else {
            var array = elements
            if (array == null) {
                array = arrayOfNulls(maxOf(2, initialCapacity))
                array[0] = first
                first = null
                elements = array
            } else if (count == array.size) {
                val capacity = maxOf(count.toLong() + 1, array.size.toLong() * 2)
                check(capacity <= Int.MAX_VALUE) { "An owned vector exceeds its array representation" }
                array = array.copyOf(capacity.toInt())
                elements = array
            }
            array[count] = value
        }
        count++
    }

    @Suppress("UNCHECKED_CAST")
    fun freeze(): List<E> {
        check(!frozen) { "An owned vector builder was already frozen" }
        frozen = true
        val result: List<E> = when (count) {
            0 -> EmptyVector as List<E>
            1 -> SingletonVector(first as E)
            else -> {
                val array = checkNotNull(elements)
                adoptVector(if (count == array.size) array else array.copyOf(count))
            }
        }
        first = null
        elements = null
        return result
    }
}

private abstract class OwnedSet<E> : AbstractSet<E>() {
    open fun storageIndex(): IntArray? = null
}

/** Ordinal plus one; zero denotes an empty bucket. Keys stay in their ordered array. */
private fun keyLookup(keys: Array<Any?>, size: Int = keys.size): IntArray? {
    if (size <= COMPACT_LINEAR_LIMIT) return null
    val required = size.toLong() * 2
    if (required > (1L shl 30)) return null
    var capacity = 1
    while (capacity.toLong() < required) capacity = capacity shl 1
    val buckets = IntArray(capacity)
    val mask = capacity - 1
    for (index in 0 until size) addKeyBucket(buckets, keys[index], index)
    return buckets
}

private fun addKeyBucket(buckets: IntArray, key: Any?, index: Int) {
    val mask = buckets.size - 1
    val hash = key?.hashCode() ?: 0
    var bucket = (hash xor (hash ushr 16)) and mask
    while (buckets[bucket] != 0) bucket = (bucket + 1) and mask
    buckets[bucket] = index + 1
}

private fun keyIndex(keys: Array<Any?>, lookup: IntArray?, key: Any?, size: Int = keys.size): Int {
    if (lookup == null) {
        for (index in 0 until size) if (keys[index] == key) return index
        return -1
    }
    val mask = lookup.size - 1
    val hash = key?.hashCode() ?: 0
    var bucket = (hash xor (hash ushr 16)) and mask
    while (true) {
        val index = lookup[bucket] - 1
        if (index < 0) return -1
        if (keys[index] == key) return index
        bucket = (bucket + 1) and mask
    }
}

private object EmptyOwnedSet : OwnedSet<Any?>() {
    override val size: Int get() = 0
    override fun contains(element: Any?): Boolean = false
    override fun iterator(): Iterator<Any?> = EmptyVector.iterator()
}

private class SingletonOwnedSet<E>(private val element: E) : OwnedSet<E>() {
    override val size: Int get() = 1
    override fun contains(element: E): Boolean = this.element == element
    override fun iterator(): Iterator<E> = object : Iterator<E> {
        private var remaining = true
        override fun hasNext(): Boolean = remaining
        override fun next(): E {
            if (!remaining) throw NoSuchElementException()
            remaining = false
            return element
        }
    }
}

private class ArrayOwnedSet<E>(private val elements: Array<Any?>,
                               private val index: IntArray? = keyLookup(elements)) : OwnedSet<E>() {
    override fun storageIndex(): IntArray? = index
    override val size: Int get() = elements.size
    override fun contains(element: E): Boolean = keyIndex(elements, index, element) >= 0
    override fun iterator(): Iterator<E> = object : Iterator<E> {
        private var next = 0
        override fun hasNext(): Boolean = next < elements.size
        @Suppress("UNCHECKED_CAST")
        override fun next(): E {
            if (!hasNext()) throw NoSuchElementException()
            return elements[next++] as E
        }
    }
}

/** Preserve first occurrence order, including when a collection contains equal values. */
@Suppress("UNCHECKED_CAST")
internal fun <E> ownedSet(values: Collection<E>): Set<E> {
    if (values is OwnedSet<*>) return values as Set<E>
    if (values is Set<E>) return when (values.size) {
        0 -> EmptyOwnedSet as Set<E>
        1 -> SingletonOwnedSet(values.iterator().next())
        else -> {
            val elements = arrayOfNulls<Any?>(values.size)
            var count = 0
            var lookup: IntArray? = null
            for (value in values) {
                if (keyIndex(elements, lookup, value, count) >= 0) continue
                elements[count] = value
                count++
                if (count > COMPACT_LINEAR_LIMIT) {
                    if (lookup == null || count.toLong() * 2 > lookup.size) lookup = keyLookup(elements, count)
                    else addKeyBucket(lookup, value, count - 1)
                }
            }
            if (count == 1) SingletonOwnedSet(elements[0] as E)
            else ArrayOwnedSet(if (count == elements.size) elements else elements.copyOf(count), lookup)
        }
    }
    val unique = ArrayList<E>(minOf(values.size, COMPACT_LINEAR_LIMIT))
    var index: HashSet<E>? = null
    for (value in values) {
        val added = index?.add(value) ?: !unique.contains(value)
        if (!added) continue
        unique.add(value)
        if (unique.size > COMPACT_LINEAR_LIMIT && index == null) index = HashSet(unique)
    }
    return when (unique.size) {
        0 -> EmptyOwnedSet as Set<E>
        1 -> SingletonOwnedSet(unique[0])
        else -> ArrayOwnedSet(Array<Any?>(unique.size) { unique[it] })
    }
}

/** Entry views are read-only and created only for callers that use the collection interface. */
private abstract class OwnedMap<K, V> : AbstractMap<K, V>() {
    @Volatile private var entryView: Set<Map.Entry<K, V>>? = null
    abstract fun keyAt(index: Int): K
    abstract fun valueAt(index: Int): V
    abstract fun keyIndex(key: K): Int
    open fun storageIndex(): IntArray? = null

    override fun containsKey(key: K): Boolean = keyIndex(key) >= 0
    override fun get(key: K): V? = keyIndex(key).let { if (it < 0) null else valueAt(it) }
    override fun containsValue(value: V): Boolean {
        for (index in 0 until size) if (valueAt(index) == value) return true
        return false
    }

    override val entries: Set<Map.Entry<K, V>>
        get() = entryView ?: object : AbstractSet<Map.Entry<K, V>>() {
            override val size: Int get() = this@OwnedMap.size
            override fun iterator(): Iterator<Map.Entry<K, V>> = object : Iterator<Map.Entry<K, V>> {
                private var next = 0
                override fun hasNext(): Boolean = next < size
                override fun next(): Map.Entry<K, V> {
                    if (!hasNext()) throw NoSuchElementException()
                    val index = next++
                    return SimpleImmutableEntry(keyAt(index), valueAt(index))
                }
            }
        }.also { entryView = it }
}

private object EmptyOwnedMap : OwnedMap<Any?, Any?>() {
    override val size: Int get() = 0
    override fun keyAt(index: Int): Nothing = throw IndexOutOfBoundsException("index=$index, size=0")
    override fun valueAt(index: Int): Nothing = throw IndexOutOfBoundsException("index=$index, size=0")
    override fun keyIndex(key: Any?): Int = -1
}

private class SingletonOwnedMap<K, V>(private val key: K, private val value: V) : OwnedMap<K, V>() {
    override val size: Int get() = 1
    override fun keyAt(index: Int): K { elementIndex(index, 1); return key }
    override fun valueAt(index: Int): V { elementIndex(index, 1); return value }
    override fun keyIndex(key: K): Int = if (this.key == key) 0 else -1
}

private class ArrayOwnedMap<K, V>(private val keyData: Array<Any?>, private val valueData: Array<Any?>,
                                 private val index: IntArray? = keyLookup(keyData)) : OwnedMap<K, V>() {
    override fun storageIndex(): IntArray? = index
    override val size: Int get() = keyData.size
    @Suppress("UNCHECKED_CAST")
    override fun keyAt(index: Int): K = keyData[index] as K
    @Suppress("UNCHECKED_CAST")
    override fun valueAt(index: Int): V = valueData[index] as V
    override fun keyIndex(key: K): Int = keyIndex(keyData, index, key)
}

@Suppress("UNCHECKED_CAST")
internal fun <K, V> ownedMap(values: Map<K, V>): Map<K, V> {
    if (values is OwnedMap<*, *>) return values as Map<K, V>
    return when (values.size) {
        0 -> EmptyOwnedMap as Map<K, V>
        1 -> values.entries.first().let { SingletonOwnedMap(it.key, it.value) }
        else -> {
            val keys = arrayOfNulls<Any?>(values.size)
            val entries = arrayOfNulls<Any?>(values.size)
            var count = 0
            var lookup: IntArray? = null
            for ((key, value) in values) {
                val existing = keyIndex(keys, lookup, key, count)
                if (existing >= 0) {
                    entries[existing] = value
                    continue
                }
                keys[count] = key
                entries[count] = value
                count++
                if (count > COMPACT_LINEAR_LIMIT) {
                    if (lookup == null || count.toLong() * 2 > lookup.size) lookup = keyLookup(keys, count)
                    else addKeyBucket(lookup, key, count - 1)
                }
            }
            if (count == 1) SingletonOwnedMap(keys[0] as K, entries[0] as V)
            else ArrayOwnedMap(if (count == keys.size) keys else keys.copyOf(count),
                if (count == entries.size) entries else entries.copyOf(count), lookup)
        }
    }
}

/** Internal producer supplies distinct ordered keys and is evaluated once per key/value. */
@Suppress("UNCHECKED_CAST")
internal fun <K, V> ownedMap(size: Int, keyAt: (Int) -> K, valueAt: (Int) -> V): Map<K, V> {
    require(size >= 0)
    return when (size) {
        0 -> EmptyOwnedMap as Map<K, V>
        1 -> SingletonOwnedMap(keyAt(0), valueAt(0))
        else -> ArrayOwnedMap(Array<Any?>(size) { keyAt(it) }, Array<Any?>(size) { valueAt(it) })
    }
}

private class OrdinalVector<E>(private val source: List<E>, private val ordinals: IntArray,
                               private val from: Int, override val size: Int) : OwnedVector<E>() {
    override fun storage(counts: FormStorageCounts) {
        counts.include(source)
        counts.index(ordinals)
    }
    override fun get(index: Int): E {
        elementIndex(index, size)
        return source[ordinals[from + index]]
    }
}

/** One shared element vector and ordinal array; every group view is retained once. */
internal fun <K, E> ownedOrdinalGroups(input: List<E>, keyOf: (E) -> K): Map<K, List<E>> {
    val values = ownedList(input)
    if (values.isEmpty()) return ownedMap(emptyMap())
    val firstKey = keyOf(values[0])
    var keys: ArrayList<K>? = null
    var lookup: HashMap<K, Int>? = null
    var groups: IntArray? = null
    var counts: IntArray? = null
    for (i in 1 until values.size) {
        val key = keyOf(values[i])
        if (keys == null) {
            if (key == firstKey) continue
            keys = arrayListOf(firstKey)
            groups = IntArray(values.size)
            counts = IntArray(values.size)
            counts[0] = i
        }
        val ordered = keys
        var group = if (lookup == null) ordered.indexOf(key) else lookup[key] ?: -1
        if (group < 0) {
            group = ordered.size
            ordered.add(key)
            if (lookup != null) lookup[key] = group
            else if (ordered.size > COMPACT_LINEAR_LIMIT) {
                lookup = HashMap<K, Int>().also { map -> ordered.forEachIndexed { index, item -> map[item] = index } }
            }
        }
        checkNotNull(groups)[i] = group
        checkNotNull(counts)[group]++
    }
    if (keys == null) return ownedMap(1, { firstKey }, { values })
    val ordered = keys
    val sizes = checkNotNull(counts)
    val offsets = IntArray(ordered.size + 1)
    for (i in ordered.indices) offsets[i + 1] = offsets[i] + sizes[i]
    for (i in ordered.indices) sizes[i] = offsets[i]
    val ordinals = IntArray(values.size)
    for (i in values.indices) {
        val group = checkNotNull(groups)[i]
        ordinals[sizes[group]++] = i
    }
    return ownedMap(ordered.size, { ordered[it] }) { group ->
        val from = offsets[group]
        val size = offsets[group + 1] - from
        if (size == 1) SingletonVector(values[ordinals[from]]) else OrdinalVector(values, ordinals, from, size)
    }
}

/** Read retained backing storage without creating entries/keys/values compatibility views. */
internal fun ownedStorage(value: Any, counts: FormStorageCounts): Boolean = when (value) {
    is OwnedVector<*> -> { value.storage(counts); true }
    is OwnedSet<*> -> {
        counts.ownedContainerEntries += value.size.toLong()
        counts.index(value.storageIndex())
        true
    }
    is OwnedMap<*, *> -> {
        counts.ownedContainerEntries += 2L * value.size
        counts.index(value.storageIndex())
        true
    }
    else -> false
}

/** Only form directories have owned vector values; filter maps remain opaque payloads. */
internal fun ownedDirectoryStorage(directory: Map<*, *>, counts: FormStorageCounts) {
    counts.include(directory)
    check(directory is OwnedMap<*, *>)
    for (index in 0 until directory.size) counts.include(checkNotNull(directory.valueAt(index)))
}

package org.opentaint.dataflow.bidi.interp

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.ap.ifds.Accessor
import org.opentaint.dataflow.bidi.ap.ApManager
import org.opentaint.ir.api.common.CommonMethod

/** A model is complete. A missing row kills that input; it does not select a fallback. */
class CompleteMethodSummary(
    normal: List<SummarySchema>,
    exceptional: List<SummarySchema> = emptyList(),
    touched: Set<AccessPathBase>,
) {
    init { require(exceptional.isEmpty()) { "Predefined exceptional rows have no supported call lane" } }
    val normal: List<SummarySchema> = ownedList(normal)
    val exceptional: List<SummarySchema> = ownedList(exceptional)
    val touched: Set<AccessPathBase> = ownedSet(touched)
    val zeroCanReturn: Boolean get() = SummarySchema.ZeroIdentity in normal

    /** The supported relations are partial identities in both directions. */
    fun reversed(): CompleteMethodSummary = this
}

sealed interface SummarySchema {
    data object ZeroIdentity : SummarySchema

    class PrefixFlowIdentity(val base: AccessPathBase, prefix: List<Accessor>) : SummarySchema {
        val prefix: List<Accessor> = ownedList(prefix)
        init { require(base != AccessPathBase.Zero) }
    }
}

/** Metadata belongs to the actual registered method and does not change its equality. */
interface PredefinedSummaryMethod {
    val predefinedSummary: CompleteMethodSummary?
}

fun predefinedSummary(method: CommonMethod): CompleteMethodSummary? =
    (method as? PredefinedSummaryMethod)?.predefinedSummary

/** This is an executable relation. It creates no method initial or inferred summary. */
fun CompleteMethodSummary.compile(manager: ApManager): StatementSummary = MicroEdgeBuilder().apply {
    for (schema in normal) when (schema) {
        SummarySchema.ZeroIdentity -> keepZero()
        is SummarySchema.PrefixFlowIdentity -> edge(keepEdge(schema.base, schema.prefix.map(manager.accessors::index)))
    }
}.buildStage()

package org.opentaint.dataflow.bidi.interp

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.ir.api.common.cfg.CommonInst

/** A small per-path reference join, independent of the production incremental predicate store. */
internal class ReferenceSourcePredicates(private val manager: ApManager) {
    private data class Contribution(val premise: Set<Pattern>, val demand: Boolean)
    private data class Proof(val bindings: Map<Int, Contribution>, val order: List<Int>, val choices: List<Int>)
    private class State {
        val leaves = HashMap<Int, LinkedHashSet<Contribution>>()
        val emitted = HashSet<Proof>()
    }
    private val states = HashMap<Pair<RuleOccurrenceId, CommonInst>, State>()

    fun apply(source: SourceRuleOccurrence, premise: Set<Pattern>, c: Conclusion, node: CommonInst,
              mode: ApMode, statementEdge: Boolean,
              edge: (MicroEdge, Conclusion, Set<Pattern>, Boolean, ReferenceSink) -> Unit,
              request: (Set<Pattern>, ReferenceRequestKind) -> Unit,
              out: ReferenceSink) {
        manager.cancellation.checkpoint()
        if (source.actions.isEmpty()) return
        val predicate = source.predicate
        if (source.backward) {
            // FormsReference historically has a forward default algebra. The descriptor selects
            // reversal; backward source reads are always restricted and never raise requests.
            for (action in source.actions) for ((ordinal, literal) in predicate.leaves.withIndex()) {
                manager.cancellation.checkpoint()
                fun transfer(multi: Boolean) {
                    val me = source.transfer(literal, action, multi)
                    val result = concat(c, me.edge, edgeDemand = me.may, restricted = true)
                    if (result is EdgeOutcome.Fact) out(premise, result.conclusion)
                }
                if (predicate.isUnary(ordinal)) transfer(false)
                if (predicate.isMulti(ordinal)) transfer(true)
            }
            return
        }

        var state: State? = null
        var changed = false
        for ((ordinal, literal) in predicate.leaves.withIndex()) {
            manager.cancellation.checkpoint()
            if (predicate.isUnary(ordinal)) for (action in source.actions) {
                edge(source.transfer(literal, action), c, premise, statementEdge, out)
            }
            if (!predicate.isMulti(ordinal)) continue
            val initial = if (c.fact.mark is MarkSlot.Star) {
                check(premise.size == 1) { "A FLOW reference input has one premise" }
                premise.single()
            } else premise.first()
            when (val checked = markCheck(initial, c, literal, restricted = mode.restricted)) {
                CheckResult.None -> Unit
                is CheckResult.Request -> if (mode.run1)
                    request(premise, ReferenceRequestKind.Mark(checked.mark))
                CheckResult.Holds -> {
                    val owner = state ?: states.getOrPut(source.id to node) { State() }.also { state = it }
                    val owned = ownedSet(premise.map { p -> p.copy(fact = p.fact.copy(path = ownedList(p.fact.path))) })
                    changed = owner.leaves.getOrPut(ordinal) { LinkedHashSet() }
                        .add(Contribution(owned, conjDemand(c, literal))) || changed
                }
            }
        }
        if (!changed) return
        val owner = checkNotNull(state)
        for (proof in proofs(predicate, owner)) {
            manager.cancellation.checkpoint()
            if (proof.bindings.size < 2 || !owner.emitted.add(proof)) continue
            val allPremises = proof.order.flatMap { proof.bindings.getValue(it).premise }
            val nonzero = allPremises.filter { it.fact.base != AccessPathBase.Zero }
            val pr = if (nonzero.isEmpty()) setOf(ZERO_PATTERN) else ownedSet(nonzero)
            val demand = proof.bindings.values.any { it.demand }
            for (action in source.actions) {
                manager.cancellation.checkpoint()
                val target = action.target
                out(pr, Conclusion(target, ExclusionSet.Empty, demand))
            }
        }
    }

    /** Re-evaluate bounded standing inputs bottom-up; no production indexes or delta joins are used. */
    private fun proofs(predicate: RulePredicate, state: State): List<Proof> {
        val values = arrayOfNulls<List<Proof>>(predicate.nodeCount)
        for (node in 0 until predicate.nodeCount) {
            manager.cancellation.checkpoint()
            values[node] = when (predicate.kind(node)) {
                RulePredicate.Kind.FALSE -> emptyList()
                RulePredicate.Kind.TRUE -> listOf(Proof(emptyMap(), emptyList(), emptyList()))
                RulePredicate.Kind.LEAF -> {
                    val leaf = predicate.leafOrdinal(node)
                    state.leaves[leaf].orEmpty().map { Proof(mapOf(leaf to it), listOf(leaf), emptyList()) }
                }
                RulePredicate.Kind.OR -> {
                    val result = ArrayList<Proof>()
                    predicate.childrenOf(node) { child ->
                        manager.cancellation.checkpoint()
                        for (proof in checkNotNull(values[child])) {
                            manager.cancellation.checkpoint()
                            result += proof.copy(choices = listOf(node, child) + proof.choices)
                        }
                    }
                    result
                }
                RulePredicate.Kind.AND -> {
                    var products = listOf(Proof(emptyMap(), emptyList(), emptyList()))
                    predicate.childrenOf(node) { child ->
                        val next = ArrayList<Proof>()
                        for (a in products) for (b in checkNotNull(values[child])) {
                            manager.cancellation.checkpoint()
                            merge(a, b)?.let(next::add)
                        }
                        products = next
                    }
                    products
                }
            }
        }
        return checkNotNull(values[predicate.root])
    }

    private fun merge(a: Proof, b: Proof): Proof? {
        for ((leaf, input) in b.bindings) if (leaf in a.bindings && a.bindings[leaf] != input) return null
        val bindings = LinkedHashMap(a.bindings)
        bindings.putAll(b.bindings)
        return Proof(bindings, a.order + b.order.filterNot { it in a.bindings }, a.choices + b.choices)
    }
}

package org.opentaint.dataflow.bidi.interp

import org.opentaint.dataflow.bidi.ap.MethodKey
import org.opentaint.ir.api.common.CommonMethod
import org.opentaint.ir.api.common.cfg.CommonInst

/** One configuration/body generation. It owns no compiled forms or rule registry. */
class FormOwner

/** Physical method forms omit context; entry and call forms include the full method key. */
data class FormKey(
    val owner: FormOwner,
    val method: CommonMethod,
    val context: MethodKey?,
    val statement: CommonInst,
)

enum class RuleKind { CALL_SOURCE, CALL_SINK, ENTRY_SOURCE, ENTRY_SINK, EXIT_SOURCE, EXIT_SINK, CLEANER, REWRITER, PASS_THROUGH, FIELD_SOURCE }

/** The ordinal belongs to a frozen provider candidate order, before validation or filtering. */
data class RuleOccurrenceId(val form: FormKey, val kind: RuleKind, val ordinal: Int) {
    init { require(ordinal >= 0) }
}

/** The same configured action can have different expansions at different application stages. */
enum class ActionRole { SOURCE, END_FACT, BOUND_CLEANER, RETURN_REWRITER, GENERATED_CLEANER, MARK_INPUT, PASS_THROUGH }

data class ActionId(
    val occurrence: RuleOccurrenceId,
    val role: ActionRole,
    val ordinal: Int,
    val relevantMarkOrdinal: Int = 0,
    val generatedStep: Int = 0,
) {
    init { require(ordinal >= 0 && relevantMarkOrdinal >= 0 && generatedStep >= 0) }
}

/** Field/string-byte substeps are separate even when their concrete tuples are equal. */
data class TemporaryKey(val action: ActionId, val substep: Int = 0) {
    init { require(substep >= 0) }
}

/** A structural support shape, allocated only after facts support a predicate branch. */
class ProofKey(val rule: RuleOccurrenceId, leaves: List<Int>, choices: List<Int> = emptyList()) {
    private val leaves = leaves.toIntArray()
    private val choices = choices.toIntArray()
    private val hash = 31 * (31 * rule.hashCode() + this.leaves.contentHashCode()) + this.choices.contentHashCode()
    override fun equals(other: Any?): Boolean = other is ProofKey &&
        rule == other.rule && leaves.contentEquals(other.leaves) && choices.contentEquals(other.choices)
    override fun hashCode(): Int = hash
}

package org.opentaint.dataflow.bidi.interp

import it.unimi.dsi.fastutil.ints.Int2ObjectOpenHashMap
import it.unimi.dsi.fastutil.ints.IntArrayList
import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.MarkSlot
import org.opentaint.dataflow.bidi.ap.Pattern
import org.opentaint.dataflow.bidi.ap.TaintMark
import org.opentaint.dataflow.bidi.ap.MarkTable
import org.opentaint.dataflow.util.Cancellation

/** An owned positive NNF DAG. Node numbers are deterministic postorder ordinals. */
class RulePredicate private constructor(
    val root: Int,
    private val tags: ByteArray,
    private val offsets: IntArray,
    private val children: IntArray,
    private val leafAt: IntArray,
    val leaves: List<Pattern>,
    private val leafNodes: IntArray,
    private val parentOffsets: IntArray,
    private val parents: IntArray,
    private val unary: BooleanArray,
    private val multi: BooleanArray,
    cancellation: Cancellation,
) {
    enum class Kind { FALSE, TRUE, LEAF, AND, OR }

    val nodeCount: Int get() = tags.size
    val childCount: Int get() = children.size
    val isTrue: Boolean get() = kind(root) == Kind.TRUE
    val isFalse: Boolean get() = kind(root) == Kind.FALSE
    fun kind(node: Int): Kind = Kind.entries[tags[node].toInt()]
    fun leafOrdinal(node: Int): Int = leafAt[node]
    fun leafNode(leaf: Int): Int = leafNodes[leaf]
    fun isUnary(leaf: Int): Boolean = unary[leaf]
    fun isMulti(leaf: Int): Boolean = multi[leaf]
    fun childrenOf(node: Int, visit: (Int) -> Unit) {
        for (i in offsets[node] until offsets[node + 1]) visit(children[i])
    }
    fun parentsOf(node: Int, visit: (Int) -> Unit) {
        for (i in parentOffsets[node] until parentOffsets[node + 1]) visit(parents[i])
    }

    /** All ordinal vectors are private, detached primitive arrays. Mark runs use binary search. */
    private class BaseLeaves(val all: IntArray, val marks: IntArray, val offsets: IntArray, val marked: IntArray)
    private class IndexBuilder {
        val all = IntArrayList()
        val marks = Int2ObjectOpenHashMap<IntArrayList>()
    }
    private val byBase: Map<AccessPathBase, BaseLeaves> = buildMap {
        val scratch = LinkedHashMap<AccessPathBase, IndexBuilder>()
        for (ordinal in leaves.indices) {
            cancellation.checkpoint()
            val fact = leaves[ordinal].fact
            val builder = scratch.getOrPut(fact.base) { IndexBuilder() }
            builder.all.add(ordinal)
            val mark = (fact.mark as MarkSlot.Concrete).mark.id
            builder.marks.getOrPut(mark) { IntArrayList() }.add(ordinal)
        }
        for ((base, builder) in scratch) {
            cancellation.checkpoint()
            val marks = builder.marks.keys.toIntArray().also { it.sort() }
            val offsets = IntArray(marks.size + 1)
            val marked = IntArray(builder.all.size)
            var cursor = 0
            for (index in marks.indices) {
                cancellation.checkpoint()
                offsets[index] = cursor
                val ordinals = checkNotNull(builder.marks[marks[index]])
                for (position in 0 until ordinals.size) {
                    cancellation.checkpoint()
                    marked[cursor++] = ordinals.getInt(position)
                }
            }
            offsets[marks.size] = cursor
            put(base, BaseLeaves(builder.all.toIntArray(), marks, offsets, marked))
        }
    }

    /** FLOW has no mark and must visit every read on its base to produce requests. */
    fun matchingLeaves(base: AccessPathBase, mark: TaintMark?, visit: (Int, Pattern) -> Unit) {
        val index = byBase[base] ?: return
        if (mark == null) {
            for (ordinal in index.all) visit(ordinal, leaves[ordinal])
            return
        }
        val run = index.marks.binarySearch(mark.id)
        if (run < 0) return
        for (position in index.offsets[run] until index.offsets[run + 1]) {
            val ordinal = index.marked[position]
            visit(ordinal, leaves[ordinal])
        }
    }

    /** Compiler scratch is discarded after build. No branch or action product is built. */
    @Suppress("UNUSED_PARAMETER")
    class Builder(private val cancellation: Cancellation, catalog: MarkTable? = null) {
        private data class Node(val kind: Kind, val children: List<Int>, val leaf: Pattern? = null)
        private val nodes = ArrayList<Node>()
        private val canonical = HashMap<Node, Int>()
        val falseNode = intern(Node(Kind.FALSE, emptyList()))
        val trueNode = intern(Node(Kind.TRUE, emptyList()))

        private fun intern(node: Node): Int {
            cancellation.checkpoint()
            return canonical.getOrPut(node) { nodes.size.also { nodes += node } }
        }

        fun leaf(pattern: Pattern): Int {
            require(pattern.fact.mark is MarkSlot.Concrete)
            val owned = pattern.copy(fact = pattern.fact.copy(path = ownedList(pattern.fact.path)))
            return intern(Node(Kind.LEAF, emptyList(), owned))
        }

        fun and(children: List<Int>): Int = junction(Kind.AND, children)
        fun or(children: List<Int>): Int = junction(Kind.OR, children)

        private fun junction(kind: Kind, children: List<Int>): Int {
            cancellation.checkpoint()
            require(children.all { it in nodes.indices })
            val identity = if (kind == Kind.AND) trueNode else falseNode
            val absorbing = if (kind == Kind.AND) falseNode else trueNode
            if (absorbing in children) return absorbing
            val live = children.filter { it != identity }.distinct()
            return when (live.size) {
                0 -> identity
                1 -> live[0]
                else -> intern(Node(kind, ownedList(live)))
            }
        }

        fun build(root: Int): RulePredicate {
            require(root in nodes.indices)
            val active = BooleanArray(nodes.size)
            val work = ArrayDeque<Int>()
            work.add(root)
            while (work.isNotEmpty()) {
                cancellation.checkpoint()
                val node = work.removeLast()
                if (active[node]) continue
                active[node] = true
                nodes[node].children.forEach(work::addLast)
            }
            val remap = IntArray(nodes.size) { -1 }
            var count = 0
            for (i in nodes.indices) if (active[i]) remap[i] = count++
            val tags = ByteArray(count)
            val offsets = IntArray(count + 1)
            val leafAt = IntArray(count) { -1 }
            val children = ArrayList<Int>()
            val leaves = ArrayList<Pattern>()
            val leafNodes = ArrayList<Int>()
            val atoms = arrayOfNulls<Set<Int>>(count)
            val singletons = arrayOfNulls<Set<Int>>(count)
            val multi = HashSet<Int>()
            for (old in nodes.indices) {
                if (!active[old]) continue
                cancellation.checkpoint()
                val id = remap[old]
                val node = nodes[old]
                tags[id] = node.kind.ordinal.toByte()
                offsets[id] = children.size
                val childIds = node.children.map { remap[it] }
                children.addAll(childIds)
                when (node.kind) {
                    Kind.FALSE, Kind.TRUE -> {
                        atoms[id] = emptySet(); singletons[id] = emptySet()
                    }
                    Kind.LEAF -> {
                        val ordinal = leaves.size
                        leafAt[id] = ordinal
                        leaves += checkNotNull(node.leaf)
                        leafNodes += id
                        atoms[id] = setOf(ordinal); singletons[id] = setOf(ordinal)
                    }
                    Kind.AND, Kind.OR -> {
                        val all = childIds.flatMapTo(LinkedHashSet()) { checkNotNull(atoms[it]) }
                        atoms[id] = all
                        singletons[id] = if (node.kind == Kind.OR)
                            childIds.flatMapTo(LinkedHashSet()) { checkNotNull(singletons[it]) }
                        else childIds.map { checkNotNull(singletons[it]) }.reduce { a, b -> a.intersect(b) }
                        // With positive live children, all atoms of an AND can take part in a
                        // proof with another distinct atom. Repeated canonical leaves count once.
                        if (node.kind == Kind.AND && all.size >= 2) multi.addAll(all)
                    }
                }
            }
            offsets[count] = children.size
            val parentsCount = IntArray(count)
            for (child in children) parentsCount[child]++
            val parentOffsets = IntArray(count + 1)
            for (i in 0 until count) parentOffsets[i + 1] = parentOffsets[i] + parentsCount[i]
            val cursors = parentOffsets.copyOf()
            val parents = IntArray(children.size)
            for (node in 0 until count) for (i in offsets[node] until offsets[node + 1]) {
                cancellation.checkpoint()
                parents[cursors[children[i]]++] = node
            }
            val unaryFlags = BooleanArray(leaves.size)
            for (leaf in checkNotNull(singletons[remap[root]])) unaryFlags[leaf] = true
            val multiFlags = BooleanArray(leaves.size)
            for (leaf in multi) multiFlags[leaf] = true
            return RulePredicate(remap[root], tags, offsets, children.toIntArray(), leafAt,
                ownedList(leaves), leafNodes.toIntArray(), parentOffsets, parents,
                unaryFlags, multiFlags, cancellation)
        }
    }
}

package org.opentaint.dataflow.bidi.interp

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.Cleaner
import org.opentaint.dataflow.bidi.ap.MarkSet
import org.opentaint.dataflow.bidi.ap.MarkSlot
import org.opentaint.dataflow.bidi.ap.Pattern
import org.opentaint.dataflow.bidi.ap.Tail
import org.opentaint.dataflow.bidi.ap.TaintMark
import org.opentaint.dataflow.configuration.CommonTaintConfigurationSink

/** One stable sink alternative. Repeated patterns retain separate literal slots. */
class SinkRule(
    val rule: CommonTaintConfigurationSink,
    val alternative: Int,
    patterns: List<Pattern>,
    endFacts: List<MicroEdge>,
    val occurrenceId: RuleOccurrenceId? = null,
    val predicate: RulePredicate? = null,
) {
    /** Legacy/manual forms keep their fresh object scope; JVM predicate forms supply a value key. */
    val joinKey: Any get() = occurrenceId ?: this
    val patterns: List<Pattern> = snapshotPatterns(patterns)
    /** Keep cached micro edges and their original forward identities. Their producers own their paths. */
    val endFacts: List<MicroEdge> = ownedList(endFacts)

    init {
        require(predicate == null || occurrenceId != null) { "A compiled predicate needs a stable rule occurrence" }
        check(this.patterns.isNotEmpty()) { "A sink has a positive literal or the zero pattern" }
        check(this.patterns.all {
            it.fact.mark is MarkSlot.Concrete && (it.fact.tail == Tail.EXACT || it.fact.tail == Tail.ANY)
        }) { "A sink literal has a concrete mark and an exact or may tail" }
    }

    val unconditional: Boolean get() = patterns.size == 1 && patterns[0].fact.base == AccessPathBase.Zero
    val conjunctive: Boolean get() = patterns.size >= 2

    /** Zero already enters every method; each other literal seeds its original exact or may requirement. */
    fun seedPatterns(): List<Pattern> = if (unconditional) emptyList() else patterns
}

private fun snapshotPatterns(patterns: List<Pattern>): List<Pattern> {
    val iterator = patterns.iterator()
    return ownedList(patterns.size) {
        val p = iterator.next()
        p.copy(fact = p.fact.copy(path = ownedList(p.fact.path)))
    }
}

/** Statement-mode rule actions and GEN end facts share stable sink alternatives. */
class RuleStatement(val summary: StatementSummary, val endFacts: StatementSummary, sinks: List<SinkRule>) {
    val sinks: List<SinkRule> = ownedList(sinks)

    /** Reverse the two action modes separately; untouched forward GEN targets need A5 pass-over identities. */
    fun reversed(): RuleStatement {
        val s = summary.reversed()
        val revEnd = StatementSummary(emptySet(), endFacts.edges.map { MicroEdge(revOrFail(it.edge), it.forward, it.conjunctive, it.actionId) },
            emptyList(), emptyMap())
        return RuleStatement(s.withIdentities(passOverBases(endFacts.targets, s.touched)), revEnd, sinks)
    }

    companion object { val EMPTY = RuleStatement(StatementSummary.EMPTY, StatementSummary.EMPTY, emptyList()) }
}

/** Forward normal-exit removals. Exceptional exits use no drop flag and an empty entry-mark set. */
class ExitRules(val rules: RuleStatement, val globalStateDrop: Boolean, entryMarks: Set<TaintMark>) {
    val entryMarks: Set<TaintMark> = ownedSet(entryMarks)
    private val entryMarkSet = if (this.entryMarks.isEmpty()) MarkSet.EMPTY
        else MarkSet(this.entryMarks.map { it.id }.toIntArray())

    /** G2 removals belong only to the forward exit; the reversed value contains rule actions alone. */
    fun reversed(): RuleStatement = rules.reversed()

    fun entryMarkRemoval(base: AccessPathBase): MarkSet? =
        if (entryMarkSet.isEmpty || (base != AccessPathBase.This && base !is AccessPathBase.Argument)) null else entryMarkSet

    companion object { val EMPTY = ExitRules(RuleStatement.EMPTY, false, emptySet()) }
}

/** Generated callees supply callee-coordinate cleaners for the cached ordered Actions stage. */
interface CallCleaners {
    val callCleaners: List<Cleaner>
}

/** Field actions keep their read and strong write as statements around one fresh temporary cleaner. */
sealed interface CleanStep {
    fun reversed(): CleanStep

    class Clean(val cleaner: Cleaner) : CleanStep {
        override fun reversed() = this
    }

    class Kill(val keepEdges: StatementSummary) : CleanStep {
        override fun reversed() = Kill(keepEdges.reversed())
    }

    class Field(val temporary: AccessPathBase, val read: StatementSummary,
                val cleaner: Cleaner, val write: StatementSummary) : CleanStep {
        init { check(cleaner.base == temporary && cleaner.path == null) { "A field cleaner acts at its temporary root" } }
        override fun reversed() = Field(temporary, write.reversed(), cleaner, read.reversed())
    }
}

package org.opentaint.dataflow.bidi.interp

import org.opentaint.dataflow.bidi.ap.PathFact
import org.opentaint.dataflow.bidi.ap.Pattern
import org.opentaint.dataflow.bidi.ap.ExclusionSet
import org.opentaint.dataflow.bidi.ap.PathEdge

class SourceAction(val id: ActionId, target: PathFact) {
    val target: PathFact = target.copy(path = ownedList(target.path))
}

/** Existing unary AP transfer, with its bound input retained through GROUP folding. */
class SourceUnaryTransfer(val predicate: RulePredicate, anchor: Pattern) {
    val anchor: Pattern = anchor.copy(fact = anchor.fact.copy(path = ownedList(anchor.fact.path)))
}

/** Conditions and action targets are separate vectors, with no leaf/action product. */
class SourceRuleOccurrence(
    val id: RuleOccurrenceId,
    val predicate: RulePredicate,
    actions: List<SourceAction>,
    val backward: Boolean = false,
    val groupTransfers: Boolean = false,
    unaryTransfers: List<SourceUnaryTransfer> = emptyList(),
    val multiPredicate: RulePredicate? = null,
) {
    val actions: List<SourceAction> = ownedList(actions)
    val unaryTransfers: List<SourceUnaryTransfer> = ownedList(unaryTransfers)
    init { require(!predicate.isFalse && !predicate.isTrue) { "Constants use the unconditional placement path" } }

    fun reversed(): SourceRuleOccurrence = SourceRuleOccurrence(id, predicate, actions, !backward,
        groupTransfers, unaryTransfers, multiPredicate)

    /** This short-lived transfer view is built only when its leaf and action are used. */
    fun transfer(leaf: Pattern, action: SourceAction, multi: Boolean = false): MicroEdge {
        val forward = PathEdge(leaf.fact, action.target, ExclusionSet.Empty)
        return if (backward) MicroEdge(revOrFail(forward), forward, conjunctive = multi, actionId = action.id)
        else MicroEdge(forward, forward, conjunctive = multi, actionId = action.id)
    }
}

package org.opentaint.dataflow.bidi.interp

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.ConjunctiveEdge
import org.opentaint.dataflow.bidi.ap.ExclusionSet
import org.opentaint.dataflow.bidi.ap.PathEdge
import org.opentaint.dataflow.bidi.ap.TypeFilter
import org.opentaint.dataflow.bidi.ap.revEdge

/** Cached form containers own their contents and retain the identities of supplied forms and filters. */
class StatementSummary(
    touched: Set<AccessPathBase>,
    edges: List<MicroEdge>,
    conjunctions: List<ConjunctiveEdge>,
    typeFilters: Map<AccessPathBase, TypeFilter>,
    resultFilters: Map<AccessPathBase, TypeFilter> = emptyMap(),
    sources: List<SourceRuleOccurrence> = emptyList(),
    staticOperations: List<StaticOperation> = emptyList(),
) {
    val touched: Set<AccessPathBase> = ownedSet(touched)
    val edges: List<MicroEdge> = ownedList(edges)
    val conjunctions: List<ConjunctiveEdge> = ownedList(conjunctions)
    val typeFilters: Map<AccessPathBase, TypeFilter> = ownedMap(typeFilters)
    val resultFilters: Map<AccessPathBase, TypeFilter> = ownedMap(resultFilters)
    val sources: List<SourceRuleOccurrence> = ownedList(sources)
    val staticOperations: List<StaticOperation> = ownedList(staticOperations)

    fun withStaticOperations(operations: List<StaticOperation>): StatementSummary =
        StatementSummary(touched, edges, conjunctions, typeFilters, resultFilters, sources, operations)

    private val byBase: Map<AccessPathBase, List<MicroEdge>> = ownedOrdinalGroups(this.edges) { it.edge.from.base }

    fun edgesOf(b: AccessPathBase): List<MicroEdge> = byBase[b].orEmpty()

    internal fun storage(counts: FormStorageCounts) {
        counts.statementSummaries++
        counts.include(touched)
        counts.include(edges)
        counts.include(conjunctions)
        counts.include(typeFilters)
        counts.include(resultFilters)
        counts.include(sources)
        counts.include(staticOperations)
        counts.include(targets)
        counts.summaryBaseDirectoryEntries += byBase.size.toLong()
        ownedDirectoryStorage(byBase, counts)
        for (source in sources) counts.include(source.actions)
    }

    val targets: Set<AccessPathBase> = run {
        val sourceTargets = this.sources.flatMap { source -> source.actions.map { it.target.base } }
        ownedSet(ownedList(this.edges.size + this.conjunctions.size + sourceTargets.size) { index ->
            if (index < this.edges.size) this.edges[index].edge.to.base
            else if (index < this.edges.size + this.conjunctions.size) this.conjunctions[index - this.edges.size].target.base
            else sourceTargets[index - this.edges.size - this.conjunctions.size]
        })
    }

    /** Conjunctive sources reverse into independent demand branches. Forward filters do not reverse. */
    fun reversed(): StatementSummary {
        val rev = ArrayList<MicroEdge>()
        for (e in edges) rev += MicroEdge(revOrFail(e.edge), e.forward, e.conjunctive, e.actionId)
        for (c in conjunctions) for (lit in c.literals) {
            val forward = PathEdge(lit.fact, c.target, ExclusionSet.Empty)
            rev += MicroEdge(revOrFail(forward), forward, conjunctive = true)
        }
        val back = StatementSummary(touched + targets, rev, emptyList(), emptyMap(), sources = sources.map { it.reversed() })
        return back.withIdentities(passOverBases(targets, touched))
    }

    fun withIdentities(bases: Collection<AccessPathBase>): StatementSummary {
        if (bases.isEmpty()) return this
        val added = ownedList(bases)
        val combined = ownedList(edges.size + added.size) { index ->
            if (index < edges.size) edges[index] else identityEdge(added[index - edges.size])
        }
        return StatementSummary(touched + added, combined, conjunctions, typeFilters, resultFilters, sources, staticOperations)
    }

    companion object {
        val EMPTY = StatementSummary(emptySet(), emptyList(), emptyList(), emptyMap())
        fun identities(bases: Collection<AccessPathBase>): StatementSummary = EMPTY.withIdentities(bases)
    }
}

/** Every supplied statement edge must have an ordinary mark reversal (I11). */
internal fun revOrFail(e: PathEdge): PathEdge =
    revEdge(e) ?: error("not mark-reversible (interpreter.md I11 (b)): $e")

/** A forward target that was not killed keeps its requirement in the reversed form (A5). */
internal fun passOverBases(targets: Iterable<AccessPathBase>, touched: Set<AccessPathBase>): Set<AccessPathBase> =
    targets.filterTo(LinkedHashSet()) { it !in touched }

fun identityEdge(b: AccessPathBase): MicroEdge = MicroEdge.of(keepEdge(b))

package org.opentaint.dataflow.bidi.interp

import org.opentaint.dataflow.bidi.ap.PathEdge
import org.opentaint.dataflow.bidi.ap.Pattern

/** A logical operation address survives eviction and rebuilding of a full form. */
data class OperationId(
    val form: FormKey,
    val stageOrdinal: Int = 0,
    val action: ActionId? = null,
    val substep: Int = 0,
) {
    init { require(stageOrdinal >= 0 && substep >= 0) }
}

/** Lowering supplies these descriptors. A static destination alone does not identify a write. */
sealed interface StaticOperation {
    val id: OperationId

    data class Read(override val id: OperationId, val transfer: PathEdge) : StaticOperation
    data class Write(
        override val id: OperationId,
        val target: Pattern,
        val transfer: PathEdge? = null,
        val action: ActionId? = id.action,
    ) : StaticOperation
    data class MarkInput(
        override val id: OperationId,
        val position: Pattern,
        // ANY predicates include their point. A BELOW cleaner excludes it.
        val includeBase: Boolean = true,
    ) : StaticOperation
}

enum class CleanerPhase { INPUT, READ, CLEAN, WRITE }

/** The operation input is different from its output; replies never restart a method entry. */
sealed interface ResumeSite {
    val operation: OperationId
    data class StatementInput(override val operation: OperationId) : ResumeSite
    data class BoundaryInput(override val operation: OperationId, val atStart: Boolean) : ResumeSite
    data class CallStageInput(override val operation: OperationId) : ResumeSite
    data class CleanerInput(
        override val operation: OperationId,
        val step: Int,
        val phase: CleanerPhase,
    ) : ResumeSite
    data class ReadOutput(override val operation: OperationId, val input: ResumeSite) : ResumeSite
}

