/** Storage/control identity only. It is not part of a fact, rule or mark key. */
data class BlockScope(val block: BlockId, val entry: PortId) {
    companion object { val ROOT = BlockScope(BlockId(0), PortId.ROOT_ENTRY) }
}

data class OwnedScope(val method: MethodKey, val local: BlockScope)

/** A row keeps both ports. Opposite-direction lookup exchanges their roles. */
data class ScopedSummaryKey(val method: MethodKey, val scope: BlockScope, val exit: PortId) {
    fun reversed(): ScopedSummaryKey = copy(scope = BlockScope(scope.block, exit), exit = scope.entry)
}

package org.opentaint.dataflow.bidi.store

import org.opentaint.dataflow.bidi.ap.InitialAp
import org.opentaint.dataflow.bidi.ap.Pattern

/** C5 can reject a packed label before graph-owner tests and endpoint allocation. */
internal fun interface StaticCandidateFilter {
    fun keep(from: Pattern, to: Pattern, marks: GuidanceMarks): Boolean
}

/** Internal capability; packed storage and its geometry stay private to the snapshot. */
internal interface C5StaticDemandView : StaticDemandView {
    fun c5Targets(actual: Pattern, prefixesOnly: Boolean, keep: StaticCandidateFilter): Sequence<StaticGuidanceEdge>
    fun c5Incoming(input: Pattern, flowOnly: Boolean, keep: StaticCandidateFilter): Sequence<StaticGuidanceEdge>
    fun c5HasComposedEndpoints(initial: InitialAp, outputs: List<Pattern>, keepTarget: StaticCandidateFilter): Boolean
    fun selectedTargets(actual: Pattern, prefixesOnly: Boolean, query: StaticRowQuery,
                        keep: StaticCandidateFilter): Sequence<StaticGuidanceEdge> = c5Targets(actual, prefixesOnly, keep)
    fun selectedIncoming(input: Pattern, query: StaticRowQuery,
                         keep: StaticCandidateFilter): Sequence<StaticGuidanceEdge> = c5Incoming(input, false, keep)
    fun selectedHasComposedEndpoints(initial: InitialAp, outputs: List<Pattern>, query: StaticRowQuery,
                                     keep: StaticCandidateFilter): Boolean = c5HasComposedEndpoints(initial, outputs, keep)
}

internal fun StaticDemandView.filteredTargets(
    actual: Pattern, prefixesOnly: Boolean, keep: StaticCandidateFilter,
): Sequence<StaticGuidanceEdge> = when (this) {
    is C5StaticDemandView -> c5Targets(actual, prefixesOnly, keep)
    else -> targets(actual, prefixesOnly).filter { keep.keep(it.from, it.to, it.marks) }
}

internal fun StaticDemandView.filteredIncoming(
    input: Pattern, flowOnly: Boolean, keep: StaticCandidateFilter,
): Sequence<StaticGuidanceEdge> = when (this) {
    is C5StaticDemandView -> c5Incoming(input, flowOnly, keep)
    else -> incoming(input, flowOnly).filter { keep.keep(it.from, it.to, it.marks) }
}

internal fun StaticDemandView.filteredHasComposedEndpoints(
    initial: InitialAp, outputs: List<Pattern>, keepTarget: StaticCandidateFilter,
): Boolean = when (this) {
    is C5StaticDemandView -> c5HasComposedEndpoints(initial, outputs, keepTarget)
    // A coarse fallback is sufficient: filteredTargets will discard impossible seeds.
    else -> hasComposedEndpoints(initial, outputs)
}

internal fun StaticDemandView.selectedTargets(
    actual: Pattern, prefixesOnly: Boolean, query: StaticRowQuery, keep: StaticCandidateFilter,
): Sequence<StaticGuidanceEdge> = when (this) {
    is C5StaticDemandView -> selectedTargets(actual, prefixesOnly, query, keep)
    else -> filteredTargets(actual, prefixesOnly, keep)
}

internal fun StaticDemandView.selectedIncoming(
    input: Pattern, query: StaticRowQuery, keep: StaticCandidateFilter,
): Sequence<StaticGuidanceEdge> = when (this) {
    is C5StaticDemandView -> selectedIncoming(input, query, keep)
    else -> filteredIncoming(input, false, keep)
}

internal fun StaticDemandView.selectedHasComposedEndpoints(
    initial: InitialAp, outputs: List<Pattern>, query: StaticRowQuery, keep: StaticCandidateFilter,
): Boolean = when (this) {
    is C5StaticDemandView -> selectedHasComposedEndpoints(initial, outputs, query, keep)
    else -> filteredHasComposedEndpoints(initial, outputs, keep)
}

package org.opentaint.dataflow.bidi.store

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.engine.N2Statistics
import org.opentaint.ir.api.common.cfg.CommonInst
import java.util.Collections

/** The semantic E6 member after full matching; no accepted Facts version is retained. */
internal data class NdBinding(val ref: CallerRef, val linkLayer: Layer) {
    // Invocation metadata never changes the accepted E6 member key.
    var triggering: TaintMark? = null
    var nonSubsumable: Boolean = false
}

/** Standing literal inputs for one method and run. One writer owns this store. */
class ConjunctionStore(private val m: ApManager, private val statistics: N2Statistics? = null,
                       private val premises: PremiseCombination = ExactPremises(m)) {
    /** Facts already accepted by the literal; layer is the effective contribution layer. */
    data class Input(val premise: PremiseKey, val layer: Layer, val facts: Facts? = null)
    class Combination(val premise: PremiseKey, val layer: Layer, val inputs: List<Input>)
    class CompleteBinding(val layer: Layer, val inputs: List<Input>)

    private val joins = HashMap<Pair<Any, CommonInst>, KaryJoin<Input>>()

    /** Rule alternatives and statements have separate joins; repeated literals retain separate slots. */
    fun add(rule: Any, statement: CommonInst, arity: Int, literal: Int, input: Input): List<Combination> {
        return addBinding(rule, statement, arity, literal, input).map { binding ->
            Combination(premises.combine(binding.inputs.asSequence().map { it.premise }.asIterable()),
                binding.layer, binding.inputs)
        }
    }

    /** Witness consumers keep the entire checked binding without constructing an executable premise. */
    fun addBinding(rule: Any, statement: CommonInst, arity: Int, literal: Int, input: Input): List<CompleteBinding> {
        m.cancellation.checkpoint()
        if (!RuntimeDataDomain.premise(input.premise) ||
            input.facts?.let { !RuntimeDataDomain.base(it.base) } == true) return emptyList()
        require(arity >= 2) { "A conjunction needs at least two literals" }
        require(literal in 0 until arity) { "A literal index must be within the conjunction's arity" }
        val key = rule to statement
        val join = joins[key]
        require(join == null || join.arity == arity) { "A rule at a statement has one fixed arity" }
        val state = join ?: KaryJoin<Input>(arity, m.cancellation).also { joins[key] = it }
        val previous = state.current(literal, input)
        val inputs = if (previous == null) state.add(literal, input)
        else {
            val oldFacts = previous.facts ?: return emptyList()
            val (merged, delta) = m.mergeAddDelta(oldFacts, checkNotNull(input.facts))
            if (delta == null) return emptyList()
            val updated = previous.copy(facts = merged)
            // Recompute only the already-complete semantic combinations at
            // this slot. The equal member key changes no product set, and no
            // Cartesian-product archive is retained for annotation replay.
            check(updated == previous)
            state.replace(literal, previous, updated)
        }
        val out = ArrayList<CompleteBinding>(inputs.size)
        for (combination in inputs) {
            m.cancellation.checkpoint()
            out += combine(combination)
        }
        return out
    }

    private fun combine(inputs: List<Input>): CompleteBinding {
        var layer = Layer.NORMAL
        for (index in inputs.indices) {
            m.cancellation.checkpoint()
            val input = inputs[index]
            if (input.layer == Layer.DEMAND) layer = Layer.DEMAND
        }
        return CompleteBinding(layer, inputs)
    }

    /** An E6 join belongs to one callee context, premise set, publication layer and caller call. */
    data class NdKey(val callee: MethodKey, val premise: PremiseKey, val layer: Layer, val call: CommonInst,
                     val stageOrdinal: Int = 0, val scope: BlockScope = BlockScope.ROOT)
    private val ndJoins = HashMap<NdKey, NdSummaryJoin<*>>()

    @Suppress("UNCHECKED_CAST")
    fun <S : Any> ndJoin(key: NdKey): NdSummaryJoin<S> {
        m.cancellation.checkpoint()
        return ndJoins.getOrPut(key) { NdSummaryJoin<S>(m, key.premise.size, statistics) } as NdSummaryJoin<S>
    }
}

/** E6 keeps every full member combination and growing TAINT conclusions. Matching is caller-owned. */
class NdSummaryJoin<S : Any>(private val m: ApManager, arity: Int, private val statistics: N2Statistics? = null) {
    private val members = KaryJoin<S>(arity, m.cancellation)
    private val full = ArrayList<List<S>>()
    private val interners = m.newInterners()
    private val conclusion = HashMap<AccessPathBase, TaintGroup>(2)

    internal val memberCount: Int get() = members.memberCount
    internal val combinationCount: Int get() = full.size

    /** Put a subscription under every member index it satisfies; new combinations meet all stored values. */
    fun addSubscription(index: Int, s: S, upgrade: ((S, S) -> Boolean)? = null): List<Pair<List<S>, TaintTree>> {
        m.cancellation.checkpoint()
        val previous = members.current(index, s)
        if (previous != null) {
            statistics?.recordE6(0, 1, 0)
            if (upgrade == null || !upgrade(previous, s)) return emptyList()
            val out = ArrayList<Pair<List<S>, TaintTree>>()
            for (combination in full) {
                m.cancellation.checkpoint()
                if (combination[index] !== previous) continue
                for (group in conclusion.values) for (g in group.all()) out += combination to g
            }
            return out
        }
        val previousMembers = if (statistics != null) members.memberCount else 0
        val fresh = members.add(index, s)
        statistics?.let {
            val newBindings = members.memberCount - previousMembers
            it.recordE6(newBindings, 1 - newBindings, fresh.size)
        }
        val out = ArrayList<Pair<List<S>, TaintTree>>()
        for (inputs in fresh) {
            m.cancellation.checkpoint()
            val owned = ArrayList<S>(inputs.size)
            for (input in inputs) {
                m.cancellation.checkpoint()
                owned += input
            }
            val combination: List<S> = Collections.unmodifiableList(owned)
            full += combination
            for (group in conclusion.values) {
                m.cancellation.checkpoint()
                for (g in group.all()) {
                    m.cancellation.checkpoint()
                    out += combination to g
                }
            }
        }
        return out
    }

    /** T4 applies the new part, or a whole T2 merged value, to every standing combination. */
    fun addConclusion(g: TaintTree): List<Pair<List<S>, TaintTree>> {
        m.cancellation.checkpoint()
        if (!RuntimeDataDomain.base(g.base)) return emptyList()
        val deltas = conclusion.getOrPut(g.base) { TaintGroup(m, interners.taint) }.addAll(g)
        if (deltas.isEmpty()) return emptyList()
        val out = ArrayList<Pair<List<S>, TaintTree>>(full.size)
        for (combination in full) {
            m.cancellation.checkpoint()
            for (delta in deltas) out += combination to delta
        }
        return out
    }
}

package org.opentaint.dataflow.bidi.store

import org.opentaint.dataflow.bidi.ap.Pattern

/** Control endpoints do not have an access path and must not enter an AP trie. */
sealed interface DemandEntry {
    data class Data(val pattern: Pattern) : DemandEntry
    data object Zero : DemandEntry
    data object Target : DemandEntry
}

sealed interface DemandExit {
    data class Data(val pattern: Pattern) : DemandExit
    data object Zero : DemandExit
}

data class PairedDemand(val entry: DemandEntry, val exit: DemandExit)

package org.opentaint.dataflow.bidi.store

import org.opentaint.dataflow.bidi.ap.*
import java.util.ArrayDeque
import java.util.concurrent.atomic.AtomicLong
import java.util.concurrent.atomic.AtomicLongArray

internal enum class PreparedPlanFallback {
    RUN, STATIC_COMPLETION, SHARED_CARRY, EMPTY_TEMPLATES, OVERSIZE_TEMPLATES, ZERO_TEMPLATE, OCCURRENCE_BUDGET,
}

/** Counters only. A query never retains its path trace in the frozen snapshot. */
internal class DemandQueryStatistics : DemandScalarWork {
    private val values = AtomicLongArray(18)
    private val admissions = AtomicLongArray(16 * 5)
    private val restriction = AtomicLongArray(11)
    private val depths = AtomicLongArray(5 * 17)
    private val sampleOrdinal = AtomicLong()
    private val rowSamples = ArrayDeque<String>()
    private val prepared = AtomicLongArray(12)
    private val tries = AtomicLongArray(3)
    private val preparedFallbacks = AtomicLongArray(PreparedPlanFallback.entries.size)
    fun add(kind: Int, amount: Long = 1) { values.addAndGet(kind, amount) }
    fun preparedPlan(checked: Int, accepted: Int, programs: Int) {
        prepared.incrementAndGet(0)
        prepared.addAndGet(1, checked.toLong())
        prepared.addAndGet(2, accepted.toLong())
        prepared.addAndGet(3, programs.toLong())
    }
    fun preparedQuery() { prepared.incrementAndGet(4) }
    fun preparedFallback(reason: PreparedPlanFallback) { preparedFallbacks.incrementAndGet(reason.ordinal) }
    override fun stream() { prepared.incrementAndGet(5) }
    override fun scalar() { prepared.incrementAndGet(6) }
    override fun candidate() { prepared.incrementAndGet(7) }
    override fun selectedReference(size: Int) {
        prepared.incrementAndGet(8)
        var old = prepared[9]
        while (size > old && !prepared.compareAndSet(9, old, size.toLong())) old = prepared[9]
    }
    override fun overflow() { prepared.incrementAndGet(10) }
    override fun pack() { prepared.incrementAndGet(11) }
    /** Aggregate once per trie query; disabled diagnostics perform no counter updates. */
    fun trieQuery(nodes: Long, profiles: Long, candidates: Long) {
        tries.addAndGet(0, nodes)
        tries.addAndGet(1, profiles)
        tries.addAndGet(2, candidates)
    }
    fun admission(entry: Pattern, actual: Pattern, emitted: Pattern?) {
        val cell = (entry.fact.tail.ordinal * 4 + actual.fact.tail.ordinal) * 5
        admissions.incrementAndGet(cell + if (emitted == null) 4 else emitted.fact.tail.ordinal)
    }
    /** DATA row/packet attempts, not unique facts or logical paths. Bin 16 includes all larger depths. */
    fun dataRow(raw: Facts, exit: Pattern, budget: Int, route: Int) {
        restriction.incrementAndGet(0)
        restriction.incrementAndGet(7 + route)
        depth(0, maxDepth(raw))
        depth(1, exit.fact.path.count { it.isCounted() })
        depth(2, budget)
    }
    fun rejectedRow() { restriction.incrementAndGet(1) }
    fun selected(value: Facts, budget: Int) {
        restriction.incrementAndGet(2)
        restriction.incrementAndGet(3)
        val max = maxDepth(value)
        if (max > budget) restriction.incrementAndGet(5)
        depth(3, max)
    }
    fun limited(selected: Facts, value: Facts) {
        restriction.incrementAndGet(4)
        if (selected.layer == Layer.NORMAL && value.layer == Layer.DEMAND) restriction.incrementAndGet(6)
        depth(4, maxDepth(value))
    }
    /** A sampled row holds copied scalar text only. It is not propagation state. */
    fun sampleRow(method: MethodKey, member: InitialAp, raw: Facts, pair: DemandPattern,
                  budget: Int, route: Int): String? =
        samplePreparedRow(method, member.toPattern(), raw, pair, budget, route)
    fun samplePreparedRow(method: MethodKey, member: Pattern, raw: Facts, pair: DemandPattern,
                          budget: Int, route: Int): String? {
        val ordinal = sampleOrdinal.incrementAndGet()
        if (ordinal > 16 && ordinal % 4096L != 0L) return null
        return "method=${method.toString().take(300)} route=$route matchingMember=${describe(member)} " +
            "Dc=${describe(pair.entry)} Dp=${pair.exit?.let(::describe)} budget=$budget raw=${describe(raw)}"
    }
    fun sampleResult(row: String?, selected: Facts?, admitted: Facts?) {
        if (row == null) return
        val value = "$row selected=${selected?.let(::describe)} admitted=${admitted?.let(::describe)}"
        synchronized(rowSamples) {
            if (rowSamples.size == 64) rowSamples.removeFirst()
            rowSamples.addLast(value)
        }
    }
    fun rowSamples(): List<String> = synchronized(rowSamples) { rowSamples.toList() }
    private fun describe(pattern: Pattern): String {
        val mark = when (val slot = pattern.fact.mark) {
            is MarkSlot.Concrete -> slot.mark.id.toString()
            is MarkSlot.Star -> "FLOW/mx${slot.excluded.data.take(8)}"
        }
        val exclusion = (pattern.exclusion as? ExclusionSet.Concrete)?.data?.take(8) ?: emptyList()
        return "${pattern.fact.base}:${pattern.fact.path.take(12)}/${pattern.fact.tail}/$mark/E$exclusion"
    }
    private fun describe(value: Facts): String {
        val root = when (value) { is Reach -> null; is FlowTree -> value.root; is TaintTree -> value.root }
        val tail = when (value) { is Reach -> "ZERO"; is FlowTree -> value.tail.name; is TaintTree -> value.anyTail.name }
        var node = root
        val path = ArrayList<Int>()
        while (node != null && path.size < 12 && node.accessorData != null) {
            path += node.accessorData[0]; node = node.childData!![0]
        }
        val leaf = node?.leaf
        val marks = if (leaf is TaintLeaves) leaf.exact.data.take(2) + leaf.any.data.take(2) else emptyList()
        val exclusion = when (value) {
            is Reach -> ExclusionSet.Empty
            is FlowTree -> value.exclusion
            is TaintTree -> value.exclusion
        }
        val fields = (exclusion as? ExclusionSet.Concrete)?.data?.take(8) ?: emptyList()
        val mx = (value as? FlowTree)?.markExclusion?.data?.take(8) ?: emptyList()
        return "${value.base}:firstBranch$path/$tail/${value.layer}/marks$marks/maxFL${maxDepth(value)}/" +
            "protected${value is TaintTree && value.nonSubsumable != null}/E$fields/mx$mx"
    }
    private fun maxDepth(value: Facts): Int = when (value) {
        is FlowTree -> value.root.boundedDepth
        is TaintTree -> value.root.boundedDepth
        is Reach -> 0
    }
    private fun depth(kind: Int, value: Int) { depths.incrementAndGet(kind * 17 + minOf(value, 16)) }
    override fun toString(): String = listOf("c2Direct", "c2Local", "c2Visible", "c2Covered", "c2Roots",
        "c2States", "c2Joins", "c5Candidates", "c5States", "c5Restrict", "c5Covered", "c5Visible",
        "c5FixedReject", "c5Duplicate", "c5Popped", "c5Expand", "c5ComposeAttempts", "c5ComposeAccepted")
        .mapIndexed { i, name -> "$name=${values[i]}" }.joinToString(" ") + buildString {
            for ((i, name) in listOf("c5PreparedPlans", "c5PlanOccurrences", "c5AcceptedOccurrences", "c5OutputPrograms",
                "c5ProgramQueries", "c5PacketStreams", "c5ScalarEnumerations", "c5ProgramCandidates",
                "c5SelectedReferences", "c5SelectedReferencePeak", "c5BucketFallbacks", "c5StreamPacks").withIndex())
                append(" $name=${prepared[i]}")
            for ((i, name) in listOf("trieNodes", "trieProfiles", "trieCandidates").withIndex())
                append(" $name=${tries[i]}")
            for ((i, name) in listOf("Run", "StaticCompletion", "SharedCarry", "EmptyTemplates",
                "OversizeTemplates", "ZeroTemplate", "OccurrenceBudget").withIndex())
                append(" c5PlanFallback$name=${preparedFallbacks[i]}")
            for (d in Tail.entries) for (a in Tail.entries) for (result in 0..4) {
                val count = admissions[(d.ordinal * 4 + a.ordinal) * 5 + result]
                if (count != 0L) append(" c2_${d}_${a}_${if (result == 4) "REJECT" else Tail.entries[result]}=$count")
            }
            for ((i, name) in listOf("c5RowAttempts", "c5ExactRejectRows", "c5SelectedPackets", "c5LimitCalls",
                "c5LimitResults", "c5CutInputs", "c5NormalToDemandPackets", "c5LocalRows", "c5VirtualRows",
                "c5ControlRows", "c5CarryRows").withIndex()) append(" $name=${restriction[i]}")
            for ((kind, name) in listOf("Raw", "Dp", "Budget", "Selected", "Admitted").withIndex())
                for (bin in 0..16) {
                    val count = depths[kind * 17 + bin]
                    if (count != 0L) append(" c5MaxDepth${name}_${if (bin == 16) "16plus" else bin}=$count")
                }
        }
}

/** Facts equality omits protection. Join only that annotation for exactly equal ordinary payloads. */
internal class ExactDemandResults(private val ap: ApManager) {
    private val values = LinkedHashMap<Facts, Facts>()
    val hasResults: Boolean get() = values.isNotEmpty()
    fun add(value: Facts) {
        ap.cancellation.checkpoint()
        val old = values[value]
        values[value] = if (old is TaintTree && value is TaintTree) {
            val mask = when {
                old.nonSubsumable == null -> value.nonSubsumable
                value.nonSubsumable == null -> old.nonSubsumable
                else -> ap.taintAlg.mergeAdd(old.nonSubsumable, value.nonSubsumable, ap.cancellation)
            }
            old.withProtection(mask, ap.cancellation)
        } else old ?: value
    }
    fun all(): List<Facts> = values.values.toList()
}

/** Compare structural keys from the scalar emitter. This check never interns hypothetical APs. */
internal class InitialDemandResults(private val ap: ApManager, private val policy: RestrictedInitialPolicy,
                                    private val actualLayer: Layer,
                                    private val statistics: DemandQueryStatistics? = null) {
    val initials = LinkedHashSet<AdmittedInitial>()
    private val keys = HashSet<InitialEmission>()
    private val offered = HashSet<Pair<Pattern, Pattern>>()
    private val missing = HashSet<InitialEmission>()
    val fullyCovered: Boolean get() = missing.isEmpty()

    fun offer(entry: Pattern, actual: Pattern) {
        ap.cancellation.checkpoint()
        if (!offered.add(entry to actual)) return
        val emitted = policy.emitAdmission(entry, actual, actualLayer)
        statistics?.admission(entry, actual, emitted?.pattern)
        if (emitted == null) return
        if (keys.add(emitted)) initials += AdmittedInitial(ap.initial(emitted.pattern), emitted.layer)
        missing.remove(emitted)
    }
    fun has(entry: Pattern, actual: Pattern): Boolean {
        ap.cancellation.checkpoint()
        val emitted = policy.emitAdmission(entry, actual, actualLayer) ?: return true
        return emitted in keys
    }
    fun requireFamily(target: Pattern, flow: Boolean, actual: Pattern) {
        fun require(entry: Pattern) {
            val potential = policy.emitAdmission(entry, actual, actualLayer) ?: return
            if (potential !in keys) missing += potential
        }
        require(target)
        if (flow && actual.fact.mark is MarkSlot.Concrete && actual.fact.mark.mark != TaintMark.ZERO)
            require(target.copy(fact = target.fact.copy(mark = actual.fact.mark)))
    }
}

package org.opentaint.dataflow.bidi.store

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import java.util.Collections
import org.opentaint.dataflow.graph.BlockId
import org.opentaint.dataflow.graph.PortId

/** Immutable demand snapshot. Tails, marks, exclusions and exits remain candidate payloads. */
class DemandStore private constructor(
    private val byMethod: Map<MethodKey, MethodDemandIndex>,
    private val controls: Map<MethodKey, List<PairedDemand>>,
    private val ap: ApManager,
    val hasSharedStaticCarry: Boolean,
    internal val completion: FrozenCompletion?,
    private val scoped: Map<OwnedScope, ScopedDemandIndex>,
    private val scopedCompletions: Map<OwnedScope, FrozenCompletion>,
) {
    private class MethodDemandIndex(val entries: FrozenDemandTrie<Pattern>, val rows: List<DemandPattern>,
                                   val byEntry: PathTrie<Int>, val byExit: PathTrie<Int>, val entryCount: Int)
    private class ScopedDemandIndex(
        val data: MethodDemandIndex,
        val rowPorts: List<PortId>,
        val controls: List<Pair<PortId, PairedDemand>>,
    )
    private data class Query(val method: MethodKey, val scope: BlockScope? = null, val exit: PortId? = null)
    private fun local(query: Query): MethodDemandIndex? = query.scope?.let {
        scoped[OwnedScope(query.method, it)]?.data
    } ?: if (query.scope == null) byMethod[query.method] else null

    private fun completion(query: Query): FrozenCompletion? =
        if (query.scope == null) completion else scopedCompletions[OwnedScope(query.method, query.scope)]?.selectExit(query.exit)

    /** C2 borrows the union of this entry's exits; C5 selects one actual exit. */
    fun scope(method: MethodKey, scope: BlockScope): ScopeDemandView = object : PreparedScopeDemandView, EntryPrecisionView {
        override fun precisionCursors(actual: Pattern, policy: RestrictedInitialPolicy): List<AnyDemandCursor> =
            local(Query(method, scope))?.entries?.precisionCursors(actual, ap.marks).orEmpty()
        override fun initials(actual: Facts, policy: RestrictedInitialPolicy): Set<AdmittedInitial> =
            initials(Query(method, scope), actual, policy)
        override fun intersect(exit: PortId, original: PremiseKey, raw: Facts,
                               policy: RestrictedInitialPolicy): List<Facts> =
            intersect(Query(method, scope, exit), original, raw, policy)
        override fun acceptsTarget(exit: PortId, original: PremiseKey, policy: RestrictedInitialPolicy): Boolean =
            intersect(Query(method, scope, exit), original, Reach.DEMAND, policy).isNotEmpty()
        override fun prepareDataPlan(exit: PortId, templates: List<Pattern>, policy: RestrictedInitialPolicy,
                                     onEntryCheck: () -> Unit): PreparedLocalDataPlan? =
            prepareLocalDataPlan(Query(method, scope, exit), templates, policy, onEntryCheck)
    }

    internal fun prepareDataPlan(method: MethodKey, templates: List<Pattern>,
                                 policy: RestrictedInitialPolicy, onEntryCheck: () -> Unit = {}): PreparedLocalDataPlan? =
        prepareLocalDataPlan(Query(method), templates, policy, onEntryCheck)

    /** Exact local DATA capability. Static/control/unsupported cases keep native C5. */
    private fun prepareLocalDataPlan(query: Query, templates: List<Pattern>,
                                     policy: RestrictedInitialPolicy, onEntryCheck: () -> Unit): PreparedLocalDataPlan? {
        ap.cancellation.checkpoint()
        fun fallback(reason: PreparedPlanFallback): PreparedLocalDataPlan? {
            statistics?.preparedFallback(reason)
            return null
        }
        if (policy.run < 3) return fallback(PreparedPlanFallback.RUN)
        if (hasStaticCompletion) return fallback(PreparedPlanFallback.STATIC_COMPLETION)
        if (hasSharedStaticCarry) return fallback(PreparedPlanFallback.SHARED_CARRY)
        if (templates.isEmpty()) return fallback(PreparedPlanFallback.EMPTY_TEMPLATES)
        if (templates.size > 2048) return fallback(PreparedPlanFallback.OVERSIZE_TEMPLATES)
        if (templates.any { it.fact.base == AccessPathBase.Zero }) return fallback(PreparedPlanFallback.ZERO_TEMPLATE)
        val local = local(query)
        val ops = ApOps(ap)
        val programs = PreparedOutputPrograms.Builder(ap, query.method, templates, policy, statistics)
        var occurrences = 0
        for (member in templates) {
            ap.cancellation.checkpoint()
            if (local != null) for (id in local.byEntry.lookupPrefixes(member.fact.base, member.fact.path.toIntArray())) {
                if (query.scope != null && query.exit != null &&
                    scoped.getValue(OwnedScope(query.method, query.scope)).rowPorts[id] != query.exit) continue
                if (occurrences + templates.size == 2048) return fallback(PreparedPlanFallback.OCCURRENCE_BUDGET)
                val pair = local.rows[id]
                onEntryCheck()
                programs.offer(EntryRestrictionTicket.prepare(ops, member, pair, policy))
                occurrences++
            }
        }
        return programs.build()
    }

    private val statistics = if (java.lang.Boolean.getBoolean("org.opentaint.bidi.optimizationStatistics"))
        DemandQueryStatistics() else null
    private val entryTrieCounts = statistics?.let { stats -> stats::trieQuery }
    val hasStaticCompletion: Boolean get() = completion != null || scopedCompletions.isNotEmpty()
    internal fun validateIncoming(run: Int) {
        require(run >= 2)
        check(run == 2 || !hasStaticCompletion && !hasSharedStaticCarry) {
            "Only run-2 can use the run-1 static completion"
        }
        for (method in byMethod.values + scoped.values.map { it.data }) for (d in method.rows) {
            ap.cancellation.checkpoint()
            if (d.entry.fact.mark !is MarkSlot.Star) continue
            check(d.entry.fact.tail == Tail.ANY || run == 2 && d.entry.fact.tail == Tail.STAR) {
                "A run-$run FLOW demand entry must be ANY (STAR is valid only in run-2): $d"
            }
            check(d.exit == null || d.exit.fact.mark is MarkSlot.Star &&
                d.exit.fact.tail in setOf(Tail.STAR, Tail.ANY)) { "Invalid paired FLOW exit: $d" }
        }
        for (rows in controls.values + scoped.values.map { it.controls.map { row -> row.second } }) for (row in rows) {
            ap.cancellation.checkpoint()
            val entry = (row.entry as? DemandEntry.Data)?.pattern ?: continue
            if (entry.fact.mark is MarkSlot.Star)
                check(entry.fact.tail == Tail.ANY || run == 2 && entry.fact.tail == Tail.STAR) {
                    "A run-$run FLOW demand entry must be ANY (STAR is valid only in run-2): $row"
                }
        }
    }
    fun staticCompletionStatistics(): String? = (completion?.statistics() ?: "localOnly=${!hasStaticCompletion}") +
        " scopedCompletions=${scopedCompletions.size}" +
        " entryRows=${byMethod.values.sumOf { it.entryCount.toLong() } + scoped.values.sumOf { it.data.entryCount.toLong() }}" +
        " pairRows=${byMethod.values.sumOf { it.rows.size.toLong() } + controls.values.sumOf { it.size.toLong() } +
            scoped.values.sumOf { it.data.rows.size.toLong() + it.controls.size.toLong() }}" +
        (statistics?.let { " $it" } ?: "")
    internal fun diagnosticC5Samples(): List<String> = statistics?.rowSamples().orEmpty()

    /** C2 uses an entry-only index and never materializes origin products. */
    fun admissionPolicy(run: Int, fieldLimit: Int, direction: Direction): RestrictedInitialPolicy =
        RestrictedInitialPolicy(run, fieldLimit, direction, ap.marks)

    fun initials(method: MethodKey, boundedActual: Facts,
                 policy: RestrictedInitialPolicy = RestrictedInitialPolicy(direction = Direction.FORWARD, catalog = ap.marks)): Set<AdmittedInitial> {
        return initials(Query(method), boundedActual, policy)
    }

    private fun initials(query: Query, boundedActual: Facts, policy: RestrictedInitialPolicy): Set<AdmittedInitial> {
        val method = query.method
        ap.cancellation.checkpoint()
        statistics?.add(0)
        if (!RuntimeDataDomain.base(boundedActual.base)) return emptySet()
        if (boundedActual is Reach) {
            var admitted = false
            visitControlPairs(query, policy) { pair ->
                admitted = pair.entry == DemandEntry.Zero || pair.entry == DemandEntry.Target
                !admitted
            }
            return if (admitted) setOf(existingZeroAdmission(ap.zero)) else emptySet()
        }
        val ops = ApOps(ap)
        val leaves = ap.canonicalPackets(boundedActual).flatMap { ops.leaves(it).toList() }
        val result = InitialDemandResults(ap, policy, boundedActual.layer, statistics)
        val local = local(query)
        for (leaf in leaves) {
            ap.cancellation.checkpoint()
            local?.entries?.visitCountedNativeOrder(leaf, DemandQueryKind.INITIAL_C2, ap.marks, entryTrieCounts) { result.offer(it, leaf) }
            staticCarry(leaf)?.let { result.offer(it.entry, leaf) }
        }
        val skipped = completion(query) ?: return result.initials // run-3 onward: local only
        val query = StaticEntryLookup(ap, method, skipped, leaves, result, statistics)
        query.directLocal()
        // This query-local structural bound uses scalar emit only. No possible key is interned.
        for (leaf in leaves) {
            ap.cancellation.checkpoint()
            local?.entries?.visitCountedNativeOrder(leaf, DemandQueryKind.INITIAL_C2, ap.marks, entryTrieCounts) {
                result.requireFamily(it, false, leaf)
            }
            skipped.visitPossibleTargets(method, leaf) { target, flow ->
                result.requireFamily(target, flow, leaf); true
            }
        }
        fun covered(): Boolean = result.fullyCovered
        if (covered()) { statistics?.add(3); return result.initials }
        query.search(visible = false, ::covered)
        if (covered()) { statistics?.add(3); return result.initials }
        if (!skipped.mayNeedInheritedEntries(method, leaves)) return result.initials
        query.search(visible = true, ::covered)
        return result.initials
    }

    /** C5 selects complete paired rows and preserves the whole original ND premise at the caller. */
    fun intersect(method: MethodKey, original: PremiseKey, raw: Facts,
                  policy: RestrictedInitialPolicy = RestrictedInitialPolicy(direction = Direction.FORWARD, catalog = ap.marks)): List<Facts> {
        return intersect(Query(method), original, raw, policy)
    }

    private fun intersect(query: Query, original: PremiseKey, raw: Facts,
                          policy: RestrictedInitialPolicy): List<Facts> {
        val method = query.method
        ap.cancellation.checkpoint()
        if (!RuntimeDataDomain.packet(original, raw)) return emptyList()
        val ops = ApOps(ap)
        val result = ExactDemandResults(ap)
        // Reach has one possible result. DATA must exhaust rows with different exit budgets.
        fun saturated(): Boolean = raw is Reach && result.hasResults
        val local = local(query)
        val outputLeaves = ops.leaves(raw).toList()
        // A control pair is tested as one row. Entry and exit permissions cannot mix.
        visitControlPairs(query, policy, includeDerived = original.isZero) { pair ->
            ap.cancellation.checkpoint()
            if (!entryAccepts(pair.entry, original, policy)) return@visitControlPairs true
            when (val exit = pair.exit) {
                DemandExit.Zero -> if (raw is Reach) result.add(raw)
                is DemandExit.Data -> if (raw !is Reach) {
                    // Data/Data rows use the AP index. A control entry admitted ZERO;
                    // use the existing AP restriction, including protection transport.
                    val dataPair = DemandPattern(ap.zero.toPattern(), exit.pattern)
                    offerDataPair(method, ops, ap.zero, raw, dataPair, policy, result, route = 2)
                }
            }
            !saturated()
        }
        fun offer(member: InitialAp, pair: DemandPattern, route: Int = 0) {
            statistics?.add(7)
            val exit = pair.exit ?: return
            statistics?.add(9)
            if (exit.fact.base == AccessPathBase.Zero) {
                // The static walker can expose a typed ZERO through its legacy AP view.
                if (raw is Reach) for (kept in ops.restrict(member, raw, pair, policy)) result.add(kept)
            } else offerDataPair(method, ops, member, raw, pair, policy, result, route)
        }
        val outputIds = HashSet<Int>()
        if (local != null) for (leaf in outputLeaves)
            local.byExit.visitAround(leaf.fact.base, leaf.fact.path.toIntArray()) { outputIds += it }
        original.forEachMember { member ->
            ap.cancellation.checkpoint()
            if (local != null) for (id in local.byEntry.lookupPrefixes(member.base,
                    member.path?.toIntArray() ?: EMPTY_PATH)) {
                if (id in outputIds && (query.scope == null || query.exit == null ||
                        scoped[OwnedScope(method, query.scope)]!!.rowPorts[id] == query.exit))
                    offer(member, local.rows[id])
            }
            staticCarry(member.toPattern())?.let { offer(member, it, route = 3) }
        }
        val skipped = completion(query) ?: return result.all() // later snapshots have no graph lookup
        // Primitive seed pairs use the same complete source/target row. They do not form a product.
        val primitive = skipped.local(method)
        original.forEachMember { member ->
            for (edge in primitive.pairs(member, outputLeaves))
                offer(member, DemandPattern(edge.to, edge.from), route = 1)
        }
        if (saturated()) { statistics?.add(10); return result.all() }
        val query = StaticPairLookup(ap, skipped, statistics) { entry, member -> policy.canStoreInitial(entry, member.toPattern()) }
        val offerVirtual: (InitialAp, DemandPattern) -> Unit = { member, pair -> offer(member, pair, route = 1) }
        query.walk(method, original, outputLeaves, visible = false, offerVirtual, ::saturated)
        if (saturated()) { statistics?.add(10); return result.all() }
        if (!skipped.mayNeedInheritedPairs(method)) return result.all()
        query.walk(method, original, outputLeaves, visible = true, offerVirtual, ::saturated)
        return result.all()
    }

    /** Exact C5 must precede the cut, and each complete row supplies its own exit depth. */
    private fun offerDataPair(method: MethodKey, ops: ApOps, member: InitialAp, raw: Facts, pair: DemandPattern,
                              policy: RestrictedInitialPolicy, result: ExactDemandResults, route: Int) {
        ap.cancellation.checkpoint()
        val exit = pair.exit ?: return
        val depth = exit.fact.path.count { it.isCounted() }
        val global = policy.fieldLimit
        check(global >= 1)
        // Clamp before adding: the default public policy uses Int.MAX_VALUE.
        val budget = if (depth >= global) global else depth + 1
        statistics?.dataRow(raw, exit, budget, route)
        val sampledRow = statistics?.sampleRow(method, member, raw, pair, budget, route)
        val selected = ops.restrict(member, raw, pair, policy)
        if (selected.isEmpty()) {
            statistics?.rejectedRow()
            statistics?.sampleResult(sampledRow, null, null)
        }
        for (kept in selected) {
            statistics?.selected(kept, budget)
            ops.limit(kept, budget, object : ApOut {
                override fun result(f: Facts) {
                    statistics?.limited(kept, f)
                    statistics?.sampleResult(sampledRow, kept, f)
                    result.add(f)
                }
                override fun markRequest(mark: TaintMark) = error("A field cut must not emit a mark request")
            })
        }
    }

    /** Immutable seed inspection for the finite explicit reference in tests. No closure is retained. */
    internal fun explicitRows(method: MethodKey): List<DemandPattern> {
        ap.cancellation.checkpoint()
        val ordinary = byMethod[method]?.rows.orEmpty()
        return ordinary + controls[method].orEmpty().mapNotNull { row ->
            val entry = when (val e = row.entry) {
                is DemandEntry.Data -> e.pattern
                DemandEntry.Zero -> ap.zero.toPattern()
                DemandEntry.Target -> return@mapNotNull null
            }
            val exit = when (val e = row.exit) {
                is DemandExit.Data -> e.pattern
                DemandExit.Zero -> ap.zero.toPattern()
            }
            DemandPattern(entry, exit)
        }
    }

    /** Terminal C5 needs one complete pair with a ZERO exit, explicit or run-2 static-composed. */
    fun acceptsTarget(method: MethodKey, original: PremiseKey,
                      policy: RestrictedInitialPolicy = RestrictedInitialPolicy(direction = Direction.FORWARD, catalog = ap.marks)): Boolean {
        // ZERO and Target match exactly the same exit slots. This read-only probe
        // reuses all paired C5 lookup paths; it never stores or propagates a ZERO edge.
        return intersect(method, original, Reach.DEMAND, policy).isNotEmpty()
    }

    /** A run-1 static write used the typed raw-write shortcut, not a
     * completed normal exit or physical loop leave. Its reverse W row therefore has STATIC_SHORTCUT as its
     * entry. An actually reached run-2 static initial can finish at a source
     * through that same shortcut, while its live DATA scope stays physical.
     * Only complete W/B paths with a genuine ZERO origin can admit Target;
     * shared carry, unrelated normal demand and terminal-reader rows cannot. */
    internal fun acceptsStaticShortcutTarget(method: MethodKey, block: BlockId, exit: PortId,
                                             original: PremiseKey, policy: RestrictedInitialPolicy): Boolean {
        if (policy.run != 2 || policy.direction != Direction.BACKWARD) return false
        val member = original as? InitialAp ?: return false
        if (member.base != STATIC || member.mark !is MarkSlot.Concrete) return false
        val owner = OwnedScope(method, BlockScope(block, PortId.STATIC_SHORTCUT))
        val skipped = scopedCompletions[owner]?.selectExit(exit) ?: return false
        val ops = ApOps(ap)
        val outputs = listOf(ap.zero.toPattern())
        var accepted = false
        fun offer(pair: DemandPattern) {
            ap.cancellation.checkpoint()
            if (pair.entry.fact.base != STATIC || pair.exit?.fact?.base != AccessPathBase.Zero) return
            if (ops.restrict(member, Reach.DEMAND, pair, policy).isNotEmpty()) accepted = true
        }
        for (row in skipped.local(method).pairs(member, outputs)) {
            ap.cancellation.checkpoint()
            offer(DemandPattern(row.to, row.from))
            if (accepted) return true
        }
        val query = StaticPairLookup(ap, skipped, statistics) { entry, initial ->
            policy.canStoreInitial(entry, initial.toPattern())
        }
        query.walk(method, member, outputs, visible = false,
            offer = { _, pair -> offer(pair) }, covered = { accepted })
        if (accepted) return true
        if (!skipped.mayNeedInheritedPairs(method)) return false
        query.walk(method, member, outputs, visible = true,
            offer = { _, pair -> offer(pair) }, covered = { accepted })
        return accepted
    }

    /** Virtual terminal pairs share the run-1 static graph; no closure rows are retained. */
    private fun visitControlPairs(query: Query, policy: RestrictedInitialPolicy, includeDerived: Boolean = true,
                                  visit: (PairedDemand) -> Boolean): Boolean {
        val method = query.method
        if (query.scope == null) {
            for (pair in controls[method].orEmpty()) {
                ap.cancellation.checkpoint()
                if (!visit(pair)) return false
            }
        } else for ((exit, pair) in scoped[OwnedScope(method, query.scope)]?.controls.orEmpty()) {
            ap.cancellation.checkpoint()
            if ((query.exit == null || query.exit == exit) && !visit(pair)) return false
        }
        val skipped = completion(query)?.takeIf { includeDerived } ?: return true
        val query = StaticPairLookup(ap, skipped, statistics) { entry, member ->
            policy.canStoreInitial(entry, member.toPattern())
        }
        fun walk(visible: Boolean): Boolean = query.walkTargetOrigins(method, visible) { origin ->
            val exit = if (origin.fact.base == AccessPathBase.Zero) DemandExit.Zero else DemandExit.Data(origin)
            visit(PairedDemand(DemandEntry.Target, exit))
        }
        if (!walk(false)) return false
        return !skipped.mayNeedInheritedPairs(method) || walk(true)
    }

    private fun entryAccepts(entry: DemandEntry, original: PremiseKey, policy: RestrictedInitialPolicy): Boolean {
        original.forEachMember { if (entryAccepts(entry, it, policy)) return true }
        return false
    }

    private fun entryAccepts(entry: DemandEntry, member: InitialAp, policy: RestrictedInitialPolicy): Boolean =
        when (entry) {
            DemandEntry.Zero, DemandEntry.Target -> member.isZero
            is DemandEntry.Data -> !member.isZero && policy.canStoreInitial(entry.pattern, member.toPattern())
        }

    /** Same actual slot and mark only. This family does not connect different fields. */
    private fun staticCarry(actual: Pattern): DemandPattern? {
        ap.cancellation.checkpoint()
        if (!hasSharedStaticCarry || actual.fact.base != STATIC) return null
        val pattern = guidancePattern(actual)
        return DemandPattern(pattern, pattern)
    }

    class Builder(private val m: ApManager) {
        private val seen = LinkedHashSet<Pair<MethodKey, DemandPattern>>()
        private val controlRows = LinkedHashSet<Pair<MethodKey, PairedDemand>>()
        private val scopedRows = LinkedHashSet<Pair<ScopedSummaryKey, DemandPattern>>()
        private val scopedControls = LinkedHashSet<Pair<ScopedSummaryKey, PairedDemand>>()
        private var staticCarry = false
        private var completion: FrozenCompletion? = null
        private val scopedCompletions = LinkedHashMap<OwnedScope, FrozenCompletion>()

        /** Only the completed run-1 boundary installs these virtual guidance families. */
        fun withCompletion(view: FrozenCompletion) { completion = view }
        fun withCompletion(method: MethodKey, scope: BlockScope, view: FrozenCompletion) {
            scopedCompletions[OwnedScope(method, scope)] = view
        }
        fun withSharedStaticCarry() { staticCarry = true }

        /** Count only a new exact normalized pattern. Validate the typed hand-off boundary. */
        fun add(method: MethodKey, d: DemandPattern): Boolean = add(method, null, d)

        fun add(method: MethodKey, scope: BlockScope, exit: PortId, d: DemandPattern): Boolean =
            add(method, ScopedSummaryKey(method, scope, exit), d)

        private fun add(method: MethodKey, key: ScopedSummaryKey?, d: DemandPattern): Boolean {
            m.cancellation.checkpoint()
            if (!RuntimeDataDomain.base(d.entry.fact.base) ||
                d.exit?.let { !RuntimeDataDomain.base(it.fact.base) } == true) return false
            if (d.entry.fact.base == AccessPathBase.Zero || d.exit?.fact?.base == AccessPathBase.Zero) {
                val exit = d.exit ?: return false // No unpaired implicit ZERO permission.
                return add(method, key, PairedDemand(
                    if (d.entry.fact.base == AccessPathBase.Zero) DemandEntry.Zero else DemandEntry.Data(d.entry),
                    if (exit.fact.base == AccessPathBase.Zero) DemandExit.Zero else DemandExit.Data(exit),
                ))
            }
            val entry = normalizeDemandFieldExclusion(d.entry)
            val exit = d.exit?.let(::normalizeDemandFieldExclusion)
            check(entry.fact.base !is AccessPathBase.CleanerTemporary && exit?.fact?.base !is AccessPathBase.CleanerTemporary) {
                "A field-action temporary cannot enter a demand hand-off"
            }
            check(entry.fact.tail != Tail.ANY_TAINT && exit?.fact?.tail != Tail.ANY_TAINT) {
                "W8 (d): a demand pattern cannot have a must tail"
            }
            check(normalizedMarks(entry) && (exit == null || normalizedMarks(exit))) {
                "Normalize mark exclusions at hand-off"
            }
            check(entry.fact.mark !is MarkSlot.Star || entry.fact.tail == Tail.ANY || entry.fact.tail == Tail.STAR) {
                "A typed abstract demand entry has ANY or STAR tail"
            }
            check(exit?.fact?.tail != Tail.EXACT || entry.fact.mark is MarkSlot.Concrete) {
                "A canonical exact exit demand has a concrete entry mark"
            }
            check(validFieldExclusion(entry) && (exit == null || validFieldExclusion(exit))) {
                "Only STAR demand endpoints can exclude fields"
            }
            val owned = ownDemand(m, DemandPattern(entry, exit))
            return if (key == null) seen.add(method to owned) else scopedRows.add(key to owned)
        }

        /** Data pairs keep the current AP index; control rows use only this local list. */
        fun add(method: MethodKey, row: PairedDemand): Boolean = add(method, null, row)

        fun add(method: MethodKey, scope: BlockScope, exit: PortId, row: PairedDemand): Boolean =
            add(method, ScopedSummaryKey(method, scope, exit), row)

        private fun add(method: MethodKey, key: ScopedSummaryKey?, row: PairedDemand): Boolean {
            m.cancellation.checkpoint()
            if (row.entry is DemandEntry.Data && !RuntimeDataDomain.base(row.entry.pattern.fact.base) ||
                row.exit is DemandExit.Data && !RuntimeDataDomain.base(row.exit.pattern.fact.base)) return false
            if (row.entry is DemandEntry.Data && row.exit is DemandExit.Data)
                return add(method, key, DemandPattern(row.entry.pattern, row.exit.pattern))
            fun ownData(p: Pattern): Pattern {
                val normalized = normalizeDemandFieldExclusion(p)
                check(normalized.fact.base != AccessPathBase.Zero) { "Use a typed ZERO control endpoint" }
                check(normalized.fact.base !is AccessPathBase.CleanerTemporary)
                check(normalized.fact.tail != Tail.ANY_TAINT && normalizedMarks(normalized))
                check(validFieldExclusion(normalized))
                return ownPattern(m, normalized)
            }
            val entry = when (val e = row.entry) {
                is DemandEntry.Data -> DemandEntry.Data(ownData(e.pattern).also {
                    check(it.fact.mark !is MarkSlot.Star || it.fact.tail in setOf(Tail.ANY, Tail.STAR))
                })
                else -> e
            }
            val exit = when (val e = row.exit) {
                is DemandExit.Data -> DemandExit.Data(ownData(e.pattern))
                DemandExit.Zero -> DemandExit.Zero
            }
            val owned = PairedDemand(entry, exit)
            return if (key == null) controlRows.add(method to owned) else scopedControls.add(key to owned)
        }

        /** The new index has no mutable alias in this builder or in earlier snapshots. */
        fun build(): DemandStore {
            m.cancellation.checkpoint()
            val grouped = LinkedHashMap<MethodKey, MutableList<DemandPattern>>()
            for ((method, demand) in seen) {
                m.cancellation.checkpoint()
                grouped.getOrPut(method) { ArrayList() } += demand
            }
            val controls = LinkedHashMap<MethodKey, MutableList<PairedDemand>>()
            for ((method, row) in controlRows) {
                controls.getOrPut(method) { ArrayList() } += row
                grouped.getOrPut(method) { ArrayList() }
            }
            val byMethod = LinkedHashMap<MethodKey, MethodDemandIndex>()
            for ((method, rows) in grouped) {
                byMethod[method] = index(rows, controls[method].orEmpty())
            }
            val scopeData = LinkedHashMap<OwnedScope, MutableList<Pair<PortId, DemandPattern>>>()
            val scopeControls = LinkedHashMap<OwnedScope, MutableList<Pair<PortId, PairedDemand>>>()
            for ((key, row) in scopedRows) {
                m.cancellation.checkpoint()
                scopeData.getOrPut(OwnedScope(key.method, key.scope)) { ArrayList() } += key.exit to row
            }
            for ((key, row) in scopedControls) {
                m.cancellation.checkpoint()
                val owner = OwnedScope(key.method, key.scope)
                scopeControls.getOrPut(owner) { ArrayList() } += key.exit to row
                scopeData.getOrPut(owner) { ArrayList() }
            }
            val scopes = LinkedHashMap<OwnedScope, ScopedDemandIndex>()
            for ((owner, rows) in scopeData) {
                m.cancellation.checkpoint()
                val control = scopeControls[owner].orEmpty()
                scopes[owner] = ScopedDemandIndex(index(rows.map { it.second }, control.map { it.second }),
                    Collections.unmodifiableList(rows.map { it.first }), Collections.unmodifiableList(control.toList()))
            }
            return DemandStore(Collections.unmodifiableMap(byMethod),
                Collections.unmodifiableMap(controls.mapValues { Collections.unmodifiableList(it.value) }),
                m, staticCarry, completion, Collections.unmodifiableMap(scopes),
                Collections.unmodifiableMap(LinkedHashMap(scopedCompletions)))
        }

        private fun index(rows: List<DemandPattern>, controls: List<PairedDemand>): MethodDemandIndex {
            val entries = FrozenDemandTrie.Builder<Pattern>(m.cancellation)
            val byEntry = PathTrie<Int>(m.cancellation)
            val byExit = PathTrie<Int>(m.cancellation)
            var entryCount = 0
            for ((id, demand) in rows.withIndex()) {
                m.cancellation.checkpoint()
                if (entries.add(demand.entry, demand.entry)) entryCount++
                byEntry.add(demand.entry.fact.base, demand.entry.fact.path.toIntArray(), id)
                demand.exit?.let { byExit.add(it.fact.base, it.fact.path.toIntArray(), id) }
            }
            for (row in controls) {
                m.cancellation.checkpoint()
                val entry = (row.entry as? DemandEntry.Data)?.pattern ?: continue
                if (entries.add(entry, entry)) entryCount++
            }
            return MethodDemandIndex(entries.build(), Collections.unmodifiableList(rows.toList()), byEntry, byExit, entryCount)
        }
    }
}

private fun normalizedMarks(p: Pattern): Boolean =
    (p.fact.mark as? MarkSlot.Star)?.excluded?.isEmpty != false

private fun validFieldExclusion(p: Pattern): Boolean =
    p.exclusion == ExclusionSet.Empty || p.fact.tail == Tail.STAR

private fun ownDemand(m: ApManager, d: DemandPattern): DemandPattern =
    DemandPattern(ownPattern(m, d.entry), d.exit?.let { ownPattern(m, it) })

private fun ownPattern(m: ApManager, p: Pattern): Pattern {
    m.cancellation.checkpoint()
    val path = ArrayList<Int>(p.fact.path.size)
    for (accessor in p.fact.path) {
        m.cancellation.checkpoint()
        path += accessor
    }
    return p.copy(fact = p.fact.copy(path = Collections.unmodifiableList(path)))
}


/** Read-only view bound to one method-owned block entry. C5 additionally names
 * the actual output port, so permissions from separate exits cannot mix. */
interface ScopeDemandView {
    fun initials(actual: Facts, policy: RestrictedInitialPolicy): Set<AdmittedInitial>
    fun intersect(exit: PortId, original: PremiseKey, raw: Facts,
                  policy: RestrictedInitialPolicy): List<Facts>
    fun acceptsTarget(exit: PortId, original: PremiseKey, policy: RestrictedInitialPolicy): Boolean
}

package org.opentaint.dataflow.bidi.store

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import java.util.ArrayDeque
import java.util.IdentityHashMap

/** Exact diagonal relations for the current runtime atoms.
 * A row has one immutable typed output geometry and two exact mark masks.
 * No original scalar tree or historical row is retained behind the masks. */
class DiagonalRelations(private val m: ApManager, private val interners: StoreInterners = m.newInterners()) {
    private data class Scope(val initial: InitialAp, val base: AccessPathBase, val layer: Layer)
    private data class Header(val scope: Scope, val tail: Tail, val exclusion: ExclusionSet) {
        constructor(initial: InitialAp, base: AccessPathBase, layer: Layer, tail: Tail, exclusion: ExclusionSet) :
            this(Scope(initial, base, layer), tail, exclusion)
        val initial get() = scope.initial
        val base get() = scope.base
        val layer get() = scope.layer
    }
    private class Masks(var marks: MarkSet, var protected: MarkSet)
    /** The common case reuses the geometry map object. Siblings allocate no
     * second index, per-scope map or per-header entry; they stay in this scope. */
    private class Rows(val tail: Tail, val exclusion: ExclusionSet) : LinkedHashMap<FlowNode, Masks>() {
        var next: Rows? = null
    }
    private val headers = LinkedHashMap<Scope, Rows>()

    private fun findRows(header: Header): Rows? {
        var current = headers[header.scope]
        while (current != null) {
            m.cancellation.checkpoint()
            if (current.tail == header.tail && current.exclusion == header.exclusion) return current
            current = current.next
        }
        return null
    }

    private fun rowsFor(header: Header): Rows {
        var current = headers[header.scope]
            ?: return Rows(header.tail, header.exclusion).also { headers[header.scope] = it }
        while (true) {
            m.cancellation.checkpoint()
            val rows = current
            if (rows.tail == header.tail && rows.exclusion == header.exclusion) return rows
            val next = rows.next
            if (next == null) return Rows(header.tail, header.exclusion).also { rows.next = it }
            current = next
        }
    }

    private fun removeHeader(header: Header) {
        var previous: Rows? = null
        var current = headers[header.scope]
        while (current != null) {
            if (current.tail == header.tail && current.exclusion == header.exclusion) {
                if (previous == null) {
                    val next = current.next
                    if (next == null) headers.remove(header.scope) else headers[header.scope] = next
                } else previous.next = current.next
                current.next = null
                return
            }
            previous = current
            current = current.next
        }
    }

    private fun scopedRows(scope: Scope): Sequence<Pair<Header, Rows>> = sequence {
        var current = headers[scope]
        while (current != null) {
            m.cancellation.checkpoint()
            val rows = current
            yield(Header(scope, rows.tail, rows.exclusion) to rows)
            current = rows.next
        }
    }

    private fun allRows(): Sequence<Pair<Header, Rows>> = sequence {
        for (scope in headers.keys) yieldAll(scopedRows(scope))
    }

    val isEmpty: Boolean get() = headers.isEmpty()
    val rowCount: Int get() = allRows().sumOf { it.second.size }
    val markMembershipCount: Int get() = allRows().sumOf { (_, rows) -> rows.values.sumOf { it.marks.size } }

    /** Scan exact masks without constructing their scalar decoded trees. */
    fun census(): RelationCensus = census(RelationCensusCounter(m.cancellation))

    internal fun census(counter: RelationCensusCounter,
                        include: (PremiseKey, Layer) -> Boolean = { _, _ -> true }): RelationCensus {
        m.cancellation.checkpoint()
        var result = RelationCensus.ZERO
        for ((header, rows) in allRows()) {
            // Diagonal scopes are nonzero singleton premises. Selection does not decode a mark.
            if (!include(header.initial, header.layer)) continue
            for ((shape, masks) in rows) {
                m.cancellation.checkpoint()
                val outputs = counter.flowAnnotations(shape)
                result += RelationCensus(
                    concreteOutputMemberships = Math.multiplyExact(outputs, masks.marks.size.toLong()),
                    protectedOutputMemberships = Math.multiplyExact(outputs, masks.protected.size.toLong()),
                    diagonalGeometryRows = 1,
                    diagonalMarkRows = masks.marks.size.toLong(),
                )
            }
        }
        return result
    }

    /** Same-geometry mask admission. Null selects the scalar fallback before
     * mutation; an empty list means the whole offered mask was already stored.
     * Different geometry for an overlapping mark needs the existing spatial
     * subtraction/protection adapter and is deliberately not guessed here. */
    fun addDiagonal(offered: DiagonalDelta): List<DiagonalDelta>? {
        m.cancellation.checkpoint()
        // Every legal ANY packet is DEMAND and each supplied head is a guide.
        // Uniformly protected packets also retain their literal coordinates.
        if (offered.tail == Tail.ANY && offered.layer != Layer.DEMAND) return null
        val delta = offered
        if (!RuntimeDataDomain.initial(delta.initialShape) || !RuntimeDataDomain.base(delta.base)) return emptyList()
        require(delta.initialShape.manager === m) { "A diagonal packet must use this AP manager" }
        val header = Header(delta.initialShape, delta.base, delta.layer, delta.tail, delta.exclusion)
        // A different tail/E header can already cover some offered atoms.
        // Keep packet admission atomic and use the exact scalar adapter below.
        if (hasOtherHeader(header, delta.marks)) return null
        val previous = findRows(header)
        if (previous != null) for ((shape, masks) in previous) {
            m.cancellation.checkpoint()
            if (!(masks.marks intersect delta.marks).isEmpty && shape != delta.geometry) return null
        }
        val old = previous?.get(delta.geometry)
        val fresh = m.intern(delta.marks - (old?.marks ?: MarkSet.EMPTY))
        val flagged = if (delta.protected)
            m.intern(delta.marks - (old?.protected ?: MarkSet.EMPTY)) else MarkSet.EMPTY
        if (fresh.isEmpty && flagged.isEmpty) return emptyList()
        val rows = previous ?: rowsFor(header)
        admit(rows, delta.geometry, delta.marks, if (delta.protected) delta.marks else MarkSet.EMPTY)
        val output = ArrayList<DiagonalDelta>(2)
        if (!delta.protected && !fresh.isEmpty) output += delta.copy(marks = fresh, protected = false)
        if (!flagged.isEmpty) output += delta.copy(marks = flagged, protected = true)
        return output
    }

    fun supports(premise: PremiseKey, facts: Facts): Boolean {
        m.cancellation.checkpoint()
        if (!RuntimeDataDomain.packet(premise, facts)) return false
        val f = facts as? TaintTree ?: return false
        if ((f.anyTail != Tail.STAR && f.anyTail != Tail.ANY) ||
            flowInitialForCoverage(m, premise) == null) return false
        val mark = ((premise as InitialAp).mark as MarkSlot.Concrete).mark
        val all = m.taintAlg.foldAll(f.root, m.cancellation)
        if (!all.exact.isEmpty || all.any != m.markSetOf(mark)) return false
        val flags = f.nonSubsumable?.let { m.taintAlg.foldAll(it, m.cancellation) }
        return flags == null || (flags.exact.isEmpty && flags.any.isSubsetOf(all.any))
    }

    /** Admit geometry/mask memberships before constructing the one scalar
     * delta needed by the current interpreter interface. */
    fun add(premise: PremiseKey, facts: Facts): Facts? = addAll(premise,facts).also {
        check(it.size <= 1) { "Canonical diagonal admission has multiple headers; use addAll" }
    }.singleOrNull()

    fun addAll(premise: PremiseKey, facts: Facts): List<Facts> {
        if (!RuntimeDataDomain.packet(premise,facts)) return emptyList()
        require(supports(premise,facts)) { "Only admitted diagonal STAR or ANY relations use this store" }
        val f = facts as TaintTree
        val initial = premise as InitialAp
        val mark = (initial.mark as MarkSlot.Concrete).mark
        val scope = Scope(checkNotNull(flowInitialForCoverage(m,premise)), f.base, f.layer)
        val header = Header(scope, f.anyTail, f.exclusion)
        val scalar = f.anyTail == Tail.ANY || f.nonSubsumable != null ||
            hasOtherHeader(header, m.markSetOf(mark)) || scopedRows(scope).any { (_, rows) ->
                rows.values.any { mark in it.protected }
            }
        if (!scalar) return addOne(premise, f)?.let(::listOf) ?: emptyList()
        val before = currentAtom(scope,mark)
        val temporary = TaintGroup(m,interners.taint)
        before.values.forEach(temporary::restoreCurrent)
        val changes = temporary.addAll(m.canonicalTaintPacket(f))
        val after = LinkedHashMap<Header,TaintTree>()
        for (value in temporary.all()) after[Header(scope.initial,value.base,value.layer,value.anyTail,value.exclusion)] = value
        replaceAtom(scope,mark,after)
        return changes
    }

    private fun addOne(premise: PremiseKey, facts: Facts): Facts? {
        if (!RuntimeDataDomain.packet(premise, facts)) return null
        require(supports(premise, facts)) { "Only admitted diagonal STAR or ANY relations use this store" }
        val f = facts as TaintTree
        val initial = premise as InitialAp
        val mark = (initial.mark as MarkSlot.Concrete).mark
        val one = m.markSetOf(mark)
        val header = Header(checkNotNull(flowInitialForCoverage(m, premise)), f.base, f.layer, f.anyTail, f.exclusion)
        val rows = rowsFor(header)
        val offered = geometry(f.root)
        var fresh: FlowNode? = offered

        // Capture only current rows for this operation. Mutations below replace
        // their mask membership; this list is not retained by the owner.
        for ((shape, masks) in rows.entries.toList()) {
            m.cancellation.checkpoint()
            if (mark !in masks.marks) continue
            fresh = fresh?.let { subtract(it, shape, header.tail) }
        }
        val delta = fresh ?: return null
        admit(rows, delta, one, MarkSet.EMPTY)
        return decode(header, delta, mark, null)
    }

    private fun hasOtherHeader(offered: Header, marks: MarkSet): Boolean {
        var current = headers[offered.scope]
        while (current != null) {
            m.cancellation.checkpoint()
            if (current.tail != offered.tail || current.exclusion != offered.exclusion) {
                for (masks in current.values) {
                    m.cancellation.checkpoint()
                    if (!(masks.marks intersect marks).isEmpty) return true
                }
            }
            current = current.next
        }
        return false
    }

    private fun currentAtom(scope: Scope, mark: TaintMark): LinkedHashMap<Header,TaintTree> {
        val before = LinkedHashMap<Header, TaintTree>()
        for ((header, rows) in scopedRows(scope)) {
            m.cancellation.checkpoint()
            var root: FlowNode? = null
            var flags: FlowNode? = null
            for ((shape, masks) in rows) {
                m.cancellation.checkpoint()
                if (mark !in masks.marks) continue
                root = union(root, shape)
                if (mark in masks.protected) flags = union(flags, shape)
            }
            if (root != null) before[header] = decode(header, root, mark, flags)
        }
        return before
    }

    private fun replaceAtom(scope: Scope, mark: TaintMark, after: Map<Header,TaintTree>) {
        // Prepare the replacement off-store. Cancellation must not leave an
        // empty header, a stale sibling, or a half-rewritten shared T/U mask.
        val one = m.markSetOf(mark)
        val replacement = LinkedHashMap<Header, Rows>()
        for ((header, rows) in scopedRows(scope)) {
            m.cancellation.checkpoint()
            val kept = Rows(header.tail, header.exclusion)
            for ((shape, masks) in rows) {
                m.cancellation.checkpoint()
                // Masks are mutable. Keep immutable sets, but do not let
                // local re-encoding change a still-published shared mask.
                if (mark !in masks.marks) kept[shape] = Masks(masks.marks, masks.protected) else {
                    val rest = m.intern(masks.marks - one)
                    if (!rest.isEmpty) kept[shape] = Masks(rest, m.intern(masks.protected - one))
                }
            }
            if (kept.isNotEmpty()) replacement[header] = kept
        }
        for ((header, value) in after) {
            m.cancellation.checkpoint()
            val root = geometry(value.root)
            val flags = value.nonSubsumable?.let(::geometry)
            val plain = if (flags == null) root else subtractExact(root, flags)
            val rows = replacement.getOrPut(header) { Rows(header.tail, header.exclusion) }
            if (plain != null) admit(rows, plain, one, MarkSet.EMPTY)
            if (flags != null) admit(rows, flags, one, one)
        }
        var head: Rows? = null
        var previous: Rows? = null
        for (rows in replacement.values) {
            m.cancellation.checkpoint()
            if (previous == null) head = rows else previous.next = rows
            previous = rows
        }
        m.cancellation.checkpoint()
        if (head == null) headers.remove(scope) else headers[scope] = head
    }

    fun all(): Sequence<Pair<PremiseKey, Facts>> = sequence {
        m.cancellation.checkpoint()
        for ((header, rows) in allRows()) for ((shape, masks) in rows) for (id in masks.marks.ids) {
            m.cancellation.checkpoint()
            val mark = TaintMark(id)
            yield(markedInitial(header.initial, mark) to decode(header, shape, mark,
                if (mark in masks.protected) shape else null))
        }
    }

    fun borrow(premise: PremiseKey): Sequence<Facts> = sequence {
        m.cancellation.checkpoint()
        val initial = premise as? InitialAp ?: return@sequence
        val mark = (initial.mark as? MarkSlot.Concrete)?.mark ?: return@sequence
        val flow = flowInitialForCoverage(m, initial) ?: return@sequence
        for (scope in headers.keys) {
            m.cancellation.checkpoint()
            if (scope.initial !== flow) continue
            for ((header, rows) in scopedRows(scope)) {
                for ((shape, masks) in rows) {
                    m.cancellation.checkpoint()
                    if (mark in masks.marks) yield(decode(header, shape, mark,
                        if (mark in masks.protected) shape else null))
                }
            }
        }
    }

    /** Remove plain diagonal outputs covered by one complete typed FLOW row. */
    fun compact(flowInitial: InitialAp, flowFacts: FlowTree) {
        m.cancellation.checkpoint()
        if (!flowInitial.isFlow || (flowInitial.tail != Tail.STAR && flowInitial.tail != Tail.ANY) ||
            (flowFacts.tail != Tail.STAR && flowFacts.tail != Tail.ANY)) return
        for (layer in Layer.entries) {
            m.cancellation.checkpoint()
            if (flowFacts.layer == Layer.DEMAND && layer == Layer.NORMAL) continue
            val scope = Scope(flowInitial, flowFacts.base, layer)
            for ((header, rows) in scopedRows(scope).toList()) {
                if (header.tail != flowFacts.tail ||
                    (header.tail == Tail.STAR && !flowFacts.exclusion.isSubsetOf(header.exclusion))) continue
                for ((shape, masks) in rows.entries.toList()) {
                    m.cancellation.checkpoint()
                    val selected = m.intern((masks.marks - masks.protected) - flowFacts.markExclusion)
                    if (selected.isEmpty) continue
                    val rest = subtract(shape, flowFacts.root, header.tail)
                    if (rest === shape || rest == shape) continue
                    removeMark(rows, shape, masks, selected)
                    if (rest != null) admit(rows, rest, selected, MarkSet.EMPTY)
                }
                if (rows.isEmpty()) removeHeader(header)
            }
        }
    }

    private fun markedInitial(flow: InitialAp, mark: TaintMark): InitialAp =
        m.initial(flow.base, flow.path, flow.tail, flow.exclusion, MarkSlot.Concrete(mark))

    private fun removeMark(rows: MutableMap<FlowNode, Masks>, shape: FlowNode, masks: Masks, marks: MarkSet) {
        masks.marks = m.intern(masks.marks - marks)
        masks.protected = m.intern(masks.protected - marks)
        if (masks.marks.isEmpty) rows.remove(shape)
    }

    private fun admit(rows: MutableMap<FlowNode, Masks>, geometry: FlowNode, marks: MarkSet, protected: MarkSet) {
        val shape = interners.flow.internIfRequired(geometry)
        val masks = rows[shape]
        if (masks == null) rows[shape] = Masks(m.intern(marks), m.intern(protected))
        else {
            masks.marks = m.intern(masks.marks + marks)
            masks.protected = m.intern(masks.protected + protected)
        }
    }

    private fun union(a: FlowNode?, b: FlowNode?): FlowNode? = when {
        a == null -> b
        b == null -> a
        else -> FlowAlgebra.mergeAdd(a, b, m.cancellation)
    }

    private fun subtract(a: FlowNode, b: FlowNode, tail: Tail): FlowNode? =
        if (tail == Tail.STAR) subtractExact(a, b) else subtractCovered(a, b)

    private fun subtractCovered(a: FlowNode, b: FlowNode): FlowNode? = FlowAlgebra.subtract(a, b, FlowLeaf.NONE,
        at = { it }, below = { it }, cancellation = m.cancellation)

    private fun subtractExact(a: FlowNode, b: FlowNode): FlowNode? = FlowAlgebra.subtract(a, b, FlowLeaf.NONE,
        at = { it }, below = { FlowLeaf.NONE }, cancellation = m.cancellation)

    private class Frame<N>(val node: N, var next: Int = 0)

    /** Convert shape once; marks do not enter the geometry key. */
    private fun geometry(root: TaintNode): FlowNode {
        val memo = IdentityHashMap<TaintNode, FlowNode>()
        val stack = ArrayDeque<Frame<TaintNode>>()
        stack.addLast(Frame(root))
        while (stack.isNotEmpty()) {
            m.cancellation.checkpoint()
            val frame = stack.peekLast()
            val kids = frame.node.childData
            if (kids != null && frame.next < kids.size) {
                val child = kids[frame.next++]
                if (!memo.containsKey(child)) stack.addLast(Frame(child))
                continue
            }
            memo[frame.node] = FlowAlgebra.node(if (frame.node.leaf.any.isEmpty) FlowLeaf.NONE else FlowLeaf.LEAF,
                frame.node.accessorData, kids?.map { memo.getValue(it) }?.toTypedArray())
            stack.removeLast()
        }
        return memo.getValue(root)
    }

    private fun scalar(root: FlowNode, mark: TaintMark): TaintNode {
        val memo = IdentityHashMap<FlowNode, TaintNode>()
        val stack = ArrayDeque<Frame<FlowNode>>()
        val leaf = m.taintLeaves(MarkSet.EMPTY, m.markSetOf(mark))
        stack.addLast(Frame(root))
        while (stack.isNotEmpty()) {
            m.cancellation.checkpoint()
            val frame = stack.peekLast()
            val kids = frame.node.childData
            if (kids != null && frame.next < kids.size) {
                val child = kids[frame.next++]
                if (!memo.containsKey(child)) stack.addLast(Frame(child))
                continue
            }
            memo[frame.node] = m.taintAlg.node(if (frame.node.leaf.isEmpty) TaintLeaves.EMPTY else leaf,
                frame.node.accessorData, kids?.map { memo.getValue(it) }?.toTypedArray())
            stack.removeLast()
        }
        return memo.getValue(root)
    }

    private fun decode(header: Header, shape: FlowNode, mark: TaintMark, protected: FlowNode?): TaintTree =
        m.taintTree(header.base, header.layer, scalar(shape, mark), header.exclusion, anyTail = header.tail,
            nonSubsumable = protected?.let { scalar(it, mark) })

}

package org.opentaint.dataflow.bidi.store

import org.opentaint.dataflow.bidi.ap.*
import java.util.IdentityHashMap

/** One summary endpoint owns this normalized relation. No old marked payloads are retained.
 * Each endpoint keeps one authoritative relation with its existing admission law. */
internal class FlowBackedSummaries(private val m: ApManager,
                                   private val replaceCovered: Boolean = true,
                                   private val interners: StoreInterners = m.newInterners(),
                                   private val normalStars: NormalStarRelationIndex? = null,
                                   private val emptied: (PremiseKey) -> Unit = {}) {
    private val groups = IdentityHashMap<PremiseKey, ConclusionGroup>()
    private val concreteByShape = IdentityHashMap<InitialAp, MutableSet<PremiseKey>>()
    private val diagonal = DiagonalRelations(m, interners)
    private val concreteShapes = PathTrie<InitialAp>(m.cancellation)

    /** A method-point neutral continuation admits its mask before any scalar
     * materialization. Summary boundaries keep their existing producer hooks. */
    fun addDiagonal(offered: DiagonalDelta): List<DiagonalDelta>? =
        if (!RuntimeDataDomain.initial(offered.initialShape) || !RuntimeDataDomain.base(offered.base)) emptyList()
        else if (replaceCovered) null else diagonal.addDiagonal(offered)

    fun census(include: (PremiseKey, Layer) -> Boolean = { _, _ -> true }): RelationCensus {
        m.cancellation.checkpoint()
        val counter = RelationCensusCounter(m.cancellation)
        var result = diagonal.census(counter, include)
        for ((premise, group) in groups) for (facts in group.all()) {
            m.cancellation.checkpoint()
            if (include(premise, facts.layer)) result += counter.scalar(facts)
        }
        normalStars?.all()?.forEach { (premise, facts) ->
            if (include(premise, facts.layer)) result += counter.scalar(facts)
        }
        return result
    }

    fun add(premise: PremiseKey, offered: Facts): Facts? = addAll(premise, offered).also {
        check(it.size <= 1) { "Use addAll for a split canonical header" }
    }.singleOrNull()

    fun addAll(premise: PremiseKey, offered: Facts): List<Facts> {
        m.cancellation.checkpoint()
        if (!RuntimeDataDomain.packet(premise, offered)) return emptyList()
        if (offered is FlowTree) {
            val initial = premise as InitialAp
            if (normalStars?.supports(initial, offered) == true) {
                val update = normalStars.add(initial, offered)
                if (update.affectedInitials.isNotEmpty()) {
                    // Include concrete-only shapes: there need not have been an old FLOW L.
                    for (shape in concreteShapes.lookupExtensions(initial.base, initial.pathData)) refreshConcrete(shape)
                }
                return update.fresh
            }
            val delta = groups.getOrPut(premise) { ConclusionGroup(m, interners) }.addAll(offered)
            if ((replaceCovered || normalStars != null) && delta.isNotEmpty()) refreshConcrete(initial)
            return delta
        }
        val residual = normalize(premise, offered) ?: return emptyList()
        rememberConcrete(premise)
        // The scalar summary backend gains the selected NORMAL relation law only.
        // Point owners have no normalStars and retain their existing diagonal path.
        if (!replaceCovered && normalStars != null) return addFallback(premise, residual)
        if (diagonal.supports(premise, residual)) return diagonal.addAll(premise, residual)
        // A cross-mark or exact sibling must not create a second authoritative
        // copy of the diagonal membership in the scalar fallback.
        if (residual is TaintTree && (residual.anyTail == Tail.STAR || residual.anyTail == Tail.ANY)) {
            val initial = flowInitialForCoverage(m, premise)
            val mark = ((premise as? InitialAp)?.mark as? MarkSlot.Concrete)?.mark
            if (initial != null && mark != null) {
                val mask = m.markSetOf(mark)
                val root = m.taintAlg.mapLeaves(residual.root, m.cancellation) {
                    m.taintLeaves(MarkSet.EMPTY, it.any intersect mask)
                }
                if (root != null) {
                    val part = residual.withRoot(root)
                    val fresh = diagonal.addAll(premise, part)
                    val rest = ApOps(m).without(residual, part)
                    val extra = rest?.let { addFallback(premise, it) }.orEmpty()
                    val result = ConclusionGroup(m, interners)
                    for (value in fresh + extra) result.addAll(value)
                    return result.all().toList()
                }
            }
        }
        return addFallback(premise, residual)
    }

    private fun addFallback(premise: PremiseKey, residual: Facts): List<Facts> =
        groups.getOrPut(premise) { ConclusionGroup(m, interners) }.addAll(residual)

    private fun rememberConcrete(premise: PremiseKey) {
        if (replaceCovered || normalStars != null) flowInitialForCoverage(m, premise)?.let { shape ->
            concreteByShape.getOrPut(shape) {
                concreteShapes.add(shape.base, shape.pathData, shape)
                java.util.Collections.newSetFromMap(IdentityHashMap())
            }.add(premise)
        }
    }

    private fun flowCovers(shape: InitialAp): List<FlowTree> = buildList {
        if (replaceCovered) groups[shape]?.all()?.filterIsInstance<FlowTree>()?.forEach(::add)
        normalStars?.visitSpecializedCovers(shape, ::add)
    }

    private fun refreshConcrete(shape: InitialAp) {
        val covers = flowCovers(shape)
        if (replaceCovered) for (flow in covers) diagonal.compact(shape, flow)
        val keys = concreteByShape[shape] ?: return
        for (key in keys.toList()) {
            m.cancellation.checkpoint()
            groups[key]?.let { current ->
                val replacement = ConclusionGroup(m, interners)
                for (facts in current.all()) normalize(key, facts)?.let { replacement.addAll(it) }
                if (replacement.all().none()) groups.remove(key) else groups[key] = replacement
            }
            if (groups[key]?.all()?.any() != true && diagonal.borrow(key).none()) {
                keys.remove(key)
                emptied(key)
            }
        }
        if (keys.isEmpty()) {
            concreteByShape.remove(shape)
            concreteShapes.remove(shape.base, shape.pathData, shape)
        }
    }

    /** All supported typed cells use the same coverage law. Call consumers
     * retain their own identity classifier; it is not a summary-store guard. */
    fun normalize(premise: PremiseKey, facts: Facts): Facts? {
        if (facts is FlowTree && premise is InitialAp && normalStars?.supports(premise, facts) == true)
            return normalStars.retainCurrent(premise, facts)
        if ((!replaceCovered && normalStars == null) || facts !is TaintTree ||
            (facts.anyTail != Tail.STAR && facts.anyTail != Tail.ANY)) return facts
        val initial = flowInitialForCoverage(m, premise) ?: return facts
        return removeFlowCovered(m, premise, facts, flowCovers(initial), facts.nonSubsumable)
    }

    fun all(): Sequence<Pair<PremiseKey, Facts>> = sequence {
        for ((premise, group) in groups) {
            m.cancellation.checkpoint()
            for (facts in group.all()) yield(premise to facts)
        }
        yieldAll(diagonal.all())
        normalStars?.all()?.forEach { yield(it.first to it.second) }
    }

    fun borrow(premise: PremiseKey): Sequence<Facts> = sequence {
        yieldAll(groups[premise]?.all() ?: emptySequence())
        yieldAll(diagonal.borrow(premise))
        yieldAll(normalStars?.borrowExact(premise) ?: emptySequence())
    }

    fun retainCurrentAll(premise: PremiseKey, offered: Facts): List<Facts> =
        retainCurrentFacts(m, offered, borrow(premise).asIterable())
}

package org.opentaint.dataflow.bidi.store

import it.unimi.dsi.fastutil.ints.Int2ObjectOpenHashMap
import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.util.Cancellation

internal enum class DemandQueryKind { INITIAL_C2, OUTPUT_C5 }

/** A cursor only follows branches with a real compatible ANY witness. */
internal interface AnyDemandCursor {
    fun follow(accessor: Int): AnyDemandCursor?
    fun subtreeWitness(): Pattern?
}

internal interface EntryPrecisionView {
    fun precisionCursors(actual: Pattern, policy: RestrictedInitialPolicy): List<AnyDemandCursor>?
}

/** Snapshot-private geometry. Builder nodes never escape and are not changed after build. */
internal class FrozenDemandTrie<P : Any> private constructor(
    private val roots: Map<AccessPathBase, Node<P>>,
    private val cancellation: Cancellation?,
) {
    private class QueryWork(var nodes: Long = 0, var profiles: Long = 0, var candidates: Long = 0)
    private data class Terminal<P>(val ordinal: Int, val pattern: Pattern, val payload: P)
    private class Node<P : Any> {
        var values: LinkedHashMap<P, Terminal<P>>? = LinkedHashMap(2)
        var children: Int2ObjectOpenHashMap<Node<P>>? = null
        var nativeChildren: List<Node<P>> = emptyList()
        var profiles: Map<MarkSlot, List<Terminal<P>>> = emptyMap()
        var witnesses: Map<MarkSlot, Terminal<P>> = emptyMap()
        fun child(accessor: Int): Node<P>? = children?.get(accessor)
    }

    class Builder<P : Any>(private val cancellation: Cancellation? = null) {
        private val roots = HashMap<AccessPathBase, Node<P>>(4)
        private val nodes = ArrayList<Node<P>>()
        private var ordinal = 0
        private var built = false

        fun add(pattern: Pattern, payload: P): Boolean {
            check(!built)
            cancellation?.checkpoint()
            var node = roots.getOrPut(pattern.fact.base) { Node<P>().also(nodes::add) }
            for (accessor in pattern.fact.path) {
                cancellation?.checkpoint()
                val children = node.children ?: Int2ObjectOpenHashMap<Node<P>>().also { node.children = it }
                node = children.getOrPut(accessor) { Node<P>().also(nodes::add) }
            }
            val values = checkNotNull(node.values)
            if (values.containsKey(payload)) return false
            values[payload] = Terminal(ordinal++, pattern, payload)
            return true
        }

        fun build(): FrozenDemandTrie<P> {
            check(!built)
            built = true
            // Use the original fastutil child order, including its final hash-table capacity.
            for (node in nodes.asReversed()) {
                cancellation?.checkpoint()
                node.nativeChildren = node.children?.values?.toList().orEmpty()
                val values = checkNotNull(node.values)
                node.profiles = values.values.groupBy { it.pattern.fact.mark }
                val witnesses = LinkedHashMap<MarkSlot, Terminal<P>>()
                fun offer(mark: MarkSlot, terminal: Terminal<P>) {
                    val prior = witnesses[mark]
                    if (prior == null || terminal.ordinal < prior.ordinal) witnesses[mark] = terminal
                }
                for (terminal in values.values) {
                    val pattern = terminal.pattern
                    if (pattern.fact.tail == Tail.ANY && pattern.exclusion == ExclusionSet.Empty) {
                        offer(pattern.fact.mark, terminal)
                    }
                }
                for (child in node.nativeChildren) for ((mark, witness) in child.witnesses) offer(mark, witness)
                node.witnesses = witnesses
                node.values = null
            }
            return FrozenDemandTrie(roots, cancellation)
        }
    }

    fun hasBase(base: AccessPathBase): Boolean = roots.containsKey(base)

    fun visitNativeOrder(actual: Pattern, kind: DemandQueryKind, catalog: MarkTable?, visit: (P) -> Unit) =
        visitCountedNativeOrder(actual, kind, catalog, null, visit)

    fun visitCountedNativeOrder(actual: Pattern, kind: DemandQueryKind, catalog: MarkTable?,
                                counts: ((Long, Long, Long) -> Unit)?, visit: (P) -> Unit) {
        cancellation?.checkpoint()
        var node = roots[actual.fact.base] ?: run { counts?.invoke(0, 0, 0); return }
        val work = if (counts == null) null else QueryWork()
        fun values(at: Node<P>) {
            if (work != null) work.nodes++
            val selected = ArrayList<Terminal<P>>()
            for ((mark, terminals) in at.profiles) {
                cancellation?.checkpoint()
                if (work != null) work.profiles++
                val compatible = when (kind) {
                    DemandQueryKind.INITIAL_C2 -> markSub(mark, actual.fact.mark, catalog)
                    DemandQueryKind.OUTPUT_C5 -> marksMeet(mark, actual.fact.mark, catalog)
                }
                if (compatible) selected.addAll(terminals)
            }
            if (selected.size > 1) selected.sortBy { it.ordinal }
            for (terminal in selected) {
                cancellation?.checkpoint()
                if (work != null) work.candidates++
                visit(terminal.payload)
            }
        }
        try {
            for (accessor in actual.fact.path) {
                values(node)
                node = node.child(accessor) ?: return
            }
            val stack = ArrayDeque<Node<P>>()
            stack.addLast(node)
            while (stack.isNotEmpty()) {
                cancellation?.checkpoint()
                val at = stack.removeLast()
                values(at)
                stack.addAll(at.nativeChildren)
            }
        } finally { if (work != null) counts?.invoke(work.nodes, work.profiles, work.candidates) }
    }

    fun precisionCursors(actual: Pattern, catalog: MarkTable?): List<AnyDemandCursor> {
        val root = roots[actual.fact.base] ?: return emptyList()
        return root.witnesses.keys.mapNotNull { profile ->
            cancellation?.checkpoint()
            if (markSub(profile, actual.fact.mark, catalog)) Cursor(root, profile) else null
        }
    }

    private inner class Cursor(private val node: Node<P>, private val profile: MarkSlot) : AnyDemandCursor {
        override fun follow(accessor: Int): AnyDemandCursor? {
            cancellation?.checkpoint()
            val child = node.child(accessor) ?: return null
            return if (profile in child.witnesses) Cursor(child, profile) else null
        }
        override fun subtreeWitness(): Pattern? = node.witnesses[profile]?.pattern
    }
}

package org.opentaint.dataflow.bidi.store

import it.unimi.dsi.fastutil.ints.IntArrayList
import org.opentaint.dataflow.util.Cancellation

/** Exact caller-to-owner reachability. Rows are immutable after the run-1 handoff. */
internal class FrozenOwnerVisibility private constructor(
    private val componentOfMethod: IntArray,
    private val wordsByComponent: Array<LongArray>,
    val familyCount: Int,
    val statistics: BuildStatistics,
) {
    data class BuildStatistics(
        val components: Int,
        val dagEdges: Long,
        val seedMemberships: Long,
        val allocatedWords: Long,
        val buildNanos: Long,
    )

    fun contains(methodId: Int?, familyId: Int): Boolean {
        if (methodId == null) return false
        val row = wordsByComponent[componentOfMethod[methodId]]
        return row[familyId ushr 6] and (1L shl (familyId and 63)) != 0L
    }

    /** Read-only certificate for independent finite-graph tests. */
    internal fun componentId(methodId: Int): Int = componentOfMethod[methodId]

    class Builder(
        graph: DetachedStaticCallGraph,
        private val familyCount: Int,
        private val cancellation: Cancellation,
    ) {
        private val started = System.nanoTime()
        private val component: IntArray
        private val dag: Array<IntArray>
        private val callerFirst: IntArray
        private val words: Array<LongArray>
        private var seedMemberships = 0L
        private var finished = false

        init {
            cancellation.checkpoint()
            require(familyCount >= 0)
            if (familyCount == 0) {
                // No query can use this index. Do not traverse an otherwise large graph.
                component = IntArray(0)
                dag = emptyArray()
                callerFirst = IntArray(0)
                words = emptyArray()
            } else {
                val components = components(graph, cancellation)
                component = components.first
                dag = quotient(graph, component, components.second, cancellation)
                callerFirst = topologicalOrder(dag, cancellation)
                val wordCount = familyCount / 64 + if (familyCount % 64 == 0) 0 else 1
                words = Array(dag.size) { cancellation.checkpoint(); LongArray(wordCount) }
            }
        }

        fun seed(familyId: Int, ownerId: Int) {
            cancellation.checkpoint()
            check(!finished)
            val row = words[component[ownerId]]
            row[familyId ushr 6] = row[familyId ushr 6] or (1L shl (familyId and 63))
            seedMemberships++
        }

        fun finish(): FrozenOwnerVisibility {
            cancellation.checkpoint()
            check(!finished)
            // Every child row is complete before its parent consumes it.
            for (position in callerFirst.lastIndex downTo 0) {
                cancellation.checkpoint()
                val parent = callerFirst[position]
                val into = words[parent]
                for (child in dag[parent]) {
                    cancellation.checkpoint()
                    val from = words[child]
                    for (word in into.indices) {
                        cancellation.checkpoint()
                        into[word] = into[word] or from[word]
                    }
                }
            }
            finished = true
            val stats = BuildStatistics(dag.size, dag.sumOf { it.size.toLong() }, seedMemberships,
                words.sumOf { it.size.toLong() }, System.nanoTime() - started)
            return FrozenOwnerVisibility(component, words, familyCount, stats)
        }

        companion object {
            /** Iterative Kosaraju. Mark on push, so each stack has at most N entries. */
            private fun components(graph: DetachedStaticCallGraph, cancellation: Cancellation): Pair<IntArray, Int> {
                val size = graph.methodCount
                val seen = BooleanArray(size)
                val cursor = IntArray(size)
                val stack = IntArray(size)
                val finish = IntArray(size)
                var finished = 0
                var pending = 0
                for (root in 0 until size) {
                    cancellation.checkpoint()
                    if (seen[root]) continue
                    stack[pending++] = root
                    seen[root] = true
                    while (pending > 0) {
                        cancellation.checkpoint()
                        val vertex = stack[pending - 1]
                        if (cursor[vertex] < graph.outDegree(vertex)) {
                            val child = graph.calleeAt(vertex, cursor[vertex]++)
                            if (!seen[child]) {
                                seen[child] = true
                                stack[pending++] = child
                            }
                        } else {
                            pending--
                            finish[finished++] = vertex
                        }
                    }
                }

                val reverseSize = IntArray(size)
                for (vertex in 0 until size) {
                    cancellation.checkpoint()
                    for (i in 0 until graph.outDegree(vertex)) {
                        cancellation.checkpoint()
                        reverseSize[graph.calleeAt(vertex, i)]++
                    }
                }
                val reverse = Array(size) { cancellation.checkpoint(); IntArray(reverseSize[it]) }
                reverseSize.fill(0)
                for (vertex in 0 until size) {
                    cancellation.checkpoint()
                    for (i in 0 until graph.outDegree(vertex)) {
                        cancellation.checkpoint()
                        val child = graph.calleeAt(vertex, i)
                        reverse[child][reverseSize[child]++] = vertex
                    }
                }

                val component = IntArray(size) { -1 }
                var componentCount = 0
                for (position in finished - 1 downTo 0) {
                    cancellation.checkpoint()
                    val root = finish[position]
                    if (component[root] >= 0) continue
                    val id = componentCount++
                    component[root] = id
                    stack[pending++] = root
                    while (pending > 0) {
                        cancellation.checkpoint()
                        val vertex = stack[--pending]
                        for (parent in reverse[vertex]) {
                            cancellation.checkpoint()
                            if (component[parent] < 0) {
                                component[parent] = id
                                stack[pending++] = parent
                            }
                        }
                    }
                }
                return component to componentCount
            }

            private fun quotient(
                graph: DetachedStaticCallGraph, component: IntArray, count: Int, cancellation: Cancellation,
            ): Array<IntArray> {
                val outgoing = Array(count) { cancellation.checkpoint(); IntArrayList() }
                for (vertex in 0 until graph.methodCount) {
                    cancellation.checkpoint()
                    val parent = component[vertex]
                    for (i in 0 until graph.outDegree(vertex)) {
                        cancellation.checkpoint()
                        val child = component[graph.calleeAt(vertex, i)]
                        if (child != parent) outgoing[parent].add(child)
                    }
                }
                return Array(count) { parent ->
                    cancellation.checkpoint()
                    val children = outgoing[parent].toIntArray()
                    children.sort()
                    var size = 0
                    for (child in children) {
                        cancellation.checkpoint()
                        if (size == 0 || children[size - 1] != child) children[size++] = child
                    }
                    if (size == children.size) children else children.copyOf(size)
                }
            }

            /** Explicit Kahn order. Component numbering is not a rank contract. */
            private fun topologicalOrder(dag: Array<IntArray>, cancellation: Cancellation): IntArray {
                val incoming = IntArray(dag.size)
                for (children in dag) {
                    cancellation.checkpoint()
                    for (child in children) { cancellation.checkpoint(); incoming[child]++ }
                }
                val order = IntArray(dag.size)
                var read = 0
                var write = 0
                for (vertex in incoming.indices) {
                    cancellation.checkpoint()
                    if (incoming[vertex] == 0) order[write++] = vertex
                }
                while (read < write) {
                    cancellation.checkpoint()
                    for (child in dag[order[read++]]) {
                        cancellation.checkpoint()
                        if (--incoming[child] == 0) order[write++] = child
                    }
                }
                check(write == dag.size) { "SCC quotient has a cycle" }
                return order
            }
        }
    }
}

package org.opentaint.dataflow.bidi.store

import org.opentaint.dataflow.bidi.ap.TaintMark

/** Immutable membership. Emptiness never enumerates marks or computes cardinality. */
interface ImmutableRequestMarks : RequestMarkSelection {
    val isEmpty: Boolean
}

/** Borrow the original segments; no merged array, seen set, or interner entry. */
internal fun distinctUnionView(a: RequestMarkSet, b: RequestMarkSet,
                               checkpoint: () -> Unit): ImmutableRequestMarks = when {
    a.isEmpty -> b
    b.isEmpty || a === b -> a
    else -> UnionRequestMarks(a, b, checkpoint)
}

private class UnionRequestMarks(
    private val a: RequestMarkSet,
    private val b: RequestMarkSet,
    private val checkpoint: () -> Unit,
) : ImmutableRequestMarks {
    override val isEmpty: Boolean get() = false
    override fun containsId(id: Int): Boolean = a.containsId(id) || b.containsId(id)
    override fun cursor(): RequestMarkCursor = object : RequestMarkCursor {
        private var i = 0
        private var j = 0
        private var hasLast = false
        private var last = 0
        override val isComplete: Boolean get() = i == a.size && j == b.size
        override fun step(budget: Int, visit: (TaintMark) -> Unit): Int {
            require(budget > 0)
            var used = 0
            while (used < budget && !isComplete) {
                checkpoint()
                val id = if (j == b.size || (i < a.size && a.idAt(i) <= b.idAt(j)))
                    a.idAt(i++) else b.idAt(j++)
                used++
                if (!hasLast || id != last) {
                    hasLast = true
                    last = id
                    visit(TaintMark(id))
                }
            }
            return used
        }
    }
}

/** Cursor work is bounded even when a step only consumes duplicate source IDs. */
internal fun ImmutableRequestMarks.forEachMark(checkpoint: () -> Unit = {}, visit: (TaintMark) -> Unit) {
    val values = cursor()
    while (!values.isComplete) {
        checkpoint()
        values.step(256, visit)
    }
}

package org.opentaint.dataflow.bidi.store

import org.opentaint.dataflow.bidi.ap.*

/** Initial keys are manager-interned and have identity equality. */
class InitialFactStore {
    private val initials = LinkedHashMap<InitialAp, Int>()

    fun add(seed: AdmittedInitial): Boolean {
        if (!RuntimeDataDomain.initial(seed.initial)) return false
        val canonical = canonicalAdmission(seed.initial, seed.layer)
        val bit = 1 shl canonical.layer.ordinal
        val old = initials[canonical.initial] ?: 0
        if (old and bit != 0) return false
        initials[canonical.initial] = old or bit
        return true
    }

    /** Explicit legacy entry: use the intrinsic start policy, with no actual-input support. */
    fun add(i: InitialAp): Boolean = add(AdmittedInitial(i, Layer.NORMAL))

    fun all(): Collection<InitialAp> = initials.keys.toList()
    fun admissions(): Collection<AdmittedInitial> = initials.flatMap { (initial, mask) ->
        Layer.entries.filter { mask and (1 shl it.ordinal) != 0 }.map { AdmittedInitial(initial, it) }
    }
}

package org.opentaint.dataflow.bidi.store

import org.opentaint.dataflow.util.Cancellation

/** One owning writer; the last new slot value completes each product exactly once. */
class KaryJoin<T : Any>(val arity: Int, private val cancellation: Cancellation? = null) {
    init { require(arity >= 2) { "A k-ary join needs at least two slots" } }
    private val slots = Array(arity) { LinkedHashMap<T, T>() }
    private var missing = arity

    internal val memberCount: Int get() = slots.sumOf { it.size }

    fun add(slot: Int, value: T): List<List<T>> {
        cancellation?.checkpoint()
        require(slot in 0 until arity) { "A literal index must be within the join's arity" }
        val values = slots[slot]
        val wasEmpty = values.isEmpty()
        if (values.putIfAbsent(value, value) != null) return emptyList()
        if (wasEmpty) missing--
        return products(slot, value)
    }

    /** Read the current annotation without adding a semantic join member. */
    internal fun current(slot: Int, value: T): T? {
        cancellation?.checkpoint()
        require(slot in 0 until arity)
        return slots[slot][value]
    }

    /** Refresh metadata on one accepted relation without retaining its old version. */
    fun replace(slot: Int, previous: T, value: T): List<List<T>> {
        cancellation?.checkpoint()
        require(slot in 0 until arity)
        check(slots[slot].remove(previous) != null) { "Only a standing member can be refreshed" }
        check(slots[slot].putIfAbsent(value, value) == null) { "A replacement keeps one semantic member" }
        return products(slot, value)
    }

    private fun products(slot: Int, value: T): List<List<T>> {
        if (missing != 0) return emptyList()

        val choices = Array<List<T>>(arity) { index ->
            cancellation?.checkpoint()
            if (index == slot) listOf(value) else slots[index].values.toList()
        }
        val positions = IntArray(arity)
        val out = ArrayList<List<T>>()
        while (true) {
            cancellation?.checkpoint()
            val tuple = ArrayList<T>(arity)
            for (index in 0 until arity) {
                cancellation?.checkpoint()
                tuple += choices[index][positions[index]]
            }
            out += tuple
            var index = arity - 1
            while (index >= 0) {
                cancellation?.checkpoint()
                positions[index]++
                if (positions[index] < choices[index].size) break
                positions[index] = 0
                index--
            }
            if (index < 0) return out
        }
    }
}

package org.opentaint.dataflow.bidi.store

import it.unimi.dsi.fastutil.ints.IntArrayList
import it.unimi.dsi.fastutil.ints.IntLinkedOpenHashSet
import it.unimi.dsi.fastutil.longs.Long2IntOpenHashMap
import it.unimi.dsi.fastutil.longs.LongArrayList
import org.opentaint.dataflow.bidi.ap.*
import java.util.Collections

/** Raw scalar data for ordinary actual-call binding. This is not an executable summary. */
data class StaticWriteKey(val original: InitialAp, val result: Pattern) {
    fun guidance(): StaticGuidanceEdge {
        val (from, to) = normalizeFlowSummaryPatterns(original.toPattern(), result)
        return StaticGuidanceEdge.of(from, to)
    }
}

private data class StaticWriteGeometry(val original: Pattern, val result: Pattern)

/** Share geometry once and pack the exact input/output mark pair in one primitive word.
 * Unlike the B-only interner, this directory also represents ordinary and genuine ZERO inputs.
 * FLOW output mark exclusions remain raw until actual-call application has finished. */
class StaticWriteKeyInterner(private val ap: ApManager) {
    private val geometryIds = HashMap<StaticWriteGeometry, Int>()
    private val geometries = ArrayList<StaticWriteGeometry>()
    private val labels = ArrayList<Long2IntOpenHashMap>()
    private val rowGeometry = IntArrayList()
    private val rowMarks = LongArrayList()

    @Synchronized fun intern(original: InitialAp, result: Pattern): Int {
        ap.cancellation.checkpoint()
        check(original.manager === ap) { "A static-write key must use its owner's AP manager" }
        check(result.fact.base == STATIC) { "A static-write key needs a static image" }
        check((original.mark is MarkSlot.Star) == (result.fact.mark is MarkSlot.Star)) {
            "A static-write key preserves the original's FLOW/TAINT relation"
        }
        fun geometry(pattern: Pattern): Pattern = pattern.copy(fact = pattern.fact.copy(
            path = Collections.unmodifiableList(ArrayList(pattern.fact.path)),
            mark = if (pattern.fact.mark is MarkSlot.Concrete) MarkSlot.STAR else pattern.fact.mark))
        val shape = StaticWriteGeometry(geometry(original.toPattern()), geometry(result))
        val shapeId = geometryIds.getOrPut(shape) {
            geometries.size.also {
                geometries += shape
                labels += Long2IntOpenHashMap().apply { defaultReturnValue(-1) }
            }
        }
        val input = original.mark
        val output = result.fact.mark
        val pair = if (input is MarkSlot.Concrete && output is MarkSlot.Concrete)
            ((input.mark.id.toLong() + 1L) shl 32) or ((output.mark.id.toLong() + 1L) and 0xffffffffL)
        else 0L
        val existing = labels[shapeId].get(pair)
        if (existing >= 0) return existing
        val id = rowGeometry.size
        rowGeometry.add(shapeId)
        rowMarks.add(pair)
        labels[shapeId].put(pair, id)
        return id
    }

    @Synchronized fun row(id: Int): StaticWriteKey {
        ap.cancellation.checkpoint()
        val shape = geometries[rowGeometry.getInt(id)]
        val pair = rowMarks.getLong(id)
        val original = if (pair == 0L) shape.original else shape.original.copy(fact = shape.original.fact.copy(
            mark = MarkSlot.Concrete(TaintMark((pair ushr 32).toInt() - 1))))
        val result = if (pair == 0L) shape.result else shape.result.copy(fact = shape.result.fact.copy(
            mark = MarkSlot.Concrete(TaintMark(pair.toInt() - 1))))
        return StaticWriteKey(ap.initial(original), result)
    }

    @Synchronized fun clear() {
        geometryIds.clear(); geometries.clear(); labels.clear(); rowGeometry.clear(); rowMarks.clear()
    }
}

/** Borrow only before the shared key directory is released at run-1 handoff. */
class FrozenStaticWrites internal constructor(
    val owner: MethodKey,
    val interner: StaticWriteKeyInterner,
    private val observed: IntArray,
    private val lost: IntArray,
    val peakCount: Int,
) {
    val observedCount: Int get() = observed.size
    val lostCount: Int get() = lost.size
    fun observedIds(): IntArray = observed.copyOf()
    fun lostIds(): IntArray = lost.copyOf()
    fun forEachObservedId(visit: (Int) -> Unit) { for (id in observed) visit(id) }
    fun forEachLostId(visit: (Int) -> Unit) { for (id in lost) visit(id) }
    fun observedRows(): Sequence<StaticWriteKey> = observed.asSequence().map(interner::row)
    fun lostRows(): Sequence<StaticWriteKey> = lost.asSequence().map(interner::row)
}

/** Actor-owned candidates, not a killed-only set. Keep every observed thin ID until the
 * joined final prune: FLOW-backed common storage can later erase a colored survivor. */
class KilledStaticWriteStore(
    private val owner: MethodKey,
    private val ap: ApManager,
    private val ops: ApOps,
    private val interner: StaticWriteKeyInterner,
) {
    private var candidates: IntLinkedOpenHashSet? = IntLinkedOpenHashSet()
    private var frozen: FrozenStaticWrites? = null
    val candidateCount: Int get() = frozen?.observedCount ?: checkNotNull(candidates).size
    var peakCount: Int = 0; private set

    fun observe(original: PremiseKey, result: Facts) {
        check(frozen == null) { "A completed static-write inventory cannot accept new observations" }
        ap.cancellation.checkpoint()
        if (!RuntimeDataDomain.packet(original, result)) return
        check(original is InitialAp) { "Run-1 static-write candidates have one original" }
        if (result.base != STATIC) return
        val pending = checkNotNull(candidates)
        for (leaf in ops.leaves(result)) {
            ap.cancellation.checkpoint()
            pending.add(interner.intern(original, leaf))
        }
        peakCount = maxOf(peakCount, pending.size)
    }

    /** Read current survivor views only at joined quiescence. Guidance normalization is
     * for equality here; observed rows retain their raw AP data for caller binding. */
    fun freeze(
        common: Sequence<Pair<PremiseKey, Facts>>,
        privateB: Sequence<StaticGuidanceEdge>,
    ): FrozenStaticWrites {
        frozen?.let { return it }
        val survivors = HashSet<StaticGuidanceEdge>()
        for ((original, result) in common) {
            ap.cancellation.checkpoint()
            if (!RuntimeDataDomain.packet(original, result)) continue
            check(original is InitialAp) { "Run-1 summaries have one original" }
            if (result.base != STATIC) continue
            for (leaf in ops.leaves(result)) {
                ap.cancellation.checkpoint()
                val (from, to) = normalizeFlowSummaryPatterns(original.toPattern(), leaf)
                survivors += StaticGuidanceEdge.of(from, to)
            }
        }
        for (row in privateB) {
            ap.cancellation.checkpoint()
            if (!RuntimeDataDomain.base(row.from.fact.base) || !RuntimeDataDomain.base(row.to.fact.base)) continue
            val (from, to) = normalizeFlowSummaryPatterns(row.from, row.to)
            survivors += StaticGuidanceEdge.of(from, to)
        }
        val observed = checkNotNull(candidates).toIntArray()
        val lost = IntArrayList()
        for (id in observed) {
            ap.cancellation.checkpoint()
            if (interner.row(id).guidance() !in survivors) lost.add(id)
        }
        return FrozenStaticWrites(owner, interner, observed, lost.toIntArray(), peakCount).also {
            frozen = it
            candidates = null // Release the mutable hash table, including its backing arrays.
        }
    }
}

package org.opentaint.dataflow.bidi.store

import org.opentaint.dataflow.ap.ifds.LanguageManager
import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.ir.api.common.cfg.CommonInst
import java.util.BitSet
import java.util.IdentityHashMap

/** A dense directory belongs to one block. Equal AP facts in different
 * directories do not share a post-statement admission cell. */
interface PointDirectory<P> {
    val size: Int
    fun index(point: P): Int
}

/** One writer owns completed post-point results for a run. A row at S is
 * the output of S, never its incoming input or the output of a predecessor. */
open class ScopedEdgeStore<P>(private val m: ApManager, private val points: PointDirectory<P>,
                             private val fieldLimit: Int, flowBacked: Boolean = false,
                             collectStatistics: Boolean = false) {
    init {
        require(fieldLimit >= 1) { "The field limit must be positive" }
        require(points.size >= 0) { "A point directory cannot have negative size" }
    }

    private val size = points.size
    private fun pointIndex(point: P): Int = points.index(point).also {
        require(it in 0 until size) { "A point must belong to this block directory: $it of $size" }
    }
    private val reach = IdentityHashMap<PremiseKey, Array<BitSet>>()
    private val groups = IdentityHashMap<PremiseKey, ScalarPremiseRows>()
    private val statistics = if (collectStatistics) ScalarCounters() else null

    /** A premise owns its point bits. Only competing images allocate full cells. */
    private class ScalarPremiseRows(val initial: InitialAp?) {
        var normal: BitSet? = null
        var demand: BitSet? = null
        var protectedNormal: BitSet? = null
        var protectedDemand: BitSet? = null
        var full: Array<ConclusionGroup?>? = null

        private fun bits(layer: Layer, protection: Boolean, allocate: Boolean): BitSet? {
            val old = when (layer) {
                Layer.NORMAL -> if (protection) protectedNormal else normal
                Layer.DEMAND -> if (protection) protectedDemand else demand
            }
            if (old != null || !allocate) return old
            val fresh = BitSet()
            when (layer) {
                Layer.NORMAL -> if (protection) protectedNormal = fresh else normal = fresh
                Layer.DEMAND -> if (protection) protectedDemand = fresh else demand = fresh
            }
            return fresh
        }

        fun present(layer: Layer, index: Int) = bits(layer, false, false)?.get(index) == true
        fun isProtected(layer: Layer, index: Int) = bits(layer, true, false)?.get(index) == true
        fun setPresent(layer: Layer, index: Int) { bits(layer, false, true)!!.set(index) }
        fun setProtected(layer: Layer, index: Int) { bits(layer, true, true)!!.set(index) }
        fun ensureFull(size: Int): Array<ConclusionGroup?> =
            full ?: arrayOfNulls<ConclusionGroup>(size).also { full = it }
        fun clearIdentityBitsAt(index: Int) {
            normal?.clear(index); demand?.clear(index)
            protectedNormal?.clear(index); protectedDemand?.clear(index)
        }
    }

    private class ScalarCounters {
        var promotedPoints = 0L
        var firstFullPoints = 0L
        val fallbackReasons = HashMap<String, Long>()
    }
    private val interners = m.newInterners()
    // Local rule observations still need concrete membership. Share its exact
    // diagonal geometry here; semantic replacement is a summary boundary only.
    private val packed: Array<FlowBackedSummaries?>? = if (flowBacked) arrayOfNulls(size) else null

    /** Null selects the exact scalar fallback; an empty result is a duplicate.
     * The packet decoder, not its FLOW-shaped storage key, determines K6. */
    fun addDiagonal(node: P, offered: DiagonalDelta): List<DiagonalDelta>? {
        m.cancellation.checkpoint()
        if (!RuntimeDataDomain.initial(offered.initialShape) || !RuntimeDataDomain.base(offered.base)) return emptyList()
        val statements = packed ?: return null
        check(offered.initialShape.manager === m) { "A diagonal packet needs an owned initial shape" }
        check(offered.base !is AccessPathBase.CleanerTemporary && offered.base != AccessPathBase.Zero)
        assert(offered.geometry.boundedDepth <= fieldLimit) { "W3: a stored conclusion must be within the field limit" }
        val index = pointIndex(node)
        val owner = statements[index] ?: FlowBackedSummaries(m, replaceCovered = false, interners = interners)
            .also { statements[index] = it }
        return owner.addDiagonal(offered)
    }

    /** T4: new leaves, or the whole merged value when a T2 annotation changes. */
    fun add(node: P, premise: PremiseKey, f: Facts): Facts? =
        addAll(node, premise, f).also { check(it.size <= 1) { "Use addAll for split canonical headers" } }.singleOrNull()

    fun addAll(node: P, premise: PremiseKey, f: Facts): List<Facts> {
        m.cancellation.checkpoint()
        if (!RuntimeDataDomain.packet(premise, f)) return emptyList()
        check(f.base !is AccessPathBase.CleanerTemporary) { "A field-action temporary cannot enter method storage" }
        check((f is FlowTree) == premise.isFlow) { "K6: the conclusion kind follows the premise" }
        check(premise !is PremiseSet || f is TaintTree) { "A multi-premise edge must be TAINT" }
        val index = pointIndex(node)
        when (f) {
            is Reach -> {
                val bits = reach.getOrPut(premise) { arrayOf(BitSet(size), BitSet(size)) }[f.layer.ordinal]
                if (bits[index]) return emptyList()
                bits.set(index)
                return listOf(f)
            }
            is FlowTree -> assert(f.root.boundedDepth <= fieldLimit) { "W3: a stored conclusion must be within the field limit" }
            is TaintTree -> assert(f.root.boundedDepth <= fieldLimit) { "W3: a stored conclusion must be within the field limit" }
        }
        packed?.let { statements ->
            val owner = statements[index] ?: FlowBackedSummaries(m, replaceCovered = false, interners = interners)
                .also { statements[index] = it }
            return owner.addAll(premise, f)
        }
        val rows = groups.getOrPut(premise) {
            ScalarPremiseRows((premise as? InitialAp)?.takeUnless { it.isZero })
        }
        rows.full?.get(index)?.let { return it.addAll(f) }
        val kind = rows.initial?.let { m.identityKind(it, f) } ?: NOT_IDENTITY
        if (kind == NOT_IDENTITY) return promoteAndAdd(rows, index, f)
        val seen = rows.present(f.layer, index)
        val protected = kind == PROTECTED_IDENTITY
        if (seen && (!protected || rows.isProtected(f.layer, index))) return emptyList()
        rows.setPresent(f.layer, index)
        if (protected) rows.setProtected(f.layer, index)
        return listOf(f)
    }

    /** Restore current compact images only. The restoration delta never escapes. */
    private fun promoteAndAdd(rows: ScalarPremiseRows, index: Int, offered: Facts): List<Facts> {
        val group = ConclusionGroup(m, interners)
        var promoted = false
        for (layer in Layer.entries) {
            m.cancellation.checkpoint()
            if (rows.present(layer, index)) {
                promoted = true
                group.addAll(initialImage(m, checkNotNull(rows.initial), layer, rows.isProtected(layer, index)))
            }
        }
        m.cancellation.checkpoint()
        rows.ensureFull(size)[index] = group
        rows.clearIdentityBitsAt(index)
        statistics?.let {
            if (promoted) it.promotedPoints++ else it.firstFullPoints++
            val reason = literalImageFallbackReason(rows.initial, offered)
            it.fallbackReasons[reason] = (it.fallbackReasons[reason] ?: 0L) + 1L
        }
        return group.addAll(offered)
    }

    /** Scan only on an explicit enabled request, at a quiescent owner boundary.
     * The returned object contains scalars only and cannot retain the actor. */
    fun scalarStatisticsSnapshot(): ScalarIdentityStatistics? {
        val counters = statistics ?: return null
        var compactPoints = 0L
        var compactNormal = 0L
        var compactDemand = 0L
        var compactFlow = 0L
        var compactTaint = 0L
        var protectedNormal = 0L
        var protectedDemand = 0L
        var fullPoints = 0L
        var bitWords = 0L
        var fullArrayCapacity = 0L
        for (rows in groups.values) {
            m.cancellation.checkpoint()
            val normal = rows.normal?.cardinality()?.toLong() ?: 0L
            val demand = rows.demand?.cardinality()?.toLong() ?: 0L
            compactNormal += normal
            compactDemand += demand
            var overlap = 0L
            val smaller = if (normal <= demand) rows.normal else rows.demand
            val other = if (normal <= demand) rows.demand else rows.normal
            if (smaller != null && other != null) {
                var index = smaller.nextSetBit(0)
                while (index >= 0) {
                    m.cancellation.checkpoint()
                    if (other[index]) overlap++
                    // BitSet indices are nonnegative Int values; do not overflow.
                    if (index == Int.MAX_VALUE) break
                    index = smaller.nextSetBit(index + 1)
                }
            }
            compactPoints += normal + demand - overlap
            if (rows.initial?.isFlow == true) compactFlow += normal + demand else compactTaint += normal + demand
            protectedNormal += rows.protectedNormal?.cardinality()?.toLong() ?: 0L
            protectedDemand += rows.protectedDemand?.cardinality()?.toLong() ?: 0L
            bitWords += (rows.normal?.size()?.toLong() ?: 0L) / 64L
            bitWords += (rows.demand?.size()?.toLong() ?: 0L) / 64L
            bitWords += (rows.protectedNormal?.size()?.toLong() ?: 0L) / 64L
            bitWords += (rows.protectedDemand?.size()?.toLong() ?: 0L) / 64L
            rows.full?.let { cells ->
                fullArrayCapacity += cells.size
                for (cell in cells) {
                    m.cancellation.checkpoint()
                    if (cell != null) fullPoints++
                }
            }
        }
        return ScalarIdentityStatistics(compactPoints, compactNormal, compactDemand, compactFlow, compactTaint,
            protectedNormal, protectedDemand, fullPoints, counters.promotedPoints, counters.firstFullPoints,
            bitWords, fullArrayCapacity, counters.fallbackReasons.toMap())
    }

    /** Test view of all complete stored values at a statement. */
    fun edgesAt(node: P, premise: PremiseKey? = null): Sequence<Pair<PremiseKey, Facts>> = sequence {
        m.cancellation.checkpoint()
        val index = pointIndex(node)
        packed?.get(index)?.let { owner ->
            if (premise == null) yieldAll(owner.all())
            else for (facts in owner.borrow(premise)) yield(premise to facts)
        }
        val keys = if (premise != null) listOf(premise) else LinkedHashSet<PremiseKey>().also { keys ->
            for (key in reach.keys) { m.cancellation.checkpoint(); keys += key }
            for (key in groups.keys) { m.cancellation.checkpoint(); keys += key }
        }
        for (key in keys) {
            m.cancellation.checkpoint()
            val bits = reach[key]
            for (layer in Layer.entries) if (bits != null && bits[layer.ordinal][index]) {
                m.cancellation.checkpoint()
                yield(key to Reach.of(layer))
            }
            val rows = groups[key] ?: continue
            val group = rows.full?.get(index)
            if (group != null) {
                for (value in group.all()) {
                    m.cancellation.checkpoint()
                    yield(key to value)
                }
            } else for (layer in Layer.entries) {
                m.cancellation.checkpoint()
                if (rows.present(layer, index)) yield(key to initialImage(m, checkNotNull(rows.initial), layer,
                    rows.isProtected(layer, index)))
            }
        }
    }

    /** Full leaf matching returns the whole stored value, including its off-query leaves. */
    fun edgesAt(node: P, pattern: Pattern): Sequence<Pair<PremiseKey, Facts>> = sequence {
        m.cancellation.checkpoint()
        val path = pattern.fact.path.toIntArray()
        val ops = ApOps(m)
        for ((premise, facts) in edgesAt(node)) {
            m.cancellation.checkpoint()
            if (facts.base == pattern.fact.base && ops.leavesNear(facts, path).any {
                m.cancellation.checkpoint()
                overlap(it, pattern)
            }) yield(premise to facts)
        }
    }
}

/** End-state gauges and separately named cumulative promotion counters. */
data class ScalarIdentityStatistics(
    /** Unique (premise, producing statement) cells, independent of layer. */
    val compactPoints: Long,
    /** The next four gauges count point-layer memberships. */
    val compactNormal: Long,
    val compactDemand: Long,
    val compactFlow: Long,
    val compactTaint: Long,
    val protectedNormal: Long,
    val protectedDemand: Long,
    val fullPoints: Long,
    val promotedPoints: Long,
    val firstFullPoints: Long,
    val bitWords: Long,
    val fullArrayCapacity: Long,
    val fallbackReasons: Map<String, Long>,
)

/** Compatibility directory for the unchanged no-loop method path. */
class MethodEdgeStore(m: ApManager, method: MethodKey, lm: LanguageManager,
                      fieldLimit: Int, flowBacked: Boolean = false,
                      collectStatistics: Boolean = false) : ScopedEdgeStore<CommonInst>(
    m,
    object : PointDirectory<CommonInst> {
        override val size = lm.getMaxInstIndex(method.method) + 1
        override fun index(point: CommonInst): Int = lm.getInstIndex(point)
    },
    fieldLimit, flowBacked, collectStatistics,
)

package org.opentaint.dataflow.bidi.store

import java.util.Collections
import java.util.concurrent.atomic.AtomicLong

/** Optional numeric aggregates. Totals span stores/runs; live census is retired at store release.
 *  Array cells cover the owned N1 arrays, not JVM headers, path child maps or byte sizes. */
class N1Statistics {
    private val createdStores = AtomicLong()
    private val liveStores = AtomicLong()
    private val insertions = AtomicLong()
    private val duplicates = AtomicLong()
    private val markRequests = AtomicLong()
    private val positionRequests = AtomicLong()
    private val liveMarkRequests = AtomicLong()
    private val livePositionRequests = AtomicLong()
    private val markRows = AtomicLong()
    private val positionRows = AtomicLong()
    private val liveMarkRows = AtomicLong()
    private val livePositionRows = AtomicLong()
    private val liveOrigins = AtomicLong()
    private val liveIndexNodes = AtomicLong()
    private val liveIndexBuckets = AtomicLong()
    private val livePrimitiveCells = AtomicLong()
    private val liveReferenceCells = AtomicLong()
    private val allocatedPrimitiveCells = AtomicLong()
    private val allocatedReferenceCells = AtomicLong()
    private val rowSizes = Array(31) { AtomicLong() }
    private val releasedRowSizes = Array(31) { AtomicLong() }
    private val coarseCandidates = AtomicLong()
    private val selectedCandidates = AtomicLong()
    private val overlappingCandidates = AtomicLong()
    private val existingLinkCandidates = AtomicLong()
    private val selectedExistingLinks = AtomicLong()
    private val answers = AtomicLong()
    private val climbs = AtomicLong()
    private val noActions = AtomicLong()

    internal fun newCensus(): Census {
        createdStores.incrementAndGet()
        liveStores.incrementAndGet()
        return Census()
    }

    internal fun duplicate() { duplicates.incrementAndGet() }
    internal class Candidates {
        var coarse = 0L
        var selected = 0L
        var overlapping = 0L
    }
    internal class Actions {
        var existingLinks = 0L
        var selectedLinks = 0L
        var answers = 0L
        var climbs = 0L
        var none = 0L
    }
    internal fun candidates(counts: Candidates) {
        coarseCandidates.addAndGet(counts.coarse)
        selectedCandidates.addAndGet(counts.selected)
        overlappingCandidates.addAndGet(counts.overlapping)
    }
    internal fun actions(counts: Actions) {
        existingLinkCandidates.addAndGet(counts.existingLinks)
        selectedExistingLinks.addAndGet(counts.selectedLinks)
        answers.addAndGet(counts.answers); climbs.addAndGet(counts.climbs); noActions.addAndGet(counts.none)
    }

    /** Fixed-size, store-local census; it retains no relation keys or values. */
    internal inner class Census {
        private var marks = 0L
        private var positions = 0L
        private var markRowCount = 0L
        private var positionRowCount = 0L
        private var origins = 0L
        private var nodes = 0L
        private var buckets = 0L
        private var primitiveCells = 0L
        private var referenceCells = 0L
        private val sizes = LongArray(31)

        fun origin() { origins++; liveOrigins.incrementAndGet() }
        fun node() { nodes++; liveIndexNodes.incrementAndGet() }
        fun bucket() { buckets++; liveIndexBuckets.incrementAndGet() }
        fun row(mark: Boolean) {
            if (mark) {
                markRowCount++; markRows.incrementAndGet(); liveMarkRows.incrementAndGet()
            } else {
                positionRowCount++; positionRows.incrementAndGet(); livePositionRows.incrementAndGet()
            }
        }
        fun member(mark: Boolean, previousSize: Int) {
            insertions.incrementAndGet()
            if (mark) {
                marks++; markRequests.incrementAndGet(); liveMarkRequests.incrementAndGet()
            } else {
                positions++; positionRequests.incrementAndGet(); livePositionRequests.incrementAndGet()
            }
            if (previousSize != 0) {
                val oldBin = 31 - Integer.numberOfLeadingZeros(previousSize)
                sizes[oldBin]--; rowSizes[oldBin].decrementAndGet()
            }
            val bin = 31 - Integer.numberOfLeadingZeros(Math.addExact(previousSize, 1))
            sizes[bin]++; rowSizes[bin].incrementAndGet()
        }
        fun primitiveArray(oldSize: Int, newSize: Int) {
            val difference = newSize.toLong() - oldSize
            primitiveCells += difference
            livePrimitiveCells.addAndGet(difference)
            allocatedPrimitiveCells.addAndGet(newSize.toLong())
        }
        fun referenceArray(oldSize: Int, newSize: Int) {
            val difference = newSize.toLong() - oldSize
            referenceCells += difference
            liveReferenceCells.addAndGet(difference)
            allocatedReferenceCells.addAndGet(newSize.toLong())
        }
        fun release() {
            liveStores.decrementAndGet()
            liveMarkRequests.addAndGet(-marks); livePositionRequests.addAndGet(-positions)
            liveMarkRows.addAndGet(-markRowCount); livePositionRows.addAndGet(-positionRowCount)
            liveOrigins.addAndGet(-origins); liveIndexNodes.addAndGet(-nodes); liveIndexBuckets.addAndGet(-buckets)
            livePrimitiveCells.addAndGet(-primitiveCells); liveReferenceCells.addAndGet(-referenceCells)
            for (index in sizes.indices) {
                rowSizes[index].addAndGet(-sizes[index])
                releasedRowSizes[index].addAndGet(sizes[index])
            }
        }
    }

    data class Snapshot(
        val createdStores: Long, val liveStores: Long,
        val insertions: Long, val duplicates: Long, val markRequests: Long, val positionRequests: Long,
        val liveMarkRequests: Long, val livePositionRequests: Long,
        val markRows: Long, val positionRows: Long, val liveMarkRows: Long, val livePositionRows: Long,
        val liveOrigins: Long, val liveIndexNodes: Long, val liveIndexBuckets: Long,
        val livePrimitiveCells: Long, val liveReferenceCells: Long,
        val allocatedPrimitiveCells: Long, val allocatedReferenceCells: Long,
        /** Bin k contains live rows with 2^k through 2^(k+1)-1 members. */
        val liveRowSizeHistogram: List<Long>,
        /** Final row sizes accumulated at explicit release, once per store. Not a simultaneous census. */
        val releasedRowSizeHistogram: List<Long>,
        /** These three totals cover new-link visitor queries only. */
        val coarseCandidates: Long, val selectedCandidates: Long, val overlappingCandidates: Long,
        /** Existing-link totals cover new-request queries. Action totals cover both arrival orders. */
        val existingLinkCandidates: Long, val selectedExistingLinks: Long,
        val answers: Long, val climbs: Long, val noActions: Long,
    )

    fun snapshot(): Snapshot = Snapshot(createdStores.get(), liveStores.get(), insertions.get(), duplicates.get(),
        markRequests.get(), positionRequests.get(), liveMarkRequests.get(), livePositionRequests.get(),
        markRows.get(), positionRows.get(), liveMarkRows.get(), livePositionRows.get(), liveOrigins.get(),
        liveIndexNodes.get(), liveIndexBuckets.get(), livePrimitiveCells.get(), liveReferenceCells.get(),
        allocatedPrimitiveCells.get(), allocatedReferenceCells.get(),
        Collections.unmodifiableList(rowSizes.map { it.get() }),
        Collections.unmodifiableList(releasedRowSizes.map { it.get() }), coarseCandidates.get(), selectedCandidates.get(),
        overlappingCandidates.get(), existingLinkCandidates.get(), selectedExistingLinks.get(),
        answers.get(), climbs.get(), noActions.get())

    companion object {
        const val PROPERTY = "org.opentaint.bidi.optimizationStatistics"
        fun ifEnabled(): N1Statistics? = if (java.lang.Boolean.getBoolean(PROPERTY)) N1Statistics() else null
    }
}

package org.opentaint.dataflow.bidi.store

import kotlinx.collections.immutable.PersistentMap
import kotlinx.collections.immutable.persistentHashMapOf
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.interp.*
import org.opentaint.dataflow.configuration.CommonTaintConfigurationSink
import org.opentaint.ir.api.common.cfg.CommonInst
import java.util.Collections

/** Rule identity only. No compiled predicate, transfer, or callback is retained. */
sealed interface NormalRuleDescriptor {
    data class Predicate(val occurrence: RuleOccurrenceId) : NormalRuleDescriptor

    class LegacyConjunction internal constructor(literals: List<Pattern>, target: PathFact) : NormalRuleDescriptor {
        private val literals = snapshotPatterns(literals)
        private val target = snapshotFact(target)
        private val hash = 31 * this.literals.hashCode() + this.target.hashCode()
        override fun hashCode(): Int = hash
        override fun equals(other: Any?): Boolean = this === other || other is LegacyConjunction &&
            literals == other.literals && target == other.target
    }

    class LegacySink internal constructor(private val configuration: CommonTaintConfigurationSink,
                                         private val alternative: Int, patterns: List<Pattern>) : NormalRuleDescriptor {
        private val patterns = snapshotPatterns(patterns)
        private val hash = 31 * (31 * configuration.hashCode() + alternative) + this.patterns.hashCode()
        override fun hashCode(): Int = hash
        override fun equals(other: Any?): Boolean = this === other || other is LegacySink &&
            configuration == other.configuration && alternative == other.alternative && patterns == other.patterns
    }

    companion object {
        fun predicate(occurrence: RuleOccurrenceId): NormalRuleDescriptor = Predicate(occurrence)
        fun legacyConjunction(edge: ConjunctiveEdge): NormalRuleDescriptor = LegacyConjunction(edge.literals, edge.target)
        fun legacySink(sink: SinkRule): NormalRuleDescriptor = LegacySink(sink.rule, sink.alternative, sink.patterns)
    }
}

private fun snapshotFact(fact: PathFact): PathFact =
    fact.copy(path = Collections.unmodifiableList(fact.path.toList()))
private fun snapshotPatterns(patterns: List<Pattern>): List<Pattern> =
    Collections.unmodifiableList(patterns.map { it.copy(fact = snapshotFact(it.fact)) })

/** These values describe a condition point, never a request/resume address. */
sealed interface NormalRulePhase {
    data object Statement : NormalRulePhase
    data class Boundary(val atStart: Boolean) : NormalRulePhase
    data object CallStage : NormalRulePhase
    data object CallSinkBound : NormalRulePhase
    data class Cleaner(val step: Int, val phase: CleanerPhase) : NormalRulePhase
    data class ReadOutput(val input: NormalRuleSite) : NormalRulePhase
}

data class NormalRuleSite(
    val statement: CommonInst,
    val stageOrdinal: Int,
    val action: ActionId?,
    val substep: Int,
    val phase: NormalRulePhase,
) {
    companion object {
        /** Strip the transient operation FormOwner. A sink observes semantic BOUND,
         * independent of which outgoing BOUND stage supplied a resume address. */
        fun of(rule: NormalRuleDescriptor, site: ResumeSite): NormalRuleSite {
            val sink = rule is NormalRuleDescriptor.LegacySink ||
                rule is NormalRuleDescriptor.Predicate && rule.occurrence.kind == RuleKind.CALL_SINK
            val operation = site.operation
            val phase = when (site) {
                is ResumeSite.StatementInput -> NormalRulePhase.Statement
                is ResumeSite.BoundaryInput -> NormalRulePhase.Boundary(site.atStart)
                is ResumeSite.CallStageInput -> if (sink) NormalRulePhase.CallSinkBound else NormalRulePhase.CallStage
                is ResumeSite.CleanerInput -> NormalRulePhase.Cleaner(site.step, site.phase)
                is ResumeSite.ReadOutput -> NormalRulePhase.ReadOutput(of(rule, site.input))
            }
            return NormalRuleSite(operation.form.statement,
                if (phase == NormalRulePhase.CallSinkBound) 0 else operation.stageOrdinal,
                operation.action, operation.substep, phase)
        }
    }
}

data class NormalRuleContributorOwner(val method: MethodKey, val scope: BlockScope, val markMode: MarkMode,
                                      val direction: Direction = Direction.FORWARD)
data class NormalRuleContributorKey(val owner: NormalRuleContributorOwner, val rule: NormalRuleDescriptor,
                                    val site: NormalRuleSite)
data class NormalRuleContributorRow(val key: NormalRuleContributorKey, val leaf: Int,
                                    val input: ConjunctionStore.Input) {
    init { require(leaf >= 0) }
}

/** Immutable previous-run input. It offers no write or executable transfer API. */
interface NormalRuleContributorView {
    val retainedRows: Long
    fun rows(key: NormalRuleContributorKey): List<NormalRuleContributorRow>
    fun allRows(): List<NormalRuleContributorRow>

    companion object {
        val EMPTY: NormalRuleContributorView = object : NormalRuleContributorView {
            override val retainedRows = 0L
            override fun rows(key: NormalRuleContributorKey) = emptyList<NormalRuleContributorRow>()
            override fun allRows() = emptyList<NormalRuleContributorRow>()
        }
    }
}

private data class NormalInputHeader(val leaf: Int, val premise: PremiseKey, val group: GroupKey)
private data class NormalContributorRoot(
    val entries: PersistentMap<NormalRuleContributorKey, PersistentMap<NormalInputHeader, NormalRuleContributorRow>> = persistentHashMapOf(),
    val size: Long = 0,
)

/** One barrier writer publishes a complete persistent-map root. Existing views
 * remain immutable even when a later publication fails or is cancelled. */
class NormalRuleContributorStore(private val manager: ApManager) {
    @Volatile private var published = NormalContributorRoot()
    val retainedRows: Long get() = published.size

    fun snapshot(): NormalRuleContributorView = Snapshot(published)

    /** Returns true for new geometry or metadata. DEMAND and unsupported modes
     * are excluded; no partially built root is visible to a reader. */
    fun publish(rows: Iterable<NormalRuleContributorRow>): Boolean {
        val previous = published
        var next = previous
        for (row in rows) {
            manager.cancellation.checkpoint()
            val input = row.input
            val facts = input.facts ?: continue
            if (row.key.owner.direction != Direction.FORWARD || row.key.owner.markMode != MarkMode.FULL ||
                input.layer != Layer.NORMAL || facts.layer != Layer.NORMAL ||
                !RuntimeDataDomain.packet(input.premise, facts)) continue
            check((facts is FlowTree) == input.premise.isFlow) { "A saved condition keeps the original conclusion kind" }
            check(input.premise !is PremiseSet || facts is TaintTree)
            val header = NormalInputHeader(row.leaf, input.premise, facts.groupKey)
            val members = next.entries[row.key] ?: persistentHashMapOf()
            val old = members[header]
            val retained = if (old == null) row else {
                val (merged, delta) = manager.mergeAddDelta(checkNotNull(old.input.facts), facts)
                if (delta == null) continue
                old.copy(input = old.input.copy(facts = merged))
            }
            next = NormalContributorRoot(next.entries.put(row.key, members.put(header, retained)),
                next.size + if (old == null) 1 else 0)
        }
        manager.cancellation.checkpoint()
        published = next
        return next !== previous
    }

    private class Snapshot(private val root: NormalContributorRoot) : NormalRuleContributorView {
        override val retainedRows get() = root.size
        override fun rows(key: NormalRuleContributorKey): List<NormalRuleContributorRow> =
            Collections.unmodifiableList(root.entries[key]?.values?.toList().orEmpty())
        override fun allRows(): List<NormalRuleContributorRow> =
            Collections.unmodifiableList(root.entries.values.flatMap { it.values })
    }
}

package org.opentaint.dataflow.bidi.store

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*

/** Current pure NORMAL STAR relations at one exact interface. The input trie fixes the
 * shared residual; packed output DAGs test its correlated counterpart without listing paths. */
internal class NormalStarRelationIndex(
    private val m: ApManager,
    private val interners: StoreInterners,
    private val emptied: (InitialAp) -> Unit = {},
) {
    private data class Header(val base: AccessPathBase, val mx: MarkExclusions)
    class Update(val fresh: List<FlowTree>, val affectedInitials: Set<InitialAp>)
    private val current = LinkedHashMap<InitialAp, LinkedHashMap<Header, FlowTree>>()
    private val byInput = PathTrie<InitialAp>(m.cancellation)

    fun supports(initial: PremiseKey, facts: Facts): Boolean = initial is InitialAp &&
        initial.manager === m && initial.isFlow && initial.mark == MarkSlot.STAR &&
        initial.tail == Tail.STAR && initial.exclusion == ExclusionSet.Empty &&
        initial.base != AccessPathBase.Zero && initial.base != STATIC && facts is FlowTree &&
        facts.layer == Layer.NORMAL && facts.tail == Tail.STAR && facts.exclusion == ExclusionSet.Empty &&
        facts.base != AccessPathBase.Zero && facts.base != STATIC

    private fun append(root: FlowNode, residual: IntArray): FlowNode {
        if (residual.isEmpty()) return root
        val suffix = FlowAlgebra.prepend(m, m.path(residual.asList()), FlowAlgebra.LEAF_NODE)
        return checkNotNull(FlowAlgebra.graft(root, { it == FlowLeaf.LEAF }, suffix, m.cancellation))
    }

    private fun canonical(rows: Iterable<FlowTree>): LinkedHashMap<Header, FlowTree> {
        // FlowGroup owns one output base, as in ConclusionGroup. An input can
        // independently return, preserve an argument, and update a local.
        val groups = LinkedHashMap<AccessPathBase, FlowGroup>()
        for (row in rows) groups.getOrPut(row.base) { FlowGroup(m, interners.flow) }.addAll(row)
        return groups.values.asSequence().flatMap { it.all() }
            .associateByTo(LinkedHashMap()) { Header(it.base, it.markExclusion) }
    }

    private fun replace(initial: InitialAp, rows: LinkedHashMap<Header, FlowTree>, affected: MutableSet<InitialAp>) {
        if (current[initial] == rows || (current[initial] == null && rows.isEmpty())) return
        affected += initial
        if (rows.isEmpty()) {
            current.remove(initial)
            byInput.remove(initial.base, initial.pathData, initial)
            emptied(initial)
        } else {
            if (!current.containsKey(initial)) byInput.add(initial.base, initial.pathData, initial)
            current[initial] = rows
        }
    }

    fun add(initial: InitialAp, offered: FlowTree): Update {
        require(supports(initial, offered))
        val previous = current[initial]?.toMap().orEmpty()
        var rows = canonical(previous.values + offered)
        // Preserve native same-input T2/mx coalescing before cross-input cover.
        // A changed header can expose another exact-header ancestor; settle locally.
        while (true) {
            val filtered = ArrayList<FlowTree>()
            for ((header, value) in rows) {
                var root: FlowNode? = value.root
                for (short in byInput.lookupPrefixes(initial.base, initial.pathData)) {
                    if (short === initial) continue
                    val residual = initial.pathData.copyOfRange(short.pathData.size, initial.pathData.size)
                    for (cover in current.getValue(short).values) {
                        if (cover.base != value.base || !cover.markExclusion.isSubsetOf(value.markExclusion)) continue
                        root = root?.let { FlowAlgebra.minusNode(it, append(cover.root, residual), m.cancellation) }
                        if (root == null) break
                    }
                    if (root == null) break
                }
                root?.let { filtered += value.withRoot(it) }
            }
            val next = canonical(filtered)
            if (next == rows) break
            rows = next
        }
        val affected = LinkedHashSet<InitialAp>()
        replace(initial, rows, affected)
        val pending = java.util.ArrayDeque<InitialAp>()
        if (affected.isNotEmpty() && rows.isNotEmpty()) pending.add(initial)
        while (pending.isNotEmpty()) {
            m.cancellation.checkpoint()
            val short = pending.removeFirst()
            val covers = current[short] ?: continue
            for (long in byInput.lookupExtensions(short.base, short.pathData)) {
                if (long === short) continue
                val old = current.getValue(long)
                val residual = long.pathData.copyOfRange(short.pathData.size, long.pathData.size)
                val remaining = ArrayList<FlowTree>()
                for ((header, value) in old) {
                    var root: FlowNode? = value.root
                    for (cover in covers.values) {
                        if (cover.base != value.base || !cover.markExclusion.isSubsetOf(value.markExclusion)) continue
                        root = root?.let { FlowAlgebra.minusNode(it, append(cover.root, residual), m.cancellation) }
                        if (root == null) break
                    }
                    root?.let { remaining += value.withRoot(it) }
                }
                val next = canonical(remaining)
                if (next != old) {
                    replace(long, next, affected)
                    if (next.isNotEmpty()) pending.add(long)
                }
            }
        }
        val fresh = ArrayList<FlowTree>()
        for ((header, value) in current[initial].orEmpty()) {
            val old = previous[header]
            val root = if (old == null) value.root else FlowAlgebra.minusNode(value.root, old.root, m.cancellation)
            root?.let { fresh += value.withRoot(it) }
        }
        return Update(fresh, affected)
    }

    fun all(): Sequence<Pair<InitialAp, FlowTree>> = sequence {
        for ((initial, headers) in current) for (facts in headers.values) {
            m.cancellation.checkpoint(); yield(initial to facts)
        }
    }

    fun borrowExact(initial: PremiseKey): Sequence<FlowTree> = current[initial]?.values?.asSequence() ?: emptySequence()

    /** Current-coordinate intersection of a detached publication; no historical payload. */
    fun retainCurrent(initial: InitialAp, offered: FlowTree): FlowTree? {
        if (!supports(initial, offered)) return offered
        val kept = current[initial]?.get(Header(offered.base, offered.markExclusion)) ?: return null
        val removed = FlowAlgebra.minusNode(offered.root, kept.root, m.cancellation) ?: return offered
        val root = FlowAlgebra.minusNode(offered.root, removed, m.cancellation) ?: return null
        return offered.withRoot(root)
    }

    /** Stronger transient S specializations for existing marked-compaction rules.
     * Grafting preserves DAG sharing and creates no hypothetical InitialAp. */
    fun visitSpecializedCovers(shape: InitialAp, emit: (FlowTree) -> Unit) {
        if (shape.tail != Tail.STAR || shape.exclusion != ExclusionSet.Empty || shape.mark != MarkSlot.STAR) return
        val input = shape.pathData
        for (short in byInput.lookupPrefixes(shape.base, input)) {
            m.cancellation.checkpoint()
            val residual = input.copyOfRange(short.pathData.size, input.size)
            for (header in current.getValue(short).values) emit(header.withRoot(append(header.root, residual)))
        }
    }
}

package org.opentaint.dataflow.bidi.store

import it.unimi.dsi.fastutil.ints.Int2ObjectOpenHashMap
import it.unimi.dsi.fastutil.ints.IntArrayList
import it.unimi.dsi.fastutil.ints.IntOpenHashSet
import it.unimi.dsi.fastutil.longs.LongArrayList
import it.unimi.dsi.fastutil.longs.LongOpenHashSet
import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*

/** Slots, including the real control ZERO mark, are distinct from nullable data endpoints. */
internal object BoundaryMarkCodec {
    fun pack(from: MarkSlot, to: MarkSlot): Long {
        if (from is MarkSlot.Star && to is MarkSlot.Star) return 0L
        check(from is MarkSlot.Concrete && to is MarkSlot.Concrete) {
            "A colored guidance row needs concrete endpoints; FLOW is diagonal"
        }
        val input = from.mark.id.toLong() + 1L
        val output = to.mark.id.toLong() + 1L
        return (input shl 32) or (output and 0xffffffffL)
    }
    fun input(label: Long): MarkSlot = if (label == 0L) MarkSlot.STAR
        else MarkSlot.Concrete(TaintMark((label ushr 32).toInt() - 1))
    fun output(label: Long): MarkSlot = if (label == 0L) MarkSlot.STAR
        else MarkSlot.Concrete(TaintMark(label.toInt() - 1))
    fun relation(geometry: GuidanceGeometry, label: Long): GuidanceMarks = if (label == 0L) GuidanceMarks.Flow else
        GuidanceMarks.Mapped(
            if (geometry.from.fact.base == AccessPathBase.Zero) null else (input(label) as MarkSlot.Concrete).mark,
            if (geometry.to.fact.base == AccessPathBase.Zero) null else (output(label) as MarkSlot.Concrete).mark)
}

/** Detached immutable metadata. A mark hole is installed after guidance normalization only. */
internal class PackedGuidanceCatalog private constructor(
    private val endpoints: Array<Pattern>,
    private val geometries: Array<GuidanceGeometry>,
) {
    val endpointCount: Int get() = endpoints.size
    val geometryCount: Int get() = geometries.size
    fun endpoint(id: Int): Pattern = endpoints[id]
    fun geometry(id: Int): GuidanceGeometry = geometries[id]

    class Builder {
        private var endpointIds = HashMap<Pattern, Int>()
        private val endpoints = ArrayList<Pattern>()
        private var geometryIds = HashMap<GuidanceGeometry, Int>()
        private val geometries = ArrayList<GuidanceGeometry>()
        private var indexed = true
        private fun ensureIndexes() {
            if (indexed) return
            for ((id, endpoint) in endpoints.withIndex()) endpointIds[endpoint] = id
            for ((id, geometry) in geometries.withIndex()) geometryIds[geometry] = id
            indexed = true
        }
        fun endpoint(normalized: Pattern): Int {
            ensureIndexes()
            val geometry = normalized.copy(fact = normalized.fact.copy(mark = MarkSlot.STAR))
            return endpointIds.getOrPut(geometry) { endpoints.size.also { endpoints += geometry } }
        }
        fun geometry(from: Pattern, to: Pattern): Int {
            val key = GuidanceGeometry(endpoints[endpoint(from)], endpoints[endpoint(to)])
            return geometryIds.getOrPut(key) { geometries.size.also { geometries += key } }
        }
        fun freeze(): PackedGuidanceCatalog = PackedGuidanceCatalog(endpoints.toTypedArray(), geometries.toTypedArray()).also {
            // The frozen catalog never points back to a builder or a live store.
            endpointIds = HashMap()
            geometryIds = HashMap()
            indexed = false
        }
    }
}

/** One exact owner/family's old local row ordinals, with primitive paired labels. */
internal class PackedGuidanceRows private constructor(
    private val catalog: PackedGuidanceCatalog,
    private val geometryIds: IntArray,
    private val labels: LongArray,
) {
    val size: Int get() = geometryIds.size
    fun geometry(id: Int): GuidanceGeometry = catalog.geometry(geometryIds[id])
    fun marks(id: Int): GuidanceMarks = BoundaryMarkCodec.relation(geometry(id), labels[id])
    fun isFlow(id: Int): Boolean = labels[id] == 0L
    fun from(id: Int): Pattern = geometry(id).from.withSlot(BoundaryMarkCodec.input(labels[id]))
    fun to(id: Int): Pattern = geometry(id).to.withSlot(BoundaryMarkCodec.output(labels[id]))
    fun outputMark(id: Int): TaintMark? = (BoundaryMarkCodec.output(labels[id]) as? MarkSlot.Concrete)?.mark
    fun edge(id: Int): StaticGuidanceEdge = StaticGuidanceEdge(from(id), to(id), marks(id))
    fun keptEdge(id: Int, keep: StaticCandidateFilter?): StaticGuidanceEdge? {
        val from = from(id)
        val to = to(id)
        val marks = marks(id)
        return if (keep == null || keep.keep(from, to, marks)) StaticGuidanceEdge(from, to, marks) else null
    }

    class Builder(private val catalog: PackedGuidanceCatalog.Builder) {
        private val geometries = IntArrayList()
        private val labels = LongArrayList()
        private var seen = Int2ObjectOpenHashMap<LongOpenHashSet>()
        private val projected = PackedEndpointRows.Builder(catalog)
        private var indexed = true
        private fun seenLabels(geometry: Int): LongOpenHashSet =
            seen.get(geometry) ?: LongOpenHashSet().also { seen.put(geometry, it) }
        val size: Int get() = geometries.size
        fun add(from: Pattern, to: Pattern) {
            if (!indexed) {
                for (id in 0 until geometries.size) seenLabels(geometries.getInt(id)).add(labels.getLong(id))
                indexed = true
            }
            val a = guidancePattern(from)
            val b = guidancePattern(to)
            val label = BoundaryMarkCodec.pack(a.fact.mark, b.fact.mark)
            val geometry = catalog.geometry(a, b)
            if (!seenLabels(geometry).add(label)) return
            geometries.add(geometry)
            labels.add(label)
            projected.add(b)
        }
        fun freezeEntries(catalog: PackedGuidanceCatalog): PackedEndpointRows = projected.freeze(catalog)
        fun freeze(catalog: PackedGuidanceCatalog): PackedGuidanceRows =
            PackedGuidanceRows(catalog, geometries.toIntArray(), labels.toLongArray()).also {
                seen = Int2ObjectOpenHashMap(); indexed = false
            }
    }
}

/** Entry directories read fields, so building an index does not decode every row. */
internal interface StaticEndpointRows {
    val size: Int
    fun geometry(id: Int): Pattern
    fun pattern(id: Int): Pattern
    fun marks(id: Int): GuidanceMarks
}

/** Primitive terminal memberships and primitive projected W/R entry memberships. */
internal class PackedEndpointRows private constructor(
    private val catalog: PackedGuidanceCatalog,
    private val geometryIds: IntArray,
    private val markIds: IntArray,
) : StaticEndpointRows {
    override val size: Int get() = geometryIds.size
    override fun geometry(id: Int): Pattern = catalog.endpoint(geometryIds[id])
    override fun pattern(id: Int): Pattern = geometry(id).withSlot(
        if (markIds[id] == FLOW_MARK) MarkSlot.STAR else MarkSlot.Concrete(TaintMark(markIds[id])))
    override fun marks(id: Int): GuidanceMarks = if (markIds[id] == FLOW_MARK) GuidanceMarks.Flow else
        GuidanceMarks.Mapped(null, if (geometry(id).fact.base == AccessPathBase.Zero) null else TaintMark(markIds[id]))
    fun patterns(): Sequence<Pattern> = sequence { for (id in geometryIds.indices) yield(pattern(id)) }

    class Builder(private val catalog: PackedGuidanceCatalog.Builder) {
        private val geometries = IntArrayList()
        private val marks = IntArrayList()
        private var seen = Int2ObjectOpenHashMap<IntOpenHashSet>()
        private var indexed = true
        private fun seenMarks(geometry: Int): IntOpenHashSet =
            seen.get(geometry) ?: IntOpenHashSet().also { seen.put(geometry, it) }
        val size: Int get() = geometries.size
        fun add(normalized: Pattern) {
            if (!indexed) {
                for (id in 0 until geometries.size) seenMarks(geometries.getInt(id)).add(marks.getInt(id))
                indexed = true
            }
            val id = catalog.endpoint(normalized)
            val mark = when (val slot = normalized.fact.mark) {
                is MarkSlot.Star -> FLOW_MARK
                is MarkSlot.Concrete -> slot.mark.id
            }
            if (!seenMarks(id).add(mark)) return
            geometries.add(id)
            marks.add(mark)
        }
        fun freeze(catalog: PackedGuidanceCatalog): PackedEndpointRows =
            PackedEndpointRows(catalog,geometries.toIntArray(),marks.toIntArray()).also {
                seen = Int2ObjectOpenHashMap(); indexed = false
            }
    }
    companion object { private const val FLOW_MARK = -1 }
}

private fun Pattern.withSlot(mark: MarkSlot): Pattern =
    if (fact.mark == mark) this else copy(fact = fact.copy(mark = mark))

package org.opentaint.dataflow.bidi.store

import it.unimi.dsi.fastutil.ints.Int2ObjectOpenHashMap
import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.walkPath
import org.opentaint.dataflow.util.Cancellation

/** Single-writer positional index. A value at two positions remains two entries. */
class PathTrie<V : Any>(private val cancellation: Cancellation? = null) {
    private class Node<V : Any> {
        val values = LinkedHashSet<V>(2)
        var children: Int2ObjectOpenHashMap<Node<V>>? = null
        fun child(accessor: Int): Node<V>? = children?.get(accessor)
        fun getOrCreate(accessor: Int): Node<V> {
            val map = children ?: Int2ObjectOpenHashMap<Node<V>>().also { children = it }
            return map.getOrPut(accessor) { Node() }
        }
    }
    private val roots = HashMap<AccessPathBase, Node<V>>(4)

    fun add(base: AccessPathBase, path: IntArray, value: V): Boolean {
        cancellation?.checkpoint()
        var node = roots.getOrPut(base) { Node() }
        for (accessor in path) {
            cancellation?.checkpoint()
            node = node.getOrCreate(accessor)
        }
        return node.values.add(value)
    }

    /** Remove one current posting and release empty path nodes on the owning writer. */
    fun remove(base: AccessPathBase, path: IntArray, value: V): Boolean {
        cancellation?.checkpoint()
        val root = roots[base] ?: return false
        val spine = ArrayList<Node<V>>(path.size + 1)
        spine += root
        var node = root
        for (accessor in path) {
            cancellation?.checkpoint()
            node = node.child(accessor) ?: return false
            spine += node
        }
        if (!node.values.remove(value)) return false
        for (index in path.indices.reversed()) {
            val child = spine[index + 1]
            if (child.values.isNotEmpty() || child.children?.isNotEmpty() == true) break
            val parent = spine[index]
            parent.children?.remove(path[index])
            if (parent.children?.isEmpty() == true) parent.children = null
        }
        if (root.values.isEmpty() && root.children == null) roots.remove(base)
        return true
    }

    fun lookupPrefixes(base: AccessPathBase, path: IntArray): MutableList<V> {
        cancellation?.checkpoint()
        val out = ArrayList<V>()
        val root = roots[base] ?: return out
        walkPath(root, path, Node<V>::child) { _, node ->
            cancellation?.checkpoint()
            out += node.values
        }?.let { out += it.values }
        return out
    }

    fun lookupExtensions(base: AccessPathBase, path: IntArray): List<V> {
        cancellation?.checkpoint()
        val out = ArrayList<V>()
        find(base, path)?.let { collect(it, out, self = true) }
        return out
    }

    fun around(base: AccessPathBase, path: IntArray): List<V> =
        lookupPrefixes(base, path).also { out -> find(base, path)?.let { collect(it, out, self = false) } }

    /** Finite owner-local visit; the callback must not mutate this index or its owning directory. */
    fun visitAround(base: AccessPathBase, path: IntArray, visit: (V) -> Unit) {
        visitAroundWhile(base, path) { visit(it); true }
    }

    /** A read-only query can stop at its first witness without allocating a candidate list. */
    fun visitAroundWhile(base: AccessPathBase, path: IntArray, visit: (V) -> Boolean): Boolean {
        cancellation?.checkpoint()
        var node = roots[base] ?: return true
        fun values(at: Node<V>): Boolean {
            for (value in at.values) {
                cancellation?.checkpoint()
                if (!visit(value)) return false
            }
            return true
        }
        for (accessor in path) {
            cancellation?.checkpoint()
            if (!values(node)) return false
            node = node.child(accessor) ?: return true
        }
        val stack = ArrayDeque<Node<V>>()
        stack.addLast(node)
        while (stack.isNotEmpty()) {
            cancellation?.checkpoint()
            val at = stack.removeLast()
            if (!values(at)) return false
            at.children?.values?.forEach {
                cancellation?.checkpoint()
                stack.addLast(it)
            }
        }
        return true
    }

    fun all(): Sequence<V> = sequence {
        cancellation?.checkpoint()
        for (root in roots.values) {
            val out = ArrayList<V>()
            collect(root, out, self = true)
            for (value in out) {
                cancellation?.checkpoint()
                yield(value)
            }
        }
    }

    private fun find(base: AccessPathBase, path: IntArray): Node<V>? {
        cancellation?.checkpoint()
        return roots[base]?.let { root ->
            walkPath(root, path, Node<V>::child) { _, _ -> cancellation?.checkpoint() }
        }
    }

    private fun collect(node: Node<V>, out: MutableList<V>, self: Boolean) {
        cancellation?.checkpoint()
        val stack = ArrayDeque<Node<V>>()
        if (self) out += node.values
        node.children?.values?.let(stack::addAll)
        while (stack.isNotEmpty()) {
            cancellation?.checkpoint()
            val next = stack.removeLast()
            out += next.values
            next.children?.values?.let(stack::addAll)
        }
    }
}

package org.opentaint.dataflow.bidi.store

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.graph.PortId

/** Private capability; unknown views and unsupported cells use native C5. */
internal interface PreparedScopeDemandView : ScopeDemandView {
    fun prepareDataPlan(exit: PortId, templates: List<Pattern>, policy: RestrictedInitialPolicy,
                        onEntryCheck: () -> Unit = {}): PreparedLocalDataPlan?
}

internal interface PreparedLocalDataPlan {
    val rowChecks: Int
    /** Immutable executable program count; rejected rows are not programs. */
    val outputProgramCount: Int
    fun intersect(original: PremiseKey, raw: Facts): List<Facts>?
    fun emptyForBase(base: AccessPathBase): Boolean
}

/** Match the exact native summary normalization without interning an initial. */
internal fun normalizedOriginalTemplates(original: PremiseKey, flow: Boolean): List<Pattern> =
    original.members.map { member ->
        val pattern = member.toPattern()
        if (flow && member.isFlow && pattern.fact.tail == Tail.EXACT)
            pattern.copy(fact = pattern.fact.copy(tail = Tail.STAR)) else pattern
    }

package org.opentaint.dataflow.bidi.store

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*

internal data class OutputProgramKey(val fullExit: Pattern, val fieldBudget: Int)

/** The representative is a capability obtained after one exact paired entry check. */
internal class OutputProgram(
    val ordinal: Int,
    val key: OutputProgramKey,
    val representative: AcceptedEntryOutput,
)

/** Immutable within one exact normalized whole-original/scope/policy query. */
internal class PreparedOutputPrograms private constructor(
    private val ap: ApManager,
    private val method: MethodKey,
    private val templates: List<Pattern>,
    private val programs: List<OutputProgram>,
    private val outputs: FrozenDemandTrie<Int>,
    override val rowChecks: Int,
    private val statistics: DemandQueryStatistics?,
) : PreparedLocalDataPlan {
    override val outputProgramCount: Int get() = programs.size
    override fun emptyForBase(base: AccessPathBase): Boolean = !outputs.hasBase(base)

    override fun intersect(original: PremiseKey, raw: Facts): List<Facts>? {
        ap.cancellation.checkpoint()
        if (raw is Reach || original.isZero || original.members.map { it.toPattern() } != templates) return null
        if (!RuntimeDataDomain.packet(original, raw)) return emptyList()
        statistics?.preparedQuery()
        if (!outputs.hasBase(raw.base)) return emptyList()
        val ops = ApOps(ap)
        val buckets = arrayOfNulls<ProgramBucket>(programs.size)
        var references = 0
        var overflow = false
        forEachDemandScalar(ops, raw, statistics) { protected, scalar ->
            if (!overflow) outputs.visitNativeOrder(Pattern(scalar.fact, scalar.exclusion),
                DemandQueryKind.OUTPUT_C5, ap.marks) { ordinal ->
                if (!overflow) {
                    ap.cancellation.checkpoint()
                    statistics?.candidate()
                    val program = programs[ordinal]
                    val selected = restrictConclusionOnly(scalar, program.representative.fullExit, ap.marks)
                    if (selected != null) {
                        val bucket = buckets[ordinal] ?: ProgramBucket().also { buckets[ordinal] = it }
                        val selections = if (protected) bucket.protectedSelections else bucket.ordinarySelections
                        if (selections.add(selected)) {
                            references++
                            statistics?.selectedReference(references)
                            if (references > MAX_SELECTED_REFERENCES) {
                                overflow = true
                                statistics?.overflow()
                            }
                        }
                    }
                }
            }
            !overflow
        }
        // No partial output escapes an oversized pure query. Native C5 recomputes it.
        if (overflow) return null
        val result = ExactDemandResults(ap)
        for (program in programs) {
            ap.cancellation.checkpoint()
            statistics?.add(7)
            statistics?.add(9)
            statistics?.dataRow(raw, program.key.fullExit, program.key.fieldBudget, route = 0)
            val sample = statistics?.samplePreparedRow(method, program.representative.initial,
                raw, program.representative.pair, program.key.fieldBudget, route = 0)
            val bucket = buckets[program.ordinal]
            if (bucket == null) {
                statistics?.rejectedRow()
                statistics?.sampleResult(sample, null, null)
                continue
            }
            for (packet in packProgramStreams(ops, bucket, statistics)) {
                statistics?.selected(packet, program.key.fieldBudget)
                ops.limit(packet, program.key.fieldBudget, object : ApOut {
                    override fun result(f: Facts) {
                        statistics?.limited(packet, f)
                        statistics?.sampleResult(sample, packet, f)
                        result.add(f)
                    }
                    override fun markRequest(mark: TaintMark) = error("A field cut must not emit a mark request")
                })
            }
        }
        return result.all()
    }

    class Builder(private val ap: ApManager, private val method: MethodKey, private val templates: List<Pattern>,
                  private val policy: RestrictedInitialPolicy,
                  private val statistics: DemandQueryStatistics?) {
        private val programs = LinkedHashMap<OutputProgramKey, OutputProgram>()
        private var checks = 0
        private var accepted = 0

        /** Call for every native member/prefix/row occurrence, including rejected rows. */
        fun offer(ticket: EntryRestrictionTicket?) {
            checks++
            if (ticket == null) return
            accepted++
            val output = ticket.acceptedOutput() ?: return
            val depth = output.fullExit.fact.path.count { it.isCounted() }
            val global = policy.fieldLimit
            check(global >= 1)
            val key = OutputProgramKey(output.fullExit, if (depth >= global) global else depth + 1)
            programs.getOrPut(key) { OutputProgram(programs.size, key, output) }
        }

        fun build(): PreparedOutputPrograms {
            val outputs = FrozenDemandTrie.Builder<Int>(ap.cancellation)
            for (program in programs.values) outputs.add(program.key.fullExit, program.ordinal)
            statistics?.preparedPlan(checks, accepted, programs.size)
            return PreparedOutputPrograms(ap, method, templates.toList(), programs.values.toList(),
                outputs.build(), checks, statistics)
        }
    }

    companion object {
        internal const val MAX_SELECTED_REFERENCES = 2048
    }
}

package org.opentaint.dataflow.bidi.store

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.graph.PortId
import org.opentaint.dataflow.graph.BlockId

/** An admitted normal singleton summary, retained in the direction in which it was derived. */
class Record(
    val method: MethodKey,
    val direction: Direction,
    val premise: InitialAp,
    val conclusion: Facts,
    val scope: BlockScope? = null,
    val exit: PortId? = null,
) {
    init { require((scope == null) == (exit == null)) { "A scoped native record keeps both control ports" } }

    /** AP reversal is below; reverse the control ports independently. */
    fun scopeIn(direction: Direction): BlockScope? = scope?.let {
        if (direction == this.direction) it else BlockScope(it.block, checkNotNull(exit))
    }
    fun exitIn(direction: Direction): PortId? = scope?.let {
        if (direction == this.direction) exit else it.entry
    }
    /** Transient opposite-direction reads retain their actual premise and result layer. */
    private fun nativeReversedLeavesAt(a: Pattern): Sequence<Pair<NativeReverseRead, Boolean>> = sequence {
        val m = premise.manager
        m.cancellation.checkpoint()
        if (!RuntimeDataDomain.packet(premise, conclusion) || !RuntimeDataDomain.base(a.fact.base)) return@sequence
        check(conclusion.layer == Layer.NORMAL) { "Only a normal native record has reversed views" }
        val nativePremise = premise.toPattern()
        for (leaf in ApOps(m).leaves(conclusion)) {
            m.cancellation.checkpoint()
            if (leaf.fact.base != a.fact.base ||
                !(leaf.fact.path.startsWith(a.fact.path) || a.fact.path.startsWith(leaf.fact.path))) continue
            reverseNativeOne(leaf, nativePremise)?.let { yield(it) }
        }
    }

    /** Metadata is an invocation annotation, not part of RecordLeafView equality. */
    fun forEachReversedAt(a: Pattern, emit: (RecordLeafView, Boolean) -> Unit) {
        forEachNativeReversedAt(a) { read, protected -> emit(read.view, protected) }
    }

    fun forEachNativeReversedAt(a: Pattern, emit: (NativeReverseRead, Boolean) -> Unit) {
        for ((read, protected) in nativeReversedLeavesAt(a)) emit(read, protected)
    }

    /** Read-only geometry view for diagnostic and reference clients. */
    fun reversedAt(a: Pattern): Sequence<RecordLeafView> = nativeReversedLeavesAt(a).map { it.first.view }

    internal fun reverseOne(leaf: Pattern, nativePremise: Pattern): Pair<RecordLeafView, Boolean>? {
        return reverseNativeOne(leaf, nativePremise)?.let { it.first.view to it.second }
    }

    internal fun reverseNativeOne(leaf: Pattern, nativePremise: Pattern): Pair<NativeReverseRead, Boolean>? {
        val m = premise.manager
        val view = reverseNativeRecordLeaf(direction, nativePremise, Conclusion(leaf.fact, leaf.exclusion, demand = false))
            ?: return null
        var at: TaintNode? = (conclusion as? TaintTree)?.nonSubsumable
        for (accessor in leaf.fact.path) { m.cancellation.checkpoint(); at = at?.child(accessor) }
        val atom = (leaf.fact.mark as? MarkSlot.Concrete)?.mark
        val protected = atom != null && at?.leaf?.let {
            atom in if (leaf.fact.tail == Tail.EXACT) it.exact else it.any
        } == true
        return view to protected
    }
}

/** One actual output position, not a full-mark posting. Record identity is unchanged. */
class RecordOutputPosition internal constructor(val record: Record, private val node: PathNode?, val ordinal: Int) {
    val path: List<Int> get() = node?.toList() ?: emptyList()
    fun forEachReversedAt(actual: Pattern, emit: (RecordLeafView, Boolean) -> Unit) {
        forEachNativeReversedAt(actual) { read, protected -> emit(read.view, protected) }
    }
    fun forEachNativeReversedAt(actual: Pattern, emit: (NativeReverseRead, Boolean) -> Unit) {
        val m = record.premise.manager
        m.cancellation.checkpoint()
        if (!RuntimeDataDomain.packet(record.premise, record.conclusion) || actual.fact.base != record.conclusion.base) return
        val p = path
        if (!(p.startsWith(actual.fact.path) || actual.fact.path.startsWith(p))) return
        check(record.conclusion.layer == Layer.NORMAL)
        val nativePremise = record.premise.toPattern()
        fun offer(pattern: Pattern) { record.reverseNativeOne(pattern, nativePremise)?.let { (view, protected) -> emit(view, protected) } }
        when (val value = record.conclusion) {
            is Reach -> if (p.isEmpty()) offer(m.zero.toPattern())
            is FlowTree -> {
                var at: FlowNode? = value.root
                for (accessor in p) { m.cancellation.checkpoint(); at = at?.child(accessor) }
                if (at?.leaf?.isEmpty == false)
                    offer(Pattern(PathFact(value.base, p, value.tail, MarkSlot.Star(value.markExclusion)), value.exclusion))
            }
            is TaintTree -> {
                var at: TaintNode? = value.root
                for (accessor in p) { m.cancellation.checkpoint(); at = at?.child(accessor) }
                val leaf = at?.leaf ?: return
                for (id in leaf.exact.data) {
                    m.cancellation.checkpoint()
                    offer(Pattern(PathFact(value.base, p, Tail.EXACT, MarkSlot.Concrete(TaintMark(id))), ExclusionSet.Empty))
                }
                for (id in leaf.any.data) {
                    m.cancellation.checkpoint()
                    offer(Pattern(PathFact(value.base, p, value.anyTail, MarkSlot.Concrete(TaintMark(id))), value.exclusion))
                }
            }
        }
    }
    override fun equals(other: Any?): Boolean = other is RecordOutputPosition && record === other.record && ordinal == other.ordinal
    override fun hashCode(): Int = 31 * System.identityHashCode(record) + ordinal
}

/** Persistent native records. A run obtains a view that permits reads only. */
interface RecordStore {
    fun add(record: Record)
    fun byEntry(method: MethodKey, addedFact: Pattern): Sequence<Record>
    fun byExit(method: MethodKey, fact: Pattern): Sequence<Record>
    fun byEntry(method: MethodKey, scope: BlockScope, addedFact: Pattern): Sequence<Record> = emptySequence()
    fun byExit(method: MethodKey, scope: BlockScope, fact: Pattern): Sequence<Record> = emptySequence()
    fun byExitPositions(method: MethodKey, scope: BlockScope, fact: Pattern): List<RecordOutputPosition>? = null
    fun view(): RecordStore
    fun persist(direction: Direction, summaries: Sequence<Pair<MethodKey, RunSummaryStore>>)
    fun persistScoped(direction: Direction, summaries: Sequence<ScopedRunSummary>) {
        check(!summaries.iterator().hasNext()) { "This record store does not support scoped persistence" }
    }
    fun persistCompleted(direction: Direction, summaries: Sequence<Pair<MethodKey, RunSummaryStore>>,
                         scoped: Sequence<ScopedRunSummary>) {
        persist(direction, summaries)
        persistScoped(direction, scoped)
    }
}

data class ScopedRunSummary(val key: ScopedSummaryKey, val summaries: RunSummaryStore)

/** The driver writes only at a barrier; the next run reads the published indexes. */
class PersistentRecordStore(private val m: ApManager) : RecordStore {
    private data class Owner(val method: MethodKey, val direction: Direction,
                             val scope: BlockScope?, val exit: PortId?)
    private data class ScopedIndexKey(val method: MethodKey, val block: BlockId, val port: PortId)
    private data class Signature(val owner: Owner, val initial: InitialAp, val facts: Facts,
                                 val protection: TaintNode?)
    private class Indexes {
        val entry = HashMap<MethodKey, PathTrie<Record>>()
        val exit = HashMap<MethodKey, PathTrie<RecordOutputPosition>>()
        val scopedEntry = HashMap<ScopedIndexKey, PathTrie<Record>>()
        val scopedExit = HashMap<ScopedIndexKey, PathTrie<RecordOutputPosition>>()
        val records = HashMap<Signature, Record>()
    }
    private class State(val current: LinkedHashMap<Owner, RunSummaryStore>, val indexes: Indexes)
    private var state = State(LinkedHashMap(), Indexes())
    private val current get() = state.current
    private val indexes get() = state.indexes

    private fun signature(owner: Owner, initial: InitialAp, facts: Facts) =
        Signature(owner, initial, facts, (facts as? TaintTree)?.nonSubsumable)

    private fun ingest(owner: Owner, premise: InitialAp, facts: Facts,
                       staged: MutableMap<Owner, RunSummaryStore>, copied: MutableSet<Owner>): Boolean {
        m.cancellation.checkpoint()
        if (!RuntimeDataDomain.packet(premise, facts)) return false
        checkNativeRecord(owner.direction, premise, facts)
        if (copied.add(owner)) {
            val replacement = RunSummaryStore(m)
            for ((initial, value) in current[owner]?.all() ?: emptySequence())
                replacement.addAdmittedAll(initial, value)
            staged[owner] = replacement
        }
        return staged.getValue(owner).addAdmittedAll(premise, facts).isNotEmpty()
    }

    private fun mutation(supplied: Map<Signature, Record> = emptyMap(),
                         body: (MutableMap<Owner, RunSummaryStore>, MutableSet<Owner>) -> Boolean) {
        m.cancellation.checkpoint()
        val staged = LinkedHashMap(current)
        if (!body(staged, HashSet())) return
        val next = rebuild(staged, supplied)
        m.cancellation.checkpoint()
        state = State(staged, next)
    }

    override fun add(record: Record) {
        val owner = Owner(record.method, record.direction, record.scope, record.exit)
        mutation(mapOf(signature(owner, record.premise, record.conclusion) to record)) { staged, copied ->
            ingest(owner, record.premise, record.conclusion, staged, copied)
        }
    }

    /** Build a complete current directory; old delta Records cease to be authoritative. */
    private fun rebuild(staged: Map<Owner, RunSummaryStore>, supplied: Map<Signature, Record>): Indexes {
        val old = indexes
        val next = Indexes()
        for ((owner, store) in staged) for ((premise, facts) in store.all()) {
            m.cancellation.checkpoint()
            val initial = premise as InitialAp
            val key = signature(owner, initial, facts)
            val record = old.records[key] ?: supplied[key] ?:
                Record(owner.method, owner.direction, initial, facts, owner.scope, owner.exit)
            next.records[key] = record
            val input = if (owner.scope == null)
                next.entry.getOrPut(owner.method) { PathTrie(m.cancellation) }
            else next.scopedEntry.getOrPut(ScopedIndexKey(owner.method, owner.scope.block, owner.scope.entry)) {
                PathTrie(m.cancellation)
            }
            input.add(initial.base, initial.pathData, record)
            val output = if (owner.scope == null)
                next.exit.getOrPut(owner.method) { PathTrie(m.cancellation) }
            else next.scopedExit.getOrPut(ScopedIndexKey(owner.method, owner.scope.block, checkNotNull(owner.exit))) {
                PathTrie(m.cancellation)
            }
            var ordinal = 0
            m.forEachLeafPosition(facts) { base, path ->
                output.add(base, path, RecordOutputPosition(record, m.path(path.asList()), ordinal++))
            }
        }
        return next
    }

    override fun byEntry(method: MethodKey, addedFact: Pattern): Sequence<Record> = sequence {
        m.cancellation.checkpoint()
        if (!RuntimeDataDomain.base(addedFact.fact.base)) return@sequence
        for (record in indexes.entry[method]?.around(addedFact.fact.base, addedFact.fact.path.toIntArray()).orEmpty()) {
            m.cancellation.checkpoint()
            yield(record)
        }
    }

    override fun byExit(method: MethodKey, fact: Pattern): Sequence<Record> = sequence {
        m.cancellation.checkpoint()
        if (!RuntimeDataDomain.base(fact.fact.base)) return@sequence
        val seen = HashSet<Record>()
        for (position in indexes.exit[method]?.around(fact.fact.base, fact.fact.path.toIntArray()).orEmpty()) {
            m.cancellation.checkpoint()
            if (seen.add(position.record)) yield(position.record)
        }
    }

    override fun byEntry(method: MethodKey, scope: BlockScope, addedFact: Pattern): Sequence<Record> =
        scopedCandidates(indexes.scopedEntry[ScopedIndexKey(method, scope.block, scope.entry)], addedFact)

    override fun byExit(method: MethodKey, scope: BlockScope, fact: Pattern): Sequence<Record> = sequence {
        val seen = HashSet<Record>()
        for (position in byExitPositions(method, scope, fact)) if (seen.add(position.record)) yield(position.record)
    }

    override fun byExitPositions(method: MethodKey, scope: BlockScope, fact: Pattern): List<RecordOutputPosition> {
        m.cancellation.checkpoint()
        if (!RuntimeDataDomain.base(fact.fact.base)) return emptyList()
        return indexes.scopedExit[ScopedIndexKey(method, scope.block, scope.entry)]
            ?.around(fact.fact.base, fact.fact.path.toIntArray()).orEmpty()
    }

    private fun scopedCandidates(index: PathTrie<Record>?, fact: Pattern): Sequence<Record> = sequence {
        m.cancellation.checkpoint()
        if (!RuntimeDataDomain.base(fact.fact.base)) return@sequence
        val seen = HashSet<Record>()
        for (record in index?.around(fact.fact.base, fact.fact.path.toIntArray()).orEmpty()) {
            m.cancellation.checkpoint()
            if (seen.add(record)) yield(record)
        }
    }

    override fun view(): RecordStore = object : RecordStore by this {
        override fun add(record: Record) = error("Read-only during a run (analyzer-core.md A4)")
        override fun persist(direction: Direction, summaries: Sequence<Pair<MethodKey, RunSummaryStore>>) =
            error("Read-only during a run (analyzer-core.md A4)")
        override fun persistScoped(direction: Direction, summaries: Sequence<ScopedRunSummary>): Unit =
            error("Read-only during a run (analyzer-core.md A4)")
        override fun persistCompleted(direction: Direction, summaries: Sequence<Pair<MethodKey, RunSummaryStore>>,
                                      scoped: Sequence<ScopedRunSummary>): Unit =
            error("Read-only during a run (analyzer-core.md A4)")
        override fun view(): RecordStore = this
    }

    override fun persist(direction: Direction, summaries: Sequence<Pair<MethodKey, RunSummaryStore>>) {
        mutation { staged, copied ->
            var changed = false
            for ((method, store) in summaries)
                changed = ingestStore(Owner(method, direction, null, null), store, staged, copied) || changed
            changed
        }
    }

    override fun persistScoped(direction: Direction, summaries: Sequence<ScopedRunSummary>) {
        mutation { staged, copied ->
            var changed = false
            for ((key, store) in summaries)
                changed = ingestStore(Owner(key.method, direction, key.scope, key.exit), store, staged, copied) || changed
            changed
        }
    }

    override fun persistCompleted(direction: Direction, summaries: Sequence<Pair<MethodKey, RunSummaryStore>>,
                                  scoped: Sequence<ScopedRunSummary>) {
        mutation { staged, copied ->
            var changed = false
            for ((method, store) in summaries)
                changed = ingestStore(Owner(method, direction, null, null), store, staged, copied) || changed
            for ((key, store) in scoped)
                changed = ingestStore(Owner(key.method, direction, key.scope, key.exit), store, staged, copied) || changed
            changed
        }
    }

    private fun ingestStore(owner: Owner, store: RunSummaryStore,
                            staged: MutableMap<Owner, RunSummaryStore>, copied: MutableSet<Owner>): Boolean {
        var changed = false
        for ((premise, facts) in store.all()) {
            m.cancellation.checkpoint()
            if (!RuntimeDataDomain.packet(premise, facts) || facts.layer == Layer.DEMAND) continue
            val initial = premise as? InitialAp ?: continue
            if (owner.direction == Direction.BACKWARD && initial.isZero) continue
            changed = ingest(owner, initial, facts, staged, copied) || changed
        }
        return changed
    }

}

private fun checkNativeRecord(direction: Direction, premise: InitialAp, conclusion: Facts) {
    assertCanonicalFlowSummary(premise, conclusion)
    check(conclusion.base !is AccessPathBase.CleanerTemporary) { "A field-action temporary cannot enter a native record" }
    check(conclusion.layer == Layer.NORMAL) { "R1: a native record must be normal" }
    check((conclusion is FlowTree) == premise.isFlow) { "K6: the conclusion kind follows the native premise" }
    check(premise.isZero || when (premise.mark) {
        is MarkSlot.Concrete -> premise.tail != Tail.STAR
        is MarkSlot.Star -> premise.tail == Tail.STAR || premise.tail == Tail.ANY_TAINT
    }) { "A native record needs a zero, concrete exact/any or abstract STAR initial" }
    if (direction == Direction.BACKWARD) {
        check(!premise.isZero) { "R1: a backward zero-premise edge is not a native record" }
        check(premise.tail != Tail.ANY_TAINT) { "W8 (d): a backward record cannot have a must premise" }
        check(conclusion !is TaintTree || !conclusion.root.hasAny) { "W6: a backward any leaf is demand" }
    }
}

package org.opentaint.dataflow.bidi.store

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.util.Cancellation
import java.util.ArrayDeque
import java.util.IdentityHashMap

/** Current stored output annotations, not a history or a count of concrete
 * locations denoted by ANY. Shared DAG branches count at every field path.
 * Exact and ANY annotations are separate memberships. Scalar rows count one
 * stored TaintTree header/payload, including ZERO-origin concrete output.
 * Packed rows use one geometry plus exact masks and are counted directly. */
data class RelationCensus(
    val concreteOutputMemberships: Long = 0,
    val protectedOutputMemberships: Long = 0,
    val diagonalGeometryRows: Long = 0,
    val diagonalMarkRows: Long = 0,
    val scalarConcreteRows: Long = 0,
    val flowOutputAnnotations: Long = 0,
) {
    operator fun plus(other: RelationCensus): RelationCensus = RelationCensus(
        Math.addExact(concreteOutputMemberships, other.concreteOutputMemberships),
        Math.addExact(protectedOutputMemberships, other.protectedOutputMemberships),
        Math.addExact(diagonalGeometryRows, other.diagonalGeometryRows),
        Math.addExact(diagonalMarkRows, other.diagonalMarkRows),
        Math.addExact(scalarConcreteRows, other.scalarConcreteRows),
        Math.addExact(flowOutputAnnotations, other.flowOutputAnnotations),
    )

    companion object { val ZERO = RelationCensus() }
}

/** A completion-scan local cache. No node reference escapes into the returned
 * numeric result or remains on a store after census() returns. */
internal class RelationCensusCounter(private val cancellation: Cancellation) {
    private val flow = IdentityHashMap<FlowNode, Long>()
    private val taint = IdentityHashMap<TaintNode, Long>()
    init { cancellation.checkpoint() }

    fun flowAnnotations(root: FlowNode): Long = count(root, flow) { if (it.isEmpty) 0L else 1L }
    fun concreteMemberships(root: TaintNode): Long = count(root, taint) {
        it.exact.size.toLong() + it.any.size.toLong()
    }

    fun scalar(facts: Facts): RelationCensus {
        cancellation.checkpoint()
        return when (facts) {
            is Reach -> RelationCensus.ZERO
            is FlowTree -> RelationCensus(flowOutputAnnotations = flowAnnotations(facts.root))
            is TaintTree -> RelationCensus(
                concreteOutputMemberships = concreteMemberships(facts.root),
                protectedOutputMemberships = facts.nonSubsumable?.let(::concreteMemberships) ?: 0L,
                scalarConcreteRows = 1,
            )
        }
    }

    private class Frame<P : TrieLeaf>(val node: TrieNode<P>, var next: Int = 0)
    private fun <P : TrieLeaf> count(root: TrieNode<P>, memo: IdentityHashMap<TrieNode<P>, Long>,
                                    weight: (P) -> Long): Long {
        cancellation.checkpoint()
        memo[root]?.let { return it }
        val stack = ArrayDeque<Frame<P>>()
        stack.addLast(Frame(root))
        while (stack.isNotEmpty()) {
            cancellation.checkpoint()
            val frame = stack.peekLast()
            val children = frame.node.childData
            if (children != null && frame.next < children.size) {
                val child = children[frame.next++]
                if (!memo.containsKey(child)) stack.addLast(Frame(child))
                continue
            }
            var result = weight(frame.node.leaf)
            children?.forEach { child ->
                cancellation.checkpoint()
                // The same cached child can occur under two accessors. Add its
                // count twice: those accessors denote two different paths.
                result = Math.addExact(result, memo.getValue(child))
            }
            memo[frame.node] = result
            stack.removeLast()
        }
        return memo.getValue(root)
    }
}

package org.opentaint.dataflow.bidi.store

import it.unimi.dsi.fastutil.ints.IntOpenHashSet
import org.opentaint.dataflow.bidi.ap.MarkSet
import org.opentaint.dataflow.bidi.ap.TaintMark

/** Owned request marks. Temporary versions never enter the AP manager's strong tables. */
interface RequestMarkSelection {
    fun containsId(id: Int): Boolean
    fun cursor(): RequestMarkCursor
}

interface RequestMarkCursor {
    val isComplete: Boolean
    /** Return source cells consumed, at most budget; deduplicating cursors can invoke fewer callbacks. */
    fun step(budget: Int, visit: (TaintMark) -> Unit): Int
}

class RequestMarkSet private constructor(private val data: IntArray, private val hash: Int = data.contentHashCode()) : ImmutableRequestMarks {
    val size: Int get() = data.size
    override val isEmpty: Boolean get() = data.isEmpty()
    val primitiveCapacity: Int get() = data.size

    fun idAt(index: Int): Int = data[index]
    fun markAt(index: Int): TaintMark = TaintMark(data[index])
    override fun containsId(id: Int): Boolean = data.binarySearch(id) >= 0
    override fun cursor(): RequestMarkCursor = object : RequestMarkCursor {
        private var offset = 0
        override val isComplete: Boolean get() = offset == data.size
        override fun step(budget: Int, visit: (TaintMark) -> Unit): Int {
            require(budget > 0)
            var used = 0
            while (used < budget && offset < data.size) { visit(TaintMark(data[offset++])); used++ }
            return used
        }
    }
    operator fun contains(mark: TaintMark): Boolean = containsId(mark.id)
    fun forEachId(visit: (Int) -> Unit) { for (id in data) visit(id) }
    fun forEachMark(visit: (TaintMark) -> Unit) { for (id in data) visit(TaintMark(id)) }

    /** Share an unchanged immutable set, including the common empty-exclusion case. */
    operator fun minus(excluded: MarkSet): RequestMarkSet {
        if (isEmpty || excluded.isEmpty) return this
        val result = IntArray(size)
        var count = 0
        var other = 0
        for (id in data) {
            while (other < excluded.data.size && excluded.data[other] < id) other++
            if (other == excluded.data.size || excluded.data[other] != id) result[count++] = id
        }
        return if (count == size) this else owned(result, count)
    }

    override fun equals(other: Any?): Boolean = this === other ||
        other is RequestMarkSet && hash == other.hash && data.contentEquals(other.data)
    override fun hashCode(): Int = hash
    override fun toString(): String = data.joinToString(prefix = "{", postfix = "}")

    companion object {
        @JvmField val EMPTY = RequestMarkSet(IntArray(0))
        fun of(mark: TaintMark): RequestMarkSet = RequestMarkSet(intArrayOf(mark.id))
        fun fromIds(ids: IntArray): RequestMarkSet {
            if (ids.isEmpty()) return EMPTY
            val sorted = ids.sortedArray()
            var count = 1
            for (index in 1 until sorted.size) if (sorted[index] != sorted[count - 1]) sorted[count++] = sorted[index]
            return owned(sorted, count)
        }
        private fun owned(ids: IntArray, size: Int): RequestMarkSet = when {
            size == 0 -> EMPTY
            size == ids.size -> RequestMarkSet(ids)
            else -> RequestMarkSet(ids.copyOf(size))
        }
        internal fun ownedSorted(ids: IntArray, hash: Int): RequestMarkSet = if (ids.isEmpty()) EMPTY else RequestMarkSet(ids, hash)
    }
}

/** One writer owns the mutable frontier; build/takeSnapshot detach immutable primitive storage. */
class RequestMarkSetBuilder {
    private class IdSet : IntOpenHashSet() {
        val capacity: Int get() = key.size
        val cells: IntArray get() = key
        val hasZero: Boolean get() = containsNull
    }
    private var values: IdSet? = null
    val size: Int get() = values?.size ?: 0
    val isEmpty: Boolean get() = size == 0
    val primitiveCapacity: Int get() = values?.capacity ?: 0
    fun add(mark: TaintMark): Boolean = addId(mark.id)
    fun addId(id: Int): Boolean = (values ?: IdSet().also { values = it }).add(id)
    operator fun contains(mark: TaintMark): Boolean = values?.contains(mark.id) == true
    fun remove(mark: TaintMark): Boolean = values?.remove(mark.id) == true
    fun addAll(marks: RequestMarkSet) { marks.forEachId { addId(it) } }
    fun build(): RequestMarkSet = values?.let { RequestMarkSet.fromIds(it.toIntArray()) } ?: RequestMarkSet.EMPTY
    fun takeSnapshot(): RequestMarkSet = build().also { clear() }
    /** Detach first: later builder additions cannot change the cursor's backing table. */
    fun snapshotCursor(): RequestMarkSnapshotCursor {
        val captured = values
        values = null
        return RequestMarkSnapshotCursor(captured?.cells ?: IntArray(0), captured?.hasZero == true, captured?.size ?: 0)
    }
    fun clear() { values = null }
}

/** Bounded primitive copy and signed radix sort. Every examined table/member/count cell uses one unit. */
class RequestMarkSnapshotCursor internal constructor(
    private var cells: IntArray,
    hasZero: Boolean,
    size: Int,
) {
    private var source = IntArray(size)
    private var scratch = IntArray(if (size > 1) size else 0)
    private val counts = IntArray(if (size > 1) 256 else 0)
    private var offset = 0
    private var copied = if (hasZero) 1 else 0
    private var pass = 0
    private var phase = if (size == 0) 4 else 0 // copy, count, prefix, scatter, done, clear, hash
    private var total = 0
    private var hash = 1
    private var completed: RequestMarkSet? = if (size == 0) RequestMarkSet.EMPTY else null
    val isComplete: Boolean get() = phase == 4
    val primitiveCapacity: Int get() = cells.size + source.size + scratch.size + counts.size
    val result: RequestMarkSet get() = checkNotNull(completed) { "The mark snapshot is not complete" }

    fun step(budget: Int): Int {
        require(budget > 0)
        var used = 0
        while (used < budget && !isComplete) {
            when (phase) {
                0 -> if (offset < cells.size) {
                    val id = cells[offset++]
                    if (id != 0) source[copied++] = id
                    used++
                } else {
                    check(copied == source.size)
                    cells = IntArray(0)
                    phase = if (source.size == 1) 6 else 1; offset = 0
                }
                1 -> if (offset < source.size) {
                    counts[digit(source[offset++])]++
                    used++
                } else { phase = 2; offset = 0; total = 0 }
                2 -> if (offset < counts.size) {
                    val count = counts[offset]
                    counts[offset++] = total
                    total += count
                    used++
                } else { phase = 3; offset = 0 }
                3 -> if (offset < source.size) {
                    val id = source[offset++]
                    scratch[counts[digit(id)]++] = id
                    used++
                } else {
                    val old = source; source = scratch; scratch = old
                    pass++
                    if (pass == 4) {
                        scratch = IntArray(0)
                        phase = 6; offset = 0
                    } else {
                        phase = 5; offset = 0
                    }
                }
                5 -> if (offset < counts.size) { counts[offset++] = 0; used++ }
                    else { phase = 1; offset = 0 }
                6 -> if (offset < source.size) { hash = hash * 31 + source[offset++]; used++ }
                    else { completed = RequestMarkSet.ownedSorted(source, hash); phase = 4 }
            }
        }
        return used
    }

    private fun digit(id: Int): Int = ((id xor Int.MIN_VALUE) ushr (pass * 8)) and 255
}

package org.opentaint.dataflow.bidi.store

import kotlinx.collections.immutable.PersistentMap
import kotlinx.collections.immutable.persistentHashMapOf
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.interp.ProofKey
import org.opentaint.dataflow.bidi.interp.FormCacheStatistics
import org.opentaint.dataflow.bidi.interp.RuleOccurrenceId
import org.opentaint.dataflow.bidi.interp.RulePredicate
import org.opentaint.ir.api.common.cfg.CommonInst
import java.util.Collections
import java.util.IdentityHashMap

/** Standing supported branches for one actor. Records contain no compiled predicate topology. */
class RulePredicateStore(private val manager: ApManager, private val statistics: FormCacheStatistics? = null,
                         private val premises: PremiseCombination = ExactPremises(manager)) {
    private data class Scope(val rule: RuleOccurrenceId, val statement: CommonInst)
    private data class Header(val leaf: Int, val premise: PremiseKey, val layer: Layer, val group: GroupKey?)
    private data class Choice(val node: Int, val branch: Int)
    private class VersionedInput(val input: ConjunctionStore.Input, val version: Long = 0)

    /** Hashes use child hashes. Equality walks a DAG without recursion or repeated shared subtrees. */
    private sealed class Proof(val node: Int, private val hash: Int) {
        final override fun hashCode(): Int = hash
        final override fun equals(other: Any?): Boolean {
            if (this === other) return true
            if (other !is Proof || hash != other.hash) return false
            val work = ArrayDeque<Pair<Proof, Proof>>()
            val seen = IdentityHashMap<Proof, MutableSet<Proof>>()
            work.add(this to other)
            while (work.isNotEmpty()) {
                val (a, b) = work.removeLast()
                if (a === b) continue
                if (a.hash != b.hash || a.node != b.node || a.javaClass != b.javaClass) return false
                val peers = seen.getOrPut(a) { Collections.newSetFromMap(IdentityHashMap()) }
                if (!peers.add(b)) continue
                when (a) {
                    is LeafProof -> if (a.leaf != (b as LeafProof).leaf) return false
                    is OrProof -> {
                        b as OrProof
                        if (a.branch != b.branch) return false
                        if (a.child !== b.child) work.add(a.child to b.child)
                    }
                    is AndProof -> {
                        b as AndProof
                        if (a.children.size != b.children.size) return false
                        for (i in a.children.indices)
                            if (a.children[i] !== b.children[i]) work.add(a.children[i] to b.children[i])
                    }
                }
            }
            return true
        }
    }
    private class LeafProof(node: Int, val leaf: Int) : Proof(node, 31 * (13 + node) + leaf)
    private class OrProof(node: Int, val branch: Int, val child: Proof) :
        Proof(node, 31 * (31 * (31 + node) + branch) + child.hashCode())
    private class AndProof(node: Int, val children: Array<Proof>) :
        Proof(node, children.fold(47 + node) { hash, child -> 31 * hash + child.hashCode() })

    private class Shape(val proof: Proof, val headers: PersistentMap<Int, Header>, val headersHash: Int) {
        private val hash = 31 * proof.hashCode() + headersHash
        override fun hashCode(): Int = hash
        override fun equals(other: Any?): Boolean = this === other || other is Shape && hash == other.hash &&
            headers == other.headers && proof == other.proof
    }
    private class Support(val shape: Shape, val inputs: PersistentMap<Int, VersionedInput>)
    private class Columns(val headers: PersistentMap<Int, Header>, val headersHash: Int,
                          val inputs: PersistentMap<Int, VersionedInput>)
    private class ChildSupports(val node: Int, val values: List<Support>)
    private class RootKey(val proof: ProofKey, val leaves: List<Int>, val headers: PersistentMap<Int, Header>,
                          headersHash: Int) {
        private val hash = 31 * proof.hashCode() + headersHash
        override fun hashCode(): Int = hash
        override fun equals(other: Any?): Boolean = this === other || other is RootKey && hash == other.hash &&
            proof == other.proof && headers == other.headers
    }
    private class State {
        val nodes = HashMap<Int, LinkedHashMap<Shape, Support>>()
        val proofs = HashMap<Proof, Proof>()
        val rootKeys = HashMap<Shape, RootKey>()
        val emitted = HashMap<RootKey, PersistentMap<Int, VersionedInput>>()
        fun intern(proof: Proof, statistics: FormCacheStatistics?): Proof = proofs.getOrPut(proof) {
            statistics?.observedProof()
            proof
        }
    }
    private val states = HashMap<Scope, State>()

    class Combination(
        val proof: ProofKey,
        val premise: PremiseKey,
        val layer: Layer,
        val leaves: List<Int>,
        val inputs: List<ConjunctionStore.Input>,
    )

    /** Complete witness inputs before a client chooses an executable premise policy. */
    class CompletePredicateBinding(
        val proof: ProofKey,
        val layer: Layer,
        val leaves: List<Int>,
        val inputs: List<ConjunctionStore.Input>,
    )

    /** FULL results keep exact premise combination; sinks can use [addBinding] directly. */
    fun add(rule: RuleOccurrenceId, statement: CommonInst, predicate: RulePredicate, leaf: Int,
            input: ConjunctionStore.Input, emit: (Combination) -> Unit) =
        addBinding(rule, statement, predicate, leaf, input) { binding ->
            val premise = premises.combine(binding.inputs.asSequence().map { it.premise }.asIterable())
            emit(Combination(binding.proof, premise, binding.layer, binding.leaves, binding.inputs))
        }

    /** Facts enter one canonical leaf. AND products are streamed when actual supports arrive. */
    fun addBinding(rule: RuleOccurrenceId, statement: CommonInst, predicate: RulePredicate, leaf: Int,
                   input: ConjunctionStore.Input, emit: (CompletePredicateBinding) -> Unit) {
        manager.cancellation.checkpoint()
        if (!RuntimeDataDomain.premise(input.premise) ||
            input.facts?.let { !RuntimeDataDomain.base(it.base) } == true) return
        require(leaf in predicate.leaves.indices)
        val state = states.getOrPut(Scope(rule, statement)) { State() }
        val queue = ArrayDeque<Pair<Int, Support>>()

        fun publish(node: Int, support: Support) {
            manager.cancellation.checkpoint()
            val standing = state.nodes.getOrPut(node) { LinkedHashMap() }
            val previous = standing[support.shape]
            val fresh = if (previous == null) support else merge(previous, support) ?: return
            standing[support.shape] = fresh
            if (previous == null) statistics?.observedSupport() else statistics?.supportGrowth()
            queue.addLast(node to fresh)
        }

        val node = predicate.leafNode(leaf)
        val header = Header(leaf, input.premise, input.layer, input.facts?.groupKey)
        val shape = Shape(state.intern(LeafProof(node, leaf), statistics), persistentHashMapOf(leaf to header),
            leaf.hashCode() xor header.hashCode())
        publish(node, Support(shape, persistentHashMapOf(leaf to VersionedInput(input))))
        while (queue.isNotEmpty()) {
            manager.cancellation.checkpoint()
            val (current, support) = queue.removeFirst()
            // A later publication contains the merged facts of an older queued version.
            if (state.nodes[current]?.get(support.shape) !== support) continue
            if (current == predicate.root) {
                combineFresh(rule, state, support)?.let(emit)
                continue
            }
            predicate.parentsOf(current) { parent ->
                manager.cancellation.checkpoint()
                when (predicate.kind(parent)) {
                    RulePredicate.Kind.OR -> {
                        val proof = state.intern(OrProof(parent, current, support.shape.proof), statistics)
                        publish(parent, Support(Shape(proof, support.shape.headers, support.shape.headersHash), support.inputs))
                    }
                    RulePredicate.Kind.AND -> {
                        val others = ArrayList<ChildSupports>()
                        val order = ArrayList<Int>()
                        var missing = false
                        predicate.childrenOf(parent) { child ->
                            manager.cancellation.checkpoint()
                            order += child
                            if (child != current) {
                                val standing = state.nodes[child]?.values
                                if (standing.isNullOrEmpty()) missing = true
                                else {
                                    val snapshot = ArrayList<Support>(standing.size)
                                    for (value in standing) {
                                        manager.cancellation.checkpoint()
                                        snapshot += value
                                    }
                                    others += ChildSupports(child, snapshot)
                                }
                            }
                        }
                        if (!missing) join(state, parent, current, support, others, order) { publish(parent, it) }
                    }
                    else -> error("A leaf or constant cannot be a predicate parent")
                }
            }
        }
    }

    /** Partial products share bindings and child records instead of copying whole support lists. */
    private fun join(state: State, parent: Int, child: Int, delta: Support, others: List<ChildSupports>,
                     order: List<Int>, emit: (Support) -> Unit) {
        val positions = IntArray(others.size)
        val partial = arrayOfNulls<Columns>(others.size + 1)
        val proofs = arrayOfNulls<PersistentMap<Int, Proof>>(others.size + 1)
        partial[0] = columns(delta)
        proofs[0] = persistentHashMapOf(child to delta.shape.proof)
        var depth = 0
        while (depth >= 0) {
            manager.cancellation.checkpoint()
            if (depth == others.size) {
                val selected = checkNotNull(proofs[depth])
                val children = Array(order.size) {
                    manager.cancellation.checkpoint()
                    checkNotNull(selected[order[it]])
                }
                val proof = state.intern(AndProof(parent, children), statistics)
                val value = checkNotNull(partial[depth])
                emit(Support(Shape(proof, value.headers, value.headersHash), value.inputs))
                depth--
                continue
            }
            val standing = others[depth]
            if (positions[depth] == standing.values.size) {
                positions[depth] = 0
                partial[depth + 1] = null
                proofs[depth + 1] = null
                depth--
                continue
            }
            val support = standing.values[positions[depth]++]
            val next = compatible(checkNotNull(partial[depth]), columns(support)) ?: continue
            partial[depth + 1] = next
            proofs[depth + 1] = checkNotNull(proofs[depth]).put(standing.node, support.shape.proof)
            depth++
        }
    }

    private fun columns(support: Support) = Columns(support.shape.headers, support.shape.headersHash, support.inputs)

    /** The binding for a repeated canonical leaf must agree, including its complete fact group. */
    private fun compatible(a: Columns, b: Columns): Columns? {
        val base = if (a.headers.size >= b.headers.size) a else b
        val other = if (base === a) b else a
        var headers = base.headers
        var hash = base.headersHash
        var inputs = base.inputs
        for ((leaf, header) in other.headers) {
            manager.cancellation.checkpoint()
            val previous = headers[leaf]
            if (previous == null) {
                headers = headers.put(leaf, header)
                hash += leaf.hashCode() xor header.hashCode()
                inputs = inputs.put(leaf, checkNotNull(other.inputs[leaf]))
            } else {
                if (previous != header) return null
                val current = checkNotNull(inputs[leaf])
                val merged = unionInput(current, checkNotNull(other.inputs[leaf]))
                if (merged !== current) inputs = inputs.put(leaf, merged)
            }
        }
        return if (headers === base.headers && inputs === base.inputs) base else Columns(headers, hash, inputs)
    }

    private fun merge(a: Support, b: Support): Support? =
        mergeInputs(a.inputs, b.inputs)?.let { Support(a.shape, it) }

    private fun mergeInputs(a: PersistentMap<Int, VersionedInput>, b: PersistentMap<Int, VersionedInput>):
        PersistentMap<Int, VersionedInput>? {
        var merged = a
        for ((leaf, input) in b) {
            manager.cancellation.checkpoint()
            val previous = checkNotNull(merged[leaf])
            val fresh = unionInput(previous, input)
            if (fresh !== previous) merged = merged.put(leaf, fresh)
        }
        return if (merged === a) null else merged
    }

    private fun unionInput(a: VersionedInput, b: VersionedInput): VersionedInput {
        if (a === b) return a
        val ai = a.input
        val bi = b.input
        check(ai.premise == bi.premise && ai.layer == bi.layer && ai.facts?.groupKey == bi.facts?.groupKey)
        val af = ai.facts ?: return a
        val (merged, delta) = manager.mergeAddDelta(af, checkNotNull(bi.facts))
        return if (delta == null) a else VersionedInput(ai.copy(facts = merged), maxOf(a.version, b.version) + 1)
    }

    /** Only complete root supports flatten their canonical leaf and OR-choice descriptors. */
    private fun rootKey(rule: RuleOccurrenceId, state: State, shape: Shape): RootKey =
        state.rootKeys.getOrPut(shape) {
            val leaves = Collections.unmodifiableList(shape.headers.keys.sorted())
            val choices = HashSet<Choice>()
            val seen = Collections.newSetFromMap(IdentityHashMap<Proof, Boolean>())
            val work = ArrayDeque<Proof>()
            work.add(shape.proof)
            while (work.isNotEmpty()) {
                manager.cancellation.checkpoint()
                val proof = work.removeLast()
                if (!seen.add(proof)) continue
                when (proof) {
                    is LeafProof -> Unit
                    is OrProof -> { choices += Choice(proof.node, proof.branch); work.add(proof.child) }
                    is AndProof -> for (child in proof.children) {
                        manager.cancellation.checkpoint()
                        work.add(child)
                    }
                }
            }
            val flat = ArrayList<Int>(2 * choices.size)
            for (choice in choices.sortedWith(choiceOrder)) {
                manager.cancellation.checkpoint()
                flat += choice.node
                flat += choice.branch
            }
            RootKey(ProofKey(rule, leaves, flat), leaves, shape.headers, shape.headersHash)
        }

    private fun combineFresh(rule: RuleOccurrenceId, state: State, support: Support): CompletePredicateBinding? {
        val key = rootKey(rule, state, support.shape)
        val previous = state.emitted[key]
        val inputs = if (previous == null) support.inputs else mergeInputs(previous, support.inputs) ?: return null
        state.emitted[key] = inputs
        var layer = Layer.NORMAL
        val ordered = ArrayList<ConjunctionStore.Input>(key.leaves.size)
        for (leaf in key.leaves) {
            manager.cancellation.checkpoint()
            val input = checkNotNull(inputs[leaf]).input
            ordered += input
            if (input.layer == Layer.DEMAND) layer = Layer.DEMAND
        }
        val combination = CompletePredicateBinding(key.proof, layer, key.leaves, Collections.unmodifiableList(ordered))
        statistics?.rootOutcome(growth = previous != null)
        return combination
    }

    private companion object {
        val choiceOrder = compareBy<Choice> { it.node }.thenBy { it.branch }
    }
}

package org.opentaint.dataflow.bidi.store

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.ir.api.common.cfg.CommonInst

/** One method actor owns accepted slot domains. Only complete header products are enumerated. */
internal class Run1OriginConjunctionStore(private val manager: ApManager) {
    private data class Header(val layer: Layer, val group: GroupKey?)
    private class Domain {
        val inputs = LinkedHashMap<InitialAp, ConjunctionStore.Input>()
        var hasProtection = false
        var marks = MarkSet.EMPTY
    }
    private class Emitted {
        val nonzero = Array(Layer.entries.size) { HashMap<InitialAp, Boolean>() }
        val zero = arrayOfNulls<Boolean>(Layer.entries.size)
        var protectedAll = false
    }
    private class State(val arity: Int) {
        val slots = List(arity) { LinkedHashMap<Header, Domain>() }
        val emitted = HashMap<List<Header>, Emitted>()
    }
    private val states = HashMap<Pair<Any, CommonInst>, State>()
    internal var originMembershipVisits = 0L
        private set

    fun addOrigins(rule: Any, statement: CommonInst, arity: Int, literal: Int,
                   input: ConjunctionStore.Input, emit: (InitialAp, Layer) -> Unit) {
        addProtectedOrigins(rule, statement, arity, literal, input, null, null) { initial, layer, _ -> emit(initial, layer) }
    }

    fun addProtectedOrigins(rule: Any, statement: CommonInst, arity: Int, literal: Int,
                            input: ConjunctionStore.Input, assigned: TaintMark?, triggering: TaintMark?,
                            emit: (InitialAp, Layer, Boolean) -> Unit) {
        manager.cancellation.checkpoint()
        if (!RuntimeDataDomain.premise(input.premise) ||
            input.facts?.let { !RuntimeDataDomain.base(it.base) } == true) return
        require(arity >= 2) { "A conjunction needs at least two literals" }
        require(literal in 0 until arity) { "A literal index must be within the conjunction's arity" }
        val initial = input.premise
        check(initial is InitialAp && initial.manager === manager) { "A run-1 input needs one owned initial" }
        check(initial.exclusion == ExclusionSet.Empty) { "Run-1 initials have empty field exclusions" }
        val state = states.getOrPut(rule to statement) { State(arity) }
        require(state.arity == arity) { "A rule at a statement has one fixed arity" }
        val header = Header(input.layer, input.facts?.groupKey)
        val domain = state.slots[literal].getOrPut(header) { Domain() }
        val previous = domain.inputs[initial]
        val accepted = if (previous == null) input else {
            if (previous.facts == null || input.facts == null) return
            val (merged, delta) = manager.mergeAddDelta(previous.facts, input.facts)
            if (delta == null) return
            input.copy(facts = merged)
        }
        domain.inputs[initial] = accepted
        (accepted.facts as? TaintTree)?.let { facts ->
            domain.hasProtection = domain.hasProtection || facts.nonSubsumable != null
        }
        if (triggering != null) domain.marks += triggering
        if (state.slots.any { it.isEmpty() }) return

        val choices = state.slots.mapIndexed { slot, headers ->
            if (slot == literal) listOf(header) else headers.keys.toList()
        }
        val positions = IntArray(arity)
        while (true) {
            manager.cancellation.checkpoint()
            val headers = choices.mapIndexed { slot, values -> values[positions[slot]] }
            val domains = headers.mapIndexed { slot, h -> state.slots[slot].getValue(h) }
            val layer = if (headers.any { it.layer == Layer.DEMAND }) Layer.DEMAND else Layer.NORMAL
            val old = state.emitted[headers]
            val emitted = old ?: Emitted().also { state.emitted[headers] = it }
            val hasProtection = assigned != null && domains.any { it.hasProtection || assigned in it.marks }
            val protectionGrowth = hasProtection && !emitted.protectedAll
            val hasDifferentMark = assigned != null && domains.any { d -> d.marks.data.any { it != assigned.id } }
            fun offer(i: InitialAp) {
                manager.cancellation.checkpoint()
                originMembershipVisits++
                if (i.isZero) return
                val flag = hasProtection || (assigned != null && (i.mark as? MarkSlot.Concrete)?.mark == assigned && hasDifferentMark)
                val armLayer = if (layer == Layer.NORMAL && domains.all {
                        i in it.inputs || manager.zero in it.inputs
                    }) Layer.NORMAL else Layer.DEMAND
                fun offerLane(lane: Layer) {
                    val flags = emitted.nonzero[lane.ordinal]
                    val previousFlag = flags[i]
                    if (previousFlag == null || flag && !previousFlag) {
                        flags[i] = previousFlag == true || flag
                        emit(i, lane, flag)
                    }
                }
                offerLane(armLayer)
                // An annotation upgrade also belongs to any earlier result lane.
                if (flag) for (lane in Layer.entries) {
                    if (lane != armLayer && emitted.nonzero[lane.ordinal][i] == false) offerLane(lane)
                }
            }
            emitted.protectedAll = emitted.protectedAll || hasProtection
            val zeroGrowth = previous == null && initial.isZero
            if (old == null || protectionGrowth || zeroGrowth) {
                for (d in domains) for (i in d.inputs.keys) offer(i)
            } else offer(initial)
            // The same complete header partition has a ZERO choice in EVERY slot.
            if (domains.all { manager.zero in it.inputs }) {
                val zeroProtected = assigned != null && domains.any { d ->
                    (d.inputs[manager.zero]?.facts as? TaintTree)?.nonSubsumable != null || assigned in d.marks
                }
                if (emitted.zero[layer.ordinal] == null || zeroProtected && emitted.zero[layer.ordinal] == false) {
                    emitted.zero[layer.ordinal] = emitted.zero[layer.ordinal] == true || zeroProtected
                    emit(manager.zero, layer, zeroProtected)
                }
            }
            var slot = arity - 1
            while (slot >= 0) {
                manager.cancellation.checkpoint()
                if (++positions[slot] < choices[slot].size) break
                positions[slot] = 0
                slot--
            }
            if (slot < 0) return
        }
    }
}

package org.opentaint.dataflow.bidi.store

import kotlinx.collections.immutable.PersistentMap
import kotlinx.collections.immutable.persistentHashMapOf
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.interp.ProofKey
import org.opentaint.dataflow.bidi.interp.FormCacheStatistics
import org.opentaint.dataflow.bidi.interp.RuleOccurrenceId
import org.opentaint.dataflow.bidi.interp.RulePredicate
import org.opentaint.ir.api.common.cfg.CommonInst
import java.util.Collections
import java.util.IdentityHashMap

/**
 * Run-1 result conditions. Each supported proof/header shape stores independent origin domains,
 * rather than one support for every tuple of original premises. Sink witnesses use RulePredicateStore.
 * One actor owns the store. Standing records do not retain compiled predicate topology or callbacks.
 */
internal class Run1OriginPredicateStore(private val manager: ApManager, private val statistics: FormCacheStatistics? = null) {
    private data class Scope(val rule: RuleOccurrenceId, val statement: CommonInst)
    private data class Header(val leaf: Int, val layer: Layer, val group: GroupKey?)
    private data class Choice(val node: Int, val branch: Int)
    private class VersionedInput(val input: ConjunctionStore.Input, val version: Long = 0)
    private class Domain(val choices: PersistentMap<InitialAp, VersionedInput>,
                         val hasProtection: Boolean = choices.values.any { (it.input.facts as? TaintTree)?.nonSubsumable != null })

    /** Hashes use child hashes. Equality walks a DAG without recursion or repeated shared subtrees. */
    private sealed class Proof(val node: Int, private val hash: Int) {
        final override fun hashCode(): Int = hash
        final override fun equals(other: Any?): Boolean {
            if (this === other) return true
            if (other !is Proof || hash != other.hash) return false
            val work = ArrayDeque<Pair<Proof, Proof>>()
            val seen = IdentityHashMap<Proof, MutableSet<Proof>>()
            work.add(this to other)
            while (work.isNotEmpty()) {
                val (a, b) = work.removeLast()
                if (a === b) continue
                if (a.hash != b.hash || a.node != b.node || a.javaClass != b.javaClass) return false
                val peers = seen.getOrPut(a) { Collections.newSetFromMap(IdentityHashMap()) }
                if (!peers.add(b)) continue
                when (a) {
                    is LeafProof -> if (a.leaf != (b as LeafProof).leaf) return false
                    is OrProof -> {
                        b as OrProof
                        if (a.branch != b.branch) return false
                        if (a.child !== b.child) work.add(a.child to b.child)
                    }
                    is AndProof -> {
                        b as AndProof
                        if (a.children.size != b.children.size) return false
                        for (i in a.children.indices)
                            if (a.children[i] !== b.children[i]) work.add(a.children[i] to b.children[i])
                    }
                }
            }
            return true
        }
    }
    private class LeafProof(node: Int, val leaf: Int) : Proof(node, 31 * (13 + node) + leaf)
    private class OrProof(node: Int, val branch: Int, val child: Proof) :
        Proof(node, 31 * (31 * (31 + node) + branch) + child.hashCode())
    private class AndProof(node: Int, val children: Array<Proof>) :
        Proof(node, children.fold(47 + node) { hash, child -> 31 * hash + child.hashCode() })

    private class Shape(val proof: Proof, val headers: PersistentMap<Int, Header>, val headersHash: Int) {
        private val hash = 31 * proof.hashCode() + headersHash
        override fun hashCode(): Int = hash
        override fun equals(other: Any?): Boolean = this === other || other is Shape && hash == other.hash &&
            headers == other.headers && proof == other.proof
    }
    private class Support(val shape: Shape, val domains: PersistentMap<Int, Domain>, val version: Long = 0,
                          val addedOrigins: Set<InitialAp> = emptySet())
    private class Columns(val headers: PersistentMap<Int, Header>, val headersHash: Int,
                          val domains: PersistentMap<Int, Domain>)
    private class ChildSupports(val node: Int, val values: List<Support>)
    private class RootKey(val proof: ProofKey, val leaves: List<Int>, val headers: PersistentMap<Int, Header>,
                          headersHash: Int) {
        private val hash = 31 * proof.hashCode() + headersHash
        override fun hashCode(): Int = hash
        override fun equals(other: Any?): Boolean = this === other || other is RootKey && hash == other.hash &&
            proof == other.proof && headers == other.headers
    }
    private class State {
        val nodes = HashMap<Int, LinkedHashMap<Shape, Support>>()
        val proofs = HashMap<Proof, Proof>()
        val rootKeys = HashMap<Shape, RootKey>()
        val emitted = HashMap<RootKey, MutableMap<Any, EmittedOrigins>>()
        fun intern(proof: Proof, statistics: FormCacheStatistics?): Proof = proofs.getOrPut(proof) {
            statistics?.observedProof()
            proof
        }
    }
    private val states = HashMap<Scope, State>()
    internal var originMembershipVisits = 0L
        private set

    private class EmittedOrigins {
        val nonzero = Array(Layer.entries.size) { HashMap<InitialAp, Boolean>() }
        val zero = arrayOfNulls<Boolean>(Layer.entries.size)
        var protectedAll = false
        // Only the last processed shape/version is retained, never an old domain snapshot or chain.
        var shape: Shape? = null
        var version = -1L
    }

    /** Only a complete compatible root can create this value. Action permission is checked by the caller. */
    sealed class ReadyCube protected constructor(
        val proof: ProofKey,
        val leaves: List<Int>,
        val layer: Layer,
    ) {
        /** Emit each original once per fixed action target. ZERO needs one complete all-ZERO binding. */
        fun emitOrigins(action: Any, emit: (InitialAp) -> Unit) =
            emitProtectedOrigins(action, null) { initial, _, _ -> emit(initial) }
        fun emitLayeredOrigins(action: Any, emit: (InitialAp, Layer) -> Unit) =
            emitProtectedOrigins(action, null) { initial, layer, _ -> emit(initial, layer) }
        abstract fun emitProtectedOrigins(action: Any, assigned: TaintMark?, emit: (InitialAp, Layer, Boolean) -> Unit)
    }

    private class ReadyResult(proof: ProofKey, leaves: List<Int>, layer: Layer,
                              private val emitAction: (Any, TaintMark?, (InitialAp, Layer, Boolean) -> Unit) -> Unit) : ReadyCube(proof, leaves, layer) {
        override fun emitProtectedOrigins(action: Any, assigned: TaintMark?, emit: (InitialAp, Layer, Boolean) -> Unit) =
            emitAction(action, assigned, emit)
    }

    /** Facts enter one canonical leaf. Only supported proof/header shapes are combined at AND. */
    fun add(rule: RuleOccurrenceId, statement: CommonInst, predicate: RulePredicate, leaf: Int,
            input: ConjunctionStore.Input, emit: (ReadyCube) -> Unit) {
        manager.cancellation.checkpoint()
        if (!RuntimeDataDomain.premise(input.premise) ||
            input.facts?.let { !RuntimeDataDomain.base(it.base) } == true) return
        require(leaf in predicate.leaves.indices)
        val initial = checkedInitial(input.premise)
        val state = states.getOrPut(Scope(rule, statement)) { State() }
        val queue = ArrayDeque<Pair<Int, Support>>()

        fun publish(node: Int, support: Support) {
            manager.cancellation.checkpoint()
            val standing = state.nodes.getOrPut(node) { LinkedHashMap() }
            val previous = standing[support.shape]
            val fresh = if (previous == null) support else merge(previous, support) ?: return
            standing[support.shape] = fresh
            if (previous == null) statistics?.observedSupport() else statistics?.supportGrowth()
            queue.addLast(node to fresh)
        }

        val node = predicate.leafNode(leaf)
        val header = Header(leaf, input.layer, input.facts?.groupKey)
        val shape = Shape(state.intern(LeafProof(node, leaf), statistics), persistentHashMapOf(leaf to header),
            leaf.hashCode() xor header.hashCode())
        publish(node, Support(shape, persistentHashMapOf(leaf to Domain(persistentHashMapOf(initial to VersionedInput(input))))))
        while (queue.isNotEmpty()) {
            manager.cancellation.checkpoint()
            val (current, support) = queue.removeFirst()
            // A later publication contains the merged facts of an older queued version.
            if (state.nodes[current]?.get(support.shape) !== support) continue
            if (current == predicate.root) {
                emit(readyCube(rule, state, support, predicate))
                continue
            }
            predicate.parentsOf(current) { parent ->
                manager.cancellation.checkpoint()
                when (predicate.kind(parent)) {
                    RulePredicate.Kind.OR -> {
                        val proof = state.intern(OrProof(parent, current, support.shape.proof), statistics)
                        publish(parent, Support(Shape(proof, support.shape.headers, support.shape.headersHash), support.domains))
                    }
                    RulePredicate.Kind.AND -> {
                        val others = ArrayList<ChildSupports>()
                        val order = ArrayList<Int>()
                        var missing = false
                        predicate.childrenOf(parent) { child ->
                            manager.cancellation.checkpoint()
                            order += child
                            if (child != current) {
                                val standing = state.nodes[child]?.values
                                if (standing.isNullOrEmpty()) missing = true
                                else {
                                    val snapshot = ArrayList<Support>(standing.size)
                                    for (value in standing) {
                                        manager.cancellation.checkpoint()
                                        snapshot += value
                                    }
                                    others += ChildSupports(child, snapshot)
                                }
                            }
                        }
                        if (!missing) join(state, parent, current, support, others, order) { publish(parent, it) }
                    }
                    else -> error("A leaf or constant cannot be a predicate parent")
                }
            }
        }
    }

    /** Combine proof/header shapes while keeping each leaf's original domain factored. */
    private fun join(state: State, parent: Int, child: Int, delta: Support, others: List<ChildSupports>,
                     order: List<Int>, emit: (Support) -> Unit) {
        val positions = IntArray(others.size)
        val partial = arrayOfNulls<Columns>(others.size + 1)
        val proofs = arrayOfNulls<PersistentMap<Int, Proof>>(others.size + 1)
        partial[0] = columns(delta)
        proofs[0] = persistentHashMapOf(child to delta.shape.proof)
        var depth = 0
        while (depth >= 0) {
            manager.cancellation.checkpoint()
            if (depth == others.size) {
                val selected = checkNotNull(proofs[depth])
                val children = Array(order.size) {
                    manager.cancellation.checkpoint()
                    checkNotNull(selected[order[it]])
                }
                val proof = state.intern(AndProof(parent, children), statistics)
                val value = checkNotNull(partial[depth])
                emit(Support(Shape(proof, value.headers, value.headersHash), value.domains))
                depth--
                continue
            }
            val standing = others[depth]
            if (positions[depth] == standing.values.size) {
                positions[depth] = 0
                partial[depth + 1] = null
                proofs[depth + 1] = null
                depth--
                continue
            }
            val support = standing.values[positions[depth]++]
            val next = compatible(checkNotNull(partial[depth]), columns(support)) ?: continue
            partial[depth + 1] = next
            proofs[depth + 1] = checkNotNull(proofs[depth]).put(standing.node, support.shape.proof)
            depth++
        }
    }

    private fun columns(support: Support) = Columns(support.shape.headers, support.shape.headersHash, support.domains)

    /** The binding for a repeated canonical leaf must agree, including its complete fact group. */
    private fun compatible(a: Columns, b: Columns): Columns? {
        val base = if (a.headers.size >= b.headers.size) a else b
        val other = if (base === a) b else a
        var headers = base.headers
        var hash = base.headersHash
        var domains = base.domains
        for ((leaf, header) in other.headers) {
            manager.cancellation.checkpoint()
            val previous = headers[leaf]
            if (previous == null) {
                headers = headers.put(leaf, header)
                hash += leaf.hashCode() xor header.hashCode()
                domains = domains.put(leaf, checkNotNull(other.domains[leaf]))
            } else {
                if (previous != header) return null
                val current = checkNotNull(domains[leaf])
                val merged = intersectDomains(current, checkNotNull(other.domains[leaf])) ?: return null
                if (merged !== current) domains = domains.put(leaf, merged)
            }
        }
        return if (headers === base.headers && domains === base.domains) base else Columns(headers, hash, domains)
    }

    private fun merge(a: Support, b: Support): Support? {
        val addedOrigins = HashSet<InitialAp>()
        val domains = mergeDomains(a.domains, b.domains, addedOrigins) ?: return null
        return Support(a.shape, domains, a.version + 1, addedOrigins)
    }

    private fun mergeDomains(a: PersistentMap<Int, Domain>, b: PersistentMap<Int, Domain>,
                            addedOrigins: MutableSet<InitialAp>): PersistentMap<Int, Domain>? {
        var merged = a
        for ((leaf, input) in b) {
            manager.cancellation.checkpoint()
            val previous = checkNotNull(merged[leaf])
            val fresh = unionDomains(previous, input, addedOrigins)
            if (fresh !== previous) merged = merged.put(leaf, fresh)
        }
        return if (merged === a) null else merged
    }

    private fun unionDomains(a: Domain, b: Domain, addedOrigins: MutableSet<InitialAp>): Domain {
        if (a === b) return a
        var choices = a.choices
        for ((initial, value) in b.choices) {
            manager.cancellation.checkpoint()
            val previous = choices[initial]
            if (previous == null) addedOrigins += initial
            val fresh = if (previous == null) value else unionInput(previous, value)
            if (fresh !== previous) choices = choices.put(initial, fresh)
        }
        return if (choices === a.choices) a else Domain(choices, a.hasProtection || b.hasProtection)
    }

    /** A repeated canonical leaf selects the same original and complete header in every operand. */
    private fun intersectDomains(a: Domain, b: Domain): Domain? {
        if (a === b) return a
        var choices = a.choices
        for ((initial, value) in a.choices) {
            manager.cancellation.checkpoint()
            val matched = b.choices[initial]
            if (matched == null) choices = choices.remove(initial)
            else {
                val fresh = unionInput(value, matched)
                if (fresh !== value) choices = choices.put(initial, fresh)
            }
        }
        if (choices.isEmpty()) return null
        return if (choices === a.choices) a else Domain(choices)
    }

    private fun checkedInitial(premise: PremiseKey): InitialAp {
        check(premise is InitialAp) { "A run-1 result condition needs one original premise" }
        check(premise.manager === manager) { "All premises must use this AP manager" }
        check(premise.exclusion == ExclusionSet.Empty) { "A run-1 original has Empty field exclusions" }
        return premise
    }

    private fun unionInput(a: VersionedInput, b: VersionedInput): VersionedInput {
        if (a === b) return a
        val ai = a.input
        val bi = b.input
        check(ai.premise == bi.premise && ai.layer == bi.layer && ai.facts?.groupKey == bi.facts?.groupKey)
        val af = ai.facts ?: return a
        val (merged, delta) = manager.mergeAddDelta(af, checkNotNull(bi.facts))
        return if (delta == null) a else VersionedInput(ai.copy(facts = merged), maxOf(a.version, b.version) + 1)
    }

    /** Only complete root supports flatten their canonical leaf and OR-choice descriptors. */
    private fun rootKey(rule: RuleOccurrenceId, state: State, shape: Shape): RootKey =
        state.rootKeys.getOrPut(shape) {
            val leaves = Collections.unmodifiableList(shape.headers.keys.sorted())
            val choices = HashSet<Choice>()
            val seen = Collections.newSetFromMap(IdentityHashMap<Proof, Boolean>())
            val work = ArrayDeque<Proof>()
            work.add(shape.proof)
            while (work.isNotEmpty()) {
                manager.cancellation.checkpoint()
                val proof = work.removeLast()
                if (!seen.add(proof)) continue
                when (proof) {
                    is LeafProof -> Unit
                    is OrProof -> { choices += Choice(proof.node, proof.branch); work.add(proof.child) }
                    is AndProof -> for (child in proof.children) {
                        manager.cancellation.checkpoint()
                        work.add(child)
                    }
                }
            }
            val flat = ArrayList<Int>(2 * choices.size)
            for (choice in choices.sortedWith(choiceOrder)) {
                manager.cancellation.checkpoint()
                flat += choice.node
                flat += choice.branch
            }
            RootKey(ProofKey(rule, leaves, flat), leaves, shape.headers, shape.headersHash)
        }

    private fun readyCube(rule: RuleOccurrenceId, state: State, support: Support, predicate: RulePredicate): ReadyCube {
        val key = rootKey(rule, state, support.shape)
        check(support.domains.isNotEmpty()) { "Unconditional sources keep their existing GEN path" }
        check(support.domains.values.all { it.choices.isNotEmpty() })
        val layer = if (key.headers.values.any { it.layer == Layer.DEMAND }) Layer.DEMAND else Layer.NORMAL
        statistics?.rootOutcome(growth = state.emitted.containsKey(key))
        val triggering = key.leaves.mapNotNull { (predicate.leaves[it].fact.mark as? MarkSlot.Concrete)?.mark }
        return ReadyResult(key.proof, key.leaves, layer) answer@{ action, assigned, emit ->
            val admitted = state.emitted.getOrPut(key) { HashMap() }.getOrPut(action) { EmittedOrigins() }
            if (admitted.shape === support.shape && admitted.version == support.version) return@answer
            val hasProtection = assigned != null && (support.domains.values.any { it.hasProtection } || assigned in triggering)
            val protectionGrowth = hasProtection && !admitted.protectedAll
            fun offer(initial: InitialAp) {
                manager.cancellation.checkpoint()
                originMembershipVisits++
                if (initial.isZero) return
                val originMark = (initial.mark as? MarkSlot.Concrete)?.mark
                val flag = hasProtection || (assigned != null && originMark == assigned && triggering.any { it != assigned })
                val armLayer = if (layer == Layer.NORMAL && support.domains.values.all {
                        initial in it.choices || manager.zero in it.choices
                    }) Layer.NORMAL else Layer.DEMAND
                fun offerLane(lane: Layer) {
                    val flags = admitted.nonzero[lane.ordinal]
                    val previous = flags[initial]
                    if (previous == null || flag && !previous) {
                        flags[initial] = previous == true || flag
                        emit(initial, lane, flag)
                    }
                }
                offerLane(armLayer)
                // Preserve protection growth in every already published result lane.
                if (flag) for (lane in Layer.entries) {
                    if (lane != armLayer && admitted.nonzero[lane.ordinal][initial] == false) offerLane(lane)
                }
            }
            // New nonzero membership can complete only that origin. A new ZERO choice or
            // protection annotation can change older arms; neither case enumerates origin products.
            val consecutive = admitted.shape === support.shape && admitted.version + 1 == support.version
            admitted.shape = support.shape
            admitted.version = support.version
            admitted.protectedAll = admitted.protectedAll || hasProtection
            if (consecutive && !protectionGrowth && manager.zero !in support.addedOrigins)
                for (initial in support.addedOrigins) offer(initial)
            else for (domain in support.domains.values) for (initial in domain.choices.keys) offer(initial)
            if (support.domains.values.all { it.choices.containsKey(manager.zero) }) {
                val zeroProtected = assigned != null && (assigned in triggering || support.domains.values.any {
                    (it.choices[manager.zero]?.input?.facts as? TaintTree)?.nonSubsumable != null
                })
                if (admitted.zero[layer.ordinal] == null || zeroProtected && admitted.zero[layer.ordinal] == false) {
                    admitted.zero[layer.ordinal] = admitted.zero[layer.ordinal] == true || zeroProtected
                    emit(manager.zero, layer, zeroProtected)
                }
            }
        }
    }

    private companion object {
        val choiceOrder = compareBy<Choice> { it.node }.thenBy { it.branch }
    }
}

package org.opentaint.dataflow.bidi.store

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.graph.PortId

/** One admitted relation. Outgoing demand is a filtered view of the final stored headers. */
class RunSummaryStore(private val m: ApManager, flowBacked: Boolean = false) {
    private val interners = m.newInterners()
    private val normalStars = NormalStarRelationIndex(m, interners)
    private val backed = FlowBackedSummaries(m, replaceCovered = flowBacked, interners = interners, normalStars = normalStars)

    /** Add a candidate only after the actor has completed demand restriction. */
    fun addAdmitted(premise: PremiseKey, g: Facts): Facts? = addAdmittedAll(premise, g).also {
        check(it.size <= 1) { "Use addAdmittedAll for split canonical headers" }
    }.singleOrNull()

    fun addAdmittedAll(premise: PremiseKey, g: Facts): List<Facts> {
        m.cancellation.checkpoint()
        if (!RuntimeDataDomain.packet(premise, g)) return emptyList()
        checkShape(premise, g)
        return backed.addAll(premise, g)
    }

    fun all(): Sequence<Pair<PremiseKey, Facts>> = backed.all()

    fun demandEdges(direction: Direction): Sequence<Pair<PremiseKey, Facts>> =
        all().filter { (premise, facts) -> selectedForHandoff(premise, facts.layer, direction) }

    fun census(): RelationCensus = census { _, _ -> true }

    fun demandCensus(direction: Direction): RelationCensus =
        census { premise, layer -> selectedForHandoff(premise, layer, direction) }

    private fun census(include: (PremiseKey, Layer) -> Boolean): RelationCensus {
        m.cancellation.checkpoint()
        return backed.census(include)
    }

    /** Borrow the current admitted relation on its actor owner. Consume this view
     * before mutating the store; do not retain a historical Facts snapshot. */
    fun borrow(premise: PremiseKey): Sequence<Facts> {
        m.cancellation.checkpoint()
        return backed.borrow(premise)
    }

    private fun checkShape(premise: PremiseKey, facts: Facts) {
        assertCanonicalFlowSummary(premise, facts)
        check(facts.base !is AccessPathBase.CleanerTemporary) { "A field-action temporary cannot enter a summary" }
        check((facts is FlowTree) == premise.isFlow) { "K6: the conclusion kind follows the premise" }
        check(premise !is PremiseSet || facts is TaintTree) { "A multi-premise summary must be TAINT" }
    }

}

/** Allocate only exits which actually publish a completed traversal. The owner
 * keeps one instance per entry scope; AP admission remains RunSummaryStore's law. */
class PortSummaryStores(private val m: ApManager, private val flowBacked: Boolean = false) {
    private val byExit = LinkedHashMap<PortId, RunSummaryStore>()

    fun at(exit: PortId): RunSummaryStore {
        m.cancellation.checkpoint()
        return byExit.getOrPut(exit) { RunSummaryStore(m, flowBacked) }
    }

    fun existing(exit: PortId): RunSummaryStore? = byExit[exit]

    /** Borrow only on the method owner; a frozen handoff must copy admitted rows. */
    fun entries(): Sequence<Pair<PortId, RunSummaryStore>> = sequence {
        for ((exit, rows) in byExit) {
            m.cancellation.checkpoint()
            yield(exit to rows)
        }
    }
}

