/** Backward-run source hits, identified by the same forward micro edge in every run. */
class SourceHitStore {
    data class Hit(val method: MethodKey, val statement: CommonInst, val forward: PathEdge, val action: ActionId?)
    private val hits = LinkedHashSet<Hit>()

    fun add(method: MethodKey, statement: CommonInst, forward: PathEdge, action: ActionId? = null): Boolean {
        if (!RuntimeDataDomain.producer(forward)) return false
        check(forward.from.base !is AccessPathBase.CleanerTemporary && forward.to.base !is AccessPathBase.CleanerTemporary) {
            "A field-action temporary cannot enter a source hit"
        }
        return hits.add(Hit(method, statement, forward, action))
    }

    /** The driver reads these hits at the barrier to seed the next forward run. */
    fun entries(): Sequence<Triple<MethodKey, CommonInst, PathEdge>> =
        hits.asSequence().map { Triple(it.method, it.statement, it.forward) }.distinct()

    /** Equal AP/mark tuples from distinct source actions remain distinct permissions. */
    fun occurrences(): Sequence<Hit> = hits.asSequence()
}

package org.opentaint.dataflow.bidi.store

/** The caller stores and deduplicates a side before each event. Near queries must be symmetric. */
class StandingJoin<A, B>(
    private val nearB: (A) -> Sequence<B>,
    private val nearA: (B) -> Sequence<A>,
    private val meet: (A, B) -> Unit,
) {
    fun newA(a: A) { for (b in nearB(a)) meet(a, b) }
    fun newB(b: B) { for (a in nearA(b)) meet(a, b) }
}

package org.opentaint.dataflow.bidi.store

import org.opentaint.dataflow.bidi.ap.*

/** C2 needs a marked output witness, not all its source/mark products.
 * The result accumulator keeps this query's actual layer through local and inherited paths. */
internal class StaticEntryLookup(
    private val ap: ApManager,
    private val method: MethodKey,
    private val completion: FrozenCompletion,
    private val actual: List<Pattern>,
    private val out: InitialDemandResults,
    private val stats: DemandQueryStatistics?,
) {
    private fun joins(output: Pattern, input: Pattern): Boolean {
        stats?.add(6)
        return staticAnchor(ap, output) == staticAnchor(ap, input) && overlap(output, input)
    }
    fun directLocal() {
        val view = completion.local(method)
        for (leaf in actual) for (entry in view.entries(leaf)) {
            ap.cancellation.checkpoint()
            out.offer(entry, leaf)
        }
    }

    /** Remote search starts afresh. No local visited bit can hide remote adjacency. */
    fun search(visible: Boolean, covered: () -> Boolean) {
        stats?.add(if (visible) 2 else 1)
        val view = if (visible) completion.visible(method) else completion.local(method)
        for (leaf in actual) {
            ap.cancellation.checkpoint()
            // Abstract ordinary inputs cannot acquire a mark from a static path.
            if (leaf.fact.base != STATIC && leaf.fact.mark is MarkSlot.Star) continue
            for (entry in view.entries(leaf)) out.offer(entry, leaf)
            if (covered()) return
            val mark = (leaf.fact.mark as? MarkSlot.Concrete)?.mark ?: continue
            if (mark == TaintMark.ZERO) continue
            for (rightmost in view.flowTargets(leaf)) {
                ap.cancellation.checkpoint()
                if (rightmost.from.fact.base == STATIC) {
                    val colored = rightmost.to.copy(fact = rightmost.to.fact.copy(mark = MarkSlot.Concrete(mark)))
                    if (!out.has(colored, leaf) && exists(view, rightmost.from, mark)) out.offer(colored, leaf)
                }
                if (covered()) return
            }
        }
    }

    /** Forward states are outputs, backward states are inputs. Meetings are directed joins. */
    private fun exists(view: StaticDemandView, input: Pattern, mark: TaintMark): Boolean {
        val forward = ArrayDeque<Pattern>()
        val backward = ArrayDeque<Pattern>()
        val seenForward = HashSet<Pattern>()
        val seenBackward = HashSet<Pattern>()
        val forwardLocations = PathTrie<Pattern>(ap.cancellation)
        val backwardLocations = PathTrie<Pattern>(ap.cancellation)
        fun geometry(p: Pattern): Pattern = p.copy(fact = p.fact.copy(mark = MarkSlot.STAR))
        fun admit(p: Pattern, isForward: Boolean): Boolean {
            val value = geometry(p)
            val seen = if (isForward) seenForward else seenBackward
            if (!seen.add(value)) return false
            stats?.add(5)
            val opposite = if (isForward) backwardLocations else forwardLocations
            var meeting = false
            opposite.visitAroundWhile(STATIC, value.fact.path.toIntArray()) { other ->
                meeting = if (isForward) joins(value, other) else joins(other, value)
                !meeting
            }
            if (meeting) return true
            (if (isForward) forward else backward).addLast(value)
            (if (isForward) forwardLocations else backwardLocations).add(STATIC, value.fact.path.toIntArray(), value)
            return false
        }
        admit(input, false)
        // A location probe can answer before enumerating producers of this mark elsewhere.
        if (view.hasMarkedOutput(input, mark)) return true
        val roots = view.markedOutputs(mark).iterator()
        var rootsOpen = true
        var estimatedRoots = view.estimatedMarkedOutputs(mark)
        while (rootsOpen || forward.isNotEmpty() || backward.isNotEmpty()) {
            ap.cancellation.checkpoint()
            // Count unexamined roots as forward work when choosing the smaller frontier.
            val forwardWork = forward.size.toLong() + if (rootsOpen) estimatedRoots else 0
            val chooseBackward = backward.isNotEmpty() &&
                (forwardWork == 0L || backward.size.toLong() <= forwardWork)
            if (chooseBackward) {
                val at = backward.removeFirst()
                if (view.hasMarkedOutput(at, mark)) return true
                for (row in view.incoming(at, flowOnly = true))
                    if (joins(row.to, at) && admit(row.from, false)) return true
            } else {
                if (rootsOpen) {
                    if (roots.hasNext()) {
                        estimatedRoots = maxOf(0, estimatedRoots - 1)
                        stats?.add(4)
                        if (admit(roots.next(), true)) return true
                    } else { rootsOpen = false; estimatedRoots = 0 }
                }
                if (forward.isNotEmpty()) {
                    val output = forward.removeFirst()
                    for (row in view.outgoing(output)) if (joins(output, row.from) && admit(row.to, true)) return true
                }
            }
        }
        // Exhaust every eligible producer and both closures before a negative answer.
        return false
    }
}

package org.opentaint.dataflow.bidi.store

import it.unimi.dsi.fastutil.ints.IntArrayList
import it.unimi.dsi.fastutil.ints.IntLinkedOpenHashSet
import it.unimi.dsi.fastutil.longs.Long2IntOpenHashMap
import it.unimi.dsi.fastutil.longs.Long2ObjectLinkedOpenHashMap
import it.unimi.dsi.fastutil.longs.LongArrayList
import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.ap.ifds.FieldAccessor
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.graph.PortId
import org.opentaint.dataflow.util.Cancellation
import org.opentaint.ir.api.common.CommonMethod
import java.util.Collections
import java.util.concurrent.atomic.AtomicLongArray

/** Virtual demand only. A lookup neither starts a query nor changes publication permission. */
interface FrozenCompletion {
    fun statistics(): String = "unavailable"
    /** Scope adapters share this snapshot's bridge graph. C2 unions exits; C5 selects one. */
    fun scopedViews(): Sequence<Pair<OwnedScope, FrozenCompletion>> = emptySequence()
    fun selectExit(exit: PortId?): FrozenCompletion = this

    /** Immutable primitive seed indexes. LOCAL has own common-method B plus exact-context W/R. */
    fun local(method: MethodKey): StaticDemandView
    fun visible(method: MethodKey): StaticDemandView

    /** Conservative target envelope: visibility can be ignored, emission cannot. */
    fun visitPossibleTargets(method: MethodKey, actual: Pattern, visit: (Pattern, Boolean) -> Boolean): Boolean
    fun mayNeedInheritedEntries(method: MethodKey, actual: List<Pattern>): Boolean
    fun mayNeedInheritedPairs(method: MethodKey): Boolean
}

interface StaticDemandView {
    /** Anonymous terminal readers have an AP input, but no AP output or output mark. */
    fun targetInputs(): Sequence<Pattern> = emptySequence()
    fun entries(actual: Pattern): Sequence<Pattern>
    fun targets(actual: Pattern, prefixesOnly: Boolean = false): Sequence<StaticGuidanceEdge>
    fun flowTargets(actual: Pattern): Sequence<StaticGuidanceEdge>
    fun pairs(initial: InitialAp, outputs: List<Pattern>): Sequence<StaticGuidanceEdge>
    fun incoming(input: Pattern, flowOnly: Boolean = false): Sequence<StaticGuidanceEdge>
    fun outgoing(output: Pattern): Sequence<StaticGuidanceEdge>
    fun markedOutputs(mark: TaintMark): Sequence<Pattern>
    fun estimatedMarkedOutputs(mark: TaintMark): Long
    fun hasMarkedOutput(input: Pattern, mark: TaintMark): Boolean
    fun hasComposedEndpoints(initial: InitialAp, outputs: List<Pattern>): Boolean
}

/** Handoff keeps STAR correlation. Only abstract demand drops its field exclusion. */
fun guidancePattern(pattern: Pattern): Pattern {
    val located = if (pattern.fact.tail == Tail.ANY_TAINT)
        pattern.copy(fact = pattern.fact.copy(tail = Tail.ANY), exclusion = ExclusionSet.Empty)
    else pattern
    val mark = if (located.fact.mark is MarkSlot.Star) MarkSlot.STAR else located.fact.mark
    return normalizeDemandFieldExclusion(located.copy(fact = located.fact.copy(
        path = Collections.unmodifiableList(ArrayList(located.fact.path)), mark = mark)))
}

/** Endpoints retain geometry; only the mark relation composes.
 * Null denotes the absence of a data mark at a typed ZERO or terminal endpoint. */
sealed interface GuidanceMarks {
    data object Flow : GuidanceMarks
    data class Mapped(val input: TaintMark?, val output: TaintMark?) : GuidanceMarks
}

data class StaticGuidanceEdge(val from: Pattern, val to: Pattern, val marks: GuidanceMarks) {
    companion object {
        fun of(from: Pattern, to: Pattern): StaticGuidanceEdge {
            val a = guidancePattern(from)
            val b = guidancePattern(to)
            val marks = if (a.fact.mark is MarkSlot.Star && b.fact.mark is MarkSlot.Star) GuidanceMarks.Flow
            else {
                // K6/S7: a FLOW original has only FLOW conclusions. Concrete guarded
                // GEN uses a concrete origin (or the real ZERO), never a mixed row.
                check(a.fact.mark is MarkSlot.Concrete && b.fact.mark is MarkSlot.Concrete) {
                    "A colored guidance row needs concrete endpoints; FLOW is diagonal"
                }
                GuidanceMarks.Mapped(
                    if (a.fact.base == AccessPathBase.Zero) null else a.fact.mark.mark,
                    if (b.fact.base == AccessPathBase.Zero) null else b.fact.mark.mark,
                )
            }
            return StaticGuidanceEdge(a, b, marks)
        }
    }
}

/** A geometry key has no runtime mark. Raw EXACT/FLOW patterns here are metadata only. */
internal data class GuidanceGeometry(val from: Pattern, val to: Pattern) {
    fun edge(label: Long): StaticGuidanceEdge = edge(unpackBridgeMarks(label))
    fun edge(marks: GuidanceMarks): StaticGuidanceEdge = when (marks) {
        GuidanceMarks.Flow -> StaticGuidanceEdge(from, to, marks)
        is GuidanceMarks.Mapped -> StaticGuidanceEdge(
            from.copy(fact = from.fact.copy(mark = MarkSlot.Concrete(checkNotNull(marks.input)))),
            to.copy(fact = to.fact.copy(mark = MarkSlot.Concrete(checkNotNull(marks.output)))), marks)
    }
    companion object {
        fun of(edge: StaticGuidanceEdge) = GuidanceGeometry(
            edge.from.copy(fact = edge.from.fact.copy(mark = MarkSlot.STAR)),
            edge.to.copy(fact = edge.to.fact.copy(mark = MarkSlot.STAR)))
    }
}

/** B endpoints are static, so zero words are private sentinels, never runtime mark IDs. */
private fun packBridgeMarks(marks: GuidanceMarks): Long = when (marks) {
    GuidanceMarks.Flow -> 0L
    is GuidanceMarks.Mapped -> {
        val input = checkNotNull(marks.input).id.toLong() + 1L
        val output = checkNotNull(marks.output).id.toLong() + 1L
        (input shl 32) or (output and 0xffffffffL)
    }
}
private fun unpackBridgeMarks(label: Long): GuidanceMarks = if (label == 0L) GuidanceMarks.Flow else
    GuidanceMarks.Mapped(TaintMark((label ushr 32).toInt() - 1), TaintMark(label.toInt() - 1))

/** Run-1 actors share B geometry once and pack its exact mark pairs in primitive words. */
class StaticGuidanceInterner(private val ap: ApManager) {
    private val geometryIds = HashMap<GuidanceGeometry, Int>()
    private val geometries = ArrayList<GuidanceGeometry>()
    private val ids = ArrayList<Long2IntOpenHashMap>()
    private val rowGeometry = IntArrayList()
    private val rowLabels = LongArrayList()
    @Synchronized fun intern(edge: StaticGuidanceEdge): Int {
        ap.cancellation.checkpoint()
        val geometry = GuidanceGeometry.of(edge)
        val geometryId = geometryIds.getOrPut(geometry) {
            geometries.size.also { geometries += geometry; ids += Long2IntOpenHashMap().apply { defaultReturnValue(-1) } }
        }
        val label = packBridgeMarks(edge.marks)
        val old = ids[geometryId].get(label)
        if (old >= 0) return old
        val id = rowGeometry.size
        rowGeometry.add(geometryId)
        rowLabels.add(label)
        ids[geometryId].put(label, id)
        return id
    }
    @Synchronized fun row(id: Int): StaticGuidanceEdge = geometries[rowGeometry.getInt(id)].edge(rowLabels.getLong(id))
    @Synchronized fun clear() { geometryIds.clear(); geometries.clear(); ids.clear(); rowGeometry.clear(); rowLabels.clear() }
}

class StaticGuidanceSeedStore(
    private val ap: ApManager,
    private val ops: ApOps,
    private val interner: StaticGuidanceInterner,
) {
    private val memberships = IntLinkedOpenHashSet()

    /** Called after exit rules, before live static/static suppression. No Facts are retained. */
    fun add(original: PremiseKey, result: Facts) {
        ap.cancellation.checkpoint()
        if (!RuntimeDataDomain.packet(original, result)) return
        check(original is InitialAp) { "Run-1 cannot contain an ND original" }
        if (original.base != STATIC || result.base != STATIC) return
        val from = original.toPattern()
        if (staticAnchor(ap, from) == null) return // broad carry is a separate symbolic family
        for (leaf in ops.leaves(result)) {
            ap.cancellation.checkpoint()
            if (staticAnchor(ap, leaf) != null) memberships.add(interner.intern(StaticGuidanceEdge.of(from, leaf)))
        }
    }

    fun frozenRows(): Sequence<StaticGuidanceEdge> = sequence {
        val iterator = memberships.iterator()
        while (iterator.hasNext()) { ap.cancellation.checkpoint(); yield(interner.row(iterator.nextInt())) }
    }
}

internal data class StaticAnchor(val owner: Int, val field: Int?)

/** Exact class markers do not denote the fields of the class. Root/class FLOW is not a graph vertex. */
internal fun staticAnchor(ap: ApManager, pattern: Pattern): StaticAnchor? {
    if (pattern.fact.base != STATIC) return null
    val path = pattern.fact.path
    if (path.isEmpty() || !path[0].isClass()) return null
    if (path.size >= 2 && ap.accessors.accessor(path[1]) is FieldAccessor) return StaticAnchor(path[0], path[1])
    return if (path.size == 1 && pattern.fact.tail == Tail.EXACT) StaticAnchor(path[0], null) else null
}

/** Only IDs and immutable adjacency survive prescan. No statement, runner or subscription is retained. */
class DetachedStaticCallGraph private constructor(
    private val ids: Map<CommonMethod, Int>,
    private val adjacency: Array<IntArray>,
) {
    val methodCount: Int get() = adjacency.size
    val edgeCount: Long get() = adjacency.sumOf { it.size.toLong() }

    internal fun id(method: CommonMethod): Int? = ids[method]
    internal fun outDegree(methodId: Int): Int = adjacency[methodId].size
    internal fun calleeAt(methodId: Int, position: Int): Int = adjacency[methodId][position]

    companion object {
        val EMPTY = DetachedStaticCallGraph(emptyMap(), emptyArray())
        fun copyOf(source: Map<CommonMethod, Set<CommonMethod>>, cancellation: Cancellation): DetachedStaticCallGraph {
            val ids = LinkedHashMap<CommonMethod, Int>()
            for ((caller, callees) in source) {
                cancellation.checkpoint()
                ids.getOrPut(caller) { ids.size }
                for (callee in callees) { cancellation.checkpoint(); ids.getOrPut(callee) { ids.size } }
            }
            val adjacency = Array(ids.size) { IntArray(0) }
            for ((caller, callees) in source) {
                cancellation.checkpoint()
                adjacency[ids.getValue(caller)] = callees.map { cancellation.checkpoint(); ids.getValue(it) }.toIntArray()
            }
            return DetachedStaticCallGraph(Collections.unmodifiableMap(ids), adjacency)
        }
    }
}

/** Incoming run-2 graph. B keys are shared; W/R remain attached to their complete MethodKey. */
class FrozenStaticCompletion private constructor(
    private val ap: ApManager,
    private val graph: DetachedStaticCallGraph,
    private val bridges: List<BridgeRows>,
    private val bridgeEnds: PathTrie<Int>,
    private val bridgeStarts: PathTrie<Int>,
    private val flowStarts: PathTrie<Int>,
    private val flowEnds: PathTrie<Int>,
    private val coloredBridgeOutputs: SelectorRows,
    private val bridgeOwners: Set<CommonMethod>,
    private val ownBridges: Map<CommonMethod, LongArray>,
    private val bridgeEntryRows: List<EntryRows>,
    private val bridgeEntries: EntryDirectory,
    private val packedCatalog: PackedGuidanceCatalog,
    private val locals: Map<MethodKey, Attachments>,
    private val terminalReaders: Map<MethodKey, PackedEndpointRows>,
    private val scopedLocals: Map<ScopedSummaryKey, Attachments>,
    private val scopedTerminals: Map<ScopedSummaryKey, PackedEndpointRows>,
    private val scopedPorts: Set<ScopedSummaryKey>,
    private val ownerVisibility: FrozenOwnerVisibility,
    val seedMemberships: Long,
    val writerAttachments: Long,
    val readerAttachments: Long,
) : FrozenCompletion {
    // Opt-in query totals only. The immutable graph relation is shared by all views.
    private val ownerStatistics = if (java.lang.Boolean.getBoolean("org.opentaint.bidi.optimizationStatistics"))
        AtomicLongArray(4) else null
    val seedKeys: Int get() = bridges.sumOf { it.labels.size }
    val seedGeometries: Int get() = bridges.size
    override fun statistics(): String = "seedKeys=$seedKeys seedEntryKeys=${bridgeEntryRows.size} seedGeometries=$seedGeometries ownerMemberships=$seedMemberships " +
        "writerAttachments=$writerAttachments readerAttachments=$readerAttachments " +
        "boundaryGeometries=${packedCatalog.geometryCount} endpointGeometries=${packedCatalog.endpointCount} " +
        "terminalAttachments=${terminalReaders.values.sumOf { it.size.toLong() } + scopedTerminals.values.sumOf { it.size.toLong() }} " +
        "scopedAttachmentPairs=${scopedLocals.size} scopedControlPairs=${scopedPorts.size} " +
        "callMethods=${graph.methodCount} callEdges=${graph.edgeCount} " +
        "ownBridgeMemberships=${ownBridges.values.sumOf { it.size.toLong() }} ownerFamilies=${ownerVisibility.familyCount} " +
        ownerVisibility.statistics.let {
            "ownerComponents=${it.components} ownerDagEdges=${it.dagEdges} ownerIndexSeedMemberships=${it.seedMemberships} " +
                "ownerIndexWords=${it.allocatedWords} ownerIndexBytes=${it.allocatedWords * Long.SIZE_BYTES} ownerIndexBuildNanos=${it.buildNanos}"
        } + (ownerStatistics?.let {
            " ownerBitQueries=${it[0]} ownerBitHits=${it[1]} ownerOutsideQueries=${it[2]} ownerOutsideHits=${it[3]}"
        } ?: "")
    private class Owners(val familyId: Int, val graphIds: IntArray, val outsideGraph: Set<CommonMethod>)
    private class BridgeRows(val geometry: GuidanceGeometry, val labels: LongArray, val owners: List<Owners>,
                             val outputs: StaticOutputOrdinals)
    private class EntryGeometryRows(val rowIds: IntArray, val outputs: StaticOutputOrdinals)
    /** The directory retains metadata and primitive entry IDs, never a decoded W/R catalog. */
    private class EntryDirectory(val entries: StaticEndpointRows,
                                 val blocks: List<EntryGeometryRows>, val spatial: PathTrie<Int>) {
        fun visit(actual: Pattern, selection: StaticLabelSelection, visit: (Pattern, Int) -> Boolean): Boolean =
            spatial.visitAroundWhile(actual.fact.base, actual.fact.path.toIntArray()) { id ->
                val block = blocks[id]
                block.outputs.visit(selection) { i ->
                    val row = block.rowIds[i]
                    visit(entries.pattern(row), row)
                }
            }
        companion object {
            fun build(ap: ApManager, entries: StaticEndpointRows): EntryDirectory {
                val grouped = LinkedHashMap<Pattern, MutableList<Int>>()
                for (id in 0 until entries.size) {
                    ap.cancellation.checkpoint()
                    grouped.getOrPut(entries.geometry(id)) { ArrayList() }.add(id)
                }
                val spatial = PathTrie<Int>(ap.cancellation)
                val blocks = ArrayList<EntryGeometryRows>(grouped.size)
                for ((geometry, ids) in grouped) {
                    val outputs = StaticOutputOrdinals.Builder(ap.marks)
                    for (id in ids) outputs.add(entries.marks(id))
                    spatial.add(geometry.fact.base, geometry.fact.path.toIntArray(), blocks.size)
                    blocks += EntryGeometryRows(ids.toIntArray(), outputs.build())
                }
                return EntryDirectory(entries, blocks, spatial)
            }
            fun build(ap: ApManager, entries: List<Pattern>): EntryDirectory = build(ap, object : StaticEndpointRows {
                override val size: Int get() = entries.size
                override fun geometry(id: Int): Pattern = entries[id].let { it.copy(fact = it.fact.copy(mark = MarkSlot.STAR)) }
                override fun pattern(id: Int): Pattern = entries[id]
                override fun marks(id: Int): GuidanceMarks = when (val mark = entries[id].fact.mark) {
                    is MarkSlot.Star -> GuidanceMarks.Flow
                    is MarkSlot.Concrete -> GuidanceMarks.Mapped(null,
                        if (entries[id].fact.base == AccessPathBase.Zero) null else mark.mark)
                }
            })
        }
    }
    private class EntryRows(val entry: Pattern, val owners: Owners)
    private class BoundaryGeometryRows(val ids: IntArray, val geometry: GuidanceGeometry,
                                       val outputs: StaticOutputOrdinals)
    /** Local row IDs stay unchanged; the trie now selects their complete geometry first. */
    private class BoundaryDirectory(val blocks: List<BoundaryGeometryRows>, val spatial: PathTrie<Int>) {
        fun ids(base: AccessPathBase, path: IntArray, prefixes: Boolean = false,
                query: StaticRowQuery = StaticRowQuery.ALL): Sequence<Int> = sequence {
            val candidates = if (prefixes) spatial.lookupPrefixes(base, path) else spatial.around(base, path)
            for (id in candidates) {
                val block = blocks[id]
                val selection = if (query.mappedGeometryAllowed(block.geometry.to)) query.labels else StaticLabelSelection.FlowOnly
                val ordinals = block.outputs.ordinals(selection, query.includeFlow)
                while (ordinals.hasNext()) yield(block.ids[ordinals.nextInt()])
            }
        }
        fun around(base: AccessPathBase, path: IntArray): List<Int> = ids(base, path).toList()
        fun lookupPrefixes(base: AccessPathBase, path: IntArray): List<Int> = ids(base, path, true).toList()
        fun visitAroundWhile(base: AccessPathBase, path: IntArray, visit: (Int) -> Boolean): Boolean {
            for (id in ids(base, path)) if (!visit(id)) return false
            return true
        }
        companion object {
            fun build(ap: ApManager, rows: PackedGuidanceRows): BoundaryDirectory {
                val grouped = LinkedHashMap<GuidanceGeometry, MutableList<Int>>()
                for (id in 0 until rows.size) {
                    ap.cancellation.checkpoint()
                    grouped.getOrPut(rows.geometry(id)) { ArrayList() }.add(id)
                }
                val spatial = PathTrie<Int>(ap.cancellation)
                val blocks = ArrayList<BoundaryGeometryRows>(grouped.size)
                for ((geometry, ids) in grouped) {
                    val outputs = StaticOutputOrdinals.Builder(ap.marks)
                    for (id in ids) { ap.cancellation.checkpoint(); outputs.add(rows.marks(id)) }
                    spatial.add(geometry.to.fact.base, geometry.to.fact.path.toIntArray(), blocks.size)
                    blocks += BoundaryGeometryRows(ids.toIntArray(), geometry, outputs.build())
                }
                return BoundaryDirectory(blocks, spatial)
            }
        }
    }
    private class Attachments(
        val writerRows: PackedGuidanceRows,
        val writers: BoundaryDirectory,
        val writerSources: PathTrie<Int>,
        val readerRows: PackedGuidanceRows,
        val readers: BoundaryDirectory,
        val coloredOutputs: SelectorRows,
        val writerEntries: EntryDirectory,
        val readerEntries: EntryDirectory,
        val flowReaders: PathTrie<Int>,
        val readerSources: PathTrie<Int>,
    )
    /** Exact FULL and GROUP buckets do not need a group atom to probe an actual full mark. */
    private class SelectorRows(private val ap: ApManager) {
        private val exact = HashMap<TaintMark, LongArrayList>()
        private val groups = HashMap<GroupId, LongArrayList>()
        fun add(mark: TaintMark, row: Long) {
            ap.cancellation.checkpoint()
            if (mark == TaintMark.ZERO) return
            val map = if (ap.marks.isGroup(mark)) null else exact.getOrPut(mark) { LongArrayList() }
            if (map != null) map.add(row)
            else groups.getOrPut(ap.marks.groupOf(mark)) { LongArrayList() }.add(row)
        }
        fun candidates(mark: TaintMark): Sequence<Long> = sequence {
            if (mark == TaintMark.ZERO) return@sequence
            for (rows in listOfNotNull(exact[mark], groups[ap.marks.groupOf(mark)])) {
                val cursor = rows.iterator()
                while (cursor.hasNext()) { ap.cancellation.checkpoint(); yield(cursor.nextLong()) }
            }
        }
        fun estimate(mark: TaintMark): Long = if (mark == TaintMark.ZERO) 0 else
            (exact[mark]?.size?.toLong() ?: 0) + (groups[ap.marks.groupOf(mark)]?.size?.toLong() ?: 0)
    }


    private val scopedKeys: Map<OwnedScope, List<ScopedSummaryKey>> =
        (scopedPorts + scopedLocals.keys + scopedTerminals.keys).distinct().groupBy {
            OwnedScope(it.method, it.reversed().scope)
        }

    override fun scopedViews(): Sequence<Pair<OwnedScope, FrozenCompletion>> = scopedKeys.asSequence().map { (owner, keys) ->
        owner to ScopedView(owner, keys)
    }

    override fun local(method: MethodKey): StaticDemandView = View(method, false)
    override fun visible(method: MethodKey): StaticDemandView = View(method, true)
    override fun mayNeedInheritedPairs(method: MethodKey): Boolean =
        bridgeOwners.isNotEmpty() && !(bridgeOwners.size == 1 && method.method in bridgeOwners)

    override fun mayNeedInheritedEntries(method: MethodKey, actual: List<Pattern>): Boolean =
        mayNeedInheritedEntries(method, actual, locals[method])

    private fun mayNeedInheritedEntries(method: MethodKey, actual: List<Pattern>, local: Attachments?): Boolean {
        if (bridgeOwners.isEmpty() || bridgeOwners.size == 1 && method.method in bridgeOwners) return false
        for (leaf in actual) {
            ap.cancellation.checkpoint()
            if (leaf.fact.base == STATIC) {
                if (!bridgeEnds.visitAroundWhile(STATIC, leaf.fact.path.toIntArray()) { false }) return true
            } else if (leaf.fact.mark is MarkSlot.Concrete && leaf.fact.mark.mark != TaintMark.ZERO && local != null) {
                if (!local.readers.visitAroundWhile(leaf.fact.base, leaf.fact.path.toIntArray()) {
                        local.readerRows.marks(it) != GuidanceMarks.Flow
                    }) return true
            }
        }
        return false
    }

    override fun visitPossibleTargets(method: MethodKey, actual: Pattern, visit: (Pattern, Boolean) -> Boolean): Boolean =
        visitPossibleTargets(actual, locals[method], includeBridges = true, visit)

    private fun visitPossibleTargets(actual: Pattern, local: Attachments?, includeBridges: Boolean,
                                     visit: (Pattern, Boolean) -> Boolean): Boolean {
        val localIndex = if (actual.fact.base == STATIC) local?.writerEntries else local?.readerEntries
        val selection = outputCovering(actual, ap.marks)
        if (localIndex != null && !localIndex.visit(actual, selection) { entry, _ ->
                ap.cancellation.checkpoint()
                visit(entry, entry.fact.mark is MarkSlot.Star)
            }) return false
        if (!includeBridges || actual.fact.base != STATIC) return true
        return bridgeEntries.visit(actual, selection) { entry, _ ->
            ap.cancellation.checkpoint()
            visit(entry, entry.fact.mark is MarkSlot.Star)
        }
    }

    private inner class ScopedView(private val owner: OwnedScope,
                                   private val keys: List<ScopedSummaryKey>) : FrozenCompletion {
        override fun statistics(): String = "scopedRows=${keys.size} shared=true ${this@FrozenStaticCompletion.statistics()}"

        override fun selectExit(exit: PortId?): FrozenCompletion = if (exit == null) this
            else ScopedView(owner, keys.filter { it.scope.entry == exit })

        private fun view(method: MethodKey, inherited: Boolean): StaticDemandView {
            require(method == owner.method) { "A scoped completion retains its original method key" }
            val selected = keys.map { View(method, inherited, scopedLocals[it], scopedTerminals[it]) }
            return if (selected.isEmpty()) View(method, inherited, null, null)
                else unionStaticDemandViews(selected)
        }

        override fun local(method: MethodKey): StaticDemandView = view(method, false)
        override fun visible(method: MethodKey): StaticDemandView = view(method, true)
        override fun mayNeedInheritedPairs(method: MethodKey): Boolean =
            this@FrozenStaticCompletion.mayNeedInheritedPairs(method)

        override fun mayNeedInheritedEntries(method: MethodKey, actual: List<Pattern>): Boolean {
            require(method == owner.method)
            if (keys.isEmpty()) return this@FrozenStaticCompletion.mayNeedInheritedEntries(method, actual, null)
            return keys.any { this@FrozenStaticCompletion.mayNeedInheritedEntries(method, actual, scopedLocals[it]) }
        }

        override fun visitPossibleTargets(method: MethodKey, actual: Pattern,
                                          visit: (Pattern, Boolean) -> Boolean): Boolean {
            require(method == owner.method)
            for (key in keys) if (!this@FrozenStaticCompletion.visitPossibleTargets(actual, scopedLocals[key],
                    includeBridges = false, visit)) return false
            return this@FrozenStaticCompletion.visitPossibleTargets(actual, null, includeBridges = true, visit)
        }
    }

    private inner class View(private val method: MethodKey, private val inherited: Boolean,
                             private val local: Attachments? = locals[method],
                             private val terminalInputs: PackedEndpointRows? = terminalReaders[method]) : C5StaticDemandView {
        override fun targetInputs(): Sequence<Pattern> = terminalInputs?.patterns() ?: emptySequence()
        private val ownId = graph.id(method.method)
        private val ownRows = ownBridges[method.method] ?: LongArray(0)
        private fun eligible(owners: Owners): Boolean {
            ap.cancellation.checkpoint()
            if (!inherited) return method.method in owners.outsideGraph ||
                (ownId != null && owners.graphIds.binarySearch(ownId) >= 0)
            ownerStatistics?.incrementAndGet(2)
            if (method.method in owners.outsideGraph) {
                ownerStatistics?.incrementAndGet(3)
                return true
            }
            ap.cancellation.checkpoint()
            ownerStatistics?.incrementAndGet(0)
            val answer = ownerVisibility.contains(ownId, owners.familyId)
            if (answer) ownerStatistics?.incrementAndGet(1)
            return answer
        }

        private fun rows(id: Int, flowOnly: Boolean = false,
                         keep: StaticCandidateFilter? = null,
                         query: StaticRowQuery = StaticRowQuery.ALL): Sequence<StaticGuidanceEdge> = sequence {
            val row = bridges[id]
            val selection = if (flowOnly) StaticLabelSelection.FlowOnly else query.labels
            val allowMapped = query.mappedGeometryAllowed(row.geometry.to)
            val ordinals = row.outputs.ordinals(if (allowMapped) selection else StaticLabelSelection.FlowOnly, query.includeFlow)
            while (ordinals.hasNext()) {
                ap.cancellation.checkpoint()
                val i = ordinals.nextInt()
                val label = row.labels[i]
                val marks = if (keep == null) null else unpackBridgeMarks(label)
                if (keep != null && !keep.keep(row.geometry.from, row.geometry.to, checkNotNull(marks))) continue
                val allowed = if (inherited) eligible(row.owners[i])
                    else ownRows.binarySearch((id.toLong() shl 32) or i.toLong()) >= 0
                if (allowed) yield(if (marks == null) row.geometry.edge(label) else row.geometry.edge(marks))
            }
        }
        private fun candidates(index: PathTrie<Int>, pattern: Pattern, prefixes: Boolean): List<Int> =
            if (prefixes) index.lookupPrefixes(pattern.fact.base, pattern.fact.path.toIntArray())
            else index.around(pattern.fact.base, pattern.fact.path.toIntArray())

        private fun entries(directory: EntryDirectory, actual: Pattern, selection: StaticLabelSelection,
                            bridge: Boolean): Sequence<Pattern> = sequence {
            for (id in directory.spatial.around(actual.fact.base, actual.fact.path.toIntArray())) {
                val block = directory.blocks[id]
                val ordinals = block.outputs.ordinals(selection)
                while (ordinals.hasNext()) {
                    ap.cancellation.checkpoint()
                    val i = ordinals.nextInt()
                    val entry = directory.entries.pattern(block.rowIds[i])
                    if (!markSub(entry.fact.mark, actual.fact.mark, ap.marks)) continue
                    // Full MethodKey already scopes local W/R. Only B projections check owners.
                    if (bridge && !eligible(bridgeEntryRows[block.rowIds[i]].owners)) continue
                    yield(entry)
                }
            }
        }
        override fun entries(actual: Pattern): Sequence<Pattern> = sequence {
            val selection = outputCovering(actual, ap.marks)
            val localEntries = if (actual.fact.base == STATIC) local?.writerEntries else local?.readerEntries
            if (localEntries != null) yieldAll(entries(localEntries, actual, selection, false))
            if (actual.fact.base == STATIC) yieldAll(entries(bridgeEntries, actual, selection, true))
        }

        override fun targets(actual: Pattern, prefixesOnly: Boolean): Sequence<StaticGuidanceEdge> =
            targetsImpl(actual, prefixesOnly, null)
        override fun c5Targets(actual: Pattern, prefixesOnly: Boolean, keep: StaticCandidateFilter) =
            targetsImpl(actual, prefixesOnly, keep)
        override fun selectedTargets(actual: Pattern, prefixesOnly: Boolean, query: StaticRowQuery,
                                     keep: StaticCandidateFilter) = targetsImpl(actual, prefixesOnly, keep, query)
        private fun targetsImpl(actual: Pattern, prefixesOnly: Boolean,
                                keep: StaticCandidateFilter?, query: StaticRowQuery = StaticRowQuery.ALL): Sequence<StaticGuidanceEdge> = sequence {
            ap.cancellation.checkpoint()
            if (local != null) {
                val index = if (actual.fact.base == STATIC) local.writers else local.readers
                val rows = if (actual.fact.base == STATIC) local.writerRows else local.readerRows
                for (id in index.ids(actual.fact.base, actual.fact.path.toIntArray(), prefixesOnly, query)) {
                    ap.cancellation.checkpoint()
                    rows.keptEdge(id, keep)?.let { yield(it) }
                }
            }
            if (actual.fact.base == STATIC) for (id in candidates(bridgeEnds, actual, prefixesOnly))
                yieldAll(rows(id, keep = keep, query = query))
        }

        override fun flowTargets(actual: Pattern): Sequence<StaticGuidanceEdge> = sequence {
            ap.cancellation.checkpoint()
            if (actual.fact.base == STATIC) {
                for (id in candidates(flowEnds, actual, false)) yieldAll(rows(id, true))
            } else if (local != null) for (id in candidates(local.flowReaders, actual, false)) {
                ap.cancellation.checkpoint(); yield(local.readerRows.edge(id))
            }
        }

        override fun pairs(initial: InitialAp, outputs: List<Pattern>): Sequence<StaticGuidanceEdge> = sequence {
            val path = initial.path?.toIntArray() ?: EMPTY_PATH
            val sourceIds = HashSet<Int>()
            if (local != null) {
                // Each ID is scoped to exactly one backing row family; never intersect W and R IDs.
                val sourceIndex = if (initial.base == STATIC) local.writerSources else local.readerSources
                for (output in outputs) sourceIndex.visitAround(output.fact.base, output.fact.path.toIntArray()) {
                    sourceIds += it
                }
                val targetIndex = if (initial.base == STATIC) local.writers else local.readers
                val rows = if (initial.base == STATIC) local.writerRows else local.readerRows
                for (id in targetIndex.lookupPrefixes(initial.base, path)) {
                    ap.cancellation.checkpoint()
                    if (id in sourceIds) yield(rows.edge(id))
                }
            }
            if (initial.base != STATIC) return@sequence
            sourceIds.clear()
            for (output in outputs) if (output.fact.base == STATIC)
                bridgeStarts.visitAround(STATIC, output.fact.path.toIntArray()) { sourceIds += it }
            for (id in bridgeEnds.lookupPrefixes(STATIC, path)) {
                ap.cancellation.checkpoint()
                if (id in sourceIds) yieldAll(rows(id))
            }
        }

        override fun incoming(input: Pattern, flowOnly: Boolean): Sequence<StaticGuidanceEdge> =
            incomingImpl(input, flowOnly, null)
        override fun c5Incoming(input: Pattern, flowOnly: Boolean, keep: StaticCandidateFilter) =
            incomingImpl(input, flowOnly, keep)
        override fun selectedIncoming(input: Pattern, query: StaticRowQuery,
                                      keep: StaticCandidateFilter) = incomingImpl(input, false, keep, query)
        private fun incomingImpl(input: Pattern, flowOnly: Boolean,
                                 keep: StaticCandidateFilter?, query: StaticRowQuery = StaticRowQuery.ALL): Sequence<StaticGuidanceEdge> = sequence {
            ap.cancellation.checkpoint()
            if (input.fact.base != STATIC) return@sequence
            val index = if (flowOnly) flowEnds else bridgeEnds
            for (id in candidates(index, input, false)) yieldAll(rows(id, flowOnly, keep, query))
            if (!flowOnly && local != null) for (id in local.writers.ids(input.fact.base, input.fact.path.toIntArray(), query = query)) {
                ap.cancellation.checkpoint()
                local.writerRows.keptEdge(id, keep)?.let { yield(it) }
            }
        }

        override fun outgoing(output: Pattern): Sequence<StaticGuidanceEdge> = sequence {
            ap.cancellation.checkpoint()
            for (id in candidates(flowStarts, output, false)) yieldAll(rows(id, true))
        }

        override fun markedOutputs(mark: TaintMark): Sequence<Pattern> = sequence {
            ap.cancellation.checkpoint()
            if (local != null) for (id in local.coloredOutputs.candidates(mark)) {
                val output = local.writerRows.to(id.toInt())
                if (ap.marks.coversAtom((output.fact.mark as MarkSlot.Concrete).mark, mark)) yield(output)
            }
            for (ref in coloredBridgeOutputs.candidates(mark)) {
                ap.cancellation.checkpoint()
                val rows = bridges[(ref ushr 32).toInt()]
                val i = ref.toInt()
                if (if (inherited) !eligible(rows.owners[i]) else ownRows.binarySearch(ref) < 0) continue
                val output = rows.geometry.edge(rows.labels[i]).to
                if (ap.marks.coversAtom((output.fact.mark as MarkSlot.Concrete).mark, mark)) yield(output)
            }
        }
        override fun estimatedMarkedOutputs(mark: TaintMark): Long =
            (local?.coloredOutputs?.estimate(mark) ?: 0) + coloredBridgeOutputs.estimate(mark)

        override fun hasComposedEndpoints(initial: InitialAp, outputs: List<Pattern>): Boolean =
            hasComposedEndpointsImpl(initial, outputs, null)
        override fun c5HasComposedEndpoints(initial: InitialAp, outputs: List<Pattern>,
                                            keepTarget: StaticCandidateFilter): Boolean =
            hasComposedEndpointsImpl(initial, outputs, keepTarget)
        override fun selectedHasComposedEndpoints(initial: InitialAp, outputs: List<Pattern>, query: StaticRowQuery,
                                                  keep: StaticCandidateFilter): Boolean =
            hasComposedEndpointsImpl(initial, outputs, keep, query)
        private fun hasComposedEndpointsImpl(initial: InitialAp, outputs: List<Pattern>,
                                             keepTarget: StaticCandidateFilter?, query: StaticRowQuery = StaticRowQuery.ALL): Boolean {
            ap.cancellation.checkpoint()
            val path = initial.path?.toIntArray() ?: EMPTY_PATH
            val target = if (initial.base == STATIC)
                bridgeEnds.lookupPrefixes(STATIC, path).any { rows(it, keep = keepTarget, query = query).iterator().hasNext() }
            else local?.readers?.ids(initial.base, path, true, query)?.any { id ->
                keepTarget == null || keepTarget.keep(local.readerRows.from(id), local.readerRows.to(id), local.readerRows.marks(id))
            } == true
            if (!target) return false
            for (leaf in outputs) {
                ap.cancellation.checkpoint()
                if (leaf.fact.base == STATIC) {
                    if (bridgeStarts.around(STATIC, leaf.fact.path.toIntArray()).any { rows(it).iterator().hasNext() }) return true
                } else if (local?.writerSources?.around(leaf.fact.base, leaf.fact.path.toIntArray())?.isNotEmpty() == true)
                    return true
            }
            return false
        }

        override fun hasMarkedOutput(input: Pattern, mark: TaintMark): Boolean {
            if (mark == TaintMark.ZERO) return false
            val query = StaticRowQuery(ap.marks.staticSelector(mark)?.let(StaticLabelSelection::OutputCovers)
                ?: StaticLabelSelection.All, includeFlow = false)
            fun matches(output: Pattern): Boolean = output.fact.mark is MarkSlot.Concrete &&
                ap.marks.coversAtom(output.fact.mark.mark, mark) && joins(output, input)
            if (local != null) for (id in local.writers.ids(STATIC, input.fact.path.toIntArray(), query = query)) {
                ap.cancellation.checkpoint()
                if (matches(local.writerRows.to(id))) return true
            }
            return !bridgeEnds.visitAroundWhile(STATIC, input.fact.path.toIntArray()) { id ->
                for (edge in rows(id, query = query)) if (edge.marks != GuidanceMarks.Flow && matches(edge.to)) return@visitAroundWhile false
                true
            }
        }

    }

    internal fun joins(output: Pattern, input: Pattern): Boolean =
        staticAnchor(ap, output) == staticAnchor(ap, input) && overlap(output, input)

    class Builder(private val ap: ApManager, private val graph: DetachedStaticCallGraph) {
        private val bridges = LinkedHashMap<GuidanceGeometry, Long2ObjectLinkedOpenHashMap<MutableSet<CommonMethod>>>()
        private val catalog = PackedGuidanceCatalog.Builder()
        private val localRows = LinkedHashMap<MethodKey, Pair<PackedGuidanceRows.Builder, PackedGuidanceRows.Builder>>()
        private val terminalReaders = LinkedHashMap<MethodKey, PackedEndpointRows.Builder>()
        private val scopedLocalRows = LinkedHashMap<ScopedSummaryKey, Pair<PackedGuidanceRows.Builder, PackedGuidanceRows.Builder>>()
        private val scopedTerminals = LinkedHashMap<ScopedSummaryKey, PackedEndpointRows.Builder>()
        private fun attachmentRows() = PackedGuidanceRows.Builder(catalog) to PackedGuidanceRows.Builder(catalog)
        private val scopedPorts = LinkedHashSet<ScopedSummaryKey>()

        /** An entered scope can borrow shared B/carry even without local W/R attachments. */
        fun addScopedBoundary(producer: ScopedSummaryKey) {
            ap.cancellation.checkpoint()
            scopedPorts += producer
        }

        /** Producer ports stay paired. The run-2 view reverses them without copying the graph. */
        fun addScopedSeed(producer: ScopedSummaryKey, from: Pattern, to: Pattern) {
            ap.cancellation.checkpoint()
            addScopedBoundary(producer)
            if (!RuntimeDataDomain.base(from.fact.base) || !RuntimeDataDomain.base(to.fact.base)) return
            val fromStatic = staticAnchor(ap, from) != null
            val toStatic = staticAnchor(ap, to) != null
            if (fromStatic && toStatic) addNormalizedBridge(producer.method, from, to)
            else {
                if (fromStatic == toStatic || !fromStatic && from.fact.base == STATIC || !toStatic && to.fact.base == STATIC) return
                val rows = scopedLocalRows.getOrPut(producer, ::attachmentRows)
                if (toStatic) rows.first.add(from, to) else rows.second.add(from, to)
            }
        }

        fun addScopedTarget(producer: ScopedSummaryKey, from: Pattern) {
            ap.cancellation.checkpoint()
            addScopedBoundary(producer)
            if (!RuntimeDataDomain.base(from.fact.base) || staticAnchor(ap, from) == null) return
            check(from.fact.mark is MarkSlot.Concrete)
            scopedTerminals.getOrPut(producer) { PackedEndpointRows.Builder(catalog) }.add(guidancePattern(from))
        }

        /** Only an anonymous DEMAND terminal is an endpoint of this guidance graph. */
        fun addTarget(method: MethodKey, from: Pattern) {
            ap.cancellation.checkpoint()
            if (!RuntimeDataDomain.base(from.fact.base) || staticAnchor(ap, from) == null) return
            check(from.fact.mark is MarkSlot.Concrete) { "A terminal reader needs a concrete input mark" }
            terminalReaders.getOrPut(method) { PackedEndpointRows.Builder(catalog) }.add(guidancePattern(from))
        }

        /** Phase B accepts only frozen seeds. Caller binding has finished and
         * no composition result is fed back to that earlier phase. */
        fun addSeed(method: MethodKey, from: Pattern, to: Pattern) {
            ap.cancellation.checkpoint()
            if (!RuntimeDataDomain.base(from.fact.base) || !RuntimeDataDomain.base(to.fact.base)) return
            val fromStatic = staticAnchor(ap, from) != null
            val toStatic = staticAnchor(ap, to) != null
            if (fromStatic && toStatic) addNormalizedBridge(method, from, to)
            else addBoundary(method, from, to)
        }

        fun addSeed(method: MethodKey, edge: StaticGuidanceEdge) = addSeed(method, edge.from, edge.to)

        private fun addNormalizedBridge(method: MethodKey, from: Pattern, to: Pattern) {
            val a = guidancePattern(from)
            val b = guidancePattern(to)
            // B keeps the same geometry, exact label codec and owner graph.
            val label = BoundaryMarkCodec.pack(a.fact.mark, b.fact.mark)
            addBridgeParts(method, GuidanceGeometry(a.copy(fact = a.fact.copy(mark = MarkSlot.STAR)),
                b.copy(fact = b.fact.copy(mark = MarkSlot.STAR))), label)
        }

        fun addBridge(method: MethodKey, edge: StaticGuidanceEdge) {
            ap.cancellation.checkpoint()
            check(staticAnchor(ap, edge.from) != null && staticAnchor(ap, edge.to) != null)
            addBridgeParts(method, GuidanceGeometry.of(edge), packBridgeMarks(edge.marks))
        }

        private fun addBridgeParts(method: MethodKey, geometry: GuidanceGeometry, label: Long) {
            val rows = bridges.getOrPut(geometry) { Long2ObjectLinkedOpenHashMap() }
            val owners = rows.get(label) ?: LinkedHashSet<CommonMethod>().also { rows.put(label, it) }
            owners += method.method
        }

        fun addBoundary(method: MethodKey, from: Pattern, to: Pattern) {
            ap.cancellation.checkpoint()
            if (!RuntimeDataDomain.base(from.fact.base) || !RuntimeDataDomain.base(to.fact.base)) return
            val fromStatic = staticAnchor(ap, from) != null
            val toStatic = staticAnchor(ap, to) != null
            if (fromStatic == toStatic) return
            // Do not reinterpret a broad static endpoint as a method-local attachment.
            if (!fromStatic && from.fact.base == STATIC || !toStatic && to.fact.base == STATIC) return
            val rows = localRows.getOrPut(method, ::attachmentRows)
            if (toStatic) rows.first.add(from, to) else rows.second.add(from, to)
        }

        fun build(): FrozenStaticCompletion {
            ap.cancellation.checkpoint()
            val frozenBridges = ArrayList<BridgeRows>()
            val ends = PathTrie<Int>(ap.cancellation)
            val starts = PathTrie<Int>(ap.cancellation)
            val flowStarts = PathTrie<Int>(ap.cancellation)
            val flowEnds = PathTrie<Int>(ap.cancellation)
            val coloredOutputs = SelectorRows(ap)
            val bridgeOwners = LinkedHashSet<CommonMethod>()
            val own = LinkedHashMap<CommonMethod, LongArrayList>()
            val projectedEntries = LinkedHashMap<Pattern, MutableSet<CommonMethod>>()
            var memberships = 0L
            val ownerFamilies = ArrayList<Owners>()
            fun freezeOwners(methods: Set<CommonMethod>): Owners {
                val owners = Owners(ownerFamilies.size,
                    methods.mapNotNull { ap.cancellation.checkpoint(); graph.id(it) }.toIntArray().also { it.sort() },
                    methods.filterTo(LinkedHashSet()) { ap.cancellation.checkpoint(); graph.id(it) == null })
                ownerFamilies += owners
                return owners
            }
            for ((geometry, rows) in bridges) {
                ap.cancellation.checkpoint()
                val labels = LongArray(rows.size)
                val owners = ArrayList<Owners>(rows.size)
                val ordinals = StaticOutputOrdinals.Builder(ap.marks)
                for ((index, row) in rows.long2ObjectEntrySet().withIndex()) {
                    ap.cancellation.checkpoint()
                    labels[index] = row.longKey
                    ordinals.add(unpackBridgeMarks(row.longKey))
                    val methods = row.value
                    val entry = geometry.edge(row.longKey).to
                    projectedEntries.getOrPut(entry) { LinkedHashSet() }.addAll(methods)
                    bridgeOwners += methods
                    for (method in methods) own.getOrPut(method) { LongArrayList() }
                        .add((frozenBridges.size.toLong() shl 32) or index.toLong())
                    memberships += methods.size
                    owners += freezeOwners(methods)
                    if (row.longKey == 0L) {
                        flowStarts.add(STATIC, geometry.from.fact.path.toIntArray(), frozenBridges.size)
                        flowEnds.add(STATIC, geometry.to.fact.path.toIntArray(), frozenBridges.size)
                    } else {
                        val output = (unpackBridgeMarks(row.longKey) as GuidanceMarks.Mapped).output!!
                        coloredOutputs.add(output, (frozenBridges.size.toLong() shl 32) or index.toLong())
                    }
                }
                ends.add(STATIC, geometry.to.fact.path.toIntArray(), frozenBridges.size)
                starts.add(STATIC, geometry.from.fact.path.toIntArray(), frozenBridges.size)
                frozenBridges += BridgeRows(geometry, labels, owners, ordinals.build())
            }
            val frozenCatalog = catalog.freeze()
            fun freezeAttachments(rows: Pair<PackedGuidanceRows.Builder, PackedGuidanceRows.Builder>): Attachments {
                ap.cancellation.checkpoint()
                val writerSources = PathTrie<Int>(ap.cancellation)
                val colors = SelectorRows(ap)
                val flowReaders = PathTrie<Int>(ap.cancellation)
                val readerSources = PathTrie<Int>(ap.cancellation)
                val writerRows = rows.first.freeze(frozenCatalog)
                val readerRows = rows.second.freeze(frozenCatalog)
                for (id in 0 until writerRows.size) {
                    ap.cancellation.checkpoint()
                    val from = writerRows.geometry(id).from
                    writerSources.add(from.fact.base, from.fact.path.toIntArray(), id)
                    writerRows.outputMark(id)?.let { colors.add(it, id.toLong()) }
                }
                for (id in 0 until readerRows.size) {
                    ap.cancellation.checkpoint()
                    val geometry = readerRows.geometry(id)
                    readerSources.add(geometry.from.fact.base, geometry.from.fact.path.toIntArray(), id)
                    if (readerRows.isFlow(id)) flowReaders.add(geometry.to.fact.base, geometry.to.fact.path.toIntArray(), id)
                }
                return Attachments(writerRows, BoundaryDirectory.build(ap, writerRows), writerSources,
                    readerRows, BoundaryDirectory.build(ap, readerRows), colors,
                    EntryDirectory.build(ap, rows.first.freezeEntries(frozenCatalog)),
                    EntryDirectory.build(ap, rows.second.freezeEntries(frozenCatalog)), flowReaders, readerSources)
            }
            val locals = localRows.mapValues { (_, rows) -> ap.cancellation.checkpoint(); freezeAttachments(rows) }
            val scoped = scopedLocalRows.mapValues { (_, rows) -> ap.cancellation.checkpoint(); freezeAttachments(rows) }
            val entryRows = ArrayList<EntryRows>()
            for ((entry, methods) in projectedEntries) {
                ap.cancellation.checkpoint()
                entryRows += EntryRows(entry, freezeOwners(methods))
            }
            // Both original B labels and their projected entry families now have stable IDs.
            val visibilityBuilder = FrozenOwnerVisibility.Builder(graph, ownerFamilies.size, ap.cancellation)
            for (family in ownerFamilies) {
                ap.cancellation.checkpoint()
                for (owner in family.graphIds) visibilityBuilder.seed(family.familyId, owner)
            }
            val visibility = visibilityBuilder.finish()
            return FrozenStaticCompletion(ap, graph, frozenBridges, ends, starts, flowStarts, flowEnds, coloredOutputs,
                Collections.unmodifiableSet(bridgeOwners), own.mapValues { it.value.toLongArray() },
                entryRows, EntryDirectory.build(ap, entryRows.map { it.entry }),
                frozenCatalog, Collections.unmodifiableMap(locals),
                Collections.unmodifiableMap(terminalReaders.mapValues { it.value.freeze(frozenCatalog) }),
                Collections.unmodifiableMap(scoped),
                Collections.unmodifiableMap(scopedTerminals.mapValues { it.value.freeze(frozenCatalog) }),
                Collections.unmodifiableSet(LinkedHashSet(scopedPorts)), visibility,
                memberships, localRows.values.sumOf { it.first.size.toLong() } + scopedLocalRows.values.sumOf { it.first.size.toLong() },
                localRows.values.sumOf { it.second.size.toLong() } + scopedLocalRows.values.sumOf { it.second.size.toLong() })
        }
    }
}

package org.opentaint.dataflow.bidi.store

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*

/** C5 retains the correlated source and target for every labelled path. */
internal class StaticPairLookup(private val ap: ApManager, private val completion: FrozenCompletion,
                                private val stats: DemandQueryStatistics?,
                                private val canStoreInitial: (Pattern, InitialAp) -> Boolean) {
    /** The terminal has no AP output. Each visited input is one complete path's origin. */
    fun walkTargetOrigins(method: MethodKey, visible: Boolean, offer: (Pattern) -> Boolean): Boolean {
        if (visible) stats?.add(11)
        val view = if (visible) completion.visible(method) else completion.local(method)
        val pending = ArrayDeque<Pattern>()
        val seen = HashSet<Pattern>()
        fun admit(input: Pattern) {
            ap.cancellation.checkpoint()
            if (seen.add(input)) { stats?.add(8); pending.addLast(input) } else stats?.add(13)
        }
        for (input in view.targetInputs()) admit(input)
        val keep = StaticCandidateFilter { _, _, _ -> true }
        while (pending.isNotEmpty()) {
            ap.cancellation.checkpoint()
            val input = pending.removeFirst()
            stats?.add(14)
            if (!offer(input)) return false
            if (input.fact.base != STATIC) continue
            // The null output belongs to the typed terminal, not to an AP ZERO sentinel.
            val right = GuidanceMarks.Mapped((input.fact.mark as MarkSlot.Concrete).mark, null)
            val query = StaticRowQuery(outputComposable(right.input, ap.marks))
            stats?.add(15)
            for (left in view.selectedIncoming(input, query, keep)) {
                ap.cancellation.checkpoint()
                stats?.add(16)
                if (!joins(left.to, input)) continue
                val marks = composeMarks(left.marks, right) ?: continue
                stats?.add(17)
                admit(endpoint(left.from, (marks as GuidanceMarks.Mapped).input, marks))
            }
        }
        return true
    }

    fun walk(method: MethodKey, original: PremiseKey, outputs: List<Pattern>, visible: Boolean,
             offer: (InitialAp, DemandPattern) -> Unit, covered: () -> Boolean) {
        if (visible) stats?.add(11)
        val view = if (visible) completion.visible(method) else completion.local(method)
        original.forEachMember { member ->
            val targetLabels = outputCovering(member.toPattern(), ap.marks)
            val fullOriginal = (targetLabels as? StaticLabelSelection.OutputCovers)?.actual is StaticMarkSelector.Full
            val targetQuery = StaticRowQuery(targetLabels) { right -> mappedRightMayEmit(member, right, fullOriginal) }
            val keepTarget = StaticCandidateFilter { _, to, marks -> mayKeep(member, to, marks) }
            if (!view.selectedHasComposedEndpoints(member, outputs, targetQuery, keepTarget)) return@forEachMember
            val pending = ArrayDeque<StaticGuidanceEdge>()
            val seen = HashSet<StaticGuidanceEdge>()
            fun admit(edge: StaticGuidanceEdge) {
                ap.cancellation.checkpoint()
                if (!mayKeep(member, edge.to, edge.marks)) return
                if (seen.add(edge)) { stats?.add(8); pending.addLast(edge) } else stats?.add(13)
            }
            for (edge in view.selectedTargets(member.toPattern(), true, targetQuery, keepTarget)) admit(edge)
            while (pending.isNotEmpty()) {
                ap.cancellation.checkpoint()
                val state = pending.removeFirst()
                stats?.add(14)
                offer(member, DemandPattern(state.to, state.from))
                if (covered()) return
                if (state.from.fact.base != STATIC) continue
                stats?.add(15)
                val keepIncoming = StaticCandidateFilter { _, _, leftMarks ->
                    val marks = composeMarks(leftMarks, state.marks)
                    marks != null && mayKeep(member, state.to, marks)
                }
                val incomingLabels = when (val marks = state.marks) {
                    GuidanceMarks.Flow -> if (mappedRightMayEmit(member, state.to, fullOriginal)) targetLabels else StaticLabelSelection.FlowOnly
                    is GuidanceMarks.Mapped -> outputComposable(marks.input, ap.marks)
                }
                for (left in view.selectedIncoming(state.from, StaticRowQuery(incomingLabels), keepIncoming)) {
                    stats?.add(16)
                    compose(left, state)?.let { stats?.add(17); admit(it) }
                }
            }
        }
    }

    /** A false result excludes mapped rows only. FLOW remains a possible repair route. */
    private fun mappedRightMayEmit(member: InitialAp, right: Pattern, fullOriginal: Boolean): Boolean {
        if (!fullOriginal || right.fact.base == AccessPathBase.Zero) return true
        val sameMark = right.copy(fact = right.fact.copy(mark = member.mark))
        return canStoreInitial(normalizeDemandFieldExclusion(sameMark), member)
    }

    private fun mayKeep(member: InitialAp, right: Pattern, marks: GuidanceMarks): Boolean = when (marks) {
        GuidanceMarks.Flow -> true // A mapped predecessor can still make its mark admissible.
        is GuidanceMarks.Mapped -> {
            val entry = if (right.fact.base == AccessPathBase.Zero) right
                else right.copy(fact = right.fact.copy(mark = MarkSlot.Concrete(checkNotNull(marks.output))))
            canStoreInitial(normalizeDemandFieldExclusion(entry), member).also { if (!it) stats?.add(12) }
        }
    }

    private fun composeMarks(left: GuidanceMarks, right: GuidanceMarks): GuidanceMarks? = when (left) {
        GuidanceMarks.Flow -> right
        is GuidanceMarks.Mapped -> when (right) {
            GuidanceMarks.Flow -> left
            is GuidanceMarks.Mapped -> if (left.output != null && right.input != null &&
                (ap.marks.coversAtom(left.output, right.input) || ap.marks.coversAtom(right.input, left.output)))
                GuidanceMarks.Mapped(left.input, right.output) else null
        }
    }

    private fun compose(left: StaticGuidanceEdge, right: StaticGuidanceEdge): StaticGuidanceEdge? {
        if (!joins(left.to, right.from)) return null
        val relation = composeMarks(left.marks, right.marks) ?: return null
        val mapped = relation as? GuidanceMarks.Mapped
        return StaticGuidanceEdge(endpoint(left.from, mapped?.input, relation), endpoint(right.to, mapped?.output, relation), relation)
    }

    private fun joins(output: Pattern, input: Pattern): Boolean =
        staticAnchor(ap, output) == staticAnchor(ap, input) && overlap(output, input)

    private fun endpoint(p: Pattern, mark: TaintMark?, relation: GuidanceMarks): Pattern = when {
        p.fact.base == AccessPathBase.Zero -> p // genuine ZERO, never a new full-mark sentinel
        relation == GuidanceMarks.Flow -> p.copy(fact = p.fact.copy(mark = MarkSlot.STAR))
        else -> p.copy(fact = p.fact.copy(mark = MarkSlot.Concrete(checkNotNull(mark))))
    }
}

package org.opentaint.dataflow.bidi.store

import it.unimi.dsi.fastutil.ints.IntArrayList
import org.opentaint.dataflow.bidi.ap.*

/** These detached keys never intern an atom or enumerate the members of a group. */
internal sealed interface StaticMarkSelector {
    data object Zero : StaticMarkSelector
    data class Full(val atom: TaintMark, val exact: ExactMark) : StaticMarkSelector
    data class Group(val id: GroupId) : StaticMarkSelector
}

internal fun MarkTable.staticSelector(atom: TaintMark): StaticMarkSelector? = when (val key = key(atom)) {
    is MarkAtomKey.Full -> StaticMarkSelector.Full(atom, key.mark)
    is MarkAtomKey.Group -> StaticMarkSelector.Group(key.id)
    MarkAtomKey.ControlZero -> null // A nonnull control atom is not an endpoint ZERO.
}

internal sealed interface StaticLabelSelection {
    data object All : StaticLabelSelection
    data object FlowOnly : StaticLabelSelection
    data class OutputCovers(val actual: StaticMarkSelector) : StaticLabelSelection
    data class OutputComposesWith(val input: StaticMarkSelector) : StaticLabelSelection
}

internal data class StaticRowQuery(
    val labels: StaticLabelSelection = StaticLabelSelection.All,
    val includeFlow: Boolean = true,
    val mappedGeometryAllowed: (Pattern) -> Boolean = { true },
) {
    companion object { val ALL = StaticRowQuery() }
}

internal fun outputCovering(actual: Pattern, marks: MarkTable): StaticLabelSelection = when (val mark = actual.fact.mark) {
    is MarkSlot.Star -> StaticLabelSelection.FlowOnly
    is MarkSlot.Concrete -> when {
        actual.fact.base == org.opentaint.dataflow.ap.ifds.AccessPathBase.Zero ->
            StaticLabelSelection.OutputCovers(StaticMarkSelector.Zero)
        else -> marks.staticSelector(mark.mark)?.let(StaticLabelSelection::OutputCovers) ?: StaticLabelSelection.All
    }
}

internal fun outputComposable(input: TaintMark?, marks: MarkTable): StaticLabelSelection =
    if (input == null) StaticLabelSelection.FlowOnly
    else marks.staticSelector(input)?.let(StaticLabelSelection::OutputComposesWith) ?: StaticLabelSelection.All

/** Sorted original ordinals. Every ordinal keeps its own complete relation and owner family. */
internal class StaticOutputOrdinals private constructor(
    val size: Int,
    val flowOrdinal: Int,
    private val full: Map<TaintMark, IntArray>?,
    private val group: Map<GroupId, IntArray>?,
    private val fullInGroup: Map<GroupId, IntArray>?,
    private val zero: IntArray?,
    private val unknown: Boolean,
) {
    /** At most two sorted postings plus FLOW. No duplicate is decoded or tested twice. */
    fun ordinals(selection: StaticLabelSelection, includeFlow: Boolean = true): IntIterator {
        if (selection == StaticLabelSelection.All || unknown && selection != StaticLabelSelection.FlowOnly)
            return object : IntIterator() {
                private var next = 0
                private fun skipFlow() { if (!includeFlow && next == flowOrdinal) next++ }
                override fun hasNext(): Boolean { skipFlow(); return next < size }
                override fun nextInt(): Int { check(hasNext()); return next++ }
            }
        var a: IntArray? = null
        var b: IntArray? = null
        when (selection) {
            StaticLabelSelection.All -> error("Handled above")
            StaticLabelSelection.FlowOnly -> Unit
            is StaticLabelSelection.OutputCovers -> when (val key = selection.actual) {
                StaticMarkSelector.Zero -> a = zero
                is StaticMarkSelector.Full -> { a = full?.get(key.atom); b = group?.get(key.exact.group) }
                is StaticMarkSelector.Group -> a = group?.get(key.id)
            }
            is StaticLabelSelection.OutputComposesWith -> when (val key = selection.input) {
                StaticMarkSelector.Zero -> Unit // Mapped relations cannot join through endpoint ZERO.
                is StaticMarkSelector.Full -> { a = full?.get(key.atom); b = group?.get(key.exact.group) }
                is StaticMarkSelector.Group -> { a = group?.get(key.id); b = fullInGroup?.get(key.id) }
            }
        }
        val first = a
        val second = b
        return object : IntIterator() {
            private var ai = 0
            private var bi = 0
            private var flow = if (includeFlow) flowOrdinal else -1
            override fun hasNext(): Boolean = ai < (first?.size ?: 0) || bi < (second?.size ?: 0) || flow >= 0
            override fun nextInt(): Int {
                check(hasNext())
                val av = first?.getOrNull(ai) ?: Int.MAX_VALUE
                val bv = second?.getOrNull(bi) ?: Int.MAX_VALUE
                val next = minOf(av, bv, if (flow >= 0) flow else Int.MAX_VALUE)
                if (av == next) ai++
                if (bv == next) bi++
                if (flow == next) flow = -1
                return next
            }
        }
    }

    fun visit(selection: StaticLabelSelection, includeFlow: Boolean = true, visit: (Int) -> Boolean): Boolean {
        val cursor = ordinals(selection, includeFlow)
        while (cursor.hasNext()) if (!visit(cursor.nextInt())) return false
        return true
    }

    class Builder(private val marks: MarkTable) {
        private var size = 0
        private var flowOrdinal = -1
        private var full: MutableMap<TaintMark, IntArrayList>? = null
        private var group: MutableMap<GroupId, IntArrayList>? = null
        private var fullInGroup: MutableMap<GroupId, IntArrayList>? = null
        private var zero: IntArrayList? = null
        private var unknown = false
        fun add(relation: GuidanceMarks) {
            val ordinal = size++
            when (relation) {
                GuidanceMarks.Flow -> { check(flowOrdinal == -1); flowOrdinal = ordinal }
                is GuidanceMarks.Mapped -> when (val output = relation.output) {
                    null -> (zero ?: IntArrayList().also { zero = it }).add(ordinal)
                    else -> when (val key = marks.staticSelector(output)) {
                        is StaticMarkSelector.Full -> {
                            val exact = full ?: HashMap<TaintMark, IntArrayList>().also { full = it }
                            exact.getOrPut(key.atom) { IntArrayList() }.add(ordinal)
                            val members = fullInGroup ?: HashMap<GroupId, IntArrayList>().also { fullInGroup = it }
                            members.getOrPut(key.exact.group) { IntArrayList() }.add(ordinal)
                        }
                        is StaticMarkSelector.Group -> {
                            val groups = group ?: HashMap<GroupId, IntArrayList>().also { group = it }
                            groups.getOrPut(key.id) { IntArrayList() }.add(ordinal)
                        }
                        else -> unknown = true
                    }
                }
            }
        }
        private fun <K> freeze(source: Map<K, IntArrayList>?): Map<K, IntArray>? = when (source?.size) {
            null, 0 -> null
            1 -> source.entries.single().let { mapOf(it.key to it.value.toIntArray()) }
            else -> source.mapValues { it.value.toIntArray() }
        }
        fun build() = StaticOutputOrdinals(size, flowOrdinal, freeze(full), freeze(group), freeze(fullInGroup),
            zero?.toIntArray(), unknown)
    }
}

package org.opentaint.dataflow.bidi.store

import org.opentaint.dataflow.bidi.ap.*

/** A C2 entry can have several exits. Their indexes are borrowed, not copied or composed.
 * C5 selects an exact exit first, so that view has one complete producer port pair. */
internal fun unionStaticDemandViews(views: List<C5StaticDemandView>): StaticDemandView =
    if (views.size == 1) views.single() else UnionStaticDemandView(views)

private class UnionStaticDemandView(private val views: List<C5StaticDemandView>) : C5StaticDemandView {
    private fun <T> union(query: (C5StaticDemandView) -> Sequence<T>): Sequence<T> =
        views.asSequence().flatMap(query).distinct()

    override fun targetInputs() = union { it.targetInputs() }
    override fun entries(actual: Pattern) = union { it.entries(actual) }
    override fun targets(actual: Pattern, prefixesOnly: Boolean) = union { it.targets(actual, prefixesOnly) }
    override fun flowTargets(actual: Pattern) = union { it.flowTargets(actual) }
    override fun pairs(initial: InitialAp, outputs: List<Pattern>) = union { it.pairs(initial, outputs) }
    override fun incoming(input: Pattern, flowOnly: Boolean) = union { it.incoming(input, flowOnly) }
    override fun outgoing(output: Pattern) = union { it.outgoing(output) }
    override fun markedOutputs(mark: TaintMark) = union { it.markedOutputs(mark) }
    override fun estimatedMarkedOutputs(mark: TaintMark) = views.sumOf { it.estimatedMarkedOutputs(mark) }
    override fun hasMarkedOutput(input: Pattern, mark: TaintMark) = views.any { it.hasMarkedOutput(input, mark) }
    override fun hasComposedEndpoints(initial: InitialAp, outputs: List<Pattern>) =
        views.any { it.hasComposedEndpoints(initial, outputs) }
    override fun c5Targets(actual: Pattern, prefixesOnly: Boolean, keep: StaticCandidateFilter) =
        union { it.c5Targets(actual, prefixesOnly, keep) }
    override fun c5Incoming(input: Pattern, flowOnly: Boolean, keep: StaticCandidateFilter) =
        union { it.c5Incoming(input, flowOnly, keep) }
    override fun c5HasComposedEndpoints(initial: InitialAp, outputs: List<Pattern>, keepTarget: StaticCandidateFilter) =
        views.any { it.c5HasComposedEndpoints(initial, outputs, keepTarget) }
    override fun selectedTargets(actual: Pattern, prefixesOnly: Boolean, query: StaticRowQuery, keep: StaticCandidateFilter) =
        union { it.selectedTargets(actual, prefixesOnly, query, keep) }
    override fun selectedIncoming(input: Pattern, query: StaticRowQuery, keep: StaticCandidateFilter) =
        union { it.selectedIncoming(input, query, keep) }
    override fun selectedHasComposedEndpoints(initial: InitialAp, outputs: List<Pattern>, query: StaticRowQuery,
                                             keep: StaticCandidateFilter) =
        views.any { it.selectedHasComposedEndpoints(initial, outputs, query, keep) }
}

package org.opentaint.dataflow.bidi.fixtures

import org.opentaint.dataflow.bidi.engine.Target

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNotEquals
import kotlin.test.assertNotSame
import kotlin.test.assertSame
import kotlin.test.assertTrue

class BidiFixtureTest {
    @Test
    fun `raw fact identity retains every annotation`() {
        val original = BidiFixtures.annotatedFlow
        val p = original.pattern
        val changes = listOf(
            original.copy(pattern = p.copy(base = BidiFixtures.y)),
            original.copy(pattern = p.copy(path = listOf(BidiFixtures.g))),
            original.copy(pattern = p.copy(tail = FixtureTail.MAY)),
            original.copy(pattern = p.copy(fieldExclusion = emptySet())),
            original.copy(pattern = p.copy(mark = FixtureMark.Concrete(BidiFixtures.T))),
            original.copy(pattern = p.copy(mark = FixtureMark.Abstract(setOf(BidiFixtures.U)))),
            original.copy(layer = FixtureLayer.DEMAND),
        )
        for (changed in changes) assertNotEquals(original, changed)
        assertEquals(changes.size + 1, (changes + original).toSet().size)
    }

    @Test
    fun `output order is independent but duplicate facts and requests remain visible`() {
        val a = BidiFixtures.annotatedFlow
        val b = BidiFixtures.must
        val request = BidiFixtures.staticPositionRequest
        val first = FixtureResult(listOf(a, b, a), setOf(request))
        val reordered = FixtureResult(listOf(a, a, b), setOf(request))
        assertEquals(first.factCounts(), reordered.factCounts())
        assertNotEquals(first.factCounts(), FixtureResult(listOf(a, b)).factCounts())
        assertNotEquals(first.requests, FixtureResult(first.facts).requests)
    }

    @Test
    fun `requests retain method context incoming premise and static position`() {
        val request = BidiFixtures.staticPositionRequest
        assertEquals(BidiFixtures.flowPremise, request.premise)
        assertEquals(listOf(BidiFixtures.classAccessor, BidiFixtures.f),
            (request.kind as FixtureRequestKind.Position).path)
        assertNotEquals(request, request.copy(method = BidiFixtures.otherContext))
        assertNotEquals(request, request.copy(premise = BidiFixtures.a))
        assertNotEquals(request, request.copy(kind = FixtureRequestKind.Mark(BidiFixtures.T)))
    }

    @Test
    fun `method keys keep context and forward entry independently`() {
        assertEquals(3, setOf(BidiFixtures.method, BidiFixtures.otherContext, BidiFixtures.otherEntry).size)
        assertEquals(BidiFixtures.method.method, BidiFixtures.otherContext.method)
        assertEquals(BidiFixtures.method.forwardEntry, BidiFixtures.otherContext.forwardEntry)
    }

    @Test
    fun `statement and exit forms are stable per method in both directions`() {
        val forms = StableFixtureForms()
        for (kind in listOf(FixtureFormKind.STATEMENT, FixtureFormKind.EXIT)) {
            for (direction in FixtureDirection.entries) {
                val first = forms.get(BidiFixtures.method, kind, "node-1", direction)
                assertSame(first, forms.get(BidiFixtures.method, kind, "node-1", direction))
                assertSame(first, forms.get(BidiFixtures.otherContext, kind, "node-1", direction))
                assertSame(first, forms.get(BidiFixtures.otherEntry, kind, "node-1", direction))
            }
            assertNotSame(forms.get(BidiFixtures.method, kind, "node-1", FixtureDirection.FORWARD),
                forms.get(BidiFixtures.method, kind, "node-1", FixtureDirection.BACKWARD))
        }
    }

    @Test
    fun `call and entry forms keep method key call site direction and alternative`() {
        val forms = StableFixtureForms()
        for (kind in listOf(FixtureFormKind.CALL, FixtureFormKind.ENTRY)) {
            val first = forms.get(BidiFixtures.method, kind, "call-1", alternative = "rule-A")
            assertSame(first, forms.get(BidiFixtures.method, kind, "call-1", alternative = "rule-A"))
            assertNotSame(first, forms.get(BidiFixtures.otherContext, kind, "call-1", alternative = "rule-A"))
            assertNotSame(first, forms.get(BidiFixtures.otherEntry, kind, "call-1", alternative = "rule-A"))
            assertNotSame(first, forms.get(BidiFixtures.method, kind, "call-2", alternative = "rule-A"))
            assertNotSame(first, forms.get(BidiFixtures.method, kind, "call-1", alternative = "rule-B"))
            assertNotSame(first, forms.get(BidiFixtures.method, kind, "call-1", FixtureDirection.BACKWARD, "rule-A"))
        }
    }

    @Test
    fun `links keep caller layer separately from added fact and link layer`() {
        val caller = FixtureCaller(BidiFixtures.method, setOf(BidiFixtures.flowPremise), FixtureLayer.NORMAL, "call-1")
        val link = FixtureLink(BidiFixtures.otherContext, caller, FixtureLayer.DEMAND, BidiFixtures.may)
        assertEquals(FixtureLayer.NORMAL, link.caller.layer)
        assertEquals(FixtureLayer.DEMAND, link.linkLayer)
        assertEquals(FixtureLayer.DEMAND, link.added.layer)
        assertNotEquals(link, link.copy(caller = caller.copy(call = "call-2")))
        assertNotEquals(link, link.copy(caller = caller.copy(layer = FixtureLayer.DEMAND)))
        assertNotEquals(link, link.copy(linkLayer = FixtureLayer.NORMAL))
    }

    @Test
    fun `current must demotion and handoff data remove field exclusion`() {
        assertEquals(FixtureTail.MUST, BidiFixtures.must.pattern.tail)
        assertEquals(setOf(BidiFixtures.g), BidiFixtures.must.pattern.fieldExclusion)
        assertEquals(FixtureLayer.NORMAL, BidiFixtures.must.layer)
        assertEquals(FixtureTail.MAY, BidiFixtures.mustDemotion.facts.single().pattern.tail)
        assertEquals(FixtureLayer.DEMAND, BidiFixtures.mustDemotion.facts.single().layer)
        assertTrue(BidiFixtures.mustDemotion.facts.single().pattern.fieldExclusion.isEmpty())
        assertTrue(BidiFixtures.selectedMustHandOff.all { it.entry == BidiFixtures.may.pattern })
        assertEquals(BidiFixtures.normalMustConjunction.premises,
            BidiFixtures.selectedMustHandOff.map { it.exit }.toSet())
    }

    @Test
    fun `normalization data retain star field exclusion and forget abstract mark exclusion`() {
        val normalized = BidiFixtures.normalizedFlowHandOff.entry
        assertEquals(BidiFixtures.annotatedFlow.pattern.fieldExclusion, normalized.fieldExclusion)
        assertEquals(FixtureTail.STAR, normalized.tail)
        assertEquals(FixtureMark.Abstract(), normalized.mark)
    }

    @Test
    fun `same-base cleaner data retain geometry and request already excluded mark`() {
        val input = BidiFixtures.sameBaseCleanerInput
        val result = BidiFixtures.sameBaseCleanerExpected
        assertEquals(input.pattern.copy(mark = FixtureMark.Abstract(setOf(BidiFixtures.T, BidiFixtures.U))),
            result.facts.single().pattern)
        assertEquals(input.layer, result.facts.single().layer)
        assertEquals(setOf(FixtureRequest(BidiFixtures.method, BidiFixtures.flowPremise,
            FixtureRequestKind.Mark(BidiFixtures.T))), result.requests)
        assertEquals(result.requests, BidiFixtures.alreadyExcludedCleanerExpected.requests)
        assertEquals(listOf(BidiFixtures.annotatedFlow), BidiFixtures.alreadyExcludedCleanerExpected.facts)
    }

    @Test
    fun `normal conjunction data preserve layer and make one handoff per member`() {
        val summary = BidiFixtures.normalConjunction
        assertEquals(FixtureLayer.NORMAL, summary.conclusion.layer)
        assertEquals(summary.premises, BidiFixtures.conjunctionHandOff.map { it.exit }.toSet())
        assertTrue(BidiFixtures.conjunctionHandOff.all { it.entry == summary.conclusion.pattern })
        assertEquals(setOf(BidiFixtures.a, BidiFixtures.b),
            BidiFixtures.reversedConjunctionBranches.facts.map { it.pattern }.toSet())
        assertTrue(BidiFixtures.reversedConjunctionBranches.facts.all { it.layer == FixtureLayer.DEMAND })
    }

    @Test
    fun `native must reader data retain exclusion distinct marks and exact target`() {
        assertEquals(FixtureTail.STAR, BidiFixtures.nativeReadPremise.tail)
        assertEquals(BidiFixtures.must.pattern.fieldExclusion, BidiFixtures.nativeReadPremise.fieldExclusion)
        assertTrue(BidiFixtures.nativeReadIncoming.pattern.path.size > BidiFixtures.nativeReadPremise.path.size)
        assertNotEquals(BidiFixtures.nativeReadPremise.mark, BidiFixtures.nativeReadTarget.pattern.mark)
        assertEquals(BidiFixtures.nativeInput, BidiFixtures.nativeReadExpected.facts.single().pattern)
        assertEquals(FixtureTail.EXACT, BidiFixtures.nativeReadExpected.facts.single().pattern.tail)
        assertEquals(FixtureLayer.NORMAL, BidiFixtures.nativeReadExpected.facts.single().layer)
    }
}

package org.opentaint.dataflow.bidi.fixtures

/** Test values use names, not manager ids. An adapter must retain every annotation. */
sealed interface FixtureAccessor {
    data class Field(val owner: String, val name: String, val type: String) : FixtureAccessor
    data class Class(val name: String) : FixtureAccessor
    data object Element : FixtureAccessor
}

sealed interface FixtureBase {
    data class Local(val name: String) : FixtureBase
    data class Argument(val index: Int) : FixtureBase
    data object Static : FixtureBase
    data object Zero : FixtureBase
}

enum class FixtureTail { EXACT, STAR, MAY, MUST }
enum class FixtureLayer { NORMAL, DEMAND }
enum class FixtureDirection { FORWARD, BACKWARD }

sealed interface FixtureMark {
    data class Concrete(val name: String) : FixtureMark
    data class Abstract(val excluded: Set<String> = emptySet()) : FixtureMark
}

/** A raw reference pattern can represent test input that a typed factory must reject. */
data class FixturePattern(
    val base: FixtureBase,
    val path: List<FixtureAccessor>,
    val tail: FixtureTail,
    val mark: FixtureMark,
    val fieldExclusion: Set<FixtureAccessor> = emptySet(),
)

/** Full raw output identity includes the layer as well as both exclusion annotations. */
data class FixtureFact(val pattern: FixturePattern, val layer: FixtureLayer)

/** The forward entry remains in the key when a test runs backward. */
data class FixtureMethodKey(val method: String, val context: String, val forwardEntry: String)

sealed interface FixtureRequestKind {
    data class Mark(val mark: String) : FixtureRequestKind
    data class Position(val path: List<FixtureAccessor>) : FixtureRequestKind
}

data class FixtureRequest(
    val method: FixtureMethodKey,
    val premise: FixturePattern,
    val kind: FixtureRequestKind,
)

/** Operation outputs are a multiset; requests have their own exact keys. */
data class FixtureResult(val facts: List<FixtureFact>, val requests: Set<FixtureRequest> = emptySet()) {
    fun factCounts(): Map<FixtureFact, Int> = facts.groupingBy { it }.eachCount()
}

data class FixtureSummary(val method: FixtureMethodKey, val premises: Set<FixturePattern>, val conclusion: FixtureFact)
data class FixtureDemand(val method: FixtureMethodKey, val entry: FixturePattern, val exit: FixturePattern?)

data class FixtureCaller(
    val method: FixtureMethodKey,
    val premises: Set<FixturePattern>,
    val layer: FixtureLayer,
    val call: String,
)

data class FixtureLink(
    val callee: FixtureMethodKey,
    val caller: FixtureCaller,
    val linkLayer: FixtureLayer,
    val added: FixtureFact,
)

enum class FixtureFormKind { STATEMENT, CALL, ENTRY, EXIT }

/** Stable objects provide identity keys for test joins and rule alternatives. */
class FixtureForm internal constructor(
    val method: FixtureMethodKey,
    val kind: FixtureFormKind,
    val statement: String,
    val direction: FixtureDirection,
    val alternative: String,
)

/** S00 harness cache only. It supplies stable test inputs, not a production-cache oracle. */
class StableFixtureForms {
    private data class Slot(
        val method: String,
        val context: String?,
        val entry: String?,
        val kind: FixtureFormKind,
        val statement: String,
        val direction: FixtureDirection,
        val alternative: String,
    )

    private val forms = HashMap<Slot, FixtureForm>()

    fun get(
        method: FixtureMethodKey,
        kind: FixtureFormKind,
        statement: String,
        direction: FixtureDirection = FixtureDirection.FORWARD,
        alternative: String = "default",
    ): FixtureForm {
        val contextual = kind == FixtureFormKind.CALL || kind == FixtureFormKind.ENTRY
        val slot = Slot(method.method, method.context.takeIf { contextual }, method.forwardEntry.takeIf { contextual },
            kind, statement, direction, alternative)
        return forms.getOrPut(slot) {
            FixtureForm(method, kind, statement, direction, alternative)
        }
    }
}

/** Small annotated vectors. Their expected values are data, with no production operation calls. */
object BidiFixtures {
    val f = FixtureAccessor.Field("Box", "f", "Box")
    val g = FixtureAccessor.Field("Box", "g", "Box")
    val freshField = FixtureAccessor.Field("Box", "fresh", "Box")
    val classAccessor = FixtureAccessor.Class("Box")
    val x = FixtureBase.Local("x")
    val y = FixtureBase.Local("y")
    const val T = "taint-T"
    const val U = "taint-U"
    const val FRESH_MARK = "fresh-mark"

    val method = FixtureMethodKey("Box.pass(Box):Box", "context-A", "entry-0")
    val otherContext = method.copy(context = "context-B")
    val otherEntry = method.copy(forwardEntry = "entry-1")

    val zero = FixturePattern(FixtureBase.Zero, emptyList(), FixtureTail.EXACT, FixtureMark.Concrete("<zero>"))
    val flowPremise = FixturePattern(x, emptyList(), FixtureTail.STAR, FixtureMark.Abstract())
    val annotatedFlow = FixtureFact(
        FixturePattern(x, listOf(f), FixtureTail.STAR, FixtureMark.Abstract(setOf(T)), setOf(g)),
        FixtureLayer.NORMAL,
    )
    val must = FixtureFact(
        FixturePattern(y, listOf(f), FixtureTail.MUST, FixtureMark.Concrete(T), setOf(g)),
        FixtureLayer.NORMAL,
    )
    val may = FixtureFact(must.pattern.copy(tail = FixtureTail.MAY, fieldExclusion = emptySet()), FixtureLayer.DEMAND)

    // AP W8: a demoted must fact has Empty E. A selected normal piece retains NORMAL until hand-off.
    val mustDemotion = FixtureResult(listOf(may))
    // This arbitrary-pattern normalization vector does not assert native-summary selection.
    val normalizedFlowHandOff = FixtureDemand(
        method,
        annotatedFlow.pattern.copy(mark = FixtureMark.Abstract()),
        flowPremise,
    )

    // AP F75: selected-mark cleaning adds X and requests even when T is already excluded.
    val sameBaseCleanerInput = annotatedFlow.copy(pattern = annotatedFlow.pattern.copy(mark = FixtureMark.Abstract(setOf(U))))
    val sameBaseCleanerExpected = FixtureResult(
        listOf(sameBaseCleanerInput.copy(pattern = sameBaseCleanerInput.pattern.copy(mark = FixtureMark.Abstract(setOf(T, U))))),
        setOf(FixtureRequest(method, flowPremise, FixtureRequestKind.Mark(T))),
    )
    val alreadyExcludedCleanerExpected = FixtureResult(
        listOf(annotatedFlow),
        setOf(FixtureRequest(method, flowPremise, FixtureRequestKind.Mark(T))),
    )
    val staticPositionRequest = FixtureRequest(
        method,
        flowPremise,
        FixtureRequestKind.Position(listOf(classAccessor, f)),
    )

    // CurrentConjunction: selection does not change a normal multi-premise conclusion.
    val a = FixturePattern(FixtureBase.Argument(0), emptyList(), FixtureTail.EXACT, FixtureMark.Concrete(T))
    val b = FixturePattern(FixtureBase.Argument(1), emptyList(), FixtureTail.EXACT, FixtureMark.Concrete(U))
    val c = FixturePattern(y, emptyList(), FixtureTail.EXACT, FixtureMark.Concrete(T))
    val normalConjunction = FixtureSummary(method, setOf(a, b), FixtureFact(c, FixtureLayer.NORMAL))
    val conjunctionHandOff = setOf(FixtureDemand(method, c, a), FixtureDemand(method, c, b))
    val normalMustConjunction = FixtureSummary(method, setOf(a, b), must)
    val selectedMustHandOff = setOf(FixtureDemand(method, may.pattern, a), FixtureDemand(method, may.pattern, b))
    val reversedConjunctionBranches = FixtureResult(
        listOf(FixtureFact(a, FixtureLayer.DEMAND), FixtureFact(b, FixtureLayer.DEMAND)),
    )

    // F76: the reader's concrete STAR/E premise is transient; its exact target drops the suffix.
    val nativeInput = a.copy(mark = FixtureMark.Concrete(U))
    val exactToMustRecord = FixtureSummary(method, setOf(nativeInput), must)
    val nativeReadPremise = must.pattern.copy(tail = FixtureTail.STAR)
    val nativeReadTarget = FixtureFact(nativeInput, FixtureLayer.NORMAL)
    val nativeReadIncoming = FixtureFact(
        must.pattern.copy(path = listOf(f, freshField), tail = FixtureTail.EXACT, fieldExclusion = emptySet()),
        FixtureLayer.NORMAL,
    )
    val nativeReadExpected = FixtureResult(listOf(nativeReadTarget))
}

package org.opentaint.dataflow.bidi.fixtures

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.Conclusion
import org.opentaint.dataflow.bidi.ap.ExclusionSet
import org.opentaint.dataflow.bidi.ap.MarkSlot
import org.opentaint.dataflow.bidi.ap.Pattern
import org.opentaint.dataflow.bidi.ap.Tail
import org.opentaint.dataflow.bidi.ap.TaintMark

data class TestPosition(val base: AccessPathBase, val path: List<Int>)
data class TestLocation(val base: AccessPathBase, val path: List<Int>, val mark: TaintMark) {
    val position: TestPosition get() = TestPosition(base, path)
}
data class TestLocationPair(val entry: TestLocation, val exit: TestLocation)

/** Finite observation of AP §3.1–§3.2. No production selector, trie or index is called here. */
class BoundedDenotation(
    bases: List<AccessPathBase>,
    accessors: List<Int>,
    val marks: List<TaintMark>,
    maximumPathLength: Int,
) {
    val paths: List<List<Int>> = buildList {
        var level: List<List<Int>> = listOf(emptyList())
        addAll(level)
        repeat(maximumPathLength) {
            level = level.flatMap { prefix -> accessors.map { prefix + it } }
            addAll(level)
        }
    }
    val positions: Set<TestPosition> = bases.flatMap { base -> paths.map { TestPosition(base, it) } }.toSet()
    val locations: Set<TestLocation> = positions.flatMap { p -> marks.map { TestLocation(p.base, p.path, it) } }.toSet()

    private fun suffix(full: List<Int>, prefix: List<Int>): List<Int>? {
        if (full.size < prefix.size) return null
        for (index in prefix.indices) if (full[index] != prefix[index]) return null
        return full.drop(prefix.size)
    }

    private fun excludedFields(exclusion: ExclusionSet): Set<Int> = when (exclusion) {
        ExclusionSet.Empty -> emptySet()
        is ExclusionSet.Concrete -> exclusion.ids.toSet()
    }

    fun admitsContinuation(tail: Tail, exclusion: ExclusionSet, continuation: List<Int>): Boolean = when (tail) {
        Tail.EXACT -> continuation.isEmpty()
        Tail.ANY -> true
        Tail.STAR, Tail.ANY_TAINT -> continuation.isEmpty() || continuation.first() !in excludedFields(exclusion)
    }

    fun admitsMark(slot: MarkSlot, mark: TaintMark): Boolean = when (slot) {
        is MarkSlot.Concrete -> slot.mark == mark
        is MarkSlot.Star -> mark.id !in slot.excluded.ids
    }

    fun markedValues(slot: MarkSlot): Set<TaintMark> = marks.filter { admitsMark(slot, it) }.toSet()

    fun spatial(pattern: Pattern): Set<TestPosition> = positions.filterTo(HashSet()) { position ->
        if (position.base != pattern.fact.base) false
        else suffix(position.path, pattern.fact.path)?.let {
            admitsContinuation(pattern.fact.tail, pattern.exclusion, it)
        } == true
    }

    fun marked(pattern: Pattern): Set<TestLocation> {
        val spatial = spatial(pattern)
        return locations.filterTo(HashSet()) { it.position in spatial && admitsMark(pattern.fact.mark, it.mark) }
    }

    fun containsPair(premise: Pattern, conclusion: Conclusion, pair: TestLocationPair): Boolean {
        if (pair.entry.base != premise.fact.base || pair.exit.base != conclusion.fact.base) return false
        val sigma = suffix(pair.entry.path, premise.fact.path) ?: return false
        val tau = suffix(pair.exit.path, conclusion.fact.path) ?: return false
        if (!admitsContinuation(premise.fact.tail, premise.exclusion, sigma)) return false
        if (!admitsMark(premise.fact.mark, pair.entry.mark)) return false
        val target = conclusion.fact.mark
        val outputMark = when (target) {
            is MarkSlot.Concrete -> target.mark
            is MarkSlot.Star -> {
                if (!admitsMark(target, pair.entry.mark)) return false
                pair.entry.mark
            }
        }
        if (pair.exit.mark != outputMark) return false
        return when (conclusion.fact.tail) {
            Tail.EXACT -> tau.isEmpty()
            Tail.STAR -> tau == sigma && admitsContinuation(Tail.STAR, conclusion.exclusion, tau)
            Tail.ANY -> true
            Tail.ANY_TAINT -> admitsContinuation(Tail.ANY_TAINT, conclusion.exclusion, tau)
        }
    }

    fun pairs(premise: Pattern, conclusion: Conclusion): Set<TestLocationPair> {
        val entries = marked(premise)
        val exits = locations.filter { it.base == conclusion.fact.base }
        return buildSet {
            for (entry in entries) for (exit in exits) {
                val pair = TestLocationPair(entry, exit)
                if (containsPair(premise, conclusion, pair)) add(pair)
            }
        }
    }
}

package org.opentaint.dataflow.bidi.fixtures

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*

/** N2 oracle: raw accepted leaves, independent bounded matching and per-leaf reference transfer.
 * No subscription accumulator, candidate index, tree selector or production predicate store is read. */
class CumulativeSubscriptionReference(private val universe: BoundedDenotation) {
    fun selects(premise: Pattern, added: Conclusion, restricted: Boolean): Boolean {
        val a = Pattern(added.fact, added.exclusion)
        // Selected CURRENT policy removes only strict-ancestor STAR. The
        // remaining oracle stays a finite denotation check, not a tree/index query.
        if (a.fact.tail == Tail.STAR && premise.fact.path.size > a.fact.path.size &&
            premise.fact.path.startsWith(a.fact.path)) return false
        val pPositions = universe.spatial(premise)
        val aPositions = universe.spatial(a)
        val applicable = universe.marked(premise).containsAll(universe.marked(a)) &&
            (premise.fact.tail !in listOf(Tail.ANY, Tail.ANY_TAINT) || a.fact.tail in listOf(Tail.ANY, Tail.ANY_TAINT))
        val inside = aPositions.containsAll(pPositions) &&
            universe.markedValues(premise.fact.mark).containsAll(universe.markedValues(a.fact.mark))
        if (premise.fact.tail == Tail.ANY_TAINT && premise.fact.mark is MarkSlot.Star)
            return a.fact.tail == Tail.ANY_TAINT && aPositions.containsAll(pPositions) &&
                universe.markedValues(premise.fact.mark).containsAll(universe.markedValues(a.fact.mark))
        if (!restricted) return applicable || inside
        val canonicalFlow = premise.fact.tail == Tail.STAR && premise.exclusion == ExclusionSet.Empty &&
            premise.fact.mark == MarkSlot.STAR
        return if (canonicalFlow) pPositions.any { it in aPositions }
        else inside || ((premise.fact.mark == MarkSlot.STAR || premise.fact.tail == Tail.STAR) && applicable)
    }

    fun transfer(premise: Pattern, conclusion: Conclusion, added: Conclusion, restricted: Boolean, run1: Boolean = false): EdgeOutcome =
        concat(added, summaryEdge(premise, conclusion), edgeDemand = conclusion.demand,
            staticIdentity = false, restricted = restricted, run1 = run1)

    private data class OutputScope(val base: AccessPathBase, val layer: Boolean, val component: String)

    /** Keep normal must and exact components separate; observe FLOW as correlated marked-location pairs. */
    fun denotation(premise: Set<Pattern>, values: Collection<Conclusion>): Map<Any, Set<Any>> {
        val result = LinkedHashMap<Any, MutableSet<Any>>()
        for (value in values) {
            val flow = value.fact.mark is MarkSlot.Star
            val component = if (flow) "FLOW" else if (!value.demand && value.fact.tail == Tail.ANY_TAINT) "MUST" else "EXACT_OR_MAY"
            val scope = OutputScope(value.fact.base, value.demand, component)
            val cells = result.getOrPut(scope) { LinkedHashSet() }
            if (flow) for (initial in premise) cells.addAll(universe.pairs(initial, value))
            else cells.addAll(universe.marked(Pattern(value.fact, value.exclusion)))
        }
        return result
    }
}

/** Build only the SUT input. Expected data remains the supplied raw leaves. */
fun cumulativeInput(manager: ApManager, raw: List<Conclusion>): Facts {
    require(raw.isNotEmpty())
    val first = raw.first()
    require(raw.all { it.fact.base == first.fact.base && it.demand == first.demand })
    if (first.fact.base == AccessPathBase.Zero) return Reach.of(if (first.demand) Layer.DEMAND else Layer.NORMAL)
    val layer = if (first.demand) Layer.DEMAND else Layer.NORMAL
    val leaves = raw.map { manager.factsOf(it.fact, it.exclusion, layer) }
    return if (first.fact.mark is MarkSlot.Star) {
        require(raw.all { it.fact.mark == first.fact.mark && it.exclusion == first.exclusion })
        val root = leaves.map { (it as FlowTree).root }.reduce { left, right ->
            FlowAlgebra.mergeAdd(left, right, manager.cancellation)
        }
        manager.flowTree(first.fact.base, layer, first.exclusion, (first.fact.mark as MarkSlot.Star).excluded, root, first.fact.tail)
    } else {
        val exclusion = raw.firstOrNull { it.fact.tail == Tail.ANY_TAINT }?.exclusion ?: ExclusionSet.Empty
        require(raw.all { it.fact.tail != Tail.ANY_TAINT || it.exclusion == exclusion })
        val root = leaves.map { (it as TaintTree).root }.reduce { left, right ->
            manager.taintAlg.mergeAdd(left, right, manager.cancellation)
        }
        manager.taintTree(first.fact.base, layer, root, exclusion,
            raw.firstOrNull { it.fact.tail != Tail.EXACT }?.fact?.tail ?: Tail.ANY_TAINT)
    }
}

