                            val hasSharedStaticCarry: Boolean = false)

private fun <T> ownedList(values: Collection<T>): List<T> = Collections.unmodifiableList(ArrayList(values))
private fun ownPath(fact: PathFact): PathFact = fact.copy(path = ownedList(fact.path))
private fun ownPattern(pattern: Pattern): Pattern = pattern.copy(fact = ownPath(pattern.fact))

/** Method identity and source graph are fixture inputs, not a production graph observation. */
class ProgramMethod internal constructor(val method: CommonMethod, successors: List<List<Int>>,
                                         val normalExit: Int, val exceptionalExit: Int?,
                                         val backwardExitDiscovery: Boolean = false) {
    data class Context(val name: String) : MethodContext {
        override fun toString(): String = name
    }
    val successors: List<List<Int>> = ownedList(successors.map(::ownedList))
    private val instructions: Array<CommonInst> = Array(successors.size) { index ->
        object : CommonInst {
            override val location = object : CommonInstLocation {
                override val method = this@ProgramMethod.method
                override val index = index
            }
            override fun toString(): String = "${method.name}:$index"
        }
    }
    private val keys = ConcurrentHashMap<Pair<String, Int>, MethodKey>()
    fun inst(index: Int): CommonInst = instructions[index]
    fun key(context: String = "context", entry: Int = 0): MethodKey =
        keys.computeIfAbsent(context to entry) { MethodKey(Context(context), inst(entry)) }
    override fun toString(): String = method.name
}

/** Complete finite input program. Construction lists are separate from engine indexes and tree stores. */
class FiniteProgramFixtures(val cancellation: Cancellation = Cancellation(), threads: Int = 1,
                            markDeclarations: MarkDeclarations = COMMON_FIXTURE_DECLARATIONS) : AutoCloseable {
    private data class ProgramUnit(val name: String) : UnitType
    val refManager = RefManager()
    val ap = testApManager(cancellation, refManager, markDeclarations)
    val manager: ApManager get() = ap
    val ops = ApOps(ap)
    val records = PersistentRecordStore(ap)
    val vulnerabilities = ConcurrentVulnerabilityStore(ap)
    private val methodData = ArrayList<ProgramMethod>()
    val methods: List<ProgramMethod> = Collections.unmodifiableList(methodData)
    private val statements = ArrayList<StatementInput>()
    private val entries = ArrayList<EntryInput>()
    private val exits = ArrayList<ExitInput>()
    private val calls = ArrayList<CallInput>()
    val statementInputs: List<StatementInput> = Collections.unmodifiableList(statements)
    val entryInputs: List<EntryInput> = Collections.unmodifiableList(entries)
    val exitInputs: List<ExitInput> = Collections.unmodifiableList(exits)
    val callInputs: List<CallInput> = Collections.unmodifiableList(calls)
    private val formCache = ConcurrentHashMap<MethodKey, MethodForms>()
    private var groupRuleViews: GroupRuleFixtureViews? = null
    /** Opt in before reading any forms; original construction rows remain FULL oracle inputs. */
    fun enableGroupRuleViews() {
        check(formCache.isEmpty())
        groupRuleViews = groupRuleViews ?: GroupRuleFixtureViews(ap.marks, cancellation)
    }
    private val graphCache = ConcurrentHashMap<Pair<MethodKey, Direction>, MethodInstGraph>()
    private val operationOwner = FormOwner()
    private val callExpressions = ConcurrentHashMap<CommonInst, CommonCallExpr>()
    private val runInputs = IdentityHashMap<RunConfig, ProgramRunInputs>()
    private val rawFacts = IdentityHashMap<Facts, List<Conclusion>>()
    private val recordInputs = IdentityHashMap<Record, List<Conclusion>>()
    private var staticCatalog: Run1StaticProfiles? = null
    private val declaredStaticFields = LinkedHashSet<HistoricalRun1Slot.StaticField>()
    private val declaredStaticClasses = LinkedHashSet<Int>()

    /** Add only canonical input domain; actual forms still determine owned semantic components. */
    fun declareStaticDomain(vararg paths: List<Int>) {
        check(staticCatalog == null) { "The finite static plan is already frozen" }
        for (path in paths) {
            require(path.size in 1..2 && path[0].isClass())
            declaredStaticClasses += path[0]
            if (path.size == 2) declaredStaticFields += HistoricalRun1Slot.StaticField(path[0], path[1])
        }
    }
    /** Immutable construction vocabulary; independent scalar oracles do not read production plans. */
    val declaredStaticFieldPaths: Set<List<Int>> get() = declaredStaticFields.mapTo(LinkedHashSet()) { listOf(it.cls, it.field) }
    val declaredStaticClassIds: Set<Int> get() = declaredStaticClasses.toSet()

    val defaultCallExpression = object : CommonCallExpr {
        override val typeName = "Box"
        override val args: List<CommonValue> = emptyList()
    }

    fun method(name: String, successors: List<List<Int>>, normalExit: Int, exceptionalExit: Int? = null,
               backwardExitDiscovery: Boolean = false): ProgramMethod {
        check(staticCatalog == null) { "The finite program catalog has already been frozen" }
        require(successors.isNotEmpty())
        require(normalExit in successors.indices && (exceptionalExit == null || exceptionalExit in successors.indices))
        require(!backwardExitDiscovery || exceptionalExit != null) {
            "I11 backward discovery requires a distinct exceptional exit, never a fabricated normal return"
        }
        require(!backwardExitDiscovery || exceptionalExit != normalExit)
        require(successors.all { next -> next.all { it in successors.indices } })
        require(methodData.none { it.method.name == name }) { "Finite methods have unique diagnostic names" }
        val common = object : CommonMethod {
            override val name = name
            override val parameters: List<CommonMethodParameter> = emptyList()
            override val returnType = object : CommonTypeName { override val typeName = "Box" }
            override fun flowGraph(): ControlFlowGraph<CommonInst> = error("Use the explicit finite compact graph")
            override fun toString(): String = name
        }
        return ProgramMethod(common, successors, normalExit, exceptionalExit, backwardExitDiscovery).also(methodData::add)
    }
    fun key(method: ProgramMethod, context: String = "context", entry: Int = 0): MethodKey = method.key(context, entry)
    fun programMethod(key: MethodKey): ProgramMethod = methodData.single { it.method === key.method }
    fun isKnown(key: MethodKey): Boolean = methodData.any { it.method === key.method }
    fun inst(key: MethodKey, index: Int): CommonInst = programMethod(key).inst(index)
    private fun mutable(key: MethodKey) {
        check(isKnown(key)) { "The method key belongs to this finite program" }
        check(staticCatalog == null) { "The finite program catalog has already been frozen" }
        check(!formCache.containsKey(key)) { "Cached forms are immutable; configure the full method key before reading it" }
    }
    fun statement(key: MethodKey, index: Int, summary: StatementSummary) {
        mutable(key); inst(key, index)
        statements.removeAll { it.key == key && it.index == index }
        statements += StatementInput(key, index, summary)
    }
    /** Explicit code operations. A static destination on a preservation/alias edge is
     * not enough to declare a logical store. These helpers retain the full form. */
    fun staticRead(key: MethodKey, index: Int, transfer: PathEdge,
                   summary: StatementSummary = StatementSummary(setOf(transfer.from.base),
                       listOf(MicroEdge.of(transfer)), emptyList(), emptyMap())) {
        require(transfer.from.base == STATIC)
        val id = OperationId(FormKey(operationOwner, key.method, key, inst(key, index)))
        statement(key, index, summary.withStaticOperations(listOf(StaticOperation.Read(id, transfer))))
    }
    fun staticWrite(key: MethodKey, index: Int, target: Pattern, transfer: PathEdge?,
                    summary: StatementSummary) {
        require(target.fact.base == STATIC)
        require(transfer == null || transfer.to.base == STATIC)
        val action = summary.edges.firstOrNull { it.edge == transfer }?.actionId
        val id = OperationId(FormKey(operationOwner, key.method, key, inst(key, index)), action = action)
        statement(key, index, summary.withStaticOperations(listOf(StaticOperation.Write(id, target, transfer, action))))
    }
    fun staticCheck(key: MethodKey, index: Int, position: Pattern, summary: StatementSummary) {
        require(position.fact.base == STATIC)
        val id = OperationId(FormKey(operationOwner, key.method, key, inst(key, index)))
        statement(key, index, summary.withStaticOperations(listOf(StaticOperation.MarkInput(id, position))))
    }

    fun entry(key: MethodKey, rules: RuleStatement) {
        mutable(key)
        entries.removeAll { it.key == key }
        entries += EntryInput(key, rules)
    }
    fun exit(key: MethodKey, index: Int, rules: ExitRules) {
        mutable(key); inst(key, index)
        exits.removeAll { it.key == key && it.index == index }
        exits += ExitInput(key, index, rules)
    }
    fun call(key: MethodKey, index: Int, plan: CallPlan, expression: CommonCallExpr = defaultCallExpression) {
        mutable(key)
        val node = inst(key, index)
        val old = callExpressions.putIfAbsent(node, expression)
        check(old == null || old === expression) { "One context-free instruction has one call expression" }
        calls.removeAll { it.key == key && it.index == index }
        calls += CallInput(key, index, plan, expression)
    }
    fun callExpression(key: MethodKey, index: Int): CommonCallExpr? = callExpressions[inst(key, index)]

    fun forms(key: MethodKey): MethodForms = formCache.computeIfAbsent(key) {
        val statementRows = statements.filter { it.key == key }.associate { it.index to it.summary }
        val exitRows = exits.filter { it.key == key }.associate { it.index to it.rules }
        val callRows = calls.filter { it.key == key }.associate { it.index to it.plan }
        val entryRules = entries.singleOrNull { it.key == key }?.rules ?: RuleStatement.EMPTY
        val statementCache = FormsCache(programMethod(key).successors.size, StatementSummary::reversed)
        val exitCache = FormsCache(programMethod(key).successors.size) { e: ExitRules -> ExitRules(e.reversed(), false, emptySet()) }
        val callCache = FormsCache(programMethod(key).successors.size, CallPlan::reversed)
        val entryCache = FormsCache(1, RuleStatement::reversed)
        val full = object : MethodForms {
            override fun statement(direction: Direction, s: CommonInst): StatementSummary =
                statementCache.get(s.location.index, direction) { statementRows[s.location.index] ?: StatementSummary.EMPTY }
            override fun entryRules(direction: Direction): RuleStatement = entryCache.get(0, direction) { entryRules }
            override fun exitRules(direction: Direction, exit: CommonInst): ExitRules =
                exitCache.get(exit.location.index, direction) { exitRows[exit.location.index] ?: ExitRules.EMPTY }
            override fun call(direction: Direction, s: CommonInst, call: CommonCallExpr): CallPlan =
                callCache.get(s.location.index, direction) { checkNotNull(callRows[s.location.index]) { "A known call needs a full-key plan" } }
        }
        groupRuleViews?.forms(full) ?: full
    }
    fun graph(key: MethodKey, direction: Direction): MethodInstGraph = graphCache.computeIfAbsent(key to direction) {
        val method = programMethod(key)
        val next = if (direction == Direction.FORWARD) method.successors else {
            val reverse = method.successors.indices.map { target ->
                method.successors.indices.filter { target in method.successors[it] }.toMutableList()
            }
            if (method.backwardExitDiscovery) {
                // Explicit selected-fixture I11(e) contract. Preserve raw forward/historical
                // graphs; only backward discovery gets the JVM-style exceptional wiring.
                val exceptional = checkNotNull(method.exceptionalExit)
                val exiting = BitSet()
                val queue = ArrayDeque<Int>()
                for (exit in listOf(method.normalExit, exceptional)) {
                    exiting.set(exit)
                    queue.addLast(exit)
                }
                while (queue.isNotEmpty()) {
                    cancellation.checkpoint()
                    for (before in reverse[queue.removeFirst()]) if (!exiting[before]) {
                        exiting.set(before)
                        queue.addLast(before)
                    }
                }
                for (index in method.successors.indices) {
                    cancellation.checkpoint()
                    if (!exiting[index]) reverse[exceptional] += index
                }
            }
            reverse
        }
        MethodInstGraph(Array(next.size, method::inst),
            CompactGraph.build(next.size) { index -> BitSet().apply { next[index].forEach(::set) } },
            BitSet().apply {
                if (direction == Direction.FORWARD) { set(method.normalExit); method.exceptionalExit?.let(::set) }
                else set(key.statement.location.index)
            })
    }
    val interpreter = object : Interpreter {
        override fun entryNode(method: MethodKey): CommonInst = method.statement
        override fun exitNodes(method: MethodKey): List<ExitNode> = programMethod(method).let { m ->
            listOf(ExitNode(m.inst(m.normalExit), false)) + listOfNotNull(m.exceptionalExit?.let { ExitNode(m.inst(it), true) })
        }
        override fun entryRules(method: MethodKey): RuleStatement = forms(method).entryRules(Direction.FORWARD)
        override fun exitRules(method: MethodKey, exit: CommonInst): ExitRules = forms(method).exitRules(Direction.FORWARD, exit)
        override fun statementSummary(method: MethodKey, statement: CommonInst): StatementSummary = forms(method).statement(Direction.FORWARD, statement)
        override fun callPlan(caller: MethodKey, statement: CommonInst, call: CommonCallExpr): CallPlan = forms(caller).call(Direction.FORWARD, statement, call)
        override fun isSummaryBase(base: AccessPathBase): Boolean = base !is AccessPathBase.LocalVar && base !is AccessPathBase.CleanerTemporary
    }
    val language = object : LanguageManager {
        private fun method(method: CommonMethod): ProgramMethod = methodData.single { it.method === method }
        override fun getInstIndex(inst: CommonInst): Int = inst.location.index
        override fun getMaxInstIndex(method: CommonMethod): Int = method(method).successors.lastIndex
        override fun getInstByIndex(method: CommonMethod, index: Int): CommonInst = method(method).inst(index)
        override fun isEmpty(method: CommonMethod): Boolean = methodData.none { it.method === method }
        override fun getCallExpr(inst: CommonInst): CommonCallExpr? = callExpressions[inst]
        override fun producesExceptionalControlFlow(inst: CommonInst): Boolean = method(inst.location.method).let { m ->
            m.exceptionalExit != null && m.exceptionalExit in m.successors[inst.location.index]
        }
        override fun getCalleeMethod(callExpr: CommonCallExpr): CommonMethod = calls.filter { it.expression === callExpr }
            .flatMap { row -> row.plan.stages.filterIsInstance<CallStage.Callees>().flatMap { it.callees } }
            .map { it.method }.distinct().single()
        override val methodContextSerializer: MethodContextSerializer get() = error("Serialization is outside the finite run fixture")
    }
    val contexts = MethodContextCache(interpreter, object : MethodContextSource {
        override fun forms(key: MethodKey): MethodForms = this@FiniteProgramFixtures.forms(key)
        override fun graph(key: MethodKey, direction: Direction): MethodInstGraph = this@FiniteProgramFixtures.graph(key, direction)
    })
    fun directed(direction: Direction): DirectedForms = contexts.directed(direction)
    private val unitResolver = UnitResolver<CommonMethod> { method ->
        if (methodData.any { it.method === method }) ProgramUnit(method.name) else UnknownUnit
    }
    private val sharedOwner = lazy {
        SharedObjects(ap, ops, interpreter, language, contexts, records, unitResolver,
            refManager, cancellation, threads, staticCallGraph = staticCallGraph())
    }
    val shared: SharedObjects get() = sharedOwner.value
    fun freshShared(sameUnit: Boolean = false, threads: Int = 1,
                    useStaticCatalog: Boolean = true): SharedObjects =
        SharedObjects(ap, ops, interpreter, language, contexts, records,
            if (sameUnit) UnitResolver<CommonMethod> { if (methodData.any { m -> m.method === it }) ProgramUnit("all") else UnknownUnit }
            else unitResolver, refManager, cancellation, threads, staticCallGraph = staticCallGraph())

    /** Fixture equivalent of the successfully resolved prescan graph. It owns no mutable call plans. */
    fun staticCallGraph(): org.opentaint.dataflow.bidi.store.DetachedStaticCallGraph {
        val adjacency = methodData.associate { it.method to LinkedHashSet<CommonMethod>() }
        for (call in calls) for (stage in call.plan.stages.filterIsInstance<CallStage.Callees>())
            for (callee in stage.callees) adjacency.getValue(call.key.method).add(callee.method)
        return org.opentaint.dataflow.bidi.store.DetachedStaticCallGraph.copyOf(adjacency, cancellation)
    }

    /** Collect only explicit forward forms. The scalar oracle does not use this collector. */
    fun staticProfiles(): Run1StaticProfiles {
        staticCatalog?.let { return it }
        val locals = methodData.associate { it.method to FiniteStaticProfileLocal() }
        val adjacency = methodData.associate { it.method to LinkedHashSet<CommonMethod>() }
        statements.forEach { locals.getValue(it.key.method).summary(it.summary) }
        entries.forEach { locals.getValue(it.key.method).rules(it.rules) }
        exits.forEach { locals.getValue(it.key.method).rules(it.rules.rules) }
        calls.forEach { call ->
            locals.getValue(call.key.method).plan(call.plan) { adjacency.getValue(call.key.method) += it.method }
        }
        return Run1StaticProfiles.build(ap, adjacency, locals.mapValues { it.value.profile() },
            declaredFieldUniverse = declaredStaticFields, declaredClassUniverse = declaredStaticClasses)
            .also { staticCatalog = it }
    }

    fun config(index: Int = 1, L: Int = maxOf(1, index - 1), roots: List<MethodKey>,
               demand: List<Pair<MethodKey, DemandPattern>> = emptyList(),
               records: List<Pair<MethodKey, Record>> = emptyList(), seeds: List<Seed> = emptyList()): RunConfig {
        val rawDemand = ownedList(demand.map { (method, d) -> method to DemandPattern(ownPattern(d.entry), d.exit?.let(::ownPattern)) })
        val recordStore = PersistentRecordStore(ap)
        val rawRecords = ArrayList<RawRecord>()
        for ((method, record) in records) {
            check(record.method == method)
            val conclusions = recordInputs[record] ?: rawFacts[record.conclusion]
                ?: error("Use fixture.fact or fixture.record for native inputs; expected leaves must precede production tree merging")
            recordStore.add(record)
            for (c in conclusions) rawRecords += RawRecord(method, record.direction, ownPattern(record.premise.toPattern()),
                c.copy(fact = ownPath(c.fact)))
        }
        val ownedSeeds = ownedList(seeds.map { seed -> when (seed) {
            is Seed.Source -> seed.copy(edge = seed.edge.copy(from = ownPath(seed.edge.from), to = ownPath(seed.edge.to)))
            is Seed.Sink -> Seed.Sink(seed.rule, seed.method, seed.statement, ownPattern(seed.requirement))
            is Seed.PredicateSink -> seed.copy()
        } })
        val builder = if (index == 1) null else DemandStore.Builder(ap).also { b -> rawDemand.forEach { b.add(it.first, it.second) } }
        // This reference fixture deliberately exercises the established GROUP contract.
        val config = RunConfig(index, L, builder?.build(), recordStore, SeedIndex.of(ownedSeeds), roots,
            run1MarkMode = MarkMode.GROUP)
        runInputs[config] = ProgramRunInputs(ownedList(roots), rawDemand, ownedList(rawRecords), ownedSeeds)
        return config
    }
    fun inputs(config: RunConfig): ProgramRunInputs = checkNotNull(runInputs[config]) { "The config belongs to this fixture" }

    fun field(name: String): Int = ap.accessors.index(FieldAccessor("Box", name, "Box"))
    fun mark(name: String): TaintMark = ap.marks.mark(name)
    fun pattern(base: AccessPathBase = AccessPathBase.Argument(0), path: List<Int> = emptyList(), tail: Tail = Tail.EXACT,
                mark: MarkSlot = MarkSlot.Concrete(mark("T")), exclusion: ExclusionSet = ExclusionSet.Empty): Pattern =
        Pattern(PathFact(base, ownedList(path), tail, mark), exclusion)
    fun fact(base: AccessPathBase = AccessPathBase.Argument(0), path: List<Int> = emptyList(), tail: Tail = Tail.EXACT,
             mark: MarkSlot = MarkSlot.Concrete(mark("T")), exclusion: ExclusionSet = ExclusionSet.Empty,
             layer: Layer = Layer.NORMAL): Facts {
        val fact = PathFact(base, ownedList(path), tail, mark)
        val value = ap.factsOf(fact, exclusion, layer)
        val demand = layer == Layer.DEMAND || tail == Tail.ANY
        val raw = if (base == AccessPathBase.Zero) Conclusion(fact, ExclusionSet.Empty, layer == Layer.DEMAND)
            else Conclusion(fact, if (tail == Tail.ANY || tail == Tail.EXACT) ExclusionSet.Empty else exclusion, demand)
        rawFacts[value] = listOf(raw)
        return value
    }
    fun record(method: MethodKey, direction: Direction, premise: InitialAp, conclusions: List<Conclusion>): Record {
        require(conclusions.isNotEmpty())
        val owned = ownedList(conclusions.map { it.copy(fact = ownPath(it.fact)) })
        val values = owned.map { ap.factsOf(it.fact, it.exclusion, if (it.demand) Layer.DEMAND else Layer.NORMAL) }
        val combined = values.reduce { a, b -> ap.mergeAddDelta(a, b).first }
        return Record(method, direction, premise, combined).also { recordInputs[it] = owned }
    }

    fun describe(): String = buildString {
        for (m in methods) appendLine("method=${m.method.name} adjacency=${m.successors} normal=${m.normalExit} exceptional=${m.exceptionalExit} backwardExitDiscovery=${m.backwardExitDiscovery}")
        val accessorIds = LinkedHashSet<Int>()
        val markIds = LinkedHashSet<Int>()
        fun key(k: MethodKey): String = "${k.method.name}/${k.context}/${k.statement.location.index}"
        fun exclusion(e: ExclusionSet) { if (e is ExclusionSet.Concrete) accessorIds.addAll(e.ids.toList()) }
        fun fact(f: PathFact): String {
            accessorIds.addAll(f.path)
            when (val mark = f.mark) {
                is MarkSlot.Concrete -> markIds += mark.mark.id
                is MarkSlot.Star -> markIds.addAll(mark.excluded.ids.toList())
            }
            return f.toString()
        }
        fun pattern(p: Pattern): String { fact(p.fact); exclusion(p.exclusion); return p.toString() }
        fun pathEdge(e: PathEdge): String {
            fact(e.from); fact(e.to); exclusion(e.exclusion); exclusion(e.fromExclusion); exclusion(e.toExclusion)
            return e.toString()
        }
        fun edge(e: MicroEdge): String = "edge=${pathEdge(e.edge)} forward=${pathEdge(e.forward)} conjunctive=${e.conjunctive}"
        fun summary(s: StatementSummary): String = "touched=${s.touched} edges=${s.edges.map(::edge)} " +
            "conjunctions=${s.conjunctions.map { "literals=${it.literals.map(::pattern)} target=${fact(it.target)}" }} " +
            "operandFilters=${s.typeFilters.map { (base, f) -> "$base:${f.may.javaClass.name}/markPolicy=${f.markPolicy != null}" }} " +
            "resultFilters=${s.resultFilters.map { (base, f) -> "$base:${f.may.javaClass.name}/markPolicy=${f.markPolicy != null}" }}"
        fun sink(s: SinkRule): String = "rule=${s.rule.id} alternative=${s.alternative} patterns=${s.patterns.map(::pattern)} " +
            "endFacts=${s.endFacts.map(::edge)}"
        fun rules(r: RuleStatement): String = "summary={${summary(r.summary)}} " +
            "endFacts={${summary(r.endFacts)}} sinks=${r.sinks.map(::sink)}"
        fun cleaner(c: Cleaner): String {
            val path = c.path?.toIntArray()?.toList()
            accessorIds.addAll(path.orEmpty())
            c.mark?.let { markIds += it.id }
            return "base=${c.base} path=$path reach=${c.reach} mark=${c.mark}"
        }
        fun action(a: CleanStep): String = when (a) {
            is CleanStep.Clean -> "Clean{${cleaner(a.cleaner)}}"
            is CleanStep.Kill -> "Kill{${summary(a.keepEdges)}}"
            is CleanStep.Field -> "Field{temporary=${a.temporary} read={${summary(a.read)}} " +
                "cleaner={${cleaner(a.cleaner)}} write={${summary(a.write)}}}"
        }
        fun stage(s: CallStage): String = "${s.from}->${s.to} " + when (s) {
            is CallStage.Edges -> "Edges(kind=${s.kind}, summary={${summary(s.summary)}}, guard=" +
                when (val g = s.guard) { null -> "none"; Guard.MemoryEffect -> "MemoryEffect"
                    is Guard.SinkTriggered -> "SinkTriggered{${sink(g.sink)}}" } +
                ", trigger=${s.trigger?.let(::sink)})"
            is CallStage.Actions -> "Actions(ordered=${s.steps.map(::action)})"
            is CallStage.Predefined -> "Predefined(target=${s.target}, summary={${summary(s.summary)}})"
            is CallStage.Callees -> "Callees(keys=${s.callees.map(::key)})"
        }
        for (row in statementInputs) appendLine("statement ${key(row.key)}:${row.index} ${summary(row.summary)}")
        for (row in entryInputs) appendLine("entry ${key(row.key)} ${rules(row.rules)}")
        for (row in exitInputs) appendLine("exit ${key(row.key)}:${row.index} ${rules(row.rules.rules)} " +
            "globalStateDrop=${row.rules.globalStateDrop} entryMarks=${row.rules.entryMarks}")
        for (row in callInputs) appendLine("call ${key(row.key)}:${row.index} expressionType=${row.expression.typeName} " +
            "touched=${row.plan.touched} entry=${row.plan.entry} exit=${row.plan.exit} " +
            "passReads=${row.plan.passReads} stages=${row.plan.stages.map(::stage)} sinks=${row.plan.sinks.map(::sink)}")
        val inputs = runInputs.entries.sortedWith(compareBy({ it.key.index }, { it.key.fieldLimit },
            { it.value.roots.joinToString(transform = ::key) }))
        for ((config, input) in inputs) {
            appendLine("run ${config.index} L=${config.fieldLimit} roots=${input.roots.map(::key)}")
            input.demand.forEach { (method, demand) -> appendLine("  demand ${key(method)} entry=${pattern(demand.entry)} exit=${demand.exit?.let(::pattern)}") }
            input.records.forEach { r ->
                fact(r.conclusion.fact); exclusion(r.conclusion.exclusion)
                appendLine("  record ${key(r.method)} ${r.direction} premise=${pattern(r.premise)} conclusion=${r.conclusion}")
            }
            for (seed in input.seeds) appendLine("  seed ${key(seed.method)}:${seed.statement.location.index} " + when (seed) {
                is Seed.Source -> "Source forward=${pathEdge(seed.edge)}"
                is Seed.Sink -> "Sink rule=${seed.rule.id} requirement=${pattern(seed.requirement)}"
                is Seed.PredicateSink -> "Sink predicate=${seed.occurrence}"
            })
        }
        appendLine("accessors=${accessorIds.sorted().associateWith { ap.accessors.accessor(it) }}")
        appendLine("marks=${markIds.sorted().associateWith { ap.marks.name(TaintMark(it)) }}")
    }
    override fun close() { if (sharedOwner.isInitialized()) sharedOwner.value.close() }
}

package org.opentaint.dataflow.bidi.fixtures

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.engine.*
import org.opentaint.dataflow.bidi.engine.historical.Run1Slot as HistoricalRun1Slot
import org.opentaint.dataflow.bidi.engine.historical.Run1StaticProfiles
import org.opentaint.dataflow.bidi.engine.historical.Run1StaticProfile
import org.opentaint.dataflow.bidi.engine.historical.Run1StaticLocalProfile
import org.opentaint.dataflow.bidi.engine.historical.Run1StaticFootprint
import org.opentaint.dataflow.bidi.engine.historical.StaticMarkInterest
import org.opentaint.dataflow.bidi.engine.historical.StaticMarkRole
import org.opentaint.dataflow.bidi.interp.*
import org.opentaint.dataflow.bidi.store.RequestMarkSet

/** Test-only extraction from explicit finite forms, independent of the JVM metadata collector. */
internal class FiniteStaticProfileLocal {
    private val accesses = LinkedHashSet<List<Int>>()
    private val abstractions = LinkedHashSet<List<Int>>()
    private val marks = LinkedHashSet<StaticMarkInterest>()
    private val wideClasses = LinkedHashSet<Int>()
    private val classPoints = LinkedHashSet<Int>()
    private var allStatic = false
    private var staticMayWrite = false

    private fun position(fact: PathFact, observe: Boolean = true, includeRoot: Boolean = false) {
        if (fact.base != STATIC || (fact.path.isEmpty() && !includeRoot)) return
        val slot = fact.path.take(2)
        if (!observe) return
        accesses += slot
        when (slot.size) {
            0 -> allStatic = true
            1 -> {
                classPoints += slot[0]
                if (fact.tail != Tail.EXACT) wideClasses += slot[0]
            }
        }
    }

    private fun literal(pattern: Pattern, role: StaticMarkRole) {
        if (pattern.fact.base != STATIC) return
        position(pattern.fact, includeRoot = true)
        val mark = (pattern.fact.mark as? MarkSlot.Concrete)?.mark ?: return
        marks += StaticMarkInterest(pattern, role, RequestMarkSet.of(mark))
    }

    private fun edge(value: MicroEdge, valueReads: Boolean = true, identityFieldReads: Boolean = false) {
        val from = value.edge.from
        val to = value.edge.to
        val identity = from == to && from.mark is MarkSlot.Star
        position(from, observe = !identity)
        position(to, observe = !identity, includeRoot = !identity)
        if ((!identity || (identityFieldReads && value.edge.exclusion == ExclusionSet.Empty)) &&
            valueReads && from.base == STATIC && from.mark is MarkSlot.Star && from.path.size >= 2)
            abstractions += from.path.take(2)
        if (to.base == STATIC && (from != to || value.edge.exclusion != ExclusionSet.Empty ||
                value.edge.fromExclusion != ExclusionSet.Empty || value.edge.toExclusion != ExclusionSet.Empty))
            staticMayWrite = true
        if (from.mark is MarkSlot.Concrete)
            literal(Pattern(from, ExclusionSet.Empty), StaticMarkRole.INPUT_GATE)
        val excluded = (to.mark as? MarkSlot.Star)?.excluded
        if (from.base == STATIC && excluded != null) for (id in excluded.ids) {
            literal(Pattern(from.copy(mark = MarkSlot.Concrete(TaintMark(id))), ExclusionSet.Empty),
                StaticMarkRole.INPUT_GATE)
        }
    }

    fun summary(value: StatementSummary, valueReads: Boolean = true, identityFieldReads: Boolean = false) {
        value.edges.forEach { edge(it, valueReads, identityFieldReads) }
        // A lowered strong write can contain no generated value, only keep edges.
        // Consume the most specific exclusion instead of treating its coarse class
        // exclusion as a write of every sibling/class point.
        for (micro in value.edges) {
            val from = micro.edge.from
            if (from.base != STATIC) continue
            val excluded = (micro.edge.exclusion as? ExclusionSet.Concrete)?.ids ?: continue
            for (next in excluded) {
                val target = from.path + next
                val refined = value.edges.any { other ->
                    other !== micro && other.edge.from.base == STATIC &&
                        other.edge.from.path.size >= target.size &&
                        other.edge.from.path.take(target.size) == target &&
                        other.edge.exclusion != ExclusionSet.Empty
                }
                if (!refined) position(from.copy(path = target), includeRoot = true)
            }
        }
        if (STATIC in value.touched && value.edges.none { it.edge.from.base == STATIC }) {
            allStatic = true
            staticMayWrite = true
        }
        for (source in value.sources) {
            source.predicate.leaves.forEach { literal(it, StaticMarkRole.SOURCE) }
            source.actions.forEach {
                position(it.target, includeRoot = true)
                if (it.target.base == STATIC) staticMayWrite = true
            }
        }
        for (conjunction in value.conjunctions) {
            conjunction.literals.forEach { literal(it, StaticMarkRole.SOURCE) }
            position(conjunction.target, includeRoot = true)
            if (conjunction.target.base == STATIC) staticMayWrite = true
        }
    }

    private fun sink(value: SinkRule) {
        (value.predicate?.leaves ?: value.patterns).forEach { literal(it, StaticMarkRole.SINK) }
        value.endFacts.forEach { edge(it) }
    }

    fun rules(value: RuleStatement) {
        summary(value.summary)
        summary(value.endFacts)
        value.sinks.forEach(::sink)
    }

    private fun clean(value: CleanStep) {
        when (value) {
            is CleanStep.Clean -> if (value.cleaner.base == STATIC) {
                position(PathFact(STATIC, value.cleaner.path?.toList().orEmpty(), Tail.STAR, MarkSlot.STAR),
                    includeRoot = true)
                staticMayWrite = true
                value.cleaner.mark?.let { mark ->
                    val path = value.cleaner.path?.toList().orEmpty()
                    literal(Pattern(PathFact(STATIC, path,
                        if (path.size == 1 && value.cleaner.reach == CleanReach.EXACT) Tail.EXACT else Tail.STAR,
                        MarkSlot.Concrete(mark)), ExclusionSet.Empty), StaticMarkRole.INPUT_GATE)
                }
            }
            is CleanStep.Kill -> summary(value.keepEdges, valueReads = false)
            is CleanStep.Field -> { summary(value.read, valueReads = false); summary(value.write, valueReads = false) }
        }
    }

    fun plan(value: CallPlan, callee: (MethodKey) -> Unit) {
        value.sinks.forEach(::sink)
        for (stage in value.stages) when (stage) {
            is CallStage.Edges -> summary(stage.summary, valueReads = stage.kind != StageKind.ALIASES,
                identityFieldReads = stage.kind == StageKind.UNRESOLVED)
            is CallStage.Actions -> stage.steps.forEach(::clean)
            is CallStage.Predefined -> Unit // Immutable models have no read/write micro-operations.
            is CallStage.Callees -> stage.callees.forEach(callee)
        }
    }

    fun profile(): Run1StaticLocalProfile = Run1StaticLocalProfile(accesses, abstractions, marks,
        RequestMarkSet.EMPTY, wideClasses, allStatic, classPoints, staticMayWrite)
}

package org.opentaint.dataflow.bidi.fixtures

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.interp.*
import org.opentaint.dataflow.util.Cancellation
import org.opentaint.ir.api.common.cfg.CommonCallExpr
import org.opentaint.ir.api.common.cfg.CommonInst
import java.util.IdentityHashMap

/** Explicit selected provider for finite tests. FULL construction rows remain the scalar
 * oracle's inputs. This projection deliberately retains the original positive DAG/proofs;
 * provider absorption and alias-collapse compatibility are tested by the JVM compiler tests.
 * Only fixtures whose distinct full leaves remain distinct GROUP leaves use this helper. */
internal class GroupRuleFixtureViews(private val marks: MarkTable, private val cancellation: Cancellation) {
    private val predicates = IdentityHashMap<RulePredicate, RulePredicate>()
    private val summaries = IdentityHashMap<StatementSummary, StatementSummary>()
    private val sources = IdentityHashMap<SourceRuleOccurrence, SourceRuleOccurrence>()
    private val sinks = IdentityHashMap<SinkRule, SinkRule>()
    private val rules = IdentityHashMap<RuleStatement, RuleStatement>()
    private val exits = IdentityHashMap<ExitRules, ExitRules>()
    private val calls = IdentityHashMap<CallPlan, CallPlan>()

    private fun pattern(p: Pattern): Pattern {
        val concrete = p.fact.mark as? MarkSlot.Concrete ?: return p
        return p.copy(fact = p.fact.copy(mark = MarkSlot.Concrete(marks.runtimeAtom(concrete.mark, MarkMode.GROUP))))
    }

    private fun predicate(full: RulePredicate): RulePredicate = predicates.getOrPut(full) {
        val selected = full.leaves.map(::pattern)
        require(selected.distinct().size == full.leaves.size) {
            "Alias-collapse fixtures must provide explicit source transfer hints, not this injective fixture view"
        }
        val builder = RulePredicate.Builder(cancellation)
        val nodes = IntArray(full.nodeCount)
        for (node in nodes.indices) nodes[node] = when (full.kind(node)) {
            RulePredicate.Kind.FALSE -> builder.falseNode
            RulePredicate.Kind.TRUE -> builder.trueNode
            RulePredicate.Kind.LEAF -> builder.leaf(selected[full.leafOrdinal(node)])
            RulePredicate.Kind.AND -> builder.and(buildList { full.childrenOf(node) { add(nodes[it]) } })
            RulePredicate.Kind.OR -> builder.or(buildList { full.childrenOf(node) { add(nodes[it]) } })
        }
        builder.build(nodes[full.root]).also { result ->
            for (leaf in full.leaves.indices) {
                val mapped = result.leaves.indexOf(selected[leaf])
                check(mapped >= 0 && full.isUnary(leaf) == result.isUnary(mapped) &&
                    full.isMulti(leaf) == result.isMulti(mapped))
            }
        }
    }

    fun source(full: SourceRuleOccurrence): SourceRuleOccurrence = sources.getOrPut(full) {
        check(!full.groupTransfers && !full.backward)
        // Injectivity above preserves unary/multi transfer modes, including original input
        // geometry. Full actions/occurrences stay identical; only positive admission changes.
        SourceRuleOccurrence(full.id, predicate(full.predicate), full.actions)
    }

    private fun sink(full: SinkRule): SinkRule = sinks.getOrPut(full) {
        val selected = full.predicate?.let(::predicate)
        SinkRule(full.rule, full.alternative, selected?.leaves ?: full.patterns.map(::pattern),
            full.endFacts, full.occurrenceId, selected)
    }

    private fun summary(full: StatementSummary): StatementSummary = summaries.getOrPut(full) {
        StatementSummary(full.touched, full.edges, full.conjunctions.map {
            ConjunctiveEdge(it.literals.map(::pattern), pattern(Pattern(it.target, ExclusionSet.Empty)).fact)
        }, full.typeFilters, full.resultFilters, full.sources.map(::source), full.staticOperations)
    }

    private fun rules(full: RuleStatement): RuleStatement = rules.getOrPut(full) {
        RuleStatement(summary(full.summary), summary(full.endFacts), full.sinks.map(::sink))
    }

    private fun exit(full: ExitRules): ExitRules = exits.getOrPut(full) {
        ExitRules(rules(full.rules), full.globalStateDrop,
            full.entryMarks.mapTo(LinkedHashSet()) { marks.runtimeAtom(it, MarkMode.GROUP) })
    }

    private fun call(full: CallPlan): CallPlan = calls.getOrPut(full) {
        CallPlan(full.touched, full.stages.map { stage -> when (stage) {
            is CallStage.Edges -> stage.copy(summary = summary(stage.summary),
                guard = (stage.guard as? Guard.SinkTriggered)?.let { Guard.SinkTriggered(sink(it.sink)) } ?: stage.guard,
                trigger = stage.trigger?.let(::sink))
            is CallStage.Predefined -> stage
            is CallStage.Actions -> stage
            is CallStage.Callees -> stage
        } }, full.sinks.map(::sink), full.entry, full.exit, full.passReads, full.zeroCanReturn)
    }

    fun forms(full: MethodForms): MethodForms = object : MethodForms by full {
        private fun selected(direction: Direction, view: RuleView): Boolean {
            check(view != RuleView.RUN1_GROUP || direction == Direction.FORWARD)
            return view == RuleView.RUN1_GROUP
        }
        override fun statement(direction: Direction, s: CommonInst, view: RuleView): StatementSummary =
            full.statement(direction, s).let { if (selected(direction, view)) summary(it) else it }
        override fun call(direction: Direction, s: CommonInst, call: CommonCallExpr, view: RuleView): CallPlan =
            full.call(direction, s, call).let { if (selected(direction, view)) this@GroupRuleFixtureViews.call(it) else it }
        override fun entryRules(direction: Direction, view: RuleView): RuleStatement =
            full.entryRules(direction).let { if (selected(direction, view)) rules(it) else it }
        override fun exitRules(direction: Direction, exit: CommonInst, view: RuleView): ExitRules =
            full.exitRules(direction, exit).let { if (selected(direction, view)) this@GroupRuleFixtureViews.exit(it) else it }
        override fun <R> withStatement(direction: Direction, s: CommonInst, view: RuleView, use: (StatementSummary) -> R): R =
            full.withStatement(direction, s) { use(if (selected(direction, view)) summary(it) else it) }
        override fun <R> withCall(direction: Direction, s: CommonInst, call: CommonCallExpr, view: RuleView, use: (CallPlan) -> R): R =
            full.withCall(direction, s, call) { use(if (selected(direction, view)) this@GroupRuleFixtureViews.call(it) else it) }
        override fun <R> withEntryRules(direction: Direction, view: RuleView, use: (RuleStatement) -> R): R =
            full.withEntryRules(direction) { use(if (selected(direction, view)) rules(it) else it) }
        override fun <R> withExitRules(direction: Direction, exit: CommonInst, view: RuleView, use: (ExitRules) -> R): R =
            full.withExitRules(direction, exit) { use(if (selected(direction, view)) this@GroupRuleFixtureViews.exit(it) else it) }
    }
}

package org.opentaint.dataflow.bidi.fixtures

import org.opentaint.dataflow.bidi.ap.*

/** Scalar group interpretation. It does not call the packed AP transfer, MarkGate,
 * runtimeFact, rule group index, or direct-static service. Full rule leaves/IDs remain inputs. */
internal class GroupedScalarMarks(private val table: MarkTable) {
    fun atom(mark: TaintMark): TaintMark = when (val key = table.key(mark)) {
        MarkAtomKey.ControlZero -> mark
        is MarkAtomKey.Group -> mark
        is MarkAtomKey.Full -> table.group(key.mark.group)
    }

    fun slot(mark: MarkSlot): MarkSlot = when (mark) {
        is MarkSlot.Concrete -> MarkSlot.Concrete(atom(mark.mark))
        is MarkSlot.Star -> MarkSlot.Star(MarkExclusions.of(table,
            mark.excluded.ids.map { atom(TaintMark(it)) }))
    }
    fun fact(fact: PathFact): PathFact = fact.copy(mark = slot(fact.mark))
    fun pattern(pattern: Pattern): Pattern = pattern.copy(fact = fact(pattern.fact))
    fun conclusion(value: Conclusion): Conclusion {
        if (value.fact.base == org.opentaint.dataflow.ap.ifds.AccessPathBase.Zero) return value
        val fact = fact(value.fact)
        return value.copy(fact = fact, demand = value.demand || fact.mark is MarkSlot.Concrete || fact.base == STATIC)
    }
    fun edge(edge: PathEdge): PathEdge = edge.copy(from = fact(edge.from), to = fact(edge.to))

    fun apply(value: Conclusion, edge: PathEdge, may: Boolean): EdgeOutcome {
        val input = conclusion(value)
        val form = edge(edge)
        // The scalar core uses full mx to suppress requests. Group interests are
        // unconditional on mx; erase it only for this FLOW->marked request gate.
        val query = if (input.fact.mark is MarkSlot.Star && form.from.mark is MarkSlot.Concrete)
            input.copy(fact = input.fact.copy(mark = MarkSlot.STAR)) else input
        return when (val result = concat(query, form, edgeDemand = may, run1 = true)) {
            is EdgeOutcome.Fact -> EdgeOutcome.Fact(conclusion(result.conclusion))
            else -> result
        }
    }

    fun check(initial: Pattern, value: Conclusion, literal: Pattern): CheckResult {
        val input = conclusion(value)
        val required = pattern(literal)
        val query = if (input.fact.mark is MarkSlot.Star)
            input.copy(fact = input.fact.copy(mark = MarkSlot.STAR)) else input
        return markCheck(initial, query, required, restricted = false)
    }

    fun clean(cleaner: Cleaner, value: Conclusion): CleanOut {
        val input = conclusion(value)
        // One selected full mark cannot remove an entire owner group. Structural
        // RemoveAll keeps the ordinary geometry-sensitive scalar clean operation.
        if (cleaner.mark != null && input.fact.mark is MarkSlot.Concrete)
            return CleanOut(listOf(input), null)
        val selected = cleaner.mark?.let(::atom)
        val out = cleanRes(Cleaner(cleaner.base, cleaner.path, cleaner.reach, selected), input, run1 = true)
        return CleanOut(out.facts.map(::conclusion), out.request?.let(::atom))
    }
}

internal fun selectedExpectedEdge(table: MarkTable, index: Int, edge: ObservedEdge): ObservedEdge {
    if (index != 1) return edge
    val scalar = GroupedScalarMarks(table)
    return edge.copy(premise = edge.premise.mapTo(LinkedHashSet(), scalar::pattern),
        conclusion = scalar.conclusion(edge.conclusion))
}

package org.opentaint.dataflow.bidi.fixtures

import org.opentaint.dataflow.bidi.interp.*

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.ir.api.common.cfg.CommonInst

/** Selected scalar oracle, in Group or later Full mode: rescan complete full-leaf NNF proofs. Ordinals and action IDs
 * remain distinct even when several full marks share one group. No runtime group index or
 * production incremental predicate/conjunction store is used. */
internal class GroupedSourcePredicates(private val manager: ApManager, grouped: Boolean = true) {
    private val groups = if (grouped) GroupedScalarMarks(manager.marks) else null
    private val run1Origins = RawRun1Origins()
    private data class Contribution(val premise: Set<Pattern>, val demand: Boolean)
    private data class Proof(val bindings: Map<Int, Contribution>, val order: List<Int>, val choices: List<Int>)
    private class State {
        val leaves = HashMap<Int, LinkedHashSet<Contribution>>()
        val emitted = HashSet<Proof>()
    }
    private val states = HashMap<Pair<RuleOccurrenceId, CommonInst>, State>()

    fun apply(source: SourceRuleOccurrence, premise: Set<Pattern>, c: Conclusion, node: CommonInst,
              mode: ApMode, statementEdge: Boolean,
              edge: (MicroEdge, Conclusion, Set<Pattern>, Boolean, ReferenceSink) -> Unit,
              request: (Set<Pattern>, ReferenceRequestKind) -> Unit,
              out: ReferenceSink,
              allows: (MicroEdge) -> Boolean = { true },
              hit: (MicroEdge) -> Unit = {}) {
        manager.cancellation.checkpoint()
        if (source.actions.isEmpty()) return
        val predicate = source.predicate
        if (source.backward) {
            // FormsReference historically has a forward default algebra. The descriptor selects
            // reversal; backward source reads are always restricted and never raise requests.
            for (action in source.actions) for ((ordinal, literal) in predicate.leaves.withIndex()) {
                manager.cancellation.checkpoint()
                fun transfer(multi: Boolean) {
                    val me = source.transfer(literal, action, multi)
                    val result = concat(c, me.edge, edgeDemand = me.may, restricted = true)
                    if (result is EdgeOutcome.Fact) { hit(me); out(premise, result.conclusion) }
                }
                if (predicate.isUnary(ordinal)) transfer(false)
                if (predicate.isMulti(ordinal)) transfer(true)
            }
            return
        }

        var state: State? = null
        var changed = false
        for ((ordinal, literal) in predicate.leaves.withIndex()) {
            manager.cancellation.checkpoint()
            if (predicate.isUnary(ordinal)) for (action in source.actions) {
                val transfer = source.transfer(literal, action)
                if (allows(transfer)) edge(transfer, c, premise, statementEdge, out)
            }
            if (!predicate.isMulti(ordinal)) continue
            val initial = if (c.fact.mark is MarkSlot.Star) {
                check(premise.size == 1) { "A FLOW reference input has one premise" }
                premise.single()
            } else premise.first()
            when (val checked = groups?.check(initial, c, literal) ?: markCheck(initial, c, literal, restricted = mode.restricted)) {
                CheckResult.None -> Unit
                is CheckResult.Request -> if (mode.run1)
                    request(premise, ReferenceRequestKind.Mark(checked.mark))
                CheckResult.Holds -> {
                    val owner = state ?: states.getOrPut(source.id to node) { State() }.also { state = it }
                    val owned = ownedSet(premise.map { p -> p.copy(fact = p.fact.copy(path = ownedList(p.fact.path))) })
                    changed = owner.leaves.getOrPut(ordinal) { LinkedHashSet() }
                        .add(Contribution(owned, groups != null || conjDemand(c, literal))) || changed
                }
            }
        }
        if (!changed) return
        val owner = checkNotNull(state)
        for (proof in proofs(predicate, owner)) {
            manager.cancellation.checkpoint()
            if (proof.bindings.size < 2 || !owner.emitted.add(proof)) continue
            val allPremises = proof.order.flatMap { proof.bindings.getValue(it).premise }
            val nonzero = allPremises.filter { it.fact.base != AccessPathBase.Zero }
            val resultPremises = if (mode.run1) run1Origins.split(proof.order.map { proof.bindings.getValue(it).premise })
                else listOf(if (nonzero.isEmpty()) setOf(ZERO_PATTERN) else ownedSet(nonzero))
            val demand = proof.bindings.values.any { it.demand }
            for (action in source.actions) {
                manager.cancellation.checkpoint()
                // Restricted source seeds authorize an action through an actually selected leaf.
                // The entire positive proof is still required, rather than treating that leaf as the condition.
                if (proof.bindings.keys.none { leaf -> allows(source.transfer(predicate.leaves[leaf], action, true)) }) continue
                val value = Conclusion(action.target, ExclusionSet.Empty, demand)
                for (pr in resultPremises) out(pr, groups?.conclusion(value) ?: value)
            }
        }
    }

    /** Re-evaluate bounded standing inputs bottom-up; no production indexes or delta joins are used. */
    private fun proofs(predicate: RulePredicate, state: State): List<Proof> {
        val values = arrayOfNulls<List<Proof>>(predicate.nodeCount)
        for (node in 0 until predicate.nodeCount) {
            manager.cancellation.checkpoint()
            values[node] = when (predicate.kind(node)) {
                RulePredicate.Kind.FALSE -> emptyList()
                RulePredicate.Kind.TRUE -> listOf(Proof(emptyMap(), emptyList(), emptyList()))
                RulePredicate.Kind.LEAF -> {
                    val leaf = predicate.leafOrdinal(node)
                    state.leaves[leaf].orEmpty().map { Proof(mapOf(leaf to it), listOf(leaf), emptyList()) }
                }
                RulePredicate.Kind.OR -> {
                    val result = ArrayList<Proof>()
                    predicate.childrenOf(node) { child ->
                        manager.cancellation.checkpoint()
                        for (proof in checkNotNull(values[child])) {
                            manager.cancellation.checkpoint()
                            result += proof.copy(choices = listOf(node, child) + proof.choices)
                        }
                    }
                    result
                }
                RulePredicate.Kind.AND -> {
                    var products = listOf(Proof(emptyMap(), emptyList(), emptyList()))
                    predicate.childrenOf(node) { child ->
                        val next = ArrayList<Proof>()
                        for (a in products) for (b in checkNotNull(values[child])) {
                            manager.cancellation.checkpoint()
                            merge(a, b)?.let(next::add)
                        }
                        products = next
                    }
                    products
                }
            }
        }
        return checkNotNull(values[predicate.root])
    }

    private fun merge(a: Proof, b: Proof): Proof? {
        for ((leaf, input) in b.bindings) if (leaf in a.bindings && a.bindings[leaf] != input) return null
        val bindings = LinkedHashMap(a.bindings)
        bindings.putAll(b.bindings)
        return Proof(bindings, a.order + b.order.filterNot { it in a.bindings }, a.choices + b.choices)
    }
}

package org.opentaint.dataflow.bidi.fixtures

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.driver.ReportBuilder
import org.opentaint.dataflow.bidi.engine.*
import org.opentaint.ir.api.common.cfg.CommonInst

/** Real frozen method actors with explicitly stated admitted barrier inputs. */
class HandOffFixtures(val index: Int = 1, val L: Int = maxOf(1, index - 1)) : AutoCloseable {
    val finite = MethodAnalysisFixtures()
    val manager get() = finite.manager
    val ops get() = finite.ops
    val shared get() = finite.shared
    val records get() = finite.records
    val vulnerabilities get() = finite.vulnerabilities
    val cancellation get() = finite.cancellation
    val config = finite.config(index, L)
    val report = ReportBuilder()
    private val actors = LinkedHashMap<MethodKey, RunMethodAnalyzer>()
    private var frozen = false

    fun key(context: String = "context", entry: Int = 0): MethodKey = finite.store.key(context, entry)
    fun inst(index: Int): CommonInst = finite.inst(index)
    fun field(name: String): Int = finite.field(name)
    fun mark(name: String): TaintMark = finite.mark(name)
    fun pattern(base: AccessPathBase = AccessPathBase.Argument(0), path: List<Int> = emptyList(),
                tail: Tail = Tail.EXACT, mark: MarkSlot = MarkSlot.Concrete(mark("T")),
                exclusion: ExclusionSet = ExclusionSet.Empty): Pattern = finite.pattern(base, path, tail, mark, exclusion)
    fun initial(base: AccessPathBase = AccessPathBase.Argument(0), path: List<Int> = emptyList(),
                tail: Tail = Tail.EXACT, mark: MarkSlot = MarkSlot.Concrete(mark("T")),
                exclusion: ExclusionSet = ExclusionSet.Empty): InitialAp =
        manager.initial(pattern(base, path, tail, mark, exclusion))
    fun premise(vararg members: InitialAp): PremiseKey = manager.premiseOf(members.toList())
    fun fact(base: AccessPathBase = AccessPathBase.Argument(0), path: List<Int> = emptyList(),
             tail: Tail = Tail.EXACT, mark: MarkSlot = MarkSlot.Concrete(mark("T")),
             exclusion: ExclusionSet = ExclusionSet.Empty, layer: Layer = Layer.NORMAL): Facts =
        finite.fact(base, path, tail, mark, exclusion, layer)

    fun core(key: MethodKey = key(), localFactory: MethodLocalServicesFactory? = null,
             callFactory: MethodCallServicesFactory? = null): RunMethodAnalyzer =
        actors[key] ?: run {
            check(!frozen) { "A frozen hand-off fixture cannot construct another actor" }
            finite.core(config, localFactory, callFactory, key).also { actors[key] = it }
        }

    fun admit(core: RunMethodAnalyzer, ref: org.opentaint.dataflow.bidi.store.CallerRef, layer: Layer, facts: Facts) =
        finite.admit(core, ref, layer, facts)
    fun links(core: RunMethodAnalyzer) = finite.links(core)

    fun drain(core: RunMethodAnalyzer, quantum: Int = 1000): Int = finite.drain(core, quantum)

    /** Prescribe an admitted row. The outgoing view computes final-header selection. */
    fun summary(key: MethodKey, premise: PremiseKey, facts: Facts): Facts? {
        check(!frozen)
        return core(key).summaries.addAdmitted(premise, facts)
    }
    fun hit(key: MethodKey, statement: CommonInst, forward: PathEdge): Boolean {
        check(!frozen)
        return checkNotNull(core(key).sourceHits) { "Only a backward actor has a source-hit store" }
            .add(key, statement, forward)
    }

    /** Full method closure and actor freeze precede the retained result used by the barrier. */
    fun result(status: RunStatus = RunStatus.COMPLETE, order: List<MethodKey>? = null): RunResult<RunMethodAnalyzer> {
        if (status != RunStatus.COMPLETE) return RunResult(status, emptyList(), index, config.direction)
        if (!frozen) {
            actors.values.forEach { drain(it) }
            actors.values.forEach { it.freeze() }
            frozen = true
        }
        val keys = order ?: actors.keys.toList()
        check(keys.toSet() == actors.keys && keys.size == actors.size) { "A result order contains every actor exactly once" }
        return RunResult(status, keys.map(actors::getValue), index, config.direction)
    }

    override fun close(): Unit = finite.close()
}

package org.opentaint.dataflow.bidi.fixtures

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.ap.ReferenceRequestKind as RequestKind
import org.opentaint.dataflow.bidi.driver.Seed
import org.opentaint.dataflow.bidi.engine.RunConfig
import org.opentaint.dataflow.bidi.interp.*
import org.opentaint.ir.api.common.cfg.CommonInst
import java.util.ArrayDeque

/**
 * Direct concrete restricted-run backend for F71, pinned to proof-history.md's fb789d0ab snapshot.
 * The copied work-list driver intentionally has separate selector/emission/cleaner implementations.
 * Supported differential domain: finite call/read/move/primitive-cleaner programs, exact concrete
 * sources, ordinary singleton records, literal/conjunctive sinks, no alias guard or end-fact GEN.
 * Explicit opt-ins admit specified END interpreter rules or refined F69 must sources; neither
 * imports F76 read views. The historical reader retains the older R3 policy in every mode.
 * Raw demand entries may carry abstract mark exclusions: no current DemandStore is consulted.
 */
class HistoricalConcreteClosure(private val program: FiniteProgramFixtures, private val config: RunConfig,
                                private val inputs: ProgramRunInputs,
                                private val allowEndFacts: Boolean = false,
                                private val allowMustSources: Boolean = false) {
    private val forward = config.direction == Direction.FORWARD
    private val zero = setOf(ZERO_PATTERN)
    private val work = ArrayDeque<() -> Unit>()
    private val processed = LinkedHashSet<ObservedEdge>()
    private val initials = LinkedHashSet<ObservedInitial>()
    private val rawSummaries = LinkedHashSet<ObservedEdge>()
    private val publications = LinkedHashSet<ObservedEdge>()
    private val selectedDemand = LinkedHashSet<ObservedEdge>()
    private val links = LinkedHashSet<ObservedLink>()
    private val requests = LinkedHashSet<ObservedRequest>()
    private val sourceHits = LinkedHashSet<ObservedSourceHit>()
    private val witnesses = LinkedHashSet<ObservedWitness>()
    private val subscriptions = LinkedHashSet<Part>()
    private val joined = HashSet<Joined>()
    private val literalInputs = HashMap<LiteralKey, MutableList<LinkedHashSet<LiteralInput>>>()
    private val literalCombinations = HashSet<LiteralCombination>()
    private val triggered = HashSet<Triple<MethodKey, CommonInst, SinkRule>>()
    private val algebras = HashMap<MethodKey, ReferenceAlgebra>()
    private val references = HashMap<MethodKey, FormsReference>()
    private var invoked = false

    private data class Part(
        val callee: MethodKey,
        val caller: MethodKey,
        val premise: Set<Pattern>,
        val callerLayer: Layer,
        val call: CommonInst,
        val added: Conclusion,
        val zeroOnly: Boolean = false,
    )
    private data class Joined(val publication: ObservedEdge, val call: CommonInst, val parts: List<Part>)
    private data class LiteralKey(val method: MethodKey, val node: CommonInst, val rule: Any)
    private data class LiteralInput(val premise: Set<Pattern>, val conclusion: Conclusion)
    private data class LiteralCombination(val key: LiteralKey, val values: List<LiteralInput>)
    private data class Checks(val fired: List<Pair<SinkRule, Layer>>, val parts: List<Conclusion>)

    fun run(): RunObservation {
        check(!invoked) { "An oracle instance has one closure" }
        invoked = true
        HistoricalF71.validate(program, inputs, allowEndFacts, allowMustSources)
        for (root in inputs.roots) if (program.isKnown(root)) addInitial(root, ZERO_PATTERN)
        while (work.isNotEmpty()) {
            program.manager.cancellation.checkpoint()
            work.removeFirst().invoke()
        }
        return RunObservation(processed = processed.toSet(), initials = initials.toSet(),
            rawSummaries = rawSummaries.toSet(), publications = publications.toSet(),
            selectedDemand = selectedDemand.toSet(), links = links.toSet(), requests = requests.toSet(),
            sourceHits = sourceHits.toSet(), witnesses = witnesses.toSet())
    }

    private fun algebra(method: MethodKey): ReferenceAlgebra = algebras.getOrPut(method) {
        ReferenceAlgebra(config.mode,
            request = { premise, request -> raise(method, premise, request) },
            allowsSource = { node, edge -> !config.seededSources || inputs.seeds.any { seed ->
                seed is Seed.Source && seed.method == method && seed.statement == node && seed.edge == edge.forward
            } },
            sourceHit = { node, edge -> if (!forward) sourceHits += ObservedSourceHit(method, node, edge.forward) },
            manager = program.manager,
            // Keep the pre-selective-preservation F1 transfer, including its native E.
            historicalRun1 = true,
            conjunction = { edge, premise, conclusion, node, sink ->
                check(forward) { "Backward forms have independent conjunction branches" }
                for ((index, literal) in edge.literals.withIndex()) {
                    program.manager.cancellation.checkpoint()
                    when (val checked = checkLiteral(method, premise, conclusion, literal)) {
                        null -> Unit
                        else -> for (combination in literal(method, node, edge, edge.literals.size, index,
                            LiteralInput(premise, checked))) {
                            val pr = union(combination.map { it.premise })
                            val demand = combination.any { it.conclusion.demand }
                            sink(pr, HistoricalF71.normalize(edge.target, ExclusionSet.Empty, demand))
                        }
                    }
                }
            })
    }

    private fun reference(method: MethodKey): FormsReference = references.getOrPut(method) {
        FormsReference(program.ops, algebra(method), run1AliasAdmission = false)
    }

    private fun addInitial(method: MethodKey, initial: Pattern) {
        if (!program.isKnown(method) || !initials.add(ObservedInitial(method, initial))) return
        check(initial.fact.tail != Tail.ANY_TAINT || (config.restricted && forward))
        work += {
            val value = startFact(initial)
            val model = program.programMethod(method)
            val nodes = if (forward) listOf(method.statement) else buildList {
                add(program.inst(method, model.normalExit))
                if (initial.fact.base == AccessPathBase.Zero)
                    model.exceptionalExit?.let { add(program.inst(method, it)) }
            }
            for (node in nodes) {
                program.manager.cancellation.checkpoint()
                val forms = program.forms(method)
                val rules = if (forward) forms.entryRules(Direction.FORWARD)
                    else forms.exitRules(Direction.BACKWARD, node).rules
                val seeds = if (!forward && initial.fact.base == AccessPathBase.Zero) seedFacts(method, node) else emptyList()
                for (item in boundary(method, node, rules, listOf(setOf(initial) to value) + seeds))
                    putEdge(method, node, item.first, item.second)
            }
        }
    }

    private fun putEdge(method: MethodKey, node: CommonInst, premise: Set<Pattern>, conclusion: Conclusion) {
        val edge = ObservedEdge(method, premise, conclusion, node)
        if (processed.add(edge)) work += { process(edge) }
    }

    private fun process(edge: ObservedEdge) {
        val node = checkNotNull(edge.node)
        val call = program.callExpression(edge.method, node.location.index)
        if (call != null) {
            val plan = program.forms(edge.method).call(config.direction, node, call)
            when {
                edge.conclusion.fact.base == AccessPathBase.Zero -> {
                    emitAfter(edge.method, node, edge.premise, edge.conclusion)
                    if (isZero(edge.premise)) {
                        if (forward) walk(edge.method, node, plan,
                            listOf(PlanItem(edge.premise, edge.conclusion, null)), layer(edge.conclusion))
                        else {
                            val seeds = seedFacts(edge.method, node).map { PlanItem(it.first, it.second, null) }
                            if (seeds.isNotEmpty()) walk(edge.method, node, plan, seeds,
                                layer(edge.conclusion), from = CallPoint.BOUND)
                            for (callee in calleeStage(plan)?.callees.orEmpty()) {
                                subscribe(Part(callee, edge.method, edge.premise, layer(edge.conclusion),
                                    node, edge.conclusion, zeroOnly = true))
                                addInitial(callee, ZERO_PATTERN)
                            }
                        }
                    } else check(!forward) { "A concrete-premise REACH edge belongs to a backward run" }
                }
                edge.conclusion.fact.base !in plan.touched ->
                    emitAfter(edge.method, node, edge.premise, edge.conclusion)
                else -> walk(edge.method, node, plan, listOf(PlanItem(edge.premise, edge.conclusion, null)),
                    layer(edge.conclusion))
            }
            return
        }
        reference(edge.method).applier.statement(program.forms(edge.method).statement(config.direction, node),
            edge.premise, edge.conclusion, Place(node, config.run1, sources = true),
            sink = { pr, conclusion -> emitAfter(edge.method, node, pr, limit(conclusion, config.fieldLimit)) },
            untouched = { pr, conclusion -> emitAfter(edge.method, node, pr, conclusion) })
    }

    private fun emitAfter(method: MethodKey, node: CommonInst, premise: Set<Pattern>, conclusion: Conclusion) {
        val model = program.programMethod(method)
        val summaryEnd = if (forward) node.location.index == model.normalExit else node == method.statement
        val exceptional = forward && node.location.index == model.exceptionalExit
        if (summaryEnd || exceptional) {
            val exit = if (forward) program.forms(method).exitRules(Direction.FORWARD, node)
                else ExitRules(program.forms(method).entryRules(Direction.BACKWARD), false, emptySet())
            boundary(method, node, exit.rules, listOf(premise to conclusion)) { pr, value, checks ->
                if (summaryEnd && program.interpreter.isSummaryBase(value.fact.base)) {
                    val dropStatic = exit.globalStateDrop && isZero(pr) && value.fact.base == STATIC && value in checks.parts
                    val mark = (value.fact.mark as? MarkSlot.Concrete)?.mark
                    val removeMark = isZero(pr) && mark != null &&
                        (value.fact.base == AccessPathBase.This || value.fact.base is AccessPathBase.Argument) &&
                        mark in exit.entryMarks
                    if (!dropStatic && !removeMark) summary(method, pr, value)
                }
            }
        }
        val next = if (forward) model.successors[node.location.index] else
            model.successors.indices.filter { node.location.index in model.successors[it] }
        for (index in next) putEdge(method, program.inst(method, index), premise, conclusion)
    }

    private fun boundary(method: MethodKey, node: CommonInst, rules: RuleStatement,
                         startInputs: List<Pair<Set<Pattern>, Conclusion>>,
                         after: (Set<Pattern>, Conclusion, Checks) -> Unit = { _, _, _ -> }): List<Pair<Set<Pattern>, Conclusion>> {
        val items = ArrayList<Pair<Set<Pattern>, Conclusion>>()
        val seen = HashSet<Pair<Set<Pattern>, Conclusion>>()
        val add: ReferenceSink = { pr, value ->
            val item = pr to limit(value, config.fieldLimit)
            if (seen.add(item)) items += item
        }
        val applier = reference(method).applier
        fun applyInput(pr: Set<Pattern>, value: Conclusion) =
            applier.statement(rules.summary, pr, value, Place(node, config.run1, sources = true), add)
        for ((pr, value) in startInputs) applyInput(pr, value)
        var index = 0
        while (index < items.size) {
            program.manager.cancellation.checkpoint()
            val (pr, value) = items[index++]
            val checks = sinks(method, node, pr, value, rules.sinks)
            for ((sink, layer) in checks.fired)
                applier.gen(sink.endFacts, zero, Conclusion(ZERO_FACT, ExclusionSet.Empty, layer == Layer.DEMAND), add)
            if (!forward) for (sink in rules.sinks) {
                val ends = rules.endFacts.edges.filter { edge -> sink.endFacts.any { it.forward == edge.forward } }
                var applied = false
                applier.gen(ends, pr, value) { p, result -> applied = true; add(p, result) }
                if (applied) for ((seedPr, seed) in triggerSeeds(method, node, sink)) applyInput(seedPr, seed)
            }
            after(pr, value, checks)
        }
        return items
    }

    private fun summary(method: MethodKey, premise: Set<Pattern>, conclusion: Conclusion) {
        val raw = ObservedEdge(method, premise, conclusion)
        if (!rawSummaries.add(raw)) return
        val selected = premise.size > 1 || if (forward)
            !HistoricalF71.cross(premise.single(), conclusion)
        else isZero(premise) || !HistoricalF71.crossBackward(premise.single(), conclusion)
        val pieces = if (config.run1 || (!forward && isZero(premise))) setOf(conclusion) else buildSet {
            for (member in premise) for ((target, demand) in inputs.demand) if (target == method)
                HistoricalF71.restrict(member, conclusion, demand)?.let { add(it) }
        }
        for (piece in pieces) {
            val pub = ObservedEdge(method, premise, piece)
            if (selected) selectedDemand += pub
            if (publications.add(pub)) work += {
                for (part in subscriptions.toList()) if (part.callee == method) match(part, pub)
            }
        }
    }

    private fun walk(method: MethodKey, node: CommonInst, plan: CallPlan, items: List<PlanItem>,
                     callerLayer: Layer, from: CallPoint = plan.entry, pendingDemotion: Boolean = false) {
        val hooks = PlanHooks(guards = forward,
            atBound = { batch -> batch.flatMap { sinks(method, node, it.premise, it.c, plan.sinks).fired }.distinct() },
            callees = { stage, item ->
                for (callee in stage.callees) {
                    val part = Part(callee, method, item.premise, callerLayer, node, item.c)
                    subscribe(part)
                    link(part)
                }
                emptyList()
            },
            clean = { cleaner, item ->
                val result = HistoricalF71.clean(cleaner, item.c)
                if (config.run1) result.request?.let { raise(method, item.premise, RequestKind.Mark(it)) }
                result.facts.map { item.copy(c = it) }
            },
            statementCut = { item -> item.copy(c = limit(item.c, config.fieldLimit)) },
            exit = { item -> item.copy(c = limit(item.c, config.fieldLimit)) },
            trigger = { sink -> triggerSeeds(method, node, sink).map { PlanItem(it.first, it.second, null) } })
        for ((point, item) in reference(method).run(plan, items, Place(node, config.run1, sources = false),
            hooks, from, pendingDemotion)) if (point == plan.exit)
            emitAfter(method, node, item.premise, item.c)
    }

    private fun link(part: Part) {
        if (!program.isKnown(part.callee)) return
        val added = Pattern(part.added.fact, part.added.exclusion)
        val link = ObservedLink(part.callee, part.caller, part.premise, part.callerLayer, part.call,
            layer(part.added), added)
        if (!links.add(link)) return
        work += {
            when {
                config.run1 -> addInitial(part.callee, policy(added))
                added.fact.base == AccessPathBase.Zero -> addInitial(part.callee, ZERO_PATTERN)
                else -> for ((method, demand) in inputs.demand) if (method == part.callee)
                    HistoricalF71.emit(demand.entry, added)?.let { addInitial(method, it) }
            }
            for (request in requests.toList()) if (request.method == part.callee) act(request, link)
        }
    }

    private fun subscribe(part: Part) {
        if (!program.isKnown(part.callee) || !subscriptions.add(part)) return
        work += {
            for (pub in publications.toList()) if (pub.method == part.callee) match(part, pub)
            if (config.restricted && !part.zeroOnly) {
                val seen = HashSet<RecordLeafView>()
                for (record in inputs.records) if (record.method == part.callee) {
                    if (record.direction == config.direction) native(part, record)
                    else HistoricalF71.reverseRecord(record.premise, record.conclusion)?.let { view ->
                        if (seen.add(view)) view(part, view)
                    }
                }
            }
        }
    }

    private fun match(part: Part, pub: ObservedEdge) {
        if (part.zeroOnly) {
            if (isZero(pub.premise)) resume(part, listOf(PlanItem(part.premise, pub.conclusion, false)))
            return
        }
        if (pub.premise.size == 1) {
            val premise = pub.premise.single()
            if (HistoricalF71.satisfies(premise, Pattern(part.added.fact, part.added.exclusion), config.restricted))
                reduce(part, premise, pub.conclusion)?.let { resume(part, listOf(it)) }
            return
        }
        check(forward) { "Backward publications cannot be conjunctive" }
        val choices = pub.premise.map { member -> subscriptions.filter { candidate ->
            !candidate.zeroOnly && candidate.callee == pub.method && candidate.caller == part.caller &&
                candidate.call == part.call && candidate.added.fact.base != AccessPathBase.Zero &&
                HistoricalF71.satisfies(member, Pattern(candidate.added.fact, candidate.added.exclusion), config.restricted)
        } }
        for (parts in product(choices)) if (joined.add(Joined(pub, part.call, parts))) {
            val pr = union(parts.map { it.premise })
            val demand = pub.conclusion.demand || parts.any { it.added.demand }
            val result = HistoricalF71.normalize(pub.conclusion.fact, pub.conclusion.exclusion, demand)
            resume(parts.first(), listOf(PlanItem(pr, result, false)))
        }
    }

    private fun native(part: Part, record: RawRecord) {
        val added = Pattern(part.added.fact, part.added.exclusion)
        if (!applicable(record.premise, added) && !inside(record.premise, added)) return
        val pending = record.premise.fact.tail == Tail.ANY_TAINT && !inside(record.premise, added)
        val result = reduce(part, record.premise, record.conclusion) ?: return
        resume(part, listOf(if (pending) result.copy(identityCandidate = false) else result), pending)
    }

    private fun view(part: Part, view: RecordLeafView) {
        val added = Pattern(part.added.fact, part.added.exclusion)
        if (!applicable(view.premise, added) && !inside(view.premise, added)) return
        val outcome = concat(part.added, summaryEdge(view.premise, view.result), edgeDemand = view.result.demand,
            restricted = config.restricted)
        check(outcome !is EdgeOutcome.Request && outcome !is EdgeOutcome.PositionRequest)
        if (outcome is EdgeOutcome.Fact)
            resume(part, listOf(PlanItem(part.premise, outcome.conclusion, recordLeafIdentity(view))))
    }

    private fun reduce(part: Part, premise: Pattern, conclusion: Conclusion): PlanItem? {
        val outcome = concat(part.added, summaryEdge(premise, conclusion), edgeDemand = conclusion.demand,
            restricted = config.restricted)
        check(outcome !is EdgeOutcome.Request && outcome !is EdgeOutcome.PositionRequest)
        if (outcome !is EdgeOutcome.Fact) return null
        val identity = premise.fact.base != AccessPathBase.Zero && !conclusion.demand && conclusion == startFact(premise)
        return PlanItem(part.premise, outcome.conclusion, identity)
    }

    private fun resume(part: Part, items: List<PlanItem>, pendingDemotion: Boolean = false) {
        if (items.isEmpty()) return
        val expression = checkNotNull(program.callExpression(part.caller, part.call.location.index))
        val plan = program.forms(part.caller).call(config.direction, part.call, expression)
        val stage = checkNotNull(calleeStage(plan))
        walk(part.caller, part.call, plan, items, part.callerLayer, stage.to, pendingDemotion)
    }

    private fun checkLiteral(method: MethodKey, premise: Set<Pattern>, conclusion: Conclusion, literal: Pattern): Conclusion? =
        when (val checked = markCheck(premise.first(), conclusion, literal, config.restricted)) {
            CheckResult.None -> null
            is CheckResult.Request -> { raise(method, premise, RequestKind.Mark(checked.mark)); null }
            CheckResult.Holds -> conclusion.copy(demand = conjDemand(conclusion, literal))
        }

    private fun sinks(method: MethodKey, node: CommonInst, premise: Set<Pattern>, conclusion: Conclusion,
                      sinks: List<SinkRule>): Checks {
        if (!forward) return Checks(emptyList(), emptyList())
        val fired = ArrayList<Pair<SinkRule, Layer>>()
        val parts = ArrayList<Conclusion>()
        for (sink in sinks) for ((index, pattern) in sink.patterns.withIndex()) {
            val checked = checkLiteral(method, premise, conclusion, pattern) ?: continue
            parts += checked
            val input = LiteralInput(premise, checked)
            val combinations = if (!sink.conjunctive) listOf(listOf(input)) else
                literal(method, node, sink, sink.patterns.size, index, input)
            for (combination in combinations) {
                val effectiveLayer = if (combination.any { it.conclusion.demand }) Layer.DEMAND else Layer.NORMAL
                witnesses += ObservedWitness(sink.rule, method, node, sink.alternative, config.index,
                    combination.map { ObservedSinkEdge(it.premise, layer(it.conclusion), setOf(it.conclusion)) },
                    sink.endFacts.mapTo(LinkedHashSet()) { it.edge.to })
                fired += sink to effectiveLayer
            }
        }
        return Checks(fired.distinct(), parts)
    }

    private fun literal(method: MethodKey, node: CommonInst, rule: Any, arity: Int, index: Int,
                        input: LiteralInput): List<List<LiteralInput>> {
        val key = LiteralKey(method, node, rule)
        val slots = literalInputs.getOrPut(key) { MutableList(arity) { LinkedHashSet() } }
        check(slots.size == arity)
        if (!slots[index].add(input)) return emptyList()
        return product(slots.map { it.toList() }).filter { literalCombinations.add(LiteralCombination(key, it)) }
    }

    private fun raise(method: MethodKey, premise: Set<Pattern>, kind: RequestKind) {
        check(config.run1) { "Restricted runs have no requests" }
        val initial = premise.single()
        check(initial.fact.mark == MarkSlot.STAR && initial.fact.tail == Tail.STAR && initial.exclusion == ExclusionSet.Empty)
        val request = ObservedRequest(method, initial, kind)
        if (requests.add(request)) work += {
            for (link in links.toList()) if (link.callee == method) act(request, link)
        }
    }

    private fun act(request: ObservedRequest, link: ObservedLink) {
        val query = when (val kind = request.kind) {
            is RequestKind.Mark -> request.premise
            is RequestKind.Position -> Pattern(PathFact(STATIC, kind.path.toList(), Tail.STAR, MarkSlot.STAR), ExclusionSet.Empty)
        }
        if (!overlap(query, link.added)) return
        when (val kind = request.kind) {
            is RequestKind.Mark -> when (val mark = link.added.fact.mark) {
                is MarkSlot.Concrete -> if (mark.mark == kind.mark)
                    addInitial(request.method, answer(request.premise, link.added, kind.mark))
                is MarkSlot.Star -> if (kind.mark !in mark.excluded) raise(link.caller, link.premise, kind)
            }
            is RequestKind.Position -> when {
                link.added.fact.path.startsWith(kind.path.toList()) ->
                    addInitial(request.method, Pattern(PathFact(STATIC, kind.path.toList(), Tail.STAR, MarkSlot.STAR), ExclusionSet.Empty))
                link.premise.singleOrNull()?.fact?.base == STATIC -> raise(link.caller, link.premise, kind)
            }
        }
    }

    private fun seedFacts(method: MethodKey, node: CommonInst): List<Pair<Set<Pattern>, Conclusion>> =
        inputs.seeds.filterIsInstance<Seed.Sink>().filter { it.method == method && it.statement == node }
            .map { zero to limit(HistoricalF71.normalize(it.requirement.fact, ExclusionSet.Empty, false), config.fieldLimit) }

    private fun triggerSeeds(method: MethodKey, node: CommonInst, sink: SinkRule): List<Pair<Set<Pattern>, Conclusion>> =
        if (!triggered.add(Triple(method, node, sink))) emptyList() else sink.seedPatterns().map {
            zero to limit(HistoricalF71.normalize(it.fact, ExclusionSet.Empty, false), config.fieldLimit)
        }

    private fun union(premises: List<Set<Pattern>>): Set<Pattern> {
        val values = premises.flatten().filterTo(LinkedHashSet()) { it.fact.base != AccessPathBase.Zero }
        return if (values.isEmpty()) zero else values
    }

    private fun <T> product(slots: List<List<T>>): List<List<T>> {
        var result: List<List<T>> = listOf(emptyList())
        for (slot in slots) {
            program.manager.cancellation.checkpoint()
            result = result.flatMap { before -> slot.map { before + it } }
        }
        return result
    }

    private fun calleeStage(plan: CallPlan): CallStage.Callees? =
        plan.stages.firstNotNullOfOrNull { it as? CallStage.Callees }
    private fun isZero(premise: Set<Pattern>): Boolean = premise.size == 1 && premise.single().fact.base == AccessPathBase.Zero
    private fun layer(conclusion: Conclusion): Layer = if (conclusion.demand) Layer.DEMAND else Layer.NORMAL
}

package org.opentaint.dataflow.bidi.fixtures

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.driver.Seed
import org.opentaint.dataflow.bidi.driver.SeedIndex
import org.opentaint.dataflow.bidi.engine.RunConfig
import org.opentaint.dataflow.bidi.interp.SinkRule
import org.opentaint.dataflow.bidi.interp.ZERO_PATTERN
import org.opentaint.dataflow.bidi.store.DemandStore
import org.opentaint.dataflow.bidi.store.PersistentRecordStore
import org.opentaint.dataflow.bidi.store.RuleId
import org.opentaint.ir.api.common.cfg.CommonInst

enum class HistoricalState { DEMAND, CONFIRMED }
data class HistoricalFinding(val rule: RuleId, val statement: CommonInst)
data class HistoricalRun(val index: Int, val inputs: ProgramRunInputs, val observation: RunObservation,
                         val handOff: ProgramRunInputs)
data class HistoricalIterationResult(val findings: Map<HistoricalFinding, HistoricalState>, val runs: List<HistoricalRun>)

/**
 * F71's finite concrete iteration, with direct raw barriers and least support. No current HandOff,
 * ReportBuilder, Support, DemandStore lookup, record index or summary selector computes the answer.
 * A RunConfig is only an ApMode carrier; raw excluded-mark demands remain separate from its empty
 * typed store. The differential domain is validated by HistoricalF71, not widened silently.
 * Opt-in END rules are argued interpreter semantics, not a theorem of the historical Lean closure.
 */
class HistoricalConcreteIteration(private val program: FiniteProgramFixtures, private val roots: List<MethodKey>,
                                  private val limits: List<Int>,
                                  private val allowEndFacts: Boolean = false,
                                  private val allowMustSources: Boolean = false) {
    init {
        require(limits.isNotEmpty() && limits.all { it >= 1 })
        require(limits.zipWithNext().all { (a, b) -> b >= a })
    }

    fun run(): HistoricalIterationResult {
        var demand = emptyList<Pair<MethodKey, DemandPattern>>()
        var seeds = emptyList<Seed>()
        val records = LinkedHashSet<RawRecord>()
        val confirmed = LinkedHashMap<HistoricalFinding, HistoricalState>()
        var currentDemand = LinkedHashMap<HistoricalFinding, HistoricalState>()
        val log = ArrayList<HistoricalRun>()
        for ((offset, limit) in limits.withIndex()) {
            program.cancellation.checkpoint()
            val index = offset + 1
            val config = RunConfig(index, limit,
                if (index == 1) null else DemandStore.Builder(program.ap).build(),
                PersistentRecordStore(program.ap), SeedIndex.of(seeds), roots,
                run1MarkMode = MarkMode.GROUP)
            val inputs = ProgramRunInputs(roots.toList(), demand.toList(), records.toList(), seeds.toList())
            var observation = HistoricalConcreteClosure(program, config, inputs, allowEndFacts, allowMustSources).run()
            if (config.direction == Direction.FORWARD) {
                observation = confirm(observation, roots, config.restricted)
                currentDemand = LinkedHashMap()
                for (witness in observation.witnesses) {
                    val key = HistoricalFinding(witness.rule, witness.statement)
                    if (witness.confirmed) confirmed[key] = HistoricalState.CONFIRMED
                    else if (key !in confirmed) currentDemand[key] = HistoricalState.DEMAND
                }
                // A later witness of the same key can confirm it; remove the earlier demand row.
                confirmed.keys.forEach(currentDemand::remove)
            }
            // Historical R1, independently scanned before hand-off. Raw native singleton facts only.
            for (edge in observation.rawSummaries) if (!edge.conclusion.demand && edge.premise.size == 1 &&
                !(config.direction == Direction.BACKWARD && isZero(edge.premise))) {
                records += RawRecord(edge.method, config.direction, edge.premise.single(), edge.conclusion)
            }
            demand = handOff(config.direction, observation)
            seeds = if (config.direction == Direction.FORWARD) sinkSeeds(observation, currentDemand.keys)
                else observation.sourceHits.map { Seed.Source(it.method, it.statement, it.forward) }
            log += HistoricalRun(index, inputs, observation,
                ProgramRunInputs(roots.toList(), demand.toList(), records.toList(), seeds.toList()))
            if (config.direction == Direction.FORWARD && (currentDemand.isEmpty() ||
                (observation.processed.none { it.conclusion.demand } &&
                    observation.rawSummaries.none { it.conclusion.demand } &&
                    observation.links.none { it.linkLayer == Layer.DEMAND }))) break
        }
        return HistoricalIterationResult(LinkedHashMap<HistoricalFinding, HistoricalState>().also {
            it.putAll(confirmed); it.putAll(currentDemand)
        }, log.toList())
    }

    /** HandoffDefs.lean handF/demOfN: selected publications swap; F71 keeps abstract mark exclusions. */
    private fun handOff(direction: Direction, observation: RunObservation): List<Pair<MethodKey, DemandPattern>> {
        val result = LinkedHashSet<Pair<MethodKey, DemandPattern>>()
        for (edge in observation.selectedDemand) {
            program.cancellation.checkpoint()
            fun forgetMust(p: Pattern): Pattern = if (p.fact.tail == Tail.ANY_TAINT)
                Pattern(p.fact.copy(tail = Tail.ANY), ExclusionSet.Empty) else p
            val entry = forgetMust(Pattern(edge.conclusion.fact.copy(path = edge.conclusion.fact.path.toList()), edge.conclusion.exclusion))
            if (direction == Direction.FORWARD) for (member in edge.premise) result += edge.method to DemandPattern(entry, forgetMust(member))
            else {
                check(edge.premise.size == 1)
                result += edge.method to DemandPattern(entry, edge.premise.single().takeUnless { it.fact.base == AccessPathBase.Zero })
            }
        }
        return result.toList()
    }

    private fun sinkSeeds(observation: RunObservation, wanted: Set<HistoricalFinding>): List<Seed> {
        val result = LinkedHashSet<Seed>()
        for (w in observation.witnesses) if (HistoricalFinding(w.rule, w.statement) in wanted) {
            program.cancellation.checkpoint()
            val forms = program.forms(w.methodKey)
            val sinks: List<SinkRule> = program.callExpression(w.methodKey, w.statement.location.index)?.let {
                forms.call(Direction.FORWARD, w.statement, it).sinks
            } ?: forms.exitRules(Direction.FORWARD, w.statement).rules.sinks
            for (s in sinks) if (s.rule == w.rule) for (p in s.patterns) if (p.fact.base != AccessPathBase.Zero)
                result += Seed.Sink(w.rule, w.methodKey, w.statement, p)
        }
        return result.toList()
    }

    /** Direct least joint support at one site, including AnyTaintExDefs.SupLinkX when opted in. */
    private fun confirm(observation: RunObservation, roots: List<MethodKey>, restricted: Boolean): RunObservation {
        data class Question(val method: MethodKey, val premise: Set<Pattern>)
        data class Site(val callee: MethodKey, val caller: MethodKey, val call: CommonInst)
        val sites = observation.links.filter { it.linkLayer == Layer.NORMAL && it.callerLayer == Layer.NORMAL }
            .groupBy { Site(it.callee, it.caller, it.call) }
        val questions = LinkedHashSet<Question>()
        for (link in observation.links) questions += Question(link.caller, link.premise)
        for (w in observation.witnesses) questions += Question(w.methodKey, union(w.edges.map { it.premise }))
        val supported = roots.mapTo(LinkedHashSet()) { Question(it, setOf(ZERO_PATTERN)) }
        fun suppliedAt(site: Site, rows: List<ObservedLink>, members: Set<Pattern>): Boolean = members.all { member ->
            rows.any { link ->
                val a = link.added
                val supplied = when {
                    member.fact.base == AccessPathBase.Zero -> a.fact.base == AccessPathBase.Zero
                    member.fact.mark !is MarkSlot.Concrete -> false
                    a.fact.tail == Tail.EXACT -> member.fact.tail == Tail.EXACT && member == a
                    allowMustSources && restricted && a.fact.tail == Tail.ANY_TAINT ->
                        member.fact.mark == a.fact.mark && (member.fact.tail == Tail.EXACT || member.fact.tail == Tail.ANY_TAINT) && inside(member, a)
                    else -> false
                }
                supplied && Question(site.caller, link.premise) in supported
            }
        }
        var changed: Boolean
        do {
            changed = false
            for (question in questions) {
                program.cancellation.checkpoint()
                if (question in supported) continue
                if (sites.any { (site, rows) -> site.callee == question.method && suppliedAt(site, rows, question.premise) }) {
                    supported += question; changed = true
                }
            }
        } while (changed)
        fun supports(method: MethodKey, premise: Set<Pattern>): Boolean =
            (method in roots && isZero(premise)) ||
                sites.any { (site, rows) -> site.callee == method && suppliedAt(site, rows, premise) }
        return observation.copy(witnesses = observation.witnesses.mapTo(LinkedHashSet()) { w ->
            w.copy(confirmed = w.edges.all { it.layer == Layer.NORMAL } && supports(w.methodKey, union(w.edges.map { it.premise })))
        })
    }

    private fun union(values: List<Set<Pattern>>): Set<Pattern> {
        val members = values.flatten().filterTo(LinkedHashSet()) { it.fact.base != AccessPathBase.Zero }
        return if (members.isEmpty()) setOf(ZERO_PATTERN) else members
    }
    private fun isZero(values: Set<Pattern>): Boolean = values.size == 1 && values.single().fact.base == AccessPathBase.Zero
}

package org.opentaint.dataflow.bidi.fixtures

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.interp.CallStage
import org.opentaint.dataflow.bidi.interp.CleanStep
import org.opentaint.dataflow.bidi.interp.StatementSummary
import org.opentaint.dataflow.bidi.interp.StageKind
import org.opentaint.dataflow.bidi.interp.Guard
import org.opentaint.dataflow.bidi.driver.Seed

/** F71 concrete-design operations. Explicit opt-ins add argued END forms and refined F69 must flags;
 *  their tests cite those rules separately from the default fb789d0ab finite-program domain. */
internal object HistoricalF71 {
    const val VERSION = "F71 concrete design / proof snapshot fb789d0ab"

    /** Frozen pre-selective-preservation Reference.kt normalizer (fa0bd5887e7b25ef912852a19d701c0a21302bcb).
     * Historical demotion changes the tail; the selected layer-only normalizer must not rewrite this oracle. */
    fun normalize(f: PathFact, exclusion: ExclusionSet, demand: Boolean): Conclusion = when {
        f.tail == Tail.ANY -> Conclusion(f, ExclusionSet.Empty, demand = true)
        f.tail == Tail.ANY_TAINT -> {
            check(f.mark is MarkSlot.Concrete)
            if (demand) Conclusion(f.copy(tail = Tail.ANY), ExclusionSet.Empty, demand = true)
            else Conclusion(f, exclusion, demand = false)
        }
        f.tail != Tail.STAR || (f.mark is MarkSlot.Star && !demand) -> Conclusion(f, exclusion, demand)
        else -> Conclusion(f.copy(tail = Tail.ANY), ExclusionSet.Empty, demand = true)
    }

    fun validate(program: FiniteProgramFixtures, inputs: ProgramRunInputs,
                 allowEndFacts: Boolean = false, allowMustSources: Boolean = false) {
        fun summary(s: StatementSummary) {
            check(s.sources.isEmpty()) { "$VERSION differential excludes compiled source predicates" }
            for (e in s.edges) if (e.isSource) check(e.forward.to.tail == Tail.EXACT ||
                (allowMustSources && e.forward.to.tail == Tail.ANY_TAINT && e.forward.to.mark is MarkSlot.Concrete)) {
                "$VERSION differential excludes must sources and F76 must-record views"
            }
            check(s.edges.none { it.forward.from.tail == Tail.ANY_TAINT ||
                (it.forward.to.tail == Tail.ANY_TAINT && !(allowMustSources && it.isSource)) })
            check(s.conjunctions.none { it.target.tail == Tail.ANY_TAINT })
        }
        fun sink(s: org.opentaint.dataflow.bidi.interp.SinkRule) {
            check(s.predicate == null) { "$VERSION differential excludes compiled sink predicates" }
            summary(StatementSummary(emptySet(), s.endFacts, emptyList(), emptyMap()))
        }
        check(inputs.seeds.none { it is Seed.PredicateSink }) {
            "$VERSION differential excludes compiled full-condition sink seeds"
        }
        program.statementInputs.forEach { summary(it.summary) }
        for (e in program.entryInputs) {
            summary(e.rules.summary)
            summary(e.rules.endFacts)
            e.rules.sinks.forEach(::sink)
            check(e.rules.endFacts.conjunctions.isEmpty())
            if (!allowEndFacts) check(e.rules.endFacts.edges.isEmpty() && e.rules.sinks.all { it.endFacts.isEmpty() })
        }
        for (e in program.exitInputs) {
            summary(e.rules.rules.summary)
            summary(e.rules.rules.endFacts)
            e.rules.rules.sinks.forEach(::sink)
            check(e.rules.rules.endFacts.conjunctions.isEmpty())
            if (!allowEndFacts) check(e.rules.rules.endFacts.edges.isEmpty() && e.rules.rules.sinks.all { it.endFacts.isEmpty() })
        }
        for (row in program.callInputs) {
            row.plan.sinks.forEach(::sink)
            if (!allowEndFacts) check(row.plan.sinks.all { it.endFacts.isEmpty() })
            for (stage in row.plan.stages) when (stage) {
                is CallStage.Edges -> {
                    val permittedEnd = allowEndFacts && stage.kind == StageKind.END_FACTS &&
                        (stage.guard == null || stage.guard is Guard.SinkTriggered)
                    check(stage.kind != StageKind.ALIASES && (permittedEnd ||
                        (stage.kind != StageKind.END_FACTS && stage.guard == null && stage.trigger == null))) {
                        "$VERSION differential excludes aliases, guarded stages, and end-fact triggers"
                    }
                    summary(stage.summary)
                }
                is CallStage.Actions -> check(stage.steps.all { it is CleanStep.Clean }) {
                    "Ordered field/alias actions are covered by current-mode tests, outside this F71 domain"
                }
                is CallStage.Predefined -> error("Predefined models are outside F71")
                is CallStage.Callees -> Unit
            }
        }
        for (record in inputs.records) {
            if (!allowMustSources) {
                check(record.premise.fact.tail != Tail.ANY_TAINT && record.conclusion.fact.tail != Tail.ANY_TAINT)
                check(record.premise.exclusion == ExclusionSet.Empty && record.conclusion.exclusion == ExclusionSet.Empty)
            } else {
                check(!record.conclusion.demand)
                check(record.premise.exclusion == ExclusionSet.Empty || record.premise.fact.tail == Tail.STAR ||
                    record.premise.fact.tail == Tail.ANY_TAINT)
                check(record.conclusion.exclusion == ExclusionSet.Empty || record.conclusion.fact.tail == Tail.STAR ||
                    record.conclusion.fact.tail == Tail.ANY_TAINT)
            }
        }
    }

    /** Restricted.lean emitM: match the demand mark, intersect locations, copy the ADDED mark. */
    fun emit(d: Pattern, a: Pattern): Pattern? {
        val admitsMark = when (val dm = d.fact.mark) {
            is MarkSlot.Concrete -> a.fact.mark == dm
            is MarkSlot.Star -> (a.fact.mark as? MarkSlot.Concrete)?.mark?.let { it !in dm.excluded } ?: true
        }
        if (d.fact.base != a.fact.base || !admitsMark) return null
        val p = d.fact.path
        val q = a.fact.path
        val result = when {
            q == p -> {
                val tail = when {
                    a.fact.tail.isAny -> d.fact.tail
                    d.fact.tail.isAny -> a.fact.tail
                    a.fact.tail == Tail.EXACT || d.fact.tail == Tail.EXACT -> Tail.EXACT
                    else -> Tail.STAR
                }
                Pattern(a.fact.copy(tail = tail), if (tail == Tail.STAR) a.exclusion.union(d.exclusion) else ExclusionSet.Empty)
            }
            q.startsWith(p) -> if (d.tailAdmits(q.drop(p.size))) a else null
            p.startsWith(q) -> if (a.tailAdmits(p.drop(q.size)))
                Pattern(d.fact.copy(mark = a.fact.mark), d.exclusion) else null
            else -> null
        }
        // AnyTaintExDefs.emitTX: the old model stores a separate must flag on an emitted any tail.
        // A same-path must keeps its own E; entering an admitted deeper chain forgets the old E.
        return if (a.fact.tail == Tail.ANY_TAINT && result?.fact?.tail == Tail.ANY)
            result.copy(fact = result.fact.copy(tail = Tail.ANY_TAINT),
                exclusion = if (p == q) a.exclusion else result.exclusion) else result
    }

    /** Earlier spatial-first cleaner, AnyTaintExDefs.lean cleanResX; F75 has not run yet. */
    fun clean(cl: Cleaner, c: Conclusion): CleanOut {
        val pos = cleanPos(cl, c.fact, c.exclusion)
        val selected = cl.mark
        if (pos == Pos.DISJOINT) return CleanOut(listOf(c), null)
        return when (val m = c.fact.mark) {
            is MarkSlot.Concrete -> when {
                selected != null && selected != m.mark -> CleanOut(listOf(c), null)
                pos == Pos.INSIDE -> CleanOut(emptyList(), null)
                else -> {
                    val q = cl.path?.toList().orEmpty()
                    val p = c.fact.path
                    if (c.fact.tail == Tail.ANY_TAINT && !c.demand && q.size == p.size + 1 &&
                        q.startsWith(p) && cl.reach != CleanReach.EXACT) {
                        val field = q.last()
                        val kept = c.copy(exclusion = c.exclusion.union(ExclusionSet.of(field)))
                        CleanOut(if (cl.reach == CleanReach.BELOW) listOf(kept,
                            Conclusion(c.fact.copy(path = q, tail = Tail.EXACT), ExclusionSet.Empty, false)) else listOf(kept), null)
                    } else CleanOut(concPart(cl, c), null)
                }
            }
            is MarkSlot.Star -> when {
                selected != null -> CleanOut(listOf(c.copy(fact = c.fact.copy(mark = MarkSlot.Star(m.excluded + selected)))),
                    if (pos == Pos.PART) selected else null)
                pos == Pos.INSIDE -> CleanOut(emptyList(), null)
                else -> CleanOut(listOf(normalize(c.fact, ExclusionSet.Empty, true)), null)
            }
        }
    }

    /** Restricted.lean satI (run 1 still uses applicable). No F72 canonical FLOW overlap shortcut. */
    fun satisfies(j: Pattern, a: Pattern, restricted: Boolean): Boolean =
        if (restricted) inside(j, a) else applicable(j, a)

    /** HandoffDefs.lean Cross/CrossB. Generic revEdge is the unchanged ordinary-record table. */
    private fun crossTail(p: Pattern): Boolean = p.fact.tail == Tail.EXACT ||
        (p.fact.tail == Tail.STAR && p.exclusion == ExclusionSet.Empty)

    fun cross(p: Pattern, c: Conclusion): Boolean {
        if (c.demand || c.fact.tail == Tail.ANY_TAINT || !crossTail(p) ||
            (c.fact.mark !is MarkSlot.Star && p.fact.mark !is MarkSlot.Concrete)) return false
        val reversed = reverseRecord(p, c) ?: return false
        return crossTail(reversed.premise)
    }

    fun crossBackward(p: Pattern, c: Conclusion): Boolean {
        if (c.demand) return false
        val r = reverseRecord(p, c) ?: return false
        return cross(r.premise, r.result)
    }

    fun reverseRecord(p: Pattern, c: Conclusion): RecordLeafView? {
        if (c.demand) return null
        // F69 amendment R3: old native must/E leaves have no F76 STAR read view.
        if (p.fact.tail == Tail.ANY_TAINT ||
            (c.fact.tail == Tail.ANY_TAINT && c.exclusion != ExclusionSet.Empty)) return null
        val reversed = revEdge(summaryEdge(p, c)) ?: return null
        return RecordLeafView(Pattern(reversed.from, ExclusionSet.Empty),
            Conclusion(reversed.to, reversed.exclusion, reversed.to.tail == Tail.ANY))
    }

    /** HandoffDefs.lean restrictI/restrictConcI, coded directly rather than invoking current restrict. */
    fun restrict(p: Pattern, c: Conclusion, d: DemandPattern): Conclusion? {
        val out = d.exit ?: return null
        if (!insideLoc(p, d.entry) || !markSub(d.entry.fact.mark, p.fact.mark)) return null
        val meetMarks = when (val a = out.fact.mark) {
            is MarkSlot.Concrete -> when (val b = c.fact.mark) {
                is MarkSlot.Concrete -> a.mark == b.mark
                is MarkSlot.Star -> a.mark !in b.excluded
            }
            is MarkSlot.Star -> (c.fact.mark as? MarkSlot.Concrete)?.mark?.let { it !in a.excluded } ?: true
        }
        if (!meetMarks || out.fact.base != c.fact.base) return null
        val q = c.fact.path
        val s = out.fact.path
        return when {
            q == s -> when {
                c.fact.tail.isAny && out.fact.tail == Tail.EXACT ->
                    c.copy(fact = c.fact.copy(tail = Tail.EXACT), exclusion = ExclusionSet.Empty)
                c.fact.tail == Tail.ANY_TAINT && out.fact.tail == Tail.STAR ->
                    c.copy(exclusion = c.exclusion.union(out.exclusion))
                else -> c
            }
            q.startsWith(s) -> if (out.tailAdmits(q.drop(s.size))) c else null
            s.startsWith(q) -> when (c.fact.tail) {
                Tail.ANY -> c.copy(fact = c.fact.copy(path = s, tail = if (out.fact.tail == Tail.EXACT) Tail.EXACT else Tail.ANY))
                Tail.STAR -> if (c.exclusion.admits(s.drop(q.size))) c else null
                Tail.EXACT -> null
                Tail.ANY_TAINT -> if (c.exclusion.admits(s.drop(q.size))) c.copy(
                    fact = c.fact.copy(path = s, tail = if (out.fact.tail == Tail.EXACT) Tail.EXACT else Tail.ANY_TAINT),
                    exclusion = if (out.fact.tail == Tail.STAR) out.exclusion else ExclusionSet.Empty) else null
            }
            else -> null
        }
    }
}

package org.opentaint.dataflow.bidi.fixtures

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.engine.*
import org.opentaint.dataflow.bidi.engine.historical.*
import org.opentaint.dataflow.bidi.engine.historical.minus
import org.opentaint.dataflow.bidi.engine.historical.Run1Abstraction
import org.opentaint.dataflow.bidi.engine.historical.Run1Slot
import org.opentaint.dataflow.bidi.engine.historical.RequestStorage
import org.opentaint.dataflow.bidi.engine.historical.RequestRows
import org.opentaint.dataflow.bidi.engine.historical.RunEvent
import org.opentaint.dataflow.bidi.engine.historical.SummaryStorage
import org.opentaint.dataflow.bidi.engine.historical.SubscriptionManager
import org.opentaint.dataflow.bidi.engine.historical.SubscriptionPort
import org.opentaint.dataflow.bidi.store.RequestMarkSelection
import org.opentaint.dataflow.bidi.store.RequestMarkSet

/** Historical a80 request protocol laws. This fixture is not the selected grouped/direct engine. */
internal class HistoricalRun1RequestPipelineFixtures(val steps: ProtocolSteps = ProtocolSteps.Inline) : AutoCloseable {
    val f = HistoricalPipelineFixtures(limit = 1, protocol = steps)
    val statistics = Run1AbstractionStatistics()
    val batchStatistics = RequestBatchStatistics()
    val events = ArrayDeque<RunEvent>()
    val sent = ArrayList<RunEvent>()
    val initialObservations = ArrayList<Pair<MethodKey, InitialAp>>()
    val initials = linkedSetOf<Pair<MethodKey, InitialAp>>()
    val climbs = linkedSetOf<Triple<MethodKey, Run1Slot, Int>>()
    val bases = LinkedHashMap<MethodKey, RequestRows>()
    val profiles = LinkedHashMap<MethodKey, Run1StaticProfile>()
    val frozenBases = LinkedHashMap<MethodKey, FrozenRequestBase>()
    private val stores = LinkedHashMap<MethodKey, SummaryStorage>()
    private val temporary = LinkedHashMap<MethodKey, RequestStorage>()
    private val emitters = LinkedHashMap<MethodKey, Run1Abstraction>()
    var acceptSends = true
    var acceptNotifications = true
    var cancelOnSend = false
    var onAnswer: (() -> Unit)? = null

    /** This fixture has identity forms. Declare its finite input field domain before emission. */
    fun declareIdentityStaticDomain(vararg fields: Run1Slot.StaticField) {
        check(emitters.isEmpty())
        val profile = Run1StaticProfiles.build(f.ap, mapOf(f.callee.method to emptyList()),
            mapOf(f.callee.method to Run1StaticLocalProfile.EMPTY),
            declaredFieldUniverse = fields.toSet(), declaredClassUniverse = fields.map { it.cls }.toSet())[f.callee.method]
        profiles[f.callee] = profile
        profiles[f.caller] = profile
    }

    fun storage(method: MethodKey = f.callee): SummaryStorage = stores.getOrPut(method) {
        SummaryStorage(method, f.ap, f.ops, steps, frozenBases[method] ?: MapFrozenRequestBase(bases[method].orEmpty()))
    }

    private val port = object : SubscriptionPort by f.port {
        override val abstractionStatistics get() = this@HistoricalRun1RequestPipelineFixtures.statistics
        override val requestBatchStatistics get() = batchStatistics
        override fun summaryStorage(key: MethodKey): SummaryStorage = storage(key)
        override fun post(event: RunEvent.ChangedRequests): Boolean {
            if (!acceptNotifications) return false
            events += event
            return true
        }
        override fun send(event: RunEvent): Boolean {
            if (cancelOnSend) f.ap.cancellation.cancel()
            if (!acceptSends) return false
            sent += event
            events += event
            return true
        }
    }
    val subscriptions = SubscriptionManager(port)

    private fun observe(method: MethodKey, initial: InitialAp) {
        initialObservations += method to initial
        initials += method to initial
    }

    private fun emitter(method: MethodKey): Run1Abstraction = emitters.getOrPut(method) {
        Run1Abstraction(f.ops, profiles[method], { observe(method, it) },
            storage(method)::borrowMatchingRequests, { slot, marks -> collect(method, slot, marks) })
    }

    fun collect(method: MethodKey, slot: Run1Slot, marks: RequestMarkSelection) {
        val fresh = marks.minus(storage(method).borrowRequest(slot), f.ap.cancellation::checkpoint)
        if (!fresh.isEmpty) temporary.getOrPut(method, ::RequestStorage).addAll(slot, fresh)
    }

    /** The test explicitly chooses the method-empty barrier, not an alternate scheduler. */
    fun commit(method: MethodKey = f.callee) {
        val pending = temporary[method] ?: return
        storage(method).commit(pending)
        temporary[method] = RequestStorage()
    }

    fun publish(slot: Run1Slot, vararg ids: Int, method: MethodKey = f.callee) {
        collect(method, slot, RequestMarkSet.fromIds(ids))
        commit(method)
    }

    /** Real caller registration/admission precedes its queued callee LinkIn. */
    fun submit(part: Subscription) {
        subscriptions.subscribe(part)
        events += RunEvent.LinkIn(part.callee, part.ref, part.linkLayer, part.added)
    }

    fun drain() {
        var count = 0
        while (events.isNotEmpty()) {
            check(++count < 100_000) { "Finite request pipeline did not close" }
            when (val event = events.removeFirst()) {
                is RunEvent.ChangedRequests -> subscriptions.onRequests(event.callee, event.rows)
                is RunEvent.LinkIn -> emitter(event.callee).emit(event.ref, event.added)
                is RunEvent.InitialAnswersIn -> {
                    event.answers.forEach { observe(event.method, it) }
                    onAnswer?.invoke()
                }
                is RunEvent.MarkRequestsIn -> for ((slot, marks) in event.rows) {
                    marks.forEachId { climbs += Triple(event.method, slot, it) }
                    collect(event.method, slot, marks)
                }
                is RunEvent.Delivery -> subscriptions.onDelivery(event.callee, event.publications)
                else -> error("Unexpected request pipeline event: $event")
            }
        }
    }

    override fun close() {
        emitters.values.forEach(Run1Abstraction::release)
        subscriptions.freeze()
        f.close()
    }
}

package org.opentaint.dataflow.bidi.fixtures

import org.opentaint.dataflow.bidi.ap.ApMode
import org.opentaint.dataflow.bidi.ap.Direction
import org.opentaint.dataflow.bidi.ap.InitialAp
import org.opentaint.dataflow.bidi.ap.Layer
import org.opentaint.dataflow.bidi.ap.MethodKey
import org.opentaint.dataflow.bidi.ap.PremiseKey
import org.opentaint.dataflow.bidi.ap.members
import org.opentaint.dataflow.bidi.engine.RunMethodAnalyzer
import org.opentaint.dataflow.bidi.engine.RunResult
import org.opentaint.dataflow.bidi.engine.RunStatus
import org.opentaint.dataflow.bidi.engine.SharedObjects
import org.opentaint.dataflow.bidi.store.Link
import org.opentaint.dataflow.bidi.store.confirmableMember
import org.opentaint.dataflow.bidi.store.supplies
import org.opentaint.ir.api.common.cfg.CommonInst

/** Historical raw-history support oracle. The current driver deliberately does not confirm candidates this way. */
class HistoricalSupport(input: HistoricalSupportInput, roots: List<MethodKey>,
              private val mode: ApMode, private val shared: SharedObjects) {
    private val result = input.result
    private val witnesses = input.witnesses
    private data class Site(val callee: MethodKey, val caller: MethodKey, val call: CommonInst)
    private val roots = roots.toHashSet()
    private val ap = shared.ap
    private val atSite = HashMap<Site, MutableList<Link>>()
    private val sitesOf = HashMap<MethodKey, MutableSet<Site>>()
    private val fedBy = HashMap<Pair<MethodKey, PremiseKey>, MutableSet<Site>>()
    private val questions = HashMap<MethodKey, MutableSet<PremiseKey>>()
    private val supported = HashSet<Pair<MethodKey, PremiseKey>>()

    init {
        check(result.status == RunStatus.COMPLETE && result.direction == Direction.FORWARD &&
            mode.direction == Direction.FORWARD) { "Support needs a complete forward run" }
        shared.cancellation.checkpoint()
        for (callee in result.analyzers) {
            shared.cancellation.checkpoint()
            for (link in input.links[callee.key].orEmpty()) {
                shared.cancellation.checkpoint()
                val ref = link.caller
                if (link.linkLayer != Layer.NORMAL || ref.callerLayer != Layer.NORMAL) continue
                val site = Site(callee.key, ref.caller, ref.call)
                atSite.getOrPut(site, ::ArrayList) += link
                sitesOf.getOrPut(callee.key, ::HashSet) += site
                fedBy.getOrPut(ref.caller to ref.premise, ::HashSet) += site
                questions.getOrPut(ref.caller, ::HashSet) += ref.premise
            }
        }
        val work = ArrayDeque<Pair<MethodKey, PremiseKey>>()
        for (root in this.roots) {
            shared.cancellation.checkpoint()
            if (supported.add(root to ap.zero)) work += root to ap.zero
        }
        while (work.isNotEmpty()) {
            shared.cancellation.checkpoint()
            val known = work.removeFirst()
            for (site in fedBy[known].orEmpty()) {
                shared.cancellation.checkpoint()
                for (premise in questions[site.callee].orEmpty()) {
                    shared.cancellation.checkpoint()
                    if ((site.callee to premise) !in supported && suppliedAt(site, premise.members)) {
                        supported += site.callee to premise
                        work += site.callee to premise
                    }
                }
            }
        }
    }

    private fun suppliedAt(site: Site, members: Collection<InitialAp>): Boolean = members.all { member ->
        shared.cancellation.checkpoint()
        confirmableMember(member, mode) && atSite[site].orEmpty().any { link ->
            shared.cancellation.checkpoint()
            supplies(member, link, mode) && (site.caller to link.caller.premise) in supported
        }
    }

    fun isSupported(method: MethodKey, members: Collection<InitialAp>): Boolean {
        require(members.isNotEmpty()) { "A support premise set must be nonempty" }
        shared.cancellation.checkpoint()
        if (method in roots && members.all { shared.cancellation.checkpoint(); it.isZero }) return true
        return sitesOf[method].orEmpty().any { site ->
            shared.cancellation.checkpoint()
            suppliedAt(site, members)
        }
    }

    fun confirm() {
        shared.cancellation.checkpoint()
        for ((_, witness) in witnesses?.witnessesOf(result.runIndex).orEmpty()) {
            shared.cancellation.checkpoint()
            witness.confirmed = witness.edges.all {
                shared.cancellation.checkpoint()
                it.layer == Layer.NORMAL
            } && isSupported(witness.methodKey, witness.supportPremise(ap).members)
        }
    }
}

