/** Finite, non-call method services. Unsupported protocol operations fail explicitly. */
class MethodAnalysisFixtures(
    successors: List<List<Int>> = listOf(listOf(1), listOf(2), emptyList()),
    val normalExit: Int = 2,
    val exceptionalExit: Int? = null,
    staticProfiles: ((MethodAnalysisFixtures) -> Run1StaticProfiles)? = null,
    abstractionStatistics: Run1AbstractionStatistics? =
        if (java.lang.Boolean.getBoolean("org.opentaint.bidi.optimizationStatistics")) Run1AbstractionStatistics() else null,
    requestBatchStatistics: RequestBatchStatistics? =
        if (java.lang.Boolean.getBoolean("org.opentaint.bidi.optimizationStatistics")) RequestBatchStatistics() else null,
    n2Statistics: N2Statistics? =
        if (java.lang.Boolean.getBoolean("org.opentaint.bidi.optimizationStatistics")) N2Statistics() else null,
) : AutoCloseable {
    val cancellation = Cancellation()
    val refManager = RefManager()
    val store = StoreFixtures(cancellation, successors.lastIndex, refManager)
    val manager = store.manager
    val ops = store.ops
    val key = store.method
    val callPlans = mutableMapOf<Int, CallPlan>()
    val callExpressions = mutableMapOf<Int, CommonCallExpr>()
    val callExpression = object : CommonCallExpr {
        override val typeName = "Box"
        override val args: List<CommonValue> = emptyList()
    }
    val language = object : LanguageManager by store.lm {
        override fun getCallExpr(inst: CommonInst): CommonCallExpr? = callExpressions[inst.location.index]
    }
    val records = PersistentRecordStore(manager)
    val vulnerabilities = ConcurrentVulnerabilityStore(manager)
    private val adjacency = successors.map { it.toList() }
    val statements = mutableMapOf<Int, StatementSummary>()
    var entryRules: RuleStatement = RuleStatement.EMPTY
    val exitRules = mutableMapOf<Int, ExitRules>()
    private val reversedStatements = IdentityHashMap<StatementSummary, StatementSummary>()
    private val reversedEntries = IdentityHashMap<RuleStatement, RuleStatement>()
    private val reversedExits = IdentityHashMap<ExitRules, ExitRules>()
    private val reversedCalls = IdentityHashMap<CallPlan, CallPlan>()
    var baseRelevance: ((Direction, CommonInst, AccessPathBase, RuleView) -> Boolean)? = null
    /** Explicit raw instruction metadata; never inferred from configured rules. */
    var instructionLocalAccess: List<org.opentaint.dataflow.graph.LocalAccess>? = null
    val unresolvedCalls = ArrayList<Triple<CommonCallExpr, AccessPathBase, CallPlan>>()

    init {
        require(normalExit in adjacency.indices)
        require(exceptionalExit == null || exceptionalExit in adjacency.indices)
        require(adjacency.all { next -> next.all { it in adjacency.indices } })
    }

    fun inst(index: Int): CommonInst = store.inst(index)
    fun statement(index: Int, summary: StatementSummary) { statements[index] = summary }
    fun entryRules(value: RuleStatement) { entryRules = value }
    fun exitRules(index: Int, value: ExitRules) { exitRules[index] = value }
    fun call(index: Int, plan: CallPlan, expression: CommonCallExpr = callExpression) {
        callPlans[index] = plan
        callExpressions[index] = expression
    }

    private val forms = object : MethodForms {
        override fun isBaseRelevant(direction: Direction, s: CommonInst, base: AccessPathBase, view: RuleView): Boolean =
            baseRelevance?.invoke(direction, s, base, view) ?: true
        override fun statement(direction: Direction, s: CommonInst): StatementSummary {
            val value = statements[s.location.index] ?: StatementSummary.EMPTY
            return if (direction == Direction.FORWARD) value
            else reversedStatements.getOrPut(value) { value.reversed() }
        }
        override fun entryRules(direction: Direction): RuleStatement =
            if (direction == Direction.FORWARD) entryRules
            else reversedEntries.getOrPut(entryRules) { entryRules.reversed() }
        override fun exitRules(direction: Direction, exit: CommonInst): ExitRules {
            val value = exitRules[exit.location.index] ?: ExitRules.EMPTY
            return if (direction == Direction.FORWARD) value
            else reversedExits.getOrPut(value) { ExitRules(value.reversed(), false, emptySet()) }
        }
        override fun call(direction: Direction, s: CommonInst, call: CommonCallExpr): CallPlan {
            val plan = checkNotNull(callPlans[s.location.index]) { "The finite call has no plan" }
            return if (direction == Direction.FORWARD) plan else reversedCalls.getOrPut(plan) { plan.reversed() }
        }
    }

    private fun graph(direction: Direction): MethodInstGraph {
        val next = if (direction == Direction.FORWARD) adjacency else
            List(adjacency.size) { target -> adjacency.indices.filter { target in adjacency[it] } }
        return MethodInstGraph(Array(adjacency.size, ::inst),
            CompactGraph.build(adjacency.size) { index -> BitSet().apply { next[index].forEach(::set) } },
            BitSet().apply {
                if (direction == Direction.FORWARD) {
                    set(normalExit)
                    exceptionalExit?.let(::set)
                } else set(0)
            })
    }

    val interpreter: Interpreter = object : Interpreter, UnresolvedCallObserver {
        override fun reached(call: CommonCallExpr, position: AccessPathBase, plan: CallPlan) {
            unresolvedCalls += Triple(call, position, plan)
        }
        override fun entryNode(method: MethodKey): CommonInst = inst(0)
        override fun exitNodes(method: MethodKey): List<ExitNode> = buildList {
            add(ExitNode(inst(normalExit), false))
            exceptionalExit?.let { add(ExitNode(inst(it), true)) }
        }
        override fun entryRules(method: MethodKey): RuleStatement = forms.entryRules(Direction.FORWARD)
        override fun exitRules(method: MethodKey, exit: CommonInst): ExitRules = forms.exitRules(Direction.FORWARD, exit)
        override fun statementSummary(method: MethodKey, statement: CommonInst): StatementSummary =
            forms.statement(Direction.FORWARD, statement)
        override fun callPlan(caller: MethodKey, statement: CommonInst, call: CommonCallExpr): CallPlan =
            forms.call(Direction.FORWARD, statement, call)
        override fun isSummaryBase(base: AccessPathBase): Boolean =
            base !is AccessPathBase.LocalVar && base !is AccessPathBase.CleanerTemporary
    }
    val contexts: MethodContextCache = MethodContextCache(interpreter, object : MethodContextSource {
        override fun forms(key: MethodKey): MethodForms = forms
        override fun graph(key: MethodKey, direction: Direction): MethodInstGraph = graph(direction)
        override fun blockLiveLocals(key: MethodKey): org.opentaint.dataflow.graph.BlockLiveLocals? =
            instructionLocalAccess?.let { metadata ->
                org.opentaint.dataflow.graph.BlockLiveLocals.build(contexts.blockLayout(key),
                    graph(Direction.FORWARD).graph, graph(Direction.BACKWARD).graph, metadata, cancellation)
            }
    })
    private var profileBound = false
    private val staticDomain = LinkedHashSet<HistoricalRun1Slot.StaticField>()
    private val staticClasses = LinkedHashSet<Int>()

    /** Declare the canonical supplier domain before creating an actor. This does not make it owned. */
    fun declareStaticDomain(vararg paths: List<Int>) {
        check(!profileBound) { "The finite static plan is already frozen" }
        for (path in paths) {
            require(path.size in 1..2 && path[0].isClass())
            staticClasses += path[0]
            if (path.size == 2) staticDomain += HistoricalRun1Slot.StaticField(path[0], path[1])
        }
    }

    private val sharedOwner = lazy {
        profileBound = true
        SharedObjects(manager, ops, interpreter, language, contexts, records,
            UnitResolver { UnknownUnit }, refManager, cancellation, threads = 1,
            abstractionStatistics = abstractionStatistics, requestBatchStatistics = requestBatchStatistics,
            n2Statistics = n2Statistics)
    }
    val shared: SharedObjects get() = sharedOwner.value

    /** Only configured forward forms enter this finite prescan. No runtime input is read here. */
    /** Explicit historical prescan oracle, never installed in SharedObjects. */
    fun historicalStaticProfiles(): Run1StaticProfiles {
        val local = FiniteStaticProfileLocal()
        statements.values.forEach(local::summary)
        local.rules(entryRules)
        exitRules.values.forEach { local.rules(it.rules) }
        val targets = LinkedHashSet<org.opentaint.ir.api.common.CommonMethod>()
        callPlans.values.forEach { plan -> local.plan(plan) { targets += it.method } }
        check(targets.all { it == key.method }) { "Foreign finite callees need an explicit complete static profile" }
        return Run1StaticProfiles.build(manager, mapOf(key.method to targets), mapOf(key.method to local.profile()),
            declaredFieldUniverse = staticDomain, declaredClassUniverse = staticClasses)
    }

    val processed = ArrayList<EdgeDelta>()
    val cuts = ArrayList<Pair<Cut, Facts>>()
    val requests = ArrayList<Pair<InitialAp, RequestKind>>()
    val addedLinks = ArrayList<Triple<CallerRef, Layer, Facts>>()
    private val inputRows = IdentityHashMap<BlockRunState, MutableList<Link>>()
    private val staticServices = IdentityHashMap<RunConfig, Run1StaticService>()
    private val questionManagers = IdentityHashMap<BlockRunState, SubscriptionManager>()
    private val questionQueue = ArrayDeque<() -> Unit>()
    private val summaryStores = LinkedHashMap<MethodKey, SummaryStorage>()
    var onRequestNotification: ((RunEvent.ChangedRequests) -> Unit)? = null

    fun requestRow(core: BlockRunState, slot: Run1Slot): RequestRowView =
        summaryStores.getValue(core.key).borrowRequest(slot)

    /** Test-owned arrival observations; actors retain none of this input history. */
    fun links(core: BlockRunState): List<Link> = inputRows[core].orEmpty().distinct()

    /** Admit the original caller subscription before delivering its callee input, as real call routing does. */
    fun admit(core: BlockRunState, ref: CallerRef, layer: Layer, facts: Facts) {
        cancellation.checkpoint()
        addedLinks += Triple(ref, layer, facts)
        inputRows.getOrPut(core, ::ArrayList).addAll(ops.leaves(facts).map { Link(it, layer, ref) })
        if (facts !is Reach) questionManagers.getValue(core).subscribe(
            Subscription(core.key, ref, layer, facts, zeroOnly = false))
        (core.localServices as? ScalarPositionLocalServices)?.onInput(ref, facts)
        if (core.config.run1) core.addLink(ref, layer, facts)
        else submitRestricted(core, facts)
    }

    /** Caller-side complete admission followed by the existing callee start gate. */
    fun submitRestricted(core: BlockRunState, facts: Facts) {
        for (initial in emitRestrictedInitials(core.config, ops, core.key, facts)) core.addInitial(initial)
    }

    /** Queued question delivery never calls an actor during a captured N2 visit. */
    fun pumpQuestions(): Boolean {
        var count = 0
        while (questionQueue.isNotEmpty()) {
            check(++count <= 100_000) { "Finite question routing did not close" }
            questionQueue.removeFirst().invoke()
        }
        return count != 0
    }

    fun flushRequests(core: BlockRunState, quantum: Int = 3) {
        // F78 submits only after actual method fact/publication work empties.
        drain(core, quantum)
    }

    val published = ArrayList<List<Publication>>()
    val publications: List<List<Publication>> get() = published
    val enqueued = ArrayList<RunMethodAnalyzer>()
    val events = ArrayList<RunEvent>()
    internal val positionDeliveries = ArrayList<ReferenceRequestDelivery>()
    val subscriptions = ArrayList<Subscription>()
    val sentLinks = ArrayList<RunEvent.LinkIn>()
    val sentInitials = ArrayList<RunEvent.InitialsIn>()
    var onInitials: ((RunEvent.InitialsIn) -> Unit)? = null
    var onSubscribe: ((Subscription) -> Unit)? = null
    var onLink: ((RunEvent.LinkIn) -> Unit)? = null
    var onPublish: ((MethodKey, List<Publication>) -> Unit)? = null
    var onPublishInput: ((MethodKey, List<Publication>) -> Unit)? = null
    var onProcess: ((MethodKey, EdgeDelta) -> Unit)? = null
    var onCut: ((Cut, Facts) -> Unit)? = null
    var sinkCheck: ((PremiseKey, CommonInst, Facts, List<SinkRule>) -> Triggers)? = null
    val triggerSeedCalls = ArrayList<Pair<CommonInst, SinkRule>>()
    val sinkSeedCalls = ArrayList<CommonInst>()
    val sinkEvaluations = ArrayList<Pair<SinkRule, Layer>>()

    /** The existing reference fixture selects GROUP; production-default controls use RunConfig directly. */
    fun config(index: Int = 1, L: Int = maxOf(1, index - 1),
               demand: DemandStore? = if (index == 1) null else DemandStore.Builder(manager).build(),
               seeds: SeedIndex = SeedIndex.EMPTY): RunConfig =
        RunConfig(index, L, demand, records, seeds, listOf(key), run1MarkMode = MarkMode.GROUP)

    fun core(index: Int = 1, L: Int = maxOf(1, index - 1),
             demand: DemandStore? = if (index == 1) null else DemandStore.Builder(manager).build(),
             seeds: SeedIndex = SeedIndex.EMPTY,
             localFactory: MethodLocalServicesFactory? = null,
             callFactory: MethodCallServicesFactory? = null,
             key: MethodKey = this.key, observe: Boolean = true): RunMethodAnalyzer =
        core(config(index, L, demand, seeds), localFactory, callFactory, key, observe)

    fun core(config: RunConfig, localFactory: MethodLocalServicesFactory? = null,
             callFactory: MethodCallServicesFactory? = null,
             key: MethodKey = this.key, observe: Boolean = true): RunMethodAnalyzer {
        lateinit var actor: RunMethodAnalyzer
        val port = object : RunnerPort<RunMethodAnalyzer> {
            override val config = config
            override val shared = this@MethodAnalysisFixtures.shared
            override val forms = contexts.directed(config.direction, if (config.mode.markMode == MarkMode.GROUP) RuleView.RUN1_GROUP else RuleView.FULL)
            override val ops = this@MethodAnalysisFixtures.ops
            override val steps = ProtocolSteps.Inline
            override val staticService = if (config.run1)
                staticServices.getOrPut(config) { Run1StaticService(manager, config.mode.markMode) } else null
            override fun send(event: RunEvent): Boolean {
                events += event
                // This fixture owns one actor. Foreign-owner effects remain
                // outbound observations; full-program fixtures route those.
                if (event is RunEvent.StaticOwner && event.effect.owner == actor.key) questionQueue += {
                    actor.onStaticEffect(event.effect)
                }
                return true
            }
            override fun post(event: RunEvent.Delivery): Boolean {
                events += event
                return true
            }
            override fun post(event: RunEvent.ChangedRequests): Boolean {
                questionQueue += { questionManagers.getValue(actor).onRequests(event.callee, event.rows) }
                onRequestNotification?.invoke(event)
                return true
            }
            override fun summaryStorage(key: MethodKey): SummaryStorage =
                summaryStores.getOrPut(key) { SummaryStorage(key, manager, ops, steps) }
            override fun subscribe(sub: Subscription) {
                val receive = checkNotNull(onSubscribe) { "Subscriptions require an explicit protocol fixture" }
                subscriptions += sub
                receive(sub)
            }
            override fun link(callee: MethodKey, ref: CallerRef, linkLayer: Layer, added: Facts) {
                val receive = checkNotNull(onLink) { "Links require an explicit protocol fixture" }
                val event = RunEvent.LinkIn(callee, ref, linkLayer, added)
                sentLinks += event
                receive(event)
            }
            override fun startInitials(callee: MethodKey, initials: Collection<AdmittedInitial>) {
                val event = RunEvent.InitialsIn(callee, initials)
                sentInitials += event
                onInitials?.invoke(event) ?: run {
                    if (callee == actor.key) for (initial in event.initials) actor.addInitial(initial)
                    else error("Initial delivery requires an explicit protocol fixture")
                }
            }
            override fun enqueue(analyzer: RunMethodAnalyzer): Boolean { enqueued += analyzer; return true }
            override fun analyzer(key: MethodKey): RunMethodAnalyzer {
                check(key == actor.key) { "The finite port owns one method actor" }
                return actor
            }
            override val onProcess: ((MethodKey, EdgeDelta) -> Unit)? = if (!observe) null else { key, edge ->
                processed += edge
                this@MethodAnalysisFixtures.onProcess?.invoke(key, edge)
            }
            override val onCut: ((Cut, Facts) -> Unit)? = if (!observe) null else { point, facts ->
                cuts += point to facts
                this@MethodAnalysisFixtures.onCut?.invoke(point, facts)
            }
        }
        val publisher = PublicationSink { method, batch ->
            onPublishInput?.invoke(method, batch)
            val owned: List<Publication> = Collections.unmodifiableList(ArrayList(batch))
            published += owned
            onPublish?.invoke(method, owned)
        }
        actor = RunMethodAnalyzer(key, port, publisher,
            localFactory ?: MethodLocalServicesFactory(::LocalServices),
            callFactory ?: MethodCallServicesFactory { NoCalls },
            TargetPublicationSink { _, _ -> }) // Standalone actor; tests inspect its owned terminal rows.
        lateinit var questions: SubscriptionManager
        questions = SubscriptionManager(object : SubscriptionPort {
            override val config = config
            override val ops = this@MethodAnalysisFixtures.ops
            override val steps = ProtocolSteps.Inline
            override val staticService get() = port.staticService
            override fun summaryStorage(key: MethodKey): SummaryStorage = port.summaryStorage(key)
            override fun applier(key: MethodKey): SummaryApplier = actor
            override fun post(event: RunEvent.Delivery): Boolean = port.post(event)
            override fun post(event: RunEvent.ChangedRequests): Boolean = port.post(event)
            override fun send(event: RunEvent): Boolean {
                events += event
                if (event is RunEvent.InitialAnswersIn && event.method == actor.key)
                    questionQueue += { event.answers.forEach(actor::addInitial) }
                return true
            }
        })
        questionManagers[actor] = questions
        return actor
    }

    private inner class LocalServices(private val core: BlockRunState) : MethodLocalServices {
        private val key get() = core.key
        override val conjunctions: ConjunctionStore? get() =
            error("Standing conjunction storage requires an explicit test service")
        private val triggered = HashSet<Pair<CommonInst, SinkRule>>()
        override fun addMarkRequest(premise: InitialAp, mark: TaintMark) { requests += premise to RequestKind.Mark(mark) }
        override fun conjunction(edge: ConjunctiveEdge, premise: PremiseKey, facts: Facts, node: CommonInst,
                                 sink: (PremiseKey, Facts) -> Unit): Unit =
            error("Standing conjunctions require an explicit test service")
        override fun checkSinks(premise: PremiseKey, node: CommonInst, facts: Facts, sinks: List<SinkRule>): Triggers {
            sinkCheck?.let { check ->
                return check(premise, node, facts, sinks).also { sinkEvaluations += it.fired }
            }
            if (!core.forward) return Triggers.NONE
            val fired = ArrayList<Pair<SinkRule, Layer>>()
            val parts = ArrayList<Facts>()
            for (sink in sinks) {
                cancellation.checkpoint()
                check(!sink.conjunctive) { "Conjunctive sinks require an explicit test service" }
                for (literal in sink.patterns) {
                    cancellation.checkpoint()
                    when (val result = ops.checkMark(facts, literal, core.mode)) {
                        MarkCheck.None -> Unit
                        is MarkCheck.Request -> core.collect(premise, facts) { _, _ -> }.markRequest(result.mark)
                        is MarkCheck.Holds -> {
                            parts += result.facts
                            fired += sink to result.facts.layer
                            vulnerabilities.add(VulnerabilityKey(sink.rule, key.method, node),
                                SinkWitness(sink.alternative, key,
                                    listOf(SinkEdge(premise, result.facts.layer, result.facts)), config.index,
                                    sink.endFacts.map { it.edge.to }))
                        }
                    }
                }
            }
            return Triggers(fired.distinct(), parts).also { sinkEvaluations += it.fired }
        }
        private val config get() = core.config
        override fun fireSinkSeeds(node: CommonInst, emit: (Facts) -> Unit) {
            sinkSeedCalls += node
            for (seed in config.seeds.at(key, node)) {
                cancellation.checkpoint()
                if (seed is Seed.Sink) seedFact(seed.requirement, emit)
            }
        }
        override fun fireTriggerSeeds(node: CommonInst, sink: SinkRule, emit: (Facts) -> Unit) {
            if (!triggered.add(node to sink)) return
            triggerSeedCalls += node to sink
            for (literal in sink.seedPatterns()) {
                cancellation.checkpoint()
                seedFact(literal, emit)
            }
        }
        private fun seedFact(pattern: Pattern, emit: (Facts) -> Unit) =
            core.cut(Cut.SEED, manager.zero, ops.targetTree(pattern.fact, Layer.NORMAL)) { _, facts -> emit(facts) }
        override fun freeze() { triggered.clear() }
    }

    private object NoCalls : MethodCallServices {
        override fun process(item: EdgeDelta): Unit = error("Calls require an explicit test service")
        override fun applySummary(part: Subscription, pub: Publication, member: Int): Unit =
            error("Summary application requires an explicit test service")
        override fun applyRecord(part: Subscription, record: Record): Unit =
            error("Record application requires an explicit test service")
        override fun applyRecordView(part: Subscription, view: RecordLeafView, nonSubsumable: Boolean): Unit =
            error("Record views require an explicit test service")
        override fun freeze() = Unit
    }

    /** Each completed item remains in the actor until its real work method processes it. */
    fun drain(core: BlockRunState, quantum: Int = 1000): Int {
        var attempts = 0
        while (true) {
            cancellation.checkpoint()
            check(++attempts <= 10000) { "The finite method fixture did not reach closure" }
            val complete = core.work(quantum)
            val delivered = pumpQuestions()
            // An answer delivered after work() returned can schedule a new initial/fact delta.
            if (complete && !delivered && !core.localServices.hasPendingRequests && questionQueue.isEmpty()) return attempts
        }
    }
    fun field(name: String): Int = store.field(name)
    fun mark(name: String): TaintMark = store.mark(name)
    fun pattern(base: AccessPathBase = AccessPathBase.Argument(0), path: List<Int> = emptyList(),
                tail: Tail = Tail.EXACT, mark: MarkSlot = MarkSlot.Concrete(mark("T")),
                exclusion: ExclusionSet = ExclusionSet.Empty): Pattern = store.pattern(base, path, tail, mark, exclusion)
    fun fact(base: AccessPathBase = AccessPathBase.Argument(0), path: List<Int> = emptyList(),
             tail: Tail = Tail.EXACT, mark: MarkSlot = MarkSlot.Concrete(mark("T")),
             exclusion: ExclusionSet = ExclusionSet.Empty, layer: Layer = Layer.NORMAL): Facts =
        store.fact(base, path, tail, mark, exclusion, layer)

    /** Explicit run-1 actor inputs. Full rule forms keep using pattern()/fact(). */
    fun groupMark(full: TaintMark = mark("T")): MarkSlot.Concrete =
        MarkSlot.Concrete(manager.marks.group(manager.marks.groupOf(full)))
    fun run1Pattern(base: AccessPathBase = AccessPathBase.Argument(0), path: List<Int> = emptyList(),
                    tail: Tail = Tail.EXACT, full: TaintMark = mark("T")): Pattern =
        pattern(base, path, tail, groupMark(full))
    fun run1Fact(base: AccessPathBase = AccessPathBase.Argument(0), path: List<Int> = emptyList(),
                 tail: Tail = Tail.EXACT, full: TaintMark = mark("T")): Facts =
        fact(base, path, tail, groupMark(full), layer = Layer.DEMAND)
    override fun close() {
        questionManagers.values.forEach { it.freeze() }
        questionManagers.clear()
        staticServices.values.forEach { it.clear() }
        staticServices.clear()
        questionQueue.clear()
        summaryStores.clear()
        inputRows.clear()
        if (sharedOwner.isInitialized()) sharedOwner.value.close()
    }
}

package org.opentaint.dataflow.bidi.fixtures

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.ap.ReferenceRequestKind as RequestKind
import org.opentaint.dataflow.bidi.driver.Seed
import org.opentaint.dataflow.bidi.engine.RunConfig
import org.opentaint.dataflow.bidi.interp.*
import org.opentaint.ir.api.common.cfg.CommonInst
import java.util.ArrayDeque

/** Exact per-path closure. No production fact store, candidate index or subsumption is used. */
class NaiveClosure(
    private val program: FiniteProgramFixtures,
    private val config: RunConfig,
    private val initialAdmission: InitialAdmission = InitialAdmission.HISTORICAL,
    private val semantics: Semantics = Semantics.HISTORICAL,
    private val rawInputs: ProgramRunInputs? = null,
) {
    enum class Semantics {
        HISTORICAL,
        /** Previous selected AP transfer with implicit ZERO and the old backward-ZERO C5 exception.
         *  Only the labelled local-candidate iteration drivers use this frozen control policy. */
        PRE_TARGETS,
        SELECTED,
    }
    private val selected get() = semantics != Semantics.HISTORICAL
    private val targetControls get() = semantics == Semantics.SELECTED

    /** Keep the scalar Position oracle available unchanged. The selected run-1 constructor
     *  admits nonexact concrete answers as STAR before starting their analyses; this is not
     *  a normalization of observations or of ordinary summary applicability. */
    enum class InitialAdmission {
        HISTORICAL, RUN1_CONCRETE_CHAIN;

        fun admit(offered: Pattern, run1: Boolean): Pattern {
            if (this == HISTORICAL) return offered
            check(run1) { "The selected initial constructor belongs to run 1" }
            check(offered.fact.tail != Tail.ANY_TAINT) { "Run 1 never admits a must initial" }
            if (offered.fact.tail != Tail.ANY) return offered
            check(offered.fact.mark is MarkSlot.Concrete && offered.fact.base != AccessPathBase.Zero)
            return Pattern(offered.fact.copy(tail = Tail.STAR), ExclusionSet.Empty)
        }
    }

    private val inputs = rawInputs ?: program.inputs(config)
    // PRE_TARGETS is a labelled frozen snapshot. Only the current SELECTED
    // oracle follows the configured mark mode instead of assuming GROUP.
    private val groups = if (selected && config.run1 &&
        (!targetControls || config.mode.markMode == MarkMode.GROUP)) GroupedScalarMarks(program.manager.marks) else null
    private val reached = LinkedHashSet<MethodKey>()
    private val admittedRequests = LinkedHashMap<MethodKey, MutableMap<Pattern, MutableSet<TaintMark>>>()
    private val forward = config.direction == Direction.FORWARD
    private val zero = setOf(ZERO_PATTERN)
    private val work = ArrayDeque<() -> Unit>()
    private val processed = LinkedHashSet<ObservedEdge>()
    private val initials = LinkedHashSet<ObservedInitial>()
    private val rawSummaries = LinkedHashSet<ObservedEdge>()
    private val publications = LinkedHashSet<ObservedEdge>()
    private val selectedDemand = LinkedHashSet<ObservedEdge>()
    private val links = LinkedHashSet<ObservedLink>()
    private val requests = LinkedHashSet<ObservedRequest>()
    private val sourceHits = LinkedHashSet<ObservedSourceHit>()
    private val witnesses = LinkedHashSet<ObservedWitness>()
    private val subscriptions = LinkedHashSet<Part>()
    private val joined = HashSet<Joined>()
    private val literalInputs = HashMap<LiteralKey, MutableList<LinkedHashSet<LiteralInput>>>()
    private val literalCombinations = HashSet<LiteralCombination>()
    private val triggered = HashSet<Triple<MethodKey, CommonInst, Any>>()
    private val predicateSupports = RawPredicateSupports(program.cancellation)
    private val algebras = HashMap<MethodKey, ReferenceAlgebra>()
    private val references = HashMap<MethodKey, FormsReference>()
    private val selectedReferences = HashMap<MethodKey, SelectedFormsReference>()
    private val run1Origins = RawRun1Origins()
    private val demandReference by lazy { SelectedDemandReference(config.index, config.fieldLimit,
        config.direction, program.manager.marks, program.field("__admission_witness__"),
        rejectMayForExact = targetControls) }
    private var invoked = false

    private data class Part(
        val callee: MethodKey,
        val caller: MethodKey,
        val premise: Set<Pattern>,
        val callerLayer: Layer,
        val call: CommonInst,
        val added: Conclusion,
        val zeroOnly: Boolean = false,
    )
    private data class Joined(val publication: ObservedEdge, val call: CommonInst, val parts: List<Part>)
    private data class LiteralKey(val method: MethodKey, val node: CommonInst, val rule: Any)
    private data class LiteralInput(val premise: Set<Pattern>, val conclusion: Conclusion)
    private data class LiteralCombination(val key: LiteralKey, val values: List<LiteralInput>)
    private data class Checks(val fired: List<Pair<SinkRule, Layer>>, val parts: List<Conclusion>)

    fun run(): RunObservation {
        check(!invoked) { "An oracle instance has one closure" }
        invoked = true
        for (root in inputs.roots) if (program.isKnown(root) && (!targetControls || config.run1 || wantsZero(root))) addInitial(root, ZERO_PATTERN)
        while (work.isNotEmpty()) {
            program.manager.cancellation.checkpoint()
            work.removeFirst().invoke()
        }
        return RunObservation(processed = processed.toSet(), initials = initials.toSet(),
            rawSummaries = rawSummaries.toSet(), publications = publications.toSet(),
            selectedDemand = selectedDemand.toSet(), links = links.toSet(), requests = requests.toSet(),
            sourceHits = sourceHits.toSet(), witnesses = witnesses.toSet())
    }

    private fun algebra(method: MethodKey): ReferenceAlgebra = algebras.getOrPut(method) {
        ReferenceAlgebra(config.mode,
            request = { premise, request -> raise(method, premise, request) },
            allowsSource = { node, edge -> !config.seededSources || inputs.seeds.any { seed ->
                seed is Seed.Source && seed.method == method && seed.statement == node && seed.edge == edge.forward
            } },
            sourceHit = { node, edge -> if (!forward) sourceHits += ObservedSourceHit(method, node, edge.forward) },
            manager = program.manager,
            historicalRun1 = true,
            conjunction = { edge, premise, conclusion, node, sink ->
                check(forward) { "Backward forms have independent conjunction branches" }
                for ((index, literal) in edge.literals.withIndex()) {
                    program.manager.cancellation.checkpoint()
                    when (val checked = checkLiteral(method, premise, conclusion, literal)) {
                        null -> Unit
                        else -> for (combination in literal(method, node, edge, edge.literals.size, index,
                            LiteralInput(premise, checked))) {
                            val demand = combination.any { it.conclusion.demand }
                            val result = normalize(edge.target, ExclusionSet.Empty, demand)
                            for (pr in resultPremises(combination.map { it.premise })) sink(pr, result)
                        }
                    }
                }
            })
    }

    private fun reference(method: MethodKey): FormsReference = references.getOrPut(method) {
        FormsReference(program.ops, algebra(method), run1AliasAdmission = selected && config.run1)
    }

    private fun addInitial(method: MethodKey, offered: Pattern) {
        val initial = if (selected && config.run1) InitialAdmission.RUN1_CONCRETE_CHAIN.admit(offered, true)
            else initialAdmission.admit(offered, config.run1)
        reach(method)
        if (!program.isKnown(method) || !initials.add(ObservedInitial(method, initial))) return
        check(initial.fact.tail != Tail.ANY_TAINT || (config.restricted && forward))
        work += {
            val rawStart = startFact(initial)
            val value = if (targetControls && config.run1 && config.mode.markMode == MarkMode.FULL)
                cover(rawStart, setOf(initial)) else rawStart
            val model = program.programMethod(method)
            val nodes = if (forward) listOf(method.statement) else buildList {
                add(program.inst(method, model.normalExit))
                if (initial.fact.base == AccessPathBase.Zero)
                    model.exceptionalExit?.let { add(program.inst(method, it)) }
            }
            for (node in nodes) {
                program.manager.cancellation.checkpoint()
                val forms = program.forms(method)
                val rules = if (forward) forms.entryRules(Direction.FORWARD)
                    else forms.exitRules(Direction.BACKWARD, node).rules
                val seeds = if (!forward && initial.fact.base == AccessPathBase.Zero) seedFacts(method, node) else emptyList()
                for (item in boundary(method, node, rules, listOf(setOf(initial) to value) + seeds))
                    putEdge(method, node, item.first, item.second)
            }
        }
    }

    private fun putEdge(method: MethodKey, node: CommonInst, premise: Set<Pattern>, conclusion: Conclusion) {
        val edge = ObservedEdge(method, premise, cover(conclusion, premise), node)
        if (processed.add(edge)) work += { process(edge) }
    }

    private fun process(edge: ObservedEdge) {
        val node = checkNotNull(edge.node)
        val call = program.callExpression(edge.method, node.location.index)
        if (call != null) {
            val plan = program.forms(edge.method).call(config.direction, node, call)
            when {
                edge.conclusion.fact.base == AccessPathBase.Zero -> {
                    emitAfter(edge.method, node, edge.premise, edge.conclusion)
                    if (isZero(edge.premise)) {
                        if (forward) walk(edge.method, node, plan,
                            listOf(PlanItem(edge.premise, edge.conclusion, null)), layer(edge.conclusion))
                        else {
                            val seeds = seedFacts(edge.method, node).map { PlanItem(it.first, it.second, null) }
                            if (seeds.isNotEmpty()) walk(edge.method, node, plan, seeds,
                                layer(edge.conclusion), from = CallPoint.BOUND)
                            for (callee in calleeStage(plan)?.callees.orEmpty()) {
                                if (targetControls && !wantsZero(callee)) continue
                                subscribe(Part(callee, edge.method, edge.premise, layer(edge.conclusion),
                                    node, edge.conclusion, zeroOnly = true))
                                addInitial(callee, ZERO_PATTERN)
                            }
                        }
                    } else check(!forward) { "A concrete-premise REACH edge belongs to a backward run" }
                }
                edge.conclusion.fact.base !in plan.touched ->
                    emitAfter(edge.method, node, edge.premise, edge.conclusion)
                else -> walk(edge.method, node, plan, listOf(PlanItem(edge.premise, edge.conclusion, null)),
                    layer(edge.conclusion))
            }
            return
        }
        applier(edge.method).statement(program.forms(edge.method).statement(config.direction, node),
            edge.premise, edge.conclusion, Place(node, config.run1, sources = true),
            sink = { pr, conclusion -> emitAfter(edge.method, node, pr, limit(conclusion, config.fieldLimit)) },
            untouched = { pr, conclusion -> emitAfter(edge.method, node, pr, conclusion) })
    }

    private fun emitAfter(method: MethodKey, node: CommonInst, premise: Set<Pattern>, conclusion: Conclusion) {
        val value = cover(conclusion, premise)
        if (value != conclusion) { emitAfter(method, node, premise, value); return }
        val model = program.programMethod(method)
        val summaryEnd = if (forward) node.location.index == model.normalExit else node == method.statement
        val exceptional = forward && node.location.index == model.exceptionalExit
        if (summaryEnd || exceptional) {
            val exit = if (forward) program.forms(method).exitRules(Direction.FORWARD, node)
                else ExitRules(program.forms(method).entryRules(Direction.BACKWARD), false, emptySet())
            boundary(method, node, exit.rules, listOf(premise to conclusion)) { pr, value, checks ->
                if (summaryEnd && program.interpreter.isSummaryBase(value.fact.base)) {
                    val dropStatic = exit.globalStateDrop && isZero(pr) && value.fact.base == STATIC && value in checks.parts
                    val mark = (value.fact.mark as? MarkSlot.Concrete)?.mark
                    val removeMark = isZero(pr) && mark != null &&
                        (value.fact.base == AccessPathBase.This || value.fact.base is AccessPathBase.Argument) &&
                        mark in exit.entryMarks
                    if (!dropStatic && !removeMark) summary(method, pr, value)
                }
            }
        }
        val next = if (forward) model.successors[node.location.index] else buildList {
            addAll(model.successors.indices.filter { node.location.index in model.successors[it] })
            if (selected && model.backwardExitDiscovery && node.location.index == model.exceptionalExit) {
                // Independent S11 oracle: search forward from each candidate, rather than
                // reading the engine fixture's compact/wired backward graph.
                val exits = setOf(model.normalExit, checkNotNull(model.exceptionalExit))
                for (candidate in model.successors.indices) {
                    val seen = HashSet<Int>()
                    val todo = ArrayDeque<Int>()
                    todo.addLast(candidate)
                    var reachesExit = false
                    while (todo.isNotEmpty()) {
                        program.cancellation.checkpoint()
                        val current = todo.removeFirst()
                        if (!seen.add(current)) continue
                        if (current in exits) { reachesExit = true; break }
                        todo.addAll(model.successors[current])
                    }
                    if (!reachesExit) add(candidate)
                }
            }
        }
        for (index in next) putEdge(method, program.inst(method, index), premise, conclusion)
    }

    private fun boundary(method: MethodKey, node: CommonInst, rules: RuleStatement,
                         startInputs: List<Pair<Set<Pattern>, Conclusion>>,
                         after: (Set<Pattern>, Conclusion, Checks) -> Unit = { _, _, _ -> }): List<Pair<Set<Pattern>, Conclusion>> {
        val items = ArrayList<Pair<Set<Pattern>, Conclusion>>()
        val seen = HashSet<Pair<Set<Pattern>, Conclusion>>()
        val add: ReferenceSink = { pr, value ->
            val item = pr to cover(limit(value, config.fieldLimit), pr)
            if (seen.add(item)) items += item
        }
        val applier = applier(method)
        fun applyInput(pr: Set<Pattern>, value: Conclusion) =
            applier.statement(rules.summary, pr, value, Place(node, config.run1, sources = true), add)
        for ((pr, value) in startInputs) applyInput(pr, value)
        var index = 0
        while (index < items.size) {
            program.manager.cancellation.checkpoint()
            val (pr, value) = items[index++]
            val checks = sinks(method, node, pr, value, rules.sinks)
            for ((sink, layer) in if (selected) emptyList() else checks.fired)
                applier.gen(sink.endFacts, zero, Conclusion(ZERO_FACT, ExclusionSet.Empty, layer == Layer.DEMAND), add)
            if (!selected && !forward) for (sink in rules.sinks) {
                val ends = rules.endFacts.edges.filter { edge -> sink.endFacts.any { it.forward == edge.forward } }
                var applied = false
                applier.gen(ends, pr, value) { p, result -> applied = true; add(p, result) }
                if (applied) for ((seedPr, seed) in triggerSeeds(method, node, sink)) applyInput(seedPr, seed)
            }
            after(pr, value, checks)
        }
        return items
    }

    private fun summary(method: MethodKey, premise: Set<Pattern>, conclusion: Conclusion) {
        // Canonicalize only a complete singleton FLOW pair. Point states retain their read barrier.
        val flow = premise.singleOrNull()?.fact?.mark is MarkSlot.Star && conclusion.fact.mark is MarkSlot.Star
        fun endpoint(p: Pattern) = if (flow && p.fact.tail == Tail.EXACT)
            p.copy(fact = p.fact.copy(tail = Tail.STAR)) else p
        val key = premise.mapTo(linkedSetOf(), ::endpoint)
        val result = if (flow && conclusion.fact.tail == Tail.EXACT)
            conclusion.copy(fact = conclusion.fact.copy(tail = Tail.STAR)) else conclusion
        if (targetControls) {
            // The current oracle has one admitted relation. Frozen historical
            // controls below keep their original raw/selected split.
            publish(method, key, result)
            return
        }
        val raw = ObservedEdge(method, key, result)
        if (!rawSummaries.add(raw)) return
        publish(method, key, result)
    }

    private fun publish(method: MethodKey, premise: Set<Pattern>, conclusion: Conclusion) {
        val selectedForDemand = conclusion.demand || premise.size > 1 || (!forward && isZero(premise))
        val pieces = if (config.run1 || (!targetControls && !forward && isZero(premise))) setOf(conclusion) else buildSet {
            for (member in premise) {
                val guides = inputs.demand.filter { it.first == method }.map { it.second } + listOfNotNull(staticCarry(member))
                for (demand in guides)
                    demandReference.restrict(member, conclusion, demand)?.let {
                        add(if (targetControls) limitSelectedSummary(it, demand.exit) else it)
                    }
            }
        }
        for (piece in pieces) {
            val pub = ObservedEdge(method, premise, piece)
            if (targetControls) rawSummaries += pub
            val finalSelected = if (targetControls)
                piece.demand || premise.size > 1 || (!forward && isZero(premise)) else selectedForDemand
            if (finalSelected) selectedDemand += pub
            if (publications.add(pub)) work += {
                for (part in subscriptions.toList()) if (part.callee == method) match(part, pub)
            }
        }
    }

    /** Independent scalar cut after exact C5. No production DemandStore or packed limit is used. */
    private fun limitSelectedSummary(value: Conclusion, exit: Pattern?): Conclusion {
        val endpoint = exit ?: return value
        if (endpoint.fact.base == AccessPathBase.Zero || value.fact.base == AccessPathBase.Zero) return value
        val depth = endpoint.fact.path.count { it.isCounted() }
        val budget = if (depth >= config.fieldLimit) config.fieldLimit else depth + 1
        var used = 0
        val prefix = ArrayList<Int>()
        for (accessor in value.fact.path) {
            if (accessor.isCounted() && used++ == budget)
                return value.copy(fact = value.fact.copy(path = prefix, tail = Tail.ANY),
                    exclusion = ExclusionSet.Empty, demand = true)
            prefix += accessor
        }
        return value
    }

    private fun walk(method: MethodKey, node: CommonInst, plan: CallPlan, items: List<PlanItem>,
                     callerLayer: Layer, from: CallPoint = plan.entry, pendingDemotion: Boolean = false) {
        val hooks = PlanHooks(guards = forward,
            atBound = { batch -> batch.flatMap { sinks(method, node, it.premise, it.c, plan.sinks).fired }.distinct() },
            callees = { stage, item ->
                for (callee in stage.callees) {
                    val part = Part(callee, method, item.premise, callerLayer, node, item.c)
                    if (selected && config.restricted) {
                        if (program.isKnown(callee)) {
                            // Saved transfer is independent of current demand and of
                            // whether this complete scalar offer was seen before.
                            replayPersisted(part)
                            val complete = currentInitials(callee, Pattern(item.c.fact, item.c.exclusion))
                            if (complete.isNotEmpty()) {
                                subscribe(part)
                                val observed = ObservedLink(callee, method, item.premise, callerLayer,
                                    node, layer(item.c), Pattern(item.c.fact, item.c.exclusion))
                                links += observed
                                complete.forEach { addInitial(callee, it) }
                            }
                        }
                    } else {
                        subscribe(part)
                        link(part)
                    }
                }
                emptyList()
            },
            clean = { cleaner, item ->
                val result = groups?.clean(cleaner, item.c) ?: cleanRes(cleaner, item.c, run1 = selected && config.run1)
                if (config.run1) result.request?.let { raise(method, item.premise, RequestKind.Mark(it)) }
                result.facts.map { item.copy(c = it) }
            },
            statementCut = { item -> item.copy(c = cover(limit(item.c, config.fieldLimit), item.premise)) },
            exit = { item -> item.copy(c = cover(limit(item.c, config.fieldLimit), item.premise)) },
            trigger = { sink -> triggerSeeds(method, node, sink).map { PlanItem(it.first, it.second, null) } })
        for ((point, item) in runForms(method, plan, items, Place(node, config.run1, sources = false), hooks, from, pendingDemotion)) if (point == plan.exit)
            emitAfter(method, node, item.premise, item.c)
    }

    private fun link(part: Part) {
        if (!program.isKnown(part.callee)) return
        val added = Pattern(part.added.fact, part.added.exclusion)
        val link = ObservedLink(part.callee, part.caller, part.premise, part.callerLayer, part.call,
            layer(part.added), added)
        if (!links.add(link)) return
        reach(part.callee)
        work += {
            when {
                selected && config.run1 -> emitSelected(link)
                selected -> currentInitials(part.callee, added).forEach { addInitial(part.callee, it) }
                config.run1 -> addInitial(part.callee, policy(added))
                added.fact.base == AccessPathBase.Zero -> addInitial(part.callee, ZERO_PATTERN)
                else -> for ((method, demand) in inputs.demand) if (method == part.callee)
                    demandReference.emit(demand.entry, added)?.let { addInitial(method, it) }
            }
            if (selected) replaySelected(link)
            else for (request in requests.toList()) if (request.method == part.callee) act(request, link)
        }
    }

    private fun subscribe(part: Part) {
        if (!program.isKnown(part.callee) || !subscriptions.add(part)) return
        work += {
            for (pub in publications.toList()) if (pub.method == part.callee) match(part, pub)
            if (!selected && config.restricted && !part.zeroOnly) replayPersisted(part)
        }
    }

    private fun replayPersisted(part: Part) {
        val seen = HashSet<RecordLeafView>()
        for (record in inputs.records) if (record.method == part.callee) {
            if (record.direction == config.direction) native(part, record)
            else reverseRecordLeaf(record.direction, record.premise, record.conclusion)?.let { view ->
                if (seen.add(view)) view(part, view)
            }
        }
    }

    private fun match(part: Part, pub: ObservedEdge) {
        if (part.zeroOnly) {
            if (isZero(pub.premise)) resume(part, listOf(PlanItem(part.premise, pub.conclusion, false)))
            return
        }
        if (pub.premise.size == 1) {
            val premise = pub.premise.single()
            if (satisfies(premise, Pattern(part.added.fact, part.added.exclusion), config.restricted))
                reduce(part, premise, pub.conclusion)?.let { resume(part, listOf(it)) }
            return
        }
        check(forward) { "Backward publications cannot be conjunctive" }
        val choices = pub.premise.map { member -> subscriptions.filter { candidate ->
            !candidate.zeroOnly && candidate.callee == pub.method && candidate.caller == part.caller &&
                candidate.call == part.call && candidate.added.fact.base != AccessPathBase.Zero &&
                satisfies(member, Pattern(candidate.added.fact, candidate.added.exclusion), config.restricted)
        } }
        for (parts in product(choices)) if (joined.add(Joined(pub, part.call, parts))) {
            val demand = pub.conclusion.demand || parts.any { it.added.demand }
            val result = normalize(pub.conclusion.fact, pub.conclusion.exclusion, demand)
            for (pr in resultPremises(parts.map { it.premise }))
                resume(parts.first(), listOf(PlanItem(pr, result, false)))
        }
    }

    private fun native(part: Part, record: RawRecord) {
        val added = Pattern(part.added.fact, part.added.exclusion)
        if (!applicable(record.premise, added) && !inside(record.premise, added)) return
        val pending = record.premise.fact.tail == Tail.ANY_TAINT && !inside(record.premise, added)
        val result = reduce(part, record.premise, record.conclusion) ?: return
        resume(part, listOf(if (pending) result.copy(identityCandidate = false) else result), pending)
    }

    private fun view(part: Part, view: RecordLeafView) {
        val added = Pattern(part.added.fact, part.added.exclusion)
        if (!applicable(view.premise, added) && !inside(view.premise, added)) return
        val outcome = concat(part.added, summaryEdge(view.premise, view.result), edgeDemand = view.result.demand,
            restricted = config.restricted)
        check(outcome !is EdgeOutcome.Request && outcome !is EdgeOutcome.PositionRequest)
        if (outcome is EdgeOutcome.Fact)
            resume(part, listOf(PlanItem(part.premise, outcome.conclusion, recordLeafIdentity(view))))
    }

    private fun reduce(part: Part, premise: Pattern, conclusion: Conclusion): PlanItem? {
        val outcome = concat(part.added, summaryEdge(premise, conclusion), edgeDemand = conclusion.demand,
            restricted = config.restricted)
        check(outcome !is EdgeOutcome.Request && outcome !is EdgeOutcome.PositionRequest)
        if (outcome !is EdgeOutcome.Fact) return null
        val identity = if (selected && config.run1) scalarSummaryNoEffect(premise.fact, conclusion.fact)
            else premise.fact.base != AccessPathBase.Zero && !conclusion.demand && conclusion == startFact(premise)
        return PlanItem(part.premise, outcome.conclusion, identity)
    }

    /** Direct scalar contract; independent of the packed production partition. */
    private fun scalarSummaryNoEffect(initial: PathFact, result: PathFact): Boolean {
        if (initial.base == AccessPathBase.Zero || initial.base != result.base || initial.path != result.path) return false
        val first = initial.mark
        val second = result.mark
        return when {
            first is MarkSlot.Star && second is MarkSlot.Star -> initial.tail == Tail.STAR && result.tail == Tail.STAR
            first is MarkSlot.Concrete && second is MarkSlot.Concrete -> first.mark == second.mark
            else -> false
        }
    }

    private fun resume(part: Part, items: List<PlanItem>, pendingDemotion: Boolean = false) {
        if (items.isEmpty()) return
        val expression = checkNotNull(program.callExpression(part.caller, part.call.location.index))
        val plan = program.forms(part.caller).call(config.direction, part.call, expression)
        val stage = checkNotNull(calleeStage(plan))
        walk(part.caller, part.call, plan, items, part.callerLayer, stage.to, pendingDemotion)
    }

    private fun checkLiteral(method: MethodKey, premise: Set<Pattern>, conclusion: Conclusion, literal: Pattern): Conclusion? =
        when (val checked = groups?.check(premise.first(), conclusion, literal) ?: markCheck(premise.first(), conclusion, literal, config.restricted)) {
            CheckResult.None -> null
            is CheckResult.Request -> { raise(method, premise, RequestKind.Mark(checked.mark)); null }
            CheckResult.Holds -> groups?.conclusion(conclusion) ?: conclusion.copy(demand = conjDemand(conclusion, literal))
        }

    private fun sinks(method: MethodKey, node: CommonInst, premise: Set<Pattern>, conclusion: Conclusion,
                      sinks: List<SinkRule>): Checks {
        if (!forward) return Checks(emptyList(), emptyList())
        val fired = ArrayList<Pair<SinkRule, Layer>>()
        val parts = ArrayList<Conclusion>()
        for (sink in sinks) {
            val predicate = sink.predicate
            if (predicate != null && !predicate.isTrue) {
                for ((index, pattern) in predicate.leaves.withIndex()) {
                    val checked = checkLiteral(method, premise, conclusion, pattern) ?: continue
                    parts += checked
                    for (combination in predicateSupports.add(method, node, checkNotNull(sink.occurrenceId),
                        predicate, index, premise, checked)) {
                        witnesses += ObservedWitness(sink.rule, method, node, sink.alternative, config.index,
                            combination.inputs.map { ObservedSinkEdge(it.premise, it.layer, it.facts, it.group) },
                            if (selected) emptySet() else sink.endFacts.mapTo(LinkedHashSet()) { it.edge.to }, proof = combination.proof)
                        fired += sink to combination.layer
                    }
                }
                continue
            }
            for ((index, pattern) in sink.patterns.withIndex()) {
                val checked = checkLiteral(method, premise, conclusion, pattern) ?: continue
                parts += checked
                val input = LiteralInput(premise, checked)
                val combinations = if (!sink.conjunctive) listOf(listOf(input)) else
                    literal(method, node, sink, sink.patterns.size, index, input)
                for (combination in combinations) {
                    val effectiveLayer = if (combination.any { it.conclusion.demand }) Layer.DEMAND else Layer.NORMAL
                    witnesses += ObservedWitness(sink.rule, method, node, sink.alternative, config.index,
                        combination.map { ObservedSinkEdge(it.premise, layer(it.conclusion), setOf(it.conclusion)) },
                        if (selected) emptySet() else sink.endFacts.mapTo(LinkedHashSet()) { it.edge.to },
                        proof = sink.occurrenceId?.let { ProofKey(it, emptyList()) })
                    fired += sink to effectiveLayer
                }
            }
        }
        return Checks(fired.distinct(), parts)
    }

    private fun literal(method: MethodKey, node: CommonInst, rule: Any, arity: Int, index: Int,
                        input: LiteralInput): List<List<LiteralInput>> {
        val key = LiteralKey(method, node, rule)
        val slots = literalInputs.getOrPut(key) { MutableList(arity) { LinkedHashSet() } }
        check(slots.size == arity)
        if (!slots[index].add(input)) return emptyList()
        return product(slots.map { it.toList() }).filter { literalCombinations.add(LiteralCombination(key, it)) }
    }

    private fun raise(method: MethodKey, premise: Set<Pattern>, kind: RequestKind) {
        check(config.run1) { "Restricted runs have no requests" }
        if (selected) { collectSelected(method, premise, kind); return }
        val initial = premise.single()
        check(initial.fact.mark == MarkSlot.STAR && initial.fact.tail == Tail.STAR && initial.exclusion == ExclusionSet.Empty)
        val request = ObservedRequest(method, initial, kind)
        if (requests.add(request)) work += {
            for (link in links.toList()) if (link.callee == method) act(request, link)
        }
    }

    private fun act(request: ObservedRequest, link: ObservedLink) {
        val query = when (val kind = request.kind) {
            is RequestKind.Mark -> request.premise
            is RequestKind.Position -> Pattern(PathFact(STATIC, kind.path.toList(), Tail.STAR, MarkSlot.STAR), ExclusionSet.Empty)
        }
        if (!overlap(query, link.added)) return
        when (val kind = request.kind) {
            is RequestKind.Mark -> when (val mark = link.added.fact.mark) {
                is MarkSlot.Concrete -> if (mark.mark == kind.mark)
                    addInitial(request.method, answer(request.premise, link.added, kind.mark))
                is MarkSlot.Star -> if (kind.mark !in mark.excluded) raise(link.caller, link.premise, kind)
            }
            is RequestKind.Position -> when {
                link.added.fact.path.startsWith(kind.path.toList()) ->
                    addInitial(request.method, Pattern(PathFact(STATIC, kind.path.toList(), Tail.STAR, MarkSlot.STAR), ExclusionSet.Empty))
                link.premise.singleOrNull()?.fact?.base == STATIC -> raise(link.caller, link.premise, kind)
            }
        }
    }

    private fun cover(value: Conclusion, premise: Set<Pattern>): Conclusion {
        var current = groups?.conclusion(value) ?: value
        if (targetControls && config.run1 && config.mode.markMode == MarkMode.FULL) {
            if (current.fact.base == STATIC || premise.any { it.fact.base == STATIC })
                current = current.copy(demand = true)
        }
        return if (selected && config.run1 && current.exclusion != ExclusionSet.Empty)
            current.copy(exclusion = ExclusionSet.Empty, demand = true) else current
    }

    private fun selectedReference(method: MethodKey): SelectedFormsReference = selectedReferences.getOrPut(method) {
        val algebra = SelectedReferenceAlgebra(config.mode,
            request = { premise, request -> raise(method, premise, request) },
            allows = { node, edge -> !config.seededSources || inputs.seeds.any { seed ->
                seed is Seed.Source && seed.method == method && seed.statement == node && seed.edge == edge.forward
            } },
            hit = { node, edge -> if (!forward) sourceHits += ObservedSourceHit(method, node, edge.forward) },
            manager = program.manager,
            join = { edge, premise, conclusion, node, sink ->
                check(forward)
                for ((index, literal) in edge.literals.withIndex()) {
                    val checked = checkLiteral(method, premise, conclusion, literal) ?: continue
                    for (combination in literal(method, node, edge, edge.literals.size, index, LiteralInput(premise, checked))) {
                        val result = normalize(edge.target, ExclusionSet.Empty,
                            combination.any { it.conclusion.demand })
                        for (pr in resultPremises(combination.map { it.premise })) sink(pr, result)
                    }
                }
            })
        SelectedFormsReference(program.ops, algebra, run1AliasAdmission = config.run1)
    }
    private fun applier(method: MethodKey): FormApplier<Set<Pattern>, Conclusion> =
        if (selected) selectedReference(method).applier else reference(method).applier
    private fun runForms(method: MethodKey, plan: CallPlan, items: List<PlanItem>, at: Place,
                         hooks: PlanHooks, from: CallPoint, pending: Boolean): List<Pair<CallPoint, PlanItem>> =
        if (selected) selectedReference(method).run(plan, items, at, hooks, from, pending)
        else reference(method).run(plan, items, at, hooks, from, pending)

    /** Ordinary stored edge, independently generated when a reached owner is initialized. */
    private fun reach(method: MethodKey) {
        if (!selected || !config.run1 || !program.isKnown(method) || !reached.add(method)) return
        // The selected engine has neither inherited static B nor executable S-root
        // identity summaries. Static permission is a later shared demand view.
        admittedRequests[method] = linkedMapOf()
    }
    /** Selected ZERO uses a stored local row, not virtual discovery permission. */
    private fun wantsZero(method: MethodKey): Boolean = inputs.demand.any {
        it.first == method && it.second.entry.fact.base == AccessPathBase.Zero
    }
    /** Selected original AP protocol: input intersects fixed demand; there is no actual-query authority. */
    private fun currentInitials(method: MethodKey, actual: Pattern): Set<Pattern> {
        if (actual.fact.base == AccessPathBase.Zero)
            return if (!targetControls || wantsZero(method)) setOf(ZERO_PATTERN) else emptySet()
        val input = limit(normalize(actual.fact, actual.exclusion, demand = actual.fact.tail == Tail.ANY), config.fieldLimit)
        val leaf = Pattern(input.fact, input.exclusion)
        val guides = inputs.demand.filter { it.first == method }.map { it.second } + listOfNotNull(staticCarry(leaf))
        return guides.mapNotNullTo(linkedSetOf()) { demandReference.emit(it.entry, leaf) }
    }
    /** A family is instantiated at this actual slot; a root probe is never a stored universal pair. */
    private fun staticCarry(actual: Pattern): DemandPattern? {
        if (!selected || !inputs.hasSharedStaticCarry || actual.fact.base != STATIC) return null
        val located = if (actual.fact.tail == Tail.ANY_TAINT)
            Pattern(actual.fact.copy(tail = Tail.ANY), ExclusionSet.Empty) else actual
        val pattern = if (located.fact.mark is MarkSlot.Star)
            located.copy(fact = located.fact.copy(mark = MarkSlot.STAR)) else located
        return DemandPattern(pattern, pattern)
    }
    private fun origin(premise: Set<Pattern>): Pattern? {
        val p = premise.singleOrNull() ?: return null
        if (p.fact.mark != MarkSlot.STAR || p.fact.tail != Tail.STAR || p.exclusion != ExclusionSet.Empty) return null
        if (p.fact.base == org.opentaint.dataflow.ap.ifds.AccessPathBase.Zero) return null
        if (p.fact.base == STATIC && p.fact.path.size != 2) return null
        return p
    }
    private fun selectedRequests(method: MethodKey): MutableMap<Pattern, MutableSet<TaintMark>> {
        reach(method)
        return admittedRequests.getOrPut(method) { linkedMapOf() }
    }
    private fun admitRequest(method: MethodKey, slot: Pattern, mark: TaintMark, observed: Boolean) {
        if (observed) requests += ObservedRequest(method, slot, RequestKind.Mark(mark))
        if (!selectedRequests(method).getOrPut(slot) { linkedSetOf() }.add(mark)) return
        work += { for (link in links.toList()) if (link.callee == method) actSelected(slot, mark, link) }
    }
    private fun collectSelected(method: MethodKey, premise: Set<Pattern>, kind: RequestKind) {
        check(config.run1)
        check(kind is RequestKind.Mark) { "The selected protocol has no Position requests" }
        val slot = origin(premise) ?: return
        admitRequest(method, slot, groups?.atom(kind.mark) ?: kind.mark, observed = true)
    }
    private fun emitSelected(link: ObservedLink) {
        val input = link.added
        if (input.fact.base == org.opentaint.dataflow.ap.ifds.AccessPathBase.Zero) {
            addInitial(link.callee, ZERO_PATTERN); return
        }
        if (input.fact.base != STATIC) addInitial(link.callee, SelectedScalarPlan.slot(input.fact.base))
        // Static values are handled by explicit local read/write descriptors, never
        // by ordinary method-entry requests. No inherited field/mark plan participates.
    }

    private fun replaySelected(link: ObservedLink) {
        if (!config.run1) return
        for ((slot, marks) in selectedRequests(link.callee).entries.toList())
            for (mark in marks.toList()) actSelected(slot, mark, link)
    }
    private fun actSelected(slot: Pattern, mark: TaintMark, link: ObservedLink) {
        if (!SelectedScalarPlan.geometry(slot, link.added)) return
        when (val actual = link.added.fact.mark) {
            is MarkSlot.Concrete -> if (actual.mark == mark) {
                val exact = link.added.fact.tail == Tail.EXACT && link.added.fact.path == slot.fact.path
                addInitial(link.callee, Pattern(slot.fact.copy(tail = if (exact) Tail.EXACT else Tail.STAR,
                    mark = actual), ExclusionSet.Empty))
            }
            is MarkSlot.Star -> {
                val target = origin(link.premise) ?: return
                if (mark in selectedRequests(link.caller)[target].orEmpty()) return
                admitRequest(link.caller, target, mark, observed = true)
            }
        }
    }


    private fun seedFacts(method: MethodKey, node: CommonInst): List<Pair<Set<Pattern>, Conclusion>> =
        rawSinkSeedRequirements(program, inputs, method, node)
            .map { zero to limit(normalize(it.fact, ExclusionSet.Empty, false), config.fieldLimit) }

    private fun triggerSeeds(method: MethodKey, node: CommonInst, sink: SinkRule): List<Pair<Set<Pattern>, Conclusion>> =
        if (!triggered.add(Triple(method, node, sink.joinKey))) emptyList() else sink.seedPatterns().map {
            zero to limit(normalize(it.fact, ExclusionSet.Empty, false), config.fieldLimit)
        }

    private fun resultPremises(premises: List<Set<Pattern>>): List<Set<Pattern>> {
        if (selected && config.run1) return run1Origins.split(premises)
        val values = premises.flatten().filterTo(LinkedHashSet()) { it.fact.base != AccessPathBase.Zero }
        return listOf(if (values.isEmpty()) zero else values)
    }

    private fun <T> product(slots: List<List<T>>): List<List<T>> {
        var result: List<List<T>> = listOf(emptyList())
        for (slot in slots) {
            program.manager.cancellation.checkpoint()
            result = result.flatMap { before -> slot.map { before + it } }
        }
        return result
    }

    private fun calleeStage(plan: CallPlan): CallStage.Callees? =
        plan.stages.firstNotNullOfOrNull { it as? CallStage.Callees }
    private fun isZero(premise: Set<Pattern>): Boolean = premise.size == 1 && premise.single().fact.base == AccessPathBase.Zero
    private fun layer(conclusion: Conclusion): Layer = if (conclusion.demand) Layer.DEMAND else Layer.NORMAL
}

