/** Selected finite closure with raw phase inputs, independent of production stores and selectors. */
internal class RawCurrentClosure(program: FiniteProgramFixtures, config: RunConfig, inputs: ProgramRunInputs,
                                 semantics: NaiveClosure.Semantics = NaiveClosure.Semantics.SELECTED) {
    private val closure = NaiveClosure(program, config, semantics = semantics, rawInputs = inputs)
    fun run(): RunObservation = closure.run()
}

package org.opentaint.dataflow.bidi.fixtures

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.driver.Seed
import org.opentaint.dataflow.bidi.driver.SeedIndex
import org.opentaint.dataflow.bidi.engine.RunConfig
import org.opentaint.dataflow.bidi.interp.SinkRule
import org.opentaint.dataflow.bidi.interp.ZERO_PATTERN
import org.opentaint.dataflow.bidi.store.DemandStore
import org.opentaint.dataflow.bidi.store.PersistentRecordStore
import org.opentaint.dataflow.bidi.store.RuleId
import org.opentaint.ir.api.common.cfg.CommonInst

/** Independent finite NNF iteration with raw barriers and unverified candidate reports.
 *  It uses RawCurrentClosure and no production driver, demand/record index, Support or HandOff.
 *  Inputs admit positive bound source/sink conditions; END actions are ignored; aliases and ordered field actions
 *  remain outside this explicit test domain. This is a current oracle, not an F71 instance. */
// Frozen pre-Targets control routing; this is not the selected Target driver oracle.
class RawPredicateIteration(private val program: FiniteProgramFixtures, private val roots: List<MethodKey>,
                                  private val limits: List<Int>) {
    init {
        require(limits.isNotEmpty() && limits.first() == 1 && limits.all { it >= 1 })
        require(limits.zipWithNext().all { (a, b) -> b >= a })
    }

    private fun validateInputs(inputs: ProgramRunInputs) {
        for (call in program.callInputs) for (stage in call.plan.stages) when (stage) {
            is org.opentaint.dataflow.bidi.interp.CallStage.Actions ->
                check(stage.steps.isEmpty()) { "The NNF iteration oracle excludes ordered field/alias actions" }
            is org.opentaint.dataflow.bidi.interp.CallStage.Edges -> {
                check(stage.kind != org.opentaint.dataflow.bidi.interp.StageKind.ALIASES)
                check(stage.guard == null && stage.trigger == null)
            }
            is org.opentaint.dataflow.bidi.interp.CallStage.Predefined -> error("Predefined models are outside this oracle")
            is org.opentaint.dataflow.bidi.interp.CallStage.Callees -> Unit
        }
        check(inputs.records.all { !it.conclusion.demand })
        val summaries = program.statementInputs.map { it.summary } + program.entryInputs.map { it.rules.summary } +
            program.exitInputs.map { it.rules.rules.summary }
        check(summaries.flatMap { it.sources }.all { !it.backward })
    }

    fun run(): HistoricalIterationResult {
        var demand = emptyList<Pair<MethodKey, DemandPattern>>()
        var seeds = emptyList<Seed>()
        val records = LinkedHashSet<RawRecord>()
        val confirmed = LinkedHashMap<HistoricalFinding, HistoricalState>()
        var currentDemand = LinkedHashMap<HistoricalFinding, HistoricalState>()
        val log = ArrayList<HistoricalRun>()
        for ((offset, limit) in limits.withIndex()) {
            program.cancellation.checkpoint()
            val index = offset + 1
            val config = RunConfig(index, limit,
                if (index == 1) null else DemandStore.Builder(program.ap).build(),
                PersistentRecordStore(program.ap), SeedIndex.of(seeds), roots,
                run1MarkMode = MarkMode.GROUP)
            val inputs = ProgramRunInputs(roots.toList(), demand.toList(), records.toList(), seeds.toList())
            validateInputs(inputs)
            var observation = RawCurrentClosure(program, config, inputs, NaiveClosure.Semantics.PRE_TARGETS).run()
            if (config.direction == Direction.FORWARD) {
                currentDemand = LinkedHashMap()
                for (witness in observation.witnesses) {
                    val key = HistoricalFinding(witness.rule, witness.statement)
                    if (!config.run1 && witness.confirmed) confirmed[key] = HistoricalState.CONFIRMED
                    else if (key !in confirmed) currentDemand[key] = HistoricalState.DEMAND
                }
                // A later witness of the same key can confirm it; remove the earlier demand row.
                confirmed.keys.forEach(currentDemand::remove)
            }
            // Every phase persists eligible ordinary normal singleton facts; grouped F1 taint is D.
            for (edge in observation.rawSummaries) if (!edge.conclusion.demand && edge.premise.size == 1 &&
                !(config.direction == Direction.BACKWARD && isZero(edge.premise))) {
                records += RawRecord(edge.method, config.direction, edge.premise.single(), edge.conclusion)
            }
            demand = handOff(config.direction, observation)
            seeds = if (config.direction == Direction.FORWARD) sinkSeeds(observation, currentDemand.keys)
                else observation.sourceHits.map { Seed.Source(it.method, it.statement, it.forward) }
            log += HistoricalRun(index, inputs, observation,
                ProgramRunInputs(roots.toList(), demand.toList(), records.toList(), seeds.toList()))
            if (config.direction == Direction.FORWARD && (currentDemand.isEmpty() ||
                (!config.run1 && observation.processed.none { it.conclusion.demand } &&
                    observation.rawSummaries.none { it.conclusion.demand } &&
                    observation.links.none { it.linkLayer == Layer.DEMAND }))) break
        }
        return HistoricalIterationResult(LinkedHashMap<HistoricalFinding, HistoricalState>().also {
            it.putAll(confirmed); it.putAll(currentDemand)
        }, log.toList())
    }

    /** Current ap.md9.2: structurally selected publications swap; abstract excluded marks normalize to STAR. */
    private fun handOff(direction: Direction, observation: RunObservation): List<Pair<MethodKey, DemandPattern>> {
        val result = LinkedHashSet<Pair<MethodKey, DemandPattern>>()
        for (edge in observation.selectedDemand) {
            program.cancellation.checkpoint()
            fun normalized(p: Pattern, entry: Boolean = false): Pattern {
                val forgotten = if (p.fact.tail == Tail.ANY_TAINT || (entry && p.fact.tail == Tail.STAR)) Pattern(p.fact.copy(tail = Tail.ANY), ExclusionSet.Empty) else p
                return if (forgotten.fact.mark is MarkSlot.Star) forgotten.copy(fact = forgotten.fact.copy(mark = MarkSlot.STAR)) else forgotten
            }
            val entry = normalized(Pattern(edge.conclusion.fact.copy(path = edge.conclusion.fact.path.toList()), edge.conclusion.exclusion), entry = true)
            if (direction == Direction.FORWARD) for (member in edge.premise) result += edge.method to DemandPattern(entry, normalized(member))
            else {
                check(edge.premise.size == 1)
                result += edge.method to DemandPattern(entry, edge.premise.single().takeUnless { it.fact.base == AccessPathBase.Zero }?.let(::normalized))
            }
        }
        return result.toList()
    }

    private fun sinkSeeds(observation: RunObservation, wanted: Set<HistoricalFinding>): List<Seed> {
        val result = LinkedHashSet<Seed>()
        for (w in observation.witnesses) if (HistoricalFinding(w.rule, w.statement) in wanted) {
            program.cancellation.checkpoint()
            val forms = program.forms(w.methodKey)
            val sinks: List<SinkRule> = program.callExpression(w.methodKey, w.statement.location.index)?.let {
                forms.call(Direction.FORWARD, w.statement, it).sinks
            } ?: forms.exitRules(Direction.FORWARD, w.statement).rules.sinks
            for (s in sinks) if (s.rule == w.rule) {
                if (s.predicate != null) {
                    if (!s.unconditional) result += Seed.PredicateSink(checkNotNull(s.occurrenceId), w.methodKey, w.statement)
                } else for (p in s.patterns) if (p.fact.base != AccessPathBase.Zero)
                    result += Seed.Sink(w.rule, w.methodKey, w.statement, p)
            }
        }
        return result.toList()
    }

    private fun isZero(values: Set<Pattern>): Boolean = values.size == 1 && values.single().fact.base == AccessPathBase.Zero
}

package org.opentaint.dataflow.bidi.fixtures

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.interp.*
import org.opentaint.dataflow.util.Cancellation
import org.opentaint.ir.api.common.cfg.CommonInst

/** Bounded reference joins: rescan the positive DAG, without production indexes or delta propagation. */
internal class RawPredicateSupports(private val cancellation: Cancellation) {
    private data class Scope(val method: MethodKey, val node: CommonInst, val rule: RuleOccurrenceId)
    private data class Header(val premise: Set<Pattern>, val layer: Layer, val group: GroupKey)
    private data class Proof(val bindings: Map<Int, Header>, val choices: Set<Pair<Int, Int>>)
    private class State {
        val leaves = HashMap<Int, LinkedHashMap<Header, Input>>()
        val emitted = HashMap<Proof, List<Input>>()
    }
    data class Input(val premise: Set<Pattern>, val layer: Layer, val group: GroupKey, val facts: Set<Conclusion>)
    data class Combination(val proof: ProofKey, val inputs: List<Input>) {
        val layer: Layer get() = if (inputs.any { it.layer == Layer.DEMAND }) Layer.DEMAND else Layer.NORMAL
    }
    private val states = HashMap<Scope, State>()

    fun add(method: MethodKey, node: CommonInst, rule: RuleOccurrenceId, predicate: RulePredicate,
            leaf: Int, premise: Set<Pattern>, conclusion: Conclusion): List<Combination> {
        cancellation.checkpoint()
        val layer = if (conclusion.demand) Layer.DEMAND else Layer.NORMAL
        val group = rawGroup(conclusion)
        val header = Header(premise.toSet(), layer, group)
        val state = states.getOrPut(Scope(method, node, rule)) { State() }
        val standing = state.leaves.getOrPut(leaf) { LinkedHashMap() }
        val old = standing[header]
        if (old != null && conclusion in old.facts) return emptyList()
        standing[header] = Input(header.premise, layer, group, old?.facts.orEmpty() + conclusion)

        val values = arrayOfNulls<List<Proof>>(predicate.nodeCount)
        for (n in 0 until predicate.nodeCount) {
            cancellation.checkpoint()
            values[n] = when (predicate.kind(n)) {
                RulePredicate.Kind.FALSE -> emptyList()
                RulePredicate.Kind.TRUE -> listOf(Proof(emptyMap(), emptySet()))
                RulePredicate.Kind.LEAF -> {
                    val ordinal = predicate.leafOrdinal(n)
                    state.leaves[ordinal].orEmpty().keys.map { Proof(mapOf(ordinal to it), emptySet()) }
                }
                RulePredicate.Kind.OR -> buildList {
                    predicate.childrenOf(n) { child ->
                        for (proof in checkNotNull(values[child])) {
                            cancellation.checkpoint()
                            add(proof.copy(choices = proof.choices + (n to child)))
                        }
                    }
                }
                RulePredicate.Kind.AND -> {
                    var products = listOf(Proof(emptyMap(), emptySet()))
                    predicate.childrenOf(n) { child ->
                        val next = ArrayList<Proof>()
                        for (a in products) for (b in checkNotNull(values[child])) {
                            cancellation.checkpoint()
                            // One canonical requirement must bind the same complete input each time.
                            if (b.bindings.any { (key, value) -> key in a.bindings && a.bindings[key] != value }) continue
                            next += Proof(a.bindings + b.bindings, a.choices + b.choices)
                        }
                        products = next
                    }
                    products
                }
            }
        }
        return buildList {
            for (proof in checkNotNull(values[predicate.root]).distinct()) {
                cancellation.checkpoint()
                val ordinals = proof.bindings.keys.sorted()
                val inputs = ordinals.map { ordinal -> state.leaves.getValue(ordinal).getValue(proof.bindings.getValue(ordinal)) }
                if (state.emitted[proof] == inputs) continue
                state.emitted[proof] = inputs
                val choices = proof.choices.sortedWith(compareBy<Pair<Int, Int>> { it.first }.thenBy { it.second })
                    .flatMap { listOf(it.first, it.second) }
                add(Combination(ProofKey(rule, ordinals, choices), inputs))
            }
        }
    }
}

private fun rawGroup(c: Conclusion): GroupKey {
    val layer = if (c.demand) Layer.DEMAND else Layer.NORMAL
    val mark = c.fact.mark
    return when {
        c.fact.base == AccessPathBase.Zero -> GroupKey(FactsKind.REACH, layer, c.fact.base)
        mark is MarkSlot.Star -> GroupKey(FactsKind.FLOW, layer, c.fact.base, c.exclusion, mark.excluded, c.fact.tail)
        else -> GroupKey(FactsKind.TAINT, layer, c.fact.base, c.exclusion, tail =
            if (c.fact.tail == Tail.EXACT) Tail.ANY_TAINT else c.fact.tail)
    }
}

/** Decode physical full-condition handles only at the requested full method/site, without seed indexes. */
internal fun rawSinkSeedRequirements(program: FiniteProgramFixtures, inputs: ProgramRunInputs,
                                     method: MethodKey, node: CommonInst): List<Pattern> = buildList {
    for (seed in inputs.seeds) {
        program.cancellation.checkpoint()
        if (seed.method != method || seed.statement != node) continue
        when (seed) {
            is org.opentaint.dataflow.bidi.driver.Seed.Source -> Unit
            is org.opentaint.dataflow.bidi.driver.Seed.Sink -> add(seed.requirement)
            is org.opentaint.dataflow.bidi.driver.Seed.PredicateSink -> {
                val forms = program.forms(method)
                val sinks = program.callExpression(method, node.location.index)?.let {
                    forms.call(Direction.FORWARD, node, it).sinks
                } ?: if (node == method.statement) forms.entryRules(Direction.FORWARD).sinks
                else forms.exitRules(Direction.FORWARD, node).rules.sinks
                val sink = sinks.singleOrNull { it.occurrenceId == seed.occurrence }
                    ?: error("Unresolved raw predicate seed at $method/$node: ${seed.occurrence}")
                val predicate = checkNotNull(sink.predicate)
                for (literal in predicate.leaves) {
                    program.cancellation.checkpoint()
                    add(literal)
                }
            }
        }
    }
}

package org.opentaint.dataflow.bidi.fixtures

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.ExclusionSet
import org.opentaint.dataflow.bidi.ap.Pattern
import org.opentaint.dataflow.bidi.interp.ZERO_PATTERN

/** Scalar oracle applied only after a complete compatible binding is accepted.
 * Each returned set is an ordinary atomic premise. No production store, premise policy,
 * InitialAp factory, interner, or executable support-set object supplies the answer.
 */
internal class RawRun1Origins {
    fun split(inputs: Iterable<Set<Pattern>>): List<Set<Pattern>> {
        val bindings = inputs.toList()
        check(bindings.isNotEmpty())
        check(bindings.all { it.size == 1 }) { "An executable run-1 input is atomic" }
        val inputsByOrigin = bindings.map { it.single() }
        check(inputsByOrigin.all { it.exclusion == ExclusionSet.Empty })
        val nonzero = inputsByOrigin.filterTo(LinkedHashSet()) { it.fact.base != AccessPathBase.Zero }
        // A mixed ZERO/nonzero binding produces no ZERO arm. This complete binding
        // permits ZERO only when every selected leaf contribution has a ZERO premise.
        return if (nonzero.isEmpty()) listOf(setOf(ZERO_PATTERN)) else nonzero.map { setOf(it) }
    }
}

package org.opentaint.dataflow.bidi.fixtures

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.engine.*
import org.opentaint.dataflow.bidi.store.RequestMarkSelection
import org.opentaint.dataflow.bidi.store.RequestMarkSet

/** Test-owned scheduling only. Storage, caller replay and input emission are production code. */
internal class Run1RequestPipelineFixtures(val steps: ProtocolSteps = ProtocolSteps.Inline) : AutoCloseable {
    val f = PipelineFixtures(limit = 1, protocol = steps)
    val statistics = Run1AbstractionStatistics()
    val batchStatistics = RequestBatchStatistics()
    val events = ArrayDeque<RunEvent>()
    val sent = ArrayList<RunEvent>()
    val initialObservations = ArrayList<Pair<MethodKey, InitialAp>>()
    val admissionObservations = ArrayList<Pair<MethodKey, AdmittedInitial>>()
    val initials = linkedSetOf<Pair<MethodKey, InitialAp>>()
    val climbs = linkedSetOf<Triple<MethodKey, Run1Slot, Int>>()
    val bases = LinkedHashMap<MethodKey, RequestRows>()
    private val stores = LinkedHashMap<MethodKey, SummaryStorage>()
    private val temporary = LinkedHashMap<MethodKey, RequestStorage>()
    private val emitters = LinkedHashMap<MethodKey, Run1Abstraction>()
    var acceptSends = true
    var acceptNotifications = true
    var cancelOnSend = false
    var onAnswer: (() -> Unit)? = null

    fun storage(method: MethodKey = f.callee): SummaryStorage = stores.getOrPut(method) {
        SummaryStorage(method, f.ap, f.ops, steps)
    }

    private val port = object : SubscriptionPort by f.port {
        override val abstractionStatistics get() = this@Run1RequestPipelineFixtures.statistics
        override val requestBatchStatistics get() = batchStatistics
        override fun summaryStorage(key: MethodKey): SummaryStorage = storage(key)
        override fun post(event: RunEvent.ChangedRequests): Boolean {
            if (!acceptNotifications) return false
            events += event
            return true
        }
        override fun send(event: RunEvent): Boolean {
            if (cancelOnSend) f.ap.cancellation.cancel()
            if (!acceptSends) return false
            sent += event
            events += event
            return true
        }
    }
    val subscriptions = SubscriptionManager(port)

    private fun observe(method: MethodKey, seed: AdmittedInitial) {
        admissionObservations += method to seed
        val initial = seed.initial
        initialObservations += method to initial
        initials += method to initial
    }

    private fun emitter(method: MethodKey): Run1Abstraction = emitters.getOrPut(method) {
        Run1Abstraction(f.ops, { observe(method, it) },
            storage(method)::borrowMatchingRequests, { slot, marks -> collect(method, slot, marks) })
    }

    fun collect(method: MethodKey, slot: Run1Slot, marks: RequestMarkSelection) {
        val fresh = marks.minus(storage(method).borrowRequest(slot), f.ap.cancellation::checkpoint)
        if (!fresh.isEmpty) temporary.getOrPut(method, ::RequestStorage).addAll(slot, fresh)
    }

    /** The test explicitly chooses the method-empty barrier, not an alternate scheduler. */
    fun commit(method: MethodKey = f.callee) {
        val pending = temporary[method] ?: return
        storage(method).commit(pending)
        temporary[method] = RequestStorage()
    }

    fun publish(slot: Run1Slot, vararg ids: Int, method: MethodKey = f.callee) {
        collect(method, slot, RequestMarkSet.fromIds(ids))
        commit(method)
    }

    /** Real caller registration/admission precedes its queued callee LinkIn. */
    fun submit(part: Subscription) {
        subscriptions.subscribe(part)
        events += RunEvent.LinkIn(part.callee, part.ref, part.linkLayer, part.added)
    }

    fun drain() {
        var count = 0
        while (events.isNotEmpty()) {
            check(++count < 100_000) { "Finite request pipeline did not close" }
            when (val event = events.removeFirst()) {
                is RunEvent.ChangedRequests -> subscriptions.onRequests(event.callee, event.rows)
                is RunEvent.LinkIn -> emitter(event.callee).emit(event.ref, event.added)
                is RunEvent.InitialAnswersIn -> {
                    event.answers.forEach { observe(event.method, it) }
                    onAnswer?.invoke()
                }
                is RunEvent.MarkRequestsIn -> for ((slot, marks) in event.rows) {
                    marks.forEachId { climbs += Triple(event.method, slot, it) }
                    collect(event.method, slot, marks)
                }
                is RunEvent.Delivery -> subscriptions.onDelivery(event.callee, event.publications)
                else -> error("Unexpected request pipeline event: $event")
            }
        }
    }

    override fun close() {
        emitters.values.forEach(Run1Abstraction::release)
        subscriptions.freeze()
        f.close()
    }
}

package org.opentaint.dataflow.bidi.fixtures

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.driver.Seed
import org.opentaint.dataflow.bidi.ap.ReferenceRequestKind as RequestKind
import org.opentaint.dataflow.bidi.store.*
import org.opentaint.dataflow.bidi.engine.SinkKey
import org.opentaint.dataflow.bidi.interp.ProofKey
import org.opentaint.ir.api.common.cfg.CommonInst

/** Raw observations retain full caller premises and annotations before bounded union comparison. */
data class ObservedEdge(val method: MethodKey, val premise: Set<Pattern>, val conclusion: Conclusion,
                        val node: CommonInst? = null)
data class ObservedInitial(val method: MethodKey, val initial: Pattern)
data class ObservedLink(val callee: MethodKey, val caller: MethodKey, val premise: Set<Pattern>,
                        val callerLayer: Layer, val call: CommonInst, val linkLayer: Layer, val added: Pattern)
data class ObservedRequest(val method: MethodKey, val premise: Pattern, val kind: RequestKind)
data class ObservedSourceHit(val method: MethodKey, val statement: CommonInst, val forward: PathEdge)
data class ObservedSinkEdge(val premise: Set<Pattern>, val layer: Layer, val facts: Set<Conclusion>,
                            val group: GroupKey? = null)
data class ObservedWitness(val rule: RuleId, val methodKey: MethodKey, val statement: CommonInst,
                           val alternative: Int, val run: Int, val edges: List<ObservedSinkEdge>,
                           val endFacts: Set<PathFact>, val confirmed: Boolean = false, val proof: ProofKey? = null)

/** null sink means anonymous DEMAND; a non-null key means NORMAL. */
data class ObservedTarget(val method: MethodKey, val premise: Set<Pattern>, val sink: SinkKey?) {
    val normal: Boolean get() = sink != null
}

data class RunObservation(
    val processed: Set<ObservedEdge> = emptySet(),
    val initials: Set<ObservedInitial> = emptySet(),
    val rawSummaries: Set<ObservedEdge> = emptySet(),
    val publications: Set<ObservedEdge> = emptySet(),
    val selectedDemand: Set<ObservedEdge> = emptySet(),
    val links: Set<ObservedLink> = emptySet(),
    val requests: Set<ObservedRequest> = emptySet(),
    val sourceHits: Set<ObservedSourceHit> = emptySet(),
    val witnesses: Set<ObservedWitness> = emptySet(),
    val targets: Set<ObservedTarget> = emptySet(),
    val sinkSeeds: Set<Seed> = emptySet(),
) {
    fun rawAt(method: MethodKey, premise: Set<Pattern>): Set<Conclusion> =
        rawSummaries.filter { it.method == method && it.premise == premise }.mapTo(LinkedHashSet()) { it.conclusion }

    /** Compare complete unions, not one production leaf against one expected leaf. */
    fun semantic(universe: BoundedDenotation): SemanticRunObservation = SemanticRunObservation(
        normalizeEdges(processed, universe), initials, normalizeEdges(rawSummaries, universe),
        normalizeEdges(publications, universe), normalizeEdges(selectedDemand, universe),
        normalizeLinks(links, universe), requests, sourceHits, normalizeWitnesses(witnesses, universe), targets)

    fun assertEquivalent(other: RunObservation, universe: BoundedDenotation) {
        val expected = semantic(universe)
        val actual = other.semantic(universe)
        if (expected != actual) throw AssertionError("Finite closure mismatch\nexpected=$expected\nactual=$actual")
    }
}

enum class ObservationComponent { REACH, FLOW, NORMAL_EXACT, NORMAL_MUST, DEMAND_EXACT, DEMAND_MUST, DEMAND_TAINT }
sealed interface ObservationCell {
    data object Zero : ObservationCell
    data class Location(val value: TestLocation) : ObservationCell
    data class Relation(val value: TestLocationPair) : ObservationCell
}
data class SemanticEdgeHeader(val method: MethodKey, val premise: Set<Pattern>, val node: CommonInst?,
                              val group: GroupKey, val component: ObservationComponent)
data class SemanticLinkHeader(val callee: MethodKey, val caller: MethodKey, val premise: Set<Pattern>,
                              val callerLayer: Layer, val call: CommonInst, val group: GroupKey,
                              val component: ObservationComponent)
data class SemanticSinkHeader(val premise: Set<Pattern>, val layer: Layer, val group: GroupKey)
data class SemanticWitnessHeader(val rule: RuleId, val methodKey: MethodKey, val statement: CommonInst,
                                 val alternative: Int, val run: Int, val edges: List<SemanticSinkHeader>,
                                 val confirmed: Boolean, val proof: ProofKey? = null)
data class SemanticWitness(val edges: List<Map<ObservationComponent, Set<ObservationCell>>>,
                           val endFacts: Set<PathFact>)
data class SemanticRunObservation(
    val processed: Map<SemanticEdgeHeader, Set<ObservationCell>>,
    val initials: Set<ObservedInitial>,
    val rawSummaries: Map<SemanticEdgeHeader, Set<ObservationCell>>,
    val publications: Map<SemanticEdgeHeader, Set<ObservationCell>>,
    val selectedDemand: Map<SemanticEdgeHeader, Set<ObservationCell>>,
    val links: Map<SemanticLinkHeader, Set<ObservationCell>>,
    val requests: Set<ObservedRequest>,
    val sourceHits: Set<ObservedSourceHit>,
    val witnesses: Map<SemanticWitnessHeader, SemanticWitness>,
    val targets: Set<ObservedTarget> = emptySet(),
    val sinkSeeds: Set<Seed> = emptySet(),
)

private fun Conclusion.observationGroup(): GroupKey {
    val layer = if (demand) Layer.DEMAND else Layer.NORMAL
    return when {
        fact.base == AccessPathBase.Zero -> GroupKey(FactsKind.REACH, layer, fact.base)
        fact.mark is MarkSlot.Star -> GroupKey(FactsKind.FLOW, layer, fact.base, exclusion,
            (fact.mark as MarkSlot.Star).excluded)
        else -> GroupKey(FactsKind.TAINT, layer, fact.base, exclusion, tail = Tail.ANY_TAINT)
    }
}
private fun Conclusion.component(): ObservationComponent = when {
    fact.base == AccessPathBase.Zero -> ObservationComponent.REACH
    fact.mark is MarkSlot.Star -> ObservationComponent.FLOW
    demand && fact.tail == Tail.EXACT -> ObservationComponent.DEMAND_EXACT
    demand && fact.tail == Tail.ANY_TAINT -> ObservationComponent.DEMAND_MUST
    demand -> ObservationComponent.DEMAND_TAINT
    fact.tail == Tail.EXACT -> ObservationComponent.NORMAL_EXACT
    else -> ObservationComponent.NORMAL_MUST
}
private fun cells(premise: Set<Pattern>, c: Conclusion, universe: BoundedDenotation): Set<ObservationCell> = when (c.component()) {
    ObservationComponent.REACH -> setOf(ObservationCell.Zero)
    ObservationComponent.FLOW -> premise.flatMap { universe.pairs(it, c) }.mapTo(HashSet()) { ObservationCell.Relation(it) }
    else -> universe.marked(Pattern(c.fact, c.exclusion)).mapTo(HashSet()) { ObservationCell.Location(it) }
}
private fun normalizeEdges(edges: Set<ObservedEdge>, universe: BoundedDenotation): Map<SemanticEdgeHeader, Set<ObservationCell>> {
    val result = LinkedHashMap<SemanticEdgeHeader, MutableSet<ObservationCell>>()
    for (edge in edges) {
        // T2/T2' can change E or mx while preserving the whole union. Both annotations constrain cells;
        // only kind/layer/base belong in this edge header. Raw DTOs still retain every annotation.
        val group = edge.conclusion.observationGroup().copy(exclusion = ExclusionSet.Empty, markExclusion = MarkExclusions.EMPTY)
        val header = SemanticEdgeHeader(edge.method, edge.premise, edge.node, group,
            edge.conclusion.component())
        result.getOrPut(header, ::LinkedHashSet).addAll(cells(edge.premise, edge.conclusion, universe))
    }
    return result
}
private fun normalizeLinks(links: Set<ObservedLink>, universe: BoundedDenotation): Map<SemanticLinkHeader, Set<ObservationCell>> {
    val result = LinkedHashMap<SemanticLinkHeader, MutableSet<ObservationCell>>()
    for (link in links) {
        val c = Conclusion(link.added.fact, link.added.exclusion, link.linkLayer == Layer.DEMAND)
        val header = SemanticLinkHeader(link.callee, link.caller, link.premise, link.callerLayer, link.call,
            c.observationGroup().copy(exclusion = ExclusionSet.Empty, markExclusion = MarkExclusions.EMPTY), c.component())
        // An added link is an initial location, not the caller-to-output FLOW relation.
        val values = if (c.fact.base == AccessPathBase.Zero) setOf(ObservationCell.Zero)
            else universe.marked(link.added).mapTo(HashSet()) { ObservationCell.Location(it) }
        result.getOrPut(header, ::LinkedHashSet).addAll(values)
    }
    return result
}
private fun sinkGroup(edge: ObservedSinkEdge): GroupKey {
    edge.group?.let { return it }
    require(edge.facts.isNotEmpty())
    val first = edge.facts.first().observationGroup()
    val must = edge.facts.firstOrNull { it.fact.tail == Tail.ANY_TAINT }
    val group = if (must == null) first else must.observationGroup()
    require(edge.facts.all {
        val own = it.observationGroup()
        own.kind == group.kind && own.layer == group.layer && own.base == group.base &&
            own.markExclusion == group.markExclusion &&
            (own.exclusion == group.exclusion || it.fact.tail == Tail.EXACT)
    }) { "One literal support retains one conclusion group" }
    return group
}
private fun normalizeWitnesses(values: Set<ObservedWitness>, universe: BoundedDenotation): Map<SemanticWitnessHeader, SemanticWitness> {
    val result = LinkedHashMap<SemanticWitnessHeader, SemanticWitness>()
    for (witness in values) {
        val headers = witness.edges.map { SemanticSinkHeader(it.premise, it.layer,
            sinkGroup(it).let { group -> group.copy(exclusion = ExclusionSet.Empty, markExclusion = MarkExclusions.EMPTY,
                // Exact members can physically share either TAINT envelope. Typed
                // fact components below retain EXACT/must/may independently.
                tail = if (group.kind == FactsKind.TAINT) Tail.ANY_TAINT else group.tail) }) }
        val header = SemanticWitnessHeader(witness.rule, witness.methodKey, witness.statement, witness.alternative,
            witness.run, headers, witness.confirmed, witness.proof)
        val edges = witness.edges.map { edge ->
            val byKind = LinkedHashMap<ObservationComponent, MutableSet<ObservationCell>>()
            for (c in edge.facts) byKind.getOrPut(c.component(), ::LinkedHashSet).addAll(cells(edge.premise, c, universe))
            byKind.mapValues { (_, v) -> v.toSet() }
        }
        val old = result[header]
        result[header] = if (old == null) SemanticWitness(edges, witness.endFacts) else
            SemanticWitness(old.edges.zip(edges) { a, b -> (a.keys + b.keys).associateWith { a[it].orEmpty() + b[it].orEmpty() } },
                old.endFacts + witness.endFacts)
    }
    return result
}

/** These are the only helpers that decode production AP leaves. The raw oracle never calls them. */
fun observedPremise(pk: PremiseKey): Set<Pattern> = pk.members.mapTo(LinkedHashSet()) { it.toPattern() }
fun observedEdges(ops: ApOps, method: MethodKey, pk: PremiseKey, facts: Facts,
                  node: CommonInst? = null): Set<ObservedEdge> = ops.leaves(facts).map {
    ObservedEdge(method, observedPremise(pk), Conclusion(it.fact, it.exclusion, facts.layer == Layer.DEMAND), node)
}.toSet()
fun observedLink(callee: MethodKey, link: Link): ObservedLink = ObservedLink(callee, link.caller.caller,
    observedPremise(link.caller.premise), link.caller.callerLayer, link.caller.call, link.linkLayer, link.addedFact)
fun observedWitness(ops: ApOps, key: VulnerabilityKey, witness: SinkWitness): ObservedWitness =
    ObservedWitness(key.rule, witness.methodKey, key.statement, witness.alternative, witness.run,
        witness.edges.map { edge -> ObservedSinkEdge(observedPremise(edge.premise), edge.layer,
            ops.leaves(edge.facts).map { Conclusion(it.fact, it.exclusion, edge.facts.layer == Layer.DEMAND) }.toSet(),
            edge.facts.groupKey) }, witness.endFacts.toSet(), witness.confirmed, witness.proof)

