/** Scalar selected transfer: no packed AP kernel, emitter, request table or static-frame reader. */
internal class SelectedReferenceAlgebra(
    private val mode: ApMode,
    private val request: (Set<Pattern>, ReferenceRequestKind) -> Unit,
    private val allows: (CommonInst, MicroEdge) -> Boolean,
    private val hit: (CommonInst, MicroEdge) -> Unit,
    private val manager: ApManager,
    private val join: (ConjunctiveEdge, Set<Pattern>, Conclusion, CommonInst, ReferenceSink) -> Unit,
) : FactAlgebra<Set<Pattern>, Conclusion> {
    private val sourcePredicates = GroupedSourcePredicates(manager, mode.run1 && mode.markMode == MarkMode.GROUP)
    private val groups = if (mode.run1 && mode.markMode == MarkMode.GROUP) GroupedScalarMarks(manager.marks) else null
    private val filters = ReferenceAlgebra(mode, manager = manager)
    override fun base(c: Conclusion) = c.fact.base
    override fun filter(c: Conclusion, filter: TypeFilter) = c.takeIf { filters.passes(filter, c) }
    override fun allowsSource(node: CommonInst, me: MicroEdge) = allows(node, me)
    override fun acceptedSource(application: AcceptedSource<Set<Pattern>, Conclusion>) = hit(application.at.node, application.edge)
    override fun conjunction(cj: ConjunctiveEdge, premise: Set<Pattern>, c: Conclusion,
                             node: CommonInst, out: ReferenceSink) = join(cj, premise, c, node, out)
    override fun sourcePredicate(source: SourceRuleOccurrence, premise: Set<Pattern>, c: Conclusion,
                                 node: CommonInst, statementEdge: Boolean, out: ReferenceSink) =
        sourcePredicates.apply(source, premise, c, node, mode, statementEdge, ::applyEdge, request, out,
            allows = { allows(node, it) }, hit = { hit(node, it) })
    override fun applyEdge(me: MicroEdge, c: Conclusion, premise: Set<Pattern>,
                           statementEdge: Boolean, out: ReferenceSink) {
        if (mode.run1 && c.fact.base == me.edge.from.base && c.fact.mark is MarkSlot.Star)
            for (id in (me.edge.to.mark as? MarkSlot.Star)?.excluded?.ids ?: intArrayOf())
                request(premise, ReferenceRequestKind.Mark(groups?.atom(TaintMark(id)) ?: TaintMark(id)))
        when (val o = groups?.apply(c, me.edge, me.may) ?: concat(c, me.edge, edgeDemand = me.may, restricted = mode.restricted, run1 = mode.run1)) {
            is EdgeOutcome.Fact -> out(premise, o.conclusion)
            is EdgeOutcome.Request -> if (mode.run1) request(premise, ReferenceRequestKind.Mark(o.mark))
            is EdgeOutcome.PositionRequest -> error("Selected statics have no Position protocol")
            EdgeOutcome.None -> Unit
        }
    }
}

/** Per-path form execution and the reference walk of a call plan. */
internal class SelectedFormsReference(
    private val ops: ApOps,
    algebra: FactAlgebra<Set<Pattern>, Conclusion>,
    private val run1AliasAdmission: Boolean = true,
) {
    val applier = FormApplier(algebra)
    private val zeroPremise = setOf(ZERO_PATTERN)

    fun conclusions(f: Facts): List<Conclusion> {
        val demand = f.layer == Layer.DEMAND
        return when (f) {
            is Reach -> listOf(Conclusion(ZERO_FACT, ExclusionSet.Empty, demand))
            else -> ops.leaves(f).map { Conclusion(it.fact, it.exclusion, demand) }.toList()
        }
    }

    enum class Mode { STATEMENT, STAGE, GEN }
    fun apply(mode: Mode, s: StatementSummary, premise: Set<Pattern>, c: Conclusion, at: Place): List<Conclusion> = buildList {
        when (mode) {
            Mode.STATEMENT -> applier.statement(s, premise, c, at, { _, x -> add(x) })
            Mode.STAGE -> applier.stage(s, premise, c, at) { _, x, _ -> add(x) }
            Mode.GEN -> applier.gen(s.edges, premise, c) { _, x -> add(x) }
        }
    }

    /** Compare complete leaf identities before store merging or subsumption. */
    fun agrees(mode: Mode, s: StatementSummary, at: Place, premise: Set<Pattern>, input: Facts, core: List<Facts>): Boolean {
        val ref = conclusions(input).flatMap { apply(mode, s, premise, it, at) }.toSet()
        val got = core.flatMap(::conclusions).toSet()
        return got == ref
    }

    /** Keep pending record exclusions until exit demotion, then apply the call cut. */
    fun run(plan: CallPlan, inputs: List<PlanItem>, at: Place, hooks: PlanHooks = PlanHooks(),
            from: CallPoint = plan.entry, pendingDemotion: Boolean = false): List<Pair<CallPoint, PlanItem>> {
        check(!pendingDemotion || (from == CallPoint.RETURNED && plan.exit == CallPoint.AFTER))
        fun finish(i: PlanItem): PlanItem {
            val result = if (!pendingDemotion) i else {
                check(i.c.fact.mark is MarkSlot.Concrete && i.c.fact.tail != Tail.STAR)
                i.copy(c = i.c.copy(demand = true), identityCandidate = if (run1AliasAdmission) i.identityCandidate else false)
            }
            return hooks.exit(result)
        }
        fun statement(s: StatementSummary, x: PlanItem): List<PlanItem> = buildList {
            applier.statement(s, x.premise, x.c, at.copy(statementEdge = true, sources = false),
                sink = { pr, y -> add(hooks.statementCut(PlanItem(pr, y, x.identityCandidate))) },
                untouched = { pr, y -> add(PlanItem(pr, y, x.identityCandidate)) })
        }
        fun cleanSteps(steps: List<CleanStep>, inputs: List<PlanItem>): List<PlanItem> =
            steps.fold(inputs) { fs, step -> fs.flatMap { x -> when (step) {
                is CleanStep.Clean -> hooks.clean(step.cleaner, x)
                is CleanStep.Kill -> buildList { applier.statement(step.keepEdges, x.premise, x.c,
                    at.copy(statementEdge = true, sources = false), { pr, y -> add(PlanItem(pr, y, x.identityCandidate)) }) }
                is CleanStep.Field -> statement(step.read, x).flatMap { hooks.clean(step.cleaner, it) }
                    .flatMap { statement(step.write, it) }.filter { it.c.fact.base != step.temporary }
            } } }
        val seen = LinkedHashSet<Pair<CallPoint, PlanItem>>()
        val work = ArrayDeque<Pair<CallPoint, List<PlanItem>>>()
        val start = ArrayList<PlanItem>()
        for (input in inputs) {
            val i = if (pendingDemotion && !run1AliasAdmission) input.copy(identityCandidate = false) else input
            when {
                from != plan.entry -> start += i
                i.c.fact.base == AccessPathBase.Zero -> { if (plan.zeroCanReturn) seen += plan.exit to finish(i); start += i }
                i.c.fact.base !in plan.touched -> seen += plan.exit to finish(i)
                else -> start += i
            }
        }
        if (start.isNotEmpty()) work.addLast(from to start)
        while (work.isNotEmpty()) {
            val (p, batch) = work.removeFirst()
            val items = batch.filter { seen.add(p to it) }
            if (items.isEmpty() || p == plan.exit) continue
            val fired = if (hooks.guards && p == CallPoint.BOUND) hooks.atBound(items) else emptyList()
            for (st in plan.stagesFrom[p].orEmpty()) {
                val out = ArrayList<PlanItem>()
                when (st) {
                    is CallStage.Edges -> {
                        if (st.kind == StageKind.END_FACTS) continue
                        val place = at.copy(statementEdge = st.kind.statementEdges, sources = st.kind == StageKind.SOURCES)
                        val guard = if (hooks.guards) st.guard else null
                        when {
                            guard is Guard.SinkTriggered ->
                                for ((sink, layer) in fired) if (sink.joinKey == guard.sink.joinKey) {
                                    val zero = Conclusion(ZERO_FACT, ExclusionSet.Empty, demand = layer == Layer.DEMAND)
                                    applier.stage(st.summary, zeroPremise, zero, place) { pr, x, me ->
                                        out += PlanItem(pr, x, st.kind.identityCandidateOf(me, null)) }
                                }
                            else -> {
                                for (i in items) {
                                    if (guard == Guard.MemoryEffect && !Guard.MemoryEffect.admits(run1AliasAdmission, i.identityCandidate,
                                        if (i.c.demand) Layer.DEMAND else Layer.NORMAL)) continue
                                    applier.stage(st.summary, i.premise, i.c, place) { pr, x, me ->
                                        out += PlanItem(pr, x, st.kind.identityCandidateOf(me, i.identityCandidate)) }
                                }
                                val sink = st.trigger
                                if (sink != null && out.isNotEmpty()) out += hooks.trigger(sink)
                            }
                        }
                    }
                    is CallStage.Actions -> out += cleanSteps(st.steps, items)
                    is CallStage.Predefined -> for (i in items) {
                        applier.stage(st.summary, i.premise, i.c, at.copy(statementEdge = false, sources = false)) { pr, x, _ ->
                            out += PlanItem(pr, x, true)
                        }
                    }
                    is CallStage.Callees -> for (i in items) out += hooks.callees(st, i)
                }
                val next = if (st.to == plan.exit) out.map(::finish) else out
                if (next.isNotEmpty()) work.addLast(st.to to next)
            }
        }
        return seen.toList()
    }
}

package org.opentaint.dataflow.bidi.fixtures

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.interp.*
import org.opentaint.ir.api.common.CommonMethod

/** Deliberately flat finite-spec model. No production static profile or request store is read. */
internal class SelectedScalarPlan(private val program: FiniteProgramFixtures) {
    data class Needs(
        val fields: MutableSet<List<Int>> = linkedSetOf(),
        val marked: MutableMap<List<Int>, MutableSet<TaintMark>> = linkedMapOf(),
        val classes: MutableSet<Int> = linkedSetOf(),
        var allPoints: Boolean = false,
        var writes: Boolean = false,
    ) {
        fun merge(other: Needs): Boolean {
            var change = fields.addAll(other.fields) or classes.addAll(other.classes)
            if (other.allPoints && !allPoints) { allPoints = true; change = true }
            if (other.writes && !writes) { writes = true; change = true }
            for ((path, marks) in other.marked)
                change = marked.getOrPut(path) { linkedSetOf() }.addAll(marks) || change
            return change
        }
    }
    private val values = program.methods.associate { it.method to Needs() }
    private val calls = program.methods.associate { it.method to linkedSetOf<CommonMethod>() }
    private val universe = linkedSetOf<List<Int>>().apply { addAll(program.declaredStaticFieldPaths) }
    private val classes = linkedSetOf<Int>().apply { addAll(program.declaredStaticClassIds) }

    init {
        for (row in program.statementInputs) summary(values.getValue(row.key.method), row.summary)
        for (row in program.entryInputs) rules(values.getValue(row.key.method), row.rules)
        for (row in program.exitInputs) rules(values.getValue(row.key.method), row.rules.rules)
        for (row in program.callInputs) {
            val n = values.getValue(row.key.method)
            row.plan.sinks.forEach { sink(n, it) }
            for (stage in row.plan.stages) when (stage) {
                is CallStage.Edges -> summary(n, stage.summary, reads = stage.kind != StageKind.ALIASES,
                    selfRead = stage.kind == StageKind.UNRESOLVED)
                is CallStage.Actions -> for (step in stage.steps) when (step) {
                    is CleanStep.Clean -> cleaner(n, step.cleaner)
                    is CleanStep.Kill -> summary(n, step.keepEdges, reads = false)
                    is CleanStep.Field -> {
                        summary(n, step.read, reads = false)
                        cleaner(n, step.cleaner)
                        summary(n, step.write, reads = false)
                    }
                }
                is CallStage.Predefined -> error("Predefined models are outside this historical profile")
                is CallStage.Callees -> for (callee in stage.callees) {
                    if (callee.method in values) calls.getValue(row.key.method) += callee.method
                    else n.writes = true
                }
            }
        }
        // The finite graph is closed by a plain whole-program least fixed point, not SCC plans.
        do {
            var changed = false
            for ((method, targets) in calls) for (callee in targets)
                changed = values.getValue(method).merge(values.getValue(callee)) || changed
        } while (changed)
    }

    private fun coordinate(n: Needs, f: PathFact, root: Boolean = true) {
        if (f.base != STATIC) return
        val path = f.path.take(2)
        when (path.size) {
            0 -> if (root) n.allPoints = true
            1 -> { classes += path[0]; n.classes += path[0] }
            else -> { classes += path[0]; universe += path }
        }
    }
    private fun literal(n: Needs, p: Pattern) {
        if (p.fact.base != STATIC) return
        coordinate(n, p.fact)
        val mark = (p.fact.mark as? MarkSlot.Concrete)?.mark ?: return
        // An exact class/root condition has no field cylinder.
        if (p.fact.path.size < 2 && p.fact.tail == Tail.EXACT) return
        n.marked.getOrPut(p.fact.path.take(2)) { linkedSetOf() } += mark
    }
    private fun summary(n: Needs, s: StatementSummary, reads: Boolean = true, selfRead: Boolean = false) {
        for (micro in s.edges) {
            val e = micro.edge
            val identity = e.from == e.to && e.from.mark is MarkSlot.Star
            if (!identity) { coordinate(n, e.from); coordinate(n, e.to) }
            if (reads && e.from.base == STATIC && e.from.path.size >= 2 && e.from.mark is MarkSlot.Star &&
                (!identity || (selfRead && e.exclusion == ExclusionSet.Empty))) {
                n.fields += e.from.path.take(2)
                coordinate(n, e.from)
            }
            if (e.from.mark is MarkSlot.Concrete) literal(n, Pattern(e.from, ExclusionSet.Empty))
            if (e.from.base == STATIC) for (id in (e.to.mark as? MarkSlot.Star)?.excluded?.ids ?: intArrayOf())
                literal(n, Pattern(e.from.copy(mark = MarkSlot.Concrete(TaintMark(id))), ExclusionSet.Empty))
            if (e.to.base == STATIC && (e.from != e.to || e.exclusion != ExclusionSet.Empty ||
                    e.fromExclusion != ExclusionSet.Empty || e.toExclusion != ExclusionSet.Empty)) n.writes = true
            // A strong keep can have no value edge. The finest exclusion names its destination.
            val excluded = (e.exclusion as? ExclusionSet.Concrete)?.ids ?: intArrayOf()
            if (e.from.base == STATIC) for (a in excluded) {
                val target = e.from.path + a
                if (s.edges.none { it !== micro && it.edge.from.base == STATIC &&
                        it.edge.from.path.startsWith(target) && it.edge.exclusion != ExclusionSet.Empty })
                    coordinate(n, e.from.copy(path = target))
            }
        }
        if (STATIC in s.touched && s.edges.none { it.edge.from.base == STATIC }) {
            n.writes = true; n.allPoints = true
        }
        for (source in s.sources) {
            source.predicate.leaves.forEach { literal(n, it) }
            for (action in source.actions) { coordinate(n, action.target); if (action.target.base == STATIC) n.writes = true }
        }
        for (cj in s.conjunctions) {
            cj.literals.forEach { literal(n, it) }; coordinate(n, cj.target)
            if (cj.target.base == STATIC) n.writes = true
        }
    }
    private fun sink(n: Needs, s: SinkRule) {
        (s.predicate?.leaves ?: s.patterns).forEach { literal(n, it) }
        s.endFacts.forEach { summary(n, StatementSummary(setOf(it.edge.from.base), listOf(it), emptyList(), emptyMap())) }
    }
    private fun rules(n: Needs, r: RuleStatement) {
        summary(n, r.summary); summary(n, r.endFacts); r.sinks.forEach { sink(n, it) }
    }
    private fun cleaner(n: Needs, c: Cleaner) {
        if (c.base != STATIC) return
        n.writes = true
        val path = c.path?.toList().orEmpty()
        coordinate(n, PathFact(STATIC, path, Tail.STAR, MarkSlot.STAR))
        c.mark?.let { mark ->
            literal(n, Pattern(PathFact(STATIC, path,
                if (path.size == 1 && c.reach == CleanReach.EXACT) Tail.EXACT else Tail.STAR,
                MarkSlot.Concrete(mark)), ExclusionSet.Empty))
        }
    }
    private fun needs(method: MethodKey) = values.getValue(method.method)
    fun fieldReads(method: MethodKey): Set<List<Int>> = needs(method).fields
    fun writes(method: MethodKey): Boolean = needs(method).writes
    fun points(method: MethodKey): Set<Int> = needs(method).let { if (it.allPoints) classes else it.classes }
    fun wide(method: MethodKey, field: List<Int>): Set<TaintMark> = needs(method).marked.entries
        .filter { (scope, _) -> scope.size < 2 && field.startsWith(scope) }.flatMapTo(linkedSetOf()) { it.value }
    fun base(method: MethodKey): Map<Pattern, Set<TaintMark>> = needs(method).let { n ->
        val slots = n.fields + n.marked.keys.filter { it.size == 2 }
        slots.associate { path -> slot(STATIC, path) to n.marked.entries
            .filter { (scope, _) -> path.startsWith(scope) }.flatMapTo(linkedSetOf()) { it.value } }
    }
    fun suppliedFields(input: Pattern): Set<List<Int>> = universe.filterTo(linkedSetOf()) { path ->
        geometry(slot(STATIC, path), input)
    }
    companion object {
        fun slot(base: org.opentaint.dataflow.ap.ifds.AccessPathBase, path: List<Int> = emptyList()) =
            Pattern(PathFact(base, path, Tail.STAR, MarkSlot.STAR), ExclusionSet.Empty)
        /** Request geometry intentionally ignores E/mx, but rejects exact proper ancestors. */
        fun geometry(slot: Pattern, input: Pattern): Boolean = slot.fact.base == input.fact.base &&
            (input.fact.path.startsWith(slot.fact.path) ||
                (slot.fact.path.startsWith(input.fact.path) && input.fact.tail != Tail.EXACT))
    }
}

